--
-- Name: apply_supplier_invoice_matching(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_supplier_invoice_matching(p_invoice_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_invoice public.supplier_invoices%ROWTYPE;
  v_allocation_count integer;
  v_invalid_count integer;
  v_expected numeric(15,2);
  v_allocated numeric(15,2);
  v_difference numeric(15,2);
  v_status text;
  v_reason text;
  v_notes text;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT invoice.*
  INTO v_invoice
  FROM public.supplier_invoices AS invoice
  WHERE invoice.id = p_invoice_id
    AND invoice.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_invoice.invoice_kind = 'service' THEN
    IF EXISTS (
      SELECT 1
      FROM public.supplier_invoice_receipt_allocations AS allocation
      WHERE allocation.tenant_id = v_tenant
        AND allocation.supplier_invoice_id = p_invoice_id
    ) THEN
      RAISE EXCEPTION 'service_invoice_receipts_forbidden'
        USING ERRCODE = '23514';
    END IF;
    v_status := CASE
      WHEN v_invoice.service_verified_at IS NULL THEN 'pending'
      ELSE 'matched'
    END;
    v_reason := CASE
      WHEN v_invoice.service_verified_at IS NULL
        THEN 'service_verification_required'
      ELSE 'service_verified'
    END;
    v_notes := CASE
      WHEN v_invoice.service_verified_at IS NULL
        THEN 'Hóa đơn dịch vụ chờ xác minh chứng từ.'
      ELSE 'Hóa đơn dịch vụ đã được xác minh chứng từ.'
    END;
    v_expected := v_invoice.subtotal;
    v_allocated := NULL;
    v_difference := NULL;
  ELSE
    SELECT
      count(*),
      count(*) FILTER (
        WHERE grn.id IS NULL
           OR grn.status <> 'confirmed'
           OR purchase_order.id IS NULL
           OR purchase_order.supplier_id IS DISTINCT FROM
             v_invoice.supplier_id
           OR po_item.id IS NULL
           OR grn_item.id IS NULL
           OR invoice_line.id IS NULL
           OR invoice_line.ingredient_id IS DISTINCT FROM
             po_item.ingredient_id
           OR invoice_line.unit_id IS DISTINCT FROM grn_item.entry_unit_id
      )
    INTO v_allocation_count, v_invalid_count
    FROM public.supplier_invoice_receipt_allocations AS allocation
    LEFT JOIN public.goods_received_notes AS grn
      ON grn.id = allocation.grn_id
     AND grn.tenant_id = allocation.tenant_id
    LEFT JOIN public.purchase_orders AS purchase_order
      ON purchase_order.id = allocation.po_id
     AND purchase_order.tenant_id = allocation.tenant_id
     AND purchase_order.id = grn.po_id
    LEFT JOIN public.purchase_order_items AS po_item
      ON po_item.id = allocation.purchase_order_item_id
     AND po_item.tenant_id = allocation.tenant_id
     AND po_item.po_id = purchase_order.id
    LEFT JOIN public.grn_items AS grn_item
      ON grn_item.grn_id = allocation.grn_id
     AND grn_item.tenant_id = allocation.tenant_id
     AND grn_item.purchase_order_item_id = po_item.id
    LEFT JOIN public.supplier_invoice_lines AS invoice_line
      ON invoice_line.id = allocation.invoice_line_id
     AND invoice_line.tenant_id = allocation.tenant_id
     AND invoice_line.supplier_invoice_id = p_invoice_id
    WHERE allocation.tenant_id = v_tenant
      AND allocation.supplier_invoice_id = p_invoice_id;

    v_expected := v_invoice.subtotal;
    SELECT coalesce(
      pg_catalog.sum(
        invoice_line.line_total
          * allocation.billed_quantity
          / invoice_line.quantity
      ),
      0
    )::numeric(15,2)
    INTO v_allocated
    FROM public.supplier_invoice_receipt_allocations AS allocation
    JOIN public.supplier_invoice_lines AS invoice_line
      ON invoice_line.id = allocation.invoice_line_id
     AND invoice_line.tenant_id = allocation.tenant_id
     AND invoice_line.supplier_invoice_id = p_invoice_id
    WHERE allocation.tenant_id = v_tenant
      AND allocation.supplier_invoice_id = p_invoice_id;

    v_difference := (v_expected - v_allocated)::numeric(15,2);
    IF v_allocation_count = 0 THEN
      v_status := 'pending';
      v_reason := 'goods_receipts_required';
      v_notes := 'Hóa đơn hàng hóa chưa phân bổ tới dòng phiếu nhập.';
    ELSIF v_invalid_count > 0 THEN
      v_status := 'discrepancy';
      v_reason := 'receipt_line_mismatch';
      v_notes := 'Có dòng phân bổ không khớp NCC, PO, GRN hoặc nguyên liệu.';
    ELSIF pg_catalog.abs(v_difference) <= 1 THEN
      v_status := 'matched';
      v_reason := 'goods_quantity_value_within_one_vnd';
      v_notes := 'Số lượng phân bổ và tổng dòng hóa đơn khớp trong 1đ.';
    ELSE
      v_status := 'discrepancy';
      v_reason := 'goods_quantity_value_difference';
      v_notes := 'Chênh lệch giá trị phân bổ: ' || v_difference::text;
    END IF;
  END IF;

  UPDATE public.supplier_invoices
  SET matching_status = v_status,
      matching_expected_amount = v_expected,
      matching_received_amount = v_allocated,
      matching_difference_amount = v_difference,
      matching_reason_code = v_reason,
      matching_notes = v_notes,
      updated_at = pg_catalog.now()
  WHERE id = p_invoice_id
    AND tenant_id = v_tenant;

  RETURN pg_catalog.jsonb_build_object(
    'invoice_id', p_invoice_id,
    'matching_status', v_status,
    'reason', v_reason,
    'expected_amount', v_expected,
    'received_amount', v_allocated,
    'difference_amount', v_difference
  );
END;
$$;


--
-- Name: assert_expense_transfer_content(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_expense_transfer_content(p_expense_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_expense public.expenses%ROWTYPE;
  v_match_count integer;
  v_event_id bigint;
  v_event public.webhook_events%ROWTYPE;
BEGIN
  SELECT *
  INTO v_expense
  FROM public.expenses expense
  WHERE expense.id = p_expense_id;

  IF NOT FOUND OR v_expense.transfer_content IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*)::integer, min(match.webhook_event_id)
  INTO v_match_count, v_event_id
  FROM public.bank_transaction_expense_matches match
  WHERE match.tenant_id = v_expense.tenant_id
    AND match.expense_id = v_expense.id;

  IF v_expense.payment_method = 'unpaid'
    AND v_expense.paid_at IS NULL
    AND v_match_count = 0
  THEN
    RETURN;
  END IF;

  IF v_expense.payment_method = 'transfer'
    AND v_expense.paid_at IS NOT NULL
    AND v_match_count = 1
  THEN
    SELECT *
    INTO v_event
    FROM public.webhook_events event
    WHERE event.tenant_id = v_expense.tenant_id
      AND event.id = v_event_id;

    IF FOUND
      AND v_event.provider = 'sepay'
      AND v_event.signature_valid IS TRUE
      AND v_event.processing_status IS DISTINCT FROM 'failed'
      AND v_event.payment_id IS NULL
      AND v_event.expense_id IS NOT DISTINCT FROM v_expense.id
      AND lower(COALESCE(v_event.payload->>'transferType', '')) = 'out'
      AND COALESCE(v_event.payload->>'transferAmount', '')
        ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND abs((v_event.payload->>'transferAmount')::numeric) = v_expense.amount
      AND v_expense.paid_at IS NOT DISTINCT FROM v_event.created_at
      AND private.sepay_payload_contains_transfer_content(
        v_event.payload,
        v_expense.transfer_content
      )
    THEN
      RETURN;
    END IF;
  END IF;

  RAISE EXCEPTION 'expense_transfer_intent_evidence_invalid'
    USING ERRCODE = '23514';
END;
$_$;


--
-- Name: assert_inventory_site_warehouse(bigint, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_inventory_site_warehouse(p_tenant_id bigint, p_branch_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_branch_kind text;
  v_warehouse_count integer;
  v_defaults_valid boolean;
BEGIN
  SELECT branch.branch_kind
  INTO v_branch_kind
  FROM public.branches AS branch
  WHERE branch.id = p_branch_id
    AND branch.tenant_id = p_tenant_id
    AND branch.is_active IS TRUE;

  IF NOT FOUND
     OR v_branch_kind NOT IN ('branch', 'central_supply', 'central_kitchen') THEN
    RETURN;
  END IF;

  SELECT
    count(*)::integer,
    bool_and(
      location.is_default_receive
      AND location.is_default_issue
      AND location.is_default_consumption
    )
  INTO v_warehouse_count, v_defaults_valid
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = p_tenant_id
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE;

  IF v_warehouse_count <> 1 THEN
    RAISE EXCEPTION 'inventory_site_requires_exactly_one_warehouse:%',
      p_branch_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_defaults_valid IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'inventory_site_warehouse_must_own_all_defaults:%',
      p_branch_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_branch_kind = 'branch'
     AND EXISTS (
       SELECT 1
       FROM public.inventory_locations AS location
       WHERE location.tenant_id = p_tenant_id
         AND location.branch_id = p_branch_id
         AND location.is_active IS TRUE
         AND location.location_kind <> 'warehouse'
     ) THEN
    RAISE EXCEPTION 'branch_site_allows_only_active_warehouse:%',
      p_branch_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_branch_kind <> 'central_kitchen'
     AND EXISTS (
       SELECT 1
       FROM public.inventory_locations AS location
       WHERE location.tenant_id = p_tenant_id
         AND location.branch_id = p_branch_id
         AND location.is_active IS TRUE
         AND location.location_kind = 'production_storage'
     ) THEN
    RAISE EXCEPTION
      'production_storage_requires_central_kitchen:%',
      p_branch_id
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$;


--
-- Name: assert_stock_transfer_warehouse_endpoints(bigint, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_stock_transfer_warehouse_endpoints(p_transfer_id bigint, p_tenant_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_transfer public.stock_transfers%ROWTYPE;
BEGIN
  SELECT transfer.*
  INTO v_transfer
  FROM public.stock_transfers AS transfer
  WHERE transfer.id = p_transfer_id
    AND transfer.tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  PERFORM branch.id
  FROM public.branches AS branch
  WHERE branch.id = ANY(ARRAY[
    v_transfer.from_branch_id,
    v_transfer.to_branch_id
  ]::bigint[])
  ORDER BY branch.id
  FOR UPDATE OF branch;

  PERFORM location.id
  FROM public.inventory_locations AS location
  WHERE location.id = ANY(ARRAY[
    v_transfer.from_location_id,
    v_transfer.to_location_id
  ]::bigint[])
  ORDER BY location.id
  FOR UPDATE;

  IF v_transfer.from_branch_id = v_transfer.to_branch_id THEN
    RAISE EXCEPTION 'transfer_warehouse_location_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
       SELECT 1
       FROM public.branches AS source_branch
       WHERE source_branch.id = v_transfer.from_branch_id
         AND source_branch.tenant_id = p_tenant_id
         AND source_branch.is_active IS TRUE
         AND source_branch.branch_kind IN (
           'branch',
           'central_supply',
           'central_kitchen'
         )
     )
     OR NOT EXISTS (
       SELECT 1
       FROM public.branches AS target_branch
       WHERE target_branch.id = v_transfer.to_branch_id
         AND target_branch.tenant_id = p_tenant_id
         AND target_branch.is_active IS TRUE
         AND target_branch.branch_kind IN (
           'branch',
           'central_supply',
           'central_kitchen'
         )
     ) THEN
    RAISE EXCEPTION 'transfer_branch_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
       SELECT 1
       FROM public.inventory_locations AS source_location
       WHERE source_location.id = v_transfer.from_location_id
         AND source_location.tenant_id = p_tenant_id
         AND source_location.branch_id = v_transfer.from_branch_id
         AND source_location.location_kind = 'warehouse'
         AND source_location.is_active IS TRUE
     )
     OR NOT EXISTS (
       SELECT 1
       FROM public.inventory_locations AS target_location
       WHERE target_location.id = v_transfer.to_location_id
         AND target_location.tenant_id = p_tenant_id
         AND target_location.branch_id = v_transfer.to_branch_id
         AND target_location.location_kind = 'warehouse'
         AND target_location.is_active IS TRUE
     ) THEN
    RAISE EXCEPTION 'transfer_warehouse_location_invalid'
      USING ERRCODE = '23514';
  END IF;
END;
$$;


--
-- Name: assign_invoice_allocation_grn_item(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assign_invoice_allocation_grn_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.grn_item_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT item.id
  INTO NEW.grn_item_id
  FROM public.grn_items AS item
  WHERE item.tenant_id = NEW.tenant_id
    AND item.grn_id = NEW.grn_id
    AND item.purchase_order_item_id IS NOT DISTINCT FROM
      NEW.purchase_order_item_id
  ORDER BY item.id
  LIMIT 1;

  IF NEW.grn_item_id IS NULL THEN
    RAISE EXCEPTION 'supplier_invoice_allocation_grn_item_missing'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: assign_stock_movement_grn_item(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assign_stock_movement_grn_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.type <> 'grn_receipt'
     OR NEW.grn_id IS NULL
     OR NEW.grn_item_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT item.id
  INTO NEW.grn_item_id
  FROM public.grn_items AS item
  WHERE item.tenant_id = NEW.tenant_id
    AND item.grn_id = NEW.grn_id
    AND item.ingredient_id = NEW.ingredient_id
    AND item.received_quantity - item.rejected_quantity > 0
    AND NOT EXISTS (
      SELECT 1
      FROM public.stock_movements AS movement
      WHERE movement.tenant_id = item.tenant_id
        AND movement.grn_item_id = item.id
    )
  ORDER BY item.id
  LIMIT 1;

  IF NEW.grn_item_id IS NULL THEN
    RAISE EXCEPTION 'grn_receipt_lineage_missing'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: attach_invoice_buyer_qr_document_to_print_job(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.attach_invoice_buyer_qr_document_to_print_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_blocks jsonb;
  v_footer_blocks jsonb;
BEGIN
  IF NEW.job_type <> 'receipt'
    OR COALESCE(jsonb_typeof(NEW.payload #> '{document,blocks}'), '') <> 'array'
  THEN
    RETURN NEW;
  END IF;

  SELECT
    COALESCE(
      jsonb_agg(entry.block ORDER BY entry.ordinal)
        FILTER (WHERE entry.block->>'type' = 'footer'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(entry.block ORDER BY entry.ordinal)
        FILTER (
          WHERE entry.block->>'type' IS DISTINCT FROM 'paymentQr'
            AND entry.block->>'type' IS DISTINCT FROM 'invoiceQr'
            AND entry.block->>'type' IS DISTINCT FROM 'footer'
        ),
      '[]'::jsonb
    )
  INTO v_footer_blocks, v_blocks
  FROM jsonb_array_elements(NEW.payload #> '{document,blocks}')
    WITH ORDINALITY AS entry(block, ordinal);

  IF COALESCE(NEW.payload #>> '{invoice_qr,content}', '') <> ''
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_blocks) block
      WHERE block->>'type' = 'invoiceQr'
    )
  THEN
    v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
      'type', 'invoiceQr',
      'heading', 'QUÉT QR XUẤT HĐĐT',
      'qr', NEW.payload->'invoice_qr'
    ));
  END IF;

  v_blocks := v_blocks || v_footer_blocks;

  NEW.payload := jsonb_set(
    NEW.payload,
    '{document,blocks}',
    v_blocks
  );
  RETURN NEW;
END;
$$;


--
-- Name: attach_invoice_buyer_qr_to_print_job(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.attach_invoice_buyer_qr_to_print_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_path text;
  v_raw_token text;
  v_token_hash text;
  v_stored_token_hash text;
  v_paid_at timestamptz;
  v_expires_at timestamptz;
  v_request_status text;
BEGIN
  IF NEW.job_type <> 'receipt' OR NEW.order_id IS NULL OR NEW.payload IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.payload := NEW.payload - 'payment_qr' - 'invoice_qr';

  SELECT payment.paid_at
  INTO v_paid_at
  FROM public.tax_invoice_issue_jobs job
  JOIN public.payments payment
    ON payment.id = job.payment_id
   AND payment.tenant_id = job.tenant_id
   AND payment.branch_id = job.branch_id
   AND payment.order_id = job.order_id
  JOIN public.tax_invoices invoice
    ON invoice.id = job.tax_invoice_id
   AND invoice.tenant_id = job.tenant_id
   AND invoice.order_id = job.order_id
  WHERE job.tenant_id = NEW.tenant_id
    AND job.branch_id = NEW.branch_id
    AND job.order_id = NEW.order_id
    AND job.tax_invoice_id IS NOT NULL
    AND job.status = 'queued'
    AND invoice.status = 'draft'
    AND invoice.invoice_number IS NULL
    AND payment.tenant_id = NEW.tenant_id
    AND payment.branch_id = NEW.branch_id
    AND payment.order_id = NEW.order_id
    AND payment.status = 'completed'
    AND payment.paid_at IS NOT NULL
  LIMIT 1;
  IF v_paid_at IS NULL THEN
    RETURN NEW;
  END IF;
  v_expires_at := v_paid_at + interval '2 hours';

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'invoice-buyer:' || NEW.tenant_id::text || ':' || NEW.order_id::text,
      0
    )
  );

  IF TG_OP = 'UPDATE' THEN
    v_path := OLD.payload #>> '{invoice_qr,content}';
  END IF;
  v_path := COALESCE(v_path, NEW.payload #>> '{invoice_qr,content}');

  IF v_path IS NULL THEN
    SELECT job.payload #>> '{invoice_qr,content}'
    INTO v_path
    FROM public.print_jobs job
    WHERE job.tenant_id = NEW.tenant_id
      AND job.order_id = NEW.order_id
      AND job.job_type = 'receipt'
      AND COALESCE(job.payload #>> '{invoice_qr,content}', '') <> ''
    ORDER BY job.created_at
    LIMIT 1;
  END IF;

  v_raw_token := substring(
    COALESCE(v_path, '')
    FROM '^/q/invoice/([a-f0-9]{48})$'
  );
  IF v_raw_token IS NULL THEN
    v_raw_token := encode(extensions.gen_random_bytes(24), 'hex');
    v_path := '/q/invoice/' || v_raw_token;
  END IF;
  v_token_hash := encode(
    extensions.digest(convert_to(v_raw_token, 'UTF8'), 'sha256'),
    'hex'
  );

  INSERT INTO public.tax_invoice_buyer_requests (
    tenant_id,
    branch_id,
    order_id,
    token_hash,
    expires_at
  ) VALUES (
    NEW.tenant_id,
    NEW.branch_id,
    NEW.order_id,
    v_token_hash,
    v_expires_at
  )
  ON CONFLICT (tenant_id, order_id) DO NOTHING;

  SELECT request.token_hash, request.expires_at, request.status
  INTO v_stored_token_hash, v_expires_at, v_request_status
  FROM public.tax_invoice_buyer_requests request
  WHERE request.tenant_id = NEW.tenant_id
    AND request.order_id = NEW.order_id;

  IF v_stored_token_hash IS DISTINCT FROM v_token_hash
    OR v_request_status <> 'open'
    OR v_expires_at <= now() THEN
    RETURN NEW;
  END IF;

  NEW.payload := jsonb_set(
    NEW.payload,
    '{invoice_qr}',
    jsonb_build_object(
      'type', 'invoice',
      'content', v_path,
      'header_label', 'NHẬN HĐĐT'
    ),
    true
  );
  RETURN NEW;
END;
$_$;


--
-- Name: authorize_leave_review(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.authorize_leave_review(p_request_id bigint) RETURNS public.leave_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.leave_requests%ROWTYPE;
  v_actor uuid := auth.uid();
  v_role text := public.auth_role();
  v_actor_branch_id bigint;
  v_branch_kind text;
BEGIN
  SELECT * INTO v_request
  FROM public.leave_requests request
  WHERE request.id = p_request_id
    AND request.tenant_id = public.auth_tenant_id()
  FOR UPDATE;
  IF v_request.id IS NULL OR v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'leave_request_not_pending' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.employees employee
    WHERE employee.id = v_request.employee_id AND employee.profile_id = v_actor
  ) THEN
    RAISE EXCEPTION 'cannot_review_own_leave' USING ERRCODE = '42501';
  END IF;

  SELECT profile.branch_id INTO v_actor_branch_id
  FROM public.profiles profile WHERE profile.id = v_actor;
  SELECT branch.branch_kind INTO v_branch_kind
  FROM public.branches branch
  WHERE branch.id = v_request.branch_id
    AND branch.tenant_id = v_request.tenant_id;

  IF v_request.branch_id IS NULL OR v_branch_kind IN ('central_supply', 'central_kitchen') THEN
    IF v_role <> 'owner' OR NOT public.auth_is_owner(v_actor) THEN
      RAISE EXCEPTION 'leave_review_requires_owner' USING ERRCODE = '42501';
    END IF;
  ELSIF v_role <> 'owner'
    AND (v_role <> 'branch_manager'
      OR v_actor_branch_id IS DISTINCT FROM v_request.branch_id
      OR NOT public.has_permission(v_request.branch_id, 'hr:approve_leave_request')) THEN
    RAISE EXCEPTION 'leave_review_wrong_branch' USING ERRCODE = '42501';
  END IF;
  RETURN v_request;
END;
$$;


--
-- Name: bootstrap_inventory_valuation_from_invoices(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.bootstrap_inventory_valuation_from_invoices(p_tenant_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_cutover public.inventory_valuation_cutovers%ROWTYPE;
  v_movement record;
  v_invoice record;
  v_origin public.inventory_cost_origins%ROWTYPE;
  v_account public.inventory_valuation_accounts%ROWTYPE;
  v_grn_item_id bigint;
  v_balance_id bigint;
  v_event_id bigint;
  v_quantity numeric(20,3);
  v_cutoff_at timestamptz;
  v_opening_quantity numeric(20,3) := 0;
  v_opening_value numeric(20,2) := 0;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'inventory-valuation-bootstrap:' || p_tenant_id::text,
      0
    )
  );

  SELECT cutover.*
  INTO v_cutover
  FROM public.inventory_valuation_cutovers AS cutover
  WHERE cutover.tenant_id = p_tenant_id
  FOR UPDATE;

  IF FOUND AND v_cutover.status = 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'status', 'active',
      'opening_quantity', v_cutover.opening_quantity,
      'opening_value', v_cutover.opening_value,
      'replayed', TRUE
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.inventory_valuation_accounts AS account
    WHERE account.tenant_id = p_tenant_id
  ) OR EXISTS (
    SELECT 1
    FROM public.inventory_cost_origins AS origin
    WHERE origin.tenant_id = p_tenant_id
  ) OR EXISTS (
    SELECT 1
    FROM public.inventory_valuation_events AS event
    WHERE event.tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'inventory_valuation_ledger_not_pristine'
      USING ERRCODE = '23514';
  END IF;

  WITH candidates AS (
    SELECT
      movement.id AS movement_id,
      pg_catalog.min(item.id) AS grn_item_id,
      pg_catalog.count(*) AS item_count
    FROM public.stock_movements AS movement
    JOIN public.grn_items AS item
      ON item.tenant_id = movement.tenant_id
     AND item.grn_id = movement.grn_id
     AND item.ingredient_id = movement.ingredient_id
    WHERE movement.tenant_id = p_tenant_id
      AND movement.type IN ('grn_receipt', 'grn_amend')
      AND movement.grn_item_id IS NULL
    GROUP BY movement.id
  )
  UPDATE public.stock_movements AS movement
  SET grn_item_id = candidate.grn_item_id
  FROM candidates AS candidate
  WHERE movement.id = candidate.movement_id
    AND candidate.item_count = 1;

  IF EXISTS (
    SELECT 1
    FROM public.stock_movements AS movement
    WHERE movement.tenant_id = p_tenant_id
      AND movement.type IN ('grn_receipt', 'grn_amend')
      AND movement.grn_item_id IS NULL
  ) THEN
    RAISE EXCEPTION 'inventory_valuation_grn_lineage_missing'
      USING ERRCODE = '23514';
  END IF;

  SELECT coalesce(pg_catalog.min(grn.received_date), pg_catalog.now())
  INTO v_cutoff_at
  FROM public.goods_received_notes AS grn
  WHERE grn.tenant_id = p_tenant_id
    AND grn.status = 'confirmed';

  INSERT INTO public.inventory_valuation_cutovers (
    tenant_id,
    status,
    cutoff_at,
    prepared_at,
    prepared_by,
    activated_at,
    activated_by,
    idempotency_key
  )
  VALUES (
    p_tenant_id,
    'active',
    v_cutoff_at,
    pg_catalog.now(),
    auth.uid(),
    pg_catalog.now(),
    auth.uid(),
    pg_catalog.md5('inventory-valuation-auto:' || p_tenant_id::text)::uuid
  )
  ON CONFLICT (tenant_id) DO UPDATE
  SET status = 'active',
      cutoff_at = EXCLUDED.cutoff_at,
      prepared_at = EXCLUDED.prepared_at,
      prepared_by = EXCLUDED.prepared_by,
      activated_at = EXCLUDED.activated_at,
      activated_by = EXCLUDED.activated_by,
      idempotency_key = EXCLUDED.idempotency_key,
      updated_at = pg_catalog.now();

  INSERT INTO public.inventory_valuation_settings (tenant_id)
  VALUES (p_tenant_id)
  ON CONFLICT (tenant_id) DO NOTHING;

  CREATE TRIGGER zzzz_inventory_valuation_bootstrap_replay
  AFTER UPDATE OF unit_cost ON public.stock_movements
  FOR EACH ROW
  EXECUTE FUNCTION private.post_stock_movement_valuation();

  FOR v_movement IN
    SELECT movement.id
    FROM public.stock_movements AS movement
    WHERE movement.tenant_id = p_tenant_id
      AND movement.type <> 'grn_amend'
    ORDER BY movement.created_at, movement.id
  LOOP
    UPDATE public.stock_movements
    SET unit_cost = unit_cost
    WHERE id = v_movement.id
      AND tenant_id = p_tenant_id;
  END LOOP;

  DROP TRIGGER zzzz_inventory_valuation_bootstrap_replay
    ON public.stock_movements;

  FOR v_movement IN
    SELECT
      movement.id,
      movement.grn_id,
      movement.ingredient_id,
      movement.branch_id,
      movement.location_id,
      movement.quantity_change,
      movement.created_at,
      movement.created_by
    FROM public.stock_movements AS movement
    WHERE movement.tenant_id = p_tenant_id
      AND movement.type = 'grn_amend'
    ORDER BY movement.created_at, movement.id
  LOOP
    SELECT item.id
    INTO v_grn_item_id
    FROM public.grn_items AS item
    WHERE item.tenant_id = p_tenant_id
      AND item.grn_id = v_movement.grn_id
      AND item.ingredient_id = v_movement.ingredient_id
    ORDER BY item.id
    LIMIT 1;

    IF v_grn_item_id IS NULL THEN
      RAISE EXCEPTION 'inventory_valuation_grn_amend_lineage_missing'
        USING ERRCODE = '23514';
    END IF;

    v_quantity := v_movement.quantity_change;
    IF v_quantity <= 0 THEN
      RAISE EXCEPTION 'inventory_valuation_grn_amend_quantity_invalid'
        USING ERRCODE = '23514';
    END IF;

    SELECT origin.*
    INTO v_origin
    FROM public.inventory_cost_origins AS origin
    WHERE origin.tenant_id = p_tenant_id
      AND origin.source_kind = 'grn_receipt'
      AND origin.grn_item_id = v_grn_item_id
    ORDER BY origin.id
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'inventory_valuation_grn_amend_origin_missing'
        USING ERRCODE = '23514';
    END IF;

    SELECT account.*
    INTO v_account
    FROM public.inventory_valuation_accounts AS account
    WHERE account.tenant_id = p_tenant_id
      AND account.branch_id = v_movement.branch_id
      AND account.location_id = v_movement.location_id
      AND account.ingredient_id = v_movement.ingredient_id
    FOR UPDATE;

    SELECT balance.id
    INTO v_balance_id
    FROM public.inventory_origin_balances AS balance
    WHERE balance.tenant_id = p_tenant_id
      AND balance.origin_id = v_origin.id
      AND balance.valuation_account_id = v_account.id
      AND balance.holder_kind = 'stock_pool'
    FOR UPDATE;

    UPDATE public.inventory_cost_origins
    SET original_quantity = original_quantity + v_quantity
    WHERE id = v_origin.id
      AND tenant_id = p_tenant_id;

    UPDATE public.inventory_origin_balances
    SET quantity = quantity + v_quantity,
        updated_at = pg_catalog.now()
    WHERE id = v_balance_id;

    UPDATE public.inventory_valuation_accounts
    SET quantity = quantity + v_quantity,
        valuation_version = valuation_version + 1,
        updated_at = pg_catalog.now()
    WHERE id = v_account.id
      AND tenant_id = p_tenant_id;

    INSERT INTO public.inventory_valuation_events (
      tenant_id,
      ingredient_id,
      event_type,
      stock_movement_id,
      grn_item_id,
      to_account_id,
      quantity_delta,
      value_delta,
      effective_at,
      posting_year,
      posting_month,
      idempotency_key,
      created_by
    )
    VALUES (
      p_tenant_id,
      v_movement.ingredient_id,
      'receipt',
      v_movement.id,
      v_grn_item_id,
      v_account.id,
      v_quantity,
      0,
      v_movement.created_at,
      extract(
        YEAR FROM v_movement.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
      )::integer,
      extract(
        MONTH FROM v_movement.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
      )::integer,
      pg_catalog.md5('stock-movement:' || v_movement.id::text)::uuid,
      v_movement.created_by
    )
    RETURNING id INTO v_event_id;

    INSERT INTO public.inventory_value_allocations (
      tenant_id,
      valuation_event_id,
      source_origin_id,
      to_balance_id,
      allocation_bucket,
      allocated_quantity,
      allocated_value,
      allocation_fraction
    )
    VALUES (
      p_tenant_id,
      v_event_id,
      v_origin.id,
      v_balance_id,
      'inventory',
      v_quantity,
      0,
      v_quantity / (v_origin.original_quantity + v_quantity)
    );
  END LOOP;

  FOR v_invoice IN
    SELECT invoice.id
    FROM public.supplier_invoices AS invoice
    WHERE invoice.tenant_id = p_tenant_id
      AND invoice.document_status = 'confirmed'
      AND invoice.invoice_kind = 'goods'
    ORDER BY invoice.id
  LOOP
    PERFORM private.settle_supplier_invoice_valuation(
      v_invoice.id,
      pg_catalog.md5(
        'inventory-valuation-auto-settlement:' || v_invoice.id::text
      )::uuid
    );
  END LOOP;

  UPDATE public.stock_levels AS stock
  SET avg_unit_cost = CASE
        WHEN account.quantity > 0
          THEN pg_catalog.round(account.book_value / account.quantity, 8)
        ELSE 0
      END,
      updated_at = pg_catalog.now()
  FROM public.inventory_valuation_accounts AS account
  WHERE account.tenant_id = p_tenant_id
    AND stock.tenant_id = account.tenant_id
    AND stock.branch_id = account.branch_id
    AND stock.location_id = account.location_id
    AND stock.ingredient_id = account.ingredient_id;

  SELECT
    coalesce(pg_catalog.sum(account.quantity), 0),
    coalesce(pg_catalog.sum(account.book_value), 0)
  INTO v_opening_quantity, v_opening_value
  FROM public.inventory_valuation_accounts AS account
  WHERE account.tenant_id = p_tenant_id;

  UPDATE public.inventory_valuation_cutovers
  SET opening_quantity = v_opening_quantity,
      opening_value = v_opening_value,
      updated_at = pg_catalog.now()
  WHERE tenant_id = p_tenant_id;

  RETURN pg_catalog.jsonb_build_object(
    'status', 'active',
    'opening_quantity', v_opening_quantity,
    'opening_value', v_opening_value,
    'replayed', FALSE
  );
END;
$$;


--
-- Name: branch_revenue_targets_enforce_branch_kind(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.branch_revenue_targets_enforce_branch_kind() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_kind text;
  v_tenant bigint;
  v_tier jsonb;
  v_threshold numeric;
  v_reward_type text;
  v_reward_value numeric;
  v_thresholds numeric[] := ARRAY[]::numeric[];
BEGIN
  SELECT b.branch_kind, b.tenant_id
  INTO v_kind, v_tenant
  FROM public.branches b
  WHERE b.id = NEW.branch_id;

  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_kind <> 'branch' THEN
    RAISE EXCEPTION 'branch_kind_not_allowed' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(NEW.reward_tiers) <> 'array'
     OR jsonb_array_length(NEW.reward_tiers) > 10 THEN
    RAISE EXCEPTION 'invalid_reward_tiers' USING ERRCODE = '22023';
  END IF;

  FOR v_tier IN SELECT value FROM jsonb_array_elements(NEW.reward_tiers)
  LOOP
    IF jsonb_typeof(v_tier) <> 'object'
       OR NOT (v_tier ?& ARRAY['threshold_pct', 'reward_type', 'reward_value'])
       OR v_tier - ARRAY['threshold_pct', 'reward_type', 'reward_value']::text[]
          <> '{}'::jsonb
       OR jsonb_typeof(v_tier -> 'threshold_pct') <> 'number'
       OR jsonb_typeof(v_tier -> 'reward_type') <> 'string'
       OR jsonb_typeof(v_tier -> 'reward_value') <> 'number' THEN
      RAISE EXCEPTION 'invalid_reward_tier' USING ERRCODE = '22023';
    END IF;

    v_threshold := (v_tier ->> 'threshold_pct')::numeric;
    v_reward_type := v_tier ->> 'reward_type';
    v_reward_value := (v_tier ->> 'reward_value')::numeric;

    IF v_threshold <= 0
       OR v_threshold > 1000
       OR v_threshold = ANY(v_thresholds)
       OR v_reward_type NOT IN ('fixed_amount', 'revenue_percent')
       OR v_reward_value <= 0
       OR (
         v_reward_type = 'fixed_amount'
         AND (
           v_reward_value > 1000000000000
           OR v_reward_value <> trunc(v_reward_value)
         )
       )
       OR (
         v_reward_type = 'revenue_percent'
         AND v_reward_value > 100
       ) THEN
      RAISE EXCEPTION 'invalid_reward_tier' USING ERRCODE = '22023';
    END IF;

    v_thresholds := array_append(v_thresholds, v_threshold);
  END LOOP;

  NEW.reward_tiers := (
    SELECT COALESCE(jsonb_agg(tier ORDER BY (tier ->> 'threshold_pct')::numeric), '[]'::jsonb)
    FROM jsonb_array_elements(NEW.reward_tiers) AS tier
  );
  NEW.tenant_id := v_tenant;
  NEW.updated_at := now();
  RETURN NEW;
EXCEPTION
  WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'invalid_reward_tier' USING ERRCODE = '22023';
END;
$$;


--
-- Name: can_view_leave_entitlement(bigint, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_view_leave_entitlement(p_employee_id bigint, p_tenant_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_tenant_id = public.auth_tenant_id()
    AND EXISTS (
      SELECT 1
      FROM public.employees e
      JOIN public.profiles pr
        ON pr.id = e.profile_id
       AND pr.tenant_id = e.tenant_id
      WHERE e.id = p_employee_id
        AND e.tenant_id = p_tenant_id
        AND (
          e.profile_id = auth.uid()
          OR public.auth_is_owner(auth.uid())
          OR (
            pr.branch_id IS NOT NULL
            AND pr.branch_id = public.auth_branch_id()
            AND public.has_permission(
              pr.branch_id,
              'hr:approve_leave_request'
            )
          )
        )
    )
$$;


--
-- Name: FUNCTION can_view_leave_entitlement(p_employee_id bigint, p_tenant_id bigint); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.can_view_leave_entitlement(p_employee_id bigint, p_tenant_id bigint) IS 'RLS-safe self, Owner, or exact-branch Branch Manager entitlement visibility without exposing salary-bearing employee rows.';


--
-- Name: canonicalize_notification(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.canonicalize_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_branch_kind text;
BEGIN
  NEW.target_roles := ARRAY(
    SELECT DISTINCT target_role
    FROM unnest(NEW.target_roles) AS roles(target_role)
    WHERE target_role = ANY (ARRAY[
      'owner',
      'accountant',
      'central_supply_ops',
      'central_kitchen_lead',
      'branch_manager',
      'cashier',
      'chef',
      'branch_staff'
    ]::text[])
    ORDER BY target_role
  );

  IF cardinality(NEW.target_roles) = 0 THEN
    RAISE EXCEPTION 'notification_requires_canonical_target_role'
      USING ERRCODE = '23514';
  END IF;

  NEW.action_url := CASE NEW.kind
    WHEN 'procurement.purchase_request_submitted' THEN
      format(
        '/inventory/purchase-orders?tab=needs&demandId=%s&mode=view',
        NEW.entity_id
      )
    WHEN 'procurement.po_pending_approval' THEN
      format(
        '/inventory/purchase-orders?tab=orders&poId=%s&mode=view',
        NEW.entity_id
      )
    WHEN 'workflow.po_approved' THEN
      format(
        '/inventory/purchase-orders?tab=orders&poId=%s&mode=view',
        NEW.entity_id
      )
    WHEN 'workflow.po_sent' THEN
      format(
        '/inventory/purchase-orders?tab=orders&poId=%s&mode=view',
        NEW.entity_id
      )
    ELSE NEW.action_url
  END;

  IF NEW.target_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT branch.branch_kind
  INTO v_branch_kind
  FROM public.branches AS branch
  WHERE branch.id = NEW.target_branch_id
    AND branch.tenant_id = NEW.tenant_id;

  NEW.action_url := CASE NEW.kind
    WHEN 'inventory.stock_low' THEN
      CASE
        WHEN v_branch_kind = 'branch' AND NEW.entity_id IS NULL
          THEN format('/br/%s/stock', NEW.target_branch_id)
        WHEN v_branch_kind = 'branch'
          THEN format(
            '/br/%s/stock/on-hand/%s',
            NEW.target_branch_id,
            NEW.entity_id
          )
        WHEN NEW.entity_id IS NULL
          THEN format('/inventory/stock?branchId=%s', NEW.target_branch_id)
        ELSE format(
          '/inventory/stock/%s?branchId=%s',
          NEW.entity_id,
          NEW.target_branch_id
        )
      END
    WHEN 'inventory.stock_request_submitted' THEN
      format('/inventory/transfers?requestId=%s', NEW.entity_id)
    WHEN 'workflow.grn_pending' THEN
      CASE
        WHEN v_branch_kind = 'branch'
          THEN format('/br/%s/stock/transfer', NEW.target_branch_id)
        ELSE format('/inventory/grn/%s', NEW.entity_id)
      END
    WHEN 'inventory.count_slip_submitted' THEN
      format('/br/%s/stock/count-slips', NEW.target_branch_id)
    WHEN 'workflow.stocktake_submitted' THEN
      CASE
        WHEN v_branch_kind = 'branch'
          THEN format(
            '/br/%s/stock/stocktake/%s',
            NEW.target_branch_id,
            NEW.entity_id
          )
        ELSE format(
          '/inventory/stocktake/%s?branchId=%s',
          NEW.entity_id,
          NEW.target_branch_id
        )
      END
    WHEN 'inventory.stocktake_completed' THEN
      CASE
        WHEN v_branch_kind = 'branch'
          THEN format(
            '/br/%s/stock/stocktake/%s',
            NEW.target_branch_id,
            NEW.entity_id
          )
        ELSE format(
          '/inventory/stocktake/%s?branchId=%s',
          NEW.entity_id,
          NEW.target_branch_id
        )
      END
    WHEN 'inventory.stocktake_conflict' THEN
      CASE
        WHEN v_branch_kind = 'branch'
          THEN format(
            '/br/%s/stock/stocktake/%s',
            NEW.target_branch_id,
            NEW.entity_id
          )
        ELSE format(
          '/inventory/stocktake/%s?branchId=%s',
          NEW.entity_id,
          NEW.target_branch_id
        )
      END
    WHEN 'inventory.waste.weekly_report' THEN
      CASE
        WHEN v_branch_kind = 'branch'
          THEN format('/br/%s/stock/waste-approvals', NEW.target_branch_id)
        ELSE format(
          '/inventory/waste/approvals?branchId=%s',
          NEW.target_branch_id
        )
      END
    WHEN 'workflow.transfer_in_transit' THEN
      format('/br/%s/stock/receive/%s', NEW.target_branch_id, NEW.entity_id)
    WHEN 'hr.leave_requested' THEN
      format('/br/%s/shift/leave-approvals', NEW.target_branch_id)
    WHEN 'attendance.checkout_requested' THEN
      format('/br/%s/shift/checkout-approvals', NEW.target_branch_id)
    WHEN 'inventory.count_slip_approved' THEN
      format('/br/%s/stock/count', NEW.target_branch_id)
    WHEN 'inventory.count_slip_recount' THEN
      format('/br/%s/stock/count', NEW.target_branch_id)
    WHEN 'hr.leave_approved' THEN
      format('/br/%s/shift/schedule/leave', NEW.target_branch_id)
    WHEN 'hr.leave_rejected' THEN
      format('/br/%s/shift/schedule/leave', NEW.target_branch_id)
    WHEN 'pos.shift_variance' THEN
      format(
        '/br/%s/pos-sessions?session=%s',
        NEW.target_branch_id,
        NEW.entity_id
      )
    WHEN 'pos.payment_stock_failed' THEN
      format('/br/%s/orders', NEW.target_branch_id)
    ELSE NEW.action_url
  END;

  RETURN NEW;
END;
$$;


--
-- Name: canonicalize_receipt_print_evidence(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.canonicalize_receipt_print_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_payment public.payments%ROWTYPE;
  v_attempt_count integer;
  v_completed_total numeric;
BEGIN
  IF NEW.job_type <> 'receipt' THEN
    RETURN NEW;
  END IF;

  IF NEW.order_id IS NULL THEN
    RAISE EXCEPTION 'receipt_order_id_missing'
      USING ERRCODE = '23514';
  END IF;

  SELECT *
  INTO v_payment
  FROM public.payments payment
  WHERE payment.tenant_id = NEW.tenant_id
    AND payment.branch_id = NEW.branch_id
    AND payment.order_id = NEW.order_id
    AND payment.status = 'completed'
    AND payment.paid_at IS NOT NULL
  ORDER BY payment.paid_at DESC, payment.id DESC
  LIMIT 1;

  IF v_payment.id IS NULL THEN
    RAISE EXCEPTION 'receipt_completed_payment_missing'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    count(*)::integer,
    COALESCE(sum(payment.amount) FILTER (
      WHERE payment.status = 'completed'
    ), 0)::numeric
  INTO v_attempt_count, v_completed_total
  FROM public.payments payment
  WHERE payment.tenant_id = NEW.tenant_id
    AND payment.order_id = NEW.order_id;

  NEW.payload := NEW.payload || jsonb_build_object(
    'payment_id', v_payment.id,
    'payment_method', v_payment.method,
    'payment_amount', v_payment.amount,
    'completed_payment_total', v_completed_total,
    'payment_attempt_count', v_attempt_count,
    'paid_at', to_char(
      v_payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
      'YYYY-MM-DD"T"HH24:MI:SS'
    ),
    'printed_at', to_char(
      v_payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
      'YYYY-MM-DD"T"HH24:MI:SS'
    )
  );

  NEW.idempotency_key :=
    'order:' || NEW.order_id::text
    || ':receipt:truth:v2:printer:' || NEW.printer_id::text
    || ':payment:' || v_payment.id::text
    || ':' || md5(NEW.payload::text);

  RETURN NEW;
END;
$$;


--
-- Name: canonicalize_shift_close_print_evidence(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.canonicalize_shift_close_print_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_session public.pos_sessions%ROWTYPE;
  v_payment_breakdown jsonb;
  v_total_revenue numeric;
  v_paid_order_count integer;
  v_payment_attempt_count integer;
  v_item_counts jsonb;
  v_payment_exceptions jsonb;
BEGIN
  IF NEW.job_type <> 'shift_close_report' THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.payload->>'session_id', '') !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'shift_close_session_id_missing'
      USING ERRCODE = '23514';
  END IF;

  SELECT *
  INTO v_session
  FROM public.pos_sessions session
  WHERE session.id = (NEW.payload->>'session_id')::bigint
    AND session.tenant_id = NEW.tenant_id
    AND session.branch_id = NEW.branch_id;

  IF v_session.id IS NULL OR v_session.status <> 'closed' THEN
    RAISE EXCEPTION 'shift_close_session_invalid'
      USING ERRCODE = '23514';
  END IF;

  WITH eligible_payments AS (
    SELECT
      payment.order_id,
      payment.method,
      payment.amount
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  ),
  grouped AS (
    SELECT
      payment.method,
      count(*)::integer AS payment_count,
      count(DISTINCT payment.order_id)::integer AS order_count,
      COALESCE(sum(payment.amount), 0)::numeric AS amount
    FROM eligible_payments payment
    GROUP BY payment.method
  )
  SELECT
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'method', grouped.method,
        'count', grouped.payment_count,
        'order_count', grouped.order_count,
        'amount', grouped.amount
      )
      ORDER BY grouped.method
    ), '[]'::jsonb),
    COALESCE((
      SELECT sum(payment.amount) FROM eligible_payments payment
    ), 0)::numeric,
    COALESCE((
      SELECT count(DISTINCT payment.order_id)
      FROM eligible_payments payment
    ), 0)::integer
  INTO
    v_payment_breakdown,
    v_total_revenue,
    v_paid_order_count
  FROM grouped;

  SELECT count(*)::integer
  INTO v_payment_attempt_count
  FROM public.payments payment
  JOIN public.orders orders
    ON orders.id = payment.order_id
   AND orders.tenant_id = payment.tenant_id
  WHERE payment.tenant_id = v_session.tenant_id
    AND orders.pos_session_id = v_session.id;

  WITH paid_orders AS (
    SELECT DISTINCT orders.id
    FROM public.orders orders
    JOIN public.payments payment
      ON payment.order_id = orders.id
     AND payment.tenant_id = orders.tenant_id
     AND payment.branch_id = orders.branch_id
    WHERE orders.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  )
  SELECT jsonb_build_object(
    'item_row_count', count(*)::integer,
    'item_quantity', COALESCE(sum(item.quantity), 0)::integer,
    'main_dish_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot = 'main_dish'
    ), 0)::integer,
    'side_dish_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot = 'side_dish'
    ), 0)::integer,
    'legacy_unclassified_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot IS NULL
    ), 0)::integer,
    'legacy_current_main_dish_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot IS NULL
        AND current_category.type = 'main_dish'
    ), 0)::integer,
    'included_side_quantity', COALESCE(sum(
      item.quantity * COALESCE((
        SELECT sum(
          CASE
            WHEN COALESCE(side->>'quantity', '') ~ '^[0-9]+$'
              THEN (side->>'quantity')::integer
            ELSE 1
          END
        )
        FROM jsonb_array_elements(item.sides) side
      ), 0)
    ), 0)::integer
  )
  INTO v_item_counts
  FROM public.order_items item
  JOIN paid_orders paid_order
    ON paid_order.id = item.order_id
  LEFT JOIN public.menu_items current_item
    ON current_item.id = item.menu_item_id
   AND current_item.tenant_id = item.tenant_id
  LEFT JOIN public.menu_categories current_category
    ON current_category.id = current_item.category_id
   AND current_category.tenant_id = current_item.tenant_id
  WHERE item.tenant_id = v_session.tenant_id
    AND item.status <> 'cancelled';

  SELECT jsonb_build_object(
    'order_payment_state_mismatch_count', count(DISTINCT orders.id) FILTER (
      WHERE orders.payment_status IS DISTINCT FROM 'paid'
        OR orders.status = 'cancelled'
        OR payment.amount IS DISTINCT FROM orders.total_amount
    ),
    'late_payment_count', count(*) FILTER (
      WHERE payment.paid_at < v_session.opened_at
        OR payment.paid_at > v_session.closed_at
    ),
    'late_payment_amount', COALESCE(sum(payment.amount) FILTER (
      WHERE payment.paid_at < v_session.opened_at
        OR payment.paid_at > v_session.closed_at
    ), 0)
  )
  INTO v_payment_exceptions
  FROM public.payments payment
  JOIN public.orders orders
    ON orders.id = payment.order_id
   AND orders.tenant_id = payment.tenant_id
   AND orders.branch_id = payment.branch_id
  WHERE payment.tenant_id = v_session.tenant_id
    AND orders.pos_session_id = v_session.id
    AND payment.status = 'completed'
    AND payment.paid_at IS NOT NULL;

  NEW.payload := NEW.payload || jsonb_build_object(
    'paid_order_count', v_paid_order_count,
    'payment_attempt_count', v_payment_attempt_count,
    'payment_breakdown', v_payment_breakdown,
    'payment_exceptions', v_payment_exceptions,
    'total_revenue', v_total_revenue,
    'item_counts', v_item_counts,
    'printed_at', to_char(
      v_session.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
      'YYYY-MM-DD"T"HH24:MI:SS'
    )
  );

  NEW.idempotency_key :=
    'session:' || v_session.id::text
    || ':shift_close:truth:v2:'
    || md5(NEW.payload::text);

  RETURN NEW;
END;
$_$;


--
-- Name: capture_kds_ticket_event(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.capture_kds_ticket_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_event_type text;
  v_actor_id uuid;
  v_station_name text;
  v_item public.order_items%ROWTYPE;
  v_batch public.kitchen_send_batches%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_event_type := CASE NEW.status
      WHEN 'pending' THEN 'sent'
      WHEN 'preparing' THEN 'preparing'
      WHEN 'ready' THEN 'completed'
      WHEN 'served' THEN 'served'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULL
    END;
  ELSIF NEW.status = 'preparing' AND OLD.status = 'ready' THEN
    v_event_type := 'recalled';
  ELSIF NEW.status = 'pending' AND OLD.status = 'preparing' THEN
    v_event_type := 'recalled';
  ELSIF NEW.status = 'preparing' THEN
    v_event_type := 'preparing';
  ELSIF NEW.status = 'ready' THEN
    v_event_type := 'completed';
  ELSIF NEW.status = 'served' THEN
    v_event_type := 'served';
  ELSIF NEW.status = 'cancelled' THEN
    SELECT *
    INTO v_item
    FROM public.order_items item
    WHERE item.id = NEW.order_item_id
      AND item.tenant_id = NEW.tenant_id;

    v_event_type := CASE
      WHEN COALESCE(v_item.cancel_reason, '') LIKE 'kds_out_of_stock:%'
        THEN 'out_of_stock'
      ELSE 'cancelled'
    END;
  ELSE
    RETURN NULL;
  END IF;

  IF v_event_type IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_item.id IS NULL THEN
    SELECT *
    INTO v_item
    FROM public.order_items item
    WHERE item.id = NEW.order_item_id
      AND item.tenant_id = NEW.tenant_id;
  END IF;

  IF v_event_type = 'cancelled'
    AND COALESCE(v_item.cancel_reason, '') LIKE 'kds_out_of_stock:%'
  THEN
    v_event_type := 'out_of_stock';
  END IF;

  IF NEW.kitchen_send_batch_id IS NOT NULL THEN
    SELECT *
    INTO v_batch
    FROM public.kitchen_send_batches batch
    WHERE batch.id = NEW.kitchen_send_batch_id
      AND batch.tenant_id = NEW.tenant_id;
  END IF;

  SELECT station.name
  INTO v_station_name
  FROM public.kds_stations station
  WHERE station.id = NEW.station_id
    AND station.tenant_id = NEW.tenant_id
    AND station.branch_id = NEW.branch_id;

  v_actor_id := COALESCE(auth.uid(), NEW.bumped_by, v_batch.created_by);

  INSERT INTO public.kds_ticket_events (
    tenant_id,
    branch_id,
    order_id,
    ticket_id,
    order_item_id,
    station_id,
    kitchen_send_batch_id,
    event_type,
    from_status,
    to_status,
    actor_id,
    reason,
    item_snapshot,
    context,
    occurred_at
  ) VALUES (
    NEW.tenant_id,
    NEW.branch_id,
    NEW.order_id,
    NEW.id,
    NEW.order_item_id,
    NEW.station_id,
    NEW.kitchen_send_batch_id,
    v_event_type,
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.status END,
    NEW.status,
    v_actor_id,
    v_item.cancel_reason,
    jsonb_build_object(
      'item_id', v_item.id,
      'menu_item_id', v_item.menu_item_id,
      'item_name', v_item.item_name,
      'variant_name', v_item.variant_name,
      'quantity', v_item.quantity,
      'modifiers', v_item.modifiers,
      'sides', v_item.sides,
      'note', v_item.note,
      'category_type', v_item.category_type_snapshot,
      'category_source', v_item.category_snapshot_source
    ),
    jsonb_build_object(
      'kitchen_ticket_number', v_batch.kitchen_ticket_number,
      'station_name', v_station_name,
      'send_seq', v_batch.send_seq,
      'send_kind', v_batch.kind,
      'first_ready_at', NEW.first_ready_at,
      'bumped_at', NEW.bumped_at
    ),
    CASE WHEN TG_OP = 'INSERT' THEN NEW.created_at ELSE now() END
  );

  RETURN NULL;
END;
$$;


--
-- Name: check_expense_transfer_content_event(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.check_expense_transfer_content_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_old_event_id bigint;
  v_new_event_id bigint;
  v_old_expense_id bigint;
  v_new_expense_id bigint;
  v_expense_id bigint;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    v_old_event_id := OLD.id;
    v_old_expense_id := OLD.expense_id;
  END IF;

  IF TG_OP <> 'DELETE' THEN
    v_new_event_id := NEW.id;
    v_new_expense_id := NEW.expense_id;
  END IF;

  FOR v_expense_id IN
    SELECT DISTINCT candidate.expense_id
    FROM (
      SELECT match.expense_id
      FROM public.bank_transaction_expense_matches match
      WHERE match.webhook_event_id IN (v_old_event_id, v_new_event_id)
      UNION ALL
      SELECT v_old_expense_id
      UNION ALL
      SELECT v_new_expense_id
    ) candidate
    WHERE candidate.expense_id IS NOT NULL
  LOOP
    PERFORM private.assert_expense_transfer_content(v_expense_id);
  END LOOP;

  RETURN NULL;
END;
$$;


--
-- Name: check_expense_transfer_content_expense(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.check_expense_transfer_content_expense() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM private.assert_expense_transfer_content(NEW.id);
  RETURN NULL;
END;
$$;


--
-- Name: check_expense_transfer_content_match(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.check_expense_transfer_content_match() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    PERFORM private.assert_expense_transfer_content(OLD.expense_id);
  END IF;

  IF TG_OP <> 'DELETE'
    AND (
      TG_OP = 'INSERT'
      OR OLD.expense_id IS DISTINCT FROM NEW.expense_id
    )
  THEN
    PERFORM private.assert_expense_transfer_content(NEW.expense_id);
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: consume_stock_for_order_at_warehouse(bigint, uuid, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.consume_stock_for_order_at_warehouse(p_order_id bigint, p_actor_id uuid, p_tenant_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order record;
  v_need record;
  v_stock_quantity numeric(15,3);
  v_location_id bigint;
  v_entry_unit_id bigint;
BEGIN
  SELECT
    orders.id,
    orders.tenant_id,
    orders.branch_id,
    orders.status,
    orders.created_by
  INTO v_order
  FROM public.orders
  WHERE orders.id = p_order_id
    AND (
      p_tenant_id IS NULL
      OR orders.tenant_id = p_tenant_id
    )
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;
  p_actor_id := coalesce(p_actor_id, v_order.created_by);
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'consumption_actor_missing'
      USING ERRCODE = 'not_null_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.stock_movements AS movement
    WHERE movement.order_id = p_order_id
      AND movement.type = 'consumption'
      AND movement.tenant_id = v_order.tenant_id
  ) THEN
    RETURN jsonb_build_object(
      'order_id', p_order_id,
      'skipped', TRUE,
      'reason', 'already_consumed'
    );
  END IF;

  SELECT location.id
  INTO v_location_id
  FROM public.inventory_locations AS location
  WHERE location.branch_id = v_order.branch_id
    AND location.tenant_id = v_order.tenant_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'consumption_warehouse_missing:%',
      v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  FOR v_need IN
    SELECT
      recipe.ingredient_id,
      sum(public.inv_to_base(
        recipe.ingredient_id,
        recipe.entry_unit_id,
        order_item.quantity::numeric
          * recipe.quantity
          / recipe.yield_factor
      )) AS quantity
    FROM public.order_items AS order_item
    JOIN public.recipes AS recipe
      ON recipe.menu_item_id = order_item.menu_item_id
     AND recipe.tenant_id = order_item.tenant_id
    WHERE order_item.order_id = p_order_id
      AND order_item.tenant_id = v_order.tenant_id
      AND order_item.status <> 'cancelled'
    GROUP BY recipe.ingredient_id
    ORDER BY recipe.ingredient_id
  LOOP
    SELECT stock.current_quantity
    INTO v_stock_quantity
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_order.tenant_id
      AND stock.branch_id = v_order.branch_id
      AND stock.location_id = v_location_id
      AND stock.ingredient_id = v_need.ingredient_id
    FOR UPDATE;

    IF coalesce(v_stock_quantity, 0) < v_need.quantity THEN
      RAISE EXCEPTION 'insufficient_stock_ingredient:%',
        v_need.ingredient_id
        USING ERRCODE = 'P0001';
    END IF;
  END LOOP;

  FOR v_need IN
    SELECT
      recipe.ingredient_id,
      sum(public.inv_to_base(
        recipe.ingredient_id,
        recipe.entry_unit_id,
        order_item.quantity::numeric
          * recipe.quantity
          / recipe.yield_factor
      )) AS quantity
    FROM public.order_items AS order_item
    JOIN public.recipes AS recipe
      ON recipe.menu_item_id = order_item.menu_item_id
     AND recipe.tenant_id = order_item.tenant_id
    WHERE order_item.order_id = p_order_id
      AND order_item.tenant_id = v_order.tenant_id
      AND order_item.status <> 'cancelled'
    GROUP BY recipe.ingredient_id
    ORDER BY recipe.ingredient_id
  LOOP
    SELECT ingredient_unit.unit_id
    INTO v_entry_unit_id
    FROM public.ingredient_units AS ingredient_unit
    JOIN public.units AS unit
      ON unit.id = ingredient_unit.unit_id
     AND unit.tenant_id = ingredient_unit.tenant_id
     AND unit.is_active IS TRUE
    WHERE ingredient_unit.tenant_id = v_order.tenant_id
      AND ingredient_unit.ingredient_id = v_need.ingredient_id
      AND ingredient_unit.is_base IS TRUE
      AND ingredient_unit.is_active IS TRUE
    ORDER BY ingredient_unit.sort_order, ingredient_unit.id
    LIMIT 1;

    IF v_entry_unit_id IS NULL THEN
      RAISE EXCEPTION 'entry_unit_not_found:%',
        v_need.ingredient_id
        USING ERRCODE = 'foreign_key_violation';
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      quantity_change,
      reason,
      created_by,
      order_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    SELECT
      v_order.tenant_id,
      v_order.branch_id,
      v_need.ingredient_id,
      'consumption',
      -v_need.quantity,
      'Order ' || p_order_id::text,
      p_actor_id,
      p_order_id,
      coalesce(stock.avg_unit_cost, 0),
      v_location_id,
      v_entry_unit_id,
      v_need.quantity
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_order.tenant_id
      AND stock.branch_id = v_order.branch_id
      AND stock.location_id = v_location_id
      AND stock.ingredient_id = v_need.ingredient_id;
  END LOOP;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'consumed', TRUE,
    'location_id', v_location_id
  );
END;
$$;


--
-- Name: create_inventory_cost_origin(bigint, bigint, text, bigint, bigint, numeric, numeric, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_inventory_cost_origin(p_tenant_id bigint, p_ingredient_id bigint, p_source_kind text, p_source_id bigint, p_grn_item_id bigint, p_quantity numeric, p_value numeric, p_effective_at timestamp with time zone, p_cost_status text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_origin_id bigint;
BEGIN
  INSERT INTO public.inventory_cost_origins (
    tenant_id,
    ingredient_id,
    source_kind,
    source_id,
    grn_item_id,
    original_quantity,
    provisional_value,
    cost_status,
    effective_at
  )
  VALUES (
    p_tenant_id,
    p_ingredient_id,
    p_source_kind,
    p_source_id,
    p_grn_item_id,
    p_quantity,
    p_value,
    p_cost_status,
    p_effective_at
  )
  ON CONFLICT (tenant_id, source_kind, source_id)
  DO UPDATE SET source_id = EXCLUDED.source_id
  RETURNING id INTO v_origin_id;

  RETURN v_origin_id;
END;
$$;


--
-- Name: enforce_branch_inventory_site_warehouse(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_branch_inventory_site_warehouse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    PERFORM private.assert_inventory_site_warehouse(
      OLD.tenant_id,
      OLD.id
    );
  END IF;

  IF TG_OP <> 'DELETE' THEN
    PERFORM private.assert_inventory_site_warehouse(
      NEW.tenant_id,
      NEW.id
    );
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: enforce_confirmed_supplier_invoice_payment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_confirmed_supplier_invoice_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.supplier_invoices AS invoice
    WHERE invoice.id = NEW.supplier_invoice_id
      AND invoice.tenant_id = NEW.tenant_id
      AND invoice.document_status = 'confirmed'
      AND invoice.matching_status = 'matched'
  ) THEN
    RAISE EXCEPTION 'supplier_invoice_not_payable'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_inventory_site_warehouse(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_inventory_site_warehouse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    PERFORM private.assert_inventory_site_warehouse(
      OLD.tenant_id,
      OLD.branch_id
    );
  END IF;

  IF TG_OP <> 'DELETE'
     AND (
       TG_OP = 'INSERT'
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
       OR NEW.location_kind IS DISTINCT FROM OLD.location_kind
       OR NEW.is_active IS DISTINCT FROM OLD.is_active
       OR NEW.is_default_receive IS DISTINCT FROM OLD.is_default_receive
       OR NEW.is_default_issue IS DISTINCT FROM OLD.is_default_issue
       OR NEW.is_default_consumption IS DISTINCT FROM OLD.is_default_consumption
     ) THEN
    PERFORM private.assert_inventory_site_warehouse(
      NEW.tenant_id,
      NEW.branch_id
    );
  END IF;

  RETURN NULL;
END;
$$;


