--
-- Name: enforce_leave_review_authority(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_leave_review_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_actor_branch bigint;
  v_requester_id uuid;
  v_requester_role text;
  v_requester_branch bigint;
BEGIN
  IF OLD.status IS DISTINCT FROM 'pending'
     OR NEW.status NOT IN ('approved', 'rejected')
     OR v_actor_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT private.staff_role_from_position_code(po.code), pr.branch_id
  INTO v_actor_role, v_actor_branch
  FROM public.profiles pr
  JOIN public.positions po
    ON po.id = pr.position_id
   AND po.tenant_id = pr.tenant_id
  WHERE pr.id = v_actor_id
    AND pr.tenant_id = NEW.tenant_id
    AND COALESCE(pr.is_active, true) = true
    AND COALESCE(po.is_active, true) = true;

  SELECT
    e.profile_id,
    private.staff_role_from_position_code(po.code),
    pr.branch_id
  INTO v_requester_id, v_requester_role, v_requester_branch
  FROM public.employees e
  JOIN public.profiles pr
    ON pr.id = e.profile_id
   AND pr.tenant_id = e.tenant_id
  JOIN public.positions po
    ON po.id = pr.position_id
   AND po.tenant_id = pr.tenant_id
  WHERE e.id = NEW.employee_id
    AND e.tenant_id = NEW.tenant_id;

  IF v_actor_id = v_requester_id THEN
    RAISE EXCEPTION 'cannot_review_own_leave_request' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role = 'owner' THEN
    RETURN NEW;
  END IF;

  IF v_actor_role <> 'branch_manager'
     OR v_actor_branch IS DISTINCT FROM NEW.branch_id
     OR v_requester_branch IS DISTINCT FROM NEW.branch_id
     OR v_requester_role NOT IN ('cashier', 'chef', 'branch_staff')
     OR NOT public.has_permission(NEW.branch_id, 'hr:approve_leave_request') THEN
    RAISE EXCEPTION 'leave_review_not_allowed' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_linked_grn_line_immutability(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_linked_grn_line_immutability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_grn record;
  v_po_item record;
  v_confirming boolean := coalesce(pg_catalog.current_setting('comtammatu.grn_confirm', TRUE), 'false') = 'true';
BEGIN
  IF TG_OP = 'UPDATE'
     AND (to_jsonb(NEW) - 'entry_to_base_factor' - 'entry_unit_code') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'entry_to_base_factor' - 'entry_unit_code') THEN
    RETURN NEW;
  END IF;
  SELECT grn.* INTO v_grn FROM public.goods_received_notes AS grn
  WHERE grn.id = coalesce(NEW.grn_id, OLD.grn_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002'; END IF;
  IF TG_OP = 'DELETE' THEN
    IF v_grn.status = 'draft' THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'confirmed_grn_lines_immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.grn_id IS DISTINCT FROM OLD.grn_id OR NEW.purchase_order_item_id IS DISTINCT FROM OLD.purchase_order_item_id
    OR NEW.ingredient_id IS DISTINCT FROM OLD.ingredient_id OR NEW.entry_unit_id IS DISTINCT FROM OLD.entry_unit_id
    OR NEW.supplier_id IS DISTINCT FROM OLD.supplier_id
  ) THEN RAISE EXCEPTION 'grn_line_identity_immutable' USING ERRCODE = '23514'; END IF;
  SELECT po_item.*, purchase_order.supplier_id INTO v_po_item
  FROM public.purchase_order_items AS po_item JOIN public.purchase_orders AS purchase_order
    ON purchase_order.id = po_item.po_id AND purchase_order.tenant_id = po_item.tenant_id
  WHERE po_item.id = NEW.purchase_order_item_id AND po_item.tenant_id = v_grn.tenant_id AND po_item.po_id = v_grn.po_id;
  IF NOT FOUND OR NEW.ingredient_id <> v_po_item.ingredient_id
     OR NEW.entry_unit_id IS DISTINCT FROM v_po_item.entry_unit_id OR NEW.supplier_id <> v_po_item.supplier_id
  THEN RAISE EXCEPTION 'grn_line_po_mismatch' USING ERRCODE = '23514'; END IF;
  IF v_confirming THEN RETURN NEW; END IF;
  IF v_grn.status <> 'draft' THEN RAISE EXCEPTION 'confirmed_grn_lines_immutable' USING ERRCODE = '23514'; END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.unit_cost := OLD.unit_cost;
    NEW.cost_pending := OLD.cost_pending;
    NEW.provisional_cost_source := OLD.provisional_cost_source;
  END IF;
  NEW.total_cost := 0;
  NEW.po_applied_quantity := 0;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_linked_grn_line_immutability(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.enforce_linked_grn_line_immutability() IS 'Linked GRN line immutability. Allows approve price sync from any draft PO linked via po_id or source_grn_id (multi-supplier).';


