--
-- Name: enforce_retrospective_grn_immutability(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_retrospective_grn_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_po record;
  v_trusted boolean;
BEGIN
  SELECT CURRENT_USER = pg_catalog.pg_get_userbyid(relation.relowner)
  INTO v_trusted
  FROM pg_catalog.pg_class relation
  WHERE relation.oid =
    'public.goods_received_notes'::pg_catalog.regclass;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'grn_must_start_as_draft'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.creation_idempotency_key IS NOT NULL
       AND (
         v_trusted IS DISTINCT FROM TRUE
         OR COALESCE(
           current_setting('comtammatu.po_first_grn_insert', TRUE),
           'false'
         ) <> 'true'
       ) THEN
      RAISE EXCEPTION 'grn_insert_requires_rpc'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'grn_delete_forbidden' USING ERRCODE = '23514';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
     OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
     OR NEW.po_id IS DISTINCT FROM OLD.po_id
     OR NEW.supplier_id IS DISTINCT FROM OLD.supplier_id
     OR NEW.grn_number IS DISTINCT FROM OLD.grn_number
     OR NEW.location_id IS DISTINCT FROM OLD.location_id
     OR NEW.creation_idempotency_key IS DISTINCT FROM
       OLD.creation_idempotency_key THEN
    RAISE EXCEPTION 'grn_identity_immutable' USING ERRCODE = '23514';
  END IF;

  IF OLD.status = 'draft'
     AND NEW.status IN ('draft', 'confirmed', 'cancelled') THEN
    IF NEW.po_id IS NOT NULL THEN
      SELECT purchase_order.*
      INTO v_po
      FROM public.purchase_orders purchase_order
      WHERE purchase_order.id = NEW.po_id
        AND purchase_order.tenant_id = NEW.tenant_id;

      IF NOT FOUND
         OR v_po.branch_id <> NEW.branch_id
         OR v_po.supplier_id <> NEW.supplier_id THEN
        RAISE EXCEPTION 'grn_po_mismatch' USING ERRCODE = '23514';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'grn_status_transition_invalid' USING ERRCODE = '23514';
END;
$$;


--
-- Name: FUNCTION enforce_retrospective_grn_immutability(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.enforce_retrospective_grn_immutability() IS 'Retrospective GRN↔PO link guard. Multi-supplier drafts (NULL header supplier_id) snapshot only the lines for the linked first PO supplier.';


--
-- Name: enforce_retrospective_purchase_order_immutability(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_retrospective_purchase_order_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_linked boolean := FALSE;
  v_trusted_rpc boolean;
BEGIN
  SELECT CURRENT_USER = pg_catalog.pg_get_userbyid(relation.relowner)
  INTO v_trusted_rpc
  FROM pg_catalog.pg_class AS relation
  WHERE relation.oid = 'public.purchase_orders'::pg_catalog.regclass;

  IF TG_OP = 'INSERT' THEN
    IF v_trusted_rpc IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'purchase_order_insert_requires_rpc'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.status NOT IN ('draft', 'pending_approval') THEN
      RAISE EXCEPTION 'purchase_order_initial_status_invalid'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'retrospective-po:' || OLD.id::text,
      0
    )
  );

  SELECT EXISTS (
    SELECT 1
    FROM public.goods_received_notes AS grn
    WHERE grn.tenant_id = OLD.tenant_id
      AND (
        grn.po_id = OLD.id
        OR OLD.source_grn_id = grn.id
      )
  )
  INTO v_linked;

  IF TG_OP = 'DELETE' THEN
    IF v_linked THEN
      RAISE EXCEPTION 'linked_grn_purchase_order_immutable'
        USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF v_trusted_rpc IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'purchase_order_status_requires_rpc'
        USING ERRCODE = '42501';
    END IF;
    IF NOT (
      (OLD.status = 'draft'
        AND NEW.status IN ('sent', 'pending_approval', 'cancelled'))
      OR (
        OLD.status = 'changes_requested'
        AND NEW.status IN ('pending_approval', 'cancelled')
      )
      OR (
        OLD.status = 'pending_approval'
        AND NEW.status IN ('approved', 'changes_requested', 'cancelled')
      )
      OR (
        OLD.status = 'sent'
        AND NEW.status IN ('partially_received', 'received', 'cancelled')
      )
      OR (
        OLD.status = 'approved'
        AND NEW.status IN (
          'partially_received',
          'received',
          'closed',
          'cancelled'
        )
      )
      OR (
        OLD.status = 'partially_received'
        AND NEW.status IN ('received', 'closed')
      )
    ) THEN
      RAISE EXCEPTION 'purchase_order_status_transition_invalid'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_linked
     AND (
       NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
       OR NEW.supplier_id IS DISTINCT FROM OLD.supplier_id
       OR NEW.po_number IS DISTINCT FROM OLD.po_number
       OR NEW.display_id IS DISTINCT FROM OLD.display_id
       OR NEW.ordered_at IS DISTINCT FROM OLD.ordered_at
       OR NEW.expected_delivery_date IS DISTINCT FROM
         OLD.expected_delivery_date
       OR NEW.notes IS DISTINCT FROM OLD.notes
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.source_grn_id IS DISTINCT FROM OLD.source_grn_id
       OR NEW.purchase_group_key IS DISTINCT FROM OLD.purchase_group_key
       OR NEW.purchase_group_code IS DISTINCT FROM OLD.purchase_group_code
       OR NEW.group_sequence IS DISTINCT FROM OLD.group_sequence
     ) THEN
    RAISE EXCEPTION 'linked_grn_purchase_order_immutable'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_retrospective_purchase_order_immutability(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.enforce_retrospective_purchase_order_immutability() IS 'Retrospective PO immutability. Links via grn.po_id or purchase_orders.source_grn_id (multi-supplier split).';


--
-- Name: enforce_retrospective_purchase_order_line_immutability(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_retrospective_purchase_order_line_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_po_id bigint; v_po_ids bigint[]; v_old_tenant_id bigint; v_new_tenant_id bigint;
  v_po_status text; v_linked boolean := FALSE; v_trusted_rpc boolean;
BEGIN
  IF TG_OP = 'UPDATE'
     AND (to_jsonb(NEW) - 'entry_to_base_factor' - 'entry_unit_code') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'entry_to_base_factor' - 'entry_unit_code') THEN
    RETURN NEW;
  END IF;
  SELECT CURRENT_USER = pg_catalog.pg_get_userbyid(relation.relowner) INTO v_trusted_rpc
  FROM pg_catalog.pg_class AS relation WHERE relation.oid = 'public.purchase_order_items'::pg_catalog.regclass;
  IF TG_OP = 'INSERT' THEN
    v_po_ids := ARRAY[NEW.po_id]; v_new_tenant_id := NEW.tenant_id;
  ELSIF TG_OP = 'DELETE' THEN
    v_po_ids := ARRAY[OLD.po_id]; v_old_tenant_id := OLD.tenant_id;
  ELSE
    v_po_ids := ARRAY[OLD.po_id, NEW.po_id]; v_old_tenant_id := OLD.tenant_id; v_new_tenant_id := NEW.tenant_id;
  END IF;
  FOR v_po_id IN SELECT DISTINCT candidate.po_id FROM unnest(v_po_ids) AS candidate(po_id)
    WHERE candidate.po_id IS NOT NULL ORDER BY candidate.po_id
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('retrospective-po:' || v_po_id::text, 0));
  END LOOP;
  SELECT EXISTS (
    SELECT 1 FROM public.goods_received_notes AS grn
    WHERE grn.po_id = ANY (v_po_ids) AND (grn.tenant_id = v_old_tenant_id OR grn.tenant_id = v_new_tenant_id)
  ) INTO v_linked;
  IF NOT v_linked THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND v_trusted_rpc IS TRUE
     AND NEW.id IS NOT DISTINCT FROM OLD.id AND NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id
     AND NEW.po_id IS NOT DISTINCT FROM OLD.po_id AND NEW.ingredient_id IS NOT DISTINCT FROM OLD.ingredient_id
     AND NEW.quantity IS NOT DISTINCT FROM OLD.quantity AND NEW.entry_unit_id IS NOT DISTINCT FROM OLD.entry_unit_id
  THEN
    SELECT purchase_order.status INTO v_po_status FROM public.purchase_orders AS purchase_order WHERE purchase_order.id = NEW.po_id;
    IF v_po_status = 'draft' THEN RETURN NEW; END IF;
  END IF;
  RAISE EXCEPTION 'linked_grn_purchase_order_lines_immutable' USING ERRCODE = 'check_violation';
END;
$$;


--
-- Name: enforce_staff_permission_boundary(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_staff_permission_boundary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target_position text;
  v_target_branch_id bigint;
  v_source_position text;
  v_permission_scope text;
  v_is_delegable_to_staff boolean;
BEGIN
  SELECT po.code, pr.branch_id
  INTO v_target_position, v_target_branch_id
  FROM public.profiles pr
  JOIN public.positions po
    ON po.id = pr.position_id
   AND po.tenant_id = pr.tenant_id
  WHERE pr.id = NEW.user_id
    AND pr.tenant_id = NEW.tenant_id;

  IF v_target_position IS NULL
     OR private.staff_role_from_position_code(v_target_position) IS NULL THEN
    RAISE EXCEPTION 'permission_target_position_not_canonical'
      USING ERRCODE = '23514';
  END IF;

  SELECT scope, is_delegable_to_staff
  INTO v_permission_scope, v_is_delegable_to_staff
  FROM public.permission_keys
  WHERE key = NEW.permission_key;

  IF v_permission_scope IS NULL THEN
    RAISE EXCEPTION 'permission_key_not_canonical'
      USING ERRCODE = '23514';
  END IF;

  IF v_permission_scope = 'tenant' AND NEW.branch_id IS NOT NULL THEN
    RAISE EXCEPTION 'tenant_permission_cannot_have_branch'
      USING ERRCODE = '23514';
  END IF;

  IF v_permission_scope = 'branch'
     AND private.staff_role_from_position_code(v_target_position) <> 'owner'
     AND NEW.branch_id IS DISTINCT FROM v_target_branch_id THEN
    RAISE EXCEPTION 'branch_permission_must_match_profile_branch'
      USING ERRCODE = '23514';
  END IF;

  IF private.staff_role_from_position_code(v_target_position) <> 'owner'
     AND v_is_delegable_to_staff = false THEN
    RAISE EXCEPTION 'owner_only_permission_cannot_be_delegated'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.permission_key = ANY (ARRAY[
       'hr:approve_checkout',
       'hr:approve_leave_request'
     ]::text[])
     AND private.staff_role_from_position_code(v_target_position)
       <> 'branch_manager' THEN
    RAISE EXCEPTION 'approval_permission_requires_branch_manager'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.source_template IS NOT NULL THEN
    SELECT rt.position_code
    INTO v_source_position
    FROM public.role_templates rt
    WHERE rt.id = NEW.source_template
      AND rt.tenant_id = NEW.tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'permission_source_template_not_in_tenant'
        USING ERRCODE = '23514';
    END IF;

    IF private.staff_role_from_position_code(v_target_position) <> 'owner'
       AND v_source_position = 'owner' THEN
      RAISE EXCEPTION 'owner_template_cannot_be_applied_to_staff'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_stock_issue_creator(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_stock_issue_creator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
    END IF;
    NEW.created_by := auth.uid();
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_stock_issue_status_authority(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_stock_issue_status_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon')
     AND NEW.status IS DISTINCT FROM OLD.status
     AND NOT (
       OLD.status = 'draft'
       AND NEW.status = 'cancelled'
     ) THEN
    RAISE EXCEPTION 'stock_issue_status_rpc_only'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_stock_movement_unit_role(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_stock_movement_unit_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_expected_unit_id bigint;
BEGIN
  IF NEW.type IN ('production_consumption', 'production_output') THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.ingredient_units AS ingredient_unit
      JOIN public.units AS unit_row
        ON unit_row.id = ingredient_unit.unit_id
       AND unit_row.tenant_id = ingredient_unit.tenant_id
       AND unit_row.is_active IS TRUE
      WHERE ingredient_unit.tenant_id = NEW.tenant_id
        AND ingredient_unit.ingredient_id = NEW.ingredient_id
        AND ingredient_unit.unit_id = NEW.entry_unit_id
        AND ingredient_unit.is_active IS TRUE
    ) THEN
      RAISE EXCEPTION 'inventory_unit_not_active_for_ingredient'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT CASE
    WHEN NEW.type IN ('grn_receipt', 'grn_amend', 'supplier_return')
      THEN ingredient.receipt_unit_id
    ELSE ingredient.issue_unit_id
  END
  INTO v_expected_unit_id
  FROM public.ingredients AS ingredient
  WHERE ingredient.tenant_id = NEW.tenant_id
    AND ingredient.id = NEW.ingredient_id;

  IF v_expected_unit_id IS NULL
     OR NEW.entry_unit_id IS DISTINCT FROM v_expected_unit_id THEN
    RAISE EXCEPTION 'inventory_unit_role_mismatch:%',
      CASE
        WHEN NEW.type IN ('grn_receipt', 'grn_amend', 'supplier_return')
          THEN 'receipt'
        ELSE 'issue'
      END
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_stocktake_line_parent_mutability(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_stocktake_line_parent_mutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_status text;
  v_current_round smallint;
BEGIN
  SELECT session.status, session.current_round
  INTO v_status, v_current_round
  FROM public.stocktake_sessions AS session
  WHERE session.id = OLD.session_id
    AND session.tenant_id = OLD.tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_status <> 'in_progress' THEN
    RAISE EXCEPTION 'stocktake_session_not_in_progress'
      USING ERRCODE = '22023';
  END IF;
  IF current_user IN ('authenticated', 'anon')
     AND (
       OLD.is_final IS TRUE
       OR OLD.round_no IS DISTINCT FROM v_current_round
     ) THEN
    RAISE EXCEPTION 'stocktake_line_not_current'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_supplier_invoice_gross_contract(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_supplier_invoice_gross_contract() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_line public.supplier_invoice_lines%ROWTYPE;
  v_expected_net numeric(15,2);
BEGIN
  SELECT line.*
  INTO v_line
  FROM public.supplier_invoice_lines AS line
  WHERE line.id = NEW.id;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  v_expected_net := GREATEST(
    pg_catalog.round(
      v_line.quantity * v_line.unit_price,
      2
    ) - v_line.line_discount_amount,
    0::numeric
  );

  IF v_line.unit_price < 0
     OR v_line.line_discount_amount < 0
     OR v_line.line_discount_amount
        > pg_catalog.round(v_line.quantity * v_line.unit_price, 2)
     OR pg_catalog.abs(v_line.line_total - v_expected_net) > 1
     OR v_line.gross_line_total IS NULL
     OR v_line.gross_line_total < 0
     OR v_line.gross_line_total IS DISTINCT FROM v_line.line_total + v_line.vat_amount
     OR v_line.vat_amount < 0
     OR v_line.vat_amount > v_line.gross_line_total
     OR (v_line.vat_rate = 0 AND v_line.vat_amount <> 0)
     OR v_line.vat_rate NOT IN (0, 5, 8, 10) THEN
    RAISE EXCEPTION 'supplier_invoice_gross_contract_invalid'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enqueue_kitchen_completion_print_internal(bigint, bigint[], uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enqueue_kitchen_completion_print_internal(p_branch_id bigint, p_ticket_ids bigint[], p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET join_collapse_limit TO '1'
    SET from_collapse_limit TO '1'
    AS $$
DECLARE
  v_ticket_ids bigint[] := ARRAY[]::bigint[];
  v_requested_count integer := 0;
  v_printed_ticket_count integer := 0;
  v_route record;
  v_payload jsonb;
  v_idempotency text;
  v_job_id bigint;
  v_jobs jsonb := '[]'::jsonb;
BEGIN
  SELECT COALESCE(
    array_agg(DISTINCT ticket_id),
    ARRAY[]::bigint[]
  )
  INTO v_ticket_ids
  FROM unnest(
    COALESCE(p_ticket_ids, ARRAY[]::bigint[])
  ) AS input(ticket_id)
  WHERE ticket_id IS NOT NULL
    AND ticket_id > 0;

  v_requested_count := COALESCE(array_length(v_ticket_ids, 1), 0);

  IF v_requested_count = 0 THEN
    RETURN jsonb_build_object(
      'jobs', v_jobs,
      'requested_ticket_count', 0,
      'printed_ticket_count', 0,
      'skipped_ticket_count', 0
    );
  END IF;

  FOR v_route IN
    WITH routed_items AS (
      SELECT
        ticket.id AS ticket_id,
        ticket.order_id,
        ticket.order_item_id,
        orders.tenant_id,
        orders.branch_id,
        orders.order_number,
        orders.order_type,
        orders.note AS order_note,
        dining_table.number AS table_number,
        COALESCE(profile.full_name, '') AS cashier_name,
        printer.id AS printer_id,
        printer.role AS printer_role,
        (printer.sort_order + 1)::smallint AS slot,
        COALESCE(
          batch.kitchen_ticket_number,
          orders.order_number
        ) AS kitchen_ticket_number,
        COALESCE(batch.send_seq, orders.kitchen_send_count) AS send_seq,
        COALESCE(batch.kind, 'manual') AS send_kind,
        jsonb_build_object(
          'order_item_id', item.id,
          'ticket_id', ticket.id,
          'item_name', item.item_name,
          'variant_name', item.variant_name,
          'quantity', item.quantity,
          'modifiers', item.modifiers,
          'sides', item.sides,
          'note', item.note
        ) AS item_payload
      FROM public.kds_tickets ticket
      JOIN public.order_items item
        ON item.tenant_id = ticket.tenant_id
       AND item.id = ticket.order_item_id
      JOIN public.orders orders
        ON orders.tenant_id = ticket.tenant_id
       AND orders.id = ticket.order_id
      LEFT JOIN public.tables dining_table
        ON dining_table.id = orders.table_id
      LEFT JOIN public.profiles profile
        ON profile.id = orders.created_by
      JOIN public.menu_items menu_item
        ON menu_item.id = item.menu_item_id
      JOIN LATERAL (
        SELECT
          candidate.id,
          candidate.role
        FROM public.printers candidate
        JOIN public.printer_print_types print_type
          ON print_type.printer_id = candidate.id
         AND print_type.tenant_id = candidate.tenant_id
         AND print_type.branch_id = candidate.branch_id
         AND print_type.print_type = 'kitchen_ticket'
        LEFT JOIN public.printer_menu_categories route
          ON route.printer_id = candidate.id
         AND route.tenant_id = candidate.tenant_id
         AND route.branch_id = candidate.branch_id
         AND route.category_id = menu_item.category_id
        WHERE candidate.tenant_id = orders.tenant_id
          AND candidate.branch_id = orders.branch_id
          AND candidate.is_active IS TRUE
          AND (
            route.id IS NOT NULL
            OR NOT EXISTS (
              SELECT 1
              FROM public.printer_menu_categories route_any
              WHERE route_any.tenant_id = orders.tenant_id
                AND route_any.branch_id = orders.branch_id
                AND route_any.category_id = menu_item.category_id
            )
          )
        ORDER BY
          CASE WHEN route.id IS NOT NULL THEN 0 ELSE 1 END,
          candidate.sort_order,
          candidate.id
        LIMIT 1
      ) printer ON true
      LEFT JOIN public.kitchen_send_batches batch
        ON batch.id = ticket.kitchen_send_batch_id
      WHERE ticket.id = ANY(v_ticket_ids)
        AND ticket.branch_id = p_branch_id
        AND item.sent_to_kitchen_at IS NULL
    ),
    grouped_routes AS (
      SELECT
        tenant_id,
        branch_id,
        order_id,
        printer_id,
        printer_role,
        slot,
        kitchen_ticket_number,
        order_number,
        order_type,
        table_number,
        cashier_name,
        send_seq,
        send_kind,
        order_note,
        array_agg(order_item_id ORDER BY order_item_id) AS item_ids,
        array_agg(ticket_id ORDER BY order_item_id) AS ticket_ids,
        jsonb_agg(item_payload ORDER BY order_item_id) AS items
      FROM routed_items
      GROUP BY
        tenant_id,
        branch_id,
        order_id,
        printer_id,
        printer_role,
        slot,
        kitchen_ticket_number,
        order_number,
        order_type,
        table_number,
        cashier_name,
        send_seq,
        send_kind,
        order_note
    )
    SELECT *
    FROM grouped_routes
    ORDER BY order_id, printer_role, printer_id
  LOOP
    v_job_id := NULL;

    v_payload := jsonb_build_object(
      'kind', 'kitchen_ticket',
      'kitchen_ticket_number', v_route.kitchen_ticket_number,
      'source_order_number', v_route.order_number,
      'order_number', v_route.order_number,
      'order_type', v_route.order_type,
      'table_number', v_route.table_number,
      'cashier_name', v_route.cashier_name,
      'send_seq', v_route.send_seq,
      'send_kind', v_route.send_kind,
      'slot', v_route.slot,
      'note', v_route.order_note,
      'order_item_ids', to_jsonb(v_route.item_ids),
      'ticket_ids', to_jsonb(v_route.ticket_ids),
      'items', v_route.items,
      'printed_at', to_char(
        now() AT TIME ZONE 'Asia/Ho_Chi_Minh',
        'YYYY-MM-DD"T"HH24:MI:SS'
      )
    );

    v_idempotency := 'order:' || v_route.order_id::text
      || ':kds-complete:printer:' || v_route.printer_id::text
      || ':tickets:' || md5(array_to_string(v_route.ticket_ids, ','));

    INSERT INTO public.print_jobs (
      tenant_id,
      branch_id,
      printer_id,
      job_type,
      order_id,
      payload,
      idempotency_key,
      created_by
    ) VALUES (
      v_route.tenant_id,
      v_route.branch_id,
      v_route.printer_id,
      'kitchen_ticket',
      v_route.order_id,
      v_payload,
      v_idempotency,
      p_actor
    )
    ON CONFLICT (idempotency_key) DO NOTHING
    RETURNING id INTO v_job_id;

    IF v_job_id IS NULL THEN
      SELECT job.id
      INTO v_job_id
      FROM public.print_jobs job
      WHERE job.idempotency_key = v_idempotency;
    END IF;

    UPDATE public.order_items
    SET sent_to_kitchen_at = COALESCE(sent_to_kitchen_at, now())
    WHERE id = ANY(v_route.item_ids)
      AND sent_to_kitchen_at IS NULL;

    v_printed_ticket_count := v_printed_ticket_count
      + COALESCE(array_length(v_route.ticket_ids, 1), 0);

    v_jobs := v_jobs || jsonb_build_object(
      'printer_id', v_route.printer_id,
      'job_id', v_job_id,
      'item_count', jsonb_array_length(v_route.items),
      'ticket_count', COALESCE(
        array_length(v_route.ticket_ids, 1),
        0
      ),
      'kitchen_ticket_number', v_route.kitchen_ticket_number,
      'send_seq', v_route.send_seq
    );
  END LOOP;

  RETURN jsonb_build_object(
    'jobs', v_jobs,
    'requested_ticket_count', v_requested_count,
    'printed_ticket_count', v_printed_ticket_count,
    'skipped_ticket_count', GREATEST(
      v_requested_count - v_printed_ticket_count,
      0
    )
  );
END;
$$;


--
-- Name: enqueue_kitchen_print_internal(bigint, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enqueue_kitchen_print_internal(p_order_id bigint, p_actor_override uuid DEFAULT NULL::uuid, p_enforce_request_auth boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_request_uid            UUID;
  v_uid                    UUID;
  v_order                  public.orders%ROWTYPE;
  v_table_no               INT;
  v_cashier_name           TEXT;
  v_route                  RECORD;
  v_payload                JSONB;
  v_idempotency            TEXT;
  v_job_id                 BIGINT;
  v_jobs                   JSONB := '[]'::jsonb;
  v_mapped_pending         INT;
  v_null_batch_pending     INT;
  v_fallback_batch_id      BIGINT;
  v_fallback_ticket_number TEXT;
  v_fallback_send_seq      INT;
  v_fallback_kind          TEXT;
  v_ticket_seq             INT;
  v_order_number_clean     TEXT;
  v_order_number_match     TEXT[];
  v_ticket_base            TEXT;
BEGIN
  v_request_uid := auth.uid();

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_enforce_request_auth THEN
    IF v_request_uid IS NULL THEN
      RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
    END IF;

    IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
      RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
    END IF;

    IF NOT public.has_permission_any('pos:send_kitchen') THEN
      RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
    END IF;

    v_uid := v_request_uid;
  ELSE
    v_uid := COALESCE(p_actor_override, v_request_uid, v_order.created_by);
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
    END IF;
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_order.created_by;

  SELECT COUNT(*)
  INTO v_mapped_pending
  FROM public.order_items oi
  JOIN public.menu_items mi ON mi.id = oi.menu_item_id
  JOIN public.printer_menu_categories pmc
    ON pmc.category_id = mi.category_id
   AND pmc.tenant_id = v_order.tenant_id
   AND pmc.branch_id = v_order.branch_id
  WHERE oi.order_id = p_order_id
    AND oi.sent_to_kitchen_at IS NULL;

  IF v_mapped_pending = 0 THEN
    RETURN jsonb_build_object(
      'order_id', p_order_id,
      'send_seq', v_order.kitchen_send_count,
      'jobs', v_jobs
    );
  END IF;

  SELECT COUNT(*)
  INTO v_null_batch_pending
  FROM public.order_items oi
  JOIN public.menu_items mi ON mi.id = oi.menu_item_id
  JOIN public.printer_menu_categories pmc
    ON pmc.category_id = mi.category_id
   AND pmc.tenant_id = v_order.tenant_id
   AND pmc.branch_id = v_order.branch_id
  LEFT JOIN public.kds_tickets kt
    ON kt.tenant_id = v_order.tenant_id
   AND kt.order_item_id = oi.id
  LEFT JOIN public.kitchen_send_batches ksb
    ON ksb.id = kt.kitchen_send_batch_id
  WHERE oi.order_id = p_order_id
    AND oi.sent_to_kitchen_at IS NULL
    AND ksb.id IS NULL;

  IF v_null_batch_pending > 0 THEN
    SELECT ksb.id, ksb.kitchen_ticket_number, ksb.send_seq, ksb.kind
    INTO v_fallback_batch_id, v_fallback_ticket_number, v_fallback_send_seq, v_fallback_kind
    FROM public.order_items oi
    JOIN public.kds_tickets kt
      ON kt.tenant_id = v_order.tenant_id
     AND kt.order_item_id = oi.id
    JOIN public.kitchen_send_batches ksb
      ON ksb.id = kt.kitchen_send_batch_id
    WHERE oi.order_id = p_order_id
      AND oi.sent_to_kitchen_at IS NULL
    ORDER BY ksb.created_at DESC, ksb.id DESC
    LIMIT 1;

    IF v_fallback_batch_id IS NULL THEN
      UPDATE public.orders
         SET kitchen_send_count = kitchen_send_count + 1
       WHERE id = p_order_id
       RETURNING kitchen_send_count INTO v_fallback_send_seq;

      INSERT INTO public.kitchen_daily_counters (
        tenant_id, branch_id, counter_date, last_seq
      )
      VALUES (
        v_order.tenant_id,
        v_order.branch_id,
        (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
        1
      )
      ON CONFLICT (tenant_id, branch_id, counter_date)
      DO UPDATE SET
        last_seq = public.kitchen_daily_counters.last_seq + 1,
        updated_at = now()
      RETURNING last_seq INTO v_ticket_seq;

      v_order_number_clean := regexp_replace(
        btrim(COALESCE(v_order.order_number, '')),
        '^#+',
        ''
      );
      v_order_number_match := regexp_match(
        v_order_number_clean,
        '^(?:TC|MV)-(?:(?:[0-9]{6}|[0-9]{8})-)?([0-9]{1,5})(?:-.+)?$',
        'i'
      );
      v_ticket_base := COALESCE(
        v_order_number_match[1],
        NULLIF(v_order_number_clean, ''),
        p_order_id::TEXT
      );
      v_fallback_ticket_number := '#' || v_ticket_base
        || CASE
             WHEN v_fallback_send_seq > 1
               THEN '-' || v_fallback_send_seq::TEXT
             ELSE ''
           END;
      v_fallback_kind := CASE WHEN v_fallback_send_seq = 1 THEN 'initial' ELSE 'append' END;

      INSERT INTO public.kitchen_send_batches (
        tenant_id, branch_id, order_id, counter_date, ticket_seq,
        kitchen_ticket_number, send_seq, kind, created_by
      )
      VALUES (
        v_order.tenant_id,
        v_order.branch_id,
        p_order_id,
        (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
        v_ticket_seq,
        v_fallback_ticket_number,
        v_fallback_send_seq,
        v_fallback_kind,
        v_uid
      )
      RETURNING id INTO v_fallback_batch_id;
    END IF;

    UPDATE public.kds_tickets kt
       SET kitchen_send_batch_id = v_fallback_batch_id,
           updated_at = now()
      FROM public.order_items oi
      JOIN public.menu_items mi ON mi.id = oi.menu_item_id
      JOIN public.printer_menu_categories pmc
        ON pmc.category_id = mi.category_id
       AND pmc.tenant_id = v_order.tenant_id
       AND pmc.branch_id = v_order.branch_id
     WHERE kt.tenant_id = v_order.tenant_id
       AND kt.order_item_id = oi.id
       AND oi.order_id = p_order_id
       AND oi.sent_to_kitchen_at IS NULL
       AND kt.kitchen_send_batch_id IS NULL;
  END IF;

  FOR v_route IN
    WITH routed_items AS (
      SELECT
        p.id AS printer_id,
        p.role AS printer_role,
        (p.sort_order + 1)::smallint AS slot,
        COALESCE(ksb.id, v_fallback_batch_id) AS batch_id,
        COALESCE(ksb.kitchen_ticket_number, v_fallback_ticket_number) AS kitchen_ticket_number,
        COALESCE(ksb.send_seq, v_fallback_send_seq) AS send_seq,
        COALESCE(ksb.kind, v_fallback_kind) AS send_kind,
        COALESCE(ksb.created_at, now()) AS batch_created_at,
        oi.id AS order_item_id,
        jsonb_build_object(
          'item_name',    oi.item_name,
          'variant_name', oi.variant_name,
          'quantity',     oi.quantity,
          'modifiers',    oi.modifiers,
          'sides',        oi.sides,
          'note',         oi.note
        ) AS item_payload
      FROM public.order_items oi
      JOIN public.menu_items mi ON mi.id = oi.menu_item_id
      JOIN public.printer_menu_categories pmc
        ON pmc.category_id = mi.category_id
       AND pmc.tenant_id = v_order.tenant_id
       AND pmc.branch_id = v_order.branch_id
      JOIN public.printers p
        ON p.id = pmc.printer_id
       AND p.tenant_id = pmc.tenant_id
       AND p.branch_id = pmc.branch_id
       AND p.is_active = TRUE
      JOIN public.printer_print_types ppt
        ON ppt.printer_id = p.id
       AND ppt.tenant_id = p.tenant_id
       AND ppt.branch_id = p.branch_id
       AND ppt.print_type = 'kitchen_ticket'
      LEFT JOIN public.kds_tickets kt
        ON kt.tenant_id = v_order.tenant_id
       AND kt.order_item_id = oi.id
      LEFT JOIN public.kitchen_send_batches ksb
        ON ksb.id = kt.kitchen_send_batch_id
      WHERE oi.order_id = p_order_id
        AND oi.sent_to_kitchen_at IS NULL
    ),
    grouped_routes AS (
      SELECT
        printer_id,
        printer_role,
        slot,
        batch_id,
        kitchen_ticket_number,
        send_seq,
        send_kind,
        batch_created_at,
        array_agg(order_item_id ORDER BY order_item_id) AS item_ids,
        jsonb_agg(item_payload ORDER BY order_item_id) AS items
      FROM routed_items
      GROUP BY
        printer_id,
        printer_role,
        slot,
        batch_id,
        kitchen_ticket_number,
        send_seq,
        send_kind,
        batch_created_at
    )
    SELECT
      gr.*,
      EXISTS (
        SELECT 1
        FROM public.order_items sent_oi
        JOIN public.kds_tickets sent_kt
          ON sent_kt.tenant_id = v_order.tenant_id
         AND sent_kt.order_item_id = sent_oi.id
        WHERE sent_oi.order_id = p_order_id
          AND sent_oi.sent_to_kitchen_at IS NOT NULL
          AND sent_kt.kitchen_send_batch_id = gr.batch_id
      ) AS batch_has_sent_items
    FROM grouped_routes gr
    ORDER BY gr.batch_created_at, gr.printer_role, gr.printer_id
  LOOP
    v_job_id := NULL;

    v_payload := jsonb_build_object(
      'kind',                  'kitchen_ticket',
      'kitchen_ticket_number', v_route.kitchen_ticket_number,
      'source_order_number',   v_order.order_number,
      'order_number',          v_order.order_number,
      'order_type',            v_order.order_type,
      'table_number',          v_table_no,
      'cashier_name',          COALESCE(v_cashier_name, ''),
      'send_seq',              v_route.send_seq,
      'send_kind',             CASE
                                  WHEN v_route.batch_has_sent_items THEN 'append'
                                  ELSE v_route.send_kind
                                END,
      'slot',                  v_route.slot,
      'note',                  v_order.note,
      'items',                 v_route.items,
      'printed_at',            to_char(now() AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                       'YYYY-MM-DD"T"HH24:MI:SS')
    );

    v_idempotency := 'order:' || p_order_id::TEXT
      || ':kitchen:printer:' || v_route.printer_id::TEXT
      || ':batch:' || v_route.batch_id::TEXT
      || ':items:' || md5(array_to_string(v_route.item_ids, ','));

    INSERT INTO public.print_jobs (
      tenant_id, branch_id, printer_id, job_type,
      order_id, payload, idempotency_key, created_by
    )
    VALUES (
      v_order.tenant_id, v_order.branch_id, v_route.printer_id, 'kitchen_ticket',
      p_order_id, v_payload, v_idempotency, v_uid
    )
    ON CONFLICT (idempotency_key) DO NOTHING
    RETURNING id INTO v_job_id;

    IF v_job_id IS NULL THEN
      SELECT id INTO v_job_id
      FROM public.print_jobs
      WHERE idempotency_key = v_idempotency;
    END IF;

    UPDATE public.order_items
       SET sent_to_kitchen_at = now()
     WHERE id = ANY(v_route.item_ids)
       AND sent_to_kitchen_at IS NULL;

    v_jobs := v_jobs || jsonb_build_object(
      'slot', v_route.slot,
      'printer_id', v_route.printer_id,
      'job_id', v_job_id,
      'item_count', jsonb_array_length(v_route.items),
      'kitchen_ticket_number', v_route.kitchen_ticket_number,
      'send_seq', v_route.send_seq
    );
  END LOOP;

  IF jsonb_array_length(v_jobs) = 0 THEN
    RAISE EXCEPTION 'no active kitchen printer for branch %', v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'send_seq', COALESCE(v_fallback_send_seq, v_order.kitchen_send_count),
    'jobs', v_jobs
  );
END;
$_$;


--
-- Name: ensure_grn_draft_after_po_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_grn_draft_after_po_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM private.ensure_grn_draft_for_po(
    NEW.tenant_id,
    NEW.id,
    coalesce(auth.uid(), NEW.created_by),
    pg_catalog.gen_random_uuid()
  );
  RETURN NEW;
END;
$$;


--
-- Name: ensure_grn_draft_for_po(bigint, bigint, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_grn_draft_for_po(p_tenant_id bigint, p_po_id bigint, p_created_by uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_po public.purchase_orders%ROWTYPE;
  v_existing record;
  v_location_id bigint;
  v_grn_id bigint;
  v_grn_number text;
  v_line_count integer;
BEGIN
  SELECT grn.id, grn.grn_number, grn.status
  INTO v_existing
  FROM public.goods_received_notes AS grn
  WHERE grn.tenant_id = p_tenant_id
    AND grn.po_id = p_po_id
    AND grn.status = 'draft'
  ORDER BY grn.id
  LIMIT 1;

  IF FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'grn_id', v_existing.id,
      'grn_number', v_existing.grn_number,
      'status', v_existing.status
    );
  END IF;

  SELECT po.*
  INTO v_po
  FROM public.purchase_orders AS po
  WHERE po.id = p_po_id
    AND po.tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_po.status NOT IN ('sent', 'approved', 'partially_received') THEN
    RAISE EXCEPTION 'purchase_order_not_receivable'
      USING ERRCODE = '23514';
  END IF;

  SELECT location.id
  INTO v_location_id
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = p_tenant_id
    AND location.branch_id = v_po.branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active
    AND location.is_default_receive
  ORDER BY location.id
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'receiving_warehouse_required'
      USING ERRCODE = 'P0002';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.purchase_order_items AS po_item
    LEFT JOIN LATERAL (
      SELECT pg_catalog.sum(grn_item.po_applied_quantity) AS quantity
      FROM public.grn_items AS grn_item
      JOIN public.goods_received_notes AS grn
        ON grn.id = grn_item.grn_id
       AND grn.tenant_id = grn_item.tenant_id
      WHERE grn_item.tenant_id = p_tenant_id
        AND grn_item.purchase_order_item_id = po_item.id
        AND grn.status = 'confirmed'
    ) AS received ON TRUE
    WHERE po_item.po_id = p_po_id
      AND po_item.tenant_id = p_tenant_id
      AND po_item.quantity > coalesce(received.quantity, 0)
  ) THEN
    RAISE EXCEPTION 'purchase_order_fully_received'
      USING ERRCODE = '02000';
  END IF;

  v_grn_number := public.next_inventory_doc_number(p_tenant_id, 'grn');
  PERFORM pg_catalog.set_config(
    'comtammatu.po_first_grn_insert',
    'true',
    TRUE
  );

  INSERT INTO public.goods_received_notes (
    tenant_id,
    branch_id,
    po_id,
    supplier_id,
    grn_number,
    expected_receive_date,
    status,
    created_by,
    location_id,
    creation_idempotency_key
  )
  VALUES (
    p_tenant_id,
    v_po.branch_id,
    v_po.id,
    v_po.supplier_id,
    v_grn_number,
    v_po.expected_delivery_date,
    'draft',
    p_created_by,
    v_location_id,
    p_idempotency_key
  )
  RETURNING id INTO v_grn_id;

  INSERT INTO public.grn_items (
    tenant_id,
    grn_id,
    ingredient_id,
    supplier_id,
    purchase_order_item_id,
    received_quantity,
    rejected_quantity,
    entry_unit_id,
    unit_cost,
    total_cost,
    po_applied_quantity,
    cost_pending,
    provisional_cost_source
  )
  SELECT
    p_tenant_id,
    v_grn_id,
    po_item.ingredient_id,
    v_po.supplier_id,
    po_item.id,
    0,
    0,
    po_item.entry_unit_id,
    CASE
      WHEN stock.avg_unit_cost > 0
        THEN stock.avg_unit_cost * public.inv_to_base(
          po_item.ingredient_id,
          po_item.entry_unit_id,
          1
        )
      WHEN ingredient.unit_cost > 0
        THEN ingredient.unit_cost * public.inv_to_base(
          po_item.ingredient_id,
          po_item.entry_unit_id,
          1
        )
      ELSE 0
    END,
    0,
    0,
    coalesce(stock.avg_unit_cost, 0) <= 0
      AND coalesce(ingredient.unit_cost, 0) <= 0,
    CASE
      WHEN stock.avg_unit_cost > 0 THEN 'wac'
      WHEN ingredient.unit_cost > 0 THEN 'reference'
      ELSE 'pending'
    END
  FROM public.purchase_order_items AS po_item
  JOIN public.ingredients AS ingredient
    ON ingredient.id = po_item.ingredient_id
   AND ingredient.tenant_id = po_item.tenant_id
  LEFT JOIN public.stock_levels AS stock
    ON stock.tenant_id = po_item.tenant_id
   AND stock.branch_id = v_po.branch_id
   AND stock.location_id = v_location_id
   AND stock.ingredient_id = po_item.ingredient_id
  LEFT JOIN LATERAL (
    SELECT pg_catalog.sum(grn_item.po_applied_quantity) AS quantity
    FROM public.grn_items AS grn_item
    JOIN public.goods_received_notes AS grn
      ON grn.id = grn_item.grn_id
     AND grn.tenant_id = grn_item.tenant_id
    WHERE grn_item.tenant_id = p_tenant_id
      AND grn_item.purchase_order_item_id = po_item.id
      AND grn.status = 'confirmed'
  ) AS received ON TRUE
  WHERE po_item.po_id = p_po_id
    AND po_item.tenant_id = p_tenant_id
    AND po_item.quantity > coalesce(received.quantity, 0)
  ORDER BY po_item.id;

  GET DIAGNOSTICS v_line_count = ROW_COUNT;

  RETURN pg_catalog.jsonb_build_object(
    'grn_id', v_grn_id,
    'grn_number', v_grn_number,
    'status', 'draft',
    'line_count', v_line_count
  );
END;
$$;


--
-- Name: ensure_inventory_valuation_account(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_inventory_valuation_account(p_tenant_id bigint, p_branch_id bigint, p_location_id bigint, p_ingredient_id bigint) RETURNS public.inventory_valuation_accounts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_account public.inventory_valuation_accounts%ROWTYPE;
BEGIN
  PERFORM private.lock_inventory_valuation_pool(
    p_tenant_id,
    p_branch_id,
    p_location_id,
    p_ingredient_id
  );

  INSERT INTO public.inventory_valuation_accounts (
    tenant_id,
    branch_id,
    location_id,
    ingredient_id
  )
  VALUES (
    p_tenant_id,
    p_branch_id,
    p_location_id,
    p_ingredient_id
  )
  ON CONFLICT (tenant_id, branch_id, location_id, ingredient_id)
  DO NOTHING;

  SELECT account.*
  INTO v_account
  FROM public.inventory_valuation_accounts AS account
  WHERE account.tenant_id = p_tenant_id
    AND account.branch_id = p_branch_id
    AND account.location_id = p_location_id
    AND account.ingredient_id = p_ingredient_id
  FOR UPDATE;

  RETURN v_account;
END;
$$;


--
-- Name: ensure_sepay_payment_reconciliation(bigint, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_sepay_payment_reconciliation(p_event_id bigint, p_payment_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_event public.webhook_events%ROWTYPE;
  v_bank public.bank_transactions%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_provider_transaction_id text;
  v_event_amount numeric(15,2);
  v_payment_match public.bank_transaction_reconciliation_matches%ROWTYPE;
  v_bank_match public.bank_transaction_reconciliation_matches%ROWTYPE;
  v_inserted integer := 0;
BEGIN
  SELECT *
  INTO v_event
  FROM public.webhook_events event
  WHERE event.id = p_event_id
    AND event.provider = 'sepay'
  FOR UPDATE;

  IF v_event.id IS NULL
    OR v_event.signature_valid IS NOT TRUE
    OR v_event.processing_status <> 'processed'
    OR v_event.error_code IS NOT NULL
    OR v_event.payment_id IS DISTINCT FROM p_payment_id
    OR lower(COALESCE(v_event.payload->>'transferType', '')) <> 'in'
    OR COALESCE(v_event.payload->>'transferAmount', '')
      !~ '^[0-9]+([.][0-9]+)?$'
  THEN
    RETURN jsonb_build_object(
      'status', 'needs_review',
      'code', 'invalid_webhook_evidence'
    );
  END IF;

  v_event_amount := (v_event.payload->>'transferAmount')::numeric;
  v_provider_transaction_id := COALESCE(
    NULLIF(btrim(v_event.payload->>'id'), ''),
    NULLIF(btrim(v_event.request_id), '')
  );

  SELECT *
  INTO v_bank
  FROM public.bank_transactions bank_record
  WHERE bank_record.tenant_id = v_event.tenant_id
    AND bank_record.provider_transaction_id = v_provider_transaction_id
  FOR UPDATE;

  SELECT *
  INTO v_payment
  FROM public.payments payment
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = v_event.tenant_id
  FOR UPDATE;

  IF v_payment.id IS NOT NULL THEN
    SELECT *
    INTO v_order
    FROM public.orders orders
    WHERE orders.id = v_payment.order_id
      AND orders.tenant_id = v_payment.tenant_id
    FOR UPDATE;
  END IF;

  IF v_bank.id IS NULL
    OR v_payment.id IS NULL
    OR v_order.id IS NULL
    OR v_provider_transaction_id IS NULL
    OR v_bank.transfer_type <> 'in'
    OR v_bank.amount <> v_event_amount
    OR v_payment.method <> 'vietqr'
    OR v_payment.status <> 'completed'
    OR v_payment.amount <> v_event_amount
    OR v_event.order_id IS DISTINCT FROM v_order.id
    OR v_order.branch_id IS DISTINCT FROM v_payment.branch_id
  THEN
    INSERT INTO public.audit_logs (
      tenant_id,
      user_id,
      action,
      entity_type,
      entity_id,
      old_data,
      new_data
    ) VALUES (
      v_event.tenant_id,
      auth.uid(),
      'sepay_canonical_reconciliation_needs_review',
      'webhook_event',
      v_event.id,
      NULL,
      jsonb_build_object(
        'code', 'bank_payment_evidence_mismatch',
        'payment_id', p_payment_id,
        'provider_transaction_id', v_provider_transaction_id
      )
    );

    RETURN jsonb_build_object(
      'status', 'needs_review',
      'code', 'bank_payment_evidence_mismatch'
    );
  END IF;

  SELECT *
  INTO v_payment_match
  FROM public.bank_transaction_reconciliation_matches match
  WHERE match.tenant_id = v_event.tenant_id
    AND match.payment_id = v_payment.id
  FOR UPDATE;

  SELECT *
  INTO v_bank_match
  FROM public.bank_transaction_reconciliation_matches match
  WHERE match.tenant_id = v_event.tenant_id
    AND match.bank_transaction_id = v_bank.id
  FOR UPDATE;

  IF v_payment_match.id IS NOT NULL
    AND v_payment_match.bank_transaction_id = v_bank.id
    AND (
      v_bank_match.id IS NULL
      OR v_bank_match.payment_id = v_payment.id
    )
  THEN
    RETURN jsonb_build_object(
      'status', 'matched',
      'bank_transaction_id', v_bank.id,
      'payment_id', v_payment.id,
      'idempotent', true
    );
  END IF;

  IF (
    v_payment_match.id IS NOT NULL
    AND v_payment_match.bank_transaction_id <> v_bank.id
  ) OR (
    v_bank_match.id IS NOT NULL
    AND v_bank_match.payment_id IS DISTINCT FROM v_payment.id
  ) THEN
    INSERT INTO public.audit_logs (
      tenant_id,
      user_id,
      action,
      entity_type,
      entity_id,
      old_data,
      new_data
    ) VALUES (
      v_event.tenant_id,
      auth.uid(),
      'sepay_canonical_reconciliation_needs_review',
      'webhook_event',
      v_event.id,
      NULL,
      jsonb_build_object(
        'code', 'canonical_match_conflict',
        'bank_transaction_id', v_bank.id,
        'payment_id', v_payment.id
      )
    );

    RETURN jsonb_build_object(
      'status', 'needs_review',
      'code', 'canonical_match_conflict'
    );
  END IF;

  INSERT INTO public.bank_transaction_reconciliation_matches (
    tenant_id,
    bank_transaction_id,
    payment_id,
    matched_amount,
    created_by
  ) VALUES (
    v_event.tenant_id,
    v_bank.id,
    v_payment.id,
    v_payment.amount,
    auth.uid()
  )
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF NOT EXISTS (
    SELECT 1
    FROM public.bank_transaction_reconciliation_matches match
    WHERE match.tenant_id = v_event.tenant_id
      AND match.bank_transaction_id = v_bank.id
      AND match.payment_id = v_payment.id
  ) THEN
    RETURN jsonb_build_object(
      'status', 'needs_review',
      'code', 'canonical_match_conflict'
    );
  END IF;

  IF v_inserted = 1 THEN
    INSERT INTO public.audit_logs (
      tenant_id,
      user_id,
      action,
      entity_type,
      entity_id,
      old_data,
      new_data
    ) VALUES (
      v_event.tenant_id,
      auth.uid(),
      'sepay_canonical_reconciliation_match',
      'webhook_event',
      v_event.id,
      NULL,
      jsonb_build_object(
        'bank_transaction_id', v_bank.id,
        'payment_id', v_payment.id,
        'matched_amount', v_payment.amount
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'status', 'matched',
    'bank_transaction_id', v_bank.id,
    'payment_id', v_payment.id,
    'idempotent', v_inserted = 0
  );
END;
$_$;


--
-- Name: entry_unit_matches_roles(bigint, bigint, bigint, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.entry_unit_matches_roles(p_tenant_id bigint, p_ingredient_id bigint, p_entry_unit_id bigint, p_roles text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_roles text[] := string_to_array(p_roles, ',');
  v_receipt_unit_id bigint;
  v_issue_unit_id bigint;
  v_production_unit_id bigint;
BEGIN
  SELECT
    ingredient.receipt_unit_id,
    ingredient.issue_unit_id,
    ingredient.production_unit_id
  INTO
    v_receipt_unit_id,
    v_issue_unit_id,
    v_production_unit_id
  FROM public.ingredients AS ingredient
  WHERE ingredient.tenant_id = p_tenant_id
    AND ingredient.id = p_ingredient_id;

  IF 'receipt' = ANY (v_roles)
     AND v_receipt_unit_id IS NOT NULL
     AND p_entry_unit_id IS NOT DISTINCT FROM v_receipt_unit_id THEN
    RETURN TRUE;
  END IF;

  IF 'issue' = ANY (v_roles)
     AND v_issue_unit_id IS NOT NULL
     AND p_entry_unit_id IS NOT DISTINCT FROM v_issue_unit_id THEN
    RETURN TRUE;
  END IF;

  IF 'production' = ANY (v_roles)
     AND v_production_unit_id IS NOT NULL
     AND p_entry_unit_id IS NOT DISTINCT FROM v_production_unit_id THEN
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


--
-- Name: execute_approve_inventory_count_slip(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_approve_inventory_count_slip(p_slip_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant          BIGINT := public.auth_tenant_id();
  v_uid             UUID   := auth.uid();
  v_slip            public.inventory_count_slips%ROWTYPE;
  v_line            RECORD;
  v_fresh           NUMERIC(15,3);
  v_counted_base    NUMERIC(15,3);
  v_delta           NUMERIC(15,3);
  v_adjusted        INT := 0;
  v_employee_bucket TEXT;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_slip
  FROM public.inventory_count_slips
  WHERE id = p_slip_id AND tenant_id = v_tenant
  FOR UPDATE;

  IF v_slip.id IS NULL THEN
    RAISE EXCEPTION 'slip_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_slip.branch_id, 'inventory:count_approve') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_slip.status = 'approved' THEN
    RETURN jsonb_build_object('success', true, 'slip_id', p_slip_id, 'already_approved', true);
  END IF;

  IF v_slip.status <> 'submitted' THEN
    RAISE EXCEPTION 'slip_not_submitted' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = v_slip.employee_id AND e.profile_id = v_uid
  ) THEN
    RAISE EXCEPTION 'cannot_review_own_slip' USING ERRCODE = '42501';
  END IF;

  FOR v_line IN
    SELECT * FROM public.inventory_count_slip_lines
    WHERE slip_id = p_slip_id AND tenant_id = v_tenant
  LOOP
    SELECT COALESCE(stl.current_quantity, 0) INTO v_fresh
    FROM public.stock_levels stl
    WHERE stl.tenant_id = v_tenant AND stl.branch_id = v_slip.branch_id
      AND stl.location_id = v_slip.location_id AND stl.ingredient_id = v_line.ingredient_id;

    IF NOT FOUND THEN
      v_fresh := 0;
    END IF;

    v_counted_base := public.inv_to_base(v_line.ingredient_id, v_line.entry_unit_id, v_line.counted_quantity);
    v_delta := v_counted_base - v_fresh;

    IF v_delta <> 0 THEN
      INSERT INTO public.stock_movements (
        tenant_id, branch_id, ingredient_id, type, quantity_change,
        reason, created_by, location_id, entry_unit_id, entry_quantity
      ) VALUES (
        v_tenant, v_slip.branch_id, v_line.ingredient_id, 'count_adjustment', v_delta,
        'Count slip #' || p_slip_id::text, v_uid, v_slip.location_id,
        v_line.entry_unit_id, v_line.counted_quantity
      );
      v_adjusted := v_adjusted + 1;
    END IF;
  END LOOP;

  UPDATE public.inventory_count_slips
  SET status = 'approved', reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
  WHERE id = p_slip_id;

  PERFORM public.log_audit(
    'approve'::TEXT,
    'inventory_count_slip'::TEXT,
    p_slip_id,
    jsonb_build_object('status', 'submitted'),
    jsonb_build_object('status', 'approved', 'adjusted_lines', v_adjusted)
  );

  SELECT COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
    INTO v_employee_bucket
    FROM public.employees e
    JOIN public.profiles p ON p.id = e.profile_id AND p.tenant_id = e.tenant_id
    LEFT JOIN public.positions po ON po.id = p.position_id AND po.tenant_id = p.tenant_id
   WHERE e.id = v_slip.employee_id AND e.tenant_id = v_tenant;

  INSERT INTO public.notifications (
    tenant_id, target_branch_id, target_roles, kind, severity, title, body,
    entity_type, entity_id, action_url, meta, dedup_key
  )
  VALUES (
    v_tenant,
    v_slip.branch_id,
    ARRAY[COALESCE(v_employee_bucket, 'unassigned')]::text[],
    'inventory.count_slip_approved',
    'info',
    'Phiếu đếm tồn đã được duyệt',
    'Phiếu đếm tồn của bạn đã được duyệt và điều chỉnh kho.',
    'inventory_count_slip',
    p_slip_id,
    format('/br/%s/stock/count', v_slip.branch_id),
    jsonb_build_object(
      'slip_id', p_slip_id, 'employee_id', v_slip.employee_id,
      'branch_id', v_slip.branch_id, 'result', 'approved', 'adjusted_lines', v_adjusted
    ),
    format('inventory.count_slip:%s:approved', p_slip_id)
  )
  ON CONFLICT (tenant_id, dedup_key) WHERE dedup_key IS NOT NULL
  DO UPDATE SET created_at = EXCLUDED.created_at, expires_at = NULL, meta = EXCLUDED.meta;

  RETURN jsonb_build_object('success', true, 'slip_id', p_slip_id, 'adjusted_lines', v_adjusted);
END;
$$;


--
-- Name: FUNCTION execute_approve_inventory_count_slip(p_slip_id bigint); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.execute_approve_inventory_count_slip(p_slip_id bigint) IS 'Manager approves a submitted count slip: posts count_adjustment movements (delta vs fresh on-hand) and reconciles stock. Branch-scoped, self-approval blocked, idempotent.';


--
-- Name: execute_bulk_import_ingredients(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_bulk_import_ingredients(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_inserted integer := 0;
  v_updated integer := 0;
BEGIN
  IF NOT public.has_permission_any('inventory:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'rows_must_be_non_empty_array' USING ERRCODE = '22023';
  END IF;

  DROP TABLE IF EXISTS pg_temp.bulk_import_ingredient_rows;
  DROP TABLE IF EXISTS pg_temp.bulk_import_ingredient_upserted;

  CREATE TEMP TABLE pg_temp.bulk_import_ingredient_rows ON COMMIT DROP AS
  SELECT
    raw.ordinality::integer AS row_no,
    btrim(raw.value ->> 'name') AS name,
    NULLIF(btrim(COALESCE(raw.value ->> 'sku', '')), '') AS sku,
    btrim(raw.value ->> 'unit') AS unit,
    NULLIF(btrim(COALESCE(raw.value ->> 'category', '')), '') AS category,
    COALESCE(NULLIF(btrim(COALESCE(raw.value ->> 'item_kind', '')), ''), 'raw_material') AS item_kind,
    (raw.value ->> 'unit_cost')::numeric AS unit_cost,
    COALESCE((raw.value ->> 'min_stock_level')::numeric, 0) AS min_stock_level,
    (raw.value ->> 'max_stock_level')::numeric AS max_stock_level,
    (raw.value ->> 'reorder_point')::numeric AS reorder_point,
    COALESCE(NULLIF(btrim(COALESCE(raw.value ->> 'storage_type', '')), ''), 'ambient') AS storage_type,
    (raw.value ->> 'shelf_life_days')::integer AS shelf_life_days
  FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS raw(value, ordinality);

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_ingredient_rows
    WHERE COALESCE(name, '') = '' OR COALESCE(unit, '') = ''
  ) THEN
    RAISE EXCEPTION 'invalid_import_row' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_ingredient_rows
    GROUP BY name
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'duplicate_import_name' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.units (tenant_id, code, name, is_active)
  SELECT DISTINCT v_tenant, unit, unit, true
  FROM pg_temp.bulk_import_ingredient_rows
  WHERE COALESCE(unit, '') <> ''
  ON CONFLICT ON CONSTRAINT units_code_tenant_key DO NOTHING;

  INSERT INTO public.ingredient_categories (tenant_id, name)
  SELECT DISTINCT v_tenant, category
  FROM pg_temp.bulk_import_ingredient_rows
  WHERE category IS NOT NULL
  ON CONFLICT ON CONSTRAINT ingredient_categories_name_tenant_key DO NOTHING;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_ingredient_rows AS rows
    LEFT JOIN public.units AS base_units
      ON base_units.tenant_id = v_tenant
     AND base_units.code = rows.unit
     AND base_units.is_active
    WHERE base_units.id IS NULL
  ) THEN
    RAISE EXCEPTION 'unit_not_found' USING ERRCODE = '23503';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_ingredient_rows AS rows
    LEFT JOIN public.ingredient_categories AS categories
      ON categories.tenant_id = v_tenant
     AND categories.name = rows.category
     AND categories.is_active
    WHERE rows.category IS NOT NULL
      AND categories.id IS NULL
  ) THEN
    RAISE EXCEPTION 'category_not_found' USING ERRCODE = '23503';
  END IF;

  CREATE TEMP TABLE pg_temp.bulk_import_ingredient_upserted ON COMMIT DROP AS
  WITH existing AS (
    SELECT ingredients.name
    FROM public.ingredients
    JOIN pg_temp.bulk_import_ingredient_rows AS rows ON rows.name = ingredients.name
    WHERE ingredients.tenant_id = v_tenant
  ), upserted AS (
    INSERT INTO public.ingredients (
      tenant_id, name, sku, category_id, category, unit_cost, item_kind,
      storage_type, min_stock_level, max_stock_level, reorder_point,
      shelf_life_days, receipt_unit_id, issue_unit_id
    )
    SELECT
      v_tenant, rows.name, rows.sku, categories.id, categories.name,
      rows.unit_cost, rows.item_kind, rows.storage_type, rows.min_stock_level,
      rows.max_stock_level, rows.reorder_point, rows.shelf_life_days,
      base_units.id, base_units.id
    FROM pg_temp.bulk_import_ingredient_rows AS rows
    JOIN public.units AS base_units
      ON base_units.tenant_id = v_tenant
     AND base_units.code = rows.unit
     AND base_units.is_active
    LEFT JOIN public.ingredient_categories AS categories
      ON categories.tenant_id = v_tenant
     AND categories.name = rows.category
     AND categories.is_active
    ON CONFLICT ON CONSTRAINT ingredients_name_tenant_id_key DO UPDATE
    SET sku = EXCLUDED.sku,
        category_id = EXCLUDED.category_id,
        category = EXCLUDED.category,
        unit_cost = EXCLUDED.unit_cost,
        item_kind = EXCLUDED.item_kind,
        storage_type = EXCLUDED.storage_type,
        min_stock_level = EXCLUDED.min_stock_level,
        max_stock_level = EXCLUDED.max_stock_level,
        reorder_point = EXCLUDED.reorder_point,
        shelf_life_days = EXCLUDED.shelf_life_days,
        updated_at = now()
    RETURNING id, name
  )
  SELECT upserted.id, upserted.name, existing.name IS NOT NULL AS existed
  FROM upserted
  LEFT JOIN existing ON existing.name = upserted.name;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_ingredient_upserted AS upserted
    JOIN pg_temp.bulk_import_ingredient_rows AS rows ON rows.name = upserted.name
    JOIN public.units AS import_units
      ON import_units.tenant_id = v_tenant
     AND import_units.code = rows.unit
     AND import_units.is_active
    JOIN public.ingredient_units AS existing_base
      ON existing_base.tenant_id = v_tenant
     AND existing_base.ingredient_id = upserted.id
     AND existing_base.is_base
    WHERE upserted.existed
      AND existing_base.unit_id IS DISTINCT FROM import_units.id
  ) THEN
    RAISE EXCEPTION 'bulk_import_base_unit_change_forbidden' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.ingredient_units (
    tenant_id, ingredient_id, unit_id, to_base_factor, is_base, sort_order
  )
  SELECT v_tenant, upserted.id, base_units.id, 1::numeric, true, 0
  FROM pg_temp.bulk_import_ingredient_rows AS rows
  JOIN pg_temp.bulk_import_ingredient_upserted AS upserted ON upserted.name = rows.name
  JOIN public.units AS base_units
    ON base_units.tenant_id = v_tenant
   AND base_units.code = rows.unit
   AND base_units.is_active
  ON CONFLICT ON CONSTRAINT ingredient_units_ing_unit_key DO UPDATE
  SET to_base_factor = 1,
      is_base = true,
      sort_order = EXCLUDED.sort_order,
      is_active = true;

  SELECT count(*) FILTER (WHERE NOT existed), count(*) FILTER (WHERE existed)
  INTO v_inserted, v_updated
  FROM pg_temp.bulk_import_ingredient_upserted;

  RETURN jsonb_build_object('inserted', v_inserted, 'updated', v_updated);
END;
$$;


--
-- Name: execute_bulk_import_production_recipes(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_bulk_import_production_recipes(p_groups jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_recipes integer := 0;
  v_lines integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_permission_any('inventory:production_create')
    OR public.has_permission_any('inventory:production_confirm')
    OR public.has_permission_any('menu:write')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_groups IS NULL OR jsonb_typeof(p_groups) <> 'array' OR jsonb_array_length(p_groups) = 0 THEN
    RAISE EXCEPTION 'groups_must_be_non_empty_array' USING ERRCODE = '22023';
  END IF;

  DROP TABLE IF EXISTS pg_temp.bulk_import_production_groups;
  DROP TABLE IF EXISTS pg_temp.bulk_import_production_lines;

  CREATE TEMP TABLE pg_temp.bulk_import_production_groups ON COMMIT DROP AS
  SELECT
    raw.ordinality::integer AS group_no,
    (raw.value->>'finished_good_id')::bigint AS finished_good_id,
    (raw.value->>'output_quantity')::numeric AS output_quantity,
    raw.value->'lines' AS lines
  FROM jsonb_array_elements(p_groups) WITH ORDINALITY AS raw(value, ordinality);

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_production_groups
    WHERE finished_good_id IS NULL
      OR output_quantity IS NULL
      OR output_quantity <= 0
      OR output_quantity = 'NaN'::numeric
      OR output_quantity = 'Infinity'::numeric
      OR output_quantity = '-Infinity'::numeric
      OR lines IS NULL
      OR jsonb_typeof(lines) <> 'array'
      OR jsonb_array_length(lines) = 0
  ) THEN
    RAISE EXCEPTION 'invalid_group_shape' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_production_groups
    GROUP BY finished_good_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'duplicate_finished_good' USING ERRCODE = '23505';
  END IF;

  CREATE TEMP TABLE pg_temp.bulk_import_production_lines ON COMMIT DROP AS
  SELECT
    groups.finished_good_id,
    groups.output_quantity,
    raw.ordinality::integer AS line_no,
    (raw.value->>'ingredient_id')::bigint AS ingredient_id,
    (raw.value->>'quantity')::numeric AS quantity,
    NULLIF(raw.value->>'entry_unit_id', '')::bigint AS entry_unit_id,
    NULLIF(btrim(COALESCE(raw.value->>'note', '')), '') AS note
  FROM pg_temp.bulk_import_production_groups groups
  CROSS JOIN LATERAL jsonb_array_elements(groups.lines) WITH ORDINALITY AS raw(value, ordinality);

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_production_lines
    WHERE ingredient_id IS NULL
      OR quantity <= 0
      OR quantity = 'NaN'::numeric
      OR quantity = 'Infinity'::numeric
      OR quantity = '-Infinity'::numeric
  ) THEN
    RAISE EXCEPTION 'invalid_line_shape' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_production_lines
    GROUP BY finished_good_id, ingredient_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'duplicate_ingredient' USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_production_groups groups
    LEFT JOIN public.ingredients finished_goods
      ON finished_goods.id = groups.finished_good_id
      AND finished_goods.tenant_id = v_tenant
      AND finished_goods.item_kind = 'finished_good'
      AND finished_goods.is_active
    WHERE finished_goods.id IS NULL
  ) THEN
    RAISE EXCEPTION 'finished_good_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.bulk_import_production_lines lines
    LEFT JOIN public.ingredients ingredients
      ON ingredients.id = lines.ingredient_id
      AND ingredients.tenant_id = v_tenant
      AND ingredients.item_kind = 'raw_material'
      AND ingredients.is_active
    WHERE ingredients.id IS NULL
  ) THEN
    RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.production_recipes (
    tenant_id,
    finished_good_id,
    ingredient_id,
    quantity,
    entry_unit_id,
    note,
    output_quantity
  )
  SELECT
    v_tenant,
    lines.finished_good_id,
    lines.ingredient_id,
    lines.quantity,
    lines.entry_unit_id,
    lines.note,
    lines.output_quantity
  FROM pg_temp.bulk_import_production_lines lines
  ON CONFLICT (finished_good_id, ingredient_id, tenant_id)
  DO UPDATE SET
    quantity = EXCLUDED.quantity,
    entry_unit_id = EXCLUDED.entry_unit_id,
    note = EXCLUDED.note,
    output_quantity = EXCLUDED.output_quantity;

  DELETE FROM public.production_recipes recipes
  USING pg_temp.bulk_import_production_groups groups
  WHERE recipes.tenant_id = v_tenant
    AND recipes.finished_good_id = groups.finished_good_id
    AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.bulk_import_production_lines lines
      WHERE lines.finished_good_id = recipes.finished_good_id
        AND lines.ingredient_id = recipes.ingredient_id
    );

  SELECT count(*) INTO v_recipes
  FROM pg_temp.bulk_import_production_groups;

  SELECT count(*) INTO v_lines
  FROM pg_temp.bulk_import_production_lines;

  RETURN jsonb_build_object('recipes', v_recipes, 'lines', v_lines);
END;
$$;


--
-- Name: FUNCTION execute_bulk_import_production_recipes(p_groups jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.execute_bulk_import_production_recipes(p_groups jsonb) IS 'Bulk replaces production recipe groups using entry_unit_id as the unit source.';


--
-- Name: execute_confirm_production_run(bigint, numeric, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_confirm_production_run(p_run_id bigint, p_actual_quantity numeric DEFAULT NULL::numeric, p_actual_ingredients jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_run record;
  v_recipe record;
  v_has_recipe boolean := false;
  v_effective_ingredients jsonb;
  v_raw_need_measure numeric(15,3);
  v_raw_need_purchase numeric(15,3);
  v_actual_usage numeric(15,3);
  v_need_map jsonb := '{}'::jsonb;
  v_key text;
  v_need_qty numeric(15,3);
  v_old_q numeric(15,3);
  v_old_wac numeric(15,2);
  v_new_q numeric(15,3);
  v_new_wac numeric(15,2);
  v_output_cost numeric(15,2) := 0;
  v_cost_total numeric(15,2);
  v_out_base numeric(15,3);
  v_out_unit_cost numeric(15,2);
  v_target_location_id bigint;
  v_source_location_id bigint;
  v_shortages jsonb;
  v_raw_entry_unit_id bigint;
  v_raw_entry_to_base_factor numeric(18,12);
  v_raw_entry_unit_code text;
  v_actual_quantity numeric(15,3);
  v_planned_output_base numeric(15,3);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('inventory:production_confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT pr.*, b.branch_kind INTO v_run
  FROM public.production_runs pr
  JOIN public.branches b
    ON b.id = pr.branch_id
   AND b.tenant_id = pr.tenant_id
  WHERE pr.id = p_run_id
    AND pr.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_run_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_run.status NOT IN ('draft', 'in_progress') THEN
    RAISE EXCEPTION 'production_run_not_draft' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission(v_run.branch_id, 'inventory:production_confirm') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.production_recipes pr
    LEFT JOIN public.ingredient_units iu
      ON iu.tenant_id = pr.tenant_id
     AND iu.ingredient_id = pr.ingredient_id
     AND iu.unit_id = pr.entry_unit_id
     AND iu.is_active = TRUE
    LEFT JOIN public.units u
      ON u.id = iu.unit_id
     AND u.tenant_id = iu.tenant_id
     AND u.is_active = TRUE
    WHERE pr.tenant_id = v_tenant
      AND pr.finished_good_id = v_run.finished_good_id
      AND pr.entry_unit_id IS NOT NULL
      AND (iu.id IS NULL OR u.id IS NULL)
  ) THEN
    RAISE EXCEPTION 'production_recipe_unit_mapping_missing:%',
      v_run.finished_good_id
      USING ERRCODE = '23503';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.production_recipes pr
    JOIN public.ingredient_units iu
      ON iu.tenant_id = pr.tenant_id
     AND iu.ingredient_id = pr.ingredient_id
     AND iu.unit_id = pr.entry_unit_id
     AND iu.is_active = TRUE
    WHERE pr.tenant_id = v_tenant
      AND pr.finished_good_id = v_run.finished_good_id
      AND iu.created_at > v_run.created_at
  ) THEN
    RAISE EXCEPTION 'production_run_unit_mapping_review_required:%',
      v_run.id
      USING ERRCODE = 'P0001';
  END IF;

  v_effective_ingredients := COALESCE(
    p_actual_ingredients,
    v_run.ingredients_override
  );

  SELECT il.id INTO v_source_location_id
  FROM public.inventory_locations il
  WHERE il.id = v_run.source_location_id
    AND il.tenant_id = v_tenant
    AND il.branch_id = v_run.branch_id
    AND il.is_active = TRUE
  LIMIT 1;
  IF v_source_location_id IS NULL THEN
    RAISE EXCEPTION 'production_source_location_missing:%', v_run.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  SELECT il.id INTO v_target_location_id
  FROM public.inventory_locations il
  WHERE il.id = v_run.target_location_id
    AND il.tenant_id = v_tenant
    AND il.branch_id = v_run.target_branch_id
    AND il.is_active = TRUE
  LIMIT 1;
  IF v_target_location_id IS NULL THEN
    RAISE EXCEPTION 'production_target_location_missing:%', v_run.target_branch_id
      USING ERRCODE = 'P0002';
  END IF;

  v_actual_quantity := ROUND(
    COALESCE(p_actual_quantity, v_run.planned_quantity),
    3
  );

  IF v_run.entry_unit_id IS NOT NULL THEN
    v_planned_output_base := ROUND(
      public.inv_to_base(
        v_run.finished_good_id,
        v_run.entry_unit_id,
        v_run.planned_quantity
      ),
      3
    );
  ELSE
    v_planned_output_base := v_run.planned_quantity;
  END IF;

  FOR v_recipe IN
    SELECT
      pr.ingredient_id,
      pr.quantity,
      pr.output_quantity,
      pr.entry_unit_id,
      COALESCE(sl.avg_unit_cost, ing.unit_cost, 0) AS raw_unit_cost
    FROM public.production_recipes pr
    JOIN public.ingredients ing
      ON ing.id = pr.ingredient_id
     AND ing.tenant_id = pr.tenant_id
    LEFT JOIN public.stock_levels sl
      ON sl.tenant_id = v_tenant
     AND sl.branch_id = v_run.branch_id
     AND sl.location_id = v_source_location_id
     AND sl.ingredient_id = pr.ingredient_id
    WHERE pr.tenant_id = v_tenant
      AND pr.finished_good_id = v_run.finished_good_id
  LOOP
    v_has_recipe := true;
    v_raw_need_measure :=
      (v_planned_output_base * v_recipe.quantity) /
      v_recipe.output_quantity;

    IF v_effective_ingredients IS NOT NULL THEN
      v_actual_usage := NULL;
      SELECT (elem ->> 'actual_quantity')::numeric(15,3)
      INTO v_actual_usage
      FROM jsonb_array_elements(v_effective_ingredients) elem
      WHERE (elem ->> 'ingredient_id')::bigint = v_recipe.ingredient_id;

      IF v_actual_usage IS NOT NULL THEN
        v_raw_need_measure := v_actual_usage;
      END IF;
    END IF;

    IF v_recipe.entry_unit_id IS NOT NULL THEN
      v_raw_need_purchase := ROUND(
        public.inv_to_base(
          v_recipe.ingredient_id,
          v_recipe.entry_unit_id,
          v_raw_need_measure
        ),
        3
      );
    ELSE
      v_raw_need_purchase := ROUND(v_raw_need_measure, 3);
    END IF;

    v_key := v_recipe.ingredient_id::text;
    v_need_map := jsonb_set(
      v_need_map,
      ARRAY[v_key],
      to_jsonb(
        COALESCE((v_need_map ->> v_key)::numeric, 0) +
        v_raw_need_purchase
      ),
      TRUE
    );
    v_output_cost := v_output_cost +
      (v_raw_need_purchase * COALESCE(v_recipe.raw_unit_cost, 0));
  END LOOP;

  IF NOT v_has_recipe THEN
    RAISE EXCEPTION 'production_recipe_missing' USING ERRCODE = 'P0001';
  END IF;

  WITH shortages AS (
    SELECT
      (need.ingredient_id)::bigint AS ingredient_id,
      ing.name AS ingredient_name,
      (
        SELECT u.name
        FROM public.ingredient_units iu
        JOIN public.units u ON u.id = iu.unit_id
        WHERE iu.ingredient_id = ing.id
          AND iu.is_base = TRUE
        LIMIT 1
      ) AS unit,
      ROUND((need.need_qty)::numeric, 3) AS needed,
      ROUND(COALESCE(sl.current_quantity, 0)::numeric, 3) AS on_hand
    FROM jsonb_each_text(v_need_map) AS need(ingredient_id, need_qty)
    JOIN public.ingredients ing
      ON ing.id = (need.ingredient_id)::bigint
    LEFT JOIN public.stock_levels sl
      ON sl.tenant_id = v_tenant
     AND sl.branch_id = v_run.branch_id
     AND sl.location_id = v_source_location_id
     AND sl.ingredient_id = (need.ingredient_id)::bigint
    WHERE COALESCE(sl.current_quantity, 0) < (need.need_qty)::numeric
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(s)), '[]'::jsonb)
  INTO v_shortages
  FROM shortages s;

  IF jsonb_array_length(v_shortages) > 0 THEN
    RAISE EXCEPTION 'insufficient_stock_for_production'
      USING ERRCODE = 'P0001', DETAIL = v_shortages::text;
  END IF;

  v_cost_total := v_output_cost;

  FOR v_key, v_need_qty IN
    SELECT key, value::numeric(15,3)
    FROM jsonb_each_text(v_need_map)
  LOOP
    IF v_need_qty = 0 THEN
      CONTINUE;
    END IF;

    SELECT sl.current_quantity, sl.avg_unit_cost
    INTO v_old_q, v_old_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_run.branch_id
      AND sl.location_id = v_source_location_id
      AND sl.ingredient_id = v_key::bigint;
    IF NOT FOUND THEN
      v_old_q := 0;
      v_old_wac := 0;
    END IF;

    SELECT
      ingredient.production_unit_id,
      ingredient_unit.to_base_factor,
      unit_row.code
    INTO
      v_raw_entry_unit_id,
      v_raw_entry_to_base_factor,
      v_raw_entry_unit_code
    FROM public.ingredients AS ingredient
    JOIN public.ingredient_units AS ingredient_unit
      ON ingredient_unit.tenant_id = ingredient.tenant_id
     AND ingredient_unit.ingredient_id = ingredient.id
     AND ingredient_unit.unit_id = ingredient.production_unit_id
     AND ingredient_unit.is_active IS TRUE
    JOIN public.units AS unit_row
      ON unit_row.id = ingredient_unit.unit_id
     AND unit_row.tenant_id = ingredient_unit.tenant_id
     AND unit_row.is_active IS TRUE
    WHERE ingredient.tenant_id = v_tenant
      AND ingredient.id = v_key::bigint;

    IF v_raw_entry_unit_id IS NULL
       OR v_raw_entry_to_base_factor IS NULL
       OR v_raw_entry_to_base_factor <= 0 THEN
      RAISE EXCEPTION 'entry_unit_not_found:%', v_key::bigint
        USING ERRCODE = '23503';
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      quantity_change,
      reason,
      created_by,
      production_run_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity,
      entry_to_base_factor,
      entry_unit_code
    ) VALUES (
      v_tenant,
      v_run.branch_id,
      v_key::bigint,
      'production_consumption',
      -v_need_qty,
      'Production ' || v_run.production_number,
      v_uid,
      p_run_id,
      COALESCE(v_old_wac, 0),
      v_source_location_id,
      v_raw_entry_unit_id,
      v_need_qty / v_raw_entry_to_base_factor,
      v_raw_entry_to_base_factor,
      v_raw_entry_unit_code
    );
  END LOOP;

  IF v_run.entry_unit_id IS NOT NULL THEN
    v_out_base := public.inv_to_base(
      v_run.finished_good_id,
      v_run.entry_unit_id,
      v_actual_quantity
    );
  ELSE
    v_out_base := v_actual_quantity;
  END IF;

  v_out_unit_cost := CASE
    WHEN v_out_base <> 0 THEN ROUND(v_cost_total / v_out_base, 2)
    ELSE 0
  END;

  SELECT sl.current_quantity, sl.avg_unit_cost
  INTO v_old_q, v_old_wac
  FROM public.stock_levels sl
  WHERE sl.tenant_id = v_tenant
    AND sl.branch_id = v_run.target_branch_id
    AND sl.location_id = v_target_location_id
    AND sl.ingredient_id = v_run.finished_good_id;
  IF NOT FOUND THEN
    v_old_q := 0;
    v_old_wac := 0;
  END IF;

  INSERT INTO public.stock_movements (
    tenant_id,
    branch_id,
    ingredient_id,
    type,
    quantity_change,
    reason,
    created_by,
    production_run_id,
    unit_cost,
    location_id,
    entry_unit_id,
    entry_quantity
  ) VALUES (
    v_tenant,
    v_run.target_branch_id,
    v_run.finished_good_id,
    'production_output',
    v_out_base,
    'Production ' || v_run.production_number,
    v_uid,
    p_run_id,
    v_out_unit_cost,
    v_target_location_id,
    v_run.entry_unit_id,
    v_actual_quantity
  );

  v_new_q := COALESCE(v_old_q, 0) + v_out_base;
  v_new_wac := CASE
    WHEN v_new_q > 0 THEN
      (
        COALESCE(v_old_q, 0) * COALESCE(v_old_wac, 0) +
        v_cost_total
      ) / v_new_q
    ELSE v_out_unit_cost
  END;

  UPDATE public.stock_levels sl
  SET avg_unit_cost = v_new_wac,
      updated_at = now()
  WHERE sl.tenant_id = v_tenant
    AND sl.branch_id = v_run.target_branch_id
    AND sl.location_id = v_target_location_id
    AND sl.ingredient_id = v_run.finished_good_id;

  UPDATE public.ingredients
  SET unit_cost = v_out_unit_cost,
      updated_at = now()
  WHERE id = v_run.finished_good_id
    AND tenant_id = v_tenant;

  UPDATE public.production_runs
  SET status = 'completed',
      actual_quantity = v_actual_quantity,
      completed_at = now(),
      updated_at = now(),
      ingredients_override = v_effective_ingredients
  WHERE id = p_run_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'production_run_id', p_run_id,
    'status', 'completed',
    'actual_quantity', v_actual_quantity,
    'output_quantity_base', v_out_base,
    'unit_cost', v_out_unit_cost
  );
END;
$$;


--
-- Name: execute_create_waste_entry(bigint, bigint, jsonb, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_create_waste_entry(p_branch_id bigint, p_location_id bigint, p_items jsonb, p_source_type text DEFAULT 'manual'::text, p_source_ref jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid UUID := auth.uid(); v_tenant BIGINT; v_location RECORD; v_shift_key TEXT; v_issue_id BIGINT;
  v_issue_no TEXT; v_item JSONB; v_photos TEXT[]; v_created INT := 0; v_needs_appr BOOLEAN := false;
  v_entry_unit_id BIGINT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:writeoff') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  SELECT tenant_id INTO v_tenant FROM public.branches WHERE id = p_branch_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002'; END IF;
  SELECT tenant_id, branch_id INTO v_location FROM public.inventory_locations WHERE id = p_location_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'location_scope_mismatch' USING ERRCODE = '42501';
  END IF;
  IF v_location.tenant_id <> v_tenant OR v_location.branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'location_scope_mismatch' USING ERRCODE = '42501';
  END IF;
  v_shift_key := public.inventory_shift_key(p_branch_id, now());
  v_issue_no := public.next_inventory_doc_number(v_tenant, 'waste');
  INSERT INTO public.stock_issues (tenant_id, branch_id, issue_number, issue_type, status, notes,
    issued_at, created_by, source_location_id, approval_status, shift_key, source_type, source_ref)
  VALUES (v_tenant, p_branch_id, v_issue_no, 'writeoff', 'draft', p_notes,
    now(), v_uid, p_location_id, 'not_required', v_shift_key, COALESCE(p_source_type, 'manual'), p_source_ref)
  RETURNING id INTO v_issue_id;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_entry_unit_id := NULLIF(v_item->>'entry_unit_id','')::BIGINT;
    IF v_entry_unit_id IS NULL THEN
      RAISE EXCEPTION 'entry_unit_required' USING ERRCODE = '22023';
    END IF;
    v_photos := CASE WHEN v_item ? 'photo_urls'
                     THEN ARRAY(SELECT jsonb_array_elements_text(v_item->'photo_urls'))
                     ELSE ARRAY[]::TEXT[] END;
    INSERT INTO public.stock_issue_items (tenant_id, issue_id, ingredient_id, quantity, entry_unit_id, unit_cost,
      reason_code, photo_urls, reason)
    VALUES (
      v_tenant,
      v_issue_id,
      (v_item->>'ingredient_id')::BIGINT,
      (v_item->>'quantity')::NUMERIC,
      v_entry_unit_id,
      NULLIF(v_item->>'unit_cost','')::NUMERIC,
      v_item->>'reason_code',
      v_photos,
      v_item->>'note'
    );
    v_created := v_created + 1;
  END LOOP;
  SELECT bool_or(approval_required) INTO v_needs_appr FROM public.stock_issue_items WHERE issue_id = v_issue_id;
  IF NOT COALESCE(v_needs_appr, false) THEN
    PERFORM public._post_writeoff_movements(v_issue_id);
  END IF;
  RETURN jsonb_build_object('issue_id', v_issue_id, 'issue_number', v_issue_no,
    'shift_key', v_shift_key, 'items_created', v_created, 'requires_approval', COALESCE(v_needs_appr, false));
END; $$;


--
-- Name: execute_post_writeoff_movements(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_post_writeoff_movements(p_issue_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid    uuid   := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_issue  RECORD;
  v_item   RECORD;
  v_loc    RECORD;
  v_sl_q   numeric(15, 3);
  v_wac    numeric(15, 2);
  v_qty_base numeric(15, 3);
BEGIN
  SELECT * INTO v_issue
    FROM public.stock_issues
   WHERE id = p_issue_id AND tenant_id = v_tenant
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_issue.issue_type <> 'writeoff' THEN
    RAISE EXCEPTION 'not_a_writeoff' USING ERRCODE = '22023';
  END IF;
  IF v_issue.status <> 'draft' THEN
    RAISE EXCEPTION 'issue_not_draft' USING ERRCODE = '22023';
  END IF;
  IF v_issue.source_location_id IS NULL THEN
    RAISE EXCEPTION 'issue_source_location_missing' USING ERRCODE = '23502';
  END IF;

  SELECT id, branch_id INTO v_loc
    FROM public.inventory_locations
   WHERE id = v_issue.source_location_id AND tenant_id = v_tenant AND is_active = TRUE;
  IF NOT FOUND OR v_loc.branch_id <> v_issue.branch_id THEN
    RAISE EXCEPTION 'issue_source_location_invalid' USING ERRCODE = '23514';
  END IF;

  FOR v_item IN
    SELECT * FROM public.stock_issue_items
     WHERE issue_id = p_issue_id AND tenant_id = v_tenant
  LOOP
    v_qty_base := public.inv_to_base(v_item.ingredient_id, v_item.entry_unit_id, v_item.quantity);

    SELECT sl.current_quantity, sl.avg_unit_cost INTO v_sl_q, v_wac
      FROM public.stock_levels sl
     WHERE sl.tenant_id = v_tenant
       AND sl.branch_id = v_issue.branch_id
       AND sl.location_id = v_issue.source_location_id
       AND sl.ingredient_id = v_item.ingredient_id
     FOR UPDATE;

    IF NOT FOUND OR v_wac IS NULL THEN
      RAISE EXCEPTION 'wac_not_ready_for_%', v_item.ingredient_id USING ERRCODE = '22023';
    END IF;
    IF v_sl_q < v_qty_base THEN
      RAISE EXCEPTION 'insufficient_stock_for_%', v_item.ingredient_id USING ERRCODE = '22023';
    END IF;

    UPDATE public.stock_issue_items SET unit_cost = v_wac
     WHERE id = v_item.id AND tenant_id = v_tenant;

    IF v_issue.approval_status <> 'approved' THEN
      PERFORM 1 FROM public.stock_issue_items
       WHERE id = v_item.id AND tenant_id = v_tenant AND approval_required = TRUE;
      IF FOUND THEN
        RAISE EXCEPTION 'writeoff_requires_approval_for_%', v_item.ingredient_id USING ERRCODE = '42501';
      END IF;
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, movement_subtype,
      quantity_change, unit_cost, reason, created_by, issue_id, location_id,
      entry_unit_id, entry_quantity
    ) VALUES (
      v_tenant, v_issue.branch_id, v_item.ingredient_id, 'consumption', 'writeoff',
      -v_qty_base, v_wac, COALESCE(v_item.reason, v_issue.notes),
      v_uid, p_issue_id, v_issue.source_location_id,
      v_item.entry_unit_id, v_item.quantity
    );
  END LOOP;

  UPDATE public.stock_issues SET status = 'confirmed'
   WHERE id = p_issue_id AND tenant_id = v_tenant;
END;
$$;


--
-- Name: execute_stock_transfer_confirm_receive(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_stock_transfer_confirm_receive(p_transfer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_role         TEXT := public.auth_role();
  v_branch_claim BIGINT := public.auth_branch_id();
  v_tr           RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tr
  FROM public.stock_transfers
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_tr.from_branch_id = v_tr.to_branch_id THEN
    RAISE EXCEPTION 'intra_branch_transfer_has_no_receive_step' USING ERRCODE = '22023';
  END IF;

  IF v_role IN ('branch_manager', 'branch_manager', 'branch_manager')
     AND (v_branch_claim IS NULL OR v_branch_claim <> v_tr.to_branch_id) THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_tr.to_branch_id, 'inventory:transfer_receive') THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF v_tr.status <> 'in_transit' THEN
    RAISE EXCEPTION 'transfer_not_in_transit' USING ERRCODE = '22023';
  END IF;

  UPDATE public.stock_transfers
  SET status = 'confirmed_receive',
      receive_started_at = COALESCE(receive_started_at, now()),
      updated_at = now()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object('transfer_id', p_transfer_id, 'status', 'confirmed_receive');
END;
$$;


--
-- Name: execute_stock_transfer_mark_in_transit(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_stock_transfer_mark_in_transit(p_transfer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_role         TEXT := public.auth_role();
  v_branch_claim BIGINT := public.auth_branch_id();
  v_tr           RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tr
  FROM public.stock_transfers
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_tr.from_branch_id = v_tr.to_branch_id THEN
    RAISE EXCEPTION 'intra_branch_transfer_has_no_transit' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'branch_manager' THEN
    RAISE EXCEPTION 'branch_manager_inter_site_ship_forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('branch_manager', 'branch_manager')
     AND (v_branch_claim IS NULL OR v_branch_claim <> v_tr.from_branch_id) THEN
    RAISE EXCEPTION 'forbidden_transfer_ship' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_tr.from_branch_id, 'inventory:transfer_ship') THEN
    RAISE EXCEPTION 'forbidden_transfer_ship' USING ERRCODE = '42501';
  END IF;

  IF v_tr.status <> 'confirmed_ship' THEN
    RAISE EXCEPTION 'transfer_wrong_state' USING ERRCODE = '22023';
  END IF;

  UPDATE public.stock_transfers
  SET status = 'in_transit',
      updated_at = now()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object('transfer_id', p_transfer_id, 'status', 'in_transit');
END;
$$;


--
-- Name: execute_stock_transfer_receive(bigint, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_stock_transfer_receive(p_transfer_id bigint, p_items jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_role         TEXT := public.auth_role();
  v_branch_claim BIGINT := public.auth_branch_id();
  v_tr           RECORD;
  v_line         RECORD;
  v_recv         NUMERIC(15,3);
  v_recv_base    NUMERIC(15,3);
  v_note         TEXT;
  v_cost         NUMERIC(15,2);
  v_old_q        NUMERIC(15,3);
  v_old_wac      NUMERIC(15,2);
  v_new_q        NUMERIC(15,3);
  v_new_wac      NUMERIC(15,2);
  v_key          TEXT;
  v_to_loc       RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tr
  FROM public.stock_transfers
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_tr.from_branch_id = v_tr.to_branch_id THEN
    RAISE EXCEPTION 'intra_branch_transfer_already_atomic' USING ERRCODE = '22023';
  END IF;

  IF v_role IN ('branch_manager', 'branch_manager', 'branch_manager')
     AND (v_branch_claim IS NULL OR v_branch_claim <> v_tr.to_branch_id) THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_tr.to_branch_id, 'inventory:transfer_receive') THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF v_tr.status <> 'confirmed_receive' THEN
    RAISE EXCEPTION 'transfer_not_in_confirmed_receive' USING ERRCODE = '22023';
  END IF;

  IF v_tr.to_location_id IS NULL THEN
    RAISE EXCEPTION 'transfer_to_location_missing' USING ERRCODE = '23502';
  END IF;

  SELECT id, branch_id
  INTO v_to_loc
  FROM public.inventory_locations
  WHERE id = v_tr.to_location_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  IF NOT FOUND OR v_to_loc.branch_id <> v_tr.to_branch_id THEN
    RAISE EXCEPTION 'transfer_to_location_invalid' USING ERRCODE = '23514';
  END IF;

  FOR v_line IN
    SELECT * FROM public.stock_transfer_items
    WHERE transfer_id = p_transfer_id
      AND tenant_id = v_tenant
  LOOP
    v_recv := v_line.quantity;
    v_note := NULL;

    IF p_items IS NOT NULL THEN
      v_key := v_line.ingredient_id::TEXT;
      IF (p_items ? v_key) THEN
        IF jsonb_typeof(p_items -> v_key) = 'object' THEN
          v_recv := ((p_items -> v_key) ->> 'qty')::NUMERIC;
          v_note := (p_items -> v_key) ->> 'note';
        ELSE
          v_recv := (p_items ->> v_key)::NUMERIC;
        END IF;
      END IF;
    END IF;

    IF v_recv < 0 OR v_recv > v_line.quantity THEN
      RAISE EXCEPTION 'invalid_receive_qty:%', v_line.ingredient_id USING ERRCODE = '22023';
    END IF;

    IF v_recv <= 0 THEN
      UPDATE public.stock_transfer_items
      SET quantity_received = 0,
          receive_note = v_note
      WHERE id = v_line.id;
      CONTINUE;
    END IF;

    v_recv_base := public.inv_to_base(v_line.ingredient_id, v_line.entry_unit_id, v_recv)::NUMERIC(15,3);
    v_cost := COALESCE(v_line.unit_cost_at_ship, 0);

    SELECT sl.current_quantity, sl.avg_unit_cost
    INTO v_old_q, v_old_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_tr.to_branch_id
      AND sl.location_id = v_tr.to_location_id
      AND sl.ingredient_id = v_line.ingredient_id
    FOR UPDATE;

    IF NOT FOUND THEN
      v_old_q := 0;
      v_old_wac := NULL;
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, transfer_id, unit_cost, location_id,
      entry_unit_id, entry_quantity
    ) VALUES (
      v_tenant, v_tr.to_branch_id, v_line.ingredient_id, 'transfer_in', v_recv_base,
      'Transfer ' || v_tr.transfer_number, v_uid, p_transfer_id, v_cost,
      v_tr.to_location_id,
      v_line.entry_unit_id, v_recv
    );

    v_new_q := COALESCE(v_old_q, 0) + v_recv_base;
    IF v_new_q > 0 THEN
      v_new_wac := (
        COALESCE(v_old_q, 0) * COALESCE(v_old_wac, 0) + v_recv_base * v_cost
      ) / v_new_q;
    ELSE
      v_new_wac := v_cost;
    END IF;

    UPDATE public.stock_levels sl
    SET avg_unit_cost = v_new_wac,
        updated_at = now()
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_tr.to_branch_id
      AND sl.location_id = v_tr.to_location_id
      AND sl.ingredient_id = v_line.ingredient_id;

    UPDATE public.stock_transfer_items
    SET quantity_received = v_recv,
        receive_note = v_note
    WHERE id = v_line.id;
  END LOOP;

  UPDATE public.stock_transfers
  SET status = 'received',
      received_at = now(),
      updated_at = now()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object(
    'transfer_id', p_transfer_id,
    'status', 'received'
  );
END;
$$;


--
-- Name: execute_update_ingredient_thresholds_bulk(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_update_ingredient_thresholds_bulk(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id      BIGINT := public.auth_tenant_id();
  v_user_id        UUID   := auth.uid();
  v_count          INTEGER := 0;
  v_request_count  INTEGER := 0;
  v_delta          JSONB := '[]'::jsonb;
  v_row            RECORD;
  v_payload_item   JSONB;
  v_id             BIGINT;
  v_min            NUMERIC(15,3);
  v_max            NUMERIC(15,3);
  v_reorder        NUMERIC(15,3);
  v_before         JSONB;
  v_after          JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'thresholds.bulk: anonymous caller'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'thresholds.bulk: missing tenant_id claim'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF jsonb_typeof(p_payload) <> 'array' THEN
    RAISE EXCEPTION 'thresholds.bulk: payload must be array'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  v_request_count := jsonb_array_length(p_payload);
  IF v_request_count = 0 THEN
    RETURN jsonb_build_object('updated', 0);
  END IF;
  IF v_request_count > 500 THEN
    RAISE EXCEPTION 'thresholds.bulk: max 500 items per call (got %)',
      v_request_count
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  FOR v_payload_item IN
    SELECT * FROM jsonb_array_elements(p_payload)
  LOOP
    v_id := (v_payload_item->>'id')::BIGINT;
    IF v_id IS NULL OR v_id <= 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: invalid id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;

    v_min := NULLIF(v_payload_item->>'min_stock_level', '')::NUMERIC(15,3);
    v_max := NULLIF(v_payload_item->>'max_stock_level', '')::NUMERIC(15,3);
    v_reorder := NULLIF(v_payload_item->>'reorder_point', '')::NUMERIC(15,3);

    IF v_min IS NOT NULL AND v_min < 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: min < 0 for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_max IS NOT NULL AND v_max < 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: max < 0 for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_reorder IS NOT NULL AND v_reorder < 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: reorder < 0 for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_min IS NOT NULL AND v_reorder IS NOT NULL AND v_min > v_reorder THEN
      RAISE EXCEPTION 'thresholds.bulk: min > reorder for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_reorder IS NOT NULL AND v_max IS NOT NULL AND v_reorder > v_max THEN
      RAISE EXCEPTION 'thresholds.bulk: reorder > max for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_min IS NOT NULL AND v_max IS NOT NULL AND v_min > v_max THEN
      RAISE EXCEPTION 'thresholds.bulk: min > max for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;

    SELECT id, min_stock_level, max_stock_level, reorder_point
      INTO v_row
      FROM public.ingredients
     WHERE id = v_id
       AND tenant_id = v_tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'thresholds.bulk: ingredient % not in tenant scope', v_id
        USING ERRCODE = 'no_data_found';
    END IF;

    v_before := jsonb_build_object(
      'min_stock_level', v_row.min_stock_level,
      'max_stock_level', v_row.max_stock_level,
      'reorder_point',   v_row.reorder_point
    );
    v_after := jsonb_build_object(
      'min_stock_level', COALESCE(v_min, v_row.min_stock_level),
      'max_stock_level', CASE
        WHEN v_payload_item ? 'max_stock_level' THEN v_max
        ELSE v_row.max_stock_level
      END,
      'reorder_point', CASE
        WHEN v_payload_item ? 'reorder_point' THEN v_reorder
        ELSE v_row.reorder_point
      END
    );

    IF v_before = v_after THEN
      CONTINUE;
    END IF;

    UPDATE public.ingredients
       SET min_stock_level = (v_after->>'min_stock_level')::NUMERIC(15,3),
           max_stock_level = NULLIF(v_after->>'max_stock_level', '')::NUMERIC(15,3),
           reorder_point   = NULLIF(v_after->>'reorder_point', '')::NUMERIC(15,3),
           updated_at      = now()
     WHERE id = v_id
       AND tenant_id = v_tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'thresholds.bulk: write blocked for id % (RLS or revoked)', v_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    v_count := v_count + 1;
    v_delta := v_delta || jsonb_build_object(
      'id',     v_id,
      'before', v_before,
      'after',  v_after
    );
  END LOOP;

  IF v_count > 0 THEN
    PERFORM public.log_audit(
      'inventory.thresholds.bulk_update',
      'ingredient',
      NULL,
      NULL,
      jsonb_build_object('updated', v_count, 'items', v_delta)
    );
  END IF;

  RETURN jsonb_build_object(
    'updated', v_count,
    'requested', v_request_count
  );
END;
$$;


--
-- Name: FUNCTION execute_update_ingredient_thresholds_bulk(p_payload jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.execute_update_ingredient_thresholds_bulk(p_payload jsonb) IS 'Bulk-update min/max/reorder on ingredients within the callers tenant. Validates min <= reorder <= max per row, skips no-ops, raises on RLS denial, and writes one audit_logs row capturing the full delta. Sprint 2 PP3-A.';


--
-- Name: execute_upsert_production_recipe_lines(bigint, jsonb, numeric, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.execute_upsert_production_recipe_lines(p_finished_good_id bigint, p_lines jsonb, p_output_quantity numeric, p_old_finished_good_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_kept bigint[] := ARRAY[]::bigint[];
  v_line jsonb;
  v_ingredient_id bigint;
  v_entry_unit_id bigint;
  v_quantity numeric;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_permission_any('inventory:production_create')
    OR public.has_permission_any('inventory:production_confirm')
    OR public.has_permission_any('menu:write')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_output_quantity IS NULL
     OR p_output_quantity <= 0
     OR p_output_quantity = 'NaN'::numeric
     OR p_output_quantity = 'Infinity'::numeric
     OR p_output_quantity = '-Infinity'::numeric THEN
    RAISE EXCEPTION 'output_quantity_invalid' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.ingredients i
    WHERE i.id = p_finished_good_id
      AND i.tenant_id = v_tenant
      AND i.item_kind = 'finished_good'
      AND i.is_active = true
  ) THEN
    RAISE EXCEPTION 'finished_good_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'lines_must_be_array' USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'lines_must_not_be_empty' USING ERRCODE = '22023';
  END IF;

  IF p_old_finished_good_id IS NOT NULL AND p_old_finished_good_id <> p_finished_good_id THEN
    DELETE FROM public.production_recipes pr
    WHERE pr.tenant_id = v_tenant
      AND pr.finished_good_id = p_old_finished_good_id;
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    IF (v_line->>'ingredient_id') IS NULL OR (v_line->>'quantity') IS NULL THEN
      RAISE EXCEPTION 'invalid_line_shape' USING ERRCODE = '22023';
    END IF;

    v_ingredient_id := (v_line->>'ingredient_id')::bigint;
    v_entry_unit_id := NULLIF(v_line->>'entry_unit_id', '')::bigint;
    v_quantity := (v_line->>'quantity')::numeric;

    IF v_quantity <= 0
       OR v_quantity = 'NaN'::numeric
       OR v_quantity = 'Infinity'::numeric
       OR v_quantity = '-Infinity'::numeric THEN
      RAISE EXCEPTION 'invalid_line_quantity' USING ERRCODE = '22023';
    END IF;

    IF v_ingredient_id = ANY(v_kept) THEN
      RAISE EXCEPTION 'duplicate_ingredient' USING ERRCODE = '23505';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.ingredients i
      WHERE i.id = v_ingredient_id
        AND i.tenant_id = v_tenant
        AND i.item_kind = 'raw_material'
        AND i.is_active = true
    ) THEN
      RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO public.production_recipes (
      tenant_id,
      finished_good_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      note,
      output_quantity
    )
    VALUES (
      v_tenant,
      p_finished_good_id,
      v_ingredient_id,
      v_quantity,
      v_entry_unit_id,
      NULLIF(v_line->>'note', ''),
      p_output_quantity
    )
    ON CONFLICT (finished_good_id, ingredient_id, tenant_id)
    DO UPDATE SET
      quantity = EXCLUDED.quantity,
      entry_unit_id = EXCLUDED.entry_unit_id,
      note = EXCLUDED.note,
      output_quantity = EXCLUDED.output_quantity;

    v_kept := v_kept || v_ingredient_id;
  END LOOP;

  DELETE FROM public.production_recipes pr
  WHERE pr.tenant_id = v_tenant
    AND pr.finished_good_id = p_finished_good_id
    AND NOT (pr.ingredient_id = ANY(v_kept));

  RETURN jsonb_build_object(
    'finished_good_id', p_finished_good_id,
    'kept_count', COALESCE(array_length(v_kept, 1), 0),
    'output_quantity', p_output_quantity
  );
END;
$$;


--
-- Name: expire_grn_pending_notification(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expire_grn_pending_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_grn_id bigint := OLD.id;
  v_po_id bigint := OLD.po_id;
  v_tenant_id bigint := OLD.tenant_id;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status = 'draft' THEN
    RETURN NULL;
  END IF;

  UPDATE public.notifications
  SET expires_at = now()
  WHERE tenant_id = v_tenant_id
    AND (
      expires_at IS NULL
      OR expires_at > now()
    )
    AND (
      (
        kind = 'workflow.grn_pending'
        AND entity_type = 'grn'
        AND entity_id = v_grn_id
      )
      OR (
        v_po_id IS NOT NULL
        AND kind IN ('workflow.po_approved', 'workflow.po_sent')
        AND entity_type = 'purchase_order'
        AND entity_id = v_po_id
      )
    );

  RETURN NULL;
END;
$$;


--
-- Name: expire_stock_request_notifications(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expire_stock_request_notifications() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request_id bigint := OLD.id;
  v_tenant_id bigint := OLD.tenant_id;
BEGIN
  IF TG_OP = 'DELETE'
     OR NEW.status IN ('fulfilled', 'closed', 'cancelled') THEN
    UPDATE public.notifications
    SET expires_at = now()
    WHERE tenant_id = v_tenant_id
      AND kind = 'inventory.stock_request_submitted'
      AND entity_type = 'stock_request'
      AND entity_id = v_request_id
      AND (expires_at IS NULL OR expires_at > now());
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: expire_stock_request_source_notification(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expire_stock_request_source_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request_id bigint := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.request_id
    ELSE NEW.request_id
  END;
  v_tenant_id bigint := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.tenant_id
    ELSE NEW.tenant_id
  END;
  v_site_kind text := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.fulfill_site_kind
    ELSE NEW.fulfill_site_kind
  END;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.stock_request_items AS item
    JOIN public.stock_requests AS request
      ON request.id = item.request_id
     AND request.tenant_id = item.tenant_id
    WHERE item.tenant_id = v_tenant_id
      AND item.request_id = v_request_id
      AND item.fulfill_site_kind = v_site_kind
      AND item.status = 'pending'
      AND request.status = 'submitted'
  ) THEN
    UPDATE public.notifications
    SET expires_at = NULL,
        action_url = format(
          '/inventory/transfers?requestId=%s',
          v_request_id
        )
    WHERE tenant_id = v_tenant_id
      AND kind = 'inventory.stock_request_submitted'
      AND entity_type = 'stock_request'
      AND entity_id = v_request_id
      AND meta ->> 'fulfill_site_kind' = v_site_kind;
  ELSE
    UPDATE public.notifications
    SET expires_at = now()
    WHERE tenant_id = v_tenant_id
      AND kind = 'inventory.stock_request_submitted'
      AND entity_type = 'stock_request'
      AND entity_id = v_request_id
      AND meta ->> 'fulfill_site_kind' = v_site_kind
      AND (expires_at IS NULL OR expires_at > now());
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: finalize_issued_replacement(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finalize_issued_replacement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_old public.tax_invoices%ROWTYPE;
BEGIN
  IF NEW.status <> 'issued' OR OLD.status = 'issued' OR NEW.replaced_for IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_old
  FROM public.tax_invoices
  WHERE id = NEW.replaced_for
  FOR UPDATE;
  IF v_old.id IS NULL OR v_old.status <> 'issued' OR v_old.replaced_by IS NOT NULL THEN
    RAISE EXCEPTION 'replacement_original_state_invalid'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.tax_invoices
  SET status = 'replaced',
      replaced_by = NEW.id,
      cancelled_at = now(),
      updated_at = now()
  WHERE id = v_old.id;

  INSERT INTO public.tax_invoice_events (
    tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note
  ) VALUES (
    v_old.id, v_old.tenant_id, 'issued', 'replaced', auth.uid(),
    jsonb_build_object('replaced_by', NEW.id),
    'Replacement confirmed by provider'
  );
  RETURN NEW;
END;
$$;


--
-- Name: finance_scope(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finance_scope(p_uid uuid, p_key text DEFAULT 'finance:view'::text) RETURNS TABLE(has_tenant_scope boolean, branch_ids bigint[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH owner_scope AS (
    SELECT 1
    FROM public.profiles pr
    JOIN public.positions po ON po.id = pr.position_id
    WHERE pr.id = p_uid
      AND po.code = 'owner'
  ),
  active_permissions AS (
    SELECT sp.branch_id
    FROM public.staff_permissions sp
    WHERE sp.user_id = p_uid
      AND sp.permission_key = p_key
      AND sp.valid_from <= now()
      AND (sp.valid_until IS NULL OR sp.valid_until > now())
  )
  SELECT
    (
      EXISTS (SELECT 1 FROM owner_scope)
      OR EXISTS (
        SELECT 1
        FROM active_permissions ap
        WHERE ap.branch_id IS NULL
      )
    ) AS has_tenant_scope,
    COALESCE(
      (
        SELECT array_agg(DISTINCT ap.branch_id)
        FROM active_permissions ap
        WHERE ap.branch_id IS NOT NULL
      ),
      ARRAY[]::BIGINT[]
    ) AS branch_ids;
$$;


--
-- Name: grn_physical_qc_is_valid(bigint, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.grn_physical_qc_is_valid(p_tenant_id bigint, p_grn_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT NOT EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.tenant_id = p_tenant_id
      AND item.grn_id = p_grn_id
      AND (
        item.received_quantity IN (
          'NaN'::numeric,
          'Infinity'::numeric,
          '-Infinity'::numeric
        )
        OR item.rejected_quantity IN (
          'NaN'::numeric,
          'Infinity'::numeric,
          '-Infinity'::numeric
        )
        OR item.rejected_quantity < 0
        OR item.rejected_quantity > item.received_quantity
        OR (
          item.rejected_quantity > 0
          AND (
            NULLIF(pg_catalog.btrim(item.rejection_reason), '') IS NULL
            OR NOT private.grn_rejection_photo_exists(
              item.tenant_id,
              item.grn_id,
              item.id,
              item.rejected_photo_url
            )
          )
        )
      )
  );
$$;


--
-- Name: grn_rejection_photo_exists(bigint, bigint, bigint, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.grn_rejection_photo_exists(p_tenant_id bigint, p_grn_id bigint, p_grn_line_id bigint, p_photo_url text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_url text := btrim(coalesce(p_photo_url, ''));
  v_marker constant text :=
    '/storage/v1/object/public/inventory-attachments/';
  v_marker_position integer;
  v_object_name text;
  v_prefix text;
  v_relative_name text;
  v_line_prefix text;
  v_issuer text := COALESCE(auth.jwt() ->> 'iss', '');
  v_expected_origin text;
BEGIN
  IF p_tenant_id IS NULL
     OR p_grn_id IS NULL
     OR p_grn_line_id IS NULL
     OR v_url !~*
       '^https?://[^/?#]+/storage/v1/object/public/inventory-attachments/' THEN
    RETURN FALSE;
  END IF;

  IF v_issuer ~ '^https://[^/?#]+/auth/v1/?$' THEN
    v_expected_origin := pg_catalog.regexp_replace(
      v_issuer,
      '/auth/v1/?$',
      ''
    );
    IF v_url NOT LIKE v_expected_origin || v_marker || '%' THEN
      RETURN FALSE;
    END IF;
  END IF;

  v_marker_position := strpos(v_url, v_marker);
  IF v_marker_position = 0 THEN
    RETURN FALSE;
  END IF;

  v_object_name := substring(
    v_url
    FROM v_marker_position + char_length(v_marker)
  );
  v_prefix := p_tenant_id::text
    || '/grn/'
    || p_grn_id::text
    || '/rejected/';
  v_line_prefix := p_grn_line_id::text || '/';

  IF v_object_name NOT LIKE v_prefix || '%'
     OR v_object_name !~ '^[A-Za-z0-9._/-]+$'
     OR v_object_name LIKE '%//%'
     OR v_object_name ~ '(^|/)\.\.?(/|$)' THEN
    RETURN FALSE;
  END IF;

  v_relative_name := substring(
    v_object_name
    FROM char_length(v_prefix) + 1
  );
  IF v_relative_name NOT LIKE v_line_prefix || '%'
     OR substring(
       v_relative_name
       FROM char_length(v_line_prefix) + 1
     ) !~* '^[A-Za-z0-9][A-Za-z0-9._-]*\.(jpe?g|png|webp|heic)$'
     OR NOT EXISTS (
       SELECT 1
       FROM public.grn_items AS item
       WHERE item.id = p_grn_line_id
         AND item.tenant_id = p_tenant_id
         AND item.grn_id = p_grn_id
     ) THEN
    RETURN FALSE;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM storage.objects AS object
    WHERE object.bucket_id = 'inventory-attachments'
      AND object.name = v_object_name
      AND pg_catalog.lower(
        COALESCE(object.metadata ->> 'mimetype', '')
      ) IN (
        'image/jpeg',
        'image/png',
        'image/webp',
        'image/heic'
      )
  );
END;
$_$;


--
-- Name: guard_authenticated_payment_update(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_authenticated_payment_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_review jsonb;
BEGIN
  IF current_user NOT IN ('anon', 'authenticated') THEN
    RETURN NEW;
  END IF;

  IF auth.uid() IS NULL
    OR OLD.tenant_id IS DISTINCT FROM public.auth_tenant_id()
  THEN
    RAISE EXCEPTION 'payment_direct_update_forbidden' USING ERRCODE = '42501';
  END IF;

  IF OLD.status = 'pending'
    AND NEW.status = 'pending'
    AND OLD.method IN ('momo', 'vietqr')
    AND NEW.method IS NOT DISTINCT FROM OLD.method
    AND NULLIF(btrim(OLD.provider_ref), '') IS NOT NULL
    AND NEW.provider_ref IS NOT DISTINCT FROM OLD.provider_ref
    AND jsonb_typeof(NEW.provider_data) = 'object'
    AND NULLIF(btrim(NEW.provider_data ->> 'providerRef'), '')
      IS NOT DISTINCT FROM NULLIF(btrim(OLD.provider_ref), '')
    AND NOT (NEW.provider_data ?| ARRAY[
      'bankWebhookReview',
      'source',
      'invoicePayload',
      'momoFailure'
    ])
    AND (
      OLD.method <> 'momo'
      OR (
        NULLIF(btrim(NEW.provider_data ->> 'qrCodeUrl'), '') IS NOT NULL
        AND NULLIF(btrim(NEW.provider_data ->> 'requestId'), '') IS NOT NULL
        AND NULLIF(btrim(NEW.provider_data ->> 'momoOrderId'), '')
          IS NOT DISTINCT FROM NULLIF(btrim(OLD.provider_ref), '')
      )
    )
    AND to_jsonb(NEW) - 'provider_data' - 'updated_at'
      = to_jsonb(OLD) - 'provider_data' - 'updated_at'
  THEN
    RETURN NEW;
  END IF;

  v_review := NEW.provider_data -> 'bankWebhookReview';
  IF OLD.status = 'completed'
    AND NEW.status = 'completed'
    AND OLD.method = 'vietqr'
    AND NEW.method = 'vietqr'
    AND public.auth_role() = 'owner'
    AND jsonb_typeof(NEW.provider_data) = 'object'
    AND COALESCE(NEW.provider_data, '{}'::jsonb) - 'bankWebhookReview'
      = COALESCE(OLD.provider_data, '{}'::jsonb) - 'bankWebhookReview'
    AND jsonb_typeof(v_review) = 'object'
    AND v_review ->> 'status' IN ('reviewing', 'resolved', 'ignored')
    AND NULLIF(v_review ->> 'reviewedAt', '') IS NOT NULL
    AND v_review ->> 'reviewedBy' = auth.uid()::text
    AND to_jsonb(NEW) - 'provider_data' - 'updated_at'
      = to_jsonb(OLD) - 'provider_data' - 'updated_at'
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'payment_direct_update_forbidden' USING ERRCODE = '42501';
END;
$$;


--
-- Name: guard_bank_payment_reconciliation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_bank_payment_reconciliation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_bank public.bank_transactions%ROWTYPE;
  v_payment public.payments%ROWTYPE;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_reconciliation_matches existing
    WHERE existing.tenant_id = NEW.tenant_id
      AND existing.bank_transaction_id = NEW.bank_transaction_id
      AND existing.id IS DISTINCT FROM NEW.id
      AND (
        NEW.payment_id IS NOT NULL
        OR existing.payment_id IS NOT NULL
      )
  ) THEN
    RAISE EXCEPTION 'bank_payment_reconciliation_conflict'
      USING ERRCODE = '23505';
  END IF;

  SELECT *
  INTO v_bank
  FROM public.bank_transactions bank_record
  WHERE bank_record.id = NEW.bank_transaction_id
    AND bank_record.tenant_id = NEW.tenant_id;

  IF NEW.payment_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT *
  INTO v_payment
  FROM public.payments payment
  WHERE payment.id = NEW.payment_id
    AND payment.tenant_id = NEW.tenant_id;

  IF v_bank.id IS NULL
    OR v_payment.id IS NULL
    OR v_bank.transfer_type <> 'in'
    OR v_payment.method <> 'vietqr'
    OR v_payment.status <> 'completed'
    OR v_bank.amount <> v_payment.amount
    OR NEW.matched_amount <> v_payment.amount
  THEN
    RAISE EXCEPTION 'invalid_bank_payment_reconciliation'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


