--
-- Name: _compute_vat_breakdown(bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compute_vat_breakdown(p_order_ids bigint[]) RETURNS TABLE(vat_rate numeric, line_gross numeric, line_subtotal numeric, line_vat numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH order_items_sum AS (
    SELECT
      oi.order_id,
      SUM(oi.subtotal) AS items_sum
    FROM public.order_items oi
    WHERE oi.order_id = ANY(p_order_ids)
      AND oi.status <> 'cancelled'
    GROUP BY oi.order_id
  ),
  scaled AS (
    SELECT
      oi.vat_rate,
      (oi.subtotal * (o.total_amount / NULLIF(ois.items_sum, 0))) AS gross
    FROM public.order_items oi
    JOIN public.orders o            ON o.id = oi.order_id
    JOIN order_items_sum ois        ON ois.order_id = oi.order_id
    WHERE oi.order_id = ANY(p_order_ids)
      AND oi.status <> 'cancelled'
      AND ois.items_sum > 0
  ),
  by_rate AS (
    SELECT
      scaled.vat_rate,
      SUM(scaled.gross)::numeric(15,2) AS line_gross
    FROM scaled
    GROUP BY scaled.vat_rate
  )
  SELECT
    by_rate.vat_rate,
    by_rate.line_gross,
    (by_rate.line_gross / (1 + by_rate.vat_rate / 100))::numeric(15,2) AS line_subtotal,
    (by_rate.line_gross
       - (by_rate.line_gross / (1 + by_rate.vat_rate / 100))::numeric(15,2)
    )::numeric(15,2) AS line_vat
  FROM by_rate
  ORDER BY by_rate.vat_rate;
$$;


--
-- Name: FUNCTION _compute_vat_breakdown(p_order_ids bigint[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._compute_vat_breakdown(p_order_ids bigint[]) IS 'Per-line VAT aggregation across input orders. Mirrors apps/web/app/finance/actions.ts:128-186. Scale absorbs order-level discount. Returns 1 row per VAT rate present.';


--
-- Name: _post_writeoff_movements(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._post_writeoff_movements(p_issue_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  PERFORM issue.id
  FROM public.stock_issues AS issue
  JOIN public.inventory_locations AS location
    ON location.id = issue.source_location_id
   AND location.tenant_id = issue.tenant_id
   AND location.branch_id = issue.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  JOIN public.branches AS branch
    ON branch.id = issue.branch_id
   AND branch.tenant_id = issue.tenant_id
   AND branch.is_active IS TRUE
  WHERE issue.id = p_issue_id
    AND issue.tenant_id = v_tenant
  FOR UPDATE OF issue, location;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_source_location_invalid'
      USING ERRCODE = '23514';
  END IF;

  PERFORM private.execute_post_writeoff_movements(p_issue_id);
END;
$$;


--
-- Name: accept_supplier_invoice_discrepancy(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_supplier_invoice_discrepancy(p_invoice_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_invoice public.supplier_invoices%ROWTYPE;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_match') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_reason IS NULL
     OR char_length(btrim(p_reason)) < 5
     OR char_length(btrim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'discrepancy_reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_invoice
  FROM public.supplier_invoices
  WHERE id = p_invoice_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_invoice.invoice_kind <> 'goods'
     OR v_invoice.matching_status <> 'discrepancy' THEN
    RAISE EXCEPTION 'invoice_not_discrepant' USING ERRCODE = '23514';
  END IF;

  UPDATE public.supplier_invoices
  SET matching_status = 'matched',
      discrepancy_accepted_by = v_uid,
      discrepancy_accepted_at = pg_catalog.now(),
      discrepancy_reason = btrim(p_reason),
      matching_reason_code = 'goods_difference_accepted',
      matching_notes = pg_catalog.concat_ws(
        E'\n',
        NULLIF(btrim(matching_notes), ''),
        'Chấp nhận chênh lệch: ' || btrim(p_reason)
      ),
      updated_at = pg_catalog.now()
  WHERE id = p_invoice_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'supplier_invoice.discrepancy_accepted',
    'supplier_invoice',
    p_invoice_id,
    pg_catalog.jsonb_build_object(
      'matching_status', v_invoice.matching_status,
      'difference_amount', v_invoice.matching_difference_amount
    ),
    pg_catalog.jsonb_build_object(
      'matching_status', 'matched',
      'reason', btrim(p_reason)
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'invoice_id', p_invoice_id,
    'matching_status', 'matched',
    'reason', 'goods_difference_accepted',
    'difference_amount', v_invoice.matching_difference_amount
  );
END;
$$;


--
-- Name: acquire_zone_lock(bigint, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_zone_lock(p_session_id bigint, p_zone_id text, p_ttl_seconds integer DEFAULT 1800) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_branch bigint;
  v_existing record;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_ttl_seconds <= 0 OR p_ttl_seconds > 7200 THEN
    RAISE EXCEPTION 'ttl_seconds must be in (0, 7200]'
      USING ERRCODE = '22023';
  END IF;

  SELECT session.branch_id
  INTO v_branch
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_branch,
    'inventory:stocktake_create'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.stocktake_zone_locks
  WHERE tenant_id = v_tenant
    AND session_id = p_session_id
    AND zone_id = p_zone_id
    AND expires_at <= now();

  INSERT INTO public.stocktake_zone_locks (
    tenant_id,
    session_id,
    zone_id,
    locked_by,
    acquired_at,
    last_heartbeat_at,
    expires_at
  )
  VALUES (
    v_tenant,
    p_session_id,
    p_zone_id,
    v_uid,
    now(),
    now(),
    now() + make_interval(secs => p_ttl_seconds)
  )
  ON CONFLICT (session_id, zone_id) DO UPDATE
  SET locked_by = CASE
        WHEN public.stocktake_zone_locks.locked_by = v_uid
          THEN v_uid
        ELSE public.stocktake_zone_locks.locked_by
      END,
      acquired_at = CASE
        WHEN public.stocktake_zone_locks.locked_by = v_uid
          THEN now()
        ELSE public.stocktake_zone_locks.acquired_at
      END,
      last_heartbeat_at = CASE
        WHEN public.stocktake_zone_locks.locked_by = v_uid
          THEN now()
        ELSE public.stocktake_zone_locks.last_heartbeat_at
      END,
      expires_at = CASE
        WHEN public.stocktake_zone_locks.locked_by = v_uid
          THEN now() + make_interval(secs => p_ttl_seconds)
        ELSE public.stocktake_zone_locks.expires_at
      END
  WHERE public.stocktake_zone_locks.tenant_id = v_tenant
    AND public.stocktake_zone_locks.locked_by = v_uid;

  SELECT lock.*
  INTO v_existing
  FROM public.stocktake_zone_locks AS lock
  WHERE lock.tenant_id = v_tenant
    AND lock.session_id = p_session_id
    AND lock.zone_id = p_zone_id;

  RETURN jsonb_build_object(
    'acquired',
    v_existing.locked_by = v_uid,
    'locked_by',
    v_existing.locked_by,
    'expires_at',
    v_existing.expires_at,
    'acquired_at',
    v_existing.acquired_at
  );
END;
$$;


--
-- Name: activate_inventory_valuation_cutover(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_inventory_valuation_cutover(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RETURN public.prepare_inventory_valuation_cutover(p_idempotency_key);
END;
$$;


--
-- Name: activate_invoice_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_invoice_profile() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor_id uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_tenant public.tenants%ROWTYPE;
  v_profile public.invoice_profiles%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'invoice_profile_activation_forbidden'
      USING ERRCODE = '42501';
  END IF;

  SELECT tenant.* INTO v_tenant
  FROM public.tenants tenant
  WHERE tenant.id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_profile_tenant_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  IF NULLIF(btrim(v_tenant.legal_name), '') IS NULL
    OR NULLIF(btrim(v_tenant.tax_code), '') IS NULL
    OR v_tenant.tax_code !~ '^[0-9]{10}(-[0-9]{3})?$'
    OR NULLIF(btrim(v_tenant.legal_address), '') IS NULL
    OR NULLIF(btrim(v_tenant.representative), '') IS NULL THEN
    RAISE EXCEPTION 'invoice_profile_legal_identity_incomplete'
      USING ERRCODE = '23514';
  END IF;

  SELECT profile.* INTO v_profile
  FROM public.invoice_profiles profile
  WHERE profile.tenant_id = v_tenant_id
    AND profile.status = 'active'
  FOR UPDATE;

  IF FOUND THEN
    IF v_profile.seller_tax_code IS DISTINCT FROM v_tenant.tax_code THEN
      RAISE EXCEPTION 'invoice_profile_seller_tax_code_mismatch'
        USING ERRCODE = '23514';
    END IF;
    RETURN v_profile.id;
  END IF;

  SELECT profile.* INTO v_profile
  FROM public.invoice_profiles profile
  WHERE profile.tenant_id = v_tenant_id
    AND profile.status = 'draft'
  ORDER BY profile.version DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_profile_draft_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.invoice_profiles
  SET seller_tax_code = v_tenant.tax_code,
      status = 'active',
      valid_from = now(),
      created_by = COALESCE(created_by, v_actor_id)
  WHERE id = v_profile.id
  RETURNING * INTO v_profile;

  RETURN v_profile.id;
END;
$_$;


--
-- Name: add_menu_item_stock_exception(bigint, bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_menu_item_stock_exception(p_branch_id bigint, p_menu_item_id bigint, p_extra_portions integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_role text := public.auth_role();
  v_branch bigint := public.auth_branch_id();
  v_uid uuid := auth.uid();
  v_location_id bigint;
  v_branch_kind text;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_line record;
  v_movement_count integer := 0;
  v_stock_capacity integer;
BEGIN
  IF v_tenant_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_role NOT IN ('owner', 'branch_manager') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_role = 'branch_manager'
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_branch_id IS NULL OR p_menu_item_id IS NULL THEN
    RAISE EXCEPTION 'invalid_replenishment_target'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_extra_portions IS NULL OR p_extra_portions NOT IN (1, 2) THEN
    RAISE EXCEPTION 'extra_portions_range' USING ERRCODE = '22023';
  END IF;
  IF length(v_reason) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT branch.branch_kind, location.id
  INTO v_branch_kind, v_location_id
  FROM public.branches AS branch
  LEFT JOIN LATERAL (
    SELECT warehouse.id
    FROM public.inventory_locations AS warehouse
    WHERE warehouse.tenant_id = branch.tenant_id
      AND warehouse.branch_id = branch.id
      AND warehouse.location_kind = 'warehouse'
      AND warehouse.is_active IS TRUE
    LIMIT 1
  ) AS location ON TRUE
  WHERE branch.tenant_id = v_tenant_id
    AND branch.id = p_branch_id
    AND branch.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_branch_kind IS DISTINCT FROM 'branch' THEN
    RAISE EXCEPTION 'branch_site_required' USING ERRCODE = '22023';
  END IF;
  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'branch_warehouse_required'
      USING ERRCODE = 'not_null_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.menu_items AS menu_item
    WHERE menu_item.tenant_id = v_tenant_id
      AND menu_item.id = p_menu_item_id
      AND menu_item.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'menu_item_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.recipes AS recipe
    WHERE recipe.tenant_id = v_tenant_id
      AND recipe.menu_item_id = p_menu_item_id
  ) THEN
    RAISE EXCEPTION 'menu_recipe_required' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.recipes AS recipe
    LEFT JOIN public.ingredients AS ingredient
      ON ingredient.tenant_id = recipe.tenant_id
     AND ingredient.id = recipe.ingredient_id
     AND ingredient.is_active IS TRUE
    WHERE recipe.tenant_id = v_tenant_id
      AND recipe.menu_item_id = p_menu_item_id
      AND ingredient.id IS NULL
  ) THEN
    RAISE EXCEPTION 'recipe_ingredient_inactive'
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.recipes AS recipe
    WHERE recipe.tenant_id = v_tenant_id
      AND recipe.menu_item_id = p_menu_item_id
      AND recipe.entry_unit_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.ingredient_units AS ingredient_unit
        WHERE ingredient_unit.tenant_id = v_tenant_id
          AND ingredient_unit.ingredient_id = recipe.ingredient_id
          AND ingredient_unit.unit_id = recipe.entry_unit_id
          AND ingredient_unit.is_active IS TRUE
      )
  ) THEN
    RAISE EXCEPTION 'recipe_unit_config_required'
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.recipes AS recipe
    WHERE recipe.tenant_id = v_tenant_id
      AND recipe.menu_item_id = p_menu_item_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.ingredient_units AS ingredient_unit
        JOIN public.units AS unit
          ON unit.tenant_id = ingredient_unit.tenant_id
         AND unit.id = ingredient_unit.unit_id
        WHERE ingredient_unit.tenant_id = v_tenant_id
          AND ingredient_unit.ingredient_id = recipe.ingredient_id
          AND ingredient_unit.is_base IS TRUE
          AND ingredient_unit.is_active IS TRUE
          AND unit.is_active IS TRUE
      )
  ) THEN
    RAISE EXCEPTION 'entry_unit_not_found'
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  FOR v_line IN
    SELECT
      recipe.ingredient_id,
      base_unit.unit_id AS entry_unit_id,
      round(sum(public.inv_to_base_for_tenant(
        v_tenant_id,
        recipe.ingredient_id,
        recipe.entry_unit_id,
        p_extra_portions::numeric
          * recipe.quantity
          / recipe.yield_factor
      )), 3)::numeric(15,3) AS quantity_change
    FROM public.recipes AS recipe
    JOIN LATERAL (
      SELECT ingredient_unit.unit_id
      FROM public.ingredient_units AS ingredient_unit
      JOIN public.units AS unit
        ON unit.tenant_id = ingredient_unit.tenant_id
       AND unit.id = ingredient_unit.unit_id
      WHERE ingredient_unit.tenant_id = v_tenant_id
        AND ingredient_unit.ingredient_id = recipe.ingredient_id
        AND ingredient_unit.is_base IS TRUE
        AND ingredient_unit.is_active IS TRUE
        AND unit.is_active IS TRUE
      ORDER BY ingredient_unit.sort_order, ingredient_unit.id
      LIMIT 1
    ) AS base_unit ON TRUE
    WHERE recipe.tenant_id = v_tenant_id
      AND recipe.menu_item_id = p_menu_item_id
    GROUP BY recipe.ingredient_id, base_unit.unit_id
    HAVING round(sum(public.inv_to_base_for_tenant(
      v_tenant_id,
      recipe.ingredient_id,
      recipe.entry_unit_id,
      p_extra_portions::numeric
        * recipe.quantity
        / recipe.yield_factor
    )), 3) > 0
    ORDER BY recipe.ingredient_id
  LOOP
    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      quantity_change,
      reason,
      created_by,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    VALUES (
      v_tenant_id,
      p_branch_id,
      v_line.ingredient_id,
      'adjustment',
      v_line.quantity_change,
      'Menu-Limits stock exception +'
        || p_extra_portions::text
        || ': '
        || v_reason,
      v_uid,
      v_location_id,
      v_line.entry_unit_id,
      v_line.quantity_change
    );

    v_movement_count := v_movement_count + 1;
  END LOOP;

  IF v_movement_count = 0 THEN
    RAISE EXCEPTION 'no_positive_recipe_quantity'
      USING ERRCODE = '22023';
  END IF;

  v_stock_capacity := public.compute_menu_item_stock_capacity(
    v_tenant_id,
    p_branch_id,
    p_menu_item_id
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'branch_id', p_branch_id,
    'menu_item_id', p_menu_item_id,
    'portions_added', p_extra_portions,
    'movements_created', v_movement_count,
    'stock_capacity', v_stock_capacity
  );
END;
$$;


--
-- Name: add_stock_request_line(bigint, bigint, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_stock_request_line(p_request_id bigint, p_ingredient_id bigint, p_entry_unit_id bigint, p_quantity numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_req public.stock_requests%ROWTYPE;
  v_fulfill text;
  v_item_id bigint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_req
  FROM public.stock_requests AS req
  WHERE req.id = p_request_id
    AND req.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stock_request_not_found' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_req.status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'stock_request_not_draft' USING ERRCODE = '22023';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission(
       v_req.branch_id,
       'inventory:request_create'
     )
  THEN
    RAISE EXCEPTION 'forbidden_request_create' USING ERRCODE = '42501';
  END IF;

  SELECT ingredient.default_fulfill_site_kind
  INTO v_fulfill
  FROM public.ingredients AS ingredient
  WHERE ingredient.id = p_ingredient_id
    AND ingredient.tenant_id = v_tenant
    AND ingredient.is_active IS TRUE;

  IF v_fulfill IS NULL THEN
    RAISE EXCEPTION 'ingredient_fulfill_site_required'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'stock_request_qty_invalid' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.stock_request_items (
    tenant_id,
    request_id,
    ingredient_id,
    entry_unit_id,
    quantity,
    fulfill_site_kind,
    status
  )
  VALUES (
    v_tenant,
    p_request_id,
    p_ingredient_id,
    p_entry_unit_id,
    p_quantity,
    v_fulfill,
    'pending'
  )
  RETURNING id INTO v_item_id;

  RETURN jsonb_build_object(
    'item_id', v_item_id,
    'fulfill_site_kind', v_fulfill
  );
END;
$$;


--
-- Name: adjust_stock_exception(bigint, bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_stock_exception(p_branch_id bigint, p_ingredient_id bigint, p_quantity_change numeric, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_entry_unit_id bigint;
  v_entry_to_base_factor numeric(18,12);
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT
    ingredient.issue_unit_id,
    ingredient_unit.to_base_factor
  INTO
    v_entry_unit_id,
    v_entry_to_base_factor
  FROM public.ingredients AS ingredient
  JOIN public.ingredient_units AS ingredient_unit
    ON ingredient_unit.tenant_id = ingredient.tenant_id
   AND ingredient_unit.ingredient_id = ingredient.id
   AND ingredient_unit.unit_id = ingredient.issue_unit_id
   AND ingredient_unit.is_active IS TRUE
  JOIN public.units AS unit_row
    ON unit_row.tenant_id = ingredient_unit.tenant_id
   AND unit_row.id = ingredient_unit.unit_id
   AND unit_row.is_active IS TRUE
  WHERE ingredient.tenant_id = v_tenant
    AND ingredient.id = p_ingredient_id
    AND ingredient.is_active IS TRUE;

  IF v_entry_unit_id IS NULL
     OR v_entry_to_base_factor IS NULL
     OR v_entry_to_base_factor <= 0 THEN
    RAISE EXCEPTION 'entry_unit_not_found:%', p_ingredient_id
      USING ERRCODE = '23503';
  END IF;

  RETURN public.adjust_stock_exception(
    p_branch_id,
    p_ingredient_id,
    p_quantity_change / v_entry_to_base_factor,
    v_entry_unit_id,
    p_reason
  );
END;
$$;


--
-- Name: adjust_stock_exception(bigint, bigint, numeric, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_stock_exception(p_branch_id bigint, p_ingredient_id bigint, p_entry_quantity numeric, p_entry_unit_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_location_id bigint;
  v_entry_to_base_factor numeric(18,12);
  v_entry_unit_code text;
  v_quantity_change numeric;
  v_movement_id bigint;
  v_reason text := pg_catalog.btrim(coalesce(p_reason, ''));
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_branch_id IS NULL
     OR p_ingredient_id IS NULL
     OR p_entry_unit_id IS NULL THEN
    RAISE EXCEPTION 'invalid_adjustment_target'
      USING ERRCODE = '22023';
  END IF;
  IF p_entry_quantity IS NULL
     OR p_entry_quantity = 0
     OR p_entry_quantity = 'NaN'::numeric
     OR p_entry_quantity = 'Infinity'::numeric
     OR p_entry_quantity = '-Infinity'::numeric THEN
    RAISE EXCEPTION 'quantity_change_nonzero_finite'
      USING ERRCODE = '22023';
  END IF;
  IF pg_catalog.length(v_reason) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT ingredient_unit.to_base_factor, unit_row.code
  INTO v_entry_to_base_factor, v_entry_unit_code
  FROM public.ingredients AS ingredient
  JOIN public.ingredient_units AS ingredient_unit
    ON ingredient_unit.tenant_id = ingredient.tenant_id
   AND ingredient_unit.ingredient_id = ingredient.id
   AND ingredient_unit.unit_id = p_entry_unit_id
   AND ingredient_unit.is_active IS TRUE
  JOIN public.units AS unit_row
    ON unit_row.tenant_id = ingredient_unit.tenant_id
   AND unit_row.id = ingredient_unit.unit_id
   AND unit_row.is_active IS TRUE
  WHERE ingredient.tenant_id = v_tenant
    AND ingredient.id = p_ingredient_id
    AND ingredient.is_active IS TRUE
    AND p_entry_unit_id IN (
      ingredient.issue_unit_id,
      ingredient.receipt_unit_id
    );

  IF v_entry_to_base_factor IS NULL OR v_entry_to_base_factor <= 0 THEN
    RAISE EXCEPTION 'inventory_unit_role_mismatch:receipt,issue'
      USING ERRCODE = '23514';
  END IF;

  v_quantity_change := p_entry_quantity * v_entry_to_base_factor;

  SELECT location.id
  INTO v_location_id
  FROM public.inventory_locations AS location
  JOIN public.branches AS branch
    ON branch.id = location.branch_id
   AND branch.tenant_id = location.tenant_id
   AND branch.is_active IS TRUE
  WHERE location.tenant_id = v_tenant
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE
  ORDER BY location.id
  LIMIT 1
  FOR UPDATE OF location;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'active_warehouse_required'
      USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.stock_movements (
    tenant_id,
    branch_id,
    ingredient_id,
    type,
    quantity_change,
    reason,
    created_by,
    location_id,
    entry_unit_id,
    entry_quantity,
    entry_to_base_factor,
    entry_unit_code
  ) VALUES (
    v_tenant,
    p_branch_id,
    p_ingredient_id,
    'adjustment',
    v_quantity_change,
    v_reason,
    v_uid,
    v_location_id,
    p_entry_unit_id,
    pg_catalog.abs(p_entry_quantity),
    v_entry_to_base_factor,
    v_entry_unit_code
  )
  RETURNING id INTO v_movement_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'movement_id', v_movement_id
  );
END;
$$;


--
-- Name: aggregate_daily_b2c_invoice(bigint, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aggregate_daily_b2c_invoice(p_branch_id bigint, p_summary_date date, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant_id   BIGINT;
  v_invoice_id  BIGINT;
  v_order_count INT;
  v_subtotal    NUMERIC(15,2);
  v_vat_amount  NUMERIC(15,2);
  v_total       NUMERIC(15,2);
  v_pred_rate   NUMERIC(5,2);
  v_eligible    BIGINT[];
  v_breakdown   JSONB;
  v_line_items  JSONB;
  v_is_service  BOOLEAN;
  v_actor       UUID;
BEGIN
  v_is_service := (auth.role() = 'service_role');
  v_actor := COALESCE(p_actor, auth.uid());

  -- 1. Tenant guard
  SELECT tenant_id INTO v_tenant_id FROM public.branches WHERE id = p_branch_id;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Permission gate (skip for service_role)
  IF NOT v_is_service THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
    END IF;
    IF v_tenant_id <> public.auth_tenant_id() THEN
      RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
    END IF;
    IF NOT public.has_permission_any('settings:tenant') THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 3. Per-(branch, date) advisory xact lock.
  PERFORM pg_advisory_xact_lock(
    hashtext('hddt-b2c:' || p_branch_id::text || ':' || p_summary_date::text)::bigint
  );

  -- 4. Idempotency short-circuit
  SELECT id INTO v_invoice_id
  FROM public.tax_invoices
  WHERE branch_id = p_branch_id
    AND summary_date = p_summary_date
    AND invoice_kind = 'daily_summary'
    AND status NOT IN ('cancelled', 'replaced');
  IF FOUND THEN
    RETURN jsonb_build_object(
      'skipped', true,
      'reason', 'already_exists',
      'tax_invoice_id', v_invoice_id
    );
  END IF;

  -- 5. Eligible orders (B2C bucket). Bucket source = payments.paid_at
  -- in Asia/Ho_Chi_Minh, matching revenue reporting.
  SELECT array_agg(DISTINCT o.id ORDER BY o.id)
  INTO v_eligible
  FROM public.orders o
  JOIN public.payments p ON p.order_id = o.id
  WHERE o.tenant_id = v_tenant_id
    AND o.branch_id = p_branch_id
    AND o.payment_status = 'paid'
    AND o.status NOT IN ('cancelled', 'refunded')
    AND p.status = 'completed'
    AND p.paid_at IS NOT NULL
    AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = p_summary_date
    AND NOT EXISTS (
      SELECT 1
      FROM public.self_order_payment_requests sopr
      WHERE sopr.tenant_id = v_tenant_id
        AND sopr.branch_id = p_branch_id
        AND sopr.order_id = o.id
        AND sopr.status = 'completed'
        AND sopr.invoice_payload @> '{"buyerNotGetInvoice": false}'::jsonb
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.tax_invoices ti
       WHERE ti.order_id = o.id
         AND ti.status IN ('draft', 'signing', 'submitted', 'issued')
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.tax_invoice_orders tio
      JOIN public.tax_invoices ti2 ON ti2.id = tio.tax_invoice_id
      WHERE tio.order_id = o.id
        AND ti2.status NOT IN ('cancelled', 'replaced')
    );

  IF v_eligible IS NULL OR array_length(v_eligible, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'skipped', true,
      'reason', 'no_eligible_orders',
      'order_count', 0
    );
  END IF;

  v_order_count := array_length(v_eligible, 1);

  -- 6. Compute per-rate VAT breakdown via shared SQL helper.
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'vat_rate', vat_rate,
      'line_gross', line_gross,
      'line_subtotal', line_subtotal,
      'line_vat', line_vat
    ) ORDER BY vat_rate), '[]'::jsonb),
    COALESCE(SUM(line_subtotal), 0),
    COALESCE(SUM(line_vat), 0)
  INTO v_breakdown, v_subtotal, v_vat_amount
  FROM public._compute_vat_breakdown(v_eligible);

  v_total := v_subtotal + v_vat_amount;

  SELECT vat_rate INTO v_pred_rate
  FROM public._compute_vat_breakdown(v_eligible)
  ORDER BY line_gross DESC
  LIMIT 1;

  SELECT jsonb_agg(jsonb_build_object(
    'name', CASE
      WHEN vat_rate = 8  THEN 'Đồ ăn (8%)'
      WHEN vat_rate = 10 THEN 'Đồ uống có cồn (10%)'
      WHEN vat_rate = 5  THEN 'Hàng hoá khác (5%)'
      ELSE 'Hàng hoá VAT ' || vat_rate || '%'
    END,
    'unit', 'Phần',
    'quantity', 1,
    'unit_price', line_subtotal,
    'amount', line_subtotal,
    'vat_rate', vat_rate,
    'vat_amount', line_vat
  ) ORDER BY vat_rate)
  INTO v_line_items
  FROM public._compute_vat_breakdown(v_eligible);

  -- 7. INSERT tax_invoices as Viettel S-invoice draft.
  INSERT INTO public.tax_invoices (
    tenant_id, branch_id, order_id, status,
    invoice_kind, summary_date, summary_orders_count,
    buyer_name, buyer_tax_code, buyer_address,
    subtotal, vat_rate, vat_amount, total_amount,
    provider, provider_ref, provider_data,
    created_by
  ) VALUES (
    v_tenant_id, p_branch_id, NULL, 'draft',
    'daily_summary', p_summary_date, v_order_count,
    'Bán cho người tiêu dùng', NULL, NULL,
    v_subtotal, v_pred_rate, v_vat_amount, v_total,
    'viettel', NULL,
    jsonb_build_object('vat_breakdown', v_breakdown),
    v_actor
  )
  RETURNING id INTO v_invoice_id;

  -- 8. INSERT junction rows.
  INSERT INTO public.tax_invoice_orders
    (tax_invoice_id, order_id, tenant_id, branch_id, vat_rate, line_subtotal, line_vat_amount)
  SELECT
    v_invoice_id,
    per_order.order_id,
    v_tenant_id,
    p_branch_id,
    per_order.pred_rate,
    per_order.order_subtotal,
    per_order.order_vat
  FROM (
    SELECT
      o.id AS order_id,
      SUM(
        (oi.subtotal * (o.total_amount / NULLIF(items_sum.s, 0)))
        / (1 + oi.vat_rate / 100)
      )::numeric(15,2) AS order_subtotal,
      SUM(
        (oi.subtotal * (o.total_amount / NULLIF(items_sum.s, 0)))
        - (oi.subtotal * (o.total_amount / NULLIF(items_sum.s, 0)))
          / (1 + oi.vat_rate / 100)
      )::numeric(15,2) AS order_vat,
      (
        SELECT oi3.vat_rate
        FROM public.order_items oi3
        WHERE oi3.order_id = o.id
          AND oi3.status <> 'cancelled'
        GROUP BY oi3.vat_rate
        ORDER BY SUM(oi3.subtotal) DESC
        LIMIT 1
      ) AS pred_rate
    FROM public.orders o
    JOIN public.order_items oi ON oi.order_id = o.id
    JOIN LATERAL (
      SELECT COALESCE(SUM(subtotal), 0) AS s
      FROM public.order_items
      WHERE order_id = o.id AND status <> 'cancelled'
    ) items_sum ON true
    WHERE o.id = ANY(v_eligible)
      AND oi.status <> 'cancelled'
      AND items_sum.s > 0
    GROUP BY o.id, o.total_amount, items_sum.s
  ) per_order;

  -- 9. Return aggregation result for Node runtime to call Sinvoice.
  RETURN jsonb_build_object(
    'tax_invoice_id', v_invoice_id,
    'order_count', v_order_count,
    'subtotal', v_subtotal,
    'vat_amount', v_vat_amount,
    'total_amount', v_total,
    'header_vat_rate', v_pred_rate,
    'vat_breakdown', v_breakdown,
    'order_ids', v_eligible,
    'line_items_for_provider', COALESCE(v_line_items, '[]'::jsonb)
  );
END;
$$;


--
-- Name: FUNCTION aggregate_daily_b2c_invoice(p_branch_id bigint, p_summary_date date, p_actor uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.aggregate_daily_b2c_invoice(p_branch_id bigint, p_summary_date date, p_actor uuid) IS 'Daily B2C summary HĐ aggregation. Creates draft tax_invoices row with provider=viettel and returns line_items_for_provider for the Node Sinvoice caller.';


--
-- Name: allocate_supplier_advance(bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_supplier_advance(p_payment_id bigint, p_idempotency_key uuid, p_allocations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_payment public.supplier_payments%ROWTYPE;
  v_allocated numeric(15,2);
  v_available numeric(15,2);
  v_remaining numeric(15,2);
  v_result_status text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT (public.auth_is_owner(v_uid) OR public.has_position('accountant'))
     OR NOT public.has_permission_any('finance:ap_pay') THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL
     OR pg_catalog.jsonb_typeof(p_allocations) <> 'array'
     OR pg_catalog.jsonb_array_length(p_allocations) = 0 THEN
    RAISE EXCEPTION 'supplier_advance_allocation_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF (
    SELECT count(DISTINCT (allocation.value->>'invoice_id')::bigint)
    FROM pg_catalog.jsonb_array_elements(p_allocations) allocation
  ) <> pg_catalog.jsonb_array_length(p_allocations) THEN
    RAISE EXCEPTION 'supplier_advance_invoice_duplicate'
      USING ERRCODE = '23505';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'supplier-advance:' || v_tenant::text || ':'
        || p_idempotency_key::text,
      0
    )
  );

  SELECT *
  INTO v_payment
  FROM public.supplier_payments payment
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_payment_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.supplier_payment_allocations allocation
    WHERE allocation.tenant_id = v_tenant
      AND allocation.allocation_intent_key = p_idempotency_key
  ) THEN
    IF EXISTS (
      SELECT 1
      FROM public.supplier_payment_allocations allocation
      WHERE allocation.tenant_id = v_tenant
        AND allocation.allocation_intent_key = p_idempotency_key
        AND allocation.supplier_payment_id <> p_payment_id
    ) OR (
      SELECT count(*)
      FROM public.supplier_payment_allocations allocation
      WHERE allocation.tenant_id = v_tenant
        AND allocation.allocation_intent_key = p_idempotency_key
        AND allocation.supplier_payment_id = p_payment_id
    ) <> pg_catalog.jsonb_array_length(p_allocations)
    OR EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_array_elements(p_allocations) requested
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.supplier_payment_allocations allocation
        WHERE allocation.tenant_id = v_tenant
          AND allocation.supplier_payment_id = p_payment_id
          AND allocation.allocation_intent_key = p_idempotency_key
          AND allocation.supplier_invoice_id =
            (requested.value->>'invoice_id')::bigint
          AND allocation.amount =
            (requested.value->>'amount')::numeric
      )
    ) THEN
      RAISE EXCEPTION 'supplier_advance_idempotency_conflict'
        USING ERRCODE = '22023';
    END IF;

    SELECT COALESCE(sum(allocation.amount), 0)
    INTO v_allocated
    FROM public.supplier_payment_allocations allocation
    WHERE allocation.tenant_id = v_tenant
      AND allocation.supplier_payment_id = p_payment_id
      AND allocation.allocation_intent_key = p_idempotency_key;

    SELECT (
      v_payment.amount - COALESCE(sum(allocation.amount), 0)
    )::numeric(15,2)
    INTO v_remaining
    FROM public.supplier_payment_allocations allocation
    WHERE allocation.tenant_id = v_tenant
      AND allocation.supplier_payment_id = p_payment_id;

    RETURN pg_catalog.jsonb_build_object(
      'payment_id', p_payment_id,
      'allocated_amount', v_allocated,
      'advance_amount', v_remaining,
      'payment_status', v_payment.idempotency_result_status
    );
  END IF;

  SELECT COALESCE(sum((allocation.value->>'amount')::numeric), 0)
  INTO v_allocated
  FROM pg_catalog.jsonb_array_elements(p_allocations) allocation;
  v_allocated := v_allocated::numeric(15,2);

  SELECT (
    v_payment.amount - COALESCE(sum(allocation.amount), 0)
  )::numeric(15,2)
  INTO v_available
  FROM public.supplier_payment_allocations allocation
  WHERE allocation.tenant_id = v_tenant
    AND allocation.supplier_payment_id = p_payment_id;

  PERFORM 1
  FROM public.supplier_invoices invoice
  JOIN pg_catalog.jsonb_array_elements(p_allocations) allocation
    ON invoice.id = (allocation.value->>'invoice_id')::bigint
  WHERE invoice.tenant_id = v_tenant
  ORDER BY invoice.id
  FOR UPDATE OF invoice;

  IF v_allocated > v_available
     OR EXISTS (
       SELECT 1
       FROM pg_catalog.jsonb_array_elements(p_allocations) allocation
       LEFT JOIN public.supplier_invoices invoice
         ON invoice.id = (allocation.value->>'invoice_id')::bigint
        AND invoice.tenant_id = v_tenant
       WHERE invoice.id IS NULL
          OR invoice.supplier_id IS DISTINCT FROM v_payment.supplier_id
          OR (allocation.value->>'amount')::numeric <= 0
          OR (allocation.value->>'amount')::numeric
            <> pg_catalog.round(
              (allocation.value->>'amount')::numeric,
              2
            )
          OR invoice.matching_status <> 'matched'
          OR invoice.vat_invoice_attachment_path IS NULL
          OR btrim(invoice.vat_invoice_attachment_path) = ''
          OR (
            invoice.invoice_kind = 'service'
            AND invoice.service_verified_at IS NULL
          )
          OR (
            invoice.invoice_kind = 'goods'
            AND (
              NOT EXISTS (
                SELECT 1
                FROM public.supplier_invoice_receipt_allocations receipt
                WHERE receipt.tenant_id = v_tenant
                  AND receipt.supplier_invoice_id = invoice.id
              )
              OR EXISTS (
                SELECT 1
                FROM public.supplier_invoice_receipt_allocations receipt
                LEFT JOIN public.goods_received_notes grn
                  ON grn.id = receipt.grn_id
                 AND grn.tenant_id = receipt.tenant_id
                LEFT JOIN public.purchase_orders purchase_order
                  ON purchase_order.id = receipt.po_id
                 AND purchase_order.tenant_id = receipt.tenant_id
                WHERE receipt.tenant_id = v_tenant
                  AND receipt.supplier_invoice_id = invoice.id
                  AND (
                    grn.id IS NULL
                    OR grn.status <> 'confirmed'
                    OR grn.po_id IS DISTINCT FROM receipt.po_id
                    OR purchase_order.supplier_id
                      IS DISTINCT FROM invoice.supplier_id
                  )
              )
            )
          )
          OR (allocation.value->>'amount')::numeric >
            invoice.total_amount
              - invoice.paid_amount
              - invoice.credit_applied_amount
     ) THEN
    RAISE EXCEPTION 'supplier_advance_allocation_invalid'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.supplier_payment_allocations (
    tenant_id,
    supplier_payment_id,
    supplier_invoice_id,
    amount,
    allocation_intent_key
  )
  SELECT
    v_tenant,
    p_payment_id,
    (allocation.value->>'invoice_id')::bigint,
    (allocation.value->>'amount')::numeric(15,2),
    p_idempotency_key
  FROM pg_catalog.jsonb_array_elements(p_allocations) allocation;

  WITH allocated AS (
    SELECT
      (allocation.value->>'invoice_id')::bigint AS invoice_id,
      sum((allocation.value->>'amount')::numeric(15,2)) AS amount
    FROM pg_catalog.jsonb_array_elements(p_allocations) allocation
    GROUP BY (allocation.value->>'invoice_id')::bigint
  )
  UPDATE public.supplier_invoices invoice
  SET paid_amount = invoice.paid_amount + allocated.amount,
      payment_status = CASE
        WHEN invoice.paid_amount
           + allocated.amount
           + invoice.credit_applied_amount
             >= invoice.total_amount THEN 'paid'
        ELSE 'partial'
      END,
      paid_at = CASE
        WHEN invoice.paid_amount
           + allocated.amount
           + invoice.credit_applied_amount
             >= invoice.total_amount THEN pg_catalog.now()
        ELSE invoice.paid_at
      END,
      updated_at = pg_catalog.now()
  FROM allocated
  WHERE invoice.id = allocated.invoice_id
    AND invoice.tenant_id = v_tenant;

  v_remaining := (v_available - v_allocated)::numeric(15,2);
  v_result_status := CASE
    WHEN v_remaining = 0
     AND NOT EXISTS (
       SELECT 1
       FROM public.supplier_payment_allocations allocation
       JOIN public.supplier_invoices invoice
         ON invoice.id = allocation.supplier_invoice_id
        AND invoice.tenant_id = allocation.tenant_id
       WHERE allocation.tenant_id = v_tenant
         AND allocation.supplier_payment_id = p_payment_id
         AND invoice.payment_status <> 'paid'
     ) THEN 'paid'
    ELSE 'partial'
  END;

  UPDATE public.supplier_payments
  SET idempotency_result_status = v_result_status,
      updated_at = pg_catalog.now()
  WHERE id = p_payment_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'supplier_payment.advance_allocated',
    'supplier_payment',
    p_payment_id,
    pg_catalog.jsonb_build_object('advance_amount', v_available),
    pg_catalog.jsonb_build_object(
      'allocated_amount', v_allocated,
      'advance_amount', v_remaining
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'payment_id', p_payment_id,
    'allocated_amount', v_allocated,
    'advance_amount', v_remaining,
    'payment_status', v_result_status
  );
END;
$$;


--
-- Name: amend_grn_line(bigint, bigint, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.amend_grn_line(p_grn_id bigint, p_line_id bigint, p_received_quantity numeric, p_rejected_quantity numeric, p_reason text, p_rejection_reason text, p_rejected_photo_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_numeric_15_3_max constant numeric := 999999999999.999;
  c_numeric_15_2_max constant numeric := 9999999999999.99;
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_grn record;
  v_line record;
  v_old_net numeric;
  v_old_net_base numeric;
  v_new_net numeric;
  v_new_net_base numeric;
  v_delta_quantity numeric;
  v_delta_base numeric;
  v_delta_value numeric;
  v_cost_base numeric;
  v_new_total_cost numeric;
  v_location_id bigint;
  v_current_quantity numeric;
  v_current_wac numeric;
  v_next_wac numeric;
  v_all_fulfilled boolean;
  v_po_status text;
  v_invoice_id bigint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'reason_required_min_5_chars'
      USING ERRCODE = '22023';
  END IF;
  IF p_received_quantity IS NULL
     OR p_received_quantity < 0
     OR p_received_quantity > c_numeric_15_3_max
     OR p_rejected_quantity IS NULL
     OR p_rejected_quantity < 0
     OR p_rejected_quantity > c_numeric_15_3_max THEN
    RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
  END IF;
  IF p_rejected_quantity > p_received_quantity THEN
    RAISE EXCEPTION 'rejected_exceeds_received'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_rejected_quantity > 0
     AND NULLIF(btrim(p_rejection_reason), '') IS NULL THEN
    RAISE EXCEPTION 'grn_qc_reason_required'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_rejected_quantity > 0
     AND NOT private.grn_rejection_photo_exists(
       v_tenant,
       p_grn_id,
       p_line_id,
       p_rejected_photo_url
     ) THEN
    RAISE EXCEPTION 'grn_qc_photo_required'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT grn.*
  INTO v_grn
  FROM public.goods_received_notes AS grn
  WHERE grn.id = p_grn_id
    AND grn.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_grn.branch_id,
    'procurement:grn_amend'
  ) THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;
  IF v_grn.status <> 'confirmed' THEN
    RAISE EXCEPTION 'grn_not_confirmed_use_upsert'
      USING ERRCODE = '22023';
  END IF;

  SELECT item.*
  INTO v_line
  FROM public.grn_items AS item
  WHERE item.id = p_line_id
    AND item.grn_id = p_grn_id
    AND item.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_line_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_line.unit_cost <= 0 THEN
    RAISE EXCEPTION 'grn_line_approved_price_missing'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_grn.po_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM public.purchase_order_items AS po_item
       WHERE po_item.tenant_id = v_tenant
         AND po_item.po_id = v_grn.po_id
         AND po_item.ingredient_id = v_line.ingredient_id
         AND po_item.entry_unit_id IS NOT DISTINCT FROM
           v_line.entry_unit_id
         AND po_item.unit_price_est = v_line.unit_cost
         AND po_item.unit_price_est > 0
     ) THEN
    RAISE EXCEPTION 'grn_line_approved_price_missing_or_stale'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.supplier_return_items AS return_item
    JOIN public.supplier_returns AS supplier_return
      ON supplier_return.id = return_item.return_id
     AND supplier_return.tenant_id = return_item.tenant_id
    WHERE return_item.tenant_id = v_tenant
      AND return_item.grn_item_id = p_line_id
      AND supplier_return.status <> 'cancelled'
  ) THEN
    RAISE EXCEPTION 'has_active_supplier_return'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.supplier_invoices AS invoice
    WHERE invoice.tenant_id = v_tenant
      AND invoice.grn_id = p_grn_id
      AND (
        coalesce(invoice.payment_status, 'unpaid') <> 'unpaid'
        OR coalesce(invoice.paid_amount, 0) > 0
        OR coalesce(invoice.credit_applied_amount, 0) > 0
      )
  ) THEN
    RAISE EXCEPTION 'has_paid_invoice'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_grn.location_id IS NULL THEN
    SELECT location.id
    INTO v_location_id
    FROM public.inventory_locations AS location
    WHERE location.tenant_id = v_tenant
      AND location.branch_id = v_grn.branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE
      AND location.is_default_receive IS TRUE;
  ELSE
    SELECT location.id
    INTO v_location_id
    FROM public.inventory_locations AS location
    WHERE location.id = v_grn.location_id
      AND location.tenant_id = v_tenant
      AND location.branch_id = v_grn.branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE;
  END IF;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'grn_warehouse_location_missing'
      USING ERRCODE = 'no_data_found';
  END IF;

  v_old_net := v_line.received_quantity - v_line.rejected_quantity;
  v_new_net := p_received_quantity - p_rejected_quantity;
  v_old_net_base := public.inv_to_base(
    v_line.ingredient_id,
    v_line.entry_unit_id,
    v_old_net
  );
  v_new_net_base := public.inv_to_base(
    v_line.ingredient_id,
    v_line.entry_unit_id,
    v_new_net
  );
  v_delta_quantity := v_new_net - v_old_net;
  v_delta_base := v_new_net_base - v_old_net_base;
  v_delta_value := v_delta_quantity * v_line.unit_cost;
  v_new_total_cost := round(v_new_net * v_line.unit_cost, 2);
  v_cost_base := CASE
    WHEN v_new_net_base <> 0
      THEN round(v_new_total_cost / v_new_net_base, 2)
    WHEN v_old_net_base <> 0
      THEN round(
        (v_old_net * v_line.unit_cost) / v_old_net_base,
        2
      )
    ELSE v_line.unit_cost
  END;

  IF abs(v_new_net_base) > c_numeric_15_3_max
     OR abs(v_delta_base) > c_numeric_15_3_max
     OR abs(v_delta_value) > c_numeric_15_2_max
     OR abs(v_new_total_cost) > c_numeric_15_2_max
     OR abs(v_cost_base) > c_numeric_15_2_max THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;

  SELECT stock.current_quantity, stock.avg_unit_cost
  INTO v_current_quantity, v_current_wac
  FROM public.stock_levels AS stock
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = v_grn.branch_id
    AND stock.location_id = v_location_id
    AND stock.ingredient_id = v_line.ingredient_id
  FOR UPDATE;

  v_current_quantity := coalesce(v_current_quantity, 0);
  IF v_current_quantity + v_delta_base < 0 THEN
    RAISE EXCEPTION 'negative_stock' USING ERRCODE = 'check_violation';
  END IF;

  IF v_current_quantity + v_delta_base > 0 THEN
    v_next_wac := round(
      (
        v_current_quantity * coalesce(v_current_wac, 0)
        + v_delta_value
      ) / (v_current_quantity + v_delta_base),
      2
    );
    IF v_next_wac < 0 OR abs(v_next_wac) > c_numeric_15_2_max THEN
      RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_delta_base <> 0 THEN
    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      quantity_change,
      reason,
      created_by,
      grn_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    VALUES (
      v_tenant,
      v_grn.branch_id,
      v_line.ingredient_id,
      'grn_amend',
      v_delta_base,
      'GRN '
        || v_grn.grn_number
        || ' line '
        || p_line_id
        || ': '
        || btrim(p_reason),
      v_uid,
      p_grn_id,
      v_cost_base,
      v_location_id,
      v_line.entry_unit_id,
      abs(v_delta_quantity)
    );
  END IF;

  IF v_next_wac IS NOT NULL THEN
    UPDATE public.stock_levels AS stock
    SET avg_unit_cost = v_next_wac,
        updated_at = now()
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_grn.branch_id
      AND stock.location_id = v_location_id
      AND stock.ingredient_id = v_line.ingredient_id;
  END IF;

  UPDATE public.grn_items
  SET received_quantity = p_received_quantity,
      rejected_quantity = p_rejected_quantity,
      rejection_reason = CASE
        WHEN p_rejected_quantity > 0 THEN NULLIF(
          btrim(p_rejection_reason),
          ''
        )
        ELSE NULL
      END,
      rejected_photo_url = CASE
        WHEN p_rejected_quantity > 0 THEN NULLIF(
          btrim(p_rejected_photo_url),
          ''
        )
        ELSE NULL
      END,
      total_cost = v_new_total_cost
  WHERE id = p_line_id
    AND tenant_id = v_tenant;

  IF v_grn.po_id IS NOT NULL THEN
    PERFORM 1
    FROM public.purchase_orders AS purchase_order
    WHERE purchase_order.id = v_grn.po_id
      AND purchase_order.tenant_id = v_tenant
    FOR UPDATE;

    WITH ordered AS (
      SELECT
        po_item.ingredient_id,
        sum(public.inv_to_base(
          po_item.ingredient_id,
          po_item.entry_unit_id,
          po_item.quantity
        )) AS quantity
      FROM public.purchase_order_items AS po_item
      WHERE po_item.po_id = v_grn.po_id
        AND po_item.tenant_id = v_tenant
      GROUP BY po_item.ingredient_id
    ),
    received AS (
      SELECT
        item.ingredient_id,
        sum(public.inv_to_base(
          item.ingredient_id,
          item.entry_unit_id,
          item.received_quantity - item.rejected_quantity
        )) AS quantity
      FROM public.grn_items AS item
      JOIN public.goods_received_notes AS grn
        ON grn.id = item.grn_id
       AND grn.tenant_id = item.tenant_id
      WHERE grn.po_id = v_grn.po_id
        AND grn.tenant_id = v_tenant
        AND grn.status = 'confirmed'
      GROUP BY item.ingredient_id
    )
    SELECT bool_and(coalesce(received.quantity, 0) >= ordered.quantity)
    INTO v_all_fulfilled
    FROM ordered
    LEFT JOIN received USING (ingredient_id)
    WHERE ordered.quantity > 0;

    UPDATE public.purchase_orders
    SET status = CASE
          WHEN coalesce(v_all_fulfilled, FALSE) THEN 'received'
          ELSE 'partially_received'
        END,
        updated_at = now()
    WHERE id = v_grn.po_id
      AND tenant_id = v_tenant
      AND status IN ('sent', 'partially_received', 'received')
    RETURNING status INTO v_po_status;
  END IF;

  FOR v_invoice_id IN
    SELECT invoice.id
    FROM public.supplier_invoices AS invoice
    WHERE invoice.tenant_id = v_tenant
      AND invoice.grn_id = p_grn_id
  LOOP
    PERFORM public.recompute_supplier_invoice_matching(v_invoice_id);
  END LOOP;

  PERFORM public.log_audit(
    'inventory.grn.line_amended',
    'goods_received_note',
    p_grn_id,
    jsonb_build_object(
      'line_id', p_line_id,
      'received_quantity', v_line.received_quantity,
      'rejected_quantity', v_line.rejected_quantity,
      'rejection_reason', v_line.rejection_reason,
      'rejected_photo_url', v_line.rejected_photo_url,
      'unit_cost', v_line.unit_cost,
      'total_cost', round(v_old_net * v_line.unit_cost, 2)
    ),
    jsonb_build_object(
      'line_id', p_line_id,
      'received_quantity', p_received_quantity,
      'rejected_quantity', p_rejected_quantity,
      'rejection_reason', CASE
        WHEN p_rejected_quantity > 0 THEN p_rejection_reason
        ELSE NULL
      END,
      'rejected_photo_url', CASE
        WHEN p_rejected_quantity > 0 THEN p_rejected_photo_url
        ELSE NULL
      END,
      'unit_cost', v_line.unit_cost,
      'total_cost', v_new_total_cost,
      'delta_quantity', v_delta_quantity,
      'delta_base_quantity', v_delta_base,
      'delta_value', v_delta_value,
      'location_id', v_location_id,
      'po_status', v_po_status,
      'reason', btrim(p_reason)
    )
  );

  RETURN jsonb_build_object(
    'grn_id', p_grn_id,
    'line_id', p_line_id,
    'received_quantity', p_received_quantity,
    'rejected_quantity', p_rejected_quantity,
    'unit_cost', v_line.unit_cost,
    'total_cost', v_new_total_cost,
    'delta_quantity', v_delta_quantity,
    'delta_base_quantity', v_delta_base,
    'location_id', v_location_id,
    'po_id', v_grn.po_id,
    'po_status', v_po_status
  );
END;
$$;


--
-- Name: append_order_items(bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_order_items(p_order_id bigint, p_items jsonb, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_prof_tenant     BIGINT;
  v_prof_branch     BIGINT;
  v_prof_role       TEXT;
  v_order           RECORD;
  v_item            JSONB;
  v_base_price      NUMERIC(15,2);
  v_variant_adj     NUMERIC(15,2);
  v_modifier_sum    NUMERIC(15,2);
  v_sides_sum       NUMERIC(15,2);
  v_enriched_sides  JSONB;
  v_unit_price      NUMERIC(15,2);
  v_item_subtotal   NUMERIC(15,2);
  v_menu_item_id    BIGINT;
  v_variant_id      BIGINT;
  v_quantity        INT;
  v_subtotal        NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_total_amount    NUMERIC(15,2);
  v_item_discount   NUMERIC(15,2);
  v_note_parts      TEXT[] := ARRAY[]::TEXT[];
  v_item_name       TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  IF p_idempotency_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.order_items
      WHERE order_id = p_order_id
        AND request_key = p_idempotency_key
      LIMIT 1
    ) THEN
      SELECT o.subtotal, o.total_amount
      INTO v_subtotal, v_total_amount
      FROM public.orders o
      WHERE o.id = p_order_id;

      RETURN jsonb_build_object(
        'success',      TRUE,
        'order_id',     p_order_id,
        'added_count',  0,
        'subtotal',     COALESCE(v_subtotal, 0),
        'total_amount', COALESCE(v_total_amount, 0),
        'idempotent',   TRUE
      );
    END IF;
  END IF;

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status, o.service_charge,
         o.discount_type, o.discount_value
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF v_order.status NOT IN ('new', 'confirmed', 'preparing', 'ready', 'served') THEN
    RAISE EXCEPTION 'order not appendable' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order not appendable' USING ERRCODE = '22023';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'p_items must be a non-empty JSON array' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) AS value
  LOOP
    v_menu_item_id := (v_item ->> 'menu_item_id')::BIGINT;
    v_variant_id := NULLIF(v_item ->> 'variant_id', '')::BIGINT;
    v_quantity := (v_item ->> 'quantity')::INT;

    IF v_quantity IS NULL OR v_quantity < 1 THEN
      RAISE EXCEPTION 'invalid quantity' USING ERRCODE = '22023';
    END IF;

    SELECT base_price INTO v_base_price
    FROM public.menu_items
    WHERE id = v_menu_item_id AND tenant_id = v_order.tenant_id AND is_active = TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Menu item % not found or inactive', v_menu_item_id USING ERRCODE = 'P0002';
    END IF;

    v_variant_adj := 0;
    IF v_variant_id IS NOT NULL THEN
      SELECT price_adjustment INTO v_variant_adj
      FROM public.menu_item_variants
      WHERE id = v_variant_id AND item_id = v_menu_item_id AND tenant_id = v_order.tenant_id AND is_active = TRUE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Variant % not found or inactive', v_variant_id USING ERRCODE = 'P0002';
      END IF;
    END IF;

    v_modifier_sum := public.pos_order_modifier_sum(
      v_order.tenant_id,
      v_menu_item_id,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB)
    );

    SELECT sides_sum, enriched_sides
    INTO v_sides_sum, v_enriched_sides
    FROM public.pos_enrich_order_sides(
      v_order.tenant_id,
      v_menu_item_id,
      COALESCE(v_item -> 'sides', '[]'::JSONB)
    );

    v_unit_price := v_base_price + v_variant_adj + v_modifier_sum + COALESCE(v_sides_sum, 0);
    v_item_subtotal := v_unit_price * v_quantity;

    v_item_name := v_item ->> 'item_name';
    IF v_item_name IS NOT NULL AND length(trim(v_item_name)) > 0 THEN
      v_note_parts := array_append(v_note_parts, v_item_name);
    END IF;

    INSERT INTO public.order_items (
      tenant_id, order_id, menu_item_id, variant_id,
      item_name, variant_name, quantity, unit_price,
      modifiers, sides, subtotal, note, status, request_key,
      discount_type, discount_value, discount_note
    )
    VALUES (
      v_order.tenant_id, p_order_id, v_menu_item_id, v_variant_id,
      COALESCE(v_item ->> 'item_name', 'Mon'),
      v_item ->> 'variant_name',
      v_quantity, v_unit_price,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB),
      COALESCE(v_enriched_sides, '[]'::JSONB),
      v_item_subtotal, v_item ->> 'note', 'pending',
      p_idempotency_key,
      NULLIF(v_item ->> 'discount_type', ''),
      CASE WHEN NULLIF(v_item ->> 'discount_value', '') IS NOT NULL
           THEN (v_item ->> 'discount_value')::NUMERIC
           ELSE NULL END,
      NULLIF(trim(COALESCE(v_item ->> 'discount_note', '')), '')
    );
  END LOOP;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal
  FROM public.order_items
  WHERE order_id = p_order_id AND status <> 'cancelled';

  v_discount_amount := public.compute_discount_amount(
    v_order.discount_type, v_order.discount_value, v_subtotal
  );

  v_total_amount := v_subtotal
                  + COALESCE(v_order.service_charge, 0)
                  - v_discount_amount;

  UPDATE public.orders o
  SET
    subtotal        = v_subtotal,
    tax_amount      = 0,
    discount_amount = v_discount_amount,
    total_amount    = v_total_amount,
    updated_at      = now()
  WHERE o.id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id,
    p_order_id,
    v_order.status,
    v_order.status,
    v_uid,
    'items_added: ' || COALESCE(array_to_string(v_note_parts, ', '), 'items')
  );

  PERFORM public.route_order_to_kds(p_order_id);

  -- Re-read the final stored totals: the order-level normalize trigger fires
  -- on the UPDATE above and recomputes discount_amount/total_amount to include
  -- per-item discounts, overwriting the order-only figures computed here.
  SELECT o.subtotal, o.total_amount, COALESCE(o.item_discount_amount, 0)
  INTO v_subtotal, v_total_amount, v_item_discount
  FROM public.orders o
  WHERE o.id = p_order_id;

  RETURN jsonb_build_object(
    'success',              TRUE,
    'order_id',             p_order_id,
    'added_count',          jsonb_array_length(p_items),
    'subtotal',             v_subtotal,
    'total_amount',         v_total_amount,
    'item_discount_amount', v_item_discount
  );
END;
$$;


--
-- Name: FUNCTION append_order_items(p_order_id bigint, p_items jsonb, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.append_order_items(p_order_id bigint, p_items jsonb, p_idempotency_key uuid) IS 'Atomic append of order_items to an existing appendable order. pg_advisory_xact_lock(order_id) serializes with other mutations. If p_idempotency_key matches a prior append on the same order, short-circuits returning current totals (no duplicate insert). Returns {success, order_id, added_count, subtotal, total_amount[, idempotent]}.';


--
-- Name: append_order_items_with_daily_limit_hold(bigint, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_order_items_with_daily_limit_hold(p_order_id bigint, p_items jsonb, p_idempotency_key uuid DEFAULT NULL::uuid, p_daily_limit_hold_token uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_order record;
BEGIN
  IF p_daily_limit_hold_token IS NOT NULL THEN
    PERFORM set_config(
      'comtammatu.daily_limit_hold_token',
      p_daily_limit_hold_token::text,
      true
    );
  END IF;

  v_result := public.append_order_items(
    p_order_id,
    p_items,
    p_idempotency_key
  );

  IF p_daily_limit_hold_token IS NOT NULL THEN
    SELECT o.tenant_id, o.branch_id
    INTO v_order
    FROM public.orders o
    WHERE o.id = p_order_id;

    IF FOUND THEN
      UPDATE public.branch_menu_item_daily_holds h
      SET committed_at = COALESCE(h.committed_at, now()),
          order_id = COALESCE(h.order_id, p_order_id),
          updated_at = now()
      WHERE h.tenant_id = v_order.tenant_id
        AND h.branch_id = v_order.branch_id
        AND h.hold_token = p_daily_limit_hold_token
        AND h.held_by = v_uid
        AND h.committed_at IS NULL
        AND h.released_at IS NULL
        AND h.expires_at > now();
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION append_order_items_with_daily_limit_hold(p_order_id bigint, p_items jsonb, p_idempotency_key uuid, p_daily_limit_hold_token uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.append_order_items_with_daily_limit_hold(p_order_id bigint, p_items jsonb, p_idempotency_key uuid, p_daily_limit_hold_token uuid) IS 'Wrapper around append_order_items that sets transaction-local daily-limit hold token so the quota trigger excludes the caller hold, then commits matching active holds to the target order.';


--
-- Name: apply_credit_note_to_invoice(bigint, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credit_note_to_invoice(p_credit_id bigint, p_invoice_id bigint, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     UUID   := auth.uid();
  v_tenant  BIGINT := public.auth_tenant_id();
  v_credit  RECORD;
  v_invoice RECORD;
  v_remaining_credit  NUMERIC(15,2);
  v_remaining_invoice NUMERIC(15,2);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission(NULL, 'finance:ap_pay') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_credit
  FROM public.supplier_credit_notes
  WHERE id = p_credit_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'credit_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_credit.status NOT IN ('open') THEN
    RAISE EXCEPTION 'credit_not_open' USING ERRCODE = '22023';
  END IF;
  IF v_credit.kind <> 'credit_note' THEN
    RAISE EXCEPTION 'credit_kind_mismatch' USING ERRCODE = '22023',
      DETAIL = 'Only credit_note kind can be applied to invoices; cash_refund is closed at issuance.';
  END IF;

  SELECT * INTO v_invoice
  FROM public.supplier_invoices
  WHERE id = p_invoice_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Same supplier guard
  IF v_invoice.supplier_id <> v_credit.supplier_id THEN
    RAISE EXCEPTION 'supplier_mismatch' USING ERRCODE = '22023';
  END IF;

  v_remaining_credit  := v_credit.amount - v_credit.applied_amount;
  v_remaining_invoice := v_invoice.total_amount
                       - COALESCE(v_invoice.paid_amount, 0)
                       - COALESCE(v_invoice.credit_applied_amount, 0);

  IF p_amount > v_remaining_credit THEN
    RAISE EXCEPTION 'amount_exceeds_credit' USING ERRCODE = '22023',
      DETAIL = format('credit_remaining=%s', v_remaining_credit);
  END IF;
  IF p_amount > v_remaining_invoice THEN
    RAISE EXCEPTION 'amount_exceeds_invoice' USING ERRCODE = '22023',
      DETAIL = format('invoice_remaining=%s', v_remaining_invoice);
  END IF;

  -- Apply
  UPDATE public.supplier_credit_notes
  SET applied_amount = applied_amount + p_amount,
      invoice_id = COALESCE(invoice_id, p_invoice_id),
      status = CASE
        WHEN applied_amount + p_amount >= amount THEN 'applied'
        ELSE 'open'
      END,
      applied_at = CASE
        WHEN applied_amount + p_amount >= amount THEN now()
        ELSE applied_at
      END
  WHERE id = p_credit_id;

  UPDATE public.supplier_invoices
  SET credit_applied_amount = COALESCE(credit_applied_amount, 0) + p_amount,
      updated_at = now()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'credit_id', p_credit_id,
    'invoice_id', p_invoice_id,
    'amount_applied', p_amount,
    'credit_remaining', v_remaining_credit - p_amount,
    'invoice_remaining', v_remaining_invoice - p_amount
  );
END;
$$;


--
-- Name: apply_order_discount(bigint, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_order_discount(p_order_id bigint, p_type text, p_value numeric, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order RECORD;
  v_note_trim TEXT;
  v_clamped_value NUMERIC(15,2);
  v_discount_base NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_updated_order RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'cashier')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_type IS NULL OR p_type NOT IN ('pct', 'vnd') THEN
    RAISE EXCEPTION 'discount_invalid_type' USING ERRCODE = '22023';
  END IF;

  IF p_value IS NULL OR p_value < 0 THEN
    RAISE EXCEPTION 'discount_invalid_value' USING ERRCODE = '22023';
  END IF;

  v_note_trim := COALESCE(trim(p_note), '');
  IF length(v_note_trim) < 3 THEN
    RAISE EXCEPTION 'discount_note_required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status,
         o.subtotal, o.service_charge, o.item_discount_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  v_discount_base := GREATEST(
    COALESCE(v_order.subtotal, 0) - COALESCE(v_order.item_discount_amount, 0),
    0
  );

  IF p_type = 'pct' THEN
    v_clamped_value := LEAST(p_value, 100);
  ELSE
    v_clamped_value := LEAST(p_value, v_discount_base);
  END IF;

  v_discount_amount := public.compute_discount_amount(
    p_type,
    v_clamped_value,
    v_discount_base
  );

  IF v_discount_amount = 0 THEN
    RAISE EXCEPTION 'discount_zero_amount' USING ERRCODE = '22023';
  END IF;

  UPDATE public.orders
     SET discount_type  = p_type,
         discount_value = v_clamped_value,
         discount_note  = v_note_trim,
         updated_at     = now()
   WHERE id = p_order_id
   RETURNING discount_type, discount_value, order_discount_amount,
             item_discount_amount, discount_amount, total_amount
   INTO v_updated_order;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_order.tenant_id, p_order_id, v_order.status, v_order.status, v_uid,
    'discount_applied: ' || p_type || ' ' || v_clamped_value::TEXT
      || ' (' || v_updated_order.order_discount_amount::TEXT || 'đ) :: '
      || v_note_trim
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'discount_type', v_updated_order.discount_type,
    'discount_value', v_updated_order.discount_value,
    'discount_amount', v_updated_order.order_discount_amount,
    'order_discount_amount', v_updated_order.order_discount_amount,
    'item_discount_amount', v_updated_order.item_discount_amount,
    'total_discount_amount', v_updated_order.discount_amount,
    'total_amount', v_updated_order.total_amount
  );
END;
$$;


--
-- Name: FUNCTION apply_order_discount(p_order_id bigint, p_type text, p_value numeric, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_order_discount(p_order_id bigint, p_type text, p_value numeric, p_note text) IS 'Set order-level discount on the post-item-discount base. Total discount is normalized by triggers.';


--
-- Name: apply_order_item_discount(bigint, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_order_item_discount(p_order_item_id bigint, p_type text, p_value numeric, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_row RECORD;
  v_note_trim TEXT;
  v_clamped_value NUMERIC(15,2);
  v_updated_item RECORD;
  v_order_totals RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_type IS NULL OR p_type NOT IN ('pct', 'vnd') THEN
    RAISE EXCEPTION 'discount_invalid_type' USING ERRCODE = '22023';
  END IF;

  IF p_value IS NULL OR p_value < 0 THEN
    RAISE EXCEPTION 'discount_invalid_value' USING ERRCODE = '22023';
  END IF;

  v_note_trim := COALESCE(trim(p_note), '');
  IF length(v_note_trim) < 3 THEN
    RAISE EXCEPTION 'discount_note_required' USING ERRCODE = '22023';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'cashier')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT oi.id AS order_item_id, oi.order_id, oi.tenant_id, oi.status AS item_status,
         oi.subtotal AS item_subtotal,
         o.branch_id, o.status AS order_status, o.payment_status
  INTO v_row
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id AND o.tenant_id = oi.tenant_id
  WHERE oi.id = p_order_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_row.order_id);

  SELECT oi.id AS order_item_id, oi.order_id, oi.tenant_id, oi.status AS item_status,
         oi.subtotal AS item_subtotal,
         o.branch_id, o.status AS order_status, o.payment_status
  INTO v_row
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id AND o.tenant_id = oi.tenant_id
  WHERE oi.id = p_order_item_id
  FOR UPDATE OF oi, o;

  IF v_row.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_row.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_row.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_row.order_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_row.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  IF v_row.item_status = 'cancelled' THEN
    RAISE EXCEPTION 'order item cancelled' USING ERRCODE = '22023';
  END IF;

  IF p_type = 'pct' THEN
    v_clamped_value := LEAST(p_value, 100);
  ELSE
    v_clamped_value := LEAST(p_value, COALESCE(v_row.item_subtotal, 0));
  END IF;

  IF public.compute_discount_amount(p_type, v_clamped_value, v_row.item_subtotal) = 0 THEN
    RAISE EXCEPTION 'discount_zero_amount' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
     SET discount_type = p_type,
         discount_value = v_clamped_value,
         discount_note = v_note_trim,
         updated_at = now()
   WHERE id = p_order_item_id
   RETURNING id, discount_type, discount_value, discount_amount, discount_note
   INTO v_updated_item;

  SELECT discount_amount, item_discount_amount, order_discount_amount, total_amount
  INTO v_order_totals
  FROM public.orders
  WHERE id = v_row.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_row.tenant_id, v_row.order_id, v_row.order_status, v_row.order_status, v_uid,
    'item_discount_applied: item ' || p_order_item_id::TEXT || ' '
      || p_type || ' ' || v_clamped_value::TEXT
      || ' (' || v_updated_item.discount_amount::TEXT || 'đ) :: ' || v_note_trim
  );

  RETURN jsonb_build_object(
    'order_id', v_row.order_id,
    'order_item_id', p_order_item_id,
    'discount_type', v_updated_item.discount_type,
    'discount_value', v_updated_item.discount_value,
    'discount_amount', v_updated_item.discount_amount,
    'discount_note', v_updated_item.discount_note,
    'order_discount_amount', v_order_totals.order_discount_amount,
    'item_discount_amount', v_order_totals.item_discount_amount,
    'total_discount_amount', v_order_totals.discount_amount,
    'total_amount', v_order_totals.total_amount
  );
END;
$$;


--
-- Name: FUNCTION apply_order_item_discount(p_order_item_id bigint, p_type text, p_value numeric, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_order_item_discount(p_order_item_id bigint, p_type text, p_value numeric, p_note text) IS 'Set item-level discount (% or VND) with required note. Blocks paid/terminal orders. Order total is normalized by triggers.';


--
-- Name: apply_template_to_user(uuid, bigint, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_template_to_user(p_target_user uuid, p_branch_id bigint, p_template_id bigint, p_valid_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id       BIGINT;
  v_target_tenant   BIGINT;
  v_target_bucket   TEXT;
  v_template        RECORD;
  v_perm_key        TEXT;
  v_perm_scope      TEXT;
  v_grant_branch_id BIGINT;
  v_inserted        INTEGER := 0;
  v_rows            INTEGER;
  v_from            TIMESTAMPTZ := COALESCE(p_valid_from, now());
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'staff:assign_permission') THEN
    RAISE EXCEPTION 'forbidden: missing staff:assign_permission' USING ERRCODE = '42501';
  END IF;

  IF p_target_user = auth.uid() THEN
    RAISE EXCEPTION 'cannot_self_assign_permissions' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.profiles WHERE id = auth.uid();
  SELECT tenant_id INTO v_target_tenant FROM public.profiles WHERE id = p_target_user;
  IF v_target_tenant IS NULL OR v_target_tenant <> v_tenant_id THEN
    RAISE EXCEPTION 'target_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF public.auth_is_owner(p_target_user) THEN
    RAISE EXCEPTION 'cannot_manage_owner_permissions' USING ERRCODE = '42501';
  END IF;

  SELECT private.staff_role_from_position_code(pos.code)
  INTO v_target_bucket
  FROM public.profiles p
  JOIN public.positions pos
    ON pos.id = p.position_id
   AND pos.tenant_id = p.tenant_id
  WHERE p.id = p_target_user;
  IF v_target_bucket IS NULL
     OR v_target_bucket NOT IN ('unassigned', 'unassigned') THEN
    v_target_bucket := NULL;
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches WHERE id = p_branch_id AND tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'branch_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF p_valid_until IS NOT NULL AND p_valid_until <= v_from THEN
    RAISE EXCEPTION 'invalid_validity_window' USING ERRCODE = '22023';
  END IF;

  SELECT id, tenant_id, permission_keys
  INTO v_template
  FROM public.role_templates
  WHERE id = p_template_id;

  IF v_template.id IS NULL OR v_template.tenant_id <> v_tenant_id THEN
    RAISE EXCEPTION 'template_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  FOREACH v_perm_key IN ARRAY v_template.permission_keys LOOP
    SELECT scope INTO v_perm_scope
    FROM public.permission_keys
    WHERE key = v_perm_key;

    IF v_perm_scope IS NULL THEN
      RAISE EXCEPTION 'unknown_permission_key_in_template' USING ERRCODE = '22023';
    END IF;

    v_grant_branch_id := CASE
      WHEN v_perm_scope = 'tenant' THEN NULL
      WHEN v_perm_scope = 'branch' THEN p_branch_id
      ELSE p_branch_id
    END;

    IF v_perm_scope = 'branch' AND v_grant_branch_id IS NULL THEN
      IF v_target_bucket IS NOT NULL THEN
        v_grant_branch_id := NULL;
      ELSE
        RAISE EXCEPTION 'permission_scope_requires_branch: %', v_perm_key USING ERRCODE = '22023';
      END IF;
    END IF;

    INSERT INTO public.staff_permissions (
      user_id, tenant_id, branch_id, permission_key, source_template, granted_by,
      valid_from, valid_until
    ) VALUES (
      p_target_user, v_tenant_id, v_grant_branch_id, v_perm_key, v_template.id, auth.uid(),
      v_from, p_valid_until
    )
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows > 0 THEN
      INSERT INTO public.permission_audit_log (
        tenant_id, actor_user_id, target_user_id, branch_id,
        permission_key, action, source_template_id, metadata
      ) VALUES (
        v_tenant_id, auth.uid(), p_target_user, v_grant_branch_id,
        v_perm_key, 'apply_template', v_template.id,
        jsonb_build_object(
          'template_id', v_template.id,
          'valid_from',  v_from,
          'valid_until', p_valid_until
        )
      );
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  RETURN v_inserted;
END;
$$;


--
-- Name: approve_employee_clock_out(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_employee_clock_out(p_attendance_id bigint, p_note text DEFAULT NULL::text) RETURNS TABLE(branch_id bigint, check_out timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_actor_role text := public.auth_role();
  v_actor_branch_id bigint;
  v_requester_profile_id uuid;
  v_requester_role text;
  v_branch_id bigint;
  v_branch_kind text;
  v_requested_at timestamptz;
  v_check_out timestamptz;
BEGIN
  SELECT profile.branch_id INTO v_actor_branch_id
  FROM public.profiles profile
  WHERE profile.id = v_actor AND profile.tenant_id = v_tenant_id AND profile.is_active;

  IF v_actor IS NULL OR v_actor_role NOT IN ('owner', 'branch_manager') THEN
    RAISE EXCEPTION 'checkout_approver_not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT requester.id, private.staff_role_from_position_code(position.code),
         attendance.branch_id, branch.branch_kind, attendance.checkout_requested_at
  INTO v_requester_profile_id, v_requester_role, v_branch_id, v_branch_kind, v_requested_at
  FROM public.attendance_records attendance
  JOIN public.employees employee
    ON employee.id = attendance.employee_id AND employee.tenant_id = attendance.tenant_id
  JOIN public.profiles requester
    ON requester.id = employee.profile_id AND requester.tenant_id = employee.tenant_id
  JOIN public.positions position
    ON position.id = requester.position_id AND position.tenant_id = requester.tenant_id
  LEFT JOIN public.branches branch
    ON branch.id = attendance.branch_id AND branch.tenant_id = attendance.tenant_id
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = v_tenant_id
    AND attendance.check_out IS NULL
    AND attendance.checkout_requested_at IS NOT NULL
  FOR UPDATE OF attendance;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'checkout_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_requester_profile_id = v_actor THEN
    RAISE EXCEPTION 'cannot_approve_own_checkout' USING ERRCODE = '42501';
  END IF;

  -- Floor branch → BM (or Owner). Accountant (null site) + central → Owner only.
  IF v_branch_kind = 'branch'
     AND v_requester_role IN ('cashier', 'chef', 'branch_staff')
     AND v_branch_id IS NOT NULL THEN
    IF v_actor_role <> 'owner'
       AND (v_actor_role <> 'branch_manager' OR v_actor_branch_id IS DISTINCT FROM v_branch_id
            OR NOT public.has_permission(v_branch_id, 'hr:approve_checkout')) THEN
      RAISE EXCEPTION 'checkout_approver_wrong_branch' USING ERRCODE = '42501';
    END IF;
  ELSIF v_actor_role <> 'owner' OR NOT public.auth_is_owner(v_actor) THEN
    RAISE EXCEPTION 'checkout_requires_owner' USING ERRCODE = '42501';
  END IF;

  UPDATE public.attendance_records attendance
  SET check_out = v_requested_at,
      checkout_approved_at = now(),
      checkout_approved_by = v_actor,
      checkout_approval_note = NULLIF(btrim(p_note), ''),
      updated_at = now()
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = v_tenant_id
    AND attendance.check_out IS NULL
  RETURNING attendance.check_out INTO v_check_out;

  RETURN QUERY SELECT v_branch_id, v_check_out;
END;
$$;


--
-- Name: FUNCTION approve_employee_clock_out(p_attendance_id bigint, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_employee_clock_out(p_attendance_id bigint, p_note text) IS 'Authenticated checkout approval using live tenant, branch, position, self-review, and hierarchy checks.';


--
-- Name: approve_inventory_count_slip(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_inventory_count_slip(p_slip_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  PERFORM slip.id
  FROM public.inventory_count_slips AS slip
  JOIN public.inventory_locations AS location
    ON location.id = slip.location_id
   AND location.tenant_id = slip.tenant_id
   AND location.branch_id = slip.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  JOIN public.branches AS branch
    ON branch.id = slip.branch_id
   AND branch.tenant_id = slip.tenant_id
   AND branch.is_active IS TRUE
  WHERE slip.id = p_slip_id
    AND slip.tenant_id = v_tenant
  FOR UPDATE OF slip, location;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'slip_location_invalid'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.stock_levels (
    tenant_id,
    branch_id,
    ingredient_id,
    location_id,
    current_quantity
  )
  SELECT DISTINCT
    slip.tenant_id,
    slip.branch_id,
    line.ingredient_id,
    slip.location_id,
    0
  FROM public.inventory_count_slips AS slip
  JOIN public.inventory_count_slip_lines AS line
    ON line.slip_id = slip.id
   AND line.tenant_id = slip.tenant_id
  WHERE slip.id = p_slip_id
    AND slip.tenant_id = v_tenant
  ON CONFLICT ON CONSTRAINT
    stock_levels_ingredient_branch_location_tenant_key
  DO NOTHING;

  PERFORM stock.id
  FROM public.stock_levels AS stock
  JOIN public.inventory_count_slips AS slip
    ON slip.tenant_id = stock.tenant_id
   AND slip.branch_id = stock.branch_id
   AND slip.location_id = stock.location_id
  JOIN public.inventory_count_slip_lines AS line
    ON line.slip_id = slip.id
   AND line.tenant_id = slip.tenant_id
   AND line.ingredient_id = stock.ingredient_id
  WHERE slip.id = p_slip_id
    AND slip.tenant_id = v_tenant
  ORDER BY stock.ingredient_id
  FOR UPDATE OF stock;

  RETURN private.execute_approve_inventory_count_slip(p_slip_id);
END;
$$;


--
-- Name: approve_leave_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_leave_request(p_request_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.leave_requests%ROWTYPE;
BEGIN
  v_request := private.authorize_leave_review(p_request_id);
  UPDATE public.leave_requests
  SET status = 'approved', reviewed_by = auth.uid(), reviewed_at = now()
  WHERE id = v_request.id AND status = 'pending';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_request_not_pending' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public.log_audit(
    'approve', 'leave_request', p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'approved')
  );
END;
$$;


--
-- Name: FUNCTION approve_leave_request(p_request_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_leave_request(p_request_id bigint) IS 'Manager approves a pending leave_request within branch scope. Paid/unpaid leave split is calculated by payroll.';


--
-- Name: approve_purchase_order(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_purchase_order(p_po_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_po record;
  v_synced_lines integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT purchase_order.*
  INTO v_po
  FROM public.purchase_orders purchase_order
  WHERE purchase_order.id = p_po_id
    AND purchase_order.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_po.branch_id, 'procurement:po_approve') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_po.status <> 'draft' THEN
    RAISE EXCEPTION 'purchase_order_not_draft' USING ERRCODE = '23514';
  END IF;
  IF v_po.purchase_request_id IS NULL
     AND v_po.source_grn_id IS NULL THEN
    RAISE EXCEPTION 'purchase_order_source_required'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.purchase_order_items item
    WHERE item.po_id = p_po_id
      AND item.tenant_id = v_tenant
  )
  OR EXISTS (
    SELECT 1
    FROM public.purchase_order_items item
    WHERE item.po_id = p_po_id
      AND item.tenant_id = v_tenant
      AND (
        item.quantity <= 0
        OR item.unit_price_est IS NULL
        OR item.unit_price_est < 0
      )
  ) THEN
    RAISE EXCEPTION 'purchase_order_lines_incomplete'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.purchase_order_items
  SET line_total = round(quantity * unit_price_est, 2)
  WHERE po_id = p_po_id
    AND tenant_id = v_tenant;

  -- Compatibility only: price an existing retrospective draft GRN.
  WITH synced AS (
    UPDATE public.grn_items grn_item
    SET unit_cost = po_item.unit_price_est,
        total_cost = round(
          (grn_item.received_quantity - grn_item.rejected_quantity)
          * po_item.unit_price_est,
          2
        )
    FROM public.purchase_order_items po_item
    WHERE v_po.source_grn_id IS NOT NULL
      AND grn_item.grn_id = v_po.source_grn_id
      AND grn_item.tenant_id = v_tenant
      AND po_item.po_id = p_po_id
      AND po_item.tenant_id = v_tenant
      AND po_item.ingredient_id = grn_item.ingredient_id
      AND po_item.entry_unit_id IS NOT DISTINCT FROM grn_item.entry_unit_id
    RETURNING grn_item.id
  )
  SELECT count(*)::integer
  INTO v_synced_lines
  FROM synced;

  UPDATE public.purchase_orders
  SET status = 'sent',
      ordered_at = now(),
      updated_at = now()
  WHERE id = p_po_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'id', p_po_id,
    'status', 'sent',
    'grn_unit_cost_synced_lines', v_synced_lines
  );
END;
$$;


--
-- Name: FUNCTION approve_purchase_order(p_po_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_purchase_order(p_po_id bigint) IS 'Approve PO draft→sent. Syncs unit_price_est into draft GRN lines matching PO supplier (source_grn_id or legacy po_id).';


--
-- Name: approve_waste(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_waste(p_issue_id bigint, p_decision text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_issue public.stock_issues%ROWTYPE;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'decision must be approved or rejected'
      USING ERRCODE = '22023';
  END IF;

  SELECT issue.*
  INTO v_issue
  FROM public.stock_issues AS issue
  WHERE issue.id = p_issue_id
    AND issue.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_issue.issue_type <> 'writeoff' THEN
    RAISE EXCEPTION 'issue is not a writeoff'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(
    v_issue.branch_id,
    'inventory:waste_approve'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_issue.approval_status <> 'pending' THEN
    RAISE EXCEPTION 'issue is not pending approval (status=%)',
      v_issue.approval_status
      USING ERRCODE = '22023';
  END IF;
  IF v_issue.created_by = v_uid
     AND NOT public.has_permission(
       NULL,
       'accounting:period_reopen'
     ) THEN
    RAISE EXCEPTION
      'self-approval forbidden: approver cannot be the creator'
      USING ERRCODE = '42501';
  END IF;

  IF p_decision = 'approved' THEN
    UPDATE public.stock_issues
    SET approval_status = 'approved',
        approved_by = v_uid,
        approved_at = now(),
        notes = coalesce(notes, '')
          || CASE
               WHEN p_note IS NOT NULL
                 THEN E'\n[approved by '
                   || v_uid::text
                   || '] '
                   || p_note
               ELSE ''
             END
    WHERE id = p_issue_id
      AND tenant_id = v_tenant;

    PERFORM public._post_writeoff_movements(p_issue_id);
  ELSE
    UPDATE public.stock_issues
    SET approval_status = 'rejected',
        approved_by = v_uid,
        approved_at = now(),
        status = 'cancelled',
        notes = coalesce(notes, '')
          || CASE
               WHEN p_note IS NOT NULL
                 THEN E'\n[rejected by '
                   || v_uid::text
                   || '] '
                   || p_note
               ELSE ''
             END
    WHERE id = p_issue_id
      AND tenant_id = v_tenant;
  END IF;
END;
$$;


--
-- Name: assert_bank_deposit_evidence(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_bank_deposit_evidence(p_tenant_id bigint, p_expense_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_expense public.expenses%ROWTYPE;
BEGIN
  SELECT *
  INTO v_expense
  FROM public.expenses expense
  WHERE expense.tenant_id = p_tenant_id
    AND expense.id = p_expense_id;

  IF NOT FOUND OR v_expense.category <> 'bank_deposit' THEN
    RETURN;
  END IF;

  IF v_expense.payment_method <> 'cash'
    OR NOT (
      EXISTS (
        SELECT 1
        FROM public.webhook_events event
        WHERE event.tenant_id = v_expense.tenant_id
          AND event.provider = 'sepay'
          AND event.expense_id = v_expense.id
          AND event.signature_valid IS TRUE
          AND event.processing_status <> 'failed'
          AND event.payment_id IS NULL
          AND lower(COALESCE(event.payload->>'transferType', '')) = 'in'
          AND COALESCE(event.payload->>'transferAmount', '')
            ~ '^[0-9]+(\.[0-9]+)?$'
          AND (event.payload->>'transferAmount')::numeric = v_expense.amount
      )
      OR EXISTS (
        SELECT 1
        FROM public.bank_transaction_reconciliation_matches match
        JOIN public.bank_transactions transaction
          ON transaction.id = match.bank_transaction_id
         AND transaction.tenant_id = match.tenant_id
        WHERE match.tenant_id = v_expense.tenant_id
          AND match.expense_id = v_expense.id
          AND match.matched_amount = v_expense.amount
          AND transaction.transfer_type = 'in'
          AND transaction.amount = v_expense.amount
      )
    )
  THEN
    RAISE EXCEPTION 'bank_deposit_requires_verified_sepay_event'
      USING ERRCODE = '23514';
  END IF;
END;
$_$;


--
-- Name: assert_refund_webhook_allocation(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_refund_webhook_allocation(p_event_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_event public.webhook_events%ROWTYPE;
  v_refund_count integer;
  v_refund_total numeric;
  v_refund_tenant_id bigint;
  v_refund_max_tenant_id bigint;
  v_refund_shape_valid boolean;
  v_transfer_amount numeric;
BEGIN
  IF p_event_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    count(*),
    COALESCE(sum(refund.amount), 0),
    min(refund.tenant_id),
    max(refund.tenant_id),
    bool_and(
      refund.status = 'approved'
      AND refund.payout_method = 'bank_transfer'
    )
  INTO
    v_refund_count,
    v_refund_total,
    v_refund_tenant_id,
    v_refund_max_tenant_id,
    v_refund_shape_valid
  FROM public.refunds refund
  WHERE refund.webhook_event_id = p_event_id;

  IF v_refund_count = 0 THEN
    RETURN;
  END IF;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id;

  IF NOT FOUND
    OR v_refund_shape_valid IS NOT TRUE
    OR v_refund_tenant_id IS DISTINCT FROM v_refund_max_tenant_id
    OR v_event.tenant_id <> v_refund_tenant_id
    OR v_event.provider <> 'sepay'
    OR v_event.signature_valid IS NOT TRUE
    OR v_event.processing_status = 'failed'
    OR v_event.order_id IS NOT NULL
    OR v_event.payment_id IS NOT NULL
    OR v_event.expense_id IS NOT NULL
    OR lower(COALESCE(v_event.payload->>'transferType', '')) <> 'out'
    OR EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches expense_match
      WHERE expense_match.tenant_id = v_refund_tenant_id
        AND expense_match.webhook_event_id = p_event_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.supplier_payments supplier_payment
      WHERE supplier_payment.tenant_id = v_refund_tenant_id
        AND supplier_payment.webhook_event_id = p_event_id
    )
  THEN
    RAISE EXCEPTION 'webhook_event_already_linked' USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN COALESCE(v_event.payload->>'transferAmount', '')
      ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN abs((v_event.payload->>'transferAmount')::numeric)
    ELSE NULL
  END
  INTO v_transfer_amount;

  IF v_transfer_amount IS NULL OR v_refund_total <> v_transfer_amount THEN
    RAISE EXCEPTION 'refund_amount_mismatch' USING ERRCODE = '23514';
  END IF;
END;
$_$;


--
-- Name: assert_sepay_expense_match_evidence(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_sepay_expense_match_evidence(p_tenant_id bigint, p_event_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_event public.webhook_events%ROWTYPE;
  v_match_count integer;
  v_expense_id bigint;
  v_has_historical_split boolean;
  v_transfer_amount numeric;
  v_expense_total numeric;
  v_component_total numeric;
  v_component_valid boolean;
BEGIN
  SELECT
    count(*)::integer,
    min(m.expense_id)
  INTO v_match_count, v_expense_id
  FROM public.bank_transaction_expense_matches m
  WHERE m.tenant_id = p_tenant_id
    AND m.webhook_event_id = p_event_id;

  IF v_match_count = 0 THEN
    SELECT *
    INTO v_event
    FROM public.webhook_events we
    WHERE we.tenant_id = p_tenant_id
      AND we.id = p_event_id;

    IF NOT FOUND OR v_event.expense_id IS NULL THEN
      RETURN;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.expenses e
      WHERE e.tenant_id = v_event.tenant_id
        AND e.id = v_event.expense_id
        AND e.category = 'bank_deposit'
    ) THEN
      RETURN;
    END IF;

    RAISE EXCEPTION 'webhook_expense_link_drift'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches m
    JOIN public.expenses e
      ON e.tenant_id = m.tenant_id
     AND e.id = m.expense_id
    WHERE m.tenant_id = p_tenant_id
      AND m.webhook_event_id = p_event_id
      AND (
        e.payment_method <> 'transfer'
        OR e.category = 'bank_deposit'
      )
  ) THEN
    RAISE EXCEPTION 'sepay_expense_match_shape_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches current_match
    JOIN public.bank_transaction_expense_matches sibling
      ON sibling.tenant_id = current_match.tenant_id
     AND sibling.expense_id = current_match.expense_id
     AND sibling.webhook_event_id <> current_match.webhook_event_id
    WHERE current_match.tenant_id = p_tenant_id
      AND current_match.webhook_event_id = p_event_id
  )
  INTO v_has_historical_split;

  SELECT *
  INTO v_event
  FROM public.webhook_events we
  WHERE we.tenant_id = p_tenant_id
    AND we.id = p_event_id;

  IF NOT FOUND
    OR v_event.provider <> 'sepay'
    OR v_event.signature_valid IS NOT TRUE
    OR v_event.processing_status IS NOT DISTINCT FROM 'failed'
    OR v_event.payment_id IS NOT NULL
    OR v_event.expense_id IS DISTINCT FROM v_expense_id
    OR lower(COALESCE(v_event.payload->>'transferType', '')) <> 'out'
    OR COALESCE(v_event.payload->>'transferAmount', '')
      !~ '^-?[0-9]+(\.[0-9]+)?$'
  THEN
    RAISE EXCEPTION 'sepay_expense_match_evidence_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_transfer_amount := abs((v_event.payload->>'transferAmount')::numeric);
  IF v_transfer_amount <= 0 THEN
    RAISE EXCEPTION 'sepay_expense_match_evidence_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF v_has_historical_split THEN
    IF v_match_count <> 1 THEN
      RAISE EXCEPTION 'historical_expense_match_graph_ambiguous'
        USING ERRCODE = '23514';
    END IF;

    SELECT
      e.amount,
      sum(
        CASE
          WHEN COALESCE(we.payload->>'transferAmount', '')
            ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN abs((we.payload->>'transferAmount')::numeric)
          ELSE 0
        END
      ),
      bool_and(
        e.payment_method = 'transfer'
        AND e.category <> 'bank_deposit'
        AND we.provider = 'sepay'
        AND we.signature_valid IS TRUE
        AND we.processing_status IS DISTINCT FROM 'failed'
        AND we.payment_id IS NULL
        AND lower(COALESCE(we.payload->>'transferType', '')) = 'out'
        AND COALESCE(we.payload->>'transferAmount', '')
          ~ '^-?[0-9]+(\.[0-9]+)?$'
      )
    INTO v_expense_total, v_component_total, v_component_valid
    FROM public.expenses e
    JOIN public.bank_transaction_expense_matches m
      ON m.tenant_id = e.tenant_id
     AND m.expense_id = e.id
    JOIN public.webhook_events we
      ON we.tenant_id = m.tenant_id
     AND we.id = m.webhook_event_id
    WHERE e.tenant_id = p_tenant_id
      AND e.id = v_expense_id
    GROUP BY e.amount;

    IF v_component_valid IS NOT TRUE
      OR v_component_total <> v_expense_total
    THEN
      RAISE EXCEPTION 'historical_split_expense_amount_mismatch'
        USING ERRCODE = '23514';
    END IF;

    RETURN;
  END IF;

  SELECT COALESCE(sum(e.amount), 0)
  INTO v_expense_total
  FROM public.bank_transaction_expense_matches m
  JOIN public.expenses e
    ON e.tenant_id = m.tenant_id
   AND e.id = m.expense_id
  WHERE m.tenant_id = p_tenant_id
    AND m.webhook_event_id = p_event_id;

  IF v_expense_total <> v_transfer_amount THEN
    RAISE EXCEPTION 'expense_amount_mismatch' USING ERRCODE = '23514';
  END IF;
END;
$_$;


--
-- Name: assign_auditor(bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_auditor(p_session_id bigint, p_auditor_id uuid, p_auditor_branch_id bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_branch bigint;
  v_status text;
  v_profile_branch bigint;
  v_auditor_branch bigint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT session.branch_id, session.status
  INTO v_branch, v_status
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant
  FOR UPDATE OF session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_status <> 'in_progress' THEN
    RAISE EXCEPTION 'stocktake_session_not_in_progress'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(
    v_branch,
    'inventory:stocktake_recount'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT profile.branch_id
  INTO v_profile_branch
  FROM public.profiles AS profile
  WHERE profile.id = p_auditor_id
    AND profile.tenant_id = v_tenant
    AND coalesce(profile.is_active, TRUE) IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'auditor_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_auditor_branch := coalesce(
    p_auditor_branch_id,
    v_profile_branch
  );
  IF v_profile_branch IS NOT NULL
     AND v_auditor_branch IS DISTINCT FROM v_profile_branch THEN
    RAISE EXCEPTION 'auditor_branch_mismatch'
      USING ERRCODE = '23514';
  END IF;
  IF v_auditor_branch IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.branches AS branch
       WHERE branch.id = v_auditor_branch
         AND branch.tenant_id = v_tenant
         AND branch.is_active IS TRUE
         AND branch.branch_kind IN (
           'branch',
           'central_supply',
           'central_kitchen'
         )
     ) THEN
    RAISE EXCEPTION 'auditor_branch_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.stocktake_sessions
  SET auditor_id = p_auditor_id,
      auditor_branch_id = v_auditor_branch,
      is_unaudited = FALSE
  WHERE id = p_session_id
    AND tenant_id = v_tenant
    AND status = 'in_progress';
END;
$$;


--
-- Name: attach_print_document_to_payload(bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_print_document_to_payload(p_tenant_id bigint, p_branch_id bigint, p_kind text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_template RECORD;
  v_template_id BIGINT := 0;
  v_template_version INT := 1;
  v_paper_width_mm INT := 80;
  v_font_profile TEXT := 'thermal_vietnamese';
  v_content JSONB := public.print_template_default_content(p_kind);
  v_document JSONB;
BEGIN
  IF p_payload ? 'document' THEN RETURN p_payload; END IF;

  SELECT * INTO v_template FROM public.resolve_print_template_version(p_tenant_id, p_branch_id, p_kind);

  IF FOUND THEN
    v_template_id := v_template.template_id;
    v_template_version := v_template.template_version;
    v_paper_width_mm := v_template.paper_width_mm;
    v_font_profile := v_template.font_profile;
    v_content := v_template.content;
  END IF;

  v_document := public.materialize_print_document(
    p_kind, p_payload, v_template_id, v_template_version,
    v_paper_width_mm, v_font_profile, v_content);

  RETURN p_payload || jsonb_build_object(
    'template_version', v_template_id::TEXT || ':' || v_template_version::TEXT,
    'document', v_document);
END;
$$;


--
-- Name: FUNCTION attach_print_document_to_payload(p_tenant_id bigint, p_branch_id bigint, p_kind text, p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.attach_print_document_to_payload(p_tenant_id bigint, p_branch_id bigint, p_kind text, p_payload jsonb) IS 'Resolve active print template and materialize a schema_version=1 document AST into the print payload.';


--
-- Name: attach_supplier_invoice_vat_evidence(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_supplier_invoice_vat_evidence(p_invoice_id bigint, p_storage_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_path text := NULLIF(pg_catalog.btrim(p_storage_path), '');
  v_prefix text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT (
      public.auth_is_owner(v_uid)
      OR public.has_position('accountant')
    )
    OR NOT (
      public.has_permission_any('finance:ap_pay')
      OR public.has_permission_any('procurement:invoice_create')
    ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_invoice_id IS NULL OR v_path IS NULL THEN
    RAISE EXCEPTION 'invalid_vat_invoice_attachment' USING ERRCODE = '22023';
  END IF;

  IF pg_catalog.char_length(v_path) > 500
     OR v_path ~ '[[:space:]]'
     OR v_path LIKE '%..%' THEN
    RAISE EXCEPTION 'invalid_vat_invoice_attachment_path' USING ERRCODE = '22023';
  END IF;

  v_prefix := v_tenant::text || '/';
  IF v_path NOT LIKE v_prefix || '%' THEN
    RAISE EXCEPTION 'vat_invoice_attachment_tenant_mismatch'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.supplier_invoices AS si
  SET vat_invoice_attachment_path = v_path,
      updated_at = pg_catalog.now()
  WHERE si.id = p_invoice_id
    AND si.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: attendance_shift_workdays(timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_shift_workdays(p_check_in timestamp with time zone, p_check_out timestamp with time zone, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_overlap_start timestamptz;
  v_overlap_end timestamptz;
  v_worked_seconds numeric;
  v_shift_seconds numeric;
BEGIN
  IF p_check_in IS NULL
     OR p_check_out IS NULL
     OR p_scheduled_start IS NULL
     OR p_scheduled_end IS NULL
     OR p_check_out <= p_check_in
     OR p_scheduled_end <= p_scheduled_start THEN
    RETURN 0;
  END IF;

  v_overlap_start := GREATEST(p_check_in, p_scheduled_start);
  v_overlap_end := LEAST(p_check_out, p_scheduled_end);
  IF v_overlap_end <= v_overlap_start THEN
    RETURN 0;
  END IF;

  v_worked_seconds := EXTRACT(EPOCH FROM (v_overlap_end - v_overlap_start));
  v_shift_seconds := EXTRACT(EPOCH FROM (p_scheduled_end - p_scheduled_start));
  IF v_shift_seconds <= 0 THEN
    RETURN 0;
  END IF;

  RETURN LEAST(1.0, ROUND((v_worked_seconds / v_shift_seconds)::numeric, 1));
END;
$$;


