--
-- Name: auto_close_periods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_close_periods() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_today DATE; v_day INT; v_prior DATE; v_year INT; v_month INT; v_count INT := 0; v_row RECORD;
BEGIN
  v_today := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::DATE;
  v_day := EXTRACT(DAY FROM v_today)::INT;
  v_prior := (date_trunc('month', v_today) - INTERVAL '1 month')::DATE;
  v_year := EXTRACT(YEAR FROM v_prior)::INT;
  v_month := EXTRACT(MONTH FROM v_prior)::INT;
  IF v_day < 5 THEN RETURN 0; END IF;
  FOR v_row IN SELECT id FROM public.tenants LOOP
    INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at)
    VALUES (v_row.id, v_year, v_month, now())
    ON CONFLICT (tenant_id, year, month) DO UPDATE
      SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at);
    v_count := v_count + 1;
  END LOOP;
  IF v_day >= 15 THEN
    FOR v_row IN SELECT id FROM public.tenants LOOP
      UPDATE public.accounting_periods SET hard_closed_at = COALESCE(hard_closed_at, now())
       WHERE tenant_id = v_row.id AND year = v_year AND month = v_month;
    END LOOP;
  END IF;
  RETURN v_count;
END; $$;


--
-- Name: FUNCTION auto_close_periods(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_close_periods() IS 'Daily automation — day 5+ soft close, day 15+ hard close. Idempotent.';


--
-- Name: bill_line_items(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bill_line_items(p_order_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(line ORDER BY first_id), '[]'::jsonb)
  FROM (
    SELECT
      jsonb_build_object(
        'item_name',     oi.item_name,
        'variant_name',  oi.variant_name,
        'category_type', mc.type,
        'quantity',      SUM(oi.quantity),
        'unit_price',    oi.unit_price,
        'modifiers',     oi.modifiers,
        'sides',         oi.sides,
        'subtotal',      SUM(oi.subtotal),
        'note',          NULL::text
      ) AS line,
      MIN(oi.id) AS first_id
    FROM public.order_items oi
    LEFT JOIN public.menu_items mi
      ON mi.id = oi.menu_item_id
     AND mi.tenant_id = oi.tenant_id
    LEFT JOIN public.menu_categories mc
      ON mc.id = mi.category_id
     AND mc.tenant_id = oi.tenant_id
    WHERE oi.order_id = p_order_id
      AND oi.status <> 'cancelled'
    GROUP BY
      oi.menu_item_id, oi.variant_id, oi.item_name, oi.variant_name,
      oi.unit_price, oi.modifiers, oi.sides, mc.type
  ) grouped;
$$;


--
-- Name: FUNCTION bill_line_items(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bill_line_items(p_order_id bigint) IS 'Payment-bill (provisional + receipt) line items: one entry per distinct sold product (menu_item, variant, unit_price, modifiers, sides, category), quantity/subtotal summed. Item note is not part of the key — it is hidden on bills — so a noted and an un-noted portion of the same dish merge into one line. Not for HĐĐT (separate builder).';


--
-- Name: branch_manager_approve_consumption_report(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.branch_manager_approve_consumption_report(p_tenant_id bigint, p_report_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_report record;
  v_line record;
  v_issue_id bigint;
  v_issue_number text;
  v_source_location_id bigint;
  v_current_quantity numeric(15,3);
  v_wac numeric(15,2);
  v_line_count integer;
  v_quantity_base numeric(15,3);
  v_entry_unit_id bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL OR v_tenant <> p_tenant_id THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT report.*
  INTO v_report
  FROM public.attendance_consumption_reports AS report
  WHERE report.id = p_report_id
    AND report.tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'consumption_report_not_found'
      USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_report.branch_id,
    'hr:approve_checkout'
  ) THEN
    RAISE EXCEPTION 'forbidden_checkout_approval'
      USING ERRCODE = '42501';
  END IF;
  IF v_report.status IN ('approved', 'applied') THEN
    RETURN jsonb_build_object(
      'ok', TRUE,
      'report_id', p_report_id,
      'stock_issue_id', v_report.stock_issue_id,
      'status', v_report.status
    );
  END IF;
  IF v_report.status <> 'submitted' THEN
    RAISE EXCEPTION 'consumption_report_not_submitted'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*)
  INTO v_line_count
  FROM public.attendance_consumption_report_lines AS line
  WHERE line.tenant_id = p_tenant_id
    AND line.report_id = p_report_id;

  IF v_report.no_consumption IS TRUE AND v_line_count = 0 THEN
    UPDATE public.attendance_consumption_reports
    SET status = 'approved',
        reviewed_by = v_uid,
        reviewed_at = now(),
        review_note = NULL
    WHERE id = p_report_id
      AND tenant_id = p_tenant_id;

    RETURN jsonb_build_object(
      'ok', TRUE,
      'report_id', p_report_id,
      'stock_issue_id', NULL,
      'no_consumption', TRUE,
      'line_count', 0
    );
  END IF;
  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'consumption_lines_required'
      USING ERRCODE = '22023';
  END IF;

  SELECT location.id
  INTO v_source_location_id
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = p_tenant_id
    AND location.branch_id = v_report.branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE;

  IF v_source_location_id IS NULL THEN
    RAISE EXCEPTION 'consumption_warehouse_missing'
      USING ERRCODE = 'not_null_violation';
  END IF;

  FOR v_line IN
    SELECT line.*
    FROM public.attendance_consumption_report_lines AS line
    WHERE line.tenant_id = p_tenant_id
      AND line.report_id = p_report_id
    ORDER BY line.sort_order, line.id
  LOOP
    v_entry_unit_id := coalesce(
      v_line.entry_unit_id,
      (
        SELECT ingredient_unit.unit_id
        FROM public.ingredient_units AS ingredient_unit
        JOIN public.units AS unit
          ON unit.id = ingredient_unit.unit_id
         AND unit.tenant_id = ingredient_unit.tenant_id
         AND unit.is_active IS TRUE
        WHERE ingredient_unit.tenant_id = p_tenant_id
          AND ingredient_unit.ingredient_id = v_line.ingredient_id
          AND ingredient_unit.is_base IS TRUE
          AND ingredient_unit.is_active IS TRUE
        ORDER BY ingredient_unit.sort_order, ingredient_unit.id
        LIMIT 1
      )
    );

    IF v_entry_unit_id IS NULL THEN
      RAISE EXCEPTION 'entry_unit_not_found:%',
        v_line.ingredient_id
        USING ERRCODE = 'foreign_key_violation';
    END IF;

    v_quantity_base := round(public.inv_to_base(
      v_line.ingredient_id,
      v_entry_unit_id,
      v_line.quantity
    ), 3);

    SELECT stock.current_quantity, stock.avg_unit_cost
    INTO v_current_quantity, v_wac
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = p_tenant_id
      AND stock.branch_id = v_report.branch_id
      AND stock.location_id = v_source_location_id
      AND stock.ingredient_id = v_line.ingredient_id
    FOR UPDATE;

    IF NOT FOUND OR v_wac IS NULL THEN
      RAISE EXCEPTION 'wac_not_ready_for_%',
        v_line.ingredient_id
        USING ERRCODE = '22023';
    END IF;
    IF coalesce(v_current_quantity, 0) < v_quantity_base THEN
      RAISE EXCEPTION 'insufficient_stock_for_%',
        v_line.ingredient_id
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  v_issue_number := 'THB-' || p_report_id::text;

  INSERT INTO public.stock_issues (
    tenant_id,
    branch_id,
    issue_number,
    issue_type,
    status,
    notes,
    issued_at,
    created_by,
    source_location_id,
    target_location_id,
    approval_status,
    approved_by,
    approved_at,
    source_type,
    source_ref
  )
  VALUES (
    p_tenant_id,
    v_report.branch_id,
    v_issue_number,
    'consumption',
    'draft',
    coalesce(v_report.note, 'Tiêu hao vận hành trong ngày'),
    now(),
    v_uid,
    v_source_location_id,
    NULL,
    'approved',
    v_uid,
    now(),
    'hrm_consumption',
    jsonb_build_object(
      'source', 'attendance_consumption_report',
      'source_label', 'HRM - Tiêu hao vận hành trong ngày',
      'report_id', p_report_id,
      'attendance_record_id', v_report.attendance_record_id,
      'employee_id', v_report.employee_id,
      'branch_id', v_report.branch_id,
      'reviewed_by', v_uid,
      'reviewed_at', now()
    )
  )
  RETURNING id INTO v_issue_id;

  FOR v_line IN
    SELECT line.*
    FROM public.attendance_consumption_report_lines AS line
    WHERE line.tenant_id = p_tenant_id
      AND line.report_id = p_report_id
    ORDER BY line.sort_order, line.id
  LOOP
    v_entry_unit_id := coalesce(
      v_line.entry_unit_id,
      (
        SELECT ingredient_unit.unit_id
        FROM public.ingredient_units AS ingredient_unit
        JOIN public.units AS unit
          ON unit.id = ingredient_unit.unit_id
         AND unit.tenant_id = ingredient_unit.tenant_id
         AND unit.is_active IS TRUE
        WHERE ingredient_unit.tenant_id = p_tenant_id
          AND ingredient_unit.ingredient_id = v_line.ingredient_id
          AND ingredient_unit.is_base IS TRUE
          AND ingredient_unit.is_active IS TRUE
        ORDER BY ingredient_unit.sort_order, ingredient_unit.id
        LIMIT 1
      )
    );
    v_quantity_base := round(public.inv_to_base(
      v_line.ingredient_id,
      v_entry_unit_id,
      v_line.quantity
    ), 3);

    SELECT stock.avg_unit_cost
    INTO v_wac
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = p_tenant_id
      AND stock.branch_id = v_report.branch_id
      AND stock.location_id = v_source_location_id
      AND stock.ingredient_id = v_line.ingredient_id;

    INSERT INTO public.stock_issue_items (
      tenant_id,
      issue_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      unit_cost,
      reason
    )
    VALUES (
      p_tenant_id,
      v_issue_id,
      v_line.ingredient_id,
      v_line.quantity,
      v_entry_unit_id,
      v_wac,
      v_line.note
    );

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      movement_subtype,
      quantity_change,
      unit_cost,
      reason,
      created_by,
      issue_id,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    VALUES (
      p_tenant_id,
      v_report.branch_id,
      v_line.ingredient_id,
      'consumption',
      'sale_consumption',
      -v_quantity_base,
      v_wac,
      coalesce(
        v_line.note,
        v_report.note,
        'Tiêu hao vận hành trong ngày'
      ),
      v_uid,
      v_issue_id,
      v_source_location_id,
      v_entry_unit_id,
      v_line.quantity
    );
  END LOOP;

  UPDATE public.stock_issues
  SET status = 'confirmed',
      updated_at = now()
  WHERE id = v_issue_id
    AND tenant_id = p_tenant_id;

  UPDATE public.attendance_consumption_reports
  SET status = 'applied',
      reviewed_by = v_uid,
      reviewed_at = now(),
      review_note = NULL,
      stock_issue_id = v_issue_id
  WHERE id = p_report_id
    AND tenant_id = p_tenant_id;

  RETURN jsonb_build_object(
    'ok', TRUE,
    'report_id', p_report_id,
    'stock_issue_id', v_issue_id,
    'line_count', v_line_count
  );
END;
$$;


--
-- Name: FUNCTION branch_manager_approve_consumption_report(p_tenant_id bigint, p_report_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.branch_manager_approve_consumption_report(p_tenant_id bigint, p_report_id bigint) IS 'Approves a submitted consumption report and posts stock consumption from the site warehouse.';


--
-- Name: branch_manager_request_consumption_adjustment(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.branch_manager_request_consumption_adjustment(p_tenant_id bigint, p_report_id bigint, p_review_note text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_report record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_tenant IS NULL OR v_tenant <> p_tenant_id THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(btrim(COALESCE(p_review_note, '')), '') IS NULL THEN
    RAISE EXCEPTION 'review_note_required' USING ERRCODE = '22023';
  END IF;

  SELECT r.*, ar.id AS attendance_id
  INTO v_report
  FROM public.attendance_consumption_reports r
  JOIN public.attendance_records ar
    ON ar.id = r.attendance_record_id
   AND ar.tenant_id = r.tenant_id
  WHERE r.id = p_report_id
    AND r.tenant_id = p_tenant_id
  FOR UPDATE OF r, ar;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'consumption_report_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_report.branch_id, 'hr:approve_checkout') THEN
    RAISE EXCEPTION 'forbidden_checkout_approval' USING ERRCODE = '42501';
  END IF;

  IF v_report.status NOT IN ('submitted', 'needs_changes') THEN
    RAISE EXCEPTION 'consumption_report_not_reviewable' USING ERRCODE = '22023';
  END IF;

  UPDATE public.attendance_consumption_reports
  SET status = 'needs_changes',
      reviewed_by = v_uid,
      reviewed_at = now(),
      review_note = NULLIF(btrim(p_review_note), '')
  WHERE id = p_report_id
    AND tenant_id = p_tenant_id;

  UPDATE public.attendance_records
  SET checkout_requested_at = NULL,
      checkout_requested_by_role = NULL,
      checkout_approval_target_roles = ARRAY[]::text[],
      updated_at = now()
  WHERE id = v_report.attendance_id
    AND tenant_id = p_tenant_id
    AND check_out IS NULL;

  UPDATE public.attendance_checklist_items
  SET is_done = false,
      completed_at = NULL
  WHERE tenant_id = p_tenant_id
    AND attendance_record_id = v_report.attendance_id
    AND task_kind = 'consumption_report';

  RETURN p_report_id;
END;
$$;


--
-- Name: FUNCTION branch_manager_request_consumption_adjustment(p_tenant_id bigint, p_report_id bigint, p_review_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.branch_manager_request_consumption_adjustment(p_tenant_id bigint, p_report_id bigint, p_review_note text) IS 'Checkout approver requests correction, reopens the consumption checklist item, and clears pending checkout for employee resubmission.';


--
-- Name: branch_menu_limit_availability(bigint, bigint, date, boolean, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.branch_menu_limit_availability(p_tenant_id bigint, p_branch_id bigint, p_limit_date date, p_stock_gate_enabled boolean DEFAULT false, p_exclude_hold_tokens uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(menu_item_id bigint, item_name text, category_id bigint, category_name text, base_price numeric, limit_id bigint, limit_date date, is_disabled boolean, sold_today integer, stock_capacity integer, manual_limit_quantity integer, pending_unfinalized_demand integer, active_hold_demand integer, available_to_sell integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  WITH order_line_demand AS (
    SELECT oi.menu_item_id::bigint AS menu_item_id,
           oi.quantity::integer AS quantity
    FROM public.orders o
    JOIN public.order_items oi
      ON oi.order_id = o.id
     AND oi.tenant_id = o.tenant_id
    WHERE o.tenant_id = p_tenant_id
      AND o.branch_id = p_branch_id
      AND (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = p_limit_date
      AND o.status NOT IN ('completed', 'cancelled')
      AND oi.status <> 'cancelled'

    UNION ALL

    SELECT (s.elem ->> 'side_item_id')::bigint AS menu_item_id,
           (oi.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::integer, 1))::integer AS quantity
    FROM public.orders o
    JOIN public.order_items oi
      ON oi.order_id = o.id
     AND oi.tenant_id = o.tenant_id
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(oi.sides, '[]'::jsonb)) AS s(elem)
    WHERE o.tenant_id = p_tenant_id
      AND o.branch_id = p_branch_id
      AND (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = p_limit_date
      AND o.status NOT IN ('completed', 'cancelled')
      AND oi.status <> 'cancelled'
      AND s.elem ? 'side_item_id'
      AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
  ),
  pending_item AS (
    SELECT d.menu_item_id,
           SUM(d.quantity)::integer AS quantity
    FROM order_line_demand d
    GROUP BY d.menu_item_id
  ),
  holds_item AS (
    SELECT h.menu_item_id,
           SUM(h.quantity)::integer AS quantity
    FROM public.branch_menu_item_daily_holds h
    WHERE h.tenant_id = p_tenant_id
      AND h.branch_id = p_branch_id
      AND h.limit_date = p_limit_date
      AND h.committed_at IS NULL
      AND h.released_at IS NULL
      AND h.expires_at > now()
      AND (p_exclude_hold_tokens IS NULL OR h.hold_token <> ALL(p_exclude_hold_tokens))
    GROUP BY h.menu_item_id
  ),
  recipe_lines AS (
    SELECT
      r.menu_item_id,
      r.ingredient_id,
      CASE
        WHEN r.entry_unit_id IS NULL THEN r.quantity / r.yield_factor
        WHEN iu.id IS NULL THEN NULL::numeric
        ELSE (r.quantity / r.yield_factor) * iu.to_base_factor
      END AS per_portion_qty,
      (r.entry_unit_id IS NOT NULL AND iu.id IS NULL) AS line_missing_config
    FROM public.recipes r
    LEFT JOIN public.ingredient_units iu
      ON iu.tenant_id = p_tenant_id
     AND iu.ingredient_id = r.ingredient_id
     AND iu.unit_id = r.entry_unit_id
     AND iu.is_active = TRUE
    WHERE r.tenant_id = p_tenant_id
  ),
  pending_ingredient AS (
    SELECT
      rl.ingredient_id,
      SUM(pi.quantity * rl.per_portion_qty) AS base_qty
    FROM pending_item pi
    JOIN recipe_lines rl ON rl.menu_item_id = pi.menu_item_id
    WHERE rl.line_missing_config = false
      AND rl.per_portion_qty IS NOT NULL
      AND rl.per_portion_qty > 0
    GROUP BY rl.ingredient_id
  ),
  holds_ingredient AS (
    SELECT
      rl.ingredient_id,
      SUM(hi.quantity * rl.per_portion_qty) AS base_qty
    FROM holds_item hi
    JOIN recipe_lines rl ON rl.menu_item_id = hi.menu_item_id
    WHERE rl.line_missing_config = false
      AND rl.per_portion_qty IS NOT NULL
      AND rl.per_portion_qty > 0
    GROUP BY rl.ingredient_id
  ),
  branch_stock AS (
    SELECT
      sl.ingredient_id,
      SUM(sl.current_quantity) AS on_hand
    FROM public.stock_levels sl
    JOIN public.inventory_locations il ON il.id = sl.location_id
    WHERE sl.tenant_id = p_tenant_id
      AND sl.branch_id = p_branch_id
      AND il.location_kind = 'warehouse'
      AND il.is_active = TRUE
    GROUP BY sl.ingredient_id
  ),
  stock_pool AS (
    SELECT
      mi.id AS menu_item_id,
      -- Keep raw capacity semantics aligned with compute_menu_item_stock_capacity.
      CASE
        WHEN COUNT(rl.ingredient_id) = 0 THEN NULL::integer
        WHEN BOOL_OR(
          rl.line_missing_config
          OR rl.per_portion_qty IS NULL
          OR rl.per_portion_qty <= 0
        ) THEN NULL::integer
        ELSE FLOOR(MIN(
          COALESCE(bs.on_hand, 0) / NULLIF(rl.per_portion_qty, 0)
        ) + 0.000001)::integer
      END AS stock_capacity,
      CASE
        WHEN COUNT(rl.ingredient_id) = 0 THEN NULL::integer
        WHEN BOOL_OR(
          rl.line_missing_config
          OR rl.per_portion_qty IS NULL
          OR rl.per_portion_qty <= 0
        ) THEN NULL::integer
        ELSE FLOOR(MIN((
          COALESCE(bs.on_hand, 0)
          - COALESCE(pi.base_qty, 0)
          - COALESCE(hi.base_qty, 0)
        ) / NULLIF(rl.per_portion_qty, 0)) + 0.000001)::integer
      END AS stock_remaining,
      CASE
        WHEN COUNT(rl.ingredient_id) = 0 THEN 0
        WHEN BOOL_OR(
          rl.line_missing_config
          OR rl.per_portion_qty IS NULL
          OR rl.per_portion_qty <= 0
        ) THEN 0
        ELSE CEIL(MAX(COALESCE(pi.base_qty, 0) / NULLIF(rl.per_portion_qty, 0)))::integer
      END AS pending_unfinalized_demand,
      CASE
        WHEN COUNT(rl.ingredient_id) = 0 THEN 0
        WHEN BOOL_OR(
          rl.line_missing_config
          OR rl.per_portion_qty IS NULL
          OR rl.per_portion_qty <= 0
        ) THEN 0
        ELSE CEIL(MAX(COALESCE(hi.base_qty, 0) / NULLIF(rl.per_portion_qty, 0)))::integer
      END AS active_hold_demand
    FROM public.menu_items mi
    LEFT JOIN recipe_lines rl ON rl.menu_item_id = mi.id
    LEFT JOIN branch_stock bs ON bs.ingredient_id = rl.ingredient_id
    LEFT JOIN pending_ingredient pi ON pi.ingredient_id = rl.ingredient_id
    LEFT JOIN holds_ingredient hi ON hi.ingredient_id = rl.ingredient_id
    WHERE mi.tenant_id = p_tenant_id
      AND mi.is_active = true
    GROUP BY mi.id
  ),
  rows AS (
    SELECT
      mi.id AS menu_item_id,
      mi.name AS item_name,
      mc.id AS category_id,
      mc.name AS category_name,
      mc.sort_order AS category_sort_order,
      mi.sort_order AS item_sort_order,
      mi.base_price,
      bl.id AS limit_id,
      bl.limit_date,
      COALESCE(bl.is_disabled, false) AS is_disabled,
      COALESCE(bl.sold_today, 0) AS sold_today,
      sp.stock_capacity,
      bl.limit_quantity AS manual_limit_quantity,
      COALESCE(sp.pending_unfinalized_demand, 0) AS pending_unfinalized_demand,
      COALESCE(sp.active_hold_demand, 0) AS active_hold_demand,
      COALESCE(hi.quantity, 0) AS item_active_hold_demand,
      sp.stock_remaining
    FROM public.menu_items mi
    JOIN public.menu_categories mc ON mc.id = mi.category_id
    LEFT JOIN public.branch_menu_item_daily_limits bl
      ON bl.menu_item_id = mi.id
     AND bl.branch_id = p_branch_id
     AND bl.limit_date = p_limit_date
    LEFT JOIN stock_pool sp ON sp.menu_item_id = mi.id
    LEFT JOIN holds_item hi ON hi.menu_item_id = mi.id
    WHERE mi.tenant_id = p_tenant_id
      AND mi.is_active = true
  ),
  computed AS (
    SELECT
      r.*,
      CASE
        WHEN NOT p_stock_gate_enabled THEN NULL::integer
        WHEN r.stock_capacity IS NULL THEN NULL::integer
        ELSE r.stock_remaining
      END AS stock_remaining_effective,
      CASE
        WHEN r.manual_limit_quantity IS NULL THEN NULL::integer
        ELSE r.manual_limit_quantity - r.sold_today - r.item_active_hold_demand
      END AS manual_remaining
    FROM rows r
  )
  SELECT
    c.menu_item_id,
    c.item_name,
    c.category_id,
    c.category_name,
    c.base_price,
    c.limit_id,
    c.limit_date,
    c.is_disabled,
    c.sold_today,
    c.stock_capacity,
    c.manual_limit_quantity,
    c.pending_unfinalized_demand,
    c.active_hold_demand,
    CASE
      WHEN c.is_disabled THEN 0
      WHEN c.stock_remaining_effective IS NULL
        AND c.manual_remaining IS NULL THEN NULL
      WHEN c.stock_remaining_effective IS NULL
        THEN GREATEST(0, c.manual_remaining)
      WHEN c.manual_remaining IS NULL
        THEN GREATEST(0, c.stock_remaining_effective)
      ELSE GREATEST(
        0,
        LEAST(c.stock_remaining_effective, c.manual_remaining)
      )
    END AS available_to_sell
  FROM computed c
  ORDER BY
    c.category_sort_order,
    c.item_sort_order,
    c.item_name;
$_$;


--
-- Name: FUNCTION branch_menu_limit_availability(p_tenant_id bigint, p_branch_id bigint, p_limit_date date, p_stock_gate_enabled boolean, p_exclude_hold_tokens uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.branch_menu_limit_availability(p_tenant_id bigint, p_branch_id bigint, p_limit_date date, p_stock_gate_enabled boolean, p_exclude_hold_tokens uuid[]) IS 'Stock availability reserves shared recipe ingredients from active branch warehouse stock; manual daily caps remain per menu item. Capacity NULL remains unlimited.';


--
-- Name: broadcast_branch_ops(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_branch_ops() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row jsonb := to_jsonb(COALESCE(NEW, OLD));
  v_payload jsonb;
  v_branch text;
BEGIN
  v_payload := jsonb_build_object(
    'domain', 'inventory',
    'table', TG_TABLE_NAME,
    'op', TG_OP,
    'id', v_row ->> 'id',
    'at', now()
  );
  BEGIN
    FOR v_branch IN
      SELECT DISTINCT b
      FROM (VALUES
        (v_row ->> 'branch_id'),
        (v_row ->> 'from_branch_id'),
        (v_row ->> 'to_branch_id')
      ) AS t(b)
      WHERE b IS NOT NULL
    LOOP
      PERFORM realtime.send(v_payload, 'ops', 'branch:' || v_branch || ':ops', true);
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'broadcast_branch_ops best-effort send failed (table=%, op=%): %',
      TG_TABLE_NAME, TG_OP, SQLERRM;
  END;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION broadcast_branch_ops(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.broadcast_branch_ops() IS 'AFTER trigger: broadcasts a thin {domain,table,op,id,at} signal to branch:{id}:ops for every branch column present on the row (branch_id / from_branch_id / to_branch_id).';


--
-- Name: broadcast_menu_ops(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_menu_ops() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row jsonb := to_jsonb(COALESCE(NEW, OLD));
  v_tenant bigint := (v_row ->> 'tenant_id')::bigint;
  v_payload jsonb;
  v_branch record;
BEGIN
  IF v_tenant IS NULL THEN
    RETURN NULL;
  END IF;

  v_payload := jsonb_build_object(
    'domain', 'pos',
    'table', TG_TABLE_NAME,
    'op', TG_OP,
    'id', v_row ->> 'id',
    'at', now()
  );

  BEGIN
    -- Broadcast to all branches belonging to this tenant
    FOR v_branch IN
      SELECT id FROM public.branches WHERE tenant_id = v_tenant
    LOOP
      PERFORM realtime.send(v_payload, 'ops', 'branch:' || v_branch.id || ':ops', true);
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'broadcast_menu_ops best-effort send failed (table=%, op=%): %',
      TG_TABLE_NAME, TG_OP, SQLERRM;
  END;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION broadcast_menu_ops(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.broadcast_menu_ops() IS 'AFTER trigger: broadcasts a thin {domain,table,op,id,at} signal to branch:{id}:ops for all branches under the same tenant on menu changes.';


--
-- Name: bulk_create_supplier_items(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_create_supplier_items(p_supplier_id bigint, p_items jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_user_id uuid := auth.uid();
  v_item_count integer;
  v_inserted_count integer;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:price_list_write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_supplier_id IS NULL OR p_supplier_id <= 0 THEN
    RAISE EXCEPTION 'invalid_supplier_id' USING ERRCODE = '22023';
  END IF;
  IF pg_catalog.jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid_supplier_items' USING ERRCODE = '22023';
  END IF;

  v_item_count := pg_catalog.jsonb_array_length(p_items);
  IF v_item_count < 1 OR v_item_count > 500 THEN
    RAISE EXCEPTION 'invalid_supplier_item_count' USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.suppliers
  WHERE id = p_supplier_id
    AND tenant_id = v_tenant_id
    AND is_active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_items)
      AS item(ingredient_id bigint)
    WHERE item.ingredient_id IS NULL
      OR item.ingredient_id <= 0
  ) THEN
    RAISE EXCEPTION 'invalid_supplier_item' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_items)
      AS item(ingredient_id bigint)
    GROUP BY item.ingredient_id
    HAVING pg_catalog.count(*) > 1
  ) THEN
    RAISE EXCEPTION 'duplicate_ingredient' USING ERRCODE = '23505';
  END IF;

  IF (
    SELECT pg_catalog.count(*)
    FROM public.ingredients AS ingredient
    JOIN pg_catalog.jsonb_to_recordset(p_items)
      AS item(ingredient_id bigint)
      ON item.ingredient_id = ingredient.id
    WHERE ingredient.tenant_id = v_tenant_id
      AND ingredient.is_active
  ) <> v_item_count THEN
    RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.supplier_items AS existing
    JOIN pg_catalog.jsonb_to_recordset(p_items)
      AS item(ingredient_id bigint)
      ON item.ingredient_id = existing.ingredient_id
    WHERE existing.tenant_id = v_tenant_id
      AND existing.supplier_id = p_supplier_id
      AND existing.is_active
  ) THEN
    RAISE EXCEPTION 'supplier_item_mapping_exists' USING ERRCODE = '23505';
  END IF;

  WITH parsed AS (
    SELECT item.ingredient_id
    FROM pg_catalog.jsonb_to_recordset(p_items)
      AS item(ingredient_id bigint)
  ),
  inserted AS (
    INSERT INTO public.supplier_items (
      tenant_id,
      supplier_id,
      ingredient_id,
      is_preferred,
      created_by
    )
    SELECT
      v_tenant_id,
      p_supplier_id,
      parsed.ingredient_id,
      NOT EXISTS (
        SELECT 1
        FROM public.supplier_items AS peer
        WHERE peer.tenant_id = v_tenant_id
          AND peer.ingredient_id = parsed.ingredient_id
          AND peer.is_active
      ),
      v_user_id
    FROM parsed
    RETURNING 1
  )
  SELECT pg_catalog.count(*)::integer
  INTO v_inserted_count
  FROM inserted;

  RETURN v_inserted_count;
END;
$$;


--
-- Name: FUNCTION bulk_create_supplier_items(p_supplier_id bigint, p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bulk_create_supplier_items(p_supplier_id bigint, p_items jsonb) IS 'Atomically maps multiple active ingredients to one active supplier.';


--
-- Name: bulk_import_ingredients(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_import_ingredients(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_sanitized_rows jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '28000';
  END IF;
  IF public.auth_role() <> 'owner' THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission_any('inventory:write') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501';
  END IF;

  IF p_rows IS NULL
     OR jsonb_typeof(p_rows) <> 'array'
     OR jsonb_array_length(p_rows) = 0 THEN
    RETURN private.execute_bulk_import_ingredients(p_rows);
  END IF;

  PERFORM ingredient.id
  FROM public.ingredients AS ingredient
  JOIN jsonb_array_elements(p_rows) AS raw(value)
    ON ingredient.name = btrim(raw.value ->> 'name')
  WHERE ingredient.tenant_id = v_tenant
  ORDER BY ingredient.id
  FOR UPDATE OF ingredient;

  SELECT jsonb_agg(
    (
      raw.value - 'unit_cost'
    ) || jsonb_build_object(
      'unit_cost',
      CASE
        WHEN ingredient.id IS NULL THEN 0
        ELSE ingredient.unit_cost
      END
    )
    ORDER BY raw.ordinality
  )
  INTO v_sanitized_rows
  FROM jsonb_array_elements(p_rows)
    WITH ORDINALITY AS raw(value, ordinality)
  LEFT JOIN public.ingredients AS ingredient
    ON ingredient.tenant_id = v_tenant
   AND ingredient.name = btrim(raw.value ->> 'name');

  RETURN private.execute_bulk_import_ingredients(v_sanitized_rows);
END;
$$;


--
-- Name: bulk_import_production_recipe_specs(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_import_production_recipe_specs(p_groups jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_group jsonb;
  v_result jsonb;
  v_recipe_count integer := 0;
  v_line_count integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF jsonb_typeof(p_groups) <> 'array' OR jsonb_array_length(p_groups) = 0 THEN
    RAISE EXCEPTION 'invalid_group_shape' USING ERRCODE = '22023';
  END IF;
  IF (
    SELECT count(*) <> count(DISTINCT item.value ->> 'finished_good_id')
    FROM jsonb_array_elements(p_groups) AS item(value)
  ) THEN
    RAISE EXCEPTION 'duplicate_finished_good' USING ERRCODE = '23505';
  END IF;

  FOR v_group IN
    SELECT item.value FROM jsonb_array_elements(p_groups) AS item(value)
  LOOP
    v_result := public.upsert_production_recipe_lines(
      nullif(v_group ->> 'finished_good_id', '')::bigint,
      nullif(v_group ->> 'output_quantity', '')::numeric,
      nullif(v_group ->> 'output_unit_id', '')::bigint,
      v_group -> 'lines'
    );
    v_recipe_count := v_recipe_count + 1;
    v_line_count := v_line_count + coalesce((v_result ->> 'line_count')::integer, 0);
  END LOOP;

  RETURN jsonb_build_object('recipes', v_recipe_count, 'lines', v_line_count);
END;
$$;


--
-- Name: bulk_import_production_recipes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_import_production_recipes(p_groups jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_group jsonb;
  v_line jsonb;
  v_quantity numeric;
  v_output_quantity numeric;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '28000';
  END IF;
  IF public.auth_role() NOT IN (
    'owner',
    'central_kitchen_lead'
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501';
  END IF;
  IF NOT (
    public.has_permission_any('inventory:production_create')
    OR public.has_permission_any('inventory:production_confirm')
    OR public.has_permission_any('menu:write')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501';
  END IF;

  IF p_groups IS NOT NULL
     AND jsonb_typeof(p_groups) = 'array' THEN
    FOR v_group IN
      SELECT item.value
      FROM jsonb_array_elements(p_groups) AS item(value)
    LOOP
      v_output_quantity := nullif(v_group ->> 'output_quantity', '')::numeric;
      IF v_output_quantity IS NULL
         OR v_output_quantity <= 0
         OR v_output_quantity = 'NaN'::numeric
         OR v_output_quantity = 'Infinity'::numeric
         OR v_output_quantity = '-Infinity'::numeric THEN
        RAISE EXCEPTION 'output_quantity_invalid'
          USING ERRCODE = '22023';
      END IF;
      IF jsonb_typeof(v_group -> 'lines') = 'array' THEN
        FOR v_line IN
          SELECT item.value
          FROM jsonb_array_elements(v_group -> 'lines') AS item(value)
        LOOP
          v_quantity := nullif(v_line ->> 'quantity', '')::numeric;
          IF v_quantity IS NULL
             OR v_quantity <= 0
             OR v_quantity = 'NaN'::numeric
             OR v_quantity = 'Infinity'::numeric
             OR v_quantity = '-Infinity'::numeric THEN
            RAISE EXCEPTION 'invalid_line_shape'
              USING ERRCODE = '22023';
          END IF;
        END LOOP;
      END IF;
    END LOOP;
  END IF;

  RETURN private.execute_bulk_import_production_recipes(p_groups);
END;
$$;


--
-- Name: bump_kds_ticket(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_kds_ticket(p_ticket_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket record;
  v_order_id bigint;
  v_new_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('kds:mark_ready') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT kt.order_id
  INTO v_order_id
  FROM public.kds_tickets kt
  WHERE kt.id = p_ticket_id
    AND kt.tenant_id = public.auth_tenant_id()
    AND (public.auth_role() = 'owner' OR kt.branch_id = public.auth_branch_id());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_order_id);

  SELECT id, tenant_id, branch_id, station_id, order_id, status
  INTO v_ticket
  FROM public.kds_tickets
  WHERE id = p_ticket_id
    AND tenant_id = public.auth_tenant_id()
    AND (public.auth_role() = 'owner' OR branch_id = public.auth_branch_id())
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_ticket.status = 'pending' THEN
    v_new_status := 'preparing';
  ELSIF v_ticket.status = 'preparing' THEN
    v_new_status := 'ready';
  ELSE
    RAISE EXCEPTION 'Ticket cannot be bumped from status %', v_ticket.status
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.kds_tickets
  SET status = v_new_status,
      bumped_at = now(),
      bumped_by = auth.uid(),
      first_ready_at = CASE
        WHEN v_new_status = 'ready' THEN COALESCE(first_ready_at, now())
        ELSE first_ready_at
      END,
      updated_at = now()
  WHERE id = p_ticket_id;

  IF v_new_status = 'ready' THEN
    PERFORM public.check_order_ready(v_ticket.order_id);
    PERFORM public.post_pos_sale_consumption_if_ready(v_ticket.order_id, auth.uid());
  END IF;

  RETURN v_new_status;
END;
$$;


--
-- Name: can_read_branch_ops(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_branch_ops(p_branch_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.branches b
    JOIN public.profiles pr
      ON pr.id = auth.uid()
     AND pr.tenant_id = b.tenant_id
    WHERE b.id = p_branch_id
      AND b.tenant_id = public.auth_tenant_id()
      AND b.is_active IS TRUE
      AND pr.is_active IS TRUE
      AND (
        pr.branch_id = p_branch_id
        OR public.auth_is_owner(pr.id)
      )
  );
$$;


--
-- Name: FUNCTION can_read_branch_ops(p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_read_branch_ops(p_branch_id bigint) IS 'Authorizes private branch:{id}:ops topics: active owners may read active tenant branches; active non-owners may read only their assigned active branch.';


--
-- Name: can_read_inventory_monetary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_inventory_monetary(p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE p_key
    WHEN 'procurement:price_list_read' THEN
      public.auth_is_owner(auth.uid())
      OR (
        public.has_position('accountant')
        AND public.has_permission_any(p_key)
      )
    WHEN 'inventory:valuation_read' THEN public.auth_is_owner(auth.uid())
    ELSE false
  END
$$;


--
-- Name: FUNCTION can_read_inventory_monetary(p_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_read_inventory_monetary(p_key text) IS 'Owner/Accountant purchase-price boundary; inventory valuation is Owner-only.';


--
-- Name: cancel_expense(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_expense(p_expense_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_user_id uuid := auth.uid();
  v_expense public.expenses%ROWTYPE;
  v_prelock_transfer_content text;
BEGIN
  IF v_user_id IS NULL
    OR v_tenant_id IS NULL
    OR NOT (
      public.auth_is_owner(v_user_id)
      OR public.has_position('accountant')
    )
    OR NOT public.has_permission_any('finance:expense_create')
    OR NOT EXISTS (
      SELECT 1
      FROM public.profiles profile
      WHERE profile.id = v_user_id
        AND profile.tenant_id = v_tenant_id
        AND COALESCE(profile.is_active, true)
    )
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT expense.transfer_content
  INTO v_prelock_transfer_content
  FROM public.expenses expense
  WHERE expense.id = p_expense_id
    AND expense.tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'expense_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_prelock_transfer_content IS NOT NULL THEN
    PERFORM event.id
    FROM public.webhook_events event
    WHERE event.tenant_id = v_tenant_id
      AND event.provider = 'sepay'
      AND private.sepay_payload_contains_transfer_content(
        event.payload,
        v_prelock_transfer_content
      )
    ORDER BY event.id
    FOR UPDATE;
  END IF;

  SELECT expense.*
  INTO v_expense
  FROM public.expenses expense
  WHERE expense.id = p_expense_id
    AND expense.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'expense_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_expense.transfer_content IS DISTINCT FROM v_prelock_transfer_content THEN
    RAISE EXCEPTION 'expense_payment_state_changed' USING ERRCODE = '40001';
  END IF;

  IF NOT (
    v_expense.category = ANY (ARRAY[
      'rent',
      'utilities',
      'gas_fuel',
      'salary',
      'supplies',
      'repair',
      'marketing',
      'fees_tax',
      'hospitality',
      'other'
    ]::text[])
  ) THEN
    RAISE EXCEPTION 'expense_cancel_not_operating' USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches match
    WHERE match.tenant_id = v_tenant_id
      AND match.expense_id = v_expense.id
  ) OR EXISTS (
    SELECT 1
    FROM public.webhook_events event
    WHERE event.tenant_id = v_tenant_id
      AND event.provider = 'sepay'
      AND event.expense_id = v_expense.id
  ) THEN
    RAISE EXCEPTION 'expense_already_matched' USING ERRCODE = '23505';
  END IF;

  PERFORM set_config('app.expense_cancel_id', v_expense.id::text, true);

  PERFORM public.log_audit(
    'cancel',
    'expense',
    v_expense.id,
    to_jsonb(v_expense),
    NULL
  );

  DELETE FROM public.expenses expense
  WHERE expense.id = v_expense.id
    AND expense.tenant_id = v_tenant_id;

  PERFORM set_config('app.expense_cancel_id', '', true);

  RETURN jsonb_build_object(
    'cancelled', true,
    'expense_id', v_expense.id
  );
END;
$$;


--
-- Name: cancel_goods_receipt_note(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_goods_receipt_note(p_grn_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_grn public.goods_received_notes%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT grn.*
  INTO v_grn
  FROM public.goods_received_notes AS grn
  WHERE grn.id = p_grn_id
    AND grn.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_grn.branch_id, 'procurement:grn_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_grn.status <> 'draft' THEN
    RAISE EXCEPTION 'grn_not_cancellable' USING ERRCODE = '23514';
  END IF;

  UPDATE public.goods_received_notes
  SET status = 'cancelled',
      notes = concat_ws(E'\n', NULLIF(notes, ''), btrim(p_reason)),
      updated_at = now()
  WHERE id = p_grn_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'inventory.grn.cancelled',
    'goods_received_note',
    p_grn_id,
    to_jsonb(v_grn),
    jsonb_build_object('status', 'cancelled', 'reason', btrim(p_reason))
  );

  RETURN jsonb_build_object('id', p_grn_id, 'status', 'cancelled');
END;
$$;


--
-- Name: cancel_leave_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_leave_request(p_request_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_user_id   UUID   := auth.uid();
  v_request   public.leave_requests%ROWTYPE;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'cancel_leave_request: missing auth context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_request
  FROM public.leave_requests
  WHERE id = p_request_id
    AND tenant_id = v_tenant_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'cancel_leave_request: request not found'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = v_request.employee_id
      AND e.profile_id = v_user_id
      AND e.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'cancel_leave_request: not the request owner'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'cancel_leave_request: request is %, not pending', v_request.status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.leave_requests
  SET status = 'cancelled',
      reviewed_by = v_user_id,
      reviewed_at = now()
  WHERE id = p_request_id;

  PERFORM public.log_audit(
    'cancel'::TEXT,
    'leave_request'::TEXT,
    p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'cancelled')
  );
END;
$$;


--
-- Name: FUNCTION cancel_leave_request(p_request_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_leave_request(p_request_id bigint) IS 'Employee cancels own pending leave request. Caller must own the underlying employee row.';


--
-- Name: cancel_order(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_order(p_order_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_prof_tenant bigint;
  v_prof_branch bigint;
  v_prof_role text;
  v_order record;
  v_item_id bigint;
  v_print_res jsonb;
  v_waste_res jsonb;
  v_tickets_enqueued int := 0;
  v_tickets_skipped int := 0;
  v_skip_reasons text[] := ARRAY[]::text[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT id, tenant_id, branch_id, status, table_id, order_type,
         service_charge, discount_type, discount_value
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  v_waste_res := public.post_pos_cancelled_ready_waste(p_order_id, v_uid, p_reason);

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = p_reason,
      updated_at = now()
  WHERE order_id = p_order_id AND status <> 'cancelled';

  UPDATE public.kds_tickets
  SET status = 'cancelled', updated_at = now()
  WHERE order_id = p_order_id AND tenant_id = v_order.tenant_id;

  UPDATE public.orders
  SET
    status = 'cancelled',
    subtotal = 0,
    discount_type = NULL,
    discount_value = NULL,
    discount_note = NULL,
    discount_amount = 0,
    total_amount = 0 + COALESCE(service_charge, 0),
    updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id, p_order_id, v_order.status, 'cancelled', v_uid, p_reason
  );

  FOR v_item_id IN
    SELECT id FROM public.order_items
    WHERE order_id = p_order_id
      AND sent_to_kitchen_at IS NOT NULL
    ORDER BY id
  LOOP
    BEGIN
      v_print_res := public.enqueue_cancel_ticket_print(v_item_id, p_reason);
      IF (v_print_res ? 'skipped') AND (v_print_res->>'skipped')::boolean THEN
        v_tickets_skipped := v_tickets_skipped + 1;
        v_skip_reasons := v_skip_reasons || COALESCE(v_print_res->>'reason', 'unknown');
      ELSE
        v_tickets_enqueued := v_tickets_enqueued + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_tickets_skipped := v_tickets_skipped + 1;
      v_skip_reasons := v_skip_reasons || ('error:' || SQLERRM);
      RAISE NOTICE '[cancel_order] cancel-ticket enqueue raised for item %: %',
        v_item_id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'status', 'cancelled',
    'cancel_tickets', v_tickets_enqueued,
    'cancel_skipped', v_tickets_skipped,
    'skip_reasons', to_jsonb(v_skip_reasons),
    'stock_outcome', COALESCE(v_waste_res, '{}'::jsonb)
  );
END;
$$;


--
-- Name: cancel_pending_payment(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_pending_payment(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order_id bigint;
  v_payment record;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'permission denied: pos:use' USING ERRCODE = '42501';
  END IF;

  SELECT payment.order_id
  INTO v_order_id
  FROM public.payments payment
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = p_tenant_id
    AND payment.branch_id = p_branch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0001';
  END IF;

  PERFORM pg_advisory_xact_lock(v_order_id);

  PERFORM 1
  FROM public.orders order_row
  WHERE order_row.id = v_order_id
    AND order_row.tenant_id = p_tenant_id
    AND order_row.branch_id = p_branch_id
  FOR UPDATE NOWAIT;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0001';
  END IF;

  SELECT
    payment.id,
    payment.order_id,
    payment.method,
    payment.status,
    payment.provider_data
  INTO v_payment
  FROM public.payments payment
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = p_tenant_id
    AND payment.branch_id = p_branch_id
  FOR UPDATE NOWAIT;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0001';
  END IF;
  IF v_payment.order_id IS DISTINCT FROM v_order_id THEN
    RAISE EXCEPTION 'payment_order_changed' USING ERRCODE = '40001';
  END IF;
  IF v_payment.status <> 'pending' THEN
    RAISE EXCEPTION 'payment_not_pending' USING ERRCODE = 'P0001';
  END IF;
  IF v_payment.method = 'momo' THEN
    RAISE EXCEPTION 'momo_cancellation_requires_provider_confirmation'
      USING ERRCODE = '55P03';
  END IF;
  IF COALESCE(v_payment.provider_data ->> 'source', '') = 'qr_self_order'
    OR EXISTS (
      SELECT 1
      FROM public.self_order_payment_requests request
      WHERE request.tenant_id = p_tenant_id
        AND request.payment_id = v_payment.id
        AND request.status IN ('cash_call', 'vietqr_pending')
    )
  THEN
    RAISE EXCEPTION 'self_order_payment_owned' USING ERRCODE = '55P03';
  END IF;

  UPDATE public.payments
  SET status = 'failed',
      updated_at = now()
  WHERE id = p_payment_id;

  UPDATE public.orders
  SET payment_status = 'unpaid',
      payment_method = NULL,
      updated_at = now()
  WHERE id = v_payment.order_id
    AND payment_status <> 'paid';
END;
$$;


--
-- Name: FUNCTION cancel_pending_payment(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_pending_payment(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint) IS 'Cancel a pending payment under the same order-scoped transaction lock used by payment creation and settlement.';


