--
-- Name: cancel_production_run(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_production_run(p_run_id bigint, p_branch_id bigint, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator()
     OR NOT public.has_permission(p_branch_id, 'inventory:production_confirm') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;
  UPDATE public.production_runs AS run
  SET status = 'cancelled', cancel_reason = nullif(pg_catalog.btrim(p_reason), ''),
      updated_at = now()
  WHERE run.tenant_id = v_tenant
    AND run.id = p_run_id
    AND run.branch_id = p_branch_id
    AND run.status IN ('draft', 'in_progress');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_transition_invalid' USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('production_run_id', p_run_id, 'status', 'cancelled');
END;
$$;


--
-- Name: cancel_purchase_order(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_purchase_order(p_po_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_po public.purchase_orders%ROWTYPE;
  v_cancelled_grns integer;
  v_permission text;
  v_demand_status text;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF pg_catalog.length(
    pg_catalog.btrim(coalesce(p_reason, ''))
  ) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT purchase_order.*
  INTO v_po
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.id = p_po_id
    AND purchase_order.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_permission := CASE
    WHEN v_po.status IN ('draft', 'changes_requested')
      THEN 'procurement:po_create'
    ELSE 'procurement:po_approve'
  END;
  IF NOT public.has_permission(v_po.branch_id, v_permission) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_po.status NOT IN (
    'draft',
    'changes_requested',
    'pending_approval',
    'sent',
    'approved'
  )
  OR EXISTS (
    SELECT 1
    FROM public.goods_received_notes AS grn
    WHERE grn.tenant_id = v_tenant
      AND grn.po_id = p_po_id
      AND grn.status = 'confirmed'
  ) THEN
    RAISE EXCEPTION 'purchase_order_not_cancellable'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.goods_received_notes
  SET status = 'cancelled',
      notes = pg_catalog.concat_ws(
        E'\n',
        nullif(notes, ''),
        'Hủy cùng PO: ' || pg_catalog.btrim(p_reason)
      ),
      updated_at = pg_catalog.now()
  WHERE tenant_id = v_tenant
    AND po_id = p_po_id
    AND status = 'draft';
  GET DIAGNOSTICS v_cancelled_grns = ROW_COUNT;

  UPDATE public.purchase_orders
  SET status = 'cancelled',
      status_reason = pg_catalog.btrim(p_reason),
      cancelled_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  WHERE id = p_po_id
    AND tenant_id = v_tenant;

  IF v_po.purchase_request_id IS NOT NULL THEN
    DELETE FROM public.purchase_request_allocations
    WHERE tenant_id = v_tenant
      AND purchase_request_id = v_po.purchase_request_id;

    v_demand_status := private.recompute_purchase_request_status(
      v_po.purchase_request_id,
      v_tenant
    );
  END IF;

  PERFORM public.log_audit(
    'procurement.po.cancelled',
    'purchase_order',
    p_po_id,
    pg_catalog.to_jsonb(v_po),
    pg_catalog.jsonb_build_object(
      'status', 'cancelled',
      'reason', pg_catalog.btrim(p_reason),
      'cancelled_draft_grns', v_cancelled_grns,
      'demand_id', v_po.purchase_request_id,
      'demand_status', v_demand_status
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'id', p_po_id,
    'status', 'cancelled',
    'cancelled_draft_grns', v_cancelled_grns,
    'demand_id', v_po.purchase_request_id,
    'demand_status', v_demand_status
  );
END;
$$;


--
-- Name: cancel_purchase_request(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_purchase_request(p_request_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_request public.purchase_requests%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF pg_catalog.length(
    pg_catalog.btrim(coalesce(p_reason, ''))
  ) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT demand.*
  INTO v_request
  FROM public.purchase_requests AS demand
  WHERE demand.id = p_request_id
    AND demand.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_demand_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_request.branch_id,
    'procurement:request_manage'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_request.status NOT IN (
    'draft',
    'submitted',
    'pending_allocation',
    'changes_requested'
  )
  OR EXISTS (
    SELECT 1
    FROM public.purchase_orders AS purchase_order
    WHERE purchase_order.tenant_id = v_tenant
      AND purchase_order.purchase_request_id = p_request_id
      AND purchase_order.status <> 'cancelled'
  ) THEN
    RAISE EXCEPTION 'purchase_request_not_cancellable'
      USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.purchase_request_allocations
  WHERE tenant_id = v_tenant
    AND purchase_request_id = p_request_id;

  UPDATE public.purchase_requests
  SET status = 'cancelled',
      status_reason = pg_catalog.btrim(p_reason),
      cancelled_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  WHERE id = p_request_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'procurement.demand.cancelled',
    'purchase_request',
    p_request_id,
    pg_catalog.to_jsonb(v_request),
    pg_catalog.jsonb_build_object(
      'status', 'cancelled',
      'reason', pg_catalog.btrim(p_reason)
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'request_id', p_request_id,
    'status', 'cancelled'
  );
END;
$$;


