--
-- Name: cancel_stock_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_stock_request(p_request_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_req public.stock_requests%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_req
  FROM public.stock_requests AS req
  WHERE req.id = p_request_id AND req.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stock_request_not_found' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_req.status NOT IN ('draft', 'submitted') THEN
    RAISE EXCEPTION 'stock_request_not_cancellable' USING ERRCODE = '22023';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission(
       v_req.branch_id,
       'inventory:request_cancel'
     )
  THEN
    RAISE EXCEPTION 'forbidden_request_cancel' USING ERRCODE = '42501';
  END IF;

  UPDATE public.stock_request_items
  SET status = 'cancelled', updated_at = now()
  WHERE request_id = p_request_id
    AND tenant_id = v_tenant
    AND status = 'pending';

  UPDATE public.stock_requests
  SET status = 'cancelled',
      cancelled_at = now(),
      updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('request_id', p_request_id, 'status', 'cancelled');
END;
$$;


--
-- Name: cancel_stock_request(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_stock_request(p_request_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_request public.stock_requests%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT request.*
  INTO v_request
  FROM public.stock_requests AS request
  WHERE request.id = p_request_id
    AND request.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stock_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission(
       v_request.branch_id,
       'inventory:request_cancel'
     ) THEN
    RAISE EXCEPTION 'forbidden_request_cancel' USING ERRCODE = '42501';
  END IF;
  IF v_request.status NOT IN ('draft', 'submitted')
     OR EXISTS (
       SELECT 1
       FROM public.stock_request_items AS item
       WHERE item.request_id = p_request_id
         AND item.tenant_id = v_tenant
         AND item.status <> 'pending'
     ) THEN
    RAISE EXCEPTION 'stock_request_not_cancellable'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.stock_request_items
  SET status = 'cancelled',
      updated_at = now()
  WHERE request_id = p_request_id
    AND tenant_id = v_tenant
    AND status = 'pending';

  UPDATE public.stock_requests
  SET status = 'cancelled',
      status_reason = btrim(p_reason),
      cancelled_at = now(),
      updated_at = now()
  WHERE id = p_request_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'inventory.request.cancelled',
    'stock_request',
    p_request_id,
    to_jsonb(v_request),
    jsonb_build_object('status', 'cancelled', 'reason', btrim(p_reason))
  );

  RETURN jsonb_build_object(
    'request_id', p_request_id,
    'status', 'cancelled'
  );
END;
$$;


--
-- Name: cancel_stock_transfer(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_stock_transfer(p_transfer_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_transfer public.stock_transfers%ROWTYPE;
  v_request_id bigint;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT transfer.*
  INTO v_transfer
  FROM public.stock_transfers AS transfer
  WHERE transfer.id = p_transfer_id
    AND transfer.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stock_transfer_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_transfer.status <> 'draft' THEN
    RAISE EXCEPTION 'stock_transfer_not_cancellable'
      USING ERRCODE = '23514';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND (
       public.auth_branch_id() IS DISTINCT FROM v_transfer.from_branch_id
       OR NOT public.has_permission(
         v_transfer.from_branch_id,
         'inventory:transfer_create'
       )
     ) THEN
    RAISE EXCEPTION 'forbidden_transfer_cancel' USING ERRCODE = '42501';
  END IF;

  SELECT min(item.request_id)
  INTO v_request_id
  FROM public.stock_request_items AS item
  WHERE item.tenant_id = v_tenant
    AND item.transfer_id = p_transfer_id;

  UPDATE public.stock_request_items
  SET status = 'pending',
      transfer_id = NULL,
      updated_at = now()
  WHERE tenant_id = v_tenant
    AND transfer_id = p_transfer_id
    AND status = 'allocated';

  UPDATE public.stock_transfers
  SET status = 'cancelled',
      status_reason = btrim(p_reason),
      cancelled_at = now(),
      updated_at = now()
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'inventory.transfer.cancelled',
    'stock_transfer',
    p_transfer_id,
    to_jsonb(v_transfer),
    jsonb_build_object(
      'status', 'cancelled',
      'reason', btrim(p_reason),
      'stock_request_id', v_request_id
    )
  );

  RETURN jsonb_build_object(
    'id', p_transfer_id,
    'status', 'cancelled',
    'stock_request_id', v_request_id
  );
END;
$$;


--
-- Name: check_bank_reconciliation_match_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_bank_reconciliation_match_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    IF OLD.expense_id IS NOT NULL THEN
      PERFORM public.assert_bank_deposit_evidence(
        OLD.tenant_id,
        OLD.expense_id
      );
    END IF;
  END IF;

  IF TG_OP <> 'DELETE' THEN
    IF NEW.expense_id IS NOT NULL THEN
      PERFORM public.assert_bank_deposit_evidence(
        NEW.tenant_id,
        NEW.expense_id
      );
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: check_branch_required(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_branch_required() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_role text;
  v_required_kind text;
BEGIN
  SELECT private.staff_role_from_position_code(position.code),
         private.required_branch_kind_for_position_code(position.code)
  INTO v_user_role, v_required_kind
  FROM public.positions position
  WHERE position.id = NEW.position_id
    AND position.tenant_id = NEW.tenant_id;

  IF v_required_kind IS NOT NULL
     AND v_required_kind <> 'unassigned'
     AND NEW.branch_id IS NULL THEN
    RAISE EXCEPTION
      'branch_required_for_operational_position: position_id=%',
      NEW.position_id
      USING ERRCODE = '23514';
  END IF;

  IF (v_required_kind IS NULL OR v_required_kind = 'unassigned')
     AND NEW.branch_id IS NOT NULL
     AND (v_user_role IS NULL OR v_user_role IN ('owner', 'accountant')) THEN
    RAISE EXCEPTION 'tenant_role_must_not_have_branch_scope: role=%',
      COALESCE(v_user_role, 'self_service')
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION check_branch_required(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_branch_required() IS 'Profiles branch guard. Unmapped active company positions are tenant-scoped self-service candidates; operational positions remain site-pinned.';


--
-- Name: check_cron_jobs_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_cron_jobs_health() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job RECORD;
  v_last_run RECORD;
  v_max_age INTERVAL;
  v_registered_at TIMESTAMPTZ;
  v_is_healthy BOOLEAN;
  v_dedup_key TEXT;
  v_msg TEXT;
BEGIN
  DELETE FROM private.cron_job_health_grace g
  WHERE NOT EXISTS (
    SELECT 1
    FROM cron.job j
    WHERE j.jobid = g.jobid
  );

  FOR v_job IN
    SELECT jobid, jobname, schedule
    FROM cron.job
  LOOP
    IF v_job.jobname = 'check_cron_jobs_health_job' THEN
      CONTINUE;
    END IF;

    IF v_job.schedule LIKE '*/15%' THEN
      v_max_age := INTERVAL '45 minutes';
    ELSIF v_job.schedule LIKE '%* * * *' AND v_job.schedule NOT LIKE '*/%' THEN
      v_max_age := INTERVAL '90 minutes';
    ELSIF v_job.schedule LIKE '%* * *' THEN
      v_max_age := INTERVAL '28 hours';
    ELSE
      v_max_age := INTERVAL '8 days';
    END IF;

    SELECT d.start_time, d.end_time, d.status, d.return_message
    INTO v_last_run
    FROM cron.job_run_details d
    WHERE d.jobid = v_job.jobid
    ORDER BY d.start_time DESC
    LIMIT 1;

    SELECT g.registered_at
    INTO v_registered_at
    FROM private.cron_job_health_grace g
    WHERE g.jobid = v_job.jobid;

    v_is_healthy := TRUE;
    v_msg := NULL;

    IF v_last_run.start_time IS NULL THEN
      IF v_registered_at IS NOT NULL
         AND now() < v_registered_at + v_max_age THEN
        CONTINUE;
      END IF;

      v_is_healthy := FALSE;
      v_msg := format(
        'Tác vụ tự động "%s" chưa từng chạy thành công hoặc bị treo.',
        v_job.jobname
      );
    ELSIF v_last_run.end_time IS NULL THEN
      IF v_last_run.start_time >= now() - v_max_age THEN
        CONTINUE;
      END IF;

      v_is_healthy := FALSE;
      v_msg := format(
        'Tác vụ tự động "%s" bị treo từ %s với trạng thái: %s.',
        v_job.jobname,
        v_last_run.start_time::text,
        COALESCE(v_last_run.status, 'Không có')
      );
    ELSE
      DELETE FROM private.cron_job_health_grace
      WHERE jobid = v_job.jobid;

      IF v_last_run.status <> 'succeeded' THEN
        v_is_healthy := FALSE;
        v_msg := format(
          'Tác vụ tự động "%s" thất bại với trạng thái: %s. Chi tiết: %s',
          v_job.jobname,
          v_last_run.status,
          COALESCE(v_last_run.return_message, 'Không có')
        );
      ELSIF v_last_run.end_time < (now() - v_max_age) THEN
        v_is_healthy := FALSE;
        v_msg := format(
          'Tác vụ tự động "%s" không chạy trong vòng %s qua (lần cuối chạy: %s).',
          v_job.jobname,
          v_max_age::text,
          v_last_run.end_time::text
        );
      END IF;
    END IF;

    IF NOT v_is_healthy THEN
      v_dedup_key := format(
        'cron_health:%s:%s',
        v_job.jobname,
        floor(extract(epoch from now()) / 21600)::text
      );

      INSERT INTO public.notifications (
        tenant_id,
        target_branch_id,
        severity,
        kind,
        title,
        body,
        dedup_key,
        target_roles,
        meta
      ) VALUES (
        1,
        NULL,
        'critical',
        'system.cron_failed',
        'Tác vụ tự động cần kiểm tra',
        v_msg,
        v_dedup_key,
        ARRAY['owner']::text[],
        jsonb_build_object(
          'job_name', v_job.jobname,
          'schedule', v_job.schedule,
          'error_message', v_msg,
          'last_run_at', v_last_run.end_time,
          'status', v_last_run.status
        )
      ) ON CONFLICT (tenant_id, dedup_key)
        WHERE dedup_key IS NOT NULL
        DO NOTHING;
    END IF;
  END LOOP;
END;
$$;


