--
-- Name: check_order_ready(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_order_ready(p_order_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pending_count INT;
  v_current_status TEXT;
BEGIN
  SELECT status INTO v_current_status
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = public.auth_tenant_id()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_current_status IN ('ready', 'served', 'completed', 'cancelled') THEN
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_pending_count
  FROM public.kds_tickets
  WHERE order_id = p_order_id
    AND tenant_id = public.auth_tenant_id()
    AND status NOT IN ('ready', 'served', 'cancelled');

  IF v_pending_count = 0 THEN
    UPDATE public.orders
    SET status = 'ready',
        updated_at = now()
    WHERE id = p_order_id
      AND tenant_id = public.auth_tenant_id();

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by
    )
    SELECT tenant_id, id, v_current_status, 'ready', auth.uid()
    FROM public.orders
    WHERE id = p_order_id
      AND tenant_id = public.auth_tenant_id();
  END IF;
END;
$$;


--
-- Name: check_sepay_expense_match_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_sepay_expense_match_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    PERFORM public.assert_sepay_expense_match_evidence(
      OLD.tenant_id,
      OLD.webhook_event_id
    );
  END IF;

  IF TG_OP <> 'DELETE'
    AND (
      TG_OP = 'INSERT'
      OR OLD.tenant_id IS DISTINCT FROM NEW.tenant_id
      OR OLD.webhook_event_id IS DISTINCT FROM NEW.webhook_event_id
    )
  THEN
    PERFORM public.assert_sepay_expense_match_evidence(
      NEW.tenant_id,
      NEW.webhook_event_id
    );
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: check_sides_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_sides_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.main_item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'main item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.side_item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'side item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: check_table_zone_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_table_zone_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.zone_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branch_zones
    WHERE id = NEW.zone_id
      AND tenant_id = NEW.tenant_id
      AND branch_id = NEW.branch_id
  ) THEN
    RAISE EXCEPTION 'zone does not belong to tenant/branch'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_variant_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_variant_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_webhook_finance_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_webhook_finance_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    IF OLD.expense_id IS NOT NULL THEN
      PERFORM public.assert_bank_deposit_evidence(OLD.tenant_id, OLD.expense_id);
    END IF;
    PERFORM public.assert_sepay_expense_match_evidence(OLD.tenant_id, OLD.id);
  END IF;

  IF TG_OP <> 'DELETE'
    AND (
      TG_OP = 'INSERT'
      OR OLD.tenant_id IS DISTINCT FROM NEW.tenant_id
      OR OLD.id IS DISTINCT FROM NEW.id
      OR OLD.expense_id IS DISTINCT FROM NEW.expense_id
    )
  THEN
    IF NEW.expense_id IS NOT NULL THEN
      PERFORM public.assert_bank_deposit_evidence(NEW.tenant_id, NEW.expense_id);
    END IF;
    PERFORM public.assert_sepay_expense_match_evidence(NEW.tenant_id, NEW.id);
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: claim_print_job(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_print_job(p_job_id bigint, p_agent_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated INT;
  v_is_service BOOLEAN := (auth.role() = 'service_role');
  v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  UPDATE public.print_jobs
    SET status = 'processing',
        claimed_by_agent = p_agent_id,
        claimed_at = now(),
        attempts = attempts + 1
    WHERE id = p_job_id
      AND status = 'pending'
      AND (v_is_service OR tenant_id = v_tenant);
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated = 1;
END;
$$;


--
-- Name: claim_tax_invoice_issue_job(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_tax_invoice_issue_job(p_job_id bigint, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id bigint, tenant_id bigint, branch_id bigint, order_id bigint, payment_id bigint, invoice_payload jsonb, tax_invoice_id bigint, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  UPDATE public.tax_invoice_issue_jobs job
  SET status = 'reconcile_required',
      locked_until = NULL,
      last_error = 'lease_expired_provider_state_unknown',
      updated_at = now()
  FROM public.tax_invoices invoice
  WHERE job.id = p_job_id
    AND job.tax_invoice_id = invoice.id
    AND job.status = 'processing'
    AND job.locked_until < now()
    AND invoice.status IN ('signing', 'submitted');

  RETURN QUERY
  WITH candidate AS (
    SELECT job.id
    FROM public.tax_invoice_issue_jobs job
    WHERE job.id = p_job_id
      AND (
        (
          job.status = 'queued'
          AND job.available_at <= now()
        )
        OR (
          job.status = 'processing'
          AND job.locked_until < now()
        )
      )
    FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE public.tax_invoice_issue_jobs job
    SET status = 'processing',
        locked_until = now() + make_interval(
          secs => LEAST(
            GREATEST(COALESCE(p_lease_seconds, 300), 30),
            900
          )
        ),
        attempt_count = job.attempt_count + 1,
        updated_at = now()
    FROM candidate
    WHERE job.id = candidate.id
    RETURNING job.*
  )
  SELECT
    claimed.id,
    claimed.tenant_id,
    claimed.branch_id,
    claimed.order_id,
    claimed.payment_id,
    claimed.invoice_payload,
    claimed.tax_invoice_id,
    claimed.attempt_count
  FROM claimed;
END;
$$;


--
-- Name: claim_tax_invoice_issue_jobs(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_tax_invoice_issue_jobs(p_limit integer DEFAULT 20, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id bigint, tenant_id bigint, branch_id bigint, order_id bigint, payment_id bigint, invoice_payload jsonb, tax_invoice_id bigint, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  UPDATE public.tax_invoice_issue_jobs job
  SET status = 'reconcile_required',
      locked_until = NULL,
      last_error = 'lease_expired_provider_state_unknown',
      updated_at = now()
  FROM public.tax_invoices invoice
  WHERE job.tax_invoice_id = invoice.id
    AND job.status = 'processing'
    AND job.locked_until < now()
    AND invoice.status IN ('signing', 'submitted');

  RETURN QUERY
  WITH candidates AS (
    SELECT job.id
    FROM public.tax_invoice_issue_jobs job
    WHERE (
        job.status = 'queued'
        AND job.available_at <= now()
      )
      OR (
        job.status = 'processing'
        AND job.locked_until < now()
      )
    ORDER BY job.available_at, job.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 20)
  ), claimed AS (
    UPDATE public.tax_invoice_issue_jobs job
    SET status = 'processing',
        locked_until = now() + make_interval(
          secs => LEAST(
            GREATEST(COALESCE(p_lease_seconds, 300), 30),
            900
          )
        ),
        attempt_count = job.attempt_count + 1,
        updated_at = now()
    FROM candidates
    WHERE job.id = candidates.id
    RETURNING job.*
  )
  SELECT
    claimed.id,
    claimed.tenant_id,
    claimed.branch_id,
    claimed.order_id,
    claimed.payment_id,
    claimed.invoice_payload,
    claimed.tax_invoice_id,
    claimed.attempt_count
  FROM claimed;
END;
$$;


--
-- Name: cleanup_abandoned_payments(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_abandoned_payments(p_threshold interval DEFAULT '24:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE public.payments
  SET
    status = 'failed',
    provider_data = COALESCE(provider_data, '{}'::jsonb) || jsonb_build_object(
      'cleanup_reason', 'abandoned',
      'cleanup_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'cleanup_threshold', extract(epoch FROM p_threshold)::int
    ),
    updated_at = now()
  WHERE status = 'pending'
    AND created_at < now() - p_threshold;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION cleanup_abandoned_payments(p_threshold interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_abandoned_payments(p_threshold interval) IS 'POS payment janitor: marks pending rows older than p_threshold (default 24h) as failed and stamps cleanup metadata into provider_data. Cron-scheduled hourly; safe to call manually for ad-hoc cleanup.';


--
-- Name: cleanup_kds_tickets_as_system(timestamp with time zone, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_kds_tickets_as_system(p_older_than timestamp with time zone, p_reset_before_local_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted_total INT := 0;
  v_by_status JSONB := '{}'::jsonb;
  v_by_branch JSONB := '[]'::jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  IF p_older_than IS NULL AND p_reset_before_local_date IS NULL THEN
    RAISE EXCEPTION 'cleanup_cutoff_required' USING ERRCODE = '22023';
  END IF;

  WITH candidates AS (
    SELECT
      kt.id,
      kt.tenant_id,
      kt.branch_id,
      kt.status
    FROM public.kds_tickets kt
    JOIN public.branches b
      ON b.id = kt.branch_id
     AND b.tenant_id = kt.tenant_id
    LEFT JOIN public.kitchen_send_batches ksb
      ON ksb.id = kt.kitchen_send_batch_id
     AND ksb.tenant_id = kt.tenant_id
    WHERE kt.status IN ('pending', 'preparing', 'ready')
      AND b.branch_kind = 'branch'
      AND (
        (
          p_older_than IS NOT NULL
          AND COALESCE(ksb.created_at, kt.created_at) < p_older_than
        )
        OR (
          p_reset_before_local_date IS NOT NULL
          AND (
            COALESCE(ksb.created_at, kt.created_at)
              AT TIME ZONE 'Asia/Ho_Chi_Minh'
          )::date < p_reset_before_local_date
        )
      )
  ),
  deleted AS (
    DELETE FROM public.kds_tickets kt
    USING candidates c
    WHERE kt.id = c.id
    RETURNING kt.tenant_id, kt.branch_id, kt.status
  ),
  status_counts AS (
    SELECT status, count(*)::int AS deleted_count
    FROM deleted
    GROUP BY status
  ),
  branch_counts AS (
    SELECT tenant_id, branch_id, count(*)::int AS deleted_count
    FROM deleted
    GROUP BY tenant_id, branch_id
  )
  SELECT
    COALESCE((SELECT count(*)::int FROM deleted), 0),
    COALESCE(
      (SELECT jsonb_object_agg(status, deleted_count) FROM status_counts),
      '{}'::jsonb
    ),
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'tenant_id', tenant_id,
            'branch_id', branch_id,
            'deleted_count', deleted_count
          )
          ORDER BY tenant_id, branch_id
        )
        FROM branch_counts
      ),
      '[]'::jsonb
    )
  INTO v_deleted_total, v_by_status, v_by_branch;

  RETURN jsonb_build_object(
    'deleted_total', v_deleted_total,
    'by_status', v_by_status,
    'by_branch', v_by_branch,
    'older_than', p_older_than,
    'reset_before_local_date', p_reset_before_local_date
  );
END;
$$;


--
-- Name: FUNCTION cleanup_kds_tickets_as_system(p_older_than timestamp with time zone, p_reset_before_local_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_kds_tickets_as_system(p_older_than timestamp with time zone, p_reset_before_local_date date) IS 'Service-role-only KDS board cleanup. Deletes active queue tickets older than the cutoff or before the current Asia/Ho_Chi_Minh local date; does not mutate orders, order_items, kitchen batches, or counters.';


--
-- Name: clear_branch_menu_daily_limit(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_role      TEXT   := public.auth_role();
  v_branch    BIGINT := public.auth_branch_id();
  v_today     DATE   := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_row       public.branch_menu_item_daily_limits;
BEGIN
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF v_role NOT IN ('owner', 'branch_manager') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'branch_manager'
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  UPDATE public.branch_menu_item_daily_limits
     SET limit_quantity = NULL,
         is_disabled = FALSE,
         updated_at = now()
   WHERE tenant_id = v_tenant_id
     AND branch_id = p_branch_id
     AND menu_item_id = p_menu_item_id
     AND limit_date = v_today
   RETURNING * INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'deleted', 0,
      'cleared', 1,
      'sold_today', v_row.sold_today,
      'stock_capacity', v_row.stock_capacity
    );
  END IF;

  RETURN jsonb_build_object('deleted', 0, 'cleared', 0);
END;
$$;


--
-- Name: FUNCTION clear_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint) IS 'Clears today''s manual limit by nulling limit_quantity and re-enabling the item while KEEPING the row, so sold_today survives a mid-day re-limit (deleting the row would reset the counter and over-permit). Never copies stock capacity into the manual limit.';


--
-- Name: clear_employee_shift_task_override(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_employee_shift_task_override(p_employee_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_template_id bigint;
BEGIN
  IF auth.uid() IS NULL OR v_tenant_id IS NULL
     OR NOT public.has_permission(NULL, 'hr:manage_position_tasks') THEN
    RAISE EXCEPTION 'position_tasks_forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT employee.default_checklist_template_id
  INTO v_template_id
  FROM public.employees employee
  WHERE employee.id = p_employee_id
    AND employee.tenant_id = v_tenant_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_template_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.shift_checklist_templates template
    WHERE template.id = v_template_id
      AND template.tenant_id = v_tenant_id
      AND template.employee_id = p_employee_id
      AND template.is_active
  ) THEN
    RETURN false;
  END IF;

  UPDATE public.employees
  SET default_checklist_template_id = NULL,
      updated_at = now()
  WHERE id = p_employee_id
    AND tenant_id = v_tenant_id;

  UPDATE public.shift_checklist_templates
  SET is_active = false,
      updated_at = now()
  WHERE id = v_template_id
    AND tenant_id = v_tenant_id
    AND employee_id = p_employee_id;

  PERFORM public.log_audit(
    'update',
    'employee_shift_task_override',
    p_employee_id,
    jsonb_build_object('template_id', v_template_id),
    jsonb_build_object('template_id', NULL)
  );

  RETURN true;
END;
$$;


--
-- Name: clear_order_discount(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_order_discount(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order RECORD;
  v_updated_order RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'cashier')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status,
         o.discount_amount, o.order_discount_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.orders
     SET discount_type  = NULL,
         discount_value = NULL,
         discount_note  = NULL,
         updated_at     = now()
   WHERE id = p_order_id
   RETURNING order_discount_amount, item_discount_amount,
             discount_amount, total_amount
   INTO v_updated_order;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_order.tenant_id, p_order_id, v_order.status, v_order.status, v_uid,
    'discount_cleared (was '
      || COALESCE(v_order.order_discount_amount::TEXT, '0') || 'đ order-level)'
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'order_discount_amount', v_updated_order.order_discount_amount,
    'item_discount_amount', v_updated_order.item_discount_amount,
    'total_discount_amount', v_updated_order.discount_amount,
    'total_amount', v_updated_order.total_amount
  );
END;
$$;


--
-- Name: FUNCTION clear_order_discount(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_order_discount(p_order_id bigint) IS 'Clear order-level discount only; item-level discounts remain active. Total discount is normalized by triggers.';


--
-- Name: clear_order_item_discount(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_order_item_discount(p_order_item_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_row RECORD;
  v_reason_trim TEXT;
  v_order_totals RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  v_reason_trim := COALESCE(trim(p_reason), '');
  IF length(v_reason_trim) < 3 THEN
    RAISE EXCEPTION 'discount_note_required' USING ERRCODE = '22023';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'cashier')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT oi.id AS order_item_id, oi.order_id, oi.tenant_id, oi.status AS item_status,
         oi.discount_amount AS old_discount_amount,
         o.branch_id, o.status AS order_status, o.payment_status
  INTO v_row
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id AND o.tenant_id = oi.tenant_id
  WHERE oi.id = p_order_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_row.order_id);

  SELECT oi.id AS order_item_id, oi.order_id, oi.tenant_id, oi.status AS item_status,
         oi.discount_amount AS old_discount_amount,
         o.branch_id, o.status AS order_status, o.payment_status
  INTO v_row
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id AND o.tenant_id = oi.tenant_id
  WHERE oi.id = p_order_item_id
  FOR UPDATE OF oi, o;

  IF v_row.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_row.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_row.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_row.order_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_row.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
     SET discount_type = NULL,
         discount_value = NULL,
         discount_note = NULL,
         updated_at = now()
   WHERE id = p_order_item_id;

  SELECT discount_amount, item_discount_amount, order_discount_amount, total_amount
  INTO v_order_totals
  FROM public.orders
  WHERE id = v_row.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_row.tenant_id, v_row.order_id, v_row.order_status, v_row.order_status, v_uid,
    'item_discount_cleared: item ' || p_order_item_id::TEXT
      || ' (was ' || COALESCE(v_row.old_discount_amount::TEXT, '0') || 'đ)'
      || ' :: ' || v_reason_trim
  );

  RETURN jsonb_build_object(
    'order_id', v_row.order_id,
    'order_item_id', p_order_item_id,
    'order_discount_amount', v_order_totals.order_discount_amount,
    'item_discount_amount', v_order_totals.item_discount_amount,
    'total_discount_amount', v_order_totals.discount_amount,
    'total_amount', v_order_totals.total_amount
  );
END;
$$;


--
-- Name: FUNCTION clear_order_item_discount(p_order_item_id bigint, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_order_item_discount(p_order_item_id bigint, p_reason text) IS 'Clear item-level discount with required reason. Blocks paid/terminal orders. Order total is normalized by triggers.';


--
-- Name: close_period_hard(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_period_hard(p_tenant_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'cross-tenant close forbidden' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at, hard_closed_at, closed_by)
  VALUES (p_tenant_id, p_year, p_month, now(), now(), v_uid)
  ON CONFLICT (tenant_id, year, month) DO UPDATE
    SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at),
        hard_closed_at = COALESCE(public.accounting_periods.hard_closed_at, EXCLUDED.hard_closed_at),
        closed_by = EXCLUDED.closed_by;
END; $$;


--
-- Name: close_period_soft(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_period_soft(p_tenant_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'cross-tenant close forbidden' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at, closed_by)
  VALUES (p_tenant_id, p_year, p_month, now(), v_uid)
  ON CONFLICT (tenant_id, year, month) DO UPDATE
    SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at),
        closed_by = COALESCE(public.accounting_periods.closed_by, EXCLUDED.closed_by);
END; $$;


--
-- Name: close_pos_session(bigint, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_pos_session(p_session_id bigint, p_closing_cash numeric, p_note text DEFAULT NULL::text, p_variance_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session record;
  v_paid_count integer;
  v_unpaid_count integer;
  v_cash_revenue numeric(15,2);
  v_noncash_revenue numeric(15,2);
  v_expected_cash numeric(15,2);
  v_cash_difference numeric(15,2);
  v_threshold numeric(15,2);
  v_closed_by uuid;
  v_variance_trim text;
BEGIN
  IF p_closing_cash IS NULL OR p_closing_cash < 0 THEN
    RAISE EXCEPTION 'closing_cash_must_be_non_negative'
      USING ERRCODE = '22023';
  END IF;

  v_closed_by := auth.uid();
  IF v_closed_by IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT
    session.id,
    session.tenant_id,
    session.branch_id,
    session.opening_cash,
    session.opened_at,
    session.status
  INTO v_session
  FROM public.pos_sessions session
  WHERE session.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_session.status <> 'open' THEN
    RAISE EXCEPTION 'session_already_closed' USING ERRCODE = 'P0001';
  END IF;

  SELECT
    count(DISTINCT orders.id) FILTER (
      WHERE EXISTS (
        SELECT 1
        FROM public.payments payment
        WHERE payment.tenant_id = orders.tenant_id
          AND payment.order_id = orders.id
          AND payment.status = 'completed'
          AND payment.paid_at IS NOT NULL
      )
    ),
    count(DISTINCT orders.id) FILTER (
      WHERE orders.status <> 'cancelled'
        AND NOT EXISTS (
          SELECT 1
          FROM public.payments payment
          WHERE payment.tenant_id = orders.tenant_id
            AND payment.order_id = orders.id
            AND payment.status = 'completed'
            AND payment.paid_at IS NOT NULL
        )
    )
  INTO v_paid_count, v_unpaid_count
  FROM public.orders orders
  WHERE orders.tenant_id = v_session.tenant_id
    AND orders.pos_session_id = p_session_id;

  SELECT
    COALESCE(sum(payment.amount) FILTER (
      WHERE payment.method = 'cash'
    ), 0),
    COALESCE(sum(payment.amount) FILTER (
      WHERE payment.method <> 'cash'
    ), 0)
  INTO v_cash_revenue, v_noncash_revenue
  FROM public.payments payment
  JOIN public.orders orders
    ON orders.id = payment.order_id
   AND orders.tenant_id = payment.tenant_id
   AND orders.branch_id = payment.branch_id
  WHERE orders.tenant_id = v_session.tenant_id
    AND orders.pos_session_id = p_session_id
    AND payment.status = 'completed'
    AND payment.paid_at IS NOT NULL;

  v_expected_cash := v_session.opening_cash + v_cash_revenue;
  v_cash_difference := p_closing_cash - v_expected_cash;
  v_threshold := GREATEST(
    50000::numeric,
    round(v_expected_cash * 0.005, 2)
  );
  v_variance_trim := NULLIF(btrim(COALESCE(p_variance_note, '')), '');

  UPDATE public.pos_sessions
  SET
    status = 'closed',
    closed_at = now(),
    closed_by = v_closed_by,
    closing_cash = p_closing_cash,
    expected_cash = v_expected_cash,
    cash_difference = v_cash_difference,
    note = p_note,
    variance_approval_note = v_variance_trim,
    variance_approver_user_id = NULL,
    variance_resolution_type = NULL,
    variance_settlement_amount = NULL,
    variance_resolved_at = NULL
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'session_id', p_session_id,
    'opening_cash', v_session.opening_cash,
    'closing_cash', p_closing_cash,
    'expected_cash', v_expected_cash,
    'cash_revenue', v_cash_revenue,
    'noncash_revenue', v_noncash_revenue,
    'cash_difference', v_cash_difference,
    'variance_threshold', v_threshold,
    'variance_breached', abs(v_cash_difference) > v_threshold,
    'order_count', v_paid_count + v_unpaid_count,
    'paid_order_count', v_paid_count,
    'unpaid_order_count', v_unpaid_count,
    'opened_at', v_session.opened_at,
    'closed_at', now()
  );
END;
$$;


--
-- Name: FUNCTION close_pos_session(p_session_id bigint, p_closing_cash numeric, p_note text, p_variance_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.close_pos_session(p_session_id bigint, p_closing_cash numeric, p_note text, p_variance_note text) IS 'Closes a POS session. Expected cash uses completed cash payments with paid_at; stale order payment mirrors never suppress collected money.';


--
-- Name: close_purchase_order(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_purchase_order(p_po_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_po public.purchase_orders%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF pg_catalog.length(
    pg_catalog.btrim(coalesce(p_reason, ''))
  ) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT po.*
  INTO v_po
  FROM public.purchase_orders AS po
  WHERE po.id = p_po_id
    AND po.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_po.branch_id,
    'procurement:po_approve'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_po.status <> 'partially_received' THEN
    RAISE EXCEPTION 'purchase_order_not_closable'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.goods_received_notes
  SET status = 'cancelled',
      notes = pg_catalog.concat_ws(
        E'\n',
        nullif(notes, ''),
        'Đóng phần còn lại của PO: ' || pg_catalog.btrim(p_reason)
      ),
      updated_at = pg_catalog.now()
  WHERE tenant_id = v_tenant
    AND po_id = p_po_id
    AND status = 'draft';

  UPDATE public.purchase_orders
  SET status = 'closed',
      status_reason = pg_catalog.btrim(p_reason),
      closed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  WHERE id = p_po_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'procurement.po.closed',
    'purchase_order',
    p_po_id,
    pg_catalog.to_jsonb(v_po),
    pg_catalog.jsonb_build_object(
      'status', 'closed',
      'reason', pg_catalog.btrim(p_reason)
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'id', p_po_id,
    'status', 'closed'
  );
END;
$$;


--
-- Name: close_purchase_request(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_purchase_request(p_request_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_request public.purchase_requests%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF pg_catalog.length(
    pg_catalog.btrim(coalesce(p_reason, ''))
  ) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT demand.*
  INTO v_request
  FROM public.purchase_requests AS demand
  WHERE demand.id = p_request_id
    AND demand.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_demand_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_request.branch_id,
    'procurement:po_approve'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_request.status <> 'partially_ordered' THEN
    RAISE EXCEPTION 'purchase_request_not_closable'
      USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.purchase_request_allocations
  WHERE tenant_id = v_tenant
    AND purchase_request_id = p_request_id;

  UPDATE public.purchase_requests
  SET status = 'closed',
      status_reason = pg_catalog.btrim(p_reason),
      closed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  WHERE id = p_request_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'procurement.demand.closed',
    'purchase_request',
    p_request_id,
    pg_catalog.to_jsonb(v_request),
    pg_catalog.jsonb_build_object(
      'status', 'closed',
      'reason', pg_catalog.btrim(p_reason)
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'request_id', p_request_id,
    'status', 'closed'
  );
END;
$$;


--
-- Name: close_recount_round(bigint, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_recount_round(p_session_id bigint, p_round_no smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_session public.stocktake_sessions%ROWTYPE;
  v_need integer := 0;
  v_final integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT session.*
  INTO v_session
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant
  FOR UPDATE OF session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_session.branch_id,
    'inventory:stocktake_recount'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_session.status <> 'in_progress' THEN
    RAISE EXCEPTION 'session not in_progress'
      USING ERRCODE = '22023';
  END IF;
  IF p_round_no <> v_session.current_round THEN
    RAISE EXCEPTION 'round % does not match current_round %',
      p_round_no,
      v_session.current_round
      USING ERRCODE = '22023';
  END IF;

  WITH latest AS (
    SELECT
      line.id,
      line.ingredient_id,
      line.counted_quantity,
      line.system_quantity,
      line.abc_class,
      coalesce(line.counted_quantity, 0)
        - coalesce(line.system_quantity, 0) AS delta,
      CASE
        WHEN line.system_quantity IS NULL
          OR line.system_quantity = 0 THEN NULL
        ELSE abs(
          coalesce(line.counted_quantity, 0)
            - line.system_quantity
        ) / line.system_quantity
      END AS pct
    FROM public.stocktake_lines AS line
    WHERE line.tenant_id = v_tenant
      AND line.session_id = p_session_id
      AND line.round_no = p_round_no
  ),
  decided AS (
    SELECT
      latest.*,
      CASE
        WHEN latest.counted_quantity IS NULL THEN FALSE
        WHEN latest.abc_class = 'A' THEN
          coalesce(latest.pct, 0)
            > v_session.variance_threshold_pct_class_a / 100.0
          OR abs(latest.delta) > (
            v_session.variance_threshold_vnd_class_a
            / greatest((
              SELECT stock.avg_unit_cost
              FROM public.stock_levels AS stock
              WHERE stock.tenant_id = v_tenant
                AND stock.branch_id = v_session.branch_id
                AND stock.location_id = v_session.location_id
                AND stock.ingredient_id = latest.ingredient_id
              LIMIT 1
            ), 1)
          )
        ELSE
          coalesce(latest.pct, 0)
            > v_session.variance_threshold_pct / 100.0
          OR abs(latest.delta) > (
            v_session.variance_threshold_vnd
            / greatest((
              SELECT stock.avg_unit_cost
              FROM public.stock_levels AS stock
              WHERE stock.tenant_id = v_tenant
                AND stock.branch_id = v_session.branch_id
                AND stock.location_id = v_session.location_id
                AND stock.ingredient_id = latest.ingredient_id
              LIMIT 1
            ), 1)
          )
      END AS needs_recount
    FROM latest
  )
  UPDATE public.stocktake_lines AS line
  SET needs_recount = decided.needs_recount,
      is_final = NOT decided.needs_recount
  FROM decided
  WHERE line.id = decided.id
    AND line.tenant_id = v_tenant;

  IF p_round_no > 1 THEN
    WITH converged AS (
      SELECT DISTINCT line.ingredient_id
      FROM public.stocktake_lines AS line
      WHERE line.tenant_id = v_tenant
        AND line.session_id = p_session_id
        AND line.round_no = p_round_no
        AND NOT line.needs_recount
    ),
    medians AS (
      SELECT
        line.ingredient_id,
        percentile_cont(0.5)
          WITHIN GROUP (ORDER BY line.counted_quantity) AS median
      FROM public.stocktake_lines AS line
      WHERE line.tenant_id = v_tenant
        AND line.session_id = p_session_id
        AND line.counted_quantity IS NOT NULL
        AND line.ingredient_id IN (
          SELECT converged.ingredient_id
          FROM converged
        )
      GROUP BY line.ingredient_id
      HAVING count(*) >= 2
    )
    UPDATE public.stocktake_lines AS line
    SET counted_quantity = medians.median,
        is_final = TRUE,
        needs_recount = FALSE
    FROM medians
    WHERE line.tenant_id = v_tenant
      AND line.session_id = p_session_id
      AND line.ingredient_id = medians.ingredient_id
      AND line.round_no = 1;
  END IF;

  SELECT
    count(*) FILTER (WHERE line.needs_recount),
    count(*) FILTER (WHERE line.is_final)
  INTO v_need, v_final
  FROM public.stocktake_lines AS line
  WHERE line.tenant_id = v_tenant
    AND line.session_id = p_session_id
    AND line.round_no = p_round_no;

  IF v_need > 0 AND v_session.current_round < 4 THEN
    UPDATE public.stocktake_sessions
    SET current_round = v_session.current_round + 1
    WHERE id = p_session_id
      AND tenant_id = v_tenant;
  END IF;

  RETURN jsonb_build_object(
    'round_no',
    p_round_no,
    'needs_recount_count',
    v_need,
    'final_count',
    v_final,
    'next_round',
    CASE
      WHEN v_need > 0 AND v_session.current_round < 4
        THEN v_session.current_round + 1
      ELSE NULL
    END,
    'round_4_escalation_required',
    v_need > 0 AND v_session.current_round >= 3
  );
END;
$$;


--
-- Name: close_stock_request(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_stock_request(p_request_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_request public.stock_requests%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT request.*
  INTO v_request
  FROM public.stock_requests AS request
  WHERE request.id = p_request_id
    AND request.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stock_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_request.status <> 'submitted'
     OR NOT EXISTS (
       SELECT 1
       FROM public.stock_request_items AS item
       WHERE item.request_id = p_request_id
         AND item.tenant_id = v_tenant
         AND item.status = 'pending'
     ) THEN
    RAISE EXCEPTION 'stock_request_not_closable'
      USING ERRCODE = '23514';
  END IF;
  IF NOT public.auth_is_owner(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden_request_close' USING ERRCODE = '42501';
  END IF;

  UPDATE public.stock_request_items
  SET status = 'cancelled',
      updated_at = now()
  WHERE request_id = p_request_id
    AND tenant_id = v_tenant
    AND status = 'pending';

  UPDATE public.stock_requests
  SET status = 'closed',
      status_reason = btrim(p_reason),
      closed_at = now(),
      updated_at = now()
  WHERE id = p_request_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'inventory.request.closed',
    'stock_request',
    p_request_id,
    to_jsonb(v_request),
    jsonb_build_object('status', 'closed', 'reason', btrim(p_reason))
  );

  RETURN jsonb_build_object(
    'request_id', p_request_id,
    'status', 'closed'
  );
END;
$$;


--
-- Name: complete_kds_tickets(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_kds_tickets(p_branch_id bigint, p_ticket_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ticket_ids bigint[] := ARRAY[]::bigint[];
  v_updated_ticket_ids bigint[] := ARRAY[]::bigint[];
  v_order_ids bigint[] := ARRAY[]::bigint[];
  v_requested_count int := 0;
  v_locked_count int := 0;
  v_completed_count int := 0;
  v_group_count int := 0;
  v_order_id bigint;
  v_print_result jsonb := jsonb_build_object(
    'jobs', '[]'::jsonb,
    'requested_ticket_count', 0,
    'printed_ticket_count', 0,
    'skipped_ticket_count', 0
  );
  v_print_warning text := NULL;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL OR p_branch_id <= 0 THEN
    RAISE EXCEPTION 'invalid_branch' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission_any('kds:mark_ready') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT ticket_id), ARRAY[]::bigint[])
  INTO v_ticket_ids
  FROM unnest(COALESCE(p_ticket_ids, ARRAY[]::bigint[])) AS input(ticket_id)
  WHERE ticket_id IS NOT NULL AND ticket_id > 0;

  v_requested_count := COALESCE(array_length(v_ticket_ids, 1), 0);

  IF v_requested_count = 0 THEN
    RAISE EXCEPTION 'no_tickets' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT kt.order_id ORDER BY kt.order_id), ARRAY[]::bigint[])
  INTO v_order_ids
  FROM public.kds_tickets kt
  WHERE kt.id = ANY(v_ticket_ids)
    AND kt.tenant_id = public.auth_tenant_id()
    AND kt.branch_id = p_branch_id
    AND (public.auth_role() = 'owner' OR kt.branch_id = public.auth_branch_id());

  FOREACH v_order_id IN ARRAY v_order_ids LOOP
    PERFORM pg_advisory_xact_lock(v_order_id);
  END LOOP;

  WITH locked AS (
    SELECT kt.id
    FROM public.kds_tickets kt
    WHERE kt.id = ANY(v_ticket_ids)
      AND kt.tenant_id = public.auth_tenant_id()
      AND kt.branch_id = p_branch_id
      AND (public.auth_role() = 'owner' OR kt.branch_id = public.auth_branch_id())
    FOR UPDATE
  )
  SELECT COUNT(*) INTO v_locked_count
  FROM locked;

  IF v_locked_count <> v_requested_count THEN
    RAISE EXCEPTION 'ticket_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COUNT(DISTINCT COALESCE(
    'batch:' || kt.kitchen_send_batch_id::text,
    'order:' || kt.order_id::text
  ))
  INTO v_group_count
  FROM public.kds_tickets kt
  WHERE kt.id = ANY(v_ticket_ids)
    AND kt.tenant_id = public.auth_tenant_id()
    AND kt.branch_id = p_branch_id;

  IF v_group_count <> 1 THEN
    RAISE EXCEPTION 'mixed_kds_card' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT kt.order_id), ARRAY[]::bigint[])
  INTO v_order_ids
  FROM public.kds_tickets kt
  WHERE kt.id = ANY(v_ticket_ids)
    AND kt.tenant_id = public.auth_tenant_id()
    AND kt.branch_id = p_branch_id;

  WITH updated AS (
    UPDATE public.kds_tickets kt
    SET status = 'ready',
        bumped_at = now(),
        bumped_by = v_uid,
        first_ready_at = COALESCE(first_ready_at, now()),
        updated_at = now()
    WHERE kt.id = ANY(v_ticket_ids)
      AND kt.tenant_id = public.auth_tenant_id()
      AND kt.branch_id = p_branch_id
      AND kt.status IN ('pending', 'preparing')
    RETURNING kt.id
  )
  SELECT
    COALESCE(array_agg(id), ARRAY[]::bigint[]),
    COUNT(*)
  INTO v_updated_ticket_ids, v_completed_count
  FROM updated;

  IF v_completed_count > 0 THEN
    BEGIN
      v_print_result := private.enqueue_kitchen_completion_print_internal(
        p_branch_id,
        v_updated_ticket_ids,
        v_uid
      );

      IF COALESCE((v_print_result->>'skipped_ticket_count')::int, 0) > 0 THEN
        v_print_warning := 'kitchen_print_skipped';
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_print_warning := 'kitchen_print_enqueue_failed';
        v_print_result := jsonb_build_object(
          'jobs', '[]'::jsonb,
          'requested_ticket_count', v_completed_count,
          'printed_ticket_count', 0,
          'skipped_ticket_count', v_completed_count
        );
        RAISE LOG 'complete_kds_tickets print enqueue skipped branch_id=%, ticket_ids=%, sqlstate=%, error=%',
          p_branch_id,
          v_updated_ticket_ids,
          SQLSTATE,
          SQLERRM;
    END;
  END IF;

  FOREACH v_order_id IN ARRAY v_order_ids LOOP
    PERFORM public.check_order_ready(v_order_id);
    PERFORM public.post_pos_sale_consumption_if_ready(v_order_id, v_uid);
  END LOOP;

  RETURN jsonb_build_object(
    'requested_count', v_requested_count,
    'completed_count', v_completed_count,
    'print_jobs', COALESCE(v_print_result->'jobs', '[]'::jsonb),
    'printed_ticket_count', COALESCE((v_print_result->>'printed_ticket_count')::int, 0),
    'skipped_ticket_count', COALESCE((v_print_result->>'skipped_ticket_count')::int, 0),
    'print_warning', v_print_warning
  );
END;
$$;


--
-- Name: FUNCTION complete_kds_tickets(p_branch_id bigint, p_ticket_ids bigint[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_kds_tickets(p_branch_id bigint, p_ticket_ids bigint[]) IS 'Atomically marks visible pending/preparing KDS tickets ready and queues matching kitchen print jobs for the completed tickets only. Does not close POS/payment/table state.';


--
-- Name: complete_payment_and_consume_stock(bigint, numeric, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_payment_and_consume_stock(p_payment_id bigint, p_expected_amount numeric DEFAULT NULL::numeric, p_provider_data jsonb DEFAULT NULL::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(status text, payment_id bigint, order_id bigint, stock_consumed boolean, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_payment record;
  v_order record;
  v_order_id bigint;
  v_line_subtotal numeric(15,2) := 0;
  v_recomputed_total numeric(15,2) := 0;
  v_stock_outcome jsonb := jsonb_build_object('consumed', false, 'reason', 'not_attempted');
BEGIN
  SELECT p.order_id
  INTO v_order_id
  FROM public.payments p
  WHERE p.id = p_payment_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'not_found'::text, p_payment_id, NULL::bigint, false,
      ('payment ' || p_payment_id || ' does not exist')::text;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(v_order_id);

  SELECT p.id, p.order_id, p.tenant_id, p.branch_id, p.amount, p.status
  INTO v_payment
  FROM public.payments p
  WHERE p.id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'not_found'::text, p_payment_id, NULL::bigint, false,
      ('payment ' || p_payment_id || ' does not exist')::text;
    RETURN;
  END IF;

  IF v_payment.status = 'completed' THEN
    RETURN QUERY SELECT
      'already_completed'::text, v_payment.id, v_payment.order_id, false,
      'payment was previously completed; no-op'::text;
    RETURN;
  END IF;

  IF v_payment.status <> 'pending' THEN
    RETURN QUERY SELECT
      'failed'::text, v_payment.id, v_payment.order_id, false,
      ('payment status=' || v_payment.status || ' cannot transition to completed')::text;
    RETURN;
  END IF;

  SELECT o.id, o.tenant_id, o.branch_id, o.tax_amount, o.service_charge,
         o.discount_amount, o.total_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_payment.order_id
    AND o.tenant_id = v_payment.tenant_id
    AND o.branch_id = v_payment.branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'failed'::text, v_payment.id, v_payment.order_id, false,
      'order_not_found'::text;
    RETURN;
  END IF;

  SELECT COALESCE(SUM(oi.quantity::numeric * oi.unit_price), 0)::numeric(15,2)
  INTO v_line_subtotal
  FROM public.order_items oi
  WHERE oi.order_id = v_order.id
    AND oi.tenant_id = v_order.tenant_id
    AND oi.status <> 'cancelled';

  v_recomputed_total := ROUND(
    v_line_subtotal
    + COALESCE(v_order.tax_amount, 0)
    + COALESCE(v_order.service_charge, 0)
    - COALESCE(v_order.discount_amount, 0),
    2
  );

  IF ABS(v_payment.amount - v_recomputed_total) > 1 THEN
    UPDATE public.payments
       SET status = 'failed',
           provider_data = COALESCE(p_provider_data, provider_data),
           updated_at = now()
     WHERE id = v_payment.id;

    RETURN QUERY SELECT
      'amount_mismatch_recomputed'::text, v_payment.id, v_payment.order_id, false,
      ('stored=' || v_payment.amount || ' recomputed=' || v_recomputed_total)::text;
    RETURN;
  END IF;

  IF p_expected_amount IS NOT NULL AND ABS(p_expected_amount - v_recomputed_total) > 1 THEN
    UPDATE public.payments
       SET status = 'failed',
           provider_data = COALESCE(p_provider_data, provider_data),
           updated_at = now()
     WHERE id = v_payment.id;

    RETURN QUERY SELECT
      'amount_mismatch_recomputed'::text, v_payment.id, v_payment.order_id, false,
      ('expected=' || p_expected_amount || ' recomputed=' || v_recomputed_total)::text;
    RETURN;
  END IF;

  UPDATE public.payments
     SET status = 'completed',
         paid_at = COALESCE(paid_at, now()),
         provider_data = COALESCE(p_provider_data, provider_data),
         updated_at = now()
   WHERE id = v_payment.id;

  UPDATE public.orders
     SET payment_status = 'paid',
         updated_at = now()
   WHERE id = v_payment.order_id
     AND tenant_id = v_payment.tenant_id;

  PERFORM public.finalize_paid_order(v_payment.order_id, p_actor_id);
  v_stock_outcome := public.post_pos_sale_consumption_if_ready(v_payment.order_id, p_actor_id);

  RETURN QUERY SELECT
    'completed'::text,
    v_payment.id,
    v_payment.order_id,
    COALESCE((v_stock_outcome->>'consumed')::boolean, false),
    ('stock=' || COALESCE(v_stock_outcome->>'reason', 'posted'))::text;
END;
$$;


--
-- Name: FUNCTION complete_payment_and_consume_stock(p_payment_id bigint, p_expected_amount numeric, p_provider_data jsonb, p_actor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_payment_and_consume_stock(p_payment_id bigint, p_expected_amount numeric, p_provider_data jsonb, p_actor_id uuid) IS 'Marks a pending payment completed, marks the order paid, and posts POS stock outcome when pos_stock_outcome_posting is enabled and KDS readiness is complete.';


--
-- Name: complete_print_job(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_print_job(p_job_id bigint, p_success boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_service BOOLEAN := (auth.role() = 'service_role');
  v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  UPDATE public.print_jobs
    SET status = CASE WHEN p_success THEN 'printed' ELSE 'failed' END,
        printed_at = CASE WHEN p_success THEN now() ELSE printed_at END,
        last_error = CASE WHEN p_success THEN NULL ELSE p_error END
    WHERE id = p_job_id
      AND (v_is_service OR tenant_id = v_tenant);
END;
$$;


--
-- Name: complete_production_run(bigint, bigint, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_production_run(p_run_id bigint, p_branch_id bigint, p_actual_quantity numeric, p_actual_ingredients jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_run record;
  v_item jsonb;
  v_ingredient_id bigint;
  v_actual numeric;
  v_actual_total_base numeric;
  v_output_base numeric;
  v_input_value numeric(20,4);
  v_output_unit_cost numeric(15,2);
  v_old_output_qty numeric;
  v_old_output_wac numeric;
  v_new_output_qty numeric;
  v_shortages jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator()
     OR NOT public.has_permission(p_branch_id, 'inventory:production_confirm') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF p_actual_quantity IS NULL OR p_actual_quantity <= 0
     OR p_actual_quantity IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) THEN
    RAISE EXCEPTION 'actual_output_invalid' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_actual_ingredients) <> 'array' THEN
    RAISE EXCEPTION 'actual_payload_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT run.* INTO v_run
  FROM public.production_runs AS run
  JOIN public.branches AS branch
    ON branch.id = run.branch_id
   AND branch.tenant_id = run.tenant_id
   AND branch.branch_kind = 'central_kitchen'
   AND branch.is_active IS TRUE
  WHERE run.tenant_id = v_tenant
    AND run.id = p_run_id
    AND run.branch_id = p_branch_id
  FOR UPDATE OF run;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_run_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_run.status <> 'in_progress' THEN
    RAISE EXCEPTION 'production_transition_invalid' USING ERRCODE = '22023';
  END IF;
  IF v_run.target_branch_id <> v_run.branch_id THEN
    RAISE EXCEPTION 'production_site_invalid' USING ERRCODE = '42501';
  END IF;

  IF jsonb_array_length(p_actual_ingredients) <> (
    SELECT count(*) FROM public.production_run_lines AS line
    WHERE line.tenant_id = v_tenant AND line.production_run_id = p_run_id
  ) OR (
    SELECT count(DISTINCT item.value ->> 'ingredientId')
    FROM jsonb_array_elements(p_actual_ingredients) AS item(value)
  ) <> jsonb_array_length(p_actual_ingredients) THEN
    RAISE EXCEPTION 'actual_payload_invalid' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN
    SELECT item.value FROM jsonb_array_elements(p_actual_ingredients) AS item(value)
  LOOP
    BEGIN
      v_ingredient_id := nullif(v_item ->> 'ingredientId', '')::bigint;
      v_actual := nullif(v_item ->> 'actualQuantity', '')::numeric;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'actual_payload_invalid' USING ERRCODE = '22023';
    END;
    IF v_ingredient_id IS NULL OR v_actual IS NULL OR v_actual < 0
       OR v_actual IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) THEN
      RAISE EXCEPTION 'actual_payload_invalid' USING ERRCODE = '22023';
    END IF;

    UPDATE public.production_run_lines AS line
    SET actual_quantity = v_actual, updated_at = now()
    WHERE line.tenant_id = v_tenant
      AND line.production_run_id = p_run_id
      AND line.ingredient_id = v_ingredient_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'actual_payload_invalid' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  IF (
    SELECT count(*)
    FROM public.production_run_lines AS line
    WHERE line.tenant_id = v_tenant
      AND line.production_run_id = p_run_id
      AND line.actual_quantity IS NOT NULL
  ) <> jsonb_array_length(p_actual_ingredients) THEN
    RAISE EXCEPTION 'actual_payload_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(sum(line.actual_quantity * line.entry_to_base_factor), 0)
  INTO v_actual_total_base
  FROM public.production_run_lines AS line
  WHERE line.tenant_id = v_tenant
    AND line.production_run_id = p_run_id;
  IF v_actual_total_base <= 0 THEN
    RAISE EXCEPTION 'actual_consumption_zero' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.stock_levels (
    tenant_id, branch_id, location_id, ingredient_id, current_quantity
  )
  SELECT v_tenant, v_run.branch_id, v_run.source_location_id,
         line.ingredient_id, 0
  FROM public.production_run_lines AS line
  WHERE line.tenant_id = v_tenant
    AND line.production_run_id = p_run_id
  UNION ALL
  SELECT v_tenant, v_run.branch_id, v_run.target_location_id,
         v_run.finished_good_id, 0
  ON CONFLICT ON CONSTRAINT stock_levels_ingredient_branch_location_tenant_key
  DO NOTHING;

  PERFORM 1
  FROM public.stock_levels AS stock
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = v_run.branch_id
    AND (
      (stock.location_id = v_run.source_location_id AND EXISTS (
        SELECT 1 FROM public.production_run_lines AS line
        WHERE line.production_run_id = p_run_id
          AND line.ingredient_id = stock.ingredient_id
      ))
      OR (stock.location_id = v_run.target_location_id
          AND stock.ingredient_id = v_run.finished_good_id)
    )
  ORDER BY stock.ingredient_id, stock.location_id
  FOR UPDATE;

  WITH shortage AS (
    SELECT
      line.ingredient_id,
      ingredient.name AS ingredient_name,
      line.entry_unit_code AS unit,
      line.actual_quantity AS needed,
      stock.current_quantity / line.entry_to_base_factor AS on_hand
    FROM public.production_run_lines AS line
    JOIN public.ingredients AS ingredient
      ON ingredient.id = line.ingredient_id
     AND ingredient.tenant_id = line.tenant_id
    JOIN public.stock_levels AS stock
      ON stock.tenant_id = line.tenant_id
     AND stock.branch_id = v_run.branch_id
     AND stock.location_id = v_run.source_location_id
     AND stock.ingredient_id = line.ingredient_id
    WHERE line.tenant_id = v_tenant
      AND line.production_run_id = p_run_id
      AND stock.current_quantity < line.actual_quantity * line.entry_to_base_factor
    ORDER BY line.ingredient_id
    LIMIT 20
  )
  SELECT coalesce(jsonb_agg(to_jsonb(shortage)), '[]'::jsonb)
  INTO v_shortages
  FROM shortage;
  IF jsonb_array_length(v_shortages) > 0 THEN
    RAISE EXCEPTION 'insufficient_stock_for_production'
      USING ERRCODE = 'P0001', DETAIL = v_shortages::text;
  END IF;

  SELECT coalesce(sum(
    line.actual_quantity
      * line.entry_to_base_factor
      * coalesce(stock.avg_unit_cost, ingredient.unit_cost, 0)
  ), 0)
  INTO v_input_value
  FROM public.production_run_lines AS line
  JOIN public.ingredients AS ingredient
    ON ingredient.tenant_id = line.tenant_id
   AND ingredient.id = line.ingredient_id
  JOIN public.stock_levels AS stock
    ON stock.tenant_id = line.tenant_id
   AND stock.branch_id = v_run.branch_id
   AND stock.location_id = v_run.source_location_id
   AND stock.ingredient_id = line.ingredient_id
  WHERE line.tenant_id = v_tenant
    AND line.production_run_id = p_run_id;

  FOR v_ingredient_id, v_actual IN
    SELECT line.ingredient_id, line.actual_quantity
    FROM public.production_run_lines AS line
    WHERE line.tenant_id = v_tenant
      AND line.production_run_id = p_run_id
      AND line.actual_quantity > 0
    ORDER BY line.ingredient_id
  LOOP
    INSERT INTO public.stock_movements (
      tenant_id, branch_id, location_id, ingredient_id, type,
      quantity_change, reason, created_by, production_run_id, unit_cost,
      entry_unit_id, entry_quantity, entry_to_base_factor, entry_unit_code
    )
    SELECT
      v_tenant, v_run.branch_id, v_run.source_location_id, line.ingredient_id,
      'production_consumption',
      -(line.actual_quantity * line.entry_to_base_factor),
      'Production ' || v_run.production_number,
      v_uid, p_run_id, coalesce(stock.avg_unit_cost, ingredient.unit_cost, 0),
      line.entry_unit_id, line.actual_quantity,
      line.entry_to_base_factor, line.entry_unit_code
    FROM public.production_run_lines AS line
    JOIN public.ingredients AS ingredient
      ON ingredient.tenant_id = line.tenant_id
     AND ingredient.id = line.ingredient_id
    JOIN public.stock_levels AS stock
      ON stock.tenant_id = line.tenant_id
     AND stock.branch_id = v_run.branch_id
     AND stock.location_id = v_run.source_location_id
     AND stock.ingredient_id = line.ingredient_id
    WHERE line.tenant_id = v_tenant
      AND line.production_run_id = p_run_id
      AND line.ingredient_id = v_ingredient_id;
  END LOOP;

  v_output_base := p_actual_quantity * v_run.entry_to_base_factor;
  v_output_unit_cost := round(v_input_value / v_output_base, 2);
  SELECT stock.current_quantity, coalesce(stock.avg_unit_cost, 0)
  INTO v_old_output_qty, v_old_output_wac
  FROM public.stock_levels AS stock
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = v_run.branch_id
    AND stock.location_id = v_run.target_location_id
    AND stock.ingredient_id = v_run.finished_good_id;

  INSERT INTO public.stock_movements (
    tenant_id, branch_id, location_id, ingredient_id, type,
    quantity_change, reason, created_by, production_run_id, unit_cost,
    entry_unit_id, entry_quantity, entry_to_base_factor, entry_unit_code
  ) VALUES (
    v_tenant, v_run.branch_id, v_run.target_location_id, v_run.finished_good_id,
    'production_output', v_output_base,
    'Production ' || v_run.production_number,
    v_uid, p_run_id, v_output_unit_cost,
    v_run.entry_unit_id, p_actual_quantity,
    v_run.entry_to_base_factor, v_run.entry_unit_code
  );

  v_new_output_qty := v_old_output_qty + v_output_base;
  UPDATE public.stock_levels AS stock
  SET avg_unit_cost = CASE
        WHEN v_new_output_qty > 0 THEN
          ((v_old_output_qty * v_old_output_wac) + v_input_value) / v_new_output_qty
        ELSE v_output_unit_cost
      END,
      updated_at = now()
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = v_run.branch_id
    AND stock.location_id = v_run.target_location_id
    AND stock.ingredient_id = v_run.finished_good_id;

  UPDATE public.ingredients AS ingredient
  SET unit_cost = v_output_unit_cost, updated_at = now()
  WHERE ingredient.tenant_id = v_tenant
    AND ingredient.id = v_run.finished_good_id;

  UPDATE public.production_runs AS run
  SET status = 'completed', actual_quantity = p_actual_quantity,
      completed_at = now(), updated_at = now()
  WHERE run.tenant_id = v_tenant AND run.id = p_run_id;

  RETURN jsonb_build_object(
    'production_run_id', p_run_id,
    'status', 'completed',
    'actual_quantity', p_actual_quantity,
    'output_quantity_base', v_output_base,
    'input_value', v_input_value,
    'unit_cost', v_output_unit_cost
  );
END;
$$;


--
-- Name: complete_stocktake(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_stocktake(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_session public.stocktake_sessions%ROWTYPE;
  v_line record;
  v_fresh_quantity numeric(15,3);
  v_counted_base numeric(15,3);
  v_adjustment numeric(15,3);
  v_total_lines integer := 0;
  v_adjusted integer := 0;
  v_total_variance_abs numeric(15,3) := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT session.*
  INTO v_session
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant
  FOR UPDATE OF session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_session.branch_id,
    'inventory:stocktake_complete'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_session.status <> 'in_progress' THEN
    RAISE EXCEPTION 'session_not_in_progress'
      USING ERRCODE = '22023';
  END IF;

  PERFORM line.id
  FROM public.stocktake_lines AS line
  WHERE line.tenant_id = v_tenant
    AND line.session_id = p_session_id
    AND line.round_no = 1
  ORDER BY line.ingredient_id
  FOR UPDATE OF line;

  IF EXISTS (
    SELECT 1
    FROM public.stocktake_lines AS line
    WHERE line.tenant_id = v_tenant
      AND line.session_id = p_session_id
      AND line.round_no = 1
      AND line.counted_quantity IS NULL
  ) THEN
    RAISE EXCEPTION 'uncounted_lines_exist'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.stocktake_lines AS line
    WHERE line.tenant_id = v_tenant
      AND line.session_id = p_session_id
      AND line.round_no = 1
      AND line.needs_recount IS TRUE
  ) THEN
    RAISE EXCEPTION 'recount_lines_exist'
      USING ERRCODE = '22023';
  END IF;

  FOR v_line IN
    SELECT line.*
    FROM public.stocktake_lines AS line
    WHERE line.tenant_id = v_tenant
      AND line.session_id = p_session_id
      AND line.round_no = 1
    ORDER BY line.ingredient_id
  LOOP
    v_total_lines := v_total_lines + 1;

    SELECT coalesce(stock.current_quantity, 0)
    INTO v_fresh_quantity
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_session.branch_id
      AND stock.location_id = v_session.location_id
      AND stock.ingredient_id = v_line.ingredient_id
    FOR UPDATE;

    IF NOT FOUND THEN
      v_fresh_quantity := 0;
    END IF;

    v_counted_base := public.inv_to_base(
      v_line.ingredient_id,
      v_line.entry_unit_id,
      v_line.counted_quantity
    );
    v_adjustment := v_counted_base - v_fresh_quantity;

    IF v_adjustment <> 0 THEN
      v_adjusted := v_adjusted + 1;
      v_total_variance_abs :=
        v_total_variance_abs + abs(v_adjustment);

      INSERT INTO public.stock_movements (
        tenant_id,
        branch_id,
        ingredient_id,
        type,
        quantity_change,
        reason,
        created_by,
        location_id,
        entry_unit_id,
        entry_quantity
      )
      VALUES (
        v_tenant,
        v_session.branch_id,
        v_line.ingredient_id,
        'count_adjustment',
        v_adjustment,
        coalesce(
          v_line.variance_reason,
          'Stocktake #' || p_session_id::text
        ),
        v_uid,
        v_session.location_id,
        v_line.entry_unit_id,
        v_line.counted_quantity
      );
    END IF;
  END LOOP;

  UPDATE public.stocktake_sessions
  SET status = 'completed',
      completed_at = now()
  WHERE id = p_session_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'success',
    TRUE,
    'session_id',
    p_session_id,
    'total_lines',
    v_total_lines,
    'adjusted_lines',
    v_adjusted,
    'total_variance_abs',
    v_total_variance_abs
  );
END;
$$;


--
-- Name: FUNCTION complete_stocktake(p_session_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_stocktake(p_session_id bigint) IS 'Completes a tenant-bound warehouse stocktake and writes count adjustments.';


--
-- Name: compute_branch_daily_waste_caps(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_branch_daily_waste_caps() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pct CONSTANT NUMERIC := 0.025; v_floor CONSTANT NUMERIC := 500000; v_ceiling CONSTANT NUMERIC := 5000000; v_count INT;
BEGIN
  WITH daily AS (
    SELECT o.branch_id, DATE(o.created_at AT TIME ZONE COALESCE(b.timezone, 'Asia/Ho_Chi_Minh')) AS day,
           SUM(COALESCE(o.total_amount, 0)) AS daily_total
    FROM public.orders o JOIN public.branches b ON b.id = o.branch_id
    WHERE o.status = 'completed' AND o.created_at >= now() - INTERVAL '7 days'
    GROUP BY o.branch_id, DATE(o.created_at AT TIME ZONE COALESCE(b.timezone, 'Asia/Ho_Chi_Minh'))
  ), avg_rev AS (SELECT branch_id, AVG(daily_total) AS avg_rev FROM daily GROUP BY branch_id)
  INSERT INTO public.branch_daily_waste_cap (branch_id, cap_vnd, avg_revenue_7d, computed_at)
  SELECT b.id, GREATEST(v_floor, LEAST(v_ceiling, v_pct * COALESCE(a.avg_rev, 0))), COALESCE(a.avg_rev, 0), now()
  FROM public.branches b LEFT JOIN avg_rev a ON a.branch_id = b.id
  WHERE b.is_active = true
  ON CONFLICT (branch_id) DO UPDATE SET cap_vnd = EXCLUDED.cap_vnd, avg_revenue_7d = EXCLUDED.avg_revenue_7d, computed_at = EXCLUDED.computed_at;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END; $$;


--
-- Name: compute_discount_amount(text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_discount_amount(p_type text, p_value numeric, p_subtotal numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_subtotal NUMERIC := COALESCE(p_subtotal, 0);
  v_value    NUMERIC := COALESCE(p_value, 0);
BEGIN
  IF p_type IS NULL OR v_value <= 0 OR v_subtotal <= 0 THEN
    RETURN 0;
  END IF;

  IF p_type = 'pct' THEN
    -- Clamp pct to [0,100]; FLOOR nguyên VND.
    RETURN FLOOR(v_subtotal * LEAST(v_value, 100) / 100);
  ELSIF p_type = 'vnd' THEN
    -- Clamp tiền giảm về subtotal (void món xong, vnd-discount cũ có thể
    -- vượt subtotal mới — kéo về subtotal để total_amount không âm).
    RETURN LEAST(v_value, v_subtotal);
  END IF;

  RETURN 0;
END;
$$;


--
-- Name: FUNCTION compute_discount_amount(p_type text, p_value numeric, p_subtotal numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compute_discount_amount(p_type text, p_value numeric, p_subtotal numeric) IS 'Single source of truth for discount math. pct => FLOOR(subtotal*pct/100) clamped to subtotal; vnd => LEAST(value, subtotal). NULL/0 inputs => 0. Called by apply_order_discount, append_order_items, void_order_item, cancel_order on every recalc path.';


--
-- Name: compute_menu_item_stock_capacity(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_menu_item_stock_capacity(p_tenant_id bigint, p_branch_id bigint, p_menu_item_id bigint) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH recipe_lines AS (
    SELECT
      r.ingredient_id,
      CASE
        WHEN r.entry_unit_id IS NULL THEN r.quantity / r.yield_factor
        WHEN iu.id IS NULL THEN NULL::numeric
        ELSE (r.quantity / r.yield_factor) * iu.to_base_factor
      END AS per_portion_qty,
      (r.entry_unit_id IS NOT NULL AND iu.id IS NULL) AS line_missing_config
    FROM public.recipes r
    LEFT JOIN public.ingredient_units iu
      ON iu.tenant_id = p_tenant_id
     AND iu.ingredient_id = r.ingredient_id
     AND iu.unit_id = r.entry_unit_id
     AND iu.is_active = TRUE
    WHERE r.tenant_id = p_tenant_id
      AND r.menu_item_id = p_menu_item_id
  ),
  capacity_lines AS (
    SELECT
      rl.ingredient_id,
      rl.per_portion_qty,
      rl.line_missing_config,
      COALESCE(oh.on_hand, 0) AS on_hand
    FROM recipe_lines rl
    LEFT JOIN LATERAL (
      SELECT SUM(sl.current_quantity) AS on_hand
      FROM public.stock_levels sl
      JOIN public.inventory_locations il ON il.id = sl.location_id
      WHERE sl.tenant_id = p_tenant_id
        AND sl.branch_id = p_branch_id
        AND sl.ingredient_id = rl.ingredient_id
        AND il.location_kind = 'warehouse'
        AND il.is_active = TRUE
    ) oh ON TRUE
  )
  SELECT CASE
    WHEN COUNT(*) = 0 THEN NULL::integer
    WHEN BOOL_OR(
      line_missing_config
      OR per_portion_qty IS NULL
      OR per_portion_qty <= 0
    ) THEN NULL::integer
    ELSE FLOOR(MIN(on_hand / NULLIF(per_portion_qty, 0)) + 0.000001)::integer
  END
  FROM capacity_lines;
$$;


--
-- Name: FUNCTION compute_menu_item_stock_capacity(p_tenant_id bigint, p_branch_id bigint, p_menu_item_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compute_menu_item_stock_capacity(p_tenant_id bigint, p_branch_id bigint, p_menu_item_id bigint) IS 'Sellable portions of a menu item from active branch warehouse stock after converting recipe entry_unit_id to the ingredient base unit. NULL means no recipe or missing unit conversion.';


--
-- Name: confirm_cash_payment(bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_cash_payment(p_order_id bigint, p_cash_received numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid;
  v_order public.orders%ROWTYPE;
  v_existing_id bigint;
  v_existing_st text;
  v_existing_method text;
  v_existing_provider_ref text;
  v_payment_id bigint;
  v_provider_ref text;
  v_cash_change numeric(15,2);
  v_complete_res record;
  v_receipt_res jsonb;
  v_print_warning text;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:confirm_payment') THEN
    RAISE EXCEPTION 'permission denied: pos:confirm_payment' USING ERRCODE = '42501';
  END IF;

  IF v_order.payment_status = 'paid' THEN
    SELECT id INTO v_payment_id
    FROM public.payments
    WHERE order_id = p_order_id
      AND tenant_id = v_order.tenant_id
      AND status = 'completed'
    ORDER BY id DESC
    LIMIT 1;

    RETURN jsonb_build_object(
      'status',        'already_completed',
      'order_id',      p_order_id,
      'payment_id',    v_payment_id,
      'cash_received', v_order.cash_received,
      'cash_change',   COALESCE(v_order.cash_change, 0),
      'print_job_id',  NULL,
      'idempotent',    true
    );
  END IF;

  IF p_cash_received IS NULL THEN
    RAISE EXCEPTION 'cash_received required' USING ERRCODE = 'P0001';
  END IF;
  IF p_cash_received < v_order.total_amount THEN
    RAISE EXCEPTION 'cash_received (%) must be >= total_amount (%)',
      p_cash_received, v_order.total_amount
      USING ERRCODE = 'P0001';
  END IF;

  IF p_cash_received > GREATEST(v_order.total_amount * 10, 50000000) THEN
    RAISE EXCEPTION 'cash_received (%) exceeds sane upper bound for total (%)',
      p_cash_received, v_order.total_amount
      USING ERRCODE = 'P0001';
  END IF;

  v_provider_ref := upper(v_order.payment_code);
  v_cash_change := p_cash_received - v_order.total_amount;

  SELECT id, status, method, provider_ref
  INTO v_existing_id, v_existing_st, v_existing_method, v_existing_provider_ref
  FROM public.payments
  WHERE order_id = p_order_id
    AND tenant_id = v_order.tenant_id
    AND status <> 'failed'
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_st = 'completed' THEN
    RETURN jsonb_build_object(
      'status',        'already_completed',
      'order_id',      p_order_id,
      'payment_id',    v_existing_id,
      'cash_received', COALESCE(v_order.cash_received, p_cash_received),
      'cash_change',   COALESCE(v_order.cash_change, v_cash_change),
      'print_job_id',  NULL,
      'idempotent',    true
    );
  END IF;

  IF v_existing_st = 'pending' AND v_existing_method = 'momo' THEN
    RAISE EXCEPTION 'pending_momo_payment_requires_provider_resolution'
      USING ERRCODE = '55P03';
  END IF;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.payments
       SET method        = 'cash',
           amount        = v_order.total_amount,
           status        = 'pending',
           provider_ref  = COALESCE(v_provider_ref, v_existing_provider_ref),
           provider_data = COALESCE(provider_data, '{}'::jsonb)
                           || jsonb_build_object('description', COALESCE(v_provider_ref, v_existing_provider_ref)),
           updated_at    = now()
     WHERE id = v_existing_id;
    v_payment_id := v_existing_id;
  ELSE
    INSERT INTO public.payments (
      tenant_id, branch_id, order_id, method, amount, status, provider_ref, provider_data, created_by
    ) VALUES (
      v_order.tenant_id, v_order.branch_id, p_order_id, 'cash',
      v_order.total_amount, 'pending', v_provider_ref,
      jsonb_build_object('description', v_provider_ref),
      v_uid
    )
    RETURNING id INTO v_payment_id;
  END IF;

  UPDATE public.orders
     SET payment_method = 'cash',
         updated_at     = now()
   WHERE id = p_order_id;

  SELECT * INTO v_complete_res
  FROM public.complete_payment_and_consume_stock(
    v_payment_id,
    v_order.total_amount,
    jsonb_build_object('cash_received', p_cash_received, 'cash_change', v_cash_change),
    v_uid
  );

  IF v_complete_res.status = 'stock_failed' THEN
    RETURN jsonb_build_object(
      'status',      'stock_failed',
      'order_id',    p_order_id,
      'payment_id',  v_payment_id,
      'error_code',  'stock_consumption_failed',
      'detail',      v_complete_res.detail
    );
  END IF;

  IF v_complete_res.status = 'amount_mismatch_recomputed' THEN
    RETURN jsonb_build_object(
      'status',      'amount_mismatch_recomputed',
      'order_id',    p_order_id,
      'payment_id',  v_payment_id,
      'error_code',  'amount_mismatch_recomputed',
      'detail',      v_complete_res.detail
    );
  END IF;

  IF v_complete_res.status NOT IN ('completed', 'already_completed') THEN
    RAISE EXCEPTION 'payment completion failed: % (detail: %)',
      v_complete_res.status, v_complete_res.detail
      USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    v_receipt_res := public.enqueue_receipt_print(
      p_order_id,
      p_cash_received,
      v_cash_change
    );
  EXCEPTION WHEN OTHERS THEN
    v_print_warning := 'receipt_enqueue_failed';
    v_receipt_res := '{}'::jsonb;
    RAISE LOG '[confirm_cash_payment] receipt enqueue skipped for order %: %',
      p_order_id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'status',        'completed',
    'order_id',      p_order_id,
    'payment_id',    v_payment_id,
    'cash_received', p_cash_received,
    'cash_change',   v_cash_change,
    'print_job_id',  v_receipt_res->>'job_id',
    'print_warning', v_print_warning
  );
END;
$$;


--
-- Name: FUNCTION confirm_cash_payment(p_order_id bigint, p_cash_received numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_cash_payment(p_order_id bigint, p_cash_received numeric) IS 'Atomically completes cash payment while preserving an existing pending MoMo intent for provider settlement.';


--
-- Name: confirm_cash_payment_with_invoice_binding(bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_cash_payment_with_invoice_binding(p_order_id bigint, p_cash_received numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_order public.orders%ROWTYPE;
  v_request public.self_order_payment_requests%ROWTYPE;
  v_bound_request public.self_order_payment_requests%ROWTYPE;
  v_active_request_count integer := 0;
  v_request_found boolean := false;
  v_bound_request_found boolean := false;
  v_expired_request_id bigint;
  v_payment_result jsonb;
  v_payment_id bigint;
  v_payment_status text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT o.*
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM v_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:confirm_payment') THEN
    RAISE EXCEPTION 'permission denied: pos:confirm_payment' USING ERRCODE = '42501';
  END IF;

  IF NOT pg_try_advisory_xact_lock(v_order.id) THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END IF;

  FOR v_expired_request_id IN
    SELECT pr.id
    FROM public.self_order_payment_requests pr
    WHERE pr.tenant_id = v_order.tenant_id
      AND pr.branch_id = v_order.branch_id
      AND pr.order_id = v_order.id
      AND pr.status IN ('cash_call', 'vietqr_pending')
      AND pr.expires_at <= now()
    ORDER BY pr.id
  LOOP
    PERFORM public.self_order_expire_payment_request(v_expired_request_id);
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.self_order_payment_requests pr
    WHERE pr.tenant_id = v_order.tenant_id
      AND pr.branch_id = v_order.branch_id
      AND pr.order_id = v_order.id
      AND pr.method = 'vietqr'
      AND pr.status = 'vietqr_pending'
      AND pr.expires_at > now()
  ) THEN
    RAISE EXCEPTION 'self_order_payment_cancel_staff_required' USING ERRCODE = '55P03';
  END IF;

  SELECT count(*)::integer
  INTO v_active_request_count
  FROM public.self_order_payment_requests pr
  WHERE pr.tenant_id = v_order.tenant_id
    AND pr.branch_id = v_order.branch_id
    AND pr.order_id = v_order.id
    AND pr.method = 'cash_call'
    AND pr.status = 'cash_call'
    AND pr.expires_at > now();

  IF v_active_request_count > 1 THEN
    RAISE EXCEPTION 'self_order_cash_request_ambiguous' USING ERRCODE = '23505';
  END IF;

  -- The order lock serializes self-order request mutations. Keep the request
  -- unlocked until confirm_cash_payment acquires its payment lock; its payment
  -- trigger then locks the request in the canonical order -> payment -> request order.
  SELECT pr.*
  INTO v_request
  FROM public.self_order_payment_requests pr
  WHERE pr.tenant_id = v_order.tenant_id
    AND pr.branch_id = v_order.branch_id
    AND pr.order_id = v_order.id
    AND pr.method = 'cash_call'
    AND pr.status = 'cash_call'
    AND pr.expires_at > now()
  ORDER BY pr.id DESC
  LIMIT 1;
  v_request_found := FOUND;

  IF v_request_found THEN
    IF abs(v_request.amount_snapshot - v_order.total_amount) > 1 THEN
      RAISE EXCEPTION 'self_order_cash_amount_mismatch' USING ERRCODE = '22023';
    END IF;

    PERFORM public.self_order_normalize_invoice_payload(v_request.invoice_payload);
  END IF;

  v_payment_result := public.confirm_cash_payment(p_order_id, p_cash_received);
  v_payment_status := NULLIF(v_payment_result ->> 'status', '');
  v_payment_id := NULLIF(v_payment_result ->> 'payment_id', '')::bigint;

  IF v_payment_status IN ('completed', 'already_completed') THEN
    IF v_request_found THEN
      IF v_payment_id IS NULL THEN
        RAISE EXCEPTION 'self_order_cash_payment_binding_missing' USING ERRCODE = '23503';
      END IF;

      UPDATE public.self_order_payment_requests pr
      SET status = 'completed',
          payment_id = COALESCE(pr.payment_id, v_payment_id),
          completed_at = COALESCE(pr.completed_at, now())
      WHERE pr.id = v_request.id
        AND pr.tenant_id = v_order.tenant_id
        AND pr.status = 'cash_call'
        AND pr.expires_at > now();

      SELECT pr.*
      INTO v_bound_request
      FROM public.self_order_payment_requests pr
      WHERE pr.id = v_request.id
        AND pr.tenant_id = v_order.tenant_id
        AND pr.branch_id = v_order.branch_id
        AND pr.order_id = v_order.id
        AND pr.method = 'cash_call'
      FOR UPDATE;
      v_bound_request_found := FOUND;

      IF NOT v_bound_request_found
         OR v_bound_request.status <> 'completed'
         OR v_bound_request.payment_id IS DISTINCT FROM v_payment_id
         OR v_bound_request.completed_at IS NULL
         OR v_bound_request.expires_at <= v_bound_request.completed_at THEN
        RAISE EXCEPTION 'self_order_cash_payment_binding_failed' USING ERRCODE = '23514';
      END IF;
    ELSIF v_payment_id IS NOT NULL THEN
      SELECT pr.*
      INTO v_bound_request
      FROM public.self_order_payment_requests pr
      WHERE pr.tenant_id = v_order.tenant_id
        AND pr.branch_id = v_order.branch_id
        AND pr.order_id = v_order.id
        AND pr.payment_id = v_payment_id
        AND pr.method = 'cash_call'
        AND pr.status = 'completed'
        AND pr.completed_at IS NOT NULL
        AND pr.expires_at > pr.completed_at
      ORDER BY pr.id DESC
      LIMIT 1
      FOR UPDATE;
      v_bound_request_found := FOUND;
    END IF;
  END IF;

  RETURN v_payment_result || jsonb_build_object(
    'self_order_request_id',
    CASE WHEN v_bound_request_found THEN v_bound_request.id ELSE NULL END
  );
END;
$$;


--
-- Name: confirm_cash_payment_with_invoice_binding(bigint, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_cash_payment_with_invoice_binding(p_order_id bigint, p_cash_received numeric, p_invoice_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result jsonb;
  v_payment_id bigint;
  v_order public.orders%ROWTYPE;
  v_payload jsonb;
  v_request_payload jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  v_payload := public.self_order_normalize_invoice_payload(p_invoice_payload);
  v_result := public.confirm_cash_payment_with_invoice_binding(
    p_order_id,
    p_cash_received
  );
  v_payment_id := NULLIF(v_result ->> 'payment_id', '')::bigint;

  IF v_result ->> 'status' NOT IN ('completed', 'already_completed')
    OR v_payment_id IS NULL THEN
    RETURN v_result;
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_issue_order_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT request.invoice_payload INTO v_request_payload
  FROM public.self_order_payment_requests request
  WHERE request.tenant_id = v_order.tenant_id
    AND request.branch_id = v_order.branch_id
    AND request.order_id = v_order.id
    AND request.payment_id = v_payment_id
    AND request.status = 'completed'
  ORDER BY request.id DESC
  LIMIT 1;

  v_payload := COALESCE(v_request_payload, v_payload);

  PERFORM private.upsert_tax_invoice_issue_job(
    v_order.tenant_id,
    v_order.branch_id,
    v_order.id,
    v_payment_id,
    v_payload,
    'queued'
  );

  RETURN v_result || jsonb_build_object('tax_invoice_job_status', 'queued');
END;
$$;


--
-- Name: confirm_goods_receipt_note(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_goods_receipt_note(p_grn_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_grn record;
  v_po record;
  v_item record;
  v_old_quantity numeric(15,3);
  v_old_wac numeric(15,2);
  v_accepted numeric(15,3);
  v_previously_applied numeric(15,3);
  v_remaining numeric(15,3);
  v_applied_base numeric(15,3);
  v_applied_money numeric(15,2);
  v_applied_cost_base numeric(15,2);
  v_new_quantity numeric(15,3);
  v_new_wac numeric(15,2);
  v_po_complete boolean;
  v_po_status text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT grn.*
  INTO v_grn
  FROM public.goods_received_notes AS grn
  WHERE grn.id = p_grn_id
    AND grn.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_grn.branch_id,
    'procurement:grn_confirm'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_grn.status = 'confirmed' THEN
    SELECT po.status
    INTO v_po_status
    FROM public.purchase_orders AS po
    WHERE po.id = v_grn.po_id
      AND po.tenant_id = v_tenant;

    RETURN pg_catalog.jsonb_build_object(
      'grn_id', p_grn_id,
      'status', 'confirmed',
      'po_id', v_grn.po_id,
      'po_status', v_po_status
    );
  END IF;
  IF v_grn.status <> 'draft' THEN
    RAISE EXCEPTION 'grn_not_draft' USING ERRCODE = '23514';
  END IF;

  SELECT po.*
  INTO v_po
  FROM public.purchase_orders AS po
  WHERE po.id = v_grn.po_id
    AND po.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND
     OR v_po.status NOT IN ('sent', 'approved', 'partially_received')
     OR v_po.supplier_id <> v_grn.supplier_id
     OR v_po.branch_id <> v_grn.branch_id THEN
    RAISE EXCEPTION 'grn_purchase_order_invalid'
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND (
        item.received_quantity < 0
        OR item.rejected_quantity < 0
        OR item.rejected_quantity > item.received_quantity
        OR (
          item.rejected_quantity > 0
          AND (
            nullif(
              pg_catalog.btrim(item.rejection_reason),
              ''
            ) IS NULL
            OR NOT private.grn_rejection_photo_exists(
              item.tenant_id,
              item.grn_id,
              item.id,
              item.rejected_photo_url
            )
          )
        )
      )
  ) THEN
    RAISE EXCEPTION 'grn_physical_qc_incomplete'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.received_quantity - item.rejected_quantity > 0
  ) THEN
    RAISE EXCEPTION 'grn_has_no_accepted_quantity'
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    JOIN public.purchase_order_items AS po_item
      ON po_item.id = item.purchase_order_item_id
     AND po_item.tenant_id = item.tenant_id
     AND po_item.po_id = v_po.id
    LEFT JOIN LATERAL (
      SELECT pg_catalog.sum(previous_item.po_applied_quantity) AS quantity
      FROM public.grn_items AS previous_item
      JOIN public.goods_received_notes AS previous_grn
        ON previous_grn.id = previous_item.grn_id
       AND previous_grn.tenant_id = previous_item.tenant_id
      WHERE previous_item.tenant_id = v_tenant
        AND previous_item.purchase_order_item_id = po_item.id
        AND previous_grn.status = 'confirmed'
    ) AS received ON TRUE
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.received_quantity - item.rejected_quantity
        > greatest(
          po_item.quantity - coalesce(received.quantity, 0),
          0
        )
  ) THEN
    RAISE EXCEPTION 'grn_over_receipt_not_allowed'
      USING ERRCODE = '23514';
  END IF;

  PERFORM 1
  FROM public.purchase_order_items AS po_item
  WHERE po_item.po_id = v_po.id
    AND po_item.tenant_id = v_tenant
  ORDER BY po_item.id
  FOR UPDATE;

  PERFORM pg_catalog.set_config(
    'comtammatu.grn_confirm',
    'true',
    TRUE
  );

  FOR v_item IN
    SELECT
      grn_item.*,
      po_item.quantity AS ordered_quantity
    FROM public.grn_items AS grn_item
    JOIN public.purchase_order_items AS po_item
      ON po_item.id = grn_item.purchase_order_item_id
     AND po_item.tenant_id = grn_item.tenant_id
     AND po_item.po_id = v_po.id
    WHERE grn_item.grn_id = p_grn_id
      AND grn_item.tenant_id = v_tenant
    ORDER BY grn_item.id
    FOR UPDATE OF grn_item
  LOOP
    v_accepted := v_item.received_quantity - v_item.rejected_quantity;

    SELECT coalesce(
      pg_catalog.sum(previous_item.po_applied_quantity),
      0
    )
    INTO v_previously_applied
    FROM public.grn_items AS previous_item
    JOIN public.goods_received_notes AS previous_grn
      ON previous_grn.id = previous_item.grn_id
     AND previous_grn.tenant_id = previous_item.tenant_id
    WHERE previous_item.tenant_id = v_tenant
      AND previous_item.purchase_order_item_id =
        v_item.purchase_order_item_id
      AND previous_grn.status = 'confirmed';

    v_remaining := greatest(
      v_item.ordered_quantity - v_previously_applied,
      0
    );
    IF v_accepted > v_remaining THEN
      RAISE EXCEPTION 'grn_over_receipt_not_allowed'
        USING ERRCODE = '23514';
    END IF;

    v_applied_base := public.inv_to_base(
      v_item.ingredient_id,
      v_item.entry_unit_id,
      v_accepted
    );

    SELECT stock.current_quantity, stock.avg_unit_cost
    INTO v_old_quantity, v_old_wac
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_grn.branch_id
      AND stock.location_id = v_grn.location_id
      AND stock.ingredient_id = v_item.ingredient_id
    FOR UPDATE;

    IF NOT FOUND THEN
      v_old_quantity := 0;
      v_old_wac := NULL;
    END IF;

    v_applied_money := CASE
      WHEN v_item.cost_pending
        THEN pg_catalog.round(
          v_applied_base * coalesce(v_old_wac, 0),
          2
        )
      ELSE pg_catalog.round(v_accepted * v_item.unit_cost, 2)
    END;
    v_applied_cost_base := CASE
      WHEN v_applied_base > 0
        THEN pg_catalog.round(v_applied_money / v_applied_base, 2)
      ELSE 0
    END;

    IF v_accepted > 0 THEN
      INSERT INTO public.stock_movements (
        tenant_id,
        branch_id,
        ingredient_id,
        type,
        quantity_change,
        reason,
        created_by,
        grn_id,
        unit_cost,
        location_id,
        entry_unit_id,
        entry_quantity
      )
      VALUES (
        v_tenant,
        v_grn.branch_id,
        v_item.ingredient_id,
        'grn_receipt',
        v_applied_base,
        'GRN ' || v_grn.grn_number,
        v_uid,
        p_grn_id,
        v_applied_cost_base,
        v_grn.location_id,
        v_item.entry_unit_id,
        v_accepted
      );
    END IF;

    v_new_quantity :=
      coalesce(v_old_quantity, 0) + v_applied_base;
    v_new_wac := CASE
      WHEN v_new_quantity > 0 THEN (
        coalesce(v_old_quantity, 0)
          * coalesce(v_old_wac, 0)
        + v_applied_money
      ) / v_new_quantity
      ELSE coalesce(v_old_wac, 0)
    END;

    UPDATE public.stock_levels AS stock
    SET avg_unit_cost = v_new_wac,
        updated_at = pg_catalog.now()
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_grn.branch_id
      AND stock.location_id = v_grn.location_id
      AND stock.ingredient_id = v_item.ingredient_id;

    UPDATE public.grn_items
    SET po_applied_quantity = v_accepted,
        total_cost = v_applied_money
    WHERE id = v_item.id
      AND tenant_id = v_tenant;
  END LOOP;

  UPDATE public.goods_received_notes
  SET status = 'confirmed',
      received_date = pg_catalog.now(),
      received_by = v_uid,
      updated_at = pg_catalog.now()
  WHERE id = p_grn_id
    AND tenant_id = v_tenant;

  SELECT pg_catalog.bool_and(
    coalesce(received.quantity, 0) >= po_item.quantity
  )
  INTO v_po_complete
  FROM public.purchase_order_items AS po_item
  LEFT JOIN LATERAL (
    SELECT pg_catalog.sum(grn_item.po_applied_quantity) AS quantity
    FROM public.grn_items AS grn_item
    JOIN public.goods_received_notes AS grn
      ON grn.id = grn_item.grn_id
     AND grn.tenant_id = grn_item.tenant_id
    WHERE grn_item.tenant_id = v_tenant
      AND grn_item.purchase_order_item_id = po_item.id
      AND grn.status = 'confirmed'
  ) AS received ON TRUE
  WHERE po_item.po_id = v_po.id
    AND po_item.tenant_id = v_tenant;

  v_po_status := CASE
    WHEN coalesce(v_po_complete, FALSE) THEN 'received'
    ELSE 'partially_received'
  END;

  UPDATE public.purchase_orders
  SET status = v_po_status,
      updated_at = pg_catalog.now()
  WHERE id = v_po.id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'inventory.grn.confirmed',
    'goods_received_note',
    p_grn_id,
    pg_catalog.to_jsonb(v_grn),
    pg_catalog.jsonb_build_object(
      'status', 'confirmed',
      'po_id', v_po.id,
      'po_status', v_po_status
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'grn_id', p_grn_id,
    'status', 'confirmed',
    'po_id', v_po.id,
    'po_status', v_po_status
  );
END;
$$;


--
-- Name: confirm_goods_receipt_note_legacy(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_goods_receipt_note_legacy(p_grn_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_grn record;
  v_item record;
  v_old_q numeric(15,3);
  v_old_wac numeric(15,2);
  v_recv numeric(15,3);
  v_recv_base numeric(15,3);
  v_cost numeric(15,2);
  v_money numeric(15,2);
  v_cost_base numeric(15,2);
  v_new_q numeric(15,3);
  v_new_wac numeric(15,2);
  v_location_id bigint;
  v_all_fulfilled boolean;
  v_po_status text;
  v_po_id bigint;
  v_po_ids bigint[];
  v_unapproved integer;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT grn.*
  INTO v_grn
  FROM public.goods_received_notes AS grn
  WHERE grn.id = p_grn_id
    AND grn.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_grn.branch_id,
    'procurement:grn_confirm'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_grn.status <> 'draft' THEN
    RAISE EXCEPTION 'grn_not_draft' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.branches AS branch
    WHERE branch.id = v_grn.branch_id
      AND branch.tenant_id = v_tenant
      AND branch.is_active IS TRUE
      AND branch.branch_kind IN (
        'branch',
        'central_supply',
        'central_kitchen'
      )
  ) THEN
    RAISE EXCEPTION 'grn_branch_must_be_operational'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_grn.location_id IS NULL THEN
    SELECT location.id
    INTO v_location_id
    FROM public.inventory_locations AS location
    WHERE location.tenant_id = v_tenant
      AND location.branch_id = v_grn.branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE
      AND location.is_default_receive IS TRUE
      AND location.is_default_issue IS TRUE
      AND location.is_default_consumption IS TRUE;
  ELSE
    SELECT location.id
    INTO v_location_id
    FROM public.inventory_locations AS location
    WHERE location.id = v_grn.location_id
      AND location.tenant_id = v_tenant
      AND location.branch_id = v_grn.branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE;
  END IF;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'grn_warehouse_location_missing'
      USING ERRCODE = 'no_data_found';
  END IF;

  SELECT COALESCE(array_agg(po.id ORDER BY po.id), ARRAY[]::bigint[])
  INTO v_po_ids
  FROM public.purchase_orders AS po
  WHERE po.tenant_id = v_tenant
    AND (
      po.source_grn_id = p_grn_id
      OR (v_grn.po_id IS NOT NULL AND po.id = v_grn.po_id)
    );

  IF cardinality(v_po_ids) = 0 THEN
    RAISE EXCEPTION 'grn_confirm_requires_approved_po'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT COUNT(*)::integer
  INTO v_unapproved
  FROM public.purchase_orders AS po
  WHERE po.id = ANY (v_po_ids)
    AND po.tenant_id = v_tenant
    AND po.status NOT IN ('sent', 'partially_received');

  IF v_unapproved > 0 THEN
    RAISE EXCEPTION 'grn_confirm_requires_approved_po'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  PERFORM 1
  FROM public.purchase_orders AS po
  WHERE po.id = ANY (v_po_ids)
    AND po.tenant_id = v_tenant
  FOR UPDATE;

  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND (
        item.rejected_quantity < 0
        OR item.rejected_quantity > item.received_quantity
      )
  ) THEN
    RAISE EXCEPTION 'rejected_exceeds_received'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.rejected_quantity > 0
      AND NULLIF(btrim(item.rejection_reason), '') IS NULL
  ) THEN
    RAISE EXCEPTION 'grn_qc_reason_required'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.rejected_quantity > 0
      AND NOT private.grn_rejection_photo_exists(
        item.tenant_id,
        item.grn_id,
        item.id,
        item.rejected_photo_url
      )
  ) THEN
    RAISE EXCEPTION 'grn_qc_photo_required'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Each receivable line must match a PO item on the PO for that line's supplier.
  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.received_quantity - item.rejected_quantity > 0
      AND (
        item.unit_cost <= 0
        OR NOT EXISTS (
          SELECT 1
          FROM public.purchase_orders AS po
          JOIN public.purchase_order_items AS po_item
            ON po_item.po_id = po.id
           AND po_item.tenant_id = po.tenant_id
          WHERE po.tenant_id = v_tenant
            AND po.id = ANY (v_po_ids)
            AND po.supplier_id = item.supplier_id
            AND po_item.ingredient_id = item.ingredient_id
            AND po_item.entry_unit_id IS NOT DISTINCT FROM
              item.entry_unit_id
            AND po_item.unit_price_est > 0
            AND po_item.unit_price_est = item.unit_cost
        )
      )
  ) THEN
    RAISE EXCEPTION 'grn_approved_po_price_missing_or_stale'
      USING ERRCODE = 'check_violation';
  END IF;

  FOR v_item IN
    SELECT item.*
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.received_quantity - item.rejected_quantity > 0
    ORDER BY item.id
    FOR UPDATE
  LOOP
    v_recv := v_item.received_quantity - v_item.rejected_quantity;
    v_recv_base := public.inv_to_base(
      v_item.ingredient_id,
      v_item.entry_unit_id,
      v_recv
    );
    v_cost := v_item.unit_cost;
    v_money := round(v_recv * v_cost, 2);
    v_cost_base := CASE
      WHEN v_recv_base <> 0 THEN round(v_money / v_recv_base, 2)
      ELSE v_cost
    END;

    SELECT stock.current_quantity, stock.avg_unit_cost
    INTO v_old_q, v_old_wac
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_grn.branch_id
      AND stock.location_id = v_location_id
      AND stock.ingredient_id = v_item.ingredient_id
    FOR UPDATE;

    IF NOT FOUND THEN
      v_old_q := 0;
      v_old_wac := NULL;
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      quantity_change,
      reason,
      created_by,
      grn_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    VALUES (
      v_tenant,
      v_grn.branch_id,
      v_item.ingredient_id,
      'grn_receipt',
      v_recv_base,
      'GRN ' || v_grn.grn_number,
      v_uid,
      p_grn_id,
      v_cost_base,
      v_location_id,
      v_item.entry_unit_id,
      v_recv
    );

    v_new_q := coalesce(v_old_q, 0) + v_recv_base;
    v_new_wac := CASE
      WHEN v_new_q > 0 THEN (
        coalesce(v_old_q, 0) * coalesce(v_old_wac, 0) + v_money
      ) / v_new_q
      ELSE v_cost_base
    END;

    UPDATE public.stock_levels AS stock
    SET avg_unit_cost = v_new_wac,
        updated_at = now()
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_grn.branch_id
      AND stock.location_id = v_location_id
      AND stock.ingredient_id = v_item.ingredient_id;

    UPDATE public.ingredients AS ingredient
    SET unit_cost = v_cost_base,
        updated_at = now()
    WHERE ingredient.id = v_item.ingredient_id
      AND ingredient.tenant_id = v_tenant;
  END LOOP;

  UPDATE public.goods_received_notes
  SET status = 'confirmed',
      po_id = COALESCE(v_grn.po_id, v_po_ids[1]),
      location_id = v_location_id,
      updated_at = now()
  WHERE id = p_grn_id
    AND tenant_id = v_tenant;

  FOREACH v_po_id IN ARRAY v_po_ids
  LOOP
    WITH ordered AS (
      SELECT
        po_item.ingredient_id,
        sum(public.inv_to_base(
          po_item.ingredient_id,
          po_item.entry_unit_id,
          po_item.quantity
        ))::numeric(15,3) AS quantity
      FROM public.purchase_order_items AS po_item
      WHERE po_item.po_id = v_po_id
        AND po_item.tenant_id = v_tenant
      GROUP BY po_item.ingredient_id
    ),
    received AS (
      SELECT
        item.ingredient_id,
        sum(public.inv_to_base(
          item.ingredient_id,
          item.entry_unit_id,
          item.received_quantity - item.rejected_quantity
        ))::numeric(15,3) AS quantity
      FROM public.grn_items AS item
      JOIN public.goods_received_notes AS grn
        ON grn.id = item.grn_id
       AND grn.tenant_id = item.tenant_id
      JOIN public.purchase_orders AS po
        ON po.id = v_po_id
       AND po.tenant_id = v_tenant
      WHERE grn.tenant_id = v_tenant
        AND grn.status = 'confirmed'
        AND (
          grn.po_id = v_po_id
          OR po.source_grn_id = grn.id
        )
        AND item.supplier_id = po.supplier_id
      GROUP BY item.ingredient_id
    )
    SELECT bool_and(coalesce(received.quantity, 0) >= ordered.quantity)
    INTO v_all_fulfilled
    FROM ordered
    LEFT JOIN received USING (ingredient_id)
    WHERE ordered.quantity > 0;

    UPDATE public.purchase_orders
    SET status = CASE
          WHEN coalesce(v_all_fulfilled, FALSE) THEN 'received'
          ELSE 'partially_received'
        END,
        updated_at = now()
    WHERE id = v_po_id
      AND tenant_id = v_tenant
      AND status IN ('sent', 'partially_received')
    RETURNING status INTO v_po_status;
  END LOOP;

  RETURN jsonb_build_object(
    'grn_id', p_grn_id,
    'status', 'confirmed',
    'po_id', COALESCE(v_grn.po_id, v_po_ids[1]),
    'po_ids', to_jsonb(v_po_ids),
    'po_status', v_po_status
  );
END;
$$;


--
-- Name: FUNCTION confirm_goods_receipt_note_legacy(p_grn_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_goods_receipt_note_legacy(p_grn_id bigint) IS 'Atomic confirm GRN. Fail-closed unless every PO linked via source_grn_id (or legacy po_id) is sent/partially_received.';


--
-- Name: confirm_payment_and_post(bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_payment_and_post(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint, p_provider_ref text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid           UUID := auth.uid();
  v_payment       RECORD;
  v_order         RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.* INTO v_payment
  FROM public.payments p
  WHERE p.id = p_payment_id
    AND p.tenant_id = p_tenant_id
    AND p.branch_id = p_branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_payment.status <> 'pending' THEN
    RAISE EXCEPTION 'payment_not_pending' USING ERRCODE = '22023';
  END IF;

  SELECT o.id, o.total_amount, o.tax_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_payment.order_id
    AND o.tenant_id = p_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.payments
  SET status = 'completed',
      provider_ref = COALESCE(p_provider_ref, provider_ref),
      paid_at = now(),
      updated_at = now()
  WHERE id = p_payment_id;

  UPDATE public.orders
  SET payment_status = 'paid',
      updated_at = now()
  WHERE id = v_payment.order_id
    AND tenant_id = p_tenant_id;

  PERFORM public.finalize_paid_order(v_payment.order_id, v_uid);

  RETURN jsonb_build_object(
    'payment_id', p_payment_id,
    'status', 'completed'
  );
END;
$$;


--
-- Name: confirm_production_run(bigint, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_production_run(p_run_id bigint, p_actual_quantity numeric DEFAULT NULL::numeric, p_actual_ingredients jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
  PERFORM auth.role();
  RAISE EXCEPTION 'production_maintenance_legacy_rpc' USING ERRCODE = '55000';
END; $$;


--
-- Name: confirm_sepay_payment(bigint, bigint, text, numeric, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_sepay_payment(p_tenant_id bigint, p_order_id bigint, p_provider_ref text, p_transfer_amount numeric, p_account_number text, p_bank_reference text, p_provider_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order            RECORD;
  v_payment          RECORD;
  v_has_payment      BOOLEAN := FALSE;
  v_payment_id       BIGINT;
  v_expected_account TEXT;
  v_complete_res     RECORD;
  v_receipt_res      JSONB;
  v_print_job_id     BIGINT;
  v_print_failed     BOOLEAN := FALSE;
  v_print_error      TEXT;
  v_provider_data    JSONB;
  v_actor            UUID;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  IF btrim(COALESCE(p_provider_ref, '')) = '' THEN
    RETURN jsonb_build_object('status', 'invalid_payment_code');
  END IF;

  IF p_transfer_amount IS NULL OR p_transfer_amount <= 0 THEN
    RETURN jsonb_build_object('status', 'invalid_amount');
  END IF;

  SELECT
    o.id AS order_id,
    o.tenant_id,
    o.branch_id,
    o.total_amount,
    o.payment_status,
    o.payment_method,
    o.payment_code,
    o.created_by
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
    AND o.tenant_id = p_tenant_id
    AND lower(o.payment_code) = lower(btrim(p_provider_ref))
    AND o.status <> 'cancelled'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'payment_not_found');
  END IF;

  SELECT NULLIF(regexp_replace(COALESCE(ss.value, ''), '\s+', '', 'g'), '')
  INTO v_expected_account
  FROM public.system_settings ss
  WHERE ss.tenant_id = v_order.tenant_id
    AND ss.key = 'payment_vietqr_account_no'
  LIMIT 1;

  IF v_expected_account IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'account_config_missing',
      'order_id', v_order.order_id,
      'payment_id', NULL
    );
  END IF;

  IF regexp_replace(COALESCE(p_account_number, ''), '\s+', '', 'g') <> v_expected_account THEN
    RETURN jsonb_build_object(
      'status', 'account_mismatch',
      'order_id', v_order.order_id,
      'payment_id', NULL
    );
  END IF;

  IF p_transfer_amount <> v_order.total_amount THEN
    RETURN jsonb_build_object(
      'status', 'amount_mismatch',
      'order_id', v_order.order_id,
      'payment_id', NULL,
      'expected', v_order.total_amount,
      'received', p_transfer_amount
    );
  END IF;

  v_provider_data := COALESCE(p_provider_data, '{}'::jsonb)
    || jsonb_build_object(
      'bankReference', p_bank_reference,
      'description', v_order.payment_code
    );

  SELECT p.id AS payment_id,
         p.method AS payment_method,
         p.amount AS payment_amount,
         p.status AS payment_status,
         p.created_by AS payment_created_by
  INTO v_payment
  FROM public.payments p
  WHERE p.tenant_id = v_order.tenant_id
    AND p.branch_id = v_order.branch_id
    AND p.order_id = v_order.order_id
    AND p.status <> 'failed'
  ORDER BY p.id DESC
  LIMIT 1
  FOR UPDATE;
  v_has_payment := FOUND;
  v_actor := v_order.created_by;
  IF v_has_payment THEN
    v_actor := COALESCE(v_payment.payment_created_by, v_order.created_by);
  END IF;

  IF v_has_payment AND (
    v_payment.payment_status = 'completed'
    OR COALESCE(v_order.payment_status, 'unpaid') = 'paid'
  ) THEN
    IF v_payment.payment_method = 'vietqr'
       AND COALESCE(v_order.payment_method, '') = 'vietqr' THEN
      BEGIN
        v_receipt_res := public.enqueue_receipt_print(v_order.order_id, NULL, NULL);
        v_print_job_id := NULLIF(v_receipt_res ->> 'job_id', '')::BIGINT;
      EXCEPTION WHEN OTHERS THEN
        v_print_failed := TRUE;
        v_print_error := SQLERRM;
        RAISE NOTICE '[confirm_sepay_payment] receipt print failed for order %: %',
          v_order.order_id, SQLERRM;
      END;

      RETURN jsonb_build_object(
        'status', 'already_completed',
        'order_id', v_order.order_id,
        'payment_id', v_payment.payment_id,
        'print', jsonb_build_object(
          'job_id', v_print_job_id,
          'failed', v_print_failed,
          'error', v_print_error
        )
      );
    END IF;

    UPDATE public.payments
       SET method = 'vietqr',
           amount = v_order.total_amount,
           status = 'completed',
           provider_ref = v_order.payment_code,
           paid_at = COALESCE(paid_at, now()),
           provider_data = v_provider_data,
           updated_at = now()
     WHERE id = v_payment.payment_id;

    UPDATE public.orders
       SET payment_status = 'paid',
           payment_method = 'vietqr',
           cash_received = NULL,
           cash_change = NULL,
           updated_at = now()
     WHERE id = v_order.order_id
       AND tenant_id = v_order.tenant_id;

    BEGIN
      v_receipt_res := public.enqueue_receipt_print(v_order.order_id, NULL, NULL);
      v_print_job_id := NULLIF(v_receipt_res ->> 'job_id', '')::BIGINT;
    EXCEPTION WHEN OTHERS THEN
      v_print_failed := TRUE;
      v_print_error := SQLERRM;
      RAISE NOTICE '[confirm_sepay_payment] receipt print failed for order %: %',
        v_order.order_id, SQLERRM;
    END;

    RETURN jsonb_build_object(
      'status', 'completed',
      'order_id', v_order.order_id,
      'payment_id', v_payment.payment_id,
      'corrected_from_cash', TRUE,
      'print', jsonb_build_object(
        'job_id', v_print_job_id,
        'failed', v_print_failed,
        'error', v_print_error
      )
    );
  END IF;

  IF v_has_payment THEN
    UPDATE public.payments
       SET method = 'vietqr',
           amount = v_order.total_amount,
           provider_ref = v_order.payment_code,
           provider_data = v_provider_data,
           updated_at = now()
     WHERE id = v_payment.payment_id
     RETURNING id INTO v_payment_id;
  ELSE
    INSERT INTO public.payments (
      tenant_id, branch_id, order_id, method, amount, status, provider_ref, provider_data, created_by
    )
    VALUES (
      v_order.tenant_id, v_order.branch_id, v_order.order_id, 'vietqr',
      v_order.total_amount, 'pending', v_order.payment_code, v_provider_data, v_order.created_by
    )
    RETURNING id INTO v_payment_id;
  END IF;

  SELECT * INTO v_complete_res
  FROM public.complete_payment_and_consume_stock(
    v_payment_id,
    p_transfer_amount,
    v_provider_data,
    v_actor
  );

  IF v_complete_res.status NOT IN ('completed', 'already_completed') THEN
    RETURN jsonb_build_object(
      'status', v_complete_res.status,
      'order_id', v_order.order_id,
      'payment_id', v_payment_id,
      'detail', v_complete_res.detail
    );
  END IF;

  UPDATE public.orders
     SET payment_method = 'vietqr',
         cash_received = NULL,
         cash_change = NULL,
         updated_at = now()
   WHERE id = v_order.order_id
     AND tenant_id = v_order.tenant_id;

  BEGIN
    v_receipt_res := public.enqueue_receipt_print(v_order.order_id, NULL, NULL);
    v_print_job_id := NULLIF(v_receipt_res ->> 'job_id', '')::BIGINT;
  EXCEPTION WHEN OTHERS THEN
    v_print_failed := TRUE;
    v_print_error := SQLERRM;
    RAISE NOTICE '[confirm_sepay_payment] receipt print failed for order %: %',
      v_order.order_id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'status', v_complete_res.status,
    'order_id', v_order.order_id,
    'payment_id', v_payment_id,
    'print', jsonb_build_object(
      'job_id', v_print_job_id,
      'failed', v_print_failed,
      'error', v_print_error
    )
  );
END;
$$;


--
-- Name: confirm_stock_issue(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_stock_issue(p_issue_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_issue public.stock_issues%ROWTYPE;
  v_item record;
  v_subtype text;
  v_stock_quantity numeric(15,3);
  v_wac numeric(15,2);
  v_quantity_base numeric(15,3);
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT issue.*
  INTO v_issue
  FROM public.stock_issues AS issue
  WHERE issue.id = p_issue_id
    AND issue.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_issue.branch_id,
    'inventory:write'
  ) THEN
    RAISE EXCEPTION 'forbidden_inventory_write'
      USING ERRCODE = '42501';
  END IF;
  IF v_issue.status <> 'draft' THEN
    RAISE EXCEPTION 'issue_not_draft' USING ERRCODE = '22023';
  END IF;
  IF v_issue.issue_type = 'writeoff'
     AND v_issue.approval_status = 'pending' THEN
    RAISE EXCEPTION 'writeoff_pending_approval'
      USING ERRCODE = '42501';
  END IF;
  IF v_issue.source_location_id IS NULL THEN
    RAISE EXCEPTION 'issue_source_location_missing'
      USING ERRCODE = '23502';
  END IF;

  PERFORM 1
  FROM public.inventory_locations AS location
  JOIN public.branches AS branch
    ON branch.id = location.branch_id
   AND branch.tenant_id = location.tenant_id
  WHERE location.id = v_issue.source_location_id
    AND location.tenant_id = v_tenant
    AND location.branch_id = v_issue.branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE
    AND branch.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_source_location_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_subtype := CASE
    WHEN v_issue.issue_type = 'consumption'
      THEN 'sale_consumption'
    WHEN v_issue.issue_type = 'writeoff'
      THEN 'writeoff'
    WHEN v_issue.issue_type = 'other'
      THEN 'other'
    ELSE NULL
  END;

  FOR v_item IN
    SELECT item.*
    FROM public.stock_issue_items AS item
    WHERE item.issue_id = p_issue_id
      AND item.tenant_id = v_tenant
  LOOP
    v_quantity_base := public.inv_to_base(
      v_item.ingredient_id,
      v_item.entry_unit_id,
      v_item.quantity
    );

    SELECT stock.current_quantity, stock.avg_unit_cost
    INTO v_stock_quantity, v_wac
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_issue.branch_id
      AND stock.location_id = v_issue.source_location_id
      AND stock.ingredient_id = v_item.ingredient_id
    FOR UPDATE;

    IF NOT FOUND OR v_wac IS NULL THEN
      RAISE EXCEPTION 'wac_not_ready_for_%',
        v_item.ingredient_id
        USING ERRCODE = '22023';
    END IF;
    IF v_stock_quantity < v_quantity_base THEN
      RAISE EXCEPTION 'insufficient_stock_for_%',
        v_item.ingredient_id
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.stock_issue_items
    SET unit_cost = v_wac
    WHERE id = v_item.id
      AND tenant_id = v_tenant;

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      movement_subtype,
      quantity_change,
      unit_cost,
      reason,
      created_by,
      issue_id,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    VALUES (
      v_tenant,
      v_issue.branch_id,
      v_item.ingredient_id,
      'consumption',
      v_subtype,
      -v_quantity_base,
      v_wac,
      coalesce(v_item.reason, v_issue.notes),
      v_uid,
      p_issue_id,
      v_issue.source_location_id,
      v_item.entry_unit_id,
      v_item.quantity
    );
  END LOOP;

  UPDATE public.stock_issues
  SET status = 'confirmed'
  WHERE id = p_issue_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'ok',
    TRUE,
    'issue_id',
    p_issue_id,
    'movement_subtype',
    v_subtype
  );
END;
$$;


--
-- Name: FUNCTION confirm_stock_issue(p_issue_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_stock_issue(p_issue_id bigint) IS 'Confirms a tenant-bound draft issue only from an active site warehouse.';


--
-- Name: confirm_supplier_invoice(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_supplier_invoice(p_invoice_id bigint, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_invoice public.supplier_invoices%ROWTYPE;
  v_result jsonb;
  v_valuation jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_match') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'supplier_invoice_confirm_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT invoice.*
  INTO v_invoice
  FROM public.supplier_invoices AS invoice
  WHERE invoice.id = p_invoice_id
    AND invoice.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_invoice.document_status = 'confirmed' THEN
    v_valuation := public.get_supplier_invoice_valuation_summary(p_invoice_id);
    RETURN pg_catalog.jsonb_build_object(
      'invoice_id', p_invoice_id,
      'document_status', 'confirmed',
      'matching_status', v_invoice.matching_status,
      'valuation', v_valuation
    );
  END IF;
  IF v_invoice.document_status <> 'draft' THEN
    RAISE EXCEPTION 'supplier_invoice_not_confirmable'
      USING ERRCODE = '23514';
  END IF;

  v_result := private.apply_supplier_invoice_matching(p_invoice_id);
  IF v_result->>'matching_status' <> 'matched' THEN
    RAISE EXCEPTION 'supplier_invoice_not_matched'
      USING ERRCODE = '23514';
  END IF;
  IF v_invoice.invoice_kind = 'service'
     AND v_invoice.service_verified_at IS NULL THEN
    RAISE EXCEPTION 'service_invoice_not_verified'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.supplier_invoices
  SET confirmed_by = v_uid
  WHERE id = p_invoice_id
    AND tenant_id = v_tenant;
  v_invoice.confirmed_by := v_uid;

  v_valuation := private.settle_supplier_invoice_valuation(
    p_invoice_id,
    p_idempotency_key
  );

  UPDATE public.supplier_invoices
  SET document_status = 'confirmed',
      confirmed_at = pg_catalog.now(),
      confirmed_by = v_uid,
      updated_at = pg_catalog.now()
  WHERE id = p_invoice_id
    AND tenant_id = v_tenant;

  INSERT INTO public.supplier_ingredient_price_history (
    tenant_id,
    supplier_id,
    ingredient_id,
    unit_id,
    unit_price,
    effective_net_unit_price,
    supplier_invoice_id,
    supplier_invoice_line_id,
    confirmed_at,
    created_by
  )
  SELECT
    v_tenant,
    v_invoice.supplier_id,
    line.ingredient_id,
    line.unit_id,
    CASE
      WHEN line.quantity > 0
        THEN pg_catalog.round(
          (
            line.line_total - line.allocated_document_discount
          ) / line.quantity,
          8
        )
      ELSE 0
    END,
    CASE
      WHEN line.quantity > 0
        THEN pg_catalog.round(
          (
            line.line_total - line.allocated_document_discount
          ) / line.quantity,
          8
        )
      ELSE 0
    END,
    p_invoice_id,
    line.id,
    pg_catalog.now(),
    v_uid
  FROM public.supplier_invoice_lines AS line
  WHERE line.tenant_id = v_tenant
    AND line.supplier_invoice_id = p_invoice_id
    AND line.ingredient_id IS NOT NULL
    AND line.unit_id IS NOT NULL
  ON CONFLICT (supplier_invoice_line_id) DO NOTHING;

  PERFORM public.log_audit(
    'supplier_invoice.confirmed',
    'supplier_invoice',
    p_invoice_id,
    pg_catalog.jsonb_build_object('document_status', 'draft'),
    pg_catalog.jsonb_build_object(
      'document_status', 'confirmed',
      'matching_status', v_result->>'matching_status',
      'valuation', v_valuation
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'invoice_id', p_invoice_id,
    'document_status', 'confirmed',
    'matching_status', v_result->>'matching_status',
    'valuation', v_valuation
  );
END;
$$;


--
-- Name: confirm_supplier_return(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_supplier_return(p_return_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     UUID   := auth.uid();
  v_tenant  BIGINT := public.auth_tenant_id();
  v_ret     RECORD;
  v_item    RECORD;
  v_old_q   NUMERIC(15,3);
  v_mv_id   BIGINT;
  v_lines_processed INT := 0;
  v_loc_id  BIGINT;
  v_qty_base NUMERIC(15,3);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_ret
  FROM public.supplier_returns
  WHERE id = p_return_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'return_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_ret.branch_id, 'supplier_return:confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_ret.status <> 'draft' THEN
    RAISE EXCEPTION 'return_not_draft' USING ERRCODE = '22023';
  END IF;

  IF v_ret.source = 'post_receipt' THEN
    SELECT id INTO v_loc_id
    FROM public.inventory_locations
    WHERE branch_id = v_ret.branch_id
      AND tenant_id = v_tenant
      AND is_default_receive = TRUE
      AND is_active = TRUE
    LIMIT 1;

    IF v_loc_id IS NULL THEN
      RAISE EXCEPTION 'no_default_location_for_branch' USING ERRCODE = 'P0002',
        DETAIL = format('branch_id=%s', v_ret.branch_id);
    END IF;

    FOR v_item IN
      SELECT sri.*, COALESCE(sri.entry_unit_id, (
        SELECT iu.unit_id
        FROM public.ingredient_units iu
        JOIN public.units u ON u.id = iu.unit_id AND u.tenant_id = iu.tenant_id AND u.is_active = TRUE
        WHERE iu.tenant_id = v_tenant
          AND iu.ingredient_id = sri.ingredient_id
          AND iu.is_base = TRUE
          AND iu.is_active = TRUE
        ORDER BY iu.sort_order ASC, iu.id ASC
        LIMIT 1
      )) AS resolved_entry_unit_id
      FROM public.supplier_return_items sri
      WHERE sri.return_id = p_return_id AND sri.tenant_id = v_tenant
      ORDER BY sri.ingredient_id
    LOOP
      IF v_item.resolved_entry_unit_id IS NULL THEN
        RAISE EXCEPTION 'entry_unit_not_found:%', v_item.ingredient_id USING ERRCODE = '23503';
      END IF;

      v_qty_base := ROUND(public.inv_to_base(v_item.ingredient_id, v_item.resolved_entry_unit_id, v_item.quantity), 3);

      SELECT current_quantity INTO v_old_q
      FROM public.stock_levels
      WHERE tenant_id = v_tenant
        AND branch_id = v_ret.branch_id
        AND ingredient_id = v_item.ingredient_id
        AND location_id = v_loc_id
      FOR UPDATE;

      IF NOT FOUND OR COALESCE(v_old_q, 0) < v_qty_base THEN
        RAISE EXCEPTION 'insufficient_stock_for_return' USING ERRCODE = '23514',
          DETAIL = format('ingredient_id=%s, requested_base=%s, available=%s',
                          v_item.ingredient_id, v_qty_base, COALESCE(v_old_q, 0));
      END IF;

      INSERT INTO public.stock_movements (
        tenant_id, branch_id, ingredient_id, location_id, type, quantity_change,
        reason, created_by, unit_cost, entry_unit_id, entry_quantity
      ) VALUES (
        v_tenant, v_ret.branch_id, v_item.ingredient_id, v_loc_id, 'supplier_return',
        -v_qty_base,
        'Tra NCC ' || v_ret.return_number, v_uid,
        CASE WHEN v_qty_base <> 0
             THEN ROUND((v_item.quantity * v_item.unit_cost) / v_qty_base, 2)
             ELSE v_item.unit_cost
        END,
        v_item.resolved_entry_unit_id,
        v_item.quantity
      ) RETURNING id INTO v_mv_id;

      UPDATE public.supplier_return_items
      SET stock_movement_id = v_mv_id
      WHERE id = v_item.id;

      v_lines_processed := v_lines_processed + 1;
    END LOOP;
  END IF;

  UPDATE public.supplier_returns
  SET status = 'sent',
      confirmed_by = v_uid,
      confirmed_at = now(),
      updated_at = now()
  WHERE id = p_return_id;

  RETURN jsonb_build_object(
    'return_id', p_return_id,
    'status', 'sent',
    'lines_processed', v_lines_processed
  );
END;
$$;


--
-- Name: FUNCTION confirm_supplier_return(p_return_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_supplier_return(p_return_id bigint) IS 'Moves supplier_return draft → sent. For source=post_receipt, decrements stock_levels atomically (FOR UPDATE) and inserts negative stock_movement type=supplier_return.';


--
-- Name: consume_stock_for_order(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_stock_for_order(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  RETURN private.consume_stock_for_order_at_warehouse(
    p_order_id,
    v_uid,
    v_tenant
  );
END;
$$;


--
-- Name: consume_stock_for_order_service(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_stock_for_order_service(p_order_id bigint, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only'
      USING ERRCODE = '42501';
  END IF;

  RETURN private.consume_stock_for_order_at_warehouse(
    p_order_id,
    p_actor_id,
    NULL
  );
END;
$$;


--
-- Name: copy_shift_assignments_week(bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_shift_assignments_week(p_tenant_id bigint, p_branch_id bigint, p_source_week_start date, p_target_week_start date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  IF (
    public.auth_tenant_id() IS NOT DISTINCT FROM p_tenant_id
    AND (
      (
        public.auth_role() = 'owner'
        AND public.auth_is_owner(auth.uid())
      )
      OR (
        public.auth_role() = 'branch_manager'
        AND p_branch_id IS NOT NULL
        AND public.auth_branch_id() IS NOT DISTINCT FROM p_branch_id
        AND public.has_permission(p_branch_id, 'hr:assign_shift')
      )
    )
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'employee_id', sa.employee_id,
        'work_date', (p_target_week_start + (sa.work_date - p_source_week_start)),
        'shift_id', sa.shift_id
      )
      ORDER BY sa.employee_id, sa.work_date
    ),
    '[]'::jsonb
  )
  INTO v_payload
  FROM public.shift_assignments sa
  JOIN public.employees emp
    ON emp.id = sa.employee_id
   AND emp.tenant_id = sa.tenant_id
   AND emp.is_active
  JOIN public.shifts sh
    ON sh.id = sa.shift_id
   AND sh.tenant_id = sa.tenant_id
   AND sh.is_active
  WHERE sa.tenant_id = p_tenant_id
    AND sa.branch_id IS NOT DISTINCT FROM p_branch_id
    AND sa.work_date BETWEEN p_source_week_start AND (p_source_week_start + 6);

  RETURN public.reconcile_shift_assignments_week(
    p_tenant_id,
    p_branch_id,
    p_target_week_start,
    v_payload
  );
END;
$$;


--
-- Name: correct_attendance_record(bigint, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_attendance_record(p_attendance_id bigint, p_check_in timestamp with time zone, p_check_out timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_previous jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_tenant_id IS NULL
     OR NOT public.has_permission(NULL, 'hr:correct_attendance') THEN
    RAISE EXCEPTION 'attendance_correction_forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_check_in IS NULL OR (p_check_out IS NOT NULL AND p_check_out <= p_check_in) THEN
    RAISE EXCEPTION 'attendance_correction_time_invalid' USING ERRCODE = '22023';
  END IF;
  IF char_length(btrim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'attendance_correction_reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT to_jsonb(attendance)
  INTO v_previous
  FROM public.attendance_records attendance
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = v_tenant_id
  FOR UPDATE;
  IF v_previous IS NULL THEN
    RAISE EXCEPTION 'attendance_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.attendance_records attendance
  SET check_in = p_check_in,
      check_out = p_check_out,
      note = concat_ws(E'\n', NULLIF(attendance.note, ''), btrim(p_reason)),
      updated_at = now()
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = v_tenant_id;

  PERFORM public.log_audit(
    'update',
    'attendance_record',
    p_attendance_id,
    v_previous,
    jsonb_build_object(
      'check_in', p_check_in,
      'check_out', p_check_out,
      'reason', btrim(p_reason)
    )
  );

  RETURN jsonb_build_object(
    'attendance_id', p_attendance_id,
    'check_in', p_check_in,
    'check_out', p_check_out
  );
END;
$$;


--
-- Name: correct_payment_method(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_payment_method(p_payment_id bigint, p_new_method text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_payment record;
  v_order record;
  v_session record;
  v_cash_revenue numeric(15,2);
  v_expected_cash numeric(15,2);
  v_cash_difference numeric(15,2);
BEGIN
  IF v_actor IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_new_method IS NULL OR p_new_method NOT IN ('cash', 'vietqr') THEN
    RAISE EXCEPTION 'invalid_payment_method' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL
    OR length(trim(p_reason)) < 1
    OR length(p_reason) > 500
  THEN
    RAISE EXCEPTION 'invalid_reason' USING ERRCODE = '22023';
  END IF;

  SELECT
    payment.id,
    payment.tenant_id,
    payment.branch_id,
    payment.order_id,
    payment.status,
    payment.method
  INTO v_payment
  FROM public.payments payment
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (public.auth_is_owner(v_actor) OR public.has_position('accountant'))
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;
  IF v_payment.status <> 'completed' THEN
    RAISE EXCEPTION 'payment_not_completed' USING ERRCODE = 'P0001';
  END IF;
  IF v_payment.method = p_new_method THEN
    RAISE EXCEPTION 'payment_method_unchanged' USING ERRCODE = 'P0001';
  END IF;

  SELECT
    orders.id,
    orders.pos_session_id,
    orders.payment_method
  INTO v_order
  FROM public.orders orders
  WHERE orders.id = v_payment.order_id
    AND orders.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.payments
  SET method = p_new_method, updated_at = now()
  WHERE id = v_payment.id;

  UPDATE public.orders
  SET payment_method = p_new_method, updated_at = now()
  WHERE id = v_order.id;

  IF v_order.pos_session_id IS NOT NULL THEN
    SELECT session.*
    INTO v_session
    FROM public.pos_sessions session
    WHERE session.id = v_order.pos_session_id
      AND session.tenant_id = v_tenant
    FOR UPDATE;

    IF FOUND AND v_session.status = 'closed' THEN
      SELECT COALESCE(sum(payment.amount), 0)
      INTO v_cash_revenue
      FROM public.payments payment
      JOIN public.orders orders
        ON orders.id = payment.order_id
       AND orders.tenant_id = payment.tenant_id
       AND orders.branch_id = payment.branch_id
      WHERE orders.tenant_id = v_tenant
        AND orders.pos_session_id = v_session.id
        AND payment.status = 'completed'
        AND payment.paid_at IS NOT NULL
        AND payment.method = 'cash';

      v_expected_cash := v_session.opening_cash + v_cash_revenue;
      v_cash_difference := v_session.closing_cash - v_expected_cash;

      UPDATE public.pos_sessions
      SET
        expected_cash = v_expected_cash,
        cash_difference = v_cash_difference,
        variance_approval_note = NULL,
        variance_approver_user_id = NULL,
        variance_resolution_type = NULL,
        variance_settlement_amount = NULL,
        variance_resolved_at = NULL,
        updated_at = now()
      WHERE id = v_session.id;
    END IF;
  END IF;

  PERFORM public.log_audit(
    'payment.method_correct',
    'payment',
    v_payment.id,
    jsonb_build_object(
      'method', v_payment.method,
      'order_payment_method', v_order.payment_method,
      'pos_session_id', v_order.pos_session_id
    ),
    jsonb_build_object(
      'method', p_new_method,
      'order_payment_method', p_new_method,
      'pos_session_id', v_order.pos_session_id,
      'reason', p_reason
    )
  );

  RETURN jsonb_build_object(
    'status', 'corrected',
    'payment_id', v_payment.id,
    'order_id', v_order.id,
    'pos_session_id', v_order.pos_session_id,
    'old_method', v_payment.method,
    'new_method', p_new_method
  );
END;
$$;


--
-- Name: FUNCTION correct_payment_method(p_payment_id bigint, p_new_method text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.correct_payment_method(p_payment_id bigint, p_new_method text, p_reason text) IS 'Owner-level audited correction that updates the completed payment and order display mirror, then recalculates any closed POS session from completed payments.';


--
-- Name: count_unread_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_unread_notifications() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH ctx AS MATERIALIZED (
    SELECT
      auth.uid() AS user_id,
      public.auth_tenant_id() AS tenant_id,
      public.auth_branch_id() AS branch_id,
      public.auth_role() AS user_role
  )
  SELECT count(*)::bigint
  FROM ctx
  JOIN public.notifications n
    ON n.tenant_id = ctx.tenant_id
  WHERE ctx.user_id IS NOT NULL
    AND ctx.tenant_id IS NOT NULL
    AND ctx.user_role IS NOT NULL
    AND n.target_roles @> ARRAY[ctx.user_role]::text[]
    AND (
      n.target_branch_id IS NULL
      OR n.target_branch_id = ctx.branch_id
      OR ctx.user_role IN ('owner')
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.notification_reads r
      WHERE r.notification_id = n.id
        AND r.user_id = ctx.user_id
    )
    AND (n.expires_at IS NULL OR n.expires_at > now());
$$;


--
-- Name: count_unread_notifications_by_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_unread_notifications_by_target() RETURNS TABLE(kind text, action_url text, unread_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    notification.kind,
    notification.action_url,
    count(*)::bigint AS unread_count
  FROM public.notifications AS notification
  LEFT JOIN public.notification_reads AS notification_read
    ON notification_read.notification_id = notification.id
   AND notification_read.user_id = (SELECT auth.uid())
  WHERE notification_read.notification_id IS NULL
    AND (
      notification.expires_at IS NULL
      OR notification.expires_at > now()
    )
  GROUP BY notification.kind, notification.action_url;
$$;


--
-- Name: FUNCTION count_unread_notifications_by_target(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.count_unread_notifications_by_target() IS 'RLS-scoped unread notification counts grouped by navigation target.';


--
-- Name: create_expense_transfer_intent(bigint, date, text, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expense_transfer_intent(p_branch_id bigint, p_expense_date date, p_category text, p_vat_breakdown jsonb, p_vendor_name text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_invoice_attachment_url text DEFAULT NULL::text) RETURNS TABLE(expense_id bigint, transfer_content text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_user_id uuid := auth.uid();
  v_prefix text;
  v_expense_token text;
  v_expense_id bigint;
  v_transfer_content text;
  v_vendor_name text := NULLIF(btrim(p_vendor_name), '');
  v_note text := NULLIF(btrim(p_note), '');
  v_attachment text := NULLIF(btrim(p_invoice_attachment_url), '');
BEGIN
  IF v_user_id IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_user_id)
    OR NOT EXISTS (
      SELECT 1
      FROM public.profiles profile
      WHERE profile.id = v_user_id
        AND profile.tenant_id = v_tenant_id
        AND COALESCE(profile.is_active, true)
    )
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_expense_date IS NULL
    OR p_category IS NULL
    OR NOT (
      p_category = ANY (ARRAY[
        'rent',
        'utilities',
        'gas_fuel',
        'salary',
        'supplies',
        'repair',
        'marketing',
        'fees_tax',
        'hospitality',
        'other'
      ]::text[])
    )
    OR p_vat_breakdown IS NULL
    OR char_length(v_vendor_name) > 200
    OR char_length(v_note) > 500
    OR char_length(v_attachment) > 2048
  THEN
    RAISE EXCEPTION 'expense_transfer_intent_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF p_branch_id IS NOT NULL THEN
    PERFORM 1
    FROM public.branches branch
    WHERE branch.id = p_branch_id
      AND branch.tenant_id = v_tenant_id
    FOR KEY SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  SELECT
    COALESCE(
      NULLIF(
        regexp_replace(
          upper(max(setting.value) FILTER (
            WHERE setting.key = 'payment_content_prefix'
          )),
          '[^A-Z0-9]+',
          '',
          'g'
        ),
        ''
      ),
      'MATU'
    ),
    COALESCE(
      NULLIF(
        regexp_replace(
          upper(max(setting.value) FILTER (
            WHERE setting.key = 'payment_content_expense_token'
          )),
          '[^A-Z0-9]+',
          '',
          'g'
        ),
        ''
      ),
      'CHI'
    )
  INTO v_prefix, v_expense_token
  FROM public.system_settings setting
  WHERE setting.tenant_id = v_tenant_id
    AND setting.key IN (
      'payment_content_prefix',
      'payment_content_expense_token'
    );

  IF char_length(v_prefix) NOT BETWEEN 2 AND 16
    OR char_length(v_expense_token) NOT BETWEEN 2 AND 16
  THEN
    RAISE EXCEPTION 'payment_content_settings_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_expense_id := nextval('public.expenses_id_seq'::regclass);
  v_transfer_content :=
    v_prefix || ' ' || v_expense_token || ' ' || v_expense_id::text;

  INSERT INTO public.expenses (
    id,
    tenant_id,
    branch_id,
    expense_date,
    category,
    amount,
    subtotal,
    vat_amount,
    vat_breakdown,
    payment_method,
    paid_at,
    vendor_name,
    note,
    invoice_attachment_url,
    created_by,
    transfer_content
  )
  OVERRIDING SYSTEM VALUE
  VALUES (
    v_expense_id,
    v_tenant_id,
    p_branch_id,
    p_expense_date,
    p_category,
    0,
    0,
    0,
    p_vat_breakdown,
    'unpaid',
    NULL,
    v_vendor_name,
    v_note,
    v_attachment,
    v_user_id,
    v_transfer_content
  );

  RETURN QUERY SELECT v_expense_id, v_transfer_content;
END;
$$;


--
-- Name: FUNCTION create_expense_transfer_intent(p_branch_id bigint, p_expense_date date, p_category text, p_vat_breakdown jsonb, p_vendor_name text, p_note text, p_invoice_attachment_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_expense_transfer_intent(p_branch_id bigint, p_expense_date date, p_category text, p_vat_breakdown jsonb, p_vendor_name text, p_note text, p_invoice_attachment_url text) IS 'Creates an unpaid operating expense with transfer_content and immutable vat_breakdown; amount is derived by trigger.';


--
-- Name: create_expiry_writeoff(bigint, bigint, bigint, numeric, bigint, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expiry_writeoff(p_branch_id bigint, p_location_id bigint, p_ingredient_id bigint, p_quantity numeric, p_grn_item_id bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_photo_urls text[] DEFAULT ARRAY[]::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_location record;
  v_grn_line record;
  v_shift_key text;
  v_issue_id bigint;
  v_issue_number text;
  v_approval_status text;
  v_seed_cost numeric(15,2);
  v_source_ref jsonb := jsonb_build_object('kind', 'expiry');
  v_entry_unit_id bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission(
    p_branch_id,
    'inventory:writeoff'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_quantity IS NULL
     OR p_quantity <= 0
     OR p_quantity = 'NaN'::numeric
     OR p_quantity = 'Infinity'::numeric
     OR p_quantity = '-Infinity'::numeric THEN
    RAISE EXCEPTION 'quantity must be positive'
      USING ERRCODE = '22023';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT
    location.id,
    location.tenant_id,
    location.branch_id,
    location.is_active,
    location.location_kind
  INTO v_location
  FROM public.inventory_locations AS location
  JOIN public.branches AS branch
    ON branch.id = location.branch_id
   AND branch.tenant_id = location.tenant_id
   AND branch.is_active IS TRUE
  WHERE location.id = p_location_id
  FOR UPDATE OF location;

  IF NOT FOUND
     OR v_location.is_active IS DISTINCT FROM TRUE
     OR v_location.tenant_id <> v_tenant
     OR v_location.branch_id <> p_branch_id
     OR v_location.location_kind <> 'warehouse' THEN
    RAISE EXCEPTION 'location_scope_mismatch'
      USING ERRCODE = '42501';
  END IF;

  IF p_grn_item_id IS NOT NULL THEN
    SELECT
      item.id,
      item.grn_id,
      item.entry_unit_id
    INTO v_grn_line
    FROM public.grn_items AS item
    JOIN public.goods_received_notes AS grn
      ON grn.id = item.grn_id
     AND grn.tenant_id = item.tenant_id
    WHERE item.id = p_grn_item_id
      AND item.tenant_id = v_tenant
      AND item.ingredient_id = p_ingredient_id
      AND grn.branch_id = p_branch_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'grn_item_not_found'
        USING ERRCODE = '22023';
    END IF;

    v_entry_unit_id := v_grn_line.entry_unit_id;
    v_source_ref := v_source_ref || jsonb_build_object(
      'grn_item_id',
      v_grn_line.id,
      'grn_id',
      v_grn_line.grn_id
    );
  END IF;

  IF v_entry_unit_id IS NULL THEN
    SELECT ingredient_unit.unit_id
    INTO v_entry_unit_id
    FROM public.ingredient_units AS ingredient_unit
    JOIN public.units AS unit
      ON unit.id = ingredient_unit.unit_id
     AND unit.tenant_id = ingredient_unit.tenant_id
     AND unit.is_active IS TRUE
    WHERE ingredient_unit.tenant_id = v_tenant
      AND ingredient_unit.ingredient_id = p_ingredient_id
      AND ingredient_unit.is_base IS TRUE
      AND ingredient_unit.is_active IS TRUE
    ORDER BY ingredient_unit.sort_order, ingredient_unit.id
    LIMIT 1;
  END IF;

  IF v_entry_unit_id IS NULL THEN
    RAISE EXCEPTION 'entry_unit_required'
      USING ERRCODE = '22023';
  END IF;

  v_shift_key := public.inventory_shift_key(p_branch_id, now());
  v_issue_number := public.next_inventory_doc_number(
    v_tenant,
    'waste'
  );

  INSERT INTO public.stock_issues (
    tenant_id,
    branch_id,
    issue_number,
    issue_type,
    status,
    notes,
    issued_at,
    created_by,
    source_location_id,
    approval_status,
    shift_key,
    source_type,
    source_ref
  )
  VALUES (
    v_tenant,
    p_branch_id,
    v_issue_number,
    'writeoff',
    'draft',
    p_note,
    now(),
    v_uid,
    p_location_id,
    'not_required',
    v_shift_key,
    'manual',
    v_source_ref
  )
  RETURNING id INTO v_issue_id;

  SELECT stock.avg_unit_cost
  INTO v_seed_cost
  FROM public.stock_levels AS stock
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = p_branch_id
    AND stock.location_id = p_location_id
    AND stock.ingredient_id = p_ingredient_id;

  INSERT INTO public.stock_issue_items (
    tenant_id,
    issue_id,
    ingredient_id,
    quantity,
    entry_unit_id,
    unit_cost,
    reason_code,
    photo_urls,
    reason
  )
  VALUES (
    v_tenant,
    v_issue_id,
    p_ingredient_id,
    p_quantity,
    v_entry_unit_id,
    coalesce(v_seed_cost, 0),
    'expired',
    coalesce(p_photo_urls, ARRAY[]::text[]),
    p_note
  );

  SELECT issue.approval_status
  INTO v_approval_status
  FROM public.stock_issues AS issue
  WHERE issue.id = v_issue_id
    AND issue.tenant_id = v_tenant;

  IF v_approval_status = 'not_required' THEN
    PERFORM public._post_writeoff_movements(v_issue_id);
  END IF;

  RETURN jsonb_build_object(
    'issue_id',
    v_issue_id,
    'issue_number',
    v_issue_number,
    'requires_approval',
    v_approval_status = 'pending',
    'stock_decremented',
    v_approval_status = 'not_required'
  );
END;
$$;


--
-- Name: create_finance_fund_adjustment(numeric, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_finance_fund_adjustment(p_cash_delta numeric, p_bank_delta numeric, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_now timestamptz := statement_timestamp();
  v_reason text := btrim(p_reason);
  v_existing public.finance_fund_entries%ROWTYPE;
  v_entry public.finance_fund_entries%ROWTYPE;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT (public.auth_is_owner(v_actor) OR public.has_position('accountant'))
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_cash_delta IS NULL
    OR p_bank_delta IS NULL
    OR (p_cash_delta = 0 AND p_bank_delta = 0)
    OR abs(p_cash_delta) > 100000000000
    OR abs(p_bank_delta) > 100000000000
    OR v_reason IS NULL
    OR char_length(v_reason) NOT BETWEEN 5 AND 500
    OR p_idempotency_key IS NULL
  THEN
    RAISE EXCEPTION 'finance_fund_adjustment_invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('finance_funds:' || v_tenant_id::text, 0)
  );

  SELECT *
  INTO v_existing
  FROM public.finance_fund_entries entry
  WHERE entry.tenant_id = v_tenant_id
    AND entry.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.entry_type = 'adjustment'
      AND v_existing.cash_delta = p_cash_delta
      AND v_existing.bank_delta = p_bank_delta
      AND v_existing.reason = v_reason
    THEN
      RETURN to_jsonb(v_existing);
    END IF;

    RAISE EXCEPTION 'finance_fund_idempotency_conflict'
      USING ERRCODE = '23505';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.finance_fund_entries entry
    WHERE entry.tenant_id = v_tenant_id
      AND entry.entry_type = 'opening'
  ) THEN
    RAISE EXCEPTION 'finance_funds_not_initialized'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.finance_fund_entries (
    tenant_id,
    entry_type,
    cash_delta,
    bank_delta,
    effective_at,
    reason,
    created_by,
    idempotency_key,
    created_at
  ) VALUES (
    v_tenant_id,
    'adjustment',
    p_cash_delta,
    p_bank_delta,
    v_now,
    v_reason,
    v_actor,
    p_idempotency_key,
    v_now
  )
  RETURNING * INTO v_entry;

  PERFORM public.log_audit(
    'finance_fund_adjustment_created',
    'finance_fund_entry',
    v_entry.id,
    NULL,
    jsonb_build_object(
      'entry_type', v_entry.entry_type,
      'cash_delta', v_entry.cash_delta,
      'bank_delta', v_entry.bank_delta,
      'effective_at', v_entry.effective_at,
      'reason', v_entry.reason,
      'idempotency_key', v_entry.idempotency_key
    )
  );

  RETURN to_jsonb(v_entry);
END;
$$;


--
-- Name: FUNCTION create_finance_fund_adjustment(p_cash_delta numeric, p_bank_delta numeric, p_reason text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_finance_fund_adjustment(p_cash_delta numeric, p_bank_delta numeric, p_reason text, p_idempotency_key uuid) IS 'Appends an audited signed correction at server time. Equal retry keys are idempotent only for equal payloads.';


--
-- Name: create_grn_draft_from_po(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_grn_draft_from_po(p_po_id bigint, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_branch_id bigint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_po_id IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'grn_create_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT purchase_order.branch_id
  INTO v_branch_id
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.id = p_po_id
    AND purchase_order.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_branch_id, 'procurement:grn_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN private.ensure_grn_draft_for_po(
    v_tenant,
    p_po_id,
    v_uid,
    p_idempotency_key
  );
END;
$$;


--
-- Name: create_grn_from_approved_po(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_grn_from_approved_po(p_po_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_po record;
  v_grn_id bigint;
  v_grn_number text;
  v_location_id bigint;
  v_line_count integer := 0;
  v_existing_draft_count integer := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_po_id IS NULL OR p_po_id <= 0 THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: invalid PO id'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT purchase_order.*
  INTO v_po
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.id = p_po_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: PO not found'
      USING ERRCODE = 'no_data_found';
  END IF;
  IF v_po.status NOT IN ('sent', 'partially_received') THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: PO status not eligible'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*)::integer, min(grn.id)
  INTO v_existing_draft_count, v_grn_id
  FROM public.goods_received_notes AS grn
  WHERE grn.tenant_id = v_po.tenant_id
    AND grn.po_id = v_po.id
    AND grn.status = 'draft';

  IF v_existing_draft_count > 1 THEN
    RAISE EXCEPTION
      'create_grn_from_approved_po: multiple linked drafts'
      USING ERRCODE = 'unique_violation';
  END IF;

  IF v_existing_draft_count = 1 THEN
    SELECT grn.grn_number
    INTO v_grn_number
    FROM public.goods_received_notes AS grn
    WHERE grn.id = v_grn_id
      AND grn.tenant_id = v_po.tenant_id;

    SELECT count(*)::integer
    INTO v_line_count
    FROM public.grn_items AS item
    WHERE item.tenant_id = v_po.tenant_id
      AND item.grn_id = v_grn_id;

    RETURN jsonb_build_object(
      'grn_id', v_grn_id,
      'grn_number', v_grn_number,
      'lines', v_line_count,
      'reused', TRUE
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches AS branch
    WHERE branch.id = v_po.branch_id
      AND branch.tenant_id = v_po.tenant_id
      AND branch.is_active IS TRUE
      AND branch.branch_kind IN (
        'branch',
        'central_supply',
        'central_kitchen'
      )
  ) THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: branch invalid'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.suppliers AS supplier
    WHERE supplier.id = v_po.supplier_id
      AND supplier.tenant_id = v_po.tenant_id
      AND supplier.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: supplier invalid'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.purchase_order_items AS item
    WHERE item.tenant_id = v_po.tenant_id
      AND item.po_id = v_po.id
  ) THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: PO has no lines'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.purchase_order_items AS item
    WHERE item.tenant_id = v_po.tenant_id
      AND item.po_id = v_po.id
      AND (
        item.quantity <= 0
        OR item.unit_price_est IS NULL
        OR item.unit_price_est <= 0
      )
  ) THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: invalid approved price'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT location.id
  INTO v_location_id
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = v_po.tenant_id
    AND location.branch_id = v_po.branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE
    AND location.is_default_receive IS TRUE;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: warehouse missing'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF NOT EXISTS (
    WITH received AS (
      SELECT
        item.ingredient_id,
        sum(public.inv_to_base_for_tenant(
          v_po.tenant_id,
          item.ingredient_id,
          item.entry_unit_id,
          item.received_quantity - item.rejected_quantity
        )) AS base_quantity
      FROM public.grn_items AS item
      JOIN public.goods_received_notes AS grn
        ON grn.id = item.grn_id
       AND grn.tenant_id = item.tenant_id
      WHERE grn.po_id = v_po.id
        AND grn.tenant_id = v_po.tenant_id
        AND grn.status = 'confirmed'
      GROUP BY item.ingredient_id
    )
    SELECT 1
    FROM public.purchase_order_items AS po_item
    LEFT JOIN received USING (ingredient_id)
    WHERE po_item.tenant_id = v_po.tenant_id
      AND po_item.po_id = v_po.id
      AND public.inv_to_base_for_tenant(
        v_po.tenant_id,
        po_item.ingredient_id,
        po_item.entry_unit_id,
        po_item.quantity
      ) > coalesce(received.base_quantity, 0)
  ) THEN
    RAISE EXCEPTION 'create_grn_from_approved_po: PO fully received'
      USING ERRCODE = 'no_data_found';
  END IF;

  v_grn_number := public.next_inventory_doc_number(
    v_po.tenant_id,
    'grn'
  );

  PERFORM pg_catalog.set_config(
    'comtammatu.grn_recovery_insert',
    'true',
    TRUE
  );

  INSERT INTO public.goods_received_notes (
    tenant_id,
    branch_id,
    location_id,
    supplier_id,
    po_id,
    grn_number,
    status,
    created_by
  )
  VALUES (
    v_po.tenant_id,
    v_po.branch_id,
    v_location_id,
    v_po.supplier_id,
    v_po.id,
    v_grn_number,
    'draft',
    v_po.created_by
  )
  RETURNING id INTO v_grn_id;

  UPDATE public.purchase_orders
  SET source_grn_id = COALESCE(source_grn_id, v_grn_id)
  WHERE id = v_po.id
    AND tenant_id = v_po.tenant_id;

  WITH received AS (
    SELECT
      item.ingredient_id,
      sum(public.inv_to_base_for_tenant(
        v_po.tenant_id,
        item.ingredient_id,
        item.entry_unit_id,
        item.received_quantity - item.rejected_quantity
      )) AS base_quantity
    FROM public.grn_items AS item
    JOIN public.goods_received_notes AS grn
      ON grn.id = item.grn_id
     AND grn.tenant_id = item.tenant_id
    WHERE grn.po_id = v_po.id
      AND grn.tenant_id = v_po.tenant_id
      AND grn.status = 'confirmed'
    GROUP BY item.ingredient_id
  ),
  remaining AS (
    SELECT
      po_item.ingredient_id,
      po_item.entry_unit_id,
      po_item.unit_price_est,
      round(
        (
          public.inv_to_base_for_tenant(
            v_po.tenant_id,
            po_item.ingredient_id,
            po_item.entry_unit_id,
            po_item.quantity
          ) - coalesce(received.base_quantity, 0)
        ) / public.inv_to_base_for_tenant(
          v_po.tenant_id,
          po_item.ingredient_id,
          po_item.entry_unit_id,
          1
        ),
        3
      )::numeric(15,3) AS quantity
    FROM public.purchase_order_items AS po_item
    LEFT JOIN received USING (ingredient_id)
    WHERE po_item.tenant_id = v_po.tenant_id
      AND po_item.po_id = v_po.id
  )
  INSERT INTO public.grn_items (
    tenant_id,
    grn_id,
    ingredient_id,
    supplier_id,
    received_quantity,
    rejected_quantity,
    rejection_reason,
    rejected_photo_url,
    entry_unit_id,
    unit_cost,
    total_cost
  )
  SELECT
    v_po.tenant_id,
    v_grn_id,
    remaining.ingredient_id,
    v_po.supplier_id,
    remaining.quantity,
    0,
    NULL,
    NULL,
    remaining.entry_unit_id,
    remaining.unit_price_est,
    round(remaining.quantity * remaining.unit_price_est, 2)
  FROM remaining
  WHERE remaining.quantity > 0;

  GET DIAGNOSTICS v_line_count = ROW_COUNT;

  PERFORM pg_catalog.set_config(
    'comtammatu.grn_recovery_insert',
    'false',
    TRUE
  );

  INSERT INTO public.audit_logs (
    tenant_id,
    user_id,
    action,
    entity_type,
    entity_id,
    old_data,
    new_data
  )
  VALUES (
    v_po.tenant_id,
    NULL,
    'inventory.grn.recovered_from_approved_po',
    'goods_received_note',
    v_grn_id,
    NULL,
    jsonb_build_object(
      'actor_type', 'service_role',
      'po_id', v_po.id,
      'branch_id', v_po.branch_id,
      'lines', v_line_count
    )
  );

  RETURN jsonb_build_object(
    'grn_id', v_grn_id,
    'grn_number', v_grn_number,
    'lines', v_line_count
  );
END;
$$;


--
-- Name: create_inventory_document_correction(text, bigint, bigint, bigint, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_inventory_document_correction(p_document_type text, p_document_id bigint, p_branch_id bigint, p_ingredient_id bigint, p_quantity_change numeric, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_reason text := pg_catalog.btrim(coalesce(p_reason, ''));
  v_source_code text;
  v_source_label text;
  v_location_id bigint;
  v_entry_unit_id bigint;
  v_entry_to_base_factor numeric(18,12);
  v_movement_id bigint;
  v_current_quantity numeric(15,3);
  v_existing public.stock_movements%ROWTYPE;
  v_grn_id bigint;
  v_issue_id bigint;
  v_transfer_id bigint;
  v_production_run_id bigint;
  v_grn record;
  v_issue record;
  v_transfer record;
  v_run record;
BEGIN
  IF v_actor IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_document_type IS NULL
     OR p_document_type NOT IN ('grn', 'issue', 'transfer', 'production_run')
     OR p_document_id IS NULL
     OR p_document_id <= 0
     OR p_branch_id IS NULL
     OR p_branch_id <= 0
     OR p_ingredient_id IS NULL
     OR p_ingredient_id <= 0
     OR p_quantity_change IS NULL
     OR p_quantity_change = 0
     OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'invalid_document_correction' USING ERRCODE = '22023';
  END IF;
  IF pg_catalog.length(v_reason) < 10 OR pg_catalog.length(v_reason) > 500 THEN
    RAISE EXCEPTION 'invalid_document_correction_reason' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles AS profile
    WHERE profile.id = v_actor
      AND profile.tenant_id = v_tenant
      AND coalesce(profile.is_active, TRUE)
  ) OR NOT public.has_permission(p_branch_id, 'inventory:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_document_type = 'grn' THEN
    SELECT note.id, note.branch_id, note.location_id, note.status, note.grn_number
    INTO v_grn
    FROM public.goods_received_notes AS note
    WHERE note.id = p_document_id
      AND note.tenant_id = v_tenant
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'source_document_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_grn.status <> 'confirmed' THEN
      RAISE EXCEPTION 'source_document_not_posted' USING ERRCODE = '23514';
    END IF;
    IF v_grn.branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'source_scope_mismatch' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.grn_items AS item
      WHERE item.tenant_id = v_tenant
        AND item.grn_id = v_grn.id
        AND item.ingredient_id = p_ingredient_id
    ) THEN
      RAISE EXCEPTION 'source_ingredient_missing' USING ERRCODE = '23514';
    END IF;
    v_grn_id := v_grn.id;
    v_location_id := v_grn.location_id;
    v_source_code := v_grn.grn_number;
    v_source_label := 'Phiếu nhập';
  ELSIF p_document_type = 'issue' THEN
    SELECT issue.id, issue.branch_id, issue.source_location_id, issue.status,
           issue.issue_number, issue.source_ref
    INTO v_issue
    FROM public.stock_issues AS issue
    WHERE issue.id = p_document_id
      AND issue.tenant_id = v_tenant
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'source_document_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_issue.status <> 'confirmed' THEN
      RAISE EXCEPTION 'source_document_not_posted' USING ERRCODE = '23514';
    END IF;
    IF v_issue.branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'source_scope_mismatch' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.stock_issue_items AS item
      WHERE item.tenant_id = v_tenant
        AND item.issue_id = v_issue.id
        AND item.ingredient_id = p_ingredient_id
    ) THEN
      RAISE EXCEPTION 'source_ingredient_missing' USING ERRCODE = '23514';
    END IF;
    v_issue_id := v_issue.id;
    v_location_id := v_issue.source_location_id;
    v_source_code := v_issue.issue_number;
    v_source_label := 'Phiếu xuất';
    IF v_issue.source_ref ->> 'source' = 'attendance_consumption_report' THEN
      v_source_label := v_source_label || ' ' || v_source_code || ' - '
        || coalesce(
          nullif(v_issue.source_ref ->> 'source_label', ''),
          'Nhân sự - Tiêu hao bếp trong ngày'
        );
      v_source_code := NULL;
    END IF;
  ELSIF p_document_type = 'transfer' THEN
    SELECT transfer.id, transfer.from_branch_id, transfer.to_branch_id,
           transfer.from_location_id, transfer.to_location_id,
           transfer.status, transfer.transfer_number
    INTO v_transfer
    FROM public.stock_transfers AS transfer
    WHERE transfer.id = p_document_id
      AND transfer.tenant_id = v_tenant
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'source_document_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_transfer.status NOT IN (
      'confirmed_ship', 'in_transit', 'confirmed_receive', 'received'
    ) THEN
      RAISE EXCEPTION 'source_document_not_posted' USING ERRCODE = '23514';
    END IF;
    IF p_branch_id NOT IN (v_transfer.from_branch_id, v_transfer.to_branch_id)
       OR (
         v_transfer.status <> 'received'
         AND p_branch_id <> v_transfer.from_branch_id
       ) THEN
      RAISE EXCEPTION 'source_scope_mismatch' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.stock_transfer_items AS item
      WHERE item.tenant_id = v_tenant
        AND item.transfer_id = v_transfer.id
        AND item.ingredient_id = p_ingredient_id
    ) THEN
      RAISE EXCEPTION 'source_ingredient_missing' USING ERRCODE = '23514';
    END IF;
    v_transfer_id := v_transfer.id;
    v_location_id := CASE
      WHEN p_branch_id = v_transfer.from_branch_id
        THEN v_transfer.from_location_id
      ELSE v_transfer.to_location_id
    END;
    v_source_code := v_transfer.transfer_number;
    v_source_label := 'Điều chuyển';
  ELSIF p_document_type = 'production_run' THEN
    SELECT run.id, run.target_branch_id, run.target_location_id, run.status,
           run.production_number, run.finished_good_id
    INTO v_run
    FROM public.production_runs AS run
    WHERE run.id = p_document_id
      AND run.tenant_id = v_tenant
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'source_document_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_run.status <> 'completed' THEN
      RAISE EXCEPTION 'source_document_not_posted' USING ERRCODE = '23514';
    END IF;
    IF v_run.target_branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'source_scope_mismatch' USING ERRCODE = '42501';
    END IF;
    IF v_run.finished_good_id <> p_ingredient_id THEN
      RAISE EXCEPTION 'source_ingredient_missing' USING ERRCODE = '23514';
    END IF;
    v_production_run_id := v_run.id;
    v_location_id := v_run.target_location_id;
    v_source_code := v_run.production_number;
    v_source_label := 'Sản xuất';
  END IF;

  IF v_location_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations AS location
    WHERE location.id = v_location_id
      AND location.tenant_id = v_tenant
      AND location.branch_id = p_branch_id
  ) THEN
    RAISE EXCEPTION 'source_location_invalid' USING ERRCODE = '23514';
  END IF;

  v_reason := v_source_label
    || CASE WHEN v_source_code IS NULL THEN '' ELSE ' ' || v_source_code END
    || ': ' || v_reason;

  SELECT movement.*
  INTO v_existing
  FROM public.stock_movements AS movement
  WHERE movement.tenant_id = v_tenant
    AND movement.correction_idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.branch_id IS DISTINCT FROM p_branch_id
       OR v_existing.ingredient_id IS DISTINCT FROM p_ingredient_id
       OR v_existing.quantity_change IS DISTINCT FROM p_quantity_change
       OR v_existing.reason IS DISTINCT FROM v_reason
       OR v_existing.created_by IS DISTINCT FROM v_actor
       OR v_existing.location_id IS DISTINCT FROM v_location_id
       OR v_existing.grn_id IS DISTINCT FROM v_grn_id
       OR v_existing.issue_id IS DISTINCT FROM v_issue_id
       OR v_existing.transfer_id IS DISTINCT FROM v_transfer_id
       OR v_existing.production_run_id IS DISTINCT FROM v_production_run_id THEN
      RAISE EXCEPTION 'document_correction_idempotency_conflict'
        USING ERRCODE = '23505';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'success', TRUE,
      'movement_id', v_existing.id,
      'idempotent', TRUE
    );
  END IF;

  SELECT ingredient_unit.unit_id, ingredient_unit.to_base_factor
  INTO v_entry_unit_id, v_entry_to_base_factor
  FROM public.ingredient_units AS ingredient_unit
  JOIN public.ingredients AS ingredient
    ON ingredient.id = ingredient_unit.ingredient_id
   AND ingredient.tenant_id = ingredient_unit.tenant_id
  JOIN public.units AS unit
    ON unit.id = ingredient_unit.unit_id
   AND unit.tenant_id = ingredient_unit.tenant_id
  WHERE ingredient_unit.tenant_id = v_tenant
    AND ingredient_unit.ingredient_id = p_ingredient_id
    AND ingredient_unit.is_active
    AND unit.is_active
    AND ingredient_unit.unit_id = ingredient.issue_unit_id
  ORDER BY ingredient_unit.sort_order, ingredient_unit.id
  LIMIT 1;
  IF v_entry_unit_id IS NULL OR v_entry_to_base_factor <= 0 THEN
    RAISE EXCEPTION 'entry_unit_not_found' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.stock_levels (
    tenant_id, branch_id, ingredient_id, location_id, current_quantity
  ) VALUES (
    v_tenant, p_branch_id, p_ingredient_id, v_location_id, 0
  )
  ON CONFLICT ON CONSTRAINT stock_levels_ingredient_branch_location_tenant_key
  DO NOTHING;

  SELECT stock.current_quantity
  INTO v_current_quantity
  FROM public.stock_levels AS stock
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = p_branch_id
    AND stock.location_id = v_location_id
    AND stock.ingredient_id = p_ingredient_id
  FOR UPDATE;

  IF v_current_quantity + p_quantity_change < 0 THEN
    RAISE EXCEPTION 'insufficient_stock' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.stock_movements (
    tenant_id,
    branch_id,
    ingredient_id,
    type,
    quantity_change,
    entry_unit_id,
    entry_quantity,
    reason,
    created_by,
    location_id,
    grn_id,
    issue_id,
    transfer_id,
    production_run_id,
    correction_idempotency_key
  ) VALUES (
    v_tenant,
    p_branch_id,
    p_ingredient_id,
    'adjustment',
    p_quantity_change,
    v_entry_unit_id,
    pg_catalog.round(
      pg_catalog.abs(p_quantity_change) / v_entry_to_base_factor,
      3
    ),
    v_reason,
    v_actor,
    v_location_id,
    v_grn_id,
    v_issue_id,
    v_transfer_id,
    v_production_run_id,
    p_idempotency_key
  )
  RETURNING id INTO v_movement_id;

  RETURN pg_catalog.jsonb_build_object(
    'success', TRUE,
    'movement_id', v_movement_id,
    'idempotent', FALSE
  );
END;
$$;


--
-- Name: create_order(bigint, bigint, uuid, jsonb, text, bigint, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_order(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text DEFAULT 'dine_in'::text, p_table_id bigint DEFAULT NULL::bigint, p_pos_session_id bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_created_by       UUID;
  v_order_id         BIGINT;
  v_order_number     TEXT;
  v_date_part        TEXT;
  v_subtotal         NUMERIC(15,2) := 0;
  v_seq              INT;
  v_table_number     INT;
  v_item             JSONB;
  v_base_price       NUMERIC(15,2);
  v_variant_adj      NUMERIC(15,2);
  v_modifier_sum     NUMERIC(15,2);
  v_sides_sum        NUMERIC(15,2);
  v_enriched_sides   JSONB;
  v_unit_price       NUMERIC(15,2);
  v_item_subtotal    NUMERIC(15,2);
  v_menu_item_id     BIGINT;
  v_variant_id       BIGINT;
  v_quantity         INT;
  v_prof_tenant      BIGINT;
  v_prof_branch      BIGINT;
  v_prof_role        TEXT;
  v_branch_code      TEXT;
  v_item_discount    NUMERIC(15,2);
BEGIN
  v_created_by := auth.uid();
  IF v_created_by IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
    INTO v_prof_tenant, v_prof_branch, v_prof_role
    FROM public.profiles p
    LEFT JOIN public.positions po ON po.id = p.position_id
   WHERE p.id = v_created_by;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_tenant IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = p_branch_id AND b.tenant_id = p_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF p_branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = p_branch_id AND b.tenant_id = p_tenant_id;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'p_items must be a non-empty JSON array' USING ERRCODE = '22023';
  END IF;

  IF p_order_type NOT IN ('dine_in', 'takeaway') THEN
    RAISE EXCEPTION 'p_order_type must be dine_in or takeaway' USING ERRCODE = '22023';
  END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT t.number INTO v_table_number
      FROM public.tables t
     WHERE t.id = p_table_id AND t.branch_id = p_branch_id AND t.tenant_id = p_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Table does not belong to this branch' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_pos_session_id IS NOT NULL THEN
    PERFORM 1 FROM public.pos_sessions
     WHERE id = p_pos_session_id
       AND branch_id = p_branch_id
       AND tenant_id = p_tenant_id
       AND status = 'open';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'POS session does not belong to this branch or is not open' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT o.id, o.order_number INTO v_order_id, v_order_number
      FROM public.orders o
     WHERE o.tenant_id = p_tenant_id
       AND o.idempotency_key = p_idempotency_key;
    IF FOUND THEN
      RETURN jsonb_build_object('order_id', v_order_id, 'order_number', v_order_number);
    END IF;
  END IF;

  INSERT INTO public.order_daily_counters (
    tenant_id, branch_id, counter_date, last_seq
  )
  VALUES (
    p_tenant_id,
    p_branch_id,
    (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    1
  )
  ON CONFLICT (tenant_id, branch_id, counter_date)
  DO UPDATE SET
    last_seq   = public.order_daily_counters.last_seq + 1,
    updated_at = now()
  RETURNING last_seq INTO v_seq;

  v_date_part := to_char(
    CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh',
    'YYMMDD'
  );

  IF p_order_type = 'dine_in' THEN
    v_order_number := 'TC-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  ELSE
    v_order_number := 'MV-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  END IF;

  IF v_branch_code IS NOT NULL THEN
    v_order_number := v_order_number || '-' || v_branch_code;
  END IF;

  BEGIN
    INSERT INTO public.orders (
      tenant_id, branch_id, table_id, order_number, order_type,
      subtotal, total_amount, note, created_by,
      pos_session_id, idempotency_key
    )
    VALUES (
      p_tenant_id, p_branch_id, p_table_id, v_order_number, p_order_type,
      0, 0, p_note, v_created_by,
      p_pos_session_id, p_idempotency_key
    )
    RETURNING id INTO v_order_id;
  EXCEPTION
    WHEN unique_violation THEN
      IF p_idempotency_key IS NOT NULL THEN
        SELECT o.id, o.order_number INTO v_order_id, v_order_number
          FROM public.orders o
         WHERE o.tenant_id = p_tenant_id
           AND o.idempotency_key = p_idempotency_key;
        IF FOUND THEN
          RETURN jsonb_build_object('order_id', v_order_id, 'order_number', v_order_number);
        END IF;
      END IF;
      RAISE;
  END;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) AS value
  LOOP
    v_menu_item_id := (v_item ->> 'menu_item_id')::BIGINT;
    v_variant_id   := NULLIF(v_item ->> 'variant_id', '')::BIGINT;
    v_quantity     := (v_item ->> 'quantity')::INT;

    IF v_quantity IS NULL OR v_quantity < 1 THEN
      RAISE EXCEPTION 'invalid quantity' USING ERRCODE = '22023';
    END IF;

    SELECT base_price INTO v_base_price
      FROM public.menu_items
     WHERE id = v_menu_item_id AND tenant_id = p_tenant_id AND is_active = TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Menu item % not found or inactive', v_menu_item_id USING ERRCODE = 'P0002';
    END IF;

    v_variant_adj := 0;
    IF v_variant_id IS NOT NULL THEN
      SELECT price_adjustment INTO v_variant_adj
        FROM public.menu_item_variants
       WHERE id = v_variant_id AND item_id = v_menu_item_id AND tenant_id = p_tenant_id AND is_active = TRUE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Variant % not found or inactive', v_variant_id USING ERRCODE = 'P0002';
      END IF;
    END IF;

    v_modifier_sum := public.pos_order_modifier_sum(
      p_tenant_id,
      v_menu_item_id,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB)
    );

    SELECT sides_sum, enriched_sides
      INTO v_sides_sum, v_enriched_sides
      FROM public.pos_enrich_order_sides(
        p_tenant_id,
        v_menu_item_id,
        COALESCE(v_item -> 'sides', '[]'::JSONB)
      );

    v_unit_price    := v_base_price + v_variant_adj + v_modifier_sum + COALESCE(v_sides_sum, 0);
    v_item_subtotal := v_unit_price * v_quantity;
    v_subtotal      := v_subtotal + v_item_subtotal;

    INSERT INTO public.order_items (
      tenant_id, order_id, menu_item_id, variant_id,
      item_name, variant_name, quantity, unit_price,
      modifiers, sides, subtotal, note,
      discount_type, discount_value, discount_note
    )
    VALUES (
      p_tenant_id, v_order_id, v_menu_item_id, v_variant_id,
      v_item ->> 'item_name', v_item ->> 'variant_name',
      v_quantity, v_unit_price,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB),
      COALESCE(v_enriched_sides, '[]'::JSONB),
      v_item_subtotal, v_item ->> 'note',
      NULLIF(v_item ->> 'discount_type', ''),
      CASE WHEN NULLIF(v_item ->> 'discount_value', '') IS NOT NULL
           THEN (v_item ->> 'discount_value')::NUMERIC
           ELSE NULL END,
      NULLIF(trim(COALESCE(v_item ->> 'discount_note', '')), '')
    );
  END LOOP;

  UPDATE public.orders
     SET subtotal = v_subtotal, total_amount = v_subtotal
   WHERE id = v_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by
  )
  VALUES (p_tenant_id, v_order_id, NULL, 'new', v_created_by);

  IF p_order_type = 'dine_in' AND p_table_id IS NOT NULL THEN
    UPDATE public.tables
       SET status = 'occupied'
     WHERE id = p_table_id AND branch_id = p_branch_id AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Failed to update table status' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  PERFORM public.route_order_to_kds(v_order_id);

  SELECT COALESCE(o.item_discount_amount, 0) INTO v_item_discount
    FROM public.orders o WHERE o.id = v_order_id;

  RETURN jsonb_build_object(
    'order_id', v_order_id,
    'order_number', v_order_number,
    'item_discount_amount', v_item_discount
  );
END;
$$;


--
-- Name: create_order_with_daily_limit_hold(bigint, bigint, uuid, jsonb, text, bigint, bigint, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_order_with_daily_limit_hold(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text DEFAULT 'dine_in'::text, p_table_id bigint DEFAULT NULL::bigint, p_pos_session_id bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_daily_limit_hold_token uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_order_id bigint;
BEGIN
  IF p_daily_limit_hold_token IS NOT NULL THEN
    PERFORM set_config(
      'comtammatu.daily_limit_hold_token',
      p_daily_limit_hold_token::text,
      true
    );
  END IF;

  v_result := public.create_order(
    p_tenant_id,
    p_branch_id,
    p_created_by,
    p_items,
    p_order_type,
    p_table_id,
    p_pos_session_id,
    p_note,
    p_idempotency_key
  );

  v_order_id := NULLIF(v_result ->> 'order_id', '')::bigint;

  IF p_daily_limit_hold_token IS NOT NULL AND v_order_id IS NOT NULL THEN
    UPDATE public.branch_menu_item_daily_holds h
    SET committed_at = COALESCE(h.committed_at, now()),
        order_id = COALESCE(h.order_id, v_order_id),
        updated_at = now()
    WHERE h.tenant_id = p_tenant_id
      AND h.branch_id = p_branch_id
      AND h.hold_token = p_daily_limit_hold_token
      AND h.held_by = v_uid
      AND h.committed_at IS NULL
      AND h.released_at IS NULL
      AND h.expires_at > now();
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION create_order_with_daily_limit_hold(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text, p_table_id bigint, p_pos_session_id bigint, p_note text, p_idempotency_key uuid, p_daily_limit_hold_token uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_order_with_daily_limit_hold(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text, p_table_id bigint, p_pos_session_id bigint, p_note text, p_idempotency_key uuid, p_daily_limit_hold_token uuid) IS 'Wrapper around create_order that sets transaction-local daily-limit hold token so the quota trigger excludes the caller hold, then commits matching active holds to the new order.';


--
-- Name: create_production_run(bigint, bigint, numeric, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_production_run(p_branch_id bigint, p_recipe_spec_id bigint, p_planned_quantity numeric, p_source_location_id bigint DEFAULT NULL::bigint, p_target_location_id bigint DEFAULT NULL::bigint, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_spec record;
  v_source_location_id bigint := p_source_location_id;
  v_target_location_id bigint := p_target_location_id;
  v_run_id bigint;
  v_number text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator()
     OR NOT public.has_permission(p_branch_id, 'inventory:production_create') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF p_planned_quantity IS NULL OR p_planned_quantity <= 0
     OR p_planned_quantity IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) THEN
    RAISE EXCEPTION 'planned_quantity_invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.branches AS branch
    WHERE branch.tenant_id = v_tenant
      AND branch.id = p_branch_id
      AND branch.branch_kind = 'central_kitchen'
      AND branch.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'production_site_invalid' USING ERRCODE = '42501';
  END IF;

  SELECT spec.* INTO v_spec
  FROM public.production_recipe_specs AS spec
  WHERE spec.tenant_id = v_tenant
    AND spec.id = p_recipe_spec_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'recipe_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_spec.status <> 'active' THEN
    RAISE EXCEPTION 'recipe_not_active' USING ERRCODE = '23514';
  END IF;

  IF v_source_location_id IS NULL THEN
    SELECT location.id INTO v_source_location_id
    FROM public.inventory_locations AS location
    WHERE location.tenant_id = v_tenant
      AND location.branch_id = p_branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE
    ORDER BY location.is_default_issue DESC, location.sort_order, location.id
    LIMIT 1;
  END IF;
  IF v_target_location_id IS NULL THEN
    v_target_location_id := v_source_location_id;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.inventory_locations AS location
    WHERE location.tenant_id = v_tenant
      AND location.branch_id = p_branch_id
      AND location.id = v_source_location_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'production_source_location_invalid' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inventory_locations AS location
    WHERE location.tenant_id = v_tenant
      AND location.branch_id = p_branch_id
      AND location.id = v_target_location_id
      AND location.location_kind IN ('warehouse', 'production_storage')
      AND location.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'production_target_location_invalid' USING ERRCODE = '23514';
  END IF;

  v_number := public.next_inventory_doc_number(v_tenant, 'production');
  INSERT INTO public.production_runs (
    tenant_id, production_number, branch_id, source_location_id,
    target_branch_id, target_location_id, finished_good_id,
    recipe_spec_id, recipe_output_quantity, planned_quantity,
    entry_unit_id, entry_to_base_factor, entry_unit_code,
    notes, created_by, status, ingredients_override
  ) VALUES (
    v_tenant, v_number, p_branch_id, v_source_location_id,
    p_branch_id, v_target_location_id, v_spec.finished_good_id,
    v_spec.id, v_spec.output_quantity, p_planned_quantity,
    v_spec.output_unit_id, v_spec.output_to_base_factor, v_spec.output_unit_code,
    nullif(pg_catalog.btrim(p_notes), ''), v_uid, 'draft', NULL
  ) RETURNING id INTO v_run_id;

  INSERT INTO public.production_run_lines (
    tenant_id, production_run_id, ingredient_id, planned_quantity,
    entry_unit_id, entry_to_base_factor, entry_unit_code
  )
  SELECT
    recipe.tenant_id,
    v_run_id,
    recipe.ingredient_id,
    (p_planned_quantity / v_spec.output_quantity) * recipe.quantity,
    recipe.entry_unit_id,
    recipe.entry_to_base_factor,
    recipe.entry_unit_code
  FROM public.production_recipes AS recipe
  WHERE recipe.tenant_id = v_tenant
    AND recipe.recipe_spec_id = v_spec.id
  ORDER BY recipe.ingredient_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'recipe_has_no_lines' USING ERRCODE = '23514';
  END IF;

  RETURN jsonb_build_object(
    'production_run_id', v_run_id,
    'production_number', v_number
  );
END;
$$;


--
-- Name: create_production_run(bigint, bigint, numeric, bigint, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_production_run(p_branch_id bigint, p_finished_good_id bigint, p_planned_quantity numeric, p_entry_unit_id bigint, p_notes text DEFAULT NULL::text, p_target_branch_id bigint DEFAULT NULL::bigint, p_ingredients_override jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  SELECT public.create_production_run_with_locations(
    p_branch_id,
    p_finished_good_id,
    p_planned_quantity,
    p_entry_unit_id,
    p_notes,
    p_target_branch_id,
    p_ingredients_override,
    NULL::bigint,
    NULL::bigint
  );
$$;


--
-- Name: create_production_run_with_locations(bigint, bigint, numeric, bigint, text, bigint, jsonb, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_production_run_with_locations(p_branch_id bigint, p_finished_good_id bigint, p_planned_quantity numeric, p_entry_unit_id bigint, p_notes text DEFAULT NULL::text, p_target_branch_id bigint DEFAULT NULL::bigint, p_ingredients_override jsonb DEFAULT NULL::jsonb, p_source_location_id bigint DEFAULT NULL::bigint, p_target_location_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
  PERFORM auth.role();
  RAISE EXCEPTION 'production_maintenance_legacy_rpc' USING ERRCODE = '55000';
END; $$;


--
-- Name: create_purchase_order_from_grn(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_order_from_grn(p_grn_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  v_result := public.create_purchase_orders_from_grn(p_grn_id);
  RETURN jsonb_build_object(
    'po_id', (v_result->>'po_id')::bigint,
    'display_id', (
      SELECT po.display_id
      FROM public.purchase_orders AS po
      WHERE po.id = (v_result->>'po_id')::bigint
    ),
    'grn_id', p_grn_id,
    'line_count', (v_result->>'line_count')::integer,
    'po_count', (v_result->>'po_count')::integer,
    'po_ids', v_result->'po_ids',
    'by_supplier', v_result->'by_supplier',
    'status', 'draft'
  );
END;
$$;


--
-- Name: FUNCTION create_purchase_order_from_grn(p_grn_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_purchase_order_from_grn(p_grn_id bigint) IS 'Compatibility wrapper around create_purchase_orders_from_grn (multi-supplier split).';


--
-- Name: create_purchase_order_from_request(bigint, bigint, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_order_from_request(p_request_id bigint, p_supplier_id bigint, p_expected_delivery_date date, p_notes text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request record;
  v_po_id bigint;
  v_po_number text;
  v_line_count integer;
  v_all_ordered boolean;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_supplier_id IS NULL
     OR jsonb_typeof(p_lines) <> 'array'
     OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'purchase_order_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT request.*
  INTO v_request
  FROM public.purchase_requests request
  WHERE request.id = p_request_id
    AND request.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_request.branch_id, 'procurement:po_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_request.status NOT IN ('submitted', 'partially_ordered') THEN
    RAISE EXCEPTION 'purchase_request_not_orderable'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.suppliers supplier
    WHERE supplier.id = p_supplier_id
      AND supplier.tenant_id = v_tenant
      AND supplier.is_active
  ) THEN
    RAISE EXCEPTION 'supplier_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_lines)
      AS line(
        request_item_id bigint,
        quantity numeric,
        unit_price numeric
      )
    JOIN public.purchase_request_items request_item
      ON request_item.id = line.request_item_id
     AND request_item.tenant_id = v_tenant
     AND request_item.purchase_request_id = p_request_id
    WHERE line.quantity IS NULL
       OR line.quantity <= 0
       OR line.unit_price IS NULL
       OR line.unit_price < 0
       OR line.quantity > (
         request_item.quantity - COALESCE((
           SELECT sum(po_item.quantity)
           FROM public.purchase_order_items po_item
           JOIN public.purchase_orders purchase_order
             ON purchase_order.id = po_item.po_id
            AND purchase_order.tenant_id = po_item.tenant_id
           WHERE po_item.tenant_id = v_tenant
             AND po_item.purchase_request_item_id = request_item.id
             AND purchase_order.status <> 'cancelled'
         ), 0)
       )
  )
  OR (
    SELECT count(*)
    FROM jsonb_to_recordset(p_lines)
      AS line(request_item_id bigint)
  ) <> (
    SELECT count(*)
    FROM jsonb_to_recordset(p_lines)
      AS line(request_item_id bigint)
    JOIN public.purchase_request_items request_item
      ON request_item.id = line.request_item_id
     AND request_item.tenant_id = v_tenant
     AND request_item.purchase_request_id = p_request_id
  )
  OR EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_lines)
      AS line(request_item_id bigint, quantity numeric)
    JOIN public.purchase_request_items request_item
      ON request_item.id = line.request_item_id
     AND request_item.tenant_id = v_tenant
     AND request_item.purchase_request_id = p_request_id
    GROUP BY request_item.id, request_item.quantity
    HAVING sum(line.quantity) > (
      request_item.quantity - COALESCE((
        SELECT sum(po_item.quantity)
        FROM public.purchase_order_items po_item
        JOIN public.purchase_orders purchase_order
          ON purchase_order.id = po_item.po_id
         AND purchase_order.tenant_id = po_item.tenant_id
        WHERE po_item.tenant_id = v_tenant
          AND po_item.purchase_request_item_id = request_item.id
          AND purchase_order.status <> 'cancelled'
      ), 0)
    )
  )
  OR EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_lines)
      AS line(request_item_id bigint)
    JOIN public.purchase_request_items request_item
      ON request_item.id = line.request_item_id
     AND request_item.tenant_id = v_tenant
     AND request_item.purchase_request_id = p_request_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.supplier_items supplier_item
      WHERE supplier_item.tenant_id = v_tenant
        AND supplier_item.supplier_id = p_supplier_id
        AND supplier_item.ingredient_id = request_item.ingredient_id
        AND supplier_item.is_active
    )
  ) THEN
    IF EXISTS (
      SELECT 1
      FROM jsonb_to_recordset(p_lines)
        AS line(request_item_id bigint)
      JOIN public.purchase_request_items request_item
        ON request_item.id = line.request_item_id
       AND request_item.tenant_id = v_tenant
       AND request_item.purchase_request_id = p_request_id
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.supplier_items supplier_item
        WHERE supplier_item.tenant_id = v_tenant
          AND supplier_item.supplier_id = p_supplier_id
          AND supplier_item.ingredient_id = request_item.ingredient_id
          AND supplier_item.is_active
      )
    ) THEN
      RAISE EXCEPTION 'supplier_item_mapping_required'
        USING ERRCODE = '23514';
    END IF;
    RAISE EXCEPTION 'purchase_order_line_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_po_number := public.next_po_display_id(v_tenant);

  INSERT INTO public.purchase_orders (
    tenant_id,
    branch_id,
    supplier_id,
    purchase_request_id,
    po_number,
    display_id,
    status,
    expected_delivery_date,
    notes,
    created_by,
    source_grn_id
  )
  VALUES (
    v_tenant,
    v_request.branch_id,
    p_supplier_id,
    p_request_id,
    v_po_number,
    v_po_number,
    'draft',
    p_expected_delivery_date,
    NULLIF(btrim(p_notes), ''),
    v_uid,
    NULL
  )
  RETURNING id INTO v_po_id;

  INSERT INTO public.purchase_order_items (
    tenant_id,
    po_id,
    purchase_request_item_id,
    ingredient_id,
    quantity,
    unit_price_est,
    line_total,
    entry_unit_id
  )
  SELECT
    v_tenant,
    v_po_id,
    request_item.id,
    request_item.ingredient_id,
    line.quantity::numeric(15,3),
    line.unit_price::numeric(15,2),
    round(line.quantity * line.unit_price, 2),
    request_item.entry_unit_id
  FROM jsonb_to_recordset(p_lines)
    AS line(
      request_item_id bigint,
      quantity numeric,
      unit_price numeric
    )
  JOIN public.purchase_request_items request_item
    ON request_item.id = line.request_item_id
   AND request_item.tenant_id = v_tenant
   AND request_item.purchase_request_id = p_request_id;

  GET DIAGNOSTICS v_line_count = ROW_COUNT;

  SELECT bool_and(
    COALESCE(ordered.quantity, 0) >= request_item.quantity
  )
  INTO v_all_ordered
  FROM public.purchase_request_items request_item
  LEFT JOIN LATERAL (
    SELECT sum(po_item.quantity) AS quantity
    FROM public.purchase_order_items po_item
    JOIN public.purchase_orders purchase_order
      ON purchase_order.id = po_item.po_id
     AND purchase_order.tenant_id = po_item.tenant_id
    WHERE po_item.tenant_id = v_tenant
      AND po_item.purchase_request_item_id = request_item.id
      AND purchase_order.status <> 'cancelled'
  ) ordered ON TRUE
  WHERE request_item.purchase_request_id = p_request_id
    AND request_item.tenant_id = v_tenant;

  UPDATE public.purchase_requests
  SET status = CASE
        WHEN COALESCE(v_all_ordered, FALSE) THEN 'ordered'
        ELSE 'partially_ordered'
      END,
      updated_at = now()
  WHERE id = p_request_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'po_id', v_po_id,
    'po_number', v_po_number,
    'status', 'draft',
    'line_count', v_line_count
  );
END;
$$;


--
-- Name: create_purchase_orders_from_grn(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_orders_from_grn(p_grn_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_grn record;
  v_supplier_id bigint;
  v_po_id bigint;
  v_location_id bigint;
  v_display text;
  v_line_count integer;
  v_total_lines integer := 0;
  v_po_count integer := 0;
  v_first_po_id bigint := NULL;
  v_by_supplier jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT grn.*
  INTO v_grn
  FROM public.goods_received_notes AS grn
  WHERE grn.id = p_grn_id
    AND grn.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_grn.branch_id, 'procurement:po_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_grn.status <> 'draft' THEN
    RAISE EXCEPTION 'grn_not_draft' USING ERRCODE = '22023';
  END IF;
  IF v_grn.po_id IS NOT NULL
     OR EXISTS (
       SELECT 1
       FROM public.purchase_orders AS po
       WHERE po.source_grn_id = p_grn_id
         AND po.tenant_id = v_tenant
     ) THEN
    RAISE EXCEPTION 'grn_already_linked_to_po' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.received_quantity - item.rejected_quantity > 0
      AND item.supplier_id IS NULL
  ) THEN
    RAISE EXCEPTION 'grn_line_supplier_required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.received_quantity - item.rejected_quantity > 0
  ) THEN
    RAISE EXCEPTION 'grn_has_no_receivable_lines' USING ERRCODE = '22023';
  END IF;

  IF NOT private.grn_physical_qc_is_valid(v_tenant, p_grn_id) THEN
    RAISE EXCEPTION 'grn_physical_qc_incomplete'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches AS branch
    WHERE branch.id = v_grn.branch_id
      AND branch.tenant_id = v_tenant
      AND branch.is_active IS TRUE
      AND branch.branch_kind IN (
        'branch',
        'central_supply',
        'central_kitchen'
      )
  ) THEN
    RAISE EXCEPTION 'invalid_branch' USING ERRCODE = 'P0002';
  END IF;

  IF v_grn.location_id IS NULL THEN
    SELECT location.id
    INTO v_location_id
    FROM public.inventory_locations AS location
    WHERE location.tenant_id = v_tenant
      AND location.branch_id = v_grn.branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE
      AND location.is_default_receive IS TRUE;
  ELSE
    SELECT location.id
    INTO v_location_id
    FROM public.inventory_locations AS location
    WHERE location.id = v_grn.location_id
      AND location.tenant_id = v_tenant
      AND location.branch_id = v_grn.branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE;
  END IF;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'grn_receiving_warehouse_required'
      USING ERRCODE = 'check_violation';
  END IF;

  FOR v_supplier_id IN
    SELECT DISTINCT item.supplier_id
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.received_quantity - item.rejected_quantity > 0
    ORDER BY item.supplier_id
  LOOP
    v_display := public.next_po_display_id(v_tenant);

    INSERT INTO public.purchase_orders (
      tenant_id,
      branch_id,
      supplier_id,
      po_number,
      display_id,
      status,
      notes,
      created_by,
      source_grn_id
    )
    VALUES (
      v_tenant,
      v_grn.branch_id,
      v_supplier_id,
      v_display,
      v_display,
      'draft',
      NULLIF(btrim(v_grn.notes), ''),
      v_uid,
      p_grn_id
    )
    RETURNING id INTO v_po_id;

    IF v_first_po_id IS NULL THEN
      v_first_po_id := v_po_id;
    END IF;

    INSERT INTO public.purchase_order_items (
      tenant_id,
      po_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      unit_price_est,
      line_total
    )
    SELECT
      v_tenant,
      v_po_id,
      item.ingredient_id,
      (
        item.received_quantity - item.rejected_quantity
      )::numeric(15,3),
      item.entry_unit_id,
      NULL::numeric,
      NULL::numeric
    FROM public.grn_items AS item
    WHERE item.grn_id = p_grn_id
      AND item.tenant_id = v_tenant
      AND item.supplier_id = v_supplier_id
      AND item.received_quantity - item.rejected_quantity > 0;

    GET DIAGNOSTICS v_line_count = ROW_COUNT;
    v_total_lines := v_total_lines + v_line_count;
    v_po_count := v_po_count + 1;

    v_by_supplier := v_by_supplier || jsonb_build_array(
      jsonb_build_object(
        'supplier_id', v_supplier_id,
        'po_id', v_po_id,
        'display_id', v_display,
        'line_count', v_line_count
      )
    );

    PERFORM public.log_audit(
      'inventory.po.created_from_grn_draft',
      'purchase_order',
      v_po_id,
      NULL,
      jsonb_build_object(
        'grn_id', p_grn_id,
        'supplier_id', v_supplier_id,
        'lines', v_line_count,
        'branch_id', v_grn.branch_id
      )
    );
  END LOOP;

  -- Legacy single pointer: first PO. Confirm gate also reads source_grn_id.
  UPDATE public.goods_received_notes
  SET po_id = v_first_po_id,
      location_id = v_location_id,
      updated_at = now()
  WHERE id = p_grn_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'grn_id', p_grn_id,
    'po_id', v_first_po_id,
    'po_ids', (
      SELECT COALESCE(jsonb_agg(po.id ORDER BY po.id), '[]'::jsonb)
      FROM public.purchase_orders AS po
      WHERE po.source_grn_id = p_grn_id
        AND po.tenant_id = v_tenant
    ),
    'po_count', v_po_count,
    'line_count', v_total_lines,
    'by_supplier', v_by_supplier,
    'status', 'draft'
  );
END;
$$;


--
-- Name: FUNCTION create_purchase_orders_from_grn(p_grn_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_purchase_orders_from_grn(p_grn_id bigint) IS 'Create one draft PO per distinct grn_items.supplier_id from a multi-supplier GRN draft. Sets purchase_orders.source_grn_id and legacy goods_received_notes.po_id to the first PO.';


--
-- Name: create_purchase_orders_from_request(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_orders_from_request(p_request_id bigint, p_orders jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF p_orders IS NULL
     OR jsonb_typeof(p_orders) <> 'array'
     OR jsonb_array_length(p_orders) = 0
     OR jsonb_array_length(p_orders) > 100 THEN
    RAISE EXCEPTION 'purchase_orders_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF (
    SELECT count(*) <> count(DISTINCT order_row.supplier_id)
    FROM jsonb_to_recordset(p_orders)
      AS order_row(supplier_id bigint)
  ) THEN
    RAISE EXCEPTION 'purchase_orders_duplicate_supplier'
      USING ERRCODE = '22023';
  END IF;

  FOR v_order IN
    SELECT value
    FROM jsonb_array_elements(p_orders)
  LOOP
    v_result := public.create_purchase_order_from_request(
      p_request_id,
      (v_order ->> 'supplier_id')::bigint,
      NULLIF(v_order ->> 'expected_delivery_date', '')::date,
      COALESCE(v_order ->> 'notes', ''),
      v_order -> 'lines'
    );
    v_results := v_results || jsonb_build_array(v_result);
  END LOOP;

  RETURN jsonb_build_object('purchase_orders', v_results);
END;
$$;


--
-- Name: create_purchase_request(bigint, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_request(p_branch_id bigint, p_needed_by date, p_notes text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request_id bigint;
  v_request_number text;
  v_line_count integer;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_branch_id IS NULL
     OR jsonb_typeof(p_lines) <> 'array'
     OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'purchase_request_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'procurement:grn_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.branches branch
    WHERE branch.id = p_branch_id
      AND branch.tenant_id = v_tenant
      AND branch.is_active
      AND branch.branch_kind IN ('central_supply', 'central_kitchen')
  ) THEN
    RAISE EXCEPTION 'purchase_request_central_site_required'
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_lines)
      AS line(ingredient_id bigint, quantity numeric, entry_unit_id bigint)
    WHERE line.ingredient_id IS NULL
       OR line.entry_unit_id IS NULL
       OR line.quantity IS NULL
       OR line.quantity <= 0
       OR NOT EXISTS (
         SELECT 1
         FROM public.ingredients ingredient
         JOIN public.ingredient_units ingredient_unit
           ON ingredient_unit.ingredient_id = ingredient.id
          AND ingredient_unit.tenant_id = ingredient.tenant_id
         WHERE ingredient.id = line.ingredient_id
           AND ingredient.tenant_id = v_tenant
           AND ingredient.is_active
           AND ingredient_unit.unit_id = line.entry_unit_id
           AND ingredient_unit.is_active
       )
  ) THEN
    RAISE EXCEPTION 'purchase_request_line_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_request_number :=
    public.next_inventory_doc_number(v_tenant, 'purchase_request');

  INSERT INTO public.purchase_requests (
    tenant_id,
    branch_id,
    request_number,
    status,
    needed_by,
    notes,
    created_by
  )
  VALUES (
    v_tenant,
    p_branch_id,
    v_request_number,
    'draft',
    p_needed_by,
    NULLIF(btrim(p_notes), ''),
    v_uid
  )
  RETURNING id INTO v_request_id;

  INSERT INTO public.purchase_request_items (
    tenant_id,
    purchase_request_id,
    ingredient_id,
    quantity,
    entry_unit_id,
    notes
  )
  SELECT
    v_tenant,
    v_request_id,
    line.ingredient_id,
    line.quantity::numeric(15,3),
    line.entry_unit_id,
    NULLIF(btrim(line.notes), '')
  FROM jsonb_to_recordset(p_lines)
    AS line(
      ingredient_id bigint,
      quantity numeric,
      entry_unit_id bigint,
      notes text
    );

  GET DIAGNOSTICS v_line_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'request_id', v_request_id,
    'request_number', v_request_number,
    'status', 'draft',
    'line_count', v_line_count
  );
END;
$$;


--
-- Name: create_refund(bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_refund(p_payment_id bigint, p_amount numeric, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor     UUID   := auth.uid();
  v_tenant    BIGINT := public.auth_tenant_id();
  v_payment   RECORD;
  v_refund_id BIGINT;
  v_already   NUMERIC(15,2) := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid amount' USING ERRCODE = 'P0001';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;
  IF length(p_reason) > 500 THEN
    RAISE EXCEPTION 'reason exceeds 500 chars' USING ERRCODE = '22023';
  END IF;

  SELECT id, tenant_id, branch_id, order_id, amount, status, method
  INTO v_payment
  FROM public.payments
  WHERE id = p_payment_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment % not found', p_payment_id
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_payment.branch_id, 'orders:refund') THEN
    RAISE EXCEPTION 'permission denied: orders:refund required'
      USING ERRCODE = '42501';
  END IF;

  IF v_payment.status <> 'completed' THEN
    RAISE EXCEPTION 'payment_not_completed: status=%', v_payment.status
      USING ERRCODE = 'P0001';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_already
  FROM public.refunds
  WHERE payment_id = v_payment.id
    AND status IN ('pending', 'approved');

  IF v_already + p_amount > v_payment.amount THEN
    RAISE EXCEPTION 'refund_exceeds_remaining: already=%, requested=%, payment=%',
      v_already, p_amount, v_payment.amount USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.refunds
    (tenant_id, branch_id, payment_id, order_id, amount, reason, status, created_by)
  VALUES
    (v_payment.tenant_id, v_payment.branch_id, v_payment.id, v_payment.order_id,
     p_amount, p_reason, 'pending', v_actor)
  RETURNING id INTO v_refund_id;

  PERFORM public.log_audit(
    'refund.create',
    'refund',
    v_refund_id,
    NULL,
    jsonb_build_object(
      'payment_id', v_payment.id,
      'order_id',   v_payment.order_id,
      'amount',     p_amount,
      'method',     v_payment.method
    )
  );

  RETURN jsonb_build_object(
    'status',    'created',
    'refund_id', v_refund_id
  );
END;
$$;


--
-- Name: FUNCTION create_refund(p_payment_id bigint, p_amount numeric, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_refund(p_payment_id bigint, p_amount numeric, p_reason text) IS 'Creates pending refunds with branch-scoped orders:refund permission, completed-payment precondition, cumulative refund cap, and audit logging.';


--
-- Name: create_refund_with_payout(bigint, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_refund_with_payout(p_payment_id bigint, p_amount numeric, p_reason text, p_payout_method text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_result jsonb;
  v_refund_id bigint;
  v_payment_amount numeric;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_payout_method IS NULL
    OR p_payout_method NOT IN ('cash', 'bank_transfer')
  THEN
    RAISE EXCEPTION 'refund_payout_method_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT payment.amount
  INTO v_payment_amount
  FROM public.payments payment
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_amount <> v_payment_amount THEN
    RAISE EXCEPTION 'partial_refund_not_supported' USING ERRCODE = '23514';
  END IF;

  v_result := public.create_refund(p_payment_id, p_amount, p_reason);
  v_refund_id := NULLIF(v_result->>'refund_id', '')::bigint;

  UPDATE public.refunds
  SET payout_method = p_payout_method,
      updated_at = now()
  WHERE id = v_refund_id
    AND tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'refund_not_found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.log_audit(
    'refund.payout_method_set',
    'refund',
    v_refund_id,
    NULL,
    jsonb_build_object('payout_method', p_payout_method)
  );

  RETURN v_result || jsonb_build_object('payout_method', p_payout_method);
END;
$$;


--
-- Name: create_remote_payment_intent(bigint, bigint, bigint, text, numeric, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_remote_payment_intent(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_method text, p_amount numeric, p_created_by uuid, p_provider_ref text, p_provider_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order public.orders%ROWTYPE;
  v_payment_id bigint;
  v_existing_payment_id bigint;
  v_existing_status text;
  v_existing_method text;
  v_existing_amount numeric;
  v_existing_provider_ref text;
  v_existing_provider_data jsonb;
  v_requested_provider_ref text;
  v_requested_provider_data jsonb;
  v_line_subtotal numeric(15,2) := 0;
  v_recomputed_total numeric(15,2) := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles profile
    WHERE profile.id = p_created_by
      AND profile.tenant_id = p_tenant_id
      AND COALESCE(profile.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'actor_inactive_or_tenant_mismatch'
      USING ERRCODE = '42501';
  END IF;

  IF NOT public.auth_is_owner(p_created_by)
    AND NOT EXISTS (
      SELECT 1
      FROM public.staff_permissions permission
      WHERE permission.user_id = p_created_by
        AND permission.tenant_id = p_tenant_id
        AND permission.permission_key = 'pos:use'
        AND (
          permission.branch_id = p_branch_id
          OR permission.branch_id IS NULL
        )
        AND permission.valid_from <= now()
        AND (
          permission.valid_until IS NULL
          OR permission.valid_until > now()
        )
    )
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_method <> 'vietqr' THEN
    RAISE EXCEPTION 'remote_payment_method_required' USING ERRCODE = '22023';
  END IF;

  v_requested_provider_ref := NULLIF(btrim(p_provider_ref), '');
  IF v_requested_provider_ref IS NULL THEN
    RAISE EXCEPTION 'remote_payment_provider_ref_required' USING ERRCODE = '22023';
  END IF;

  IF p_provider_data IS NULL OR jsonb_typeof(p_provider_data) <> 'object' THEN
    RAISE EXCEPTION 'provider_data_must_be_object' USING ERRCODE = '22023';
  END IF;
  IF p_provider_data ?| ARRAY[
    'bankWebhookReview',
    'source',
    'invoicePayload'
  ] THEN
    RAISE EXCEPTION 'provider_data_contains_reserved_key'
      USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(p_provider_data ->> 'providerRef'), '')
    IS DISTINCT FROM v_requested_provider_ref
  THEN
    RAISE EXCEPTION 'provider_data_ref_mismatch' USING ERRCODE = '23514';
  END IF;
  v_requested_provider_data := p_provider_data;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT order_row.*
  INTO v_order
  FROM public.orders order_row
  WHERE order_row.id = p_order_id
    AND order_row.tenant_id = p_tenant_id
    AND order_row.branch_id = p_branch_id
  FOR UPDATE NOWAIT;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.payment_status = 'paid' THEN
    RAISE EXCEPTION 'order_already_paid' USING ERRCODE = 'P0001';
  END IF;

  SELECT COALESCE(
    SUM(order_item.quantity::numeric * order_item.unit_price),
    0
  )::numeric(15,2)
  INTO v_line_subtotal
  FROM public.order_items order_item
  WHERE order_item.order_id = v_order.id
    AND order_item.tenant_id = v_order.tenant_id
    AND order_item.status <> 'cancelled';

  v_recomputed_total := ROUND(
    v_line_subtotal
    + COALESCE(v_order.tax_amount, 0)
    + COALESCE(v_order.service_charge, 0)
    - COALESCE(v_order.discount_amount, 0),
    2
  );

  IF ABS(p_amount - v_recomputed_total) > 1
    OR ABS(v_order.total_amount - v_recomputed_total) > 1
  THEN
    RAISE EXCEPTION 'amount_mismatch_recomputed: stored=% expected=% recomputed=%',
      v_order.total_amount,
      p_amount,
      v_recomputed_total
      USING ERRCODE = '23514';
  END IF;

  IF p_amount <> v_order.total_amount THEN
    RAISE EXCEPTION 'amount_mismatch: expected % got %',
      v_order.total_amount,
      p_amount
      USING ERRCODE = '22023';
  END IF;

  IF p_method = 'vietqr' THEN
    IF NULLIF(btrim(v_order.payment_code), '') IS NULL THEN
      RAISE EXCEPTION 'order_payment_code_required' USING ERRCODE = '23514';
    END IF;
    IF lower(v_requested_provider_ref)
      IS DISTINCT FROM lower(btrim(v_order.payment_code))
    THEN
      RAISE EXCEPTION 'vietqr_provider_ref_mismatch'
        USING ERRCODE = '23514';
    END IF;
    v_requested_provider_ref := btrim(v_order.payment_code);
    v_requested_provider_data := jsonb_set(
      v_requested_provider_data,
      '{providerRef}',
      to_jsonb(v_requested_provider_ref),
      true
    );
  END IF;

  SELECT
    payment.id,
    payment.status,
    payment.method,
    payment.amount,
    payment.provider_ref,
    payment.provider_data
  INTO
    v_existing_payment_id,
    v_existing_status,
    v_existing_method,
    v_existing_amount,
    v_existing_provider_ref,
    v_existing_provider_data
  FROM public.payments payment
  WHERE payment.tenant_id = p_tenant_id
    AND payment.branch_id = p_branch_id
    AND payment.order_id = p_order_id
    AND payment.status <> 'failed'
  ORDER BY payment.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_status = 'completed' THEN
    RAISE EXCEPTION 'payment_already_completed' USING ERRCODE = 'P0001';
  ELSIF v_existing_status = 'pending' THEN
    IF v_existing_method IS DISTINCT FROM p_method THEN
      RAISE EXCEPTION 'payment_pending_different_method: existing=% requested=%',
        v_existing_method,
        p_method
        USING ERRCODE = '23505';
    END IF;

    IF v_existing_amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'payment_pending_amount_mismatch'
        USING ERRCODE = '23514';
    END IF;

    IF COALESCE(v_existing_provider_data ->> 'source', '') = 'qr_self_order'
      OR EXISTS (
        SELECT 1
        FROM public.self_order_payment_requests request
        WHERE request.tenant_id = p_tenant_id
          AND request.payment_id = v_existing_payment_id
          AND request.status IN ('cash_call', 'vietqr_pending')
      )
    THEN
      RAISE EXCEPTION 'self_order_payment_owned' USING ERRCODE = '55P03';
    END IF;

    IF (
        v_existing_provider_ref IS DISTINCT FROM v_requested_provider_ref
        OR jsonb_typeof(v_existing_provider_data) IS DISTINCT FROM 'object'
        OR NULLIF(btrim(v_existing_provider_data ->> 'providerRef'), '')
          IS DISTINCT FROM v_requested_provider_ref
      )
    THEN
      UPDATE public.payments
      SET provider_ref = v_requested_provider_ref,
          provider_data = v_requested_provider_data,
          updated_at = now()
      WHERE id = v_existing_payment_id
      RETURNING id INTO v_payment_id;
      v_existing_provider_ref := v_requested_provider_ref;
      v_existing_provider_data := v_requested_provider_data;
    ELSE
      v_payment_id := v_existing_payment_id;
    END IF;
  ELSIF v_existing_payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'payment_not_pending: status=%', v_existing_status
      USING ERRCODE = '22023';
  ELSE
    INSERT INTO public.payments (
      tenant_id,
      branch_id,
      order_id,
      method,
      amount,
      status,
      provider_ref,
      provider_data,
      paid_at,
      created_by
    ) VALUES (
      p_tenant_id,
      p_branch_id,
      p_order_id,
      p_method,
      p_amount,
      'pending',
      v_requested_provider_ref,
      v_requested_provider_data,
      NULL,
      p_created_by
    )
    RETURNING id INTO v_payment_id;
  END IF;

  UPDATE public.orders
  SET payment_method = p_method,
      updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'payment_id', v_payment_id,
    'status', 'pending',
    'idempotent', COALESCE(v_existing_status = 'pending', false),
    'provider_ref', COALESCE(v_existing_provider_ref, v_requested_provider_ref)
  );
END;
$$;


--
-- Name: FUNCTION create_remote_payment_intent(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_method text, p_amount numeric, p_created_by uuid, p_provider_ref text, p_provider_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_remote_payment_intent(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_method text, p_amount numeric, p_created_by uuid, p_provider_ref text, p_provider_data jsonb) IS 'Service-only atomic creation or reuse of a pending VietQR intent with trusted provider metadata and an explicitly authorized POS actor.';


--
-- Name: create_stock_request_draft(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_request_draft(p_branch_id bigint, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_kind text;
  v_id bigint;
  v_number text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT branch.branch_kind INTO v_kind
  FROM public.branches AS branch
  WHERE branch.id = p_branch_id
    AND branch.tenant_id = v_tenant
    AND branch.is_active IS TRUE;

  IF v_kind IS DISTINCT FROM 'branch' THEN
    RAISE EXCEPTION 'stock_request_branch_site_only'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission(p_branch_id, 'inventory:request_create')
  THEN
    RAISE EXCEPTION 'forbidden_request_create' USING ERRCODE = '42501';
  END IF;

  v_number := public.next_inventory_doc_number(v_tenant, 'stock_request');

  INSERT INTO public.stock_requests (
    tenant_id, branch_id, request_number, status, notes, created_by
  )
  VALUES (
    v_tenant, p_branch_id, v_number, 'draft', p_notes, v_uid
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'request_id', v_id,
    'request_number', v_number
  );
END;
$$;


--
-- Name: create_stock_transfer_draft(bigint, bigint, text, text, text, jsonb, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_transfer_draft(p_from_branch_id bigint, p_to_branch_id bigint, p_transfer_number text, p_notes text DEFAULT NULL::text, p_vehicle_info text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb, p_from_location_id bigint DEFAULT NULL::bigint, p_to_location_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_transfer_id bigint;
  v_from_kind text;
  v_to_kind text;
  v_line jsonb;
  v_ingredient_id bigint;
  v_entry_unit_id bigint;
  v_entry_quantity numeric(15,3);
  v_transfer_number text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_from_branch_id = p_to_branch_id THEN
    RAISE EXCEPTION 'transfer_requires_distinct_branches'
      USING ERRCODE = '22023';
  END IF;
  IF p_from_location_id IS NULL OR p_to_location_id IS NULL THEN
    RAISE EXCEPTION 'transfer_warehouse_locations_required'
      USING ERRCODE = 'not_null_violation';
  END IF;

  PERFORM branch.id
  FROM public.branches AS branch
  WHERE branch.id = ANY(ARRAY[
    p_from_branch_id,
    p_to_branch_id
  ]::bigint[])
  ORDER BY branch.id
  FOR UPDATE OF branch;

  SELECT branch.branch_kind
  INTO v_from_kind
  FROM public.branches AS branch
  WHERE branch.id = p_from_branch_id
    AND branch.tenant_id = v_tenant
    AND branch.is_active IS TRUE
    AND branch.branch_kind IN (
      'branch',
      'central_supply',
      'central_kitchen'
    );

  SELECT branch.branch_kind
  INTO v_to_kind
  FROM public.branches AS branch
  WHERE branch.id = p_to_branch_id
    AND branch.tenant_id = v_tenant
    AND branch.is_active IS TRUE
    AND branch.branch_kind IN (
      'branch',
      'central_supply',
      'central_kitchen'
    );

  IF v_from_kind IS NULL OR v_to_kind IS NULL THEN
    RAISE EXCEPTION 'transfer_branch_invalid'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations AS location
    WHERE location.id = p_from_location_id
      AND location.tenant_id = v_tenant
      AND location.branch_id = p_from_branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE
  ) OR NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations AS location
    WHERE location.id = p_to_location_id
      AND location.tenant_id = v_tenant
      AND location.branch_id = p_to_branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'transfer_warehouse_location_invalid'
      USING ERRCODE = 'check_violation';
  END IF;

  -- D093: transfer_create on from-site (owner + central ops), not owner-only role.
  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission(
       p_from_branch_id,
       'inventory:transfer_create'
     ) THEN
    RAISE EXCEPTION 'forbidden_transfer_create'
      USING ERRCODE = '42501';
  END IF;

  IF p_lines IS NULL
     OR jsonb_typeof(p_lines) <> 'array'
     OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'transfer_lines_invalid' USING ERRCODE = '22023';
  END IF;

  v_transfer_number := public.next_inventory_doc_number(
    v_tenant,
    'transfer'
  );

  INSERT INTO public.stock_transfers (
    tenant_id,
    from_branch_id,
    to_branch_id,
    from_location_id,
    to_location_id,
    transfer_number,
    status,
    notes,
    vehicle_info,
    created_by
  )
  VALUES (
    v_tenant,
    p_from_branch_id,
    p_to_branch_id,
    p_from_location_id,
    p_to_location_id,
    v_transfer_number,
    'draft',
    p_notes,
    p_vehicle_info,
    v_uid
  )
  RETURNING id INTO v_transfer_id;

  FOR v_line IN
    SELECT value
    FROM jsonb_array_elements(p_lines) AS line(value)
  LOOP
    v_ingredient_id := NULLIF(
      coalesce(
        v_line ->> 'ingredientId',
        v_line ->> 'ingredient_id'
      ),
      ''
    )::bigint;
    v_entry_quantity := NULLIF(
      v_line ->> 'quantity',
      ''
    )::numeric(15,3);
    v_entry_unit_id := NULLIF(
      coalesce(
        v_line ->> 'entryUnitId',
        v_line ->> 'entry_unit_id'
      ),
      ''
    )::bigint;

    IF v_ingredient_id IS NULL
       OR v_entry_quantity IS NULL
       OR v_entry_quantity <= 0
       OR v_entry_quantity = 'NaN'::numeric
       OR v_entry_quantity = 'Infinity'::numeric
       OR v_entry_quantity = '-Infinity'::numeric THEN
      RAISE EXCEPTION 'transfer_lines_invalid'
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.ingredients AS ingredient
      WHERE ingredient.id = v_ingredient_id
        AND ingredient.tenant_id = v_tenant
        AND ingredient.is_active IS TRUE
    ) THEN
      RAISE EXCEPTION 'transfer_ingredient_invalid:%',
        v_ingredient_id
        USING ERRCODE = 'check_violation';
    END IF;

    IF v_entry_unit_id IS NULL THEN
      SELECT ingredient_unit.unit_id
      INTO v_entry_unit_id
      FROM public.ingredient_units AS ingredient_unit
      JOIN public.units AS unit
        ON unit.id = ingredient_unit.unit_id
       AND unit.tenant_id = ingredient_unit.tenant_id
       AND unit.is_active IS TRUE
      WHERE ingredient_unit.tenant_id = v_tenant
        AND ingredient_unit.ingredient_id = v_ingredient_id
        AND ingredient_unit.is_base IS TRUE
        AND ingredient_unit.is_active IS TRUE
      ORDER BY ingredient_unit.sort_order, ingredient_unit.id
      LIMIT 1;
    ELSIF NOT EXISTS (
      SELECT 1
      FROM public.ingredient_units AS ingredient_unit
      JOIN public.units AS unit
        ON unit.id = ingredient_unit.unit_id
       AND unit.tenant_id = ingredient_unit.tenant_id
       AND unit.is_active IS TRUE
      WHERE ingredient_unit.tenant_id = v_tenant
        AND ingredient_unit.ingredient_id = v_ingredient_id
        AND ingredient_unit.unit_id = v_entry_unit_id
        AND ingredient_unit.is_active IS TRUE
    ) THEN
      RAISE EXCEPTION 'entry_unit_not_found:%',
        v_ingredient_id
        USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_entry_unit_id IS NULL THEN
      RAISE EXCEPTION 'entry_unit_not_found:%',
        v_ingredient_id
        USING ERRCODE = 'foreign_key_violation';
    END IF;

    INSERT INTO public.stock_transfer_items (
      tenant_id,
      transfer_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      unit_cost_at_ship
    )
    VALUES (
      v_tenant,
      v_transfer_id,
      v_ingredient_id,
      v_entry_quantity,
      v_entry_unit_id,
      (
        SELECT stock.avg_unit_cost
        FROM public.stock_levels AS stock
        WHERE stock.tenant_id = v_tenant
          AND stock.branch_id = p_from_branch_id
          AND stock.location_id = p_from_location_id
          AND stock.ingredient_id = v_ingredient_id
        LIMIT 1
      )
    )
    ON CONFLICT (transfer_id, ingredient_id, tenant_id)
    DO UPDATE SET
      quantity = EXCLUDED.quantity,
      entry_unit_id = EXCLUDED.entry_unit_id,
      unit_cost_at_ship = EXCLUDED.unit_cost_at_ship;
  END LOOP;

  RETURN jsonb_build_object(
    'id', v_transfer_id,
    'status', 'draft',
    'transfer_number', v_transfer_number
  );
END;
$$;


--
-- Name: create_stocktake_session(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stocktake_session(p_branch_id bigint, p_location_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_session_id bigint;
  v_location_id bigint;
  v_session_number text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  PERFORM 1
  FROM public.branches AS branch
  WHERE branch.id = p_branch_id
    AND branch.tenant_id = v_tenant
    AND branch.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    p_branch_id,
    'inventory:stocktake_create'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT location.id
  INTO v_location_id
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = v_tenant
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE
    AND (
      p_location_id IS NULL
      OR location.id = p_location_id
    )
  ORDER BY
    location.is_default_consumption DESC,
    location.sort_order NULLS LAST,
    location.id
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'location_not_found_or_inactive'
      USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = p_branch_id
      AND stock.location_id = v_location_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.ingredient_units AS ingredient_unit
        JOIN public.units AS unit
          ON unit.id = ingredient_unit.unit_id
         AND unit.tenant_id = ingredient_unit.tenant_id
         AND unit.is_active IS TRUE
        WHERE ingredient_unit.tenant_id = v_tenant
          AND ingredient_unit.ingredient_id = stock.ingredient_id
          AND ingredient_unit.is_base IS TRUE
          AND ingredient_unit.is_active IS TRUE
      )
  ) THEN
    RAISE EXCEPTION 'stocktake_entry_unit_missing'
      USING ERRCODE = '23503';
  END IF;

  v_session_number := public.next_inventory_doc_number(
    v_tenant,
    'stocktake'
  );

  INSERT INTO public.stocktake_sessions (
    tenant_id,
    branch_id,
    location_id,
    created_by,
    session_number
  )
  VALUES (
    v_tenant,
    p_branch_id,
    v_location_id,
    v_uid,
    v_session_number
  )
  RETURNING id INTO v_session_id;

  INSERT INTO public.stocktake_lines (
    tenant_id,
    session_id,
    ingredient_id,
    system_quantity,
    entry_unit_id
  )
  SELECT
    v_tenant,
    v_session_id,
    stock.ingredient_id,
    stock.current_quantity,
    base_unit.unit_id
  FROM public.stock_levels AS stock
  JOIN LATERAL (
    SELECT ingredient_unit.unit_id
    FROM public.ingredient_units AS ingredient_unit
    JOIN public.units AS unit
      ON unit.id = ingredient_unit.unit_id
     AND unit.tenant_id = ingredient_unit.tenant_id
     AND unit.is_active IS TRUE
    WHERE ingredient_unit.tenant_id = v_tenant
      AND ingredient_unit.ingredient_id = stock.ingredient_id
      AND ingredient_unit.is_base IS TRUE
      AND ingredient_unit.is_active IS TRUE
    ORDER BY ingredient_unit.sort_order, ingredient_unit.id
    LIMIT 1
  ) AS base_unit ON TRUE
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = p_branch_id
    AND stock.location_id = v_location_id;

  RETURN jsonb_build_object(
    'id',
    v_session_id,
    'session_number',
    v_session_number
  );
END;
$$;


--
-- Name: FUNCTION create_stocktake_session(p_branch_id bigint, p_location_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_stocktake_session(p_branch_id bigint, p_location_id bigint) IS 'Creates a stocktake only at the authenticated tenant site active warehouse.';


--
-- Name: create_supplier_credit_allocated(bigint, text, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_credit_allocated(p_supplier_id bigint, p_credit_number text, p_amount numeric, p_notes text, p_allocations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_credit_id bigint;
  v_allocated numeric(15,2);
  v_single_invoice_id bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_match') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_amount IS NULL
     OR p_amount <= 0
     OR p_amount <> round(p_amount, 2)
     OR btrim(p_credit_number) = ''
     OR jsonb_typeof(p_allocations) <> 'array' THEN
    RAISE EXCEPTION 'supplier_credit_invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.suppliers supplier
    WHERE supplier.id = p_supplier_id
      AND supplier.tenant_id = v_tenant
  ) THEN
    RAISE EXCEPTION 'supplier_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF (
    SELECT count(DISTINCT (allocation.value->>'invoice_id')::bigint)
    FROM jsonb_array_elements(p_allocations) allocation
  ) <> jsonb_array_length(p_allocations) THEN
    RAISE EXCEPTION 'supplier_credit_invoice_duplicate'
      USING ERRCODE = '23505';
  END IF;

  SELECT COALESCE(sum((allocation.value->>'amount')::numeric), 0)
  INTO v_allocated
  FROM jsonb_array_elements(p_allocations) allocation;

  PERFORM 1
  FROM public.supplier_invoices invoice
  JOIN jsonb_array_elements(p_allocations) allocation
    ON invoice.id = (allocation.value->>'invoice_id')::bigint
  WHERE invoice.tenant_id = v_tenant
  ORDER BY invoice.id
  FOR UPDATE OF invoice;

  IF v_allocated > p_amount
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_allocations) allocation
       LEFT JOIN public.supplier_invoices invoice
         ON invoice.id = (allocation.value->>'invoice_id')::bigint
        AND invoice.tenant_id = v_tenant
       WHERE invoice.id IS NULL
          OR invoice.supplier_id IS DISTINCT FROM p_supplier_id
          OR (allocation.value->>'amount')::numeric <= 0
          OR (allocation.value->>'amount')::numeric >
            invoice.total_amount
              - invoice.paid_amount
              - invoice.credit_applied_amount
     ) THEN
    RAISE EXCEPTION 'supplier_credit_allocation_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN jsonb_array_length(p_allocations) = 1
    THEN (p_allocations->0->>'invoice_id')::bigint
    ELSE NULL
  END
  INTO v_single_invoice_id;

  INSERT INTO public.supplier_credit_notes (
    tenant_id,
    supplier_id,
    return_id,
    invoice_id,
    credit_number,
    kind,
    amount,
    status,
    applied_amount,
    notes,
    created_by,
    applied_at
  )
  VALUES (
    v_tenant,
    p_supplier_id,
    NULL,
    v_single_invoice_id,
    btrim(p_credit_number),
    'credit_note',
    p_amount,
    CASE WHEN v_allocated = p_amount THEN 'applied' ELSE 'open' END,
    v_allocated,
    NULLIF(btrim(p_notes), ''),
    v_uid,
    CASE WHEN v_allocated > 0 THEN now() ELSE NULL END
  )
  RETURNING id INTO v_credit_id;

  INSERT INTO public.supplier_credit_allocations (
    tenant_id,
    supplier_credit_note_id,
    supplier_invoice_id,
    amount
  )
  SELECT
    v_tenant,
    v_credit_id,
    (allocation.value->>'invoice_id')::bigint,
    (allocation.value->>'amount')::numeric(15,2)
  FROM jsonb_array_elements(p_allocations) allocation;

  WITH allocated AS (
    SELECT
      (allocation.value->>'invoice_id')::bigint AS invoice_id,
      sum((allocation.value->>'amount')::numeric(15,2)) AS amount
    FROM jsonb_array_elements(p_allocations) allocation
    GROUP BY (allocation.value->>'invoice_id')::bigint
  )
  UPDATE public.supplier_invoices invoice
  SET credit_applied_amount =
        invoice.credit_applied_amount + allocated.amount,
      payment_status = CASE
        WHEN invoice.paid_amount
           + invoice.credit_applied_amount
           + allocated.amount
             >= invoice.total_amount THEN 'paid'
        WHEN invoice.paid_amount > 0 THEN 'partial'
        ELSE invoice.payment_status
      END,
      updated_at = now()
  FROM allocated
  WHERE invoice.id = allocated.invoice_id
    AND invoice.tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'credit_id', v_credit_id,
    'unallocated_amount', p_amount - v_allocated
  );
END;
$$;


--
-- Name: create_supplier_invoice_with_allocations(bigint, text, date, jsonb, text, date, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_invoice_with_allocations(p_supplier_id bigint, p_invoice_number text, p_invoice_date date, p_vat_breakdown jsonb, p_matching_notes text, p_due_date date, p_document_discount_amount numeric, p_receipts jsonb) RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT public.create_supplier_invoice_with_allocations(
    p_supplier_id,
    p_invoice_number,
    p_invoice_date,
    p_vat_breakdown,
    p_matching_notes,
    p_due_date,
    p_document_discount_amount,
    p_receipts,
    'goods'
  );
$$;


--
-- Name: create_supplier_invoice_with_allocations(bigint, text, date, jsonb, text, date, numeric, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_invoice_with_allocations(p_supplier_id bigint, p_invoice_number text, p_invoice_date date, p_vat_breakdown jsonb, p_matching_notes text, p_due_date date, p_document_discount_amount numeric, p_receipts jsonb, p_invoice_kind text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_receipt_count integer := COALESCE(
    pg_catalog.jsonb_array_length(p_receipts),
    0
  );
  v_first_receipt jsonb;
  v_invoice_id bigint;
  v_bucket jsonb;
  v_bucket_index integer := 0;
  v_bucket_count integer := COALESCE(
    pg_catalog.jsonb_array_length(p_vat_breakdown),
    0
  );
  v_taxable_total numeric(15,2);
  v_bucket_taxable numeric(15,2);
  v_discount numeric(15,2) :=
    COALESCE(p_document_discount_amount, 0)::numeric(15,2);
  v_allocated_discount numeric(15,2);
  v_remaining_discount numeric(15,2);
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_invoice_kind NOT IN ('goods', 'service')
     OR pg_catalog.jsonb_typeof(p_receipts) <> 'array'
     OR pg_catalog.jsonb_typeof(p_vat_breakdown) <> 'array'
     OR v_bucket_count = 0
     OR v_discount < 0 THEN
    RAISE EXCEPTION 'supplier_invoice_allocations_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF p_invoice_kind = 'goods' AND v_receipt_count = 0 THEN
    RAISE EXCEPTION 'goods_invoice_receipts_required'
      USING ERRCODE = '23514';
  END IF;
  IF p_invoice_kind = 'service' AND v_receipt_count <> 0 THEN
    RAISE EXCEPTION 'service_invoice_receipts_forbidden'
      USING ERRCODE = '23514';
  END IF;

  IF v_receipt_count > 0 AND (
    SELECT count(DISTINCT (receipt.value->>'grn_id')::bigint)
    FROM pg_catalog.jsonb_array_elements(p_receipts) receipt
  ) <> v_receipt_count THEN
    RAISE EXCEPTION 'supplier_invoice_receipt_duplicate'
      USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_array_elements(p_receipts) receipt
    LEFT JOIN public.goods_received_notes grn
      ON grn.id = (receipt.value->>'grn_id')::bigint
     AND grn.tenant_id = v_tenant
    LEFT JOIN public.purchase_orders purchase_order
      ON purchase_order.id = (receipt.value->>'po_id')::bigint
     AND purchase_order.tenant_id = v_tenant
    WHERE grn.id IS NULL
       OR grn.status <> 'confirmed'
       OR grn.po_id IS DISTINCT FROM purchase_order.id
       OR purchase_order.supplier_id IS DISTINCT FROM p_supplier_id
  ) THEN
    RAISE EXCEPTION 'supplier_invoice_receipt_mismatch'
      USING ERRCODE = '23514';
  END IF;

  v_first_receipt := p_receipts->0;
  v_invoice_id := public.create_supplier_invoice_with_vat_breakdown(
    p_supplier_id,
    CASE
      WHEN v_first_receipt IS NULL THEN NULL
      ELSE (v_first_receipt->>'grn_id')::bigint
    END,
    CASE
      WHEN v_first_receipt IS NULL THEN NULL
      ELSE (v_first_receipt->>'po_id')::bigint
    END,
    p_invoice_number,
    p_invoice_date,
    p_vat_breakdown,
    p_matching_notes,
    p_due_date
  );

  SELECT COALESCE(
    sum((bucket.value->>'taxable_amount')::numeric),
    0
  )
  INTO v_taxable_total
  FROM pg_catalog.jsonb_array_elements(p_vat_breakdown) bucket;

  IF v_taxable_total <= 0 THEN
    RAISE EXCEPTION 'supplier_invoice_vat_breakdown_invalid'
      USING ERRCODE = '23514';
  END IF;

  v_remaining_discount := v_discount;
  FOR v_bucket IN
    SELECT bucket.value
    FROM pg_catalog.jsonb_array_elements(p_vat_breakdown)
      WITH ORDINALITY bucket(value, ord)
    ORDER BY bucket.ord
  LOOP
    v_bucket_index := v_bucket_index + 1;
    v_bucket_taxable :=
      (v_bucket->>'taxable_amount')::numeric(15,2);
    v_allocated_discount := CASE
      WHEN v_bucket_index = v_bucket_count THEN v_remaining_discount
      ELSE pg_catalog.round(
        v_discount * v_bucket_taxable / v_taxable_total,
        2
      )
    END;
    v_remaining_discount := v_remaining_discount - v_allocated_discount;

    INSERT INTO public.supplier_invoice_lines (
      tenant_id,
      supplier_invoice_id,
      description,
      quantity,
      unit_price,
      line_discount_amount,
      allocated_document_discount,
      line_total
    )
    VALUES (
      v_tenant,
      v_invoice_id,
      'Thuế suất ' || (v_bucket->>'vat_rate') || '%',
      1,
      v_bucket_taxable + v_allocated_discount,
      0,
      v_allocated_discount,
      v_bucket_taxable
    );
  END LOOP;

  UPDATE public.supplier_invoices
  SET invoice_kind = p_invoice_kind,
      document_discount_amount = v_discount,
      updated_at = pg_catalog.now()
  WHERE id = v_invoice_id
    AND tenant_id = v_tenant;

  INSERT INTO public.supplier_invoice_receipt_allocations (
    tenant_id,
    supplier_invoice_id,
    grn_id,
    po_id,
    billed_quantity,
    matched_quantity
  )
  SELECT
    v_tenant,
    v_invoice_id,
    (receipt.value->>'grn_id')::bigint,
    (receipt.value->>'po_id')::bigint,
    0,
    0
  FROM pg_catalog.jsonb_array_elements(p_receipts) receipt;

  v_result := private.apply_supplier_invoice_matching(v_invoice_id);

  PERFORM public.log_audit(
    'supplier_invoice.created',
    'supplier_invoice',
    v_invoice_id,
    NULL,
    v_result || pg_catalog.jsonb_build_object(
      'invoice_kind', p_invoice_kind,
      'supplier_id', p_supplier_id,
      'receipt_count', v_receipt_count
    )
  );

  RETURN v_invoice_id;
END;
$$;


--
-- Name: create_supplier_invoice_with_vat_breakdown(bigint, bigint, bigint, text, date, jsonb, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_invoice_with_vat_breakdown(p_supplier_id bigint, p_grn_id bigint, p_po_id bigint, p_invoice_number text, p_invoice_date date, p_vat_breakdown jsonb, p_matching_notes text, p_due_date date) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_user_id uuid := auth.uid();
  v_payment_terms_days integer;
  v_effective_po_id bigint := p_po_id;
  v_due_date date := p_due_date;
  v_grn record;
  v_invoice_id bigint;
  v_supplier_ok boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT payment_terms_days
  INTO v_payment_terms_days
  FROM public.suppliers
  WHERE id = p_supplier_id
    AND tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_grn_id IS NOT NULL THEN
    SELECT id, supplier_id, po_id, status
    INTO v_grn
    FROM public.goods_received_notes
    WHERE id = p_grn_id
      AND tenant_id = v_tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_grn.status <> 'confirmed' THEN
      RAISE EXCEPTION 'grn_not_confirmed' USING ERRCODE = '22023';
    END IF;

    v_supplier_ok := (
      v_grn.supplier_id IS NOT DISTINCT FROM p_supplier_id
      OR (
        v_grn.supplier_id IS NULL
        AND EXISTS (
          SELECT 1
          FROM public.grn_items gi
          WHERE gi.grn_id = p_grn_id
            AND gi.tenant_id = v_tenant_id
            AND gi.supplier_id = p_supplier_id
        )
      )
    );
    IF NOT v_supplier_ok THEN
      RAISE EXCEPTION 'grn_supplier_mismatch' USING ERRCODE = '22023';
    END IF;

    IF p_po_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.purchase_orders po
        WHERE po.id = p_po_id
          AND po.tenant_id = v_tenant_id
          AND po.supplier_id = p_supplier_id
          AND (
            po.id IS NOT DISTINCT FROM v_grn.po_id
            OR po.source_grn_id = p_grn_id
          )
      ) THEN
        RAISE EXCEPTION 'po_grn_mismatch' USING ERRCODE = '22023';
      END IF;
      v_effective_po_id := p_po_id;
    ELSE
      SELECT po.id
      INTO v_effective_po_id
      FROM public.purchase_orders po
      WHERE po.tenant_id = v_tenant_id
        AND po.supplier_id = p_supplier_id
        AND po.source_grn_id = p_grn_id
      ORDER BY po.id
      LIMIT 1;

      IF v_effective_po_id IS NULL
        AND v_grn.po_id IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.purchase_orders po
          WHERE po.id = v_grn.po_id
            AND po.tenant_id = v_tenant_id
            AND po.supplier_id = p_supplier_id
        ) THEN
        v_effective_po_id := v_grn.po_id;
      END IF;
    END IF;
  ELSIF p_po_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.purchase_orders
    WHERE id = p_po_id
      AND tenant_id = v_tenant_id
      AND supplier_id = p_supplier_id
  ) THEN
    RAISE EXCEPTION 'po_supplier_mismatch' USING ERRCODE = '22023';
  END IF;

  IF v_due_date IS NULL
    AND v_payment_terms_days IS NOT NULL
    AND v_payment_terms_days > 0 THEN
    v_due_date := p_invoice_date + v_payment_terms_days;
  END IF;

  INSERT INTO public.supplier_invoices (
    tenant_id,
    supplier_id,
    grn_id,
    po_id,
    invoice_date,
    subtotal,
    vat_rate,
    vat_amount,
    total_amount,
    vat_breakdown,
    matching_notes,
    created_by,
    due_date,
    payment_status
  ) VALUES (
    v_tenant_id,
    p_supplier_id,
    p_grn_id,
    v_effective_po_id,
    p_invoice_date,
    0,
    NULL,
    0,
    0,
    p_vat_breakdown,
    NULLIF(pg_catalog.btrim(p_matching_notes), ''),
    v_user_id,
    v_due_date,
    'unpaid'
  )
  RETURNING id INTO v_invoice_id;

  RETURN v_invoice_id;
END;
$$;


--
-- Name: FUNCTION create_supplier_invoice_with_vat_breakdown(p_supplier_id bigint, p_grn_id bigint, p_po_id bigint, p_invoice_number text, p_invoice_date date, p_vat_breakdown jsonb, p_matching_notes text, p_due_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_supplier_invoice_with_vat_breakdown(p_supplier_id bigint, p_grn_id bigint, p_po_id bigint, p_invoice_number text, p_invoice_date date, p_vat_breakdown jsonb, p_matching_notes text, p_due_date date) IS 'Creates one tenant-scoped supplier invoice with multi-rate input-VAT breakdown; links GRN/PO per supplier including multi-NCC GRN slices.';


