--
-- Name: create_supplier_return_from_stock(bigint, bigint, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_return_from_stock(p_branch_id bigint, p_supplier_id bigint, p_resolution text, p_reason text, p_notes text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     UUID   := auth.uid();
  v_tenant  BIGINT := public.auth_tenant_id();
  v_branch  RECORD;
  v_return_id BIGINT;
  v_ret_num   TEXT;
  v_total     NUMERIC(15,2) := 0;
  v_line      JSONB;
  v_ing_id    BIGINT;
  v_qty       NUMERIC(15,3);
  v_unit_cost NUMERIC(15,2);
  v_entry_unit_id BIGINT;
  v_lines_inserted INT := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'supplier_return:create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_resolution NOT IN ('replacement','credit_note','cash_refund') THEN
    RAISE EXCEPTION 'invalid_resolution' USING ERRCODE = '22023';
  END IF;
  IF p_reason NOT IN ('damaged','wrong_item','expired','quality_fail','short_delivery_credit','other') THEN
    RAISE EXCEPTION 'invalid_reason' USING ERRCODE = '22023';
  END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'no_lines' USING ERRCODE = '22023';
  END IF;

  SELECT b.id, b.branch_kind INTO v_branch
  FROM public.branches b
  WHERE b.id = p_branch_id AND b.tenant_id = v_tenant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_ret_num := 'SR-' || to_char(now(),'YYMMDD') || '-' || lpad(nextval('public.supplier_returns_id_seq')::TEXT, 4, '0');

  INSERT INTO public.supplier_returns (
    tenant_id, branch_id, supplier_id, grn_id, return_number,
    source, reason, resolution, status, notes, total_value, created_by
  ) VALUES (
    v_tenant, p_branch_id, p_supplier_id, NULL, v_ret_num,
    'post_receipt', p_reason, p_resolution, 'draft', p_notes, 0, v_uid
  ) RETURNING id INTO v_return_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    v_ing_id    := (v_line->>'ingredient_id')::BIGINT;
    v_qty       := (v_line->>'quantity')::NUMERIC(15,3);
    v_unit_cost := (v_line->>'unit_cost')::NUMERIC(15,2);

    IF v_ing_id IS NULL OR v_qty IS NULL OR v_qty <= 0 OR v_unit_cost IS NULL THEN
      RAISE EXCEPTION 'invalid_line' USING ERRCODE = '22023';
    END IF;

    SELECT iu.unit_id INTO v_entry_unit_id
    FROM public.ingredient_units iu
    JOIN public.units u ON u.id = iu.unit_id AND u.tenant_id = iu.tenant_id AND u.is_active = TRUE
    WHERE iu.tenant_id = v_tenant
      AND iu.ingredient_id = v_ing_id
      AND iu.is_base = TRUE
      AND iu.is_active = TRUE
    ORDER BY iu.sort_order ASC, iu.id ASC
    LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO public.supplier_return_items (
      tenant_id, return_id, ingredient_id, quantity, unit_cost, total_cost,
      reason_detail, photo_url, entry_unit_id
    ) VALUES (
      v_tenant, v_return_id, v_ing_id, v_qty, v_unit_cost,
      ROUND(v_qty * v_unit_cost, 2),
      v_line->>'reason_detail', v_line->>'photo_url',
      v_entry_unit_id
    );
    v_total := v_total + ROUND(v_qty * v_unit_cost, 2);
    v_lines_inserted := v_lines_inserted + 1;
  END LOOP;

  UPDATE public.supplier_returns SET total_value = v_total WHERE id = v_return_id;

  RETURN jsonb_build_object(
    'return_id', v_return_id,
    'return_number', v_ret_num,
    'lines', v_lines_inserted,
    'total_value', v_total
  );
END;
$$;


--
-- Name: create_waste_entry(bigint, bigint, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_waste_entry(p_branch_id bigint, p_location_id bigint, p_items jsonb, p_source_type text DEFAULT 'manual'::text, p_source_ref jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_item jsonb;
  v_ingredient_id bigint;
  v_entry_unit_id bigint;
  v_quantity numeric;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission(
    p_branch_id,
    'inventory:writeoff'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  PERFORM location.id
  FROM public.inventory_locations AS location
  JOIN public.branches AS branch
    ON branch.id = location.branch_id
   AND branch.tenant_id = location.tenant_id
   AND branch.is_active IS TRUE
  WHERE location.id = p_location_id
    AND location.tenant_id = v_tenant
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE
  FOR UPDATE OF location;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'location_scope_mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF p_items IS NULL
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'waste_items_invalid'
      USING ERRCODE = '22023';
  END IF;

  FOR v_item IN
    SELECT item.value
    FROM jsonb_array_elements(p_items) AS item(value)
  LOOP
    v_ingredient_id :=
      nullif(v_item ->> 'ingredient_id', '')::bigint;
    v_entry_unit_id :=
      nullif(v_item ->> 'entry_unit_id', '')::bigint;
    v_quantity := nullif(v_item ->> 'quantity', '')::numeric;

    IF v_ingredient_id IS NULL
       OR v_entry_unit_id IS NULL
       OR v_quantity IS NULL
       OR v_quantity <= 0
       OR v_quantity = 'NaN'::numeric
       OR v_quantity = 'Infinity'::numeric
       OR v_quantity = '-Infinity'::numeric THEN
      RAISE EXCEPTION 'waste_item_invalid'
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.ingredients AS ingredient
      JOIN public.ingredient_units AS ingredient_unit
        ON ingredient_unit.ingredient_id = ingredient.id
       AND ingredient_unit.tenant_id = ingredient.tenant_id
       AND ingredient_unit.unit_id = v_entry_unit_id
       AND ingredient_unit.is_active IS TRUE
      JOIN public.units AS unit
        ON unit.id = ingredient_unit.unit_id
       AND unit.tenant_id = ingredient_unit.tenant_id
       AND unit.is_active IS TRUE
      WHERE ingredient.id = v_ingredient_id
        AND ingredient.tenant_id = v_tenant
        AND ingredient.is_active IS TRUE
    ) THEN
      RAISE EXCEPTION 'waste_item_unit_invalid'
        USING ERRCODE = '23503';
    END IF;
  END LOOP;

  RETURN private.execute_create_waste_entry(
    p_branch_id,
    p_location_id,
    p_items,
    p_source_type,
    p_source_ref,
    p_notes
  );
END;
$$;


--
-- Name: create_waste_from_order(bigint, bigint, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_waste_from_order(p_order_id bigint, p_location_id bigint, p_source_type text, p_items jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_order RECORD; v_default_reason TEXT; v_items_norm JSONB;
BEGIN
  IF p_source_type NOT IN ('pos_return','kds_cancel_mid_cook','kds_cancel_after_cook') THEN
    RAISE EXCEPTION 'source_type must be pos_return / kds_cancel_mid_cook / kds_cancel_after_cook' USING ERRCODE = '22023';
  END IF;
  IF p_source_type = 'pos_return' THEN v_default_reason := 'customer_return';
  ELSE v_default_reason := p_source_type; END IF;
  SELECT id, branch_id INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002'; END IF;
  SELECT jsonb_agg(CASE WHEN item ? 'reason_code' THEN item ELSE item || jsonb_build_object('reason_code', v_default_reason) END)
    INTO v_items_norm FROM jsonb_array_elements(p_items) AS item;
  RETURN public.create_waste_entry(v_order.branch_id, p_location_id, v_items_norm,
    p_source_type, jsonb_build_object('order_id', p_order_id), COALESCE(p_note, 'Auto from order #' || p_order_id::TEXT));
END; $$;


--
-- Name: current_position(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_position() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT po.code
  FROM public.profiles pr
  JOIN public.positions po
    ON po.id = pr.position_id
   AND po.tenant_id = pr.tenant_id
  WHERE pr.id = auth.uid()
    AND COALESCE(pr.is_active, true) = true
  LIMIT 1
$$;


--
-- Name: FUNCTION current_position(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.current_position() IS 'Returns the active profile HR position_code. profiles.position_id is the only position source.';


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  claims jsonb := event -> 'claims';
  source_metadata jsonb := COALESCE(claims -> 'app_metadata', '{}'::jsonb);
  canonical_metadata jsonb;
  user_profile record;
BEGIN
  SELECT
    profile.tenant_id,
    profile.branch_id,
    COALESCE(
      private.staff_role_from_position_code(position.code),
      CASE WHEN EXISTS (
        SELECT 1
        FROM public.auth_role_bindings binding
        WHERE binding.user_id = profile.id
          AND binding.tenant_id = profile.tenant_id
          AND binding.role_code = 'self_service_member'
          AND binding.scope_type = 'tenant'
          AND binding.branch_id IS NULL
          AND binding.valid_from <= now()
          AND (binding.valid_until IS NULL OR binding.valid_until > now())
      ) THEN 'self_service' END
    ) AS user_role,
    position.code AS position_code
  INTO user_profile
  FROM public.profiles profile
  JOIN public.positions position
    ON position.id = profile.position_id
   AND position.tenant_id = profile.tenant_id
  WHERE profile.id = (event ->> 'user_id')::uuid
    AND profile.is_active
    AND position.is_active
  LIMIT 1;

  canonical_metadata := jsonb_strip_nulls(jsonb_build_object(
    'provider', source_metadata -> 'provider',
    'providers', source_metadata -> 'providers',
    'full_name', source_metadata -> 'full_name'
  ));

  IF user_profile.tenant_id IS NOT NULL THEN
    IF user_profile.user_role IS NULL THEN
      RAISE EXCEPTION
        'custom_access_token_hook: active_self_service_binding_not_resolved for position=% tenant=%',
        user_profile.position_code,
        user_profile.tenant_id
        USING ERRCODE = 'P0001';
    END IF;

    canonical_metadata := canonical_metadata || jsonb_build_object(
      'tenant_id', user_profile.tenant_id,
      'branch_id', user_profile.branch_id,
      'user_role', user_profile.user_role,
      'position_code', user_profile.position_code
    );
  END IF;

  claims := jsonb_set(claims, '{app_metadata}', canonical_metadata);
  RETURN jsonb_set(event, '{claims}', claims);
END;
$$;


--
-- Name: FUNCTION custom_access_token_hook(event jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.custom_access_token_hook(event jsonb) IS 'Emits the legacy application role or the self_service compatibility projection. Live bindings and database capabilities remain authoritative.';


--
-- Name: decrement_branch_menu_daily_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_branch_menu_daily_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_branch_id  BIGINT;
  v_order_date DATE;
  v_target     RECORD;
BEGIN
  IF OLD.status = 'cancelled' OR NEW.status <> 'cancelled' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.kds_tickets kt
    WHERE kt.tenant_id = NEW.tenant_id
      AND kt.order_item_id = NEW.id
      AND kt.first_ready_at IS NOT NULL
  ) THEN
    RETURN NEW;
  END IF;

  SELECT o.branch_id,
         (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  INTO v_branch_id, v_order_date
  FROM public.orders o
  WHERE o.id = NEW.order_id;

  IF v_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_target IN
    WITH agg AS (
      SELECT OLD.menu_item_id::BIGINT AS item_id,
             OLD.quantity::INT        AS need_qty
      UNION ALL
      SELECT (s.elem ->> 'side_item_id')::BIGINT,
             (OLD.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::INT, 1))::INT
      FROM jsonb_array_elements(COALESCE(OLD.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT item_id, SUM(need_qty)::INT AS need_qty
    FROM agg
    WHERE item_id IS NOT NULL
    GROUP BY item_id
    ORDER BY item_id ASC
  LOOP
    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = GREATEST(0, sold_today - v_target.need_qty)
    WHERE branch_id    = v_branch_id
      AND menu_item_id = v_target.item_id
      AND limit_date   = v_order_date;
  END LOOP;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION decrement_branch_menu_daily_limit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.decrement_branch_menu_daily_limit() IS 'AFTER UPDATE OF status on order_items (→ cancelled): symmetric decrement using OLD.menu_item_id + OLD.sides aggregated by menu_item_id ASC. Bounded at 0 via GREATEST. First-ready boundary (D064 §5): a line the kitchen already made (kds_tickets.first_ready_at IS NOT NULL) keeps its quota consumed on cancel/void; a never-ready line returns quota.';


--
-- Name: delete_branch_revenue_target(date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_branch_revenue_target(p_year_month date, p_branch_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_month date;
  v_deleted integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT (public.auth_is_owner(v_uid) OR public.has_position('accountant'))
     OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_year_month IS NULL OR p_branch_id IS NULL OR p_branch_id <= 0 THEN
    RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
  END IF;

  v_month := date_trunc('month', p_year_month::timestamp)::date;

  DELETE FROM public.branch_revenue_targets
  WHERE tenant_id = v_tenant
    AND branch_id = p_branch_id
    AND year_month = v_month;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'deleted', v_deleted,
    'year_month', v_month,
    'branch_id', p_branch_id
  );
END;
$$;


--
-- Name: FUNCTION delete_branch_revenue_target(p_year_month date, p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_branch_revenue_target(p_year_month date, p_branch_id bigint) IS 'Owner-only deletion of one branch monthly Doanh thu thuần target and reward tiers.';


--
-- Name: delete_payroll_adjustment(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_payroll_adjustment(p_adjustment_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_adjustment public.payroll_adjustments%ROWTYPE;
BEGIN
  IF v_tenant_id IS NULL OR NOT public.has_permission_any('finance:payroll_calculate') THEN
    RAISE EXCEPTION 'delete_payroll_adjustment: missing payroll permission'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_adjustment
  FROM public.payroll_adjustments pa
  WHERE pa.id = p_adjustment_id
    AND pa.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'delete_payroll_adjustment: adjustment not found'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.payroll_periods pp
    WHERE pp.tenant_id = v_tenant_id
      AND pp.period_year = EXTRACT(YEAR FROM v_adjustment.effective_month)::integer
      AND pp.period_month = EXTRACT(MONTH FROM v_adjustment.effective_month)::integer
      AND pp.status IN ('approved', 'paid')
  ) THEN
    RAISE EXCEPTION 'delete_payroll_adjustment: payroll snapshot locked'
      USING ERRCODE = 'check_violation';
  END IF;

  DELETE FROM public.payroll_adjustments
  WHERE id = v_adjustment.id;

  PERFORM public.log_audit(
    'delete',
    'payroll_adjustment',
    v_adjustment.id,
    jsonb_build_object(
      'employee_id', v_adjustment.employee_id,
      'effective_month', v_adjustment.effective_month,
      'kind', v_adjustment.kind,
      'amount', v_adjustment.amount,
      'note', v_adjustment.note
    ),
    NULL
  );
END;
$$;


--
-- Name: edit_pending_order_item(bigint, bigint, text, numeric, jsonb, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_pending_order_item(p_order_item_id bigint, p_variant_id bigint, p_variant_name text, p_unit_price numeric, p_modifiers jsonb, p_sides jsonb, p_note text, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid            UUID;
  v_prof_tenant    BIGINT;
  v_prof_branch    BIGINT;
  v_prof_role      TEXT;
  v_item           public.order_items%ROWTYPE;
  v_order          public.orders%ROWTYPE;
  v_menu_active    BOOLEAN;
  v_base_price     NUMERIC(15,2);
  v_variant_adj    NUMERIC(15,2) := 0;
  v_modifier_sum   NUMERIC(15,2) := 0;
  v_sides_sum      NUMERIC(15,2) := 0;
  v_enriched_sides JSONB := '[]'::JSONB;
  v_new_unit       NUMERIC(15,2);
  v_old_qty        INT;
  v_old_unit       NUMERIC(15,2);
  v_new_subtotal   NUMERIC(15,2);
  v_subtotal_sum   NUMERIC(15,2);
  v_disc_amount    NUMERIC(15,2);
  v_total_amount   NUMERIC(15,2);
  v_flag_enabled   TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'cashier') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_quantity IS NULL OR p_quantity < 1 THEN
    RAISE EXCEPTION 'quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  IF p_unit_price IS NULL OR p_unit_price < 0 THEN
    RAISE EXCEPTION 'unit_price must be >= 0' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_edit_pending_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'feature disabled' USING ERRCODE = '22023';
  END IF;

  IF v_item.status <> 'pending' THEN
    RAISE EXCEPTION 'item not editable' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  SELECT base_price, is_active
  INTO v_base_price, v_menu_active
  FROM public.menu_items
  WHERE id = v_item.menu_item_id AND tenant_id = v_order.tenant_id;

  IF NOT FOUND OR COALESCE(v_menu_active, FALSE) = FALSE THEN
    RAISE EXCEPTION 'menu item inactive' USING ERRCODE = '22023';
  END IF;

  IF p_variant_id IS NOT NULL THEN
    SELECT price_adjustment INTO v_variant_adj
    FROM public.menu_item_variants
    WHERE id = p_variant_id
      AND item_id = v_item.menu_item_id
      AND tenant_id = v_order.tenant_id
      AND is_active = TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'variant inactive' USING ERRCODE = '22023';
    END IF;
  ELSE
    v_variant_adj := 0;
  END IF;

  v_modifier_sum := public.pos_order_modifier_sum(
    v_order.tenant_id,
    v_item.menu_item_id,
    COALESCE(p_modifiers, '[]'::JSONB)
  );

  SELECT sides_sum, enriched_sides
  INTO v_sides_sum, v_enriched_sides
  FROM public.pos_enrich_order_sides(
    v_order.tenant_id,
    v_item.menu_item_id,
    COALESCE(p_sides, '[]'::JSONB)
  );

  v_new_unit := v_base_price + v_variant_adj + v_modifier_sum + COALESCE(v_sides_sum, 0);

  v_old_qty := v_item.quantity;
  v_old_unit := v_item.unit_price;
  v_new_subtotal := v_new_unit * p_quantity;

  UPDATE public.order_items
  SET variant_id   = p_variant_id,
      variant_name = NULLIF(p_variant_name, ''),
      unit_price   = v_new_unit,
      modifiers    = COALESCE(p_modifiers, '[]'::JSONB),
      sides        = COALESCE(v_enriched_sides, '[]'::JSONB),
      note         = NULLIF(trim(COALESCE(p_note, '')), ''),
      quantity     = p_quantity,
      subtotal     = v_new_subtotal,
      updated_at   = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET updated_at = now()
  WHERE order_item_id = p_order_item_id
    AND tenant_id = v_item.tenant_id
    AND status NOT IN ('served', 'cancelled');

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal_sum
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  v_disc_amount := public.compute_discount_amount(
    v_order.discount_type, v_order.discount_value, v_subtotal_sum
  );
  v_total_amount := v_subtotal_sum
    + COALESCE(v_order.service_charge, 0)
    - v_disc_amount;

  UPDATE public.orders
  SET subtotal        = v_subtotal_sum,
      discount_amount = v_disc_amount,
      total_amount    = v_total_amount,
      updated_at      = now()
  WHERE id = v_item.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
    'edit_item ' || p_order_item_id::TEXT
      || ': qty ' || v_old_qty::TEXT || '->' || p_quantity::TEXT
      || ', unit ' || v_old_unit::TEXT || '->' || v_new_unit::TEXT
  );

  RETURN jsonb_build_object(
    'order_id',           v_item.order_id,
    'order_item_id',      p_order_item_id,
    'old_quantity',       v_old_qty,
    'new_quantity',       p_quantity,
    'subtotal',           v_subtotal_sum,
    'discount_amount',    v_disc_amount,
    'total_amount',       v_total_amount,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


--
-- Name: FUNCTION edit_pending_order_item(p_order_item_id bigint, p_variant_id bigint, p_variant_name text, p_unit_price numeric, p_modifiers jsonb, p_sides jsonb, p_note text, p_quantity integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.edit_pending_order_item(p_order_item_id bigint, p_variant_id bigint, p_variant_name text, p_unit_price numeric, p_modifiers jsonb, p_sides jsonb, p_note text, p_quantity integer) IS 'Sửa món đã gửi khi status=pending (chef chưa bắt đầu nấu). Server recompute unit_price/subtotal từ menu (base + variant_adj + modifier_sum + sides_sum) — BỎ QUA p_unit_price từ client (giữ trong signature cho compat). Mirror create_order/append_order_items convention. Sides JSONB được enrich qua pos_enrich_order_sides. Lock order + item, gate qua pos:void_order. Recompute discount qua compute_discount_amount, bump kds_tickets.updated_at. Block khi status<>pending, order completed/cancelled, payment_status=paid, menu_item inactive, variant inactive, feature flag pos_edit_pending_enabled=false.';


--
-- Name: employee_clock_in_with_checklist(bigint, bigint, bigint, bigint, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_clock_in_with_checklist(p_tenant_id bigint, p_employee_id bigint, p_branch_id bigint, p_shift_id bigint, p_business_date date, p_photo_path text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attendance_id bigint;
  v_shift_id bigint;
  v_is_open boolean;
  v_is_close boolean;
  v_position_id bigint;
BEGIN
  IF p_photo_path IS NULL OR btrim(p_photo_path) = '' THEN
    RAISE EXCEPTION 'photo_required' USING ERRCODE = '23514';
  END IF;

  SELECT p.position_id INTO v_position_id
  FROM public.employees e
  JOIN public.profiles p ON p.id = e.profile_id AND p.tenant_id = e.tenant_id
  WHERE e.id = p_employee_id AND e.tenant_id = p_tenant_id AND e.is_active AND p.branch_id = p_branch_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'employee_not_found' USING ERRCODE='P0002'; END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = p_tenant_id
      AND COALESCE(b.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_shift_id IS NULL OR p_shift_id = 0 THEN
    RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT s.id, s.is_opening, s.is_closing
  INTO v_shift_id, v_is_open, v_is_close
  FROM public.shifts s
  WHERE s.id = p_shift_id AND s.tenant_id = p_tenant_id
    AND (s.branch_id IS NULL OR s.branch_id = p_branch_id) AND COALESCE(s.is_active, true);
  IF NOT FOUND THEN RAISE EXCEPTION 'shift_not_found' USING ERRCODE='P0002'; END IF;

  IF EXISTS (
    SELECT 1
    FROM public.attendance_records ar
    WHERE ar.tenant_id = p_tenant_id
      AND ar.employee_id = p_employee_id
      AND ar.date = p_business_date
      AND ar.shift_id = v_shift_id
  ) THEN
    RAISE EXCEPTION 'duplicate_clock_in' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.attendance_records (
    tenant_id,
    branch_id,
    employee_id,
    shift_id,
    date,
    check_in,
    status,
    method,
    check_in_photo_path,
    checklist_template_id
  )
  VALUES (
    p_tenant_id,
    p_branch_id,
    p_employee_id,
    v_shift_id,
    p_business_date,
    now(),
    'present',
    'pwa',
    p_photo_path,
    NULL
  )
  RETURNING id INTO v_attendance_id;

  INSERT INTO public.attendance_checklist_items
    (tenant_id, attendance_record_id, template_item_id, title, phase, done_definition, is_required, scope, task_kind, sort_order)
  SELECT p_tenant_id, v_attendance_id, NULL, t.title, t.phase, t.done_definition, t.is_required,
         t.applicability, t.kind, row_number() OVER (ORDER BY t.sort_order, t.id)::integer
  FROM public.position_shift_tasks t
  WHERE t.tenant_id = p_tenant_id AND t.position_id = v_position_id AND t.is_active
    AND ( t.applicability = 'every_shift'
          OR (t.applicability = 'opening' AND v_is_open)
          OR (t.applicability = 'closing' AND v_is_close) );

  IF EXISTS (
    SELECT 1 FROM public.inventory_count_assignments a
    WHERE a.tenant_id = p_tenant_id AND a.branch_id = p_branch_id
      AND a.employee_id = p_employee_id AND a.is_active
  ) THEN
    INSERT INTO public.attendance_checklist_items
      (tenant_id, attendance_record_id, template_item_id, title, phase, done_definition, is_required, scope, task_kind, sort_order)
    VALUES (p_tenant_id, v_attendance_id, NULL, 'Kiểm kê tồn', 'end_of_shift',
            'Nộp phiếu đếm tại màn Kiểm kê tồn.', true, 'every_shift', 'inventory_count',
            COALESCE((SELECT max(sort_order) FROM public.attendance_checklist_items WHERE attendance_record_id = v_attendance_id), 0) + 1);
  END IF;

  RETURN v_attendance_id;
END;
$$;


--
-- Name: FUNCTION employee_clock_in_with_checklist(p_tenant_id bigint, p_employee_id bigint, p_branch_id bigint, p_shift_id bigint, p_business_date date, p_photo_path text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employee_clock_in_with_checklist(p_tenant_id bigint, p_employee_id bigint, p_branch_id bigint, p_shift_id bigint, p_business_date date, p_photo_path text) IS 'Per-shift employee clock-in: validates a global-or-branch shift, dedupes per (employee, date, shift), snapshots the employee default checklist filtered by item scope for this shift (opening shift gets every_shift+opening, closing gets every_shift+closing; weekly excluded).';


--
-- Name: employee_clock_out_with_code(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_clock_out_with_code(p_tenant_id bigint, p_employee_id bigint, p_attendance_id bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN public.employee_request_clock_out(
    p_tenant_id,
    p_employee_id,
    p_attendance_id
  );
END;
$$;


--
-- Name: employee_request_clock_out(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_request_clock_out(p_tenant_id bigint, p_employee_id bigint, p_attendance_id bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_record public.attendance_records%ROWTYPE;
  v_count_remaining integer;
  v_requested_at timestamptz;
  v_employee_name text;
  v_requester_role text;
  v_target_roles text[];
  v_now_local timestamp := now() AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_calendar_date date := v_now_local::date;
BEGIN
  SELECT ar.*
  INTO v_record
  FROM public.attendance_records ar
  JOIN public.employees e
    ON e.id = ar.employee_id
   AND e.tenant_id = ar.tenant_id
  JOIN public.profiles p
    ON p.id = e.profile_id
   AND p.tenant_id = e.tenant_id
  WHERE ar.id = p_attendance_id
    AND ar.tenant_id = p_tenant_id
    AND ar.employee_id = p_employee_id
    AND ar.branch_id = p.branch_id
    AND ar.date BETWEEN v_calendar_date - 1 AND v_calendar_date
    AND ar.check_out IS NULL
    AND COALESCE(e.is_active, true) = true
    AND COALESCE(p.is_active, true) = true
  FOR UPDATE OF ar;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'open_attendance_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::integer
  INTO v_count_remaining
  FROM (
    SELECT a.location_id
    FROM public.inventory_count_assignments a
    WHERE a.tenant_id = p_tenant_id
      AND a.branch_id = v_record.branch_id
      AND a.employee_id = p_employee_id
      AND a.is_active
      AND (a.shift_id IS NULL OR a.shift_id = v_record.shift_id)
    GROUP BY a.location_id
  ) assigned
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.inventory_count_slips s
    WHERE s.tenant_id = p_tenant_id
      AND s.branch_id = v_record.branch_id
      AND s.employee_id = p_employee_id
      AND s.location_id = assigned.location_id
      AND s.count_date = v_record.date
      AND s.shift_id IS NOT DISTINCT FROM v_record.shift_id
      AND s.status IN ('submitted', 'approved')
  );

  IF v_count_remaining > 0 THEN
    RAISE EXCEPTION 'checklist_incomplete' USING ERRCODE = '23514';
  END IF;

  IF v_record.checkout_requested_at IS NOT NULL THEN
    RETURN v_record.checkout_requested_at;
  END IF;

  v_requested_at := now();

  SELECT p.full_name, private.staff_role_from_position_code(po.code)
  INTO v_employee_name, v_requester_role
  FROM public.employees e
  LEFT JOIN public.profiles p
    ON p.id = e.profile_id
   AND p.tenant_id = e.tenant_id
  LEFT JOIN public.positions po
    ON po.id = p.position_id
   AND po.tenant_id = p.tenant_id
  WHERE e.id = p_employee_id
    AND e.tenant_id = p_tenant_id;

  v_requester_role := COALESCE(v_requester_role, 'unassigned');
  v_target_roles := CASE
    WHEN v_requester_role = 'branch_manager' THEN ARRAY['owner']::text[]
    WHEN v_requester_role IN ('cashier', 'chef', 'branch_staff')
      THEN ARRAY['branch_manager']::text[]
    ELSE ARRAY['owner']::text[]
  END;

  UPDATE public.attendance_records
  SET checkout_requested_at = v_requested_at,
      checkout_requested_by_role = v_requester_role,
      checkout_approval_target_roles = v_target_roles,
      updated_at = now()
  WHERE id = p_attendance_id
    AND tenant_id = p_tenant_id
    AND employee_id = p_employee_id
    AND branch_id = v_record.branch_id
    AND date = v_record.date
    AND check_out IS NULL;

  INSERT INTO public.notifications (
    tenant_id,
    target_branch_id,
    target_roles,
    kind,
    severity,
    title,
    body,
    entity_type,
    entity_id,
    action_url,
    meta,
    dedup_key
  )
  VALUES (
    p_tenant_id,
    v_record.branch_id,
    v_target_roles,
    'attendance.checkout_requested',
    'info',
    'Yêu cầu duyệt kết ca',
    format(
      '%s đã gửi yêu cầu kết ca lúc %s.',
      COALESCE(v_employee_name, 'Nhân viên'),
      to_char(v_requested_at AT TIME ZONE 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM')
    ),
    'attendance_record',
    p_attendance_id,
    format('/br/%s/shift/checkout-approvals', v_record.branch_id),
    jsonb_build_object(
      'attendance_id', p_attendance_id,
      'employee_id', p_employee_id,
      'requester_role', v_requester_role,
      'approval_target_roles', to_jsonb(v_target_roles),
      'branch_id', v_record.branch_id,
      'business_date', v_record.date,
      'requested_at', v_requested_at
    ),
    format('attendance.checkout_request:%s', p_attendance_id)
  )
  ON CONFLICT (tenant_id, dedup_key)
    WHERE dedup_key IS NOT NULL
  DO UPDATE SET
    created_at = EXCLUDED.created_at,
    expires_at = NULL,
    meta = EXCLUDED.meta;

  RETURN v_requested_at;
END;
$$;


--
-- Name: employee_submit_consumption_report(bigint, bigint, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_submit_consumption_report(p_tenant_id bigint, p_attendance_id bigint, p_lines jsonb, p_note text DEFAULT NULL::text, p_no_consumption boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_attendance record;
  v_report_id bigint;
  v_checklist_item_id bigint;
  v_line_count integer;
  v_distinct_line_count integer;
  v_no_consumption boolean := COALESCE(p_no_consumption, false);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_tenant IS NULL OR v_tenant <> p_tenant_id THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'invalid_consumption_lines' USING ERRCODE = '22023';
  END IF;

  IF v_no_consumption AND jsonb_array_length(p_lines) <> 0 THEN
    RAISE EXCEPTION 'no_consumption_with_lines' USING ERRCODE = '22023';
  END IF;

  IF NOT v_no_consumption AND jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'consumption_lines_required' USING ERRCODE = '22023';
  END IF;

  SELECT ar.id, ar.tenant_id, ar.branch_id, ar.employee_id, ar.check_in, ar.check_out,
         ar.checkout_requested_at
  INTO v_attendance
  FROM public.attendance_records ar
  JOIN public.employees e
    ON e.id = ar.employee_id
   AND e.tenant_id = ar.tenant_id
  WHERE ar.id = p_attendance_id
    AND ar.tenant_id = p_tenant_id
    AND e.profile_id = v_uid
  FOR UPDATE OF ar;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'attendance_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_attendance.check_in IS NULL OR v_attendance.check_out IS NOT NULL THEN
    RAISE EXCEPTION 'attendance_not_open' USING ERRCODE = '22023';
  END IF;

  IF v_attendance.checkout_requested_at IS NOT NULL THEN
    RAISE EXCEPTION 'checkout_already_requested' USING ERRCODE = '22023';
  END IF;

  SELECT ci.id
  INTO v_checklist_item_id
  FROM public.attendance_checklist_items ci
  WHERE ci.tenant_id = p_tenant_id
    AND ci.attendance_record_id = v_attendance.id
    AND ci.task_kind = 'consumption_report'
  LIMIT 1;

  IF v_checklist_item_id IS NULL THEN
    RAISE EXCEPTION 'consumption_checklist_not_assigned' USING ERRCODE = '22023';
  END IF;

  SELECT count(*)
  INTO v_line_count
  FROM jsonb_to_recordset(p_lines) AS src(
    default_item_id bigint,
    ingredient_id bigint,
    quantity numeric,
    note text
  )
  JOIN public.ingredients i
    ON i.id = src.ingredient_id
   AND i.tenant_id = p_tenant_id
   AND i.is_active = true
  LEFT JOIN public.shift_checklist_consumption_default_items d
    ON d.id = src.default_item_id
   AND d.tenant_id = p_tenant_id
   AND d.ingredient_id = src.ingredient_id
   AND d.is_active = true
  LEFT JOIN public.attendance_checklist_items ci
    ON ci.tenant_id = p_tenant_id
   AND ci.attendance_record_id = v_attendance.id
   AND ci.task_kind = 'consumption_report'
   AND ci.template_item_id = d.template_item_id
  WHERE src.quantity > 0
    AND (src.default_item_id IS NULL OR ci.id IS NOT NULL);

  SELECT count(DISTINCT src.ingredient_id)
  INTO v_distinct_line_count
  FROM jsonb_to_recordset(p_lines) AS src(
    default_item_id bigint,
    ingredient_id bigint,
    quantity numeric,
    note text
  );

  IF v_line_count <> jsonb_array_length(p_lines)
     OR v_distinct_line_count <> jsonb_array_length(p_lines) THEN
    RAISE EXCEPTION 'invalid_consumption_line' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.attendance_consumption_reports (
    tenant_id,
    attendance_record_id,
    branch_id,
    employee_id,
    status,
    note,
    submitted_by,
    submitted_at,
    reviewed_by,
    reviewed_at,
    review_note,
    stock_issue_id,
    no_consumption
  )
  VALUES (
    p_tenant_id,
    v_attendance.id,
    v_attendance.branch_id,
    v_attendance.employee_id,
    'submitted',
    NULLIF(btrim(COALESCE(p_note, '')), ''),
    v_uid,
    now(),
    NULL,
    NULL,
    NULL,
    NULL,
    v_no_consumption
  )
  ON CONFLICT (tenant_id, attendance_record_id)
  DO UPDATE SET
    status = 'submitted',
    note = EXCLUDED.note,
    submitted_by = EXCLUDED.submitted_by,
    submitted_at = EXCLUDED.submitted_at,
    reviewed_by = NULL,
    reviewed_at = NULL,
    review_note = NULL,
    stock_issue_id = NULL,
    no_consumption = EXCLUDED.no_consumption
  WHERE attendance_consumption_reports.status IN ('draft', 'submitted', 'needs_changes')
  RETURNING id INTO v_report_id;

  IF v_report_id IS NULL THEN
    RAISE EXCEPTION 'consumption_report_locked' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.attendance_consumption_report_lines
  WHERE tenant_id = p_tenant_id
    AND report_id = v_report_id;

  INSERT INTO public.attendance_consumption_report_lines (
    tenant_id,
    report_id,
    ingredient_id,
    default_item_id,
    quantity,
    note,
    sort_order,
    entry_unit_id
  )
  SELECT
    p_tenant_id,
    v_report_id,
    src.ingredient_id,
    src.default_item_id,
    src.quantity,
    NULLIF(btrim(COALESCE(src.note, '')), ''),
    src.sort_order,
    bu.unit_id
  FROM (
    SELECT
      row_number() OVER ()::integer AS sort_order,
      default_item_id,
      ingredient_id,
      quantity,
      note
    FROM jsonb_to_recordset(p_lines) AS parsed(
      default_item_id bigint,
      ingredient_id bigint,
      quantity numeric,
      note text
    )
  ) src
  JOIN public.ingredients i
    ON i.id = src.ingredient_id
   AND i.tenant_id = p_tenant_id
   AND i.is_active = true
  JOIN LATERAL (
    SELECT iu.unit_id
    FROM public.ingredient_units iu
    JOIN public.units u
      ON u.id = iu.unit_id
     AND u.tenant_id = iu.tenant_id
     AND u.is_active = TRUE
    WHERE iu.tenant_id = p_tenant_id
      AND iu.ingredient_id = src.ingredient_id
      AND iu.is_base = TRUE
      AND iu.is_active = TRUE
    ORDER BY iu.sort_order ASC, iu.id ASC
    LIMIT 1
  ) bu ON TRUE;

  UPDATE public.attendance_checklist_items
  SET is_done = true,
      completed_at = now()
  WHERE tenant_id = p_tenant_id
    AND attendance_record_id = v_attendance.id
    AND task_kind = 'consumption_report';

  RETURN v_report_id;
END;
$$;


--
-- Name: FUNCTION employee_submit_consumption_report(p_tenant_id bigint, p_attendance_id bigint, p_lines jsonb, p_note text, p_no_consumption boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employee_submit_consumption_report(p_tenant_id bigint, p_attendance_id bigint, p_lines jsonb, p_note text, p_no_consumption boolean) IS 'Employee submits daily kitchen consumption lines or an explicit no-consumption confirmation for an open attendance record. Does not affect Inventory.';


--
-- Name: enable_offline_for_session(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enable_offline_for_session(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_session public.stocktake_sessions%ROWTYPE;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT session.*
  INTO v_session
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant
  FOR UPDATE OF session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(NULL, 'settings:tenant') THEN
    RAISE EXCEPTION
      'forbidden: settings:tenant required for offline pilot'
      USING ERRCODE = '42501';
  END IF;
  IF v_session.status <> 'in_progress' THEN
    RAISE EXCEPTION 'session not in_progress (status=%)',
      v_session.status
      USING ERRCODE = '22023';
  END IF;
  IF v_session.offline_enabled THEN
    RAISE EXCEPTION 'offline already enabled for session %',
      p_session_id
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.stocktake_sessions
  SET offline_enabled = TRUE,
      offline_enabled_by = v_uid,
      offline_enabled_at = now()
  WHERE id = p_session_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'session_id',
    p_session_id,
    'offline_enabled',
    TRUE,
    'enabled_by',
    v_uid,
    'enabled_at',
    now()
  );
END;
$$;


--
-- Name: enforce_branch_menu_daily_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_branch_menu_daily_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_branch_id       bigint;
  v_order_date      date;
  v_tenant_id       bigint;
  v_target          record;
  v_limit           record;
  v_hold_token_text text;
  v_hold_token      uuid;
  v_active_hold_qty integer;
BEGIN
  IF COALESCE(current_setting('comtammatu.skip_quota_enforcement', true), 'false') = 'true' THEN
    RETURN NEW;
  END IF;

  v_hold_token_text := NULLIF(
    current_setting('comtammatu.daily_limit_hold_token', true),
    ''
  );
  IF v_hold_token_text IS NOT NULL THEN
    v_hold_token := v_hold_token_text::uuid;
  END IF;

  SELECT o.tenant_id,
         o.branch_id,
         (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  INTO v_tenant_id, v_branch_id, v_order_date
  FROM public.orders o
  WHERE o.id = NEW.order_id;

  IF v_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_target IN
    WITH agg AS (
      SELECT NEW.menu_item_id::bigint AS item_id,
             NEW.quantity::integer    AS need_qty
      UNION ALL
      SELECT (s.elem ->> 'side_item_id')::bigint,
             (NEW.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::integer, 1))::integer
      FROM jsonb_array_elements(COALESCE(NEW.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT item_id, SUM(need_qty)::integer AS need_qty
    FROM agg
    WHERE item_id IS NOT NULL
    GROUP BY item_id
    ORDER BY item_id ASC
  LOOP
    SELECT * INTO v_limit
    FROM public.branch_menu_item_daily_limits
    WHERE branch_id = v_branch_id
      AND menu_item_id = v_target.item_id
      AND limit_date = v_order_date
    FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.branch_menu_item_daily_limits (
        tenant_id,
        branch_id,
        menu_item_id,
        limit_date,
        limit_quantity,
        is_disabled,
        sold_today
      ) VALUES (
        v_tenant_id,
        v_branch_id,
        v_target.item_id,
        v_order_date,
        NULL,
        FALSE,
        v_target.need_qty
      )
      ON CONFLICT (branch_id, menu_item_id, limit_date)
      DO UPDATE SET sold_today = public.branch_menu_item_daily_limits.sold_today + EXCLUDED.sold_today;
      CONTINUE;
    END IF;

    IF v_limit.is_disabled THEN
      RAISE EXCEPTION 'daily_limit_item_disabled'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_item_disabled',
                'menu_item_id', v_target.item_id
              )::text;
    END IF;

    SELECT COALESCE(SUM(h.quantity), 0)::integer
    INTO v_active_hold_qty
    FROM public.branch_menu_item_daily_holds h
    WHERE h.tenant_id = v_tenant_id
      AND h.branch_id = v_branch_id
      AND h.menu_item_id = v_target.item_id
      AND h.limit_date = v_order_date
      AND (v_hold_token IS NULL OR h.hold_token <> v_hold_token)
      AND h.committed_at IS NULL
      AND h.released_at IS NULL
      AND h.expires_at > now();

    IF v_limit.limit_quantity IS NOT NULL
       AND v_limit.sold_today + v_active_hold_qty + v_target.need_qty > v_limit.limit_quantity THEN
      RAISE EXCEPTION 'daily_limit_exceeded'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_exceeded',
                'menu_item_id', v_target.item_id,
                'limit_quantity', v_limit.limit_quantity,
                'sold_today', v_limit.sold_today,
                'held_quantity', v_active_hold_qty,
                'requested_quantity', v_target.need_qty
              )::text;
    END IF;

    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = sold_today + v_target.need_qty
    WHERE id = v_limit.id;
  END LOOP;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION enforce_branch_menu_daily_limit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_branch_menu_daily_limit() IS 'AFTER INSERT on order_items: aggregate main + sides by menu_item_id ASC, lock each limit row, count active daily-limit holds except comtammatu.daily_limit_hold_token, raise P0001 daily_limit_item_disabled / daily_limit_exceeded, increment sold_today. Skip-hatch: comtammatu.skip_quota_enforcement=true.';


--
-- Name: enforce_branch_stock_availability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_branch_stock_availability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_tenant_id   bigint;
  v_branch_id   bigint;
  v_order_date  date;
  v_location_id bigint;
  v_need        record;
  v_on_hand     numeric(15,3);
  v_pending     numeric(15,3);
BEGIN
  IF COALESCE(current_setting('comtammatu.skip_quota_enforcement', true), 'false') = 'true' THEN
    RETURN NEW;
  END IF;

  SELECT o.tenant_id,
         o.branch_id,
         (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  INTO v_tenant_id, v_branch_id, v_order_date
  FROM public.orders o
  WHERE o.id = NEW.order_id;

  IF v_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT public.is_feature_enabled(v_branch_id, 'pos_stock_outcome_posting') THEN
    RETURN NEW;
  END IF;

  -- Same location resolution as post_pos_sale_consumption_if_ready so the
  -- gate measures exactly the pool posting deducts from. NULL (no active
  -- kitchen location) leaves on_hand at 0 below — consistent with
  -- capacity/availability display already showing 0 in that case.
  SELECT il.id
  INTO v_location_id
  FROM public.inventory_locations il
  WHERE il.branch_id = v_branch_id
    AND il.tenant_id = v_tenant_id
    AND il.location_kind = 'warehouse'
    AND il.is_active = TRUE
  ORDER BY il.is_default_consumption DESC, il.sort_order NULLS LAST, il.id
  LIMIT 1;

  -- Demand of this inserted row only (main + sides), converted to base units.
  -- Recipe-less items contribute nothing — outside stock control (D064 §2/D065 §4).
  -- Items with a recipe line whose entry_unit_id has no active ingredient_units
  -- row are ALSO outside stock control (mirrors compute_menu_item_stock_capacity's
  -- line_missing_config: capacity is NULL for them, never a hard 0) — excluded
  -- via NOT EXISTS so inv_to_base_for_tenant never hits recipe_unit_conversion_missing.
  FOR v_need IN
    WITH row_demand AS (
      SELECT NEW.menu_item_id::bigint AS menu_item_id,
             NEW.quantity::integer    AS quantity
      UNION ALL
      SELECT (s.elem ->> 'side_item_id')::bigint,
             (NEW.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::integer, 1))::integer
      FROM jsonb_array_elements(COALESCE(NEW.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT
      r.ingredient_id,
      ROUND(SUM(public.inv_to_base_for_tenant(
        v_tenant_id,
        r.ingredient_id,
        r.entry_unit_id,
        d.quantity * r.quantity / r.yield_factor
      )), 3)::numeric(15,3) AS need_qty
    FROM row_demand d
    JOIN public.recipes r
      ON r.menu_item_id = d.menu_item_id
     AND r.tenant_id = v_tenant_id
    WHERE d.menu_item_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.recipes r2
        WHERE r2.menu_item_id = d.menu_item_id
          AND r2.tenant_id = v_tenant_id
          AND r2.entry_unit_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.ingredient_units iu
            WHERE iu.tenant_id = v_tenant_id
              AND iu.ingredient_id = r2.ingredient_id
              AND iu.unit_id = r2.entry_unit_id
              AND iu.is_active = TRUE
          )
      )
    GROUP BY r.ingredient_id
    HAVING ROUND(SUM(public.inv_to_base_for_tenant(
      v_tenant_id,
      r.ingredient_id,
      r.entry_unit_id,
      d.quantity * r.quantity / r.yield_factor
    )), 3) > 0
    ORDER BY r.ingredient_id
  LOOP
    -- Serialize concurrent carts sharing an ingredient — lock only the
    -- stock_levels row(s) at the resolved issue location, not the location
    -- catalog itself.
    PERFORM 1
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant_id
      AND sl.branch_id = v_branch_id
      AND sl.ingredient_id = v_need.ingredient_id
      AND sl.location_id = v_location_id
    FOR UPDATE OF sl;

    SELECT COALESCE(SUM(sl.current_quantity), 0)
    INTO v_on_hand
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant_id
      AND sl.branch_id = v_branch_id
      AND sl.ingredient_id = v_need.ingredient_id
      AND sl.location_id = v_location_id;

    -- Pending demand = today's not-yet-completed/cancelled order lines
    -- (main + sides), including the row just inserted, same explosion,
    -- business-date keying, and missing-config exclusion as above.
    SELECT COALESCE(ROUND(SUM(public.inv_to_base_for_tenant(
      v_tenant_id,
      r.ingredient_id,
      r.entry_unit_id,
      cl.quantity * r.quantity / r.yield_factor
    )), 3), 0)
    INTO v_pending
    FROM (
      SELECT oi.menu_item_id::bigint AS menu_item_id,
             oi.quantity::integer AS quantity
      FROM public.orders o
      JOIN public.order_items oi
        ON oi.order_id = o.id
       AND oi.tenant_id = o.tenant_id
      WHERE o.tenant_id = v_tenant_id
        AND o.branch_id = v_branch_id
        AND (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = v_order_date
        AND o.status NOT IN ('completed', 'cancelled')
        AND oi.status <> 'cancelled'

      UNION ALL

      SELECT (s.elem ->> 'side_item_id')::bigint AS menu_item_id,
             (oi.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::integer, 1))::integer AS quantity
      FROM public.orders o
      JOIN public.order_items oi
        ON oi.order_id = o.id
       AND oi.tenant_id = o.tenant_id
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(oi.sides, '[]'::jsonb)) AS s(elem)
      WHERE o.tenant_id = v_tenant_id
        AND o.branch_id = v_branch_id
        AND (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = v_order_date
        AND o.status NOT IN ('completed', 'cancelled')
        AND oi.status <> 'cancelled'
        AND s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    ) cl
    JOIN public.recipes r
      ON r.menu_item_id = cl.menu_item_id
     AND r.tenant_id = v_tenant_id
    WHERE r.ingredient_id = v_need.ingredient_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.recipes r2
        WHERE r2.menu_item_id = cl.menu_item_id
          AND r2.tenant_id = v_tenant_id
          AND r2.entry_unit_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.ingredient_units iu
            WHERE iu.tenant_id = v_tenant_id
              AND iu.ingredient_id = r2.ingredient_id
              AND iu.unit_id = r2.entry_unit_id
              AND iu.is_active = TRUE
          )
      );

    IF v_on_hand - v_pending < 0 THEN
      RAISE EXCEPTION 'insufficient_stock_ingredient:%', v_need.ingredient_id
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'insufficient_stock_ingredient',
                'ingredient_id', v_need.ingredient_id
              )::text;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION enforce_branch_stock_availability(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_branch_stock_availability() IS 'Blocks stock-controlled order demand that exceeds the active branch warehouse balance when POS stock posting is enabled.';


--
-- Name: enforce_grn_central_site_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_grn_central_site_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_kind text;
BEGIN
  SELECT branch.branch_kind
  INTO v_kind
  FROM public.branches AS branch
  WHERE branch.id = NEW.branch_id
    AND branch.tenant_id = NEW.tenant_id;

  IF v_kind IS DISTINCT FROM 'central_supply'
     AND v_kind IS DISTINCT FROM 'central_kitchen' THEN
    RAISE EXCEPTION 'grn_central_site_only'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_period_close(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_period_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_status TEXT; v_effective TIMESTAMPTZ; v_tenant BIGINT;
BEGIN
  v_effective := (row_to_json(NEW.*)->>'effective_date')::TIMESTAMPTZ;
  v_tenant    := (row_to_json(NEW.*)->>'tenant_id')::BIGINT;
  IF v_effective IS NULL OR v_tenant IS NULL THEN RETURN NEW; END IF;
  v_status := public.period_status_at(v_tenant, v_effective);
  IF v_status = 'hard_closed' THEN
    IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN
      RAISE EXCEPTION 'target period is hard-closed' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: enforce_period_close_stock_issues(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_period_close_stock_issues() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_status TEXT;
BEGIN
  IF NEW.issued_at IS NULL OR NEW.tenant_id IS NULL THEN RETURN NEW; END IF;
  v_status := public.period_status_at(NEW.tenant_id, NEW.issued_at);
  IF v_status = 'hard_closed' AND NOT public.has_permission(NULL, 'accounting:period_reopen') THEN
    RAISE EXCEPTION 'target accounting period is hard-closed; accounting:period_reopen required' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: enforce_po_grn_branch_is_procurement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_po_grn_branch_is_procurement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = NEW.branch_id
      AND b.tenant_id = NEW.tenant_id
      AND b.branch_kind IN ('branch', 'central_supply', 'central_kitchen')
      AND b.is_active = true
  ) THEN
    RAISE EXCEPTION 'branch must be active procurement site' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_production_recipe_entry_unit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_production_recipe_entry_unit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.entry_unit_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.ingredient_units iu
       JOIN public.units u
         ON u.id = iu.unit_id
        AND u.tenant_id = iu.tenant_id
        AND u.is_active = TRUE
       WHERE iu.tenant_id = NEW.tenant_id
         AND iu.ingredient_id = NEW.ingredient_id
         AND iu.unit_id = NEW.entry_unit_id
         AND iu.is_active = TRUE
     ) THEN
    RAISE EXCEPTION 'production_recipe_unit_mapping_missing:%:%',
      NEW.ingredient_id,
      NEW.entry_unit_id
      USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_production_run_recipe_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_production_run_recipe_units() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.production_recipes pr
    LEFT JOIN public.ingredient_units iu
      ON iu.tenant_id = pr.tenant_id
     AND iu.ingredient_id = pr.ingredient_id
     AND iu.unit_id = pr.entry_unit_id
     AND iu.is_active = TRUE
    LEFT JOIN public.units u
      ON u.id = iu.unit_id
     AND u.tenant_id = iu.tenant_id
     AND u.is_active = TRUE
    WHERE pr.tenant_id = NEW.tenant_id
      AND pr.finished_good_id = NEW.finished_good_id
      AND pr.entry_unit_id IS NOT NULL
      AND (iu.id IS NULL OR u.id IS NULL)
  ) THEN
    RAISE EXCEPTION 'production_recipe_unit_mapping_missing:%',
      NEW.finished_good_id
      USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_stock_transfer_direction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_stock_transfer_direction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.from_branch_id = NEW.to_branch_id THEN
    RAISE EXCEPTION 'stock_transfers: distinct branches required'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations AS source
    WHERE source.id = NEW.from_location_id
      AND source.tenant_id = NEW.tenant_id
      AND source.branch_id = NEW.from_branch_id
      AND source.location_kind = 'warehouse'
      AND source.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'stock_transfers: source warehouse invalid'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations AS target
    WHERE target.id = NEW.to_location_id
      AND target.tenant_id = NEW.tenant_id
      AND target.branch_id = NEW.to_branch_id
      AND target.location_kind = 'warehouse'
      AND target.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'stock_transfers: target warehouse invalid'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_stock_transfer_direction(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_stock_transfer_direction() IS 'Transfers require distinct sites and active warehouse endpoints.';


--
-- Name: enforce_supplier_item_line_mapping(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_supplier_item_line_mapping() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_supplier_id bigint;
BEGIN
  IF TG_TABLE_NAME = 'purchase_order_items' THEN
    SELECT po.supplier_id
      INTO v_supplier_id
      FROM public.purchase_orders po
     WHERE po.id = NEW.po_id
       AND po.tenant_id = NEW.tenant_id;
  ELSIF TG_TABLE_NAME = 'grn_items' THEN
    -- Legacy PO→GRN inserts omit line supplier; fill from header when present.
    IF NEW.supplier_id IS NULL THEN
      SELECT grn.supplier_id
        INTO NEW.supplier_id
        FROM public.goods_received_notes grn
       WHERE grn.id = NEW.grn_id
         AND grn.tenant_id = NEW.tenant_id;
    END IF;
    v_supplier_id := NEW.supplier_id;
  ELSE
    RAISE EXCEPTION 'unsupported_supplier_item_line_table'
      USING ERRCODE = '22023';
  END IF;

  IF v_supplier_id IS NULL THEN
    RAISE EXCEPTION 'supplier_item_parent_not_found'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
       SELECT 1
         FROM public.supplier_items si
        WHERE si.tenant_id = NEW.tenant_id
          AND si.supplier_id = v_supplier_id
          AND si.ingredient_id = NEW.ingredient_id
          AND si.is_active
     ) THEN
    RAISE EXCEPTION 'supplier_item_mapping_required'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_supplier_items_on_document_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_supplier_items_on_document_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'purchase_orders'
     AND NEW.status = 'sent'
     AND OLD.status IS DISTINCT FROM NEW.status
     AND EXISTS (
       SELECT 1
         FROM public.purchase_order_items poi
        WHERE poi.po_id = NEW.id
          AND poi.tenant_id = NEW.tenant_id
          AND NOT EXISTS (
            SELECT 1
              FROM public.supplier_items si
             WHERE si.tenant_id = NEW.tenant_id
               AND si.supplier_id = NEW.supplier_id
               AND si.ingredient_id = poi.ingredient_id
               AND si.is_active
          )
     ) THEN
    RAISE EXCEPTION 'supplier_item_mapping_required'
      USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'goods_received_notes'
     AND NEW.status = 'confirmed'
     AND OLD.status IS DISTINCT FROM NEW.status
     AND EXISTS (
       SELECT 1
         FROM public.grn_items gi
        WHERE gi.grn_id = NEW.id
          AND gi.tenant_id = NEW.tenant_id
          AND gi.received_quantity - gi.rejected_quantity > 0
          AND NOT EXISTS (
            SELECT 1
              FROM public.supplier_items si
             WHERE si.tenant_id = NEW.tenant_id
               AND si.supplier_id = gi.supplier_id
               AND si.ingredient_id = gi.ingredient_id
               AND si.is_active
          )
     ) THEN
    RAISE EXCEPTION 'supplier_item_mapping_required'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enqueue_cancel_ticket_print(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_cancel_ticket_print(p_order_item_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid           UUID;
  v_item          public.order_items%ROWTYPE;
  v_order         public.orders%ROWTYPE;
  v_table_no      INT;
  v_slot          SMALLINT;
  v_printer_id    BIGINT;
  v_category_id   BIGINT;
  v_voided_by     TEXT;
  v_flag_enabled  TEXT;
  v_items_payload JSONB;
  v_payload       JSONB;
  v_idempotency   TEXT;
  v_job_id        BIGINT;
  v_now           TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_cancel_ticket_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  SELECT p.id, (p.sort_order + 1)::smallint
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = 'cancel_ticket'
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_voided_by
  FROM public.profiles WHERE id = v_uid;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',    v_item.item_name,
    'variant_name', v_item.variant_name,
    'quantity',     v_item.quantity,
    'modifiers',    v_item.modifiers,
    'sides',        v_item.sides,
    'note',         v_item.note
  ));

  v_payload := jsonb_build_object(
    'kind',          'cancel_ticket',
    'order_number',  v_order.order_number,
    'order_type',    v_order.order_type,
    'table_number',  v_table_no,
    'slot',          v_slot,
    'items',         v_items_payload,
    'reason',        COALESCE(NULLIF(trim(p_reason), ''), v_item.cancel_reason, ''),
    'voided_by',     COALESCE(v_voided_by, ''),
    'printed_at',    to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                             'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':cancel:' || p_order_item_id::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'cancel_ticket',
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot
  );
END;
$$;


--
-- Name: FUNCTION enqueue_cancel_ticket_print(p_order_item_id bigint, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_cancel_ticket_print(p_order_item_id bigint, p_reason text) IS 'Enqueue a PHIẾU HUỶ MÓN print job targeting the original kitchen slot. Skips silently (returns skipped:true) when feature flag off, item never sent to kitchen, category has no slot, or no active printer for the slot. Called by the voidOrderItem Server Action after void_order_item commits.';


--
-- Name: enqueue_edit_pending_order_item_quantity_print(bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_edit_pending_order_item_quantity_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_item            public.order_items%ROWTYPE;
  v_order           public.orders%ROWTYPE;
  v_table_no        INT;
  v_slot            SMALLINT;
  v_printer_id      BIGINT;
  v_category_id     BIGINT;
  v_staff_name      TEXT;
  v_flag_enabled    TEXT;
  v_delta           INT;
  v_print_type      TEXT;
  v_items_payload   JSONB;
  v_payload         JSONB;
  v_idempotency     TEXT;
  v_job_id          BIGINT;
  v_now             TIMESTAMPTZ := now();
  v_change_note     TEXT;
  v_item_note       TEXT;
  v_event_token     TEXT;
  v_batch_ticket_number TEXT;
  v_batch_send_seq      INT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_old_quantity IS NULL OR p_new_quantity IS NULL
     OR p_old_quantity < 1 OR p_new_quantity < 1
  THEN
    RAISE EXCEPTION 'quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  IF p_old_quantity = p_new_quantity THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_quantity_change');
  END IF;

  IF p_new_quantity < p_old_quantity THEN
    SELECT value INTO v_flag_enabled
    FROM public.system_settings
    WHERE tenant_id = v_order.tenant_id AND key = 'pos_reduce_qty_enabled';
    IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
      RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
    END IF;
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id
    AND mi.tenant_id = v_order.tenant_id;

  IF v_category_id IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  v_delta := abs(p_new_quantity - p_old_quantity);
  v_print_type := CASE
    WHEN p_new_quantity > p_old_quantity THEN 'kitchen_ticket'
    ELSE 'cancel_ticket'
  END;

  SELECT p.id, (p.sort_order + 1)::smallint
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = v_print_type
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_staff_name
  FROM public.profiles WHERE id = v_uid;

  SELECT ksb.kitchen_ticket_number, ksb.send_seq
  INTO v_batch_ticket_number, v_batch_send_seq
  FROM public.kds_tickets kt
  JOIN public.kitchen_send_batches ksb
    ON ksb.id = kt.kitchen_send_batch_id
  WHERE kt.tenant_id = v_order.tenant_id
    AND kt.order_item_id = v_item.id
  ORDER BY ksb.created_at DESC
  LIMIT 1;

  v_change_note := CASE
    WHEN p_new_quantity > p_old_quantity THEN
      'TANG SL ' || p_old_quantity::TEXT || ' -> ' || p_new_quantity::TEXT
    ELSE
      'GIAM SL ' || p_old_quantity::TEXT || ' -> ' || p_new_quantity::TEXT
  END;

  v_item_note := v_change_note
    || CASE
      WHEN NULLIF(trim(COALESCE(v_item.note, '')), '') IS NULL THEN ''
      ELSE ': ' || trim(v_item.note)
    END;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',    v_item.item_name,
    'variant_name', v_item.variant_name,
    'quantity',     v_delta,
    'modifiers',    v_item.modifiers,
    'sides',        v_item.sides,
    'note',         v_item_note
  ));

  v_event_token := replace(
    COALESCE(extract(epoch from v_item.updated_at)::NUMERIC(20,6)::TEXT, ''),
    '.',
    ''
  );

  IF p_new_quantity > p_old_quantity THEN
    v_payload := jsonb_build_object(
      'kind',                  'kitchen_ticket',
      'kitchen_ticket_number', COALESCE(v_batch_ticket_number, v_order.order_number),
      'source_order_number',   v_order.order_number,
      'order_number',          v_order.order_number,
      'order_type',            v_order.order_type,
      'table_number',          v_table_no,
      'cashier_name',          COALESCE(v_staff_name, ''),
      'send_seq',              COALESCE(v_batch_send_seq, v_order.kitchen_send_count, 1),
      'send_kind',             'append',
      'slot',                  v_slot,
      'note',                  v_change_note,
      'items',                 v_items_payload,
      'printed_at',            to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                       'YYYY-MM-DD"T"HH24:MI:SS')
    );
  ELSE
    v_payload := jsonb_build_object(
      'kind',         'cancel_ticket',
      'order_number', v_order.order_number,
      'order_type',   v_order.order_type,
      'table_number', v_table_no,
      'slot',         v_slot,
      'items',        v_items_payload,
      'reason',       v_change_note || ': '
                      || COALESCE(NULLIF(trim(p_reason), ''), 'Sua so luong mon'),
      'voided_by',    COALESCE(v_staff_name, ''),
      'printed_at',   to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                              'YYYY-MM-DD"T"HH24:MI:SS')
    );
  END IF;

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':edit-qty:' || p_order_item_id::TEXT
    || ':' || p_old_quantity::TEXT || '->' || p_new_quantity::TEXT
    || ':printer:' || v_printer_id::TEXT
    || ':at:' || v_event_token;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, v_print_type,
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  IF v_job_id IS NULL THEN
    SELECT id INTO v_job_id
    FROM public.print_jobs
    WHERE idempotency_key = v_idempotency;
  END IF;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot,
    'job_type',   v_print_type,
    'delta',      v_delta
  );
END;
$$;


--
-- Name: FUNCTION enqueue_edit_pending_order_item_quantity_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_edit_pending_order_item_quantity_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text) IS 'Enqueue a kitchen-visible print delta after edit_pending_order_item changes quantity for an already-sent pending item. Increase uses kitchen_ticket (GỌI THÊM); decrease uses cancel_ticket. Returns skipped reasons for not_sent, no_quantity_change, no_slot, no_printer, and feature_disabled.';


--
-- Name: enqueue_kitchen_print(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_kitchen_print(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_order public.orders%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'send_seq', v_order.kitchen_send_count,
    'jobs', '[]'::jsonb,
    'deferred_to', 'kds_completion'
  );
END;
$$;


--
-- Name: FUNCTION enqueue_kitchen_print(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_kitchen_print(p_order_id bigint) IS 'Compatibility wrapper. POS send routes work to KDS; kitchen paper is queued by complete_kds_tickets when KDS marks items ready.';


--
-- Name: enqueue_partial_cancel_ticket_print(bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_partial_cancel_ticket_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_item            public.order_items%ROWTYPE;
  v_order           public.orders%ROWTYPE;
  v_table_no        INT;
  v_slot            SMALLINT;
  v_printer_id      BIGINT;
  v_category_id     BIGINT;
  v_voided_by       TEXT;
  v_flag_enabled    TEXT;
  v_items_payload   JSONB;
  v_payload         JSONB;
  v_idempotency     TEXT;
  v_job_id          BIGINT;
  v_now             TIMESTAMPTZ := now();
  v_reason_prefixed TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_reduce_qty_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  IF p_new_quantity >= p_old_quantity THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_reduction');
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  SELECT p.id, (p.sort_order + 1)::smallint
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = 'cancel_ticket'
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_voided_by
  FROM public.profiles WHERE id = v_uid;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',     v_item.item_name,
    'variant_name',  v_item.variant_name,
    'quantity',      p_old_quantity - p_new_quantity,
    'modifiers',     v_item.modifiers,
    'sides',         v_item.sides,
    'note',          v_item.note
  ));

  v_reason_prefixed := 'GIAM SL ' || p_old_quantity::TEXT
    || ' -> ' || p_new_quantity::TEXT
    || ': ' || COALESCE(NULLIF(trim(p_reason), ''), '');

  v_payload := jsonb_build_object(
    'kind',          'cancel_ticket',
    'order_number',  v_order.order_number,
    'order_type',    v_order.order_type,
    'table_number',  v_table_no,
    'slot',          v_slot,
    'items',         v_items_payload,
    'reason',        v_reason_prefixed,
    'voided_by',     COALESCE(v_voided_by, ''),
    'printed_at',    to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                             'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':reduce:' || p_order_item_id::TEXT
    || ':' || p_old_quantity::TEXT || '->' || p_new_quantity::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'cancel_ticket',
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot
  );
END;
$$;


--
-- Name: FUNCTION enqueue_partial_cancel_ticket_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_partial_cancel_ticket_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text) IS 'Enqueue PHIẾU GIẢM SL — payload.kind=cancel_ticket (reuse template HUỶ MÓN ở print-agent), items[].quantity=delta (số phần bị giảm), reason prefix "GIẢM SL N → M:" để chef phân biệt với phiếu huỷ-toàn-phần. Skip silently khi feature flag off, item chưa gửi bếp, không có slot/printer. Idempotency key bao gồm old_qty+new_qty cho phép giảm nhiều lần (5→3 rồi 3→1) mà vẫn dedup double-submit cùng delta.';


--
-- Name: enqueue_provisional_bill(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_provisional_bill(p_order_id bigint, p_qr_content text DEFAULT NULL::text, p_qr_header_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID;
  v_order        public.orders%ROWTYPE;
  v_branch       public.branches%ROWTYPE;
  v_table_no     INT;
  v_printer_id   BIGINT;
  v_cashier_name TEXT;
  v_branch_tax   TEXT;
  v_qr_type      TEXT;
  v_flag_enabled TEXT;
  v_vietqr_bank  TEXT;
  v_vietqr_acc   TEXT;
  v_vietqr_name  TEXT;
  v_payment_qr   JSONB;
  v_items        JSONB;
  v_payload      JSONB;
  v_idempotency  TEXT;
  v_job_id       BIGINT;
  v_now          TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:print') THEN
    RAISE EXCEPTION 'permission denied: pos:print' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_provisional_bill_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'provisional bill printing is disabled' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.payment_status = 'paid' THEN
    RAISE EXCEPTION 'order already paid; cannot print provisional bill' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.status = 'cancelled' THEN
    RAISE EXCEPTION 'order is cancelled; cannot print provisional bill' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_order.branch_id;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_order.created_by;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_order.tenant_id,
    v_order.branch_id,
    'provisional_bill'
  );

  IF v_printer_id IS NULL THEN
    RAISE EXCEPTION 'no active receipt printer for branch %', v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  IF p_qr_content IS NOT NULL AND length(trim(p_qr_content)) > 0 THEN
    SELECT value INTO v_qr_type
    FROM public.system_settings
    WHERE tenant_id = v_order.tenant_id AND key = 'payment_qr_type';
    v_qr_type := COALESCE(v_qr_type, 'vietqr');

    IF v_qr_type = 'vietqr' THEN
      SELECT value INTO v_vietqr_bank FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_bank_code';
      SELECT value INTO v_vietqr_acc FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_no';
      SELECT value INTO v_vietqr_name FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_name';
    END IF;

    v_payment_qr := jsonb_build_object(
      'type',          v_qr_type,
      'content',       p_qr_content,
      'header_label',  COALESCE(p_qr_header_label, UPPER(v_qr_type)),
      'account_no',    v_vietqr_acc,
      'account_name',  v_vietqr_name,
      'amount',        v_order.total_amount,
      'description',   'DH ' || v_order.order_number
    );
  END IF;

  v_items := public.bill_line_items(p_order_id);

  v_payload := jsonb_build_object(
    'kind',             'provisional_bill',
    'branch_name',      COALESCE(v_branch.name, ''),
    'branch_address',   COALESCE(v_branch.address, ''),
    'branch_phone',     COALESCE(v_branch.phone, ''),
    'branch_tax_code',  COALESCE(v_branch_tax, ''),
    'order_number',     v_order.order_number,
    'order_type',       v_order.order_type,
    'table_number',     v_table_no,
    'cashier_name',     COALESCE(v_cashier_name, ''),
    'note',             v_order.note,
    'items',            COALESCE(v_items, '[]'::jsonb),
    'subtotal',         v_order.subtotal,
    'tax_amount',       v_order.tax_amount,
    'service_charge',   v_order.service_charge,
    'discount_amount',  v_order.discount_amount,
    'total_amount',     v_order.total_amount,
    'payment_qr',       v_payment_qr,
    'created_at',       to_char(v_order.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS'),
    'printed_at',       to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || p_order_id::TEXT
    || ':provisional:' || extract(epoch from v_now)::BIGINT::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  )
  VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'provisional_bill',
    p_order_id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET payload = EXCLUDED.payload
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'order_id',   p_order_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'qr_type',    v_qr_type
  );
END;
$$;


--
-- Name: enqueue_receipt_print(bigint, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_receipt_print(p_order_id bigint, p_cash_received numeric DEFAULT NULL::numeric, p_cash_change numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid          UUID;
  v_is_service   BOOLEAN := (auth.role() = 'service_role');
  v_actor        UUID;
  v_order        public.orders%ROWTYPE;
  v_branch       public.branches%ROWTYPE;
  v_table_no     INT;
  v_printer_id   BIGINT;
  v_cashier_name TEXT;
  v_branch_tax   TEXT;
  v_qr_type      TEXT;
  v_vietqr_bank  TEXT;
  v_vietqr_acc   TEXT;
  v_vietqr_name  TEXT;
  v_payment_ref  TEXT;
  v_qr_content   TEXT;
  v_payment_qr   JSONB;
  v_items        JSONB;
  v_payload      JSONB;
  v_idempotency  TEXT;
  v_job_id       BIGINT;
  v_now          TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_is_service THEN
    IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
      RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
    END IF;

    IF NOT (
      public.has_permission(v_order.branch_id, 'pos:print')
      OR public.has_permission(v_order.branch_id, 'pos:reprint_receipt')
    ) THEN
      RAISE EXCEPTION 'permission denied: pos:print' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_actor := COALESCE(v_uid, v_order.created_by);

  SELECT * INTO v_branch FROM public.branches WHERE id = v_order.branch_id;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_order.created_by;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_order.tenant_id,
    v_order.branch_id,
    'receipt'
  );

  IF v_printer_id IS NULL THEN
    RAISE EXCEPTION 'no active receipt printer for branch %', v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  IF p_cash_received IS NOT NULL OR p_cash_change IS NOT NULL THEN
    UPDATE public.orders
       SET cash_received = p_cash_received,
           cash_change   = p_cash_change
     WHERE id = p_order_id;
  END IF;

  SELECT provider_ref INTO v_payment_ref
  FROM public.payments
  WHERE order_id = p_order_id
    AND tenant_id = v_order.tenant_id
    AND status <> 'failed'
    AND provider_ref ~* ('^(' || public.vietqr_payment_code_prefix()
          || ' [A-Z0-9]{12}|VQRLOAMB20260626100157757 [A-Z0-9]{12}|VQRLOAMB[0-9]{17}|DH[A-Z0-9]{3,12})$')
  ORDER BY id DESC
  LIMIT 1;

  SELECT value INTO v_qr_type
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'payment_qr_type';
  v_qr_type := COALESCE(v_qr_type, 'vietqr');

  IF v_qr_type = 'vietqr' AND v_payment_ref IS NOT NULL THEN
    SELECT value INTO v_vietqr_bank FROM public.system_settings
     WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_bank_code';
    SELECT value INTO v_vietqr_acc FROM public.system_settings
     WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_no';
    SELECT value INTO v_vietqr_name FROM public.system_settings
     WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_name';

    BEGIN
      v_qr_content := public.print_vietqr_emvco(
        v_vietqr_bank,
        v_vietqr_acc,
        v_vietqr_name,
        v_order.total_amount,
        v_payment_ref
      );
    EXCEPTION WHEN OTHERS THEN
      v_qr_content := NULL;
      RAISE WARNING '[enqueue_receipt_print] vietqr emv build failed for order %: %',
        p_order_id, SQLERRM;
    END;

    IF v_qr_content IS NOT NULL THEN
      v_payment_qr := jsonb_build_object(
        'type',         'vietqr',
        'content',      v_qr_content,
        'header_label', upper(COALESCE(v_vietqr_bank, ''))
                          || ' (BIN ' || public.print_vietqr_bank_bin(v_vietqr_bank) || ')',
        'account_no',   v_vietqr_acc,
        'account_name', v_vietqr_name,
        'amount',       v_order.total_amount,
        'description',  v_payment_ref
      );
    END IF;
  END IF;

  v_items := public.bill_line_items(p_order_id);

  v_payload := jsonb_build_object(
    'kind',             'receipt',
    'branch_name',      COALESCE(v_branch.name, ''),
    'branch_address',   COALESCE(v_branch.address, ''),
    'branch_phone',     COALESCE(v_branch.phone, ''),
    'branch_tax_code',  COALESCE(v_branch_tax, ''),
    'order_number',     v_order.order_number,
    'order_type',       v_order.order_type,
    'table_number',     v_table_no,
    'cashier_name',     COALESCE(v_cashier_name, ''),
    'note',             v_order.note,
    'items',            COALESCE(v_items, '[]'::jsonb),
    'subtotal',         v_order.subtotal,
    'tax_amount',       v_order.tax_amount,
    'service_charge',   v_order.service_charge,
    'discount_amount',  v_order.discount_amount,
    'total_amount',     v_order.total_amount,
    'payment_method',   v_order.payment_method,
    'payment_qr',       v_payment_qr,
    'cash_received',    p_cash_received,
    'cash_change',      p_cash_change,
    'created_at',       to_char(v_order.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS'),
    'printed_at',       to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || p_order_id::TEXT || ':receipt';

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  )
  VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'receipt',
    p_order_id, v_payload, v_idempotency, v_actor
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET
    payload    = EXCLUDED.payload,
    printer_id = EXCLUDED.printer_id,
    status = CASE
               WHEN public.print_jobs.status IN ('failed','expired')
               THEN 'pending'
               WHEN public.print_jobs.status = 'printed' AND NOT v_is_service
               THEN 'pending'
               ELSE public.print_jobs.status
             END,
    last_error       = NULL,
    claimed_by_agent = NULL,
    claimed_at       = NULL
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'order_id',   p_order_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id
  );
END;
$_$;


--
-- Name: enqueue_shift_close_print(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_shift_close_print(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid                 UUID;
  v_session             RECORD;
  v_branch              RECORD;
  v_cashier_name        TEXT;
  v_approver_name       TEXT;
  v_branch_tax          TEXT;
  v_printer_id          BIGINT;
  v_breakdown           JSONB;
  v_total_revenue       NUMERIC(15,2);
  v_discount_total      NUMERIC(15,2);
  v_item_breakdown      JSONB;
  v_total_item_quantity INT;
  v_payload             JSONB;
  v_idempotency         TEXT;
  v_job_id              BIGINT;
  v_now                 TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, status, opening_cash, closing_cash,
         expected_cash, cash_difference, opened_at, closed_at, closed_by,
         note, variance_approval_note, variance_approver_user_id
  INTO v_session
  FROM public.pos_sessions
  WHERE id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_session.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_session.status <> 'closed' THEN
    RAISE EXCEPTION 'session not closed yet' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission_any('pos:close_shift') THEN
    RAISE EXCEPTION 'permission denied: pos:close_shift' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_session.branch_id;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_session.closed_by;

  IF v_session.variance_approver_user_id IS NOT NULL THEN
    SELECT full_name INTO v_approver_name
    FROM public.profiles WHERE id = v_session.variance_approver_user_id;
  END IF;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_session.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_session.tenant_id,
    v_session.branch_id,
    'shift_close_report'
  );

  IF v_printer_id IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'method',  payment_method,
      'count',   cnt,
      'amount',  amount
    ) ORDER BY payment_method), '[]'::jsonb),
    COALESCE(SUM(amount), 0)
  INTO v_breakdown, v_total_revenue
  FROM (
    SELECT
      COALESCE(payment_method, 'unknown') AS payment_method,
      COUNT(*) AS cnt,
      SUM(total_amount) AS amount
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY payment_method
  ) AS grp;

  SELECT COALESCE(SUM(discount_amount), 0)
  INTO v_discount_total
  FROM public.orders
  WHERE pos_session_id = p_session_id
    AND tenant_id = v_session.tenant_id
    AND payment_status = 'paid'
    AND status <> 'cancelled';

  WITH paid_items AS (
    SELECT
      oi.item_name,
      oi.quantity,
      oi.unit_price,
      CASE
        WHEN jsonb_typeof(oi.modifiers) = 'array' THEN oi.modifiers
        ELSE '[]'::jsonb
      END AS modifiers,
      CASE
        WHEN jsonb_typeof(oi.sides) = 'array' THEN oi.sides
        ELSE '[]'::jsonb
      END AS sides
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE o.pos_session_id = p_session_id
      AND o.tenant_id = v_session.tenant_id
      AND o.payment_status = 'paid'
      AND o.status <> 'cancelled'
      AND oi.status <> 'cancelled'
  ),
  item_unit_prices AS (
    SELECT
      pi.item_name,
      pi.quantity,
      pi.unit_price,
      pi.modifiers,
      pi.sides,
      COALESCE((
        SELECT SUM(COALESCE(NULLIF(m->>'price', '')::numeric, 0))
        FROM jsonb_array_elements(pi.modifiers) AS m
      ), 0) AS modifier_unit_sum,
      COALESCE((
        SELECT SUM(
          COALESCE(NULLIF(s->>'price', '')::numeric, 0)
          * COALESCE(NULLIF(s->>'quantity', '')::numeric, 1)
        )
        FROM jsonb_array_elements(pi.sides) AS s
      ), 0) AS side_unit_sum
    FROM paid_items pi
  ),
  main_agg AS (
    SELECT
      item_name AS name,
      'main'::TEXT AS source,
      COALESCE(SUM(COALESCE(quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(GREATEST(0, COALESCE(unit_price, 0) - modifier_unit_sum - side_unit_sum) * COALESCE(quantity, 0)), 0) AS revenue,
      1 AS source_order
    FROM item_unit_prices
    GROUP BY item_name
  ),
  side_agg AS (
    SELECT
      COALESCE(NULLIF(s->>'name', ''), NULLIF(s->>'side_item_name', ''), 'Side')::TEXT AS name,
      'side'::TEXT AS source,
      COALESCE(SUM(COALESCE(NULLIF(s->>'quantity', '')::numeric, 1) * COALESCE(pi.quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(
        COALESCE(NULLIF(s->>'price', '')::numeric, 0)
        * COALESCE(NULLIF(s->>'quantity', '')::numeric, 1)
        * COALESCE(pi.quantity, 0)
      ), 0) AS revenue,
      2 AS source_order
    FROM item_unit_prices pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.sides) AS s
    GROUP BY COALESCE(NULLIF(s->>'name', ''), NULLIF(s->>'side_item_name', ''), 'Side')
  ),
  mod_agg AS (
    SELECT
      COALESCE(NULLIF(m->>'name', ''), 'Modifier')::TEXT AS name,
      'modifier'::TEXT AS source,
      COALESCE(SUM(COALESCE(pi.quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(COALESCE(NULLIF(m->>'price', '')::numeric, 0) * COALESCE(pi.quantity, 0)), 0) AS revenue,
      3 AS source_order
    FROM item_unit_prices pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.modifiers) AS m
    GROUP BY COALESCE(NULLIF(m->>'name', ''), 'Modifier')
  ),
  all_items AS (
    SELECT name, source, qty, revenue, source_order FROM main_agg
    UNION ALL
    SELECT name, source, qty, revenue, source_order FROM side_agg
    UNION ALL
    SELECT name, source, qty, revenue, source_order FROM mod_agg
  )
  SELECT
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'name', name,
        'source', source,
        'qty', qty,
        'revenue', revenue
      )
      ORDER BY revenue DESC, qty DESC, source_order, name
    ), '[]'::jsonb),
    COALESCE(SUM(qty), 0)::INT
  INTO v_item_breakdown, v_total_item_quantity
  FROM all_items;

  v_payload := jsonb_build_object(
    'kind',                  'shift_close_report',
    'branch_name',           COALESCE(v_branch.name, ''),
    'branch_address',        COALESCE(v_branch.address, ''),
    'branch_phone',          COALESCE(v_branch.phone, ''),
    'branch_tax_code',       COALESCE(v_branch_tax, ''),
    'session_id',            p_session_id,
    'cashier_name',          COALESCE(v_cashier_name, ''),
    'opened_at',             to_char(v_session.opened_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS'),
    'closed_at',             to_char(v_session.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS'),
    'opening_cash',          v_session.opening_cash,
    'closing_cash',          v_session.closing_cash,
    'expected_cash',         v_session.expected_cash,
    'cash_difference',       v_session.cash_difference,
    'note',                  v_session.note,
    'variance_note',         v_session.variance_approval_note,
    'variance_approver',     v_approver_name,
    'paid_order_count',      (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND payment_status = 'paid'
         AND status <> 'cancelled'
    ),
    'unpaid_order_count',    (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND payment_status <> 'paid'
         AND status <> 'cancelled'
    ),
    'cancelled_order_count', (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND status = 'cancelled'
    ),
    'payment_breakdown',     v_breakdown,
    'total_revenue',         v_total_revenue,
    'discount_total',        COALESCE(v_discount_total, 0),
    'total_item_quantity',   COALESCE(v_total_item_quantity, 0),
    'item_breakdown',        COALESCE(v_item_breakdown, '[]'::jsonb),
    'printed_at',            to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'session:' || p_session_id::TEXT || ':shift_close';

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_session.tenant_id, v_session.branch_id, v_printer_id, 'shift_close_report',
    NULL, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET
    payload = EXCLUDED.payload,
    status  = CASE WHEN public.print_jobs.status IN ('failed', 'expired')
                   THEN 'pending' ELSE public.print_jobs.status END,
    last_error = NULL,
    claimed_by_agent = NULL,
    claimed_at = NULL
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'session_id', p_session_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id
  );
END;
$$;


--
-- Name: FUNCTION enqueue_shift_close_print(p_session_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_shift_close_print(p_session_id bigint) IS 'Enqueue data-driven shift-close print payload. Includes paid-order discount_total and sold-item breakdown ordered by revenue desc.';


--
-- Name: ensure_branch_inventory_location_defaults(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_branch_inventory_location_defaults(p_tenant_id bigint, p_branch_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_branch_kind text;
  v_warehouse_id bigint;
  v_warehouse_name text;
BEGIN
  SELECT branch.branch_kind
  INTO v_branch_kind
  FROM public.branches AS branch
  WHERE branch.id = p_branch_id
    AND branch.tenant_id = p_tenant_id
    AND branch.is_active IS TRUE
  FOR UPDATE;

  IF NOT FOUND
     OR v_branch_kind NOT IN ('branch', 'central_supply', 'central_kitchen') THEN
    RETURN;
  END IF;

  v_warehouse_name := CASE v_branch_kind
    WHEN 'central_supply' THEN 'Kho Tổng'
    WHEN 'central_kitchen' THEN 'Kho Bếp Trung Tâm'
    ELSE 'Kho chi nhánh'
  END;

  SELECT location.id
  INTO v_warehouse_id
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = p_tenant_id
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
  ORDER BY
    location.is_active DESC,
    (
      location.is_default_receive
      AND location.is_default_issue
      AND location.is_default_consumption
    ) DESC,
    location.sort_order,
    location.id
  LIMIT 1
  FOR UPDATE;

  IF v_warehouse_id IS NULL THEN
    SELECT location.id
    INTO v_warehouse_id
    FROM public.inventory_locations AS location
    WHERE location.tenant_id = p_tenant_id
      AND location.branch_id = p_branch_id
      AND location.code = 'main_warehouse'
    LIMIT 1
    FOR UPDATE;
  END IF;

  UPDATE public.inventory_locations AS location
  SET is_active = CASE
        WHEN location.location_kind = 'warehouse'
          OR v_branch_kind = 'branch'
          THEN FALSE
        ELSE location.is_active
      END,
      is_default_receive = FALSE,
      is_default_issue = FALSE,
      is_default_consumption = FALSE,
      updated_at = now()
  WHERE location.tenant_id = p_tenant_id
    AND location.branch_id = p_branch_id
    AND (v_warehouse_id IS NULL OR location.id <> v_warehouse_id)
    AND (
      location.location_kind = 'warehouse'
      OR v_branch_kind = 'branch'
      OR location.is_default_receive
      OR location.is_default_issue
      OR location.is_default_consumption
    );

  IF v_warehouse_id IS NULL THEN
    INSERT INTO public.inventory_locations (
      tenant_id,
      branch_id,
      code,
      name,
      location_kind,
      is_active,
      is_default_receive,
      is_default_issue,
      is_default_consumption,
      sort_order
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      'main_warehouse',
      v_warehouse_name,
      'warehouse',
      TRUE,
      TRUE,
      TRUE,
      TRUE,
      0
    )
    RETURNING id INTO v_warehouse_id;
  ELSE
    UPDATE public.inventory_locations
    SET name = v_warehouse_name,
        location_kind = 'warehouse',
        is_active = TRUE,
        is_default_receive = TRUE,
        is_default_issue = TRUE,
        is_default_consumption = TRUE,
        sort_order = 0,
        updated_at = now()
    WHERE id = v_warehouse_id;
  END IF;

  IF v_branch_kind = 'branch' THEN
    INSERT INTO public.branch_feature_flags (
      branch_id,
      flag_key,
      enabled,
      enabled_at,
      disabled_at,
      updated_at
    )
    VALUES (
      p_branch_id,
      'pos_stock_outcome_posting',
      TRUE,
      now(),
      NULL,
      now()
    )
    ON CONFLICT (branch_id, flag_key) DO NOTHING;
  END IF;
END;
$$;


--
-- Name: ensure_order_payment_code(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_order_payment_code(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_order RECORD;
  v_code text;
  v_try int;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT id, tenant_id, branch_id, status, payment_status, payment_code
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = p_tenant_id
    AND branch_id = p_branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.has_permission(v_order.branch_id, 'pos:use')
    OR public.has_permission(v_order.branch_id, 'pos:print')
  ) THEN
    RAISE EXCEPTION 'permission denied: pos:use' USING ERRCODE = '42501';
  END IF;

  IF v_order.status = 'cancelled' THEN
    RAISE EXCEPTION 'order_cancelled' USING ERRCODE = '22023';
  END IF;

  IF v_order.payment_code IS NULL
     OR (
       v_order.payment_code ~* '^DH[A-Z0-9]{3,12}$'
       AND NOT EXISTS (
         SELECT 1
           FROM public.payments p
          WHERE p.order_id = v_order.id
            AND p.tenant_id = v_order.tenant_id
            AND p.branch_id = v_order.branch_id
            AND p.status <> 'failed'
       )
     )
  THEN
    FOR v_try IN 1..20 LOOP
      v_code := public.generate_order_payment_code();
      BEGIN
        UPDATE public.orders
           SET payment_code = v_code,
               updated_at = now()
         WHERE id = v_order.id
         RETURNING payment_code INTO v_order.payment_code;
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        IF v_try = 20 THEN
          RAISE;
        END IF;
      END;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'payment_code', v_order.payment_code
  );
END;
$_$;


--
-- Name: escalate_round_4(bigint, bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_round_4(p_session_id bigint, p_ingredient_id bigint, p_final_qty numeric, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_session public.stocktake_sessions%ROWTYPE;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT session.*
  INTO v_session
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant
  FOR UPDATE OF session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_session.branch_id,
    'inventory:stocktake_recount'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_session.status <> 'in_progress' THEN
    RAISE EXCEPTION 'session not in_progress'
      USING ERRCODE = '22023';
  END IF;
  IF v_session.current_round <> 4 THEN
    RAISE EXCEPTION 'round_4_not_active'
      USING ERRCODE = '22023';
  END IF;
  IF p_final_qty IS NULL
     OR p_final_qty < 0
     OR p_final_qty = 'NaN'::numeric
     OR p_final_qty = 'Infinity'::numeric
     OR p_final_qty = '-Infinity'::numeric THEN
    RAISE EXCEPTION 'final_quantity_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF length(coalesce(p_note, '')) < 20 THEN
    RAISE EXCEPTION
      'escalation note must be at least 20 characters'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.stocktake_lines (
    tenant_id,
    session_id,
    ingredient_id,
    system_quantity,
    counted_quantity,
    counted_by,
    counted_at,
    round_no,
    variance_reason,
    is_final,
    needs_recount,
    abc_class,
    entry_unit_id
  )
  SELECT
    v_tenant,
    p_session_id,
    p_ingredient_id,
    round_one.system_quantity,
    p_final_qty,
    v_uid,
    now(),
    4,
    '[ROUND4] ' || p_note,
    TRUE,
    FALSE,
    round_one.abc_class,
    round_one.entry_unit_id
  FROM public.stocktake_lines AS round_one
  WHERE round_one.tenant_id = v_tenant
    AND round_one.session_id = p_session_id
    AND round_one.ingredient_id = p_ingredient_id
    AND round_one.round_no = 1
  ON CONFLICT (session_id, ingredient_id, round_no) DO UPDATE
  SET counted_quantity = EXCLUDED.counted_quantity,
      counted_by = EXCLUDED.counted_by,
      counted_at = EXCLUDED.counted_at,
      variance_reason = EXCLUDED.variance_reason,
      is_final = TRUE,
      entry_unit_id = EXCLUDED.entry_unit_id;

  UPDATE public.stocktake_lines
  SET counted_quantity = p_final_qty,
      is_final = TRUE,
      needs_recount = FALSE,
      variance_reason = coalesce(variance_reason, '')
        || E'\n[ROUND4 escalated by '
        || v_uid::text
        || ']'
  WHERE tenant_id = v_tenant
    AND session_id = p_session_id
    AND ingredient_id = p_ingredient_id
    AND round_no = 1;
END;
$$;


--
-- Name: expire_stuck_print_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_stuck_print_jobs(p_stale_after_seconds integer DEFAULT 300) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_revived INT;
BEGIN
  UPDATE public.print_jobs
     SET status           = 'pending',
         claimed_by_agent = NULL,
         claimed_at       = NULL,
         last_error       = COALESCE(last_error, '') ||
                            CASE WHEN COALESCE(last_error, '') = '' THEN '' ELSE E'\n' END ||
                            'reaped: stuck in processing >' ||
                            p_stale_after_seconds || 's at ' || now()::text
   WHERE status     = 'processing'
     AND claimed_at < (now() - make_interval(secs => p_stale_after_seconds));

  GET DIAGNOSTICS v_revived = ROW_COUNT;
  RETURN v_revived;
END;
$$;


--
-- Name: feedback_take_rate_bucket(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feedback_take_rate_bucket(p_scope_type text, p_scope_hash text, p_limit integer, p_window_seconds integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_hits INTEGER;
  v_retry_after_seconds INTEGER;
BEGIN
  IF p_scope_type NOT IN ('token', 'token_ip')
     OR p_scope_hash IS NULL
     OR p_scope_hash !~ '^[0-9a-f]{64}$'
     OR p_limit < 1
     OR p_window_seconds < 1 THEN
    RAISE EXCEPTION 'feedback_invalid_rate_limit_input' USING ERRCODE = '22023';
  END IF;

  v_window_start := to_timestamp(
    floor(extract(epoch FROM now()) / p_window_seconds) * p_window_seconds
  );

  DELETE FROM public.feedback_rate_buckets r
  WHERE r.ctid IN (
    SELECT stale.ctid
    FROM public.feedback_rate_buckets stale
    WHERE stale.expires_at <= now()
    ORDER BY stale.expires_at
    LIMIT 100
  );

  INSERT INTO public.feedback_rate_buckets (
    scope_type, scope_hash, window_start, hits, expires_at
  )
  VALUES (
    p_scope_type,
    p_scope_hash,
    v_window_start,
    1,
    v_window_start + make_interval(secs => p_window_seconds * 2)
  )
  ON CONFLICT (scope_type, scope_hash, window_start)
  DO UPDATE SET hits = public.feedback_rate_buckets.hits + 1
  RETURNING hits INTO v_hits;

  IF v_hits > p_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      ceil(extract(epoch FROM (
        v_window_start
        + make_interval(secs => p_window_seconds)
        - clock_timestamp()
      )))::integer
    );
    RAISE EXCEPTION 'feedback_rate_limited'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'retryAfterSeconds', v_retry_after_seconds
            )::text;
  END IF;

  RETURN v_hits;
END;
$_$;


--
-- Name: fetch_tax_invoice_issue_attention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fetch_tax_invoice_issue_attention() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden_finance_view' USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', job.id,
        'order_id', job.order_id,
        'order_number', sales_order.order_number,
        'status', job.status,
        'provider_ref', invoice.provider_ref,
        'invoice_number', invoice.invoice_number,
        'last_error', job.last_error,
        'updated_at', job.updated_at,
        'payment_method', payment.method,
        'tax_invoice_id', job.tax_invoice_id
      ) ORDER BY job.updated_at DESC
    )
    FROM public.tax_invoice_issue_jobs job
    LEFT JOIN public.orders sales_order
      ON sales_order.id = job.order_id
      AND sales_order.tenant_id = job.tenant_id
    LEFT JOIN public.payments payment
      ON payment.id = job.payment_id
      AND payment.tenant_id = job.tenant_id
    LEFT JOIN public.tax_invoices invoice
      ON invoice.id = job.tax_invoice_id
      AND invoice.tenant_id = job.tenant_id
    WHERE job.tenant_id = v_tenant
      AND job.status IN ('blocked', 'reconcile_required')
  ), '[]'::jsonb);
END;
$$;


--
-- Name: finalize_paid_order(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_paid_order(p_order_id bigint, p_actor_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order record;
  v_actor uuid := COALESCE(p_actor_id, auth.uid());
BEGIN
  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.status, o.created_by
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_actor := COALESCE(v_actor, v_order.created_by);

  IF v_order.status = 'cancelled' THEN
    RETURN;
  END IF;

  IF v_order.status = 'completed' THEN
    PERFORM public.post_pos_sale_consumption_if_ready(p_order_id, v_actor);
    RETURN;
  END IF;

  UPDATE public.orders
  SET status = 'completed',
      updated_at = now()
  WHERE id = p_order_id;

  IF v_actor IS NOT NULL THEN
    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_order.tenant_id,
      p_order_id,
      v_order.status,
      'completed',
      v_actor,
      'auto_complete_on_payment'
    );
  END IF;

  PERFORM public.post_pos_sale_consumption_if_ready(p_order_id, v_actor);
END;
$$;


--
-- Name: FUNCTION finalize_paid_order(p_order_id bigint, p_actor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalize_paid_order(p_order_id bigint, p_actor_id uuid) IS 'Marks order completed after payment. If stock-outcome posting is enabled, sale consumption posts only after KDS first_ready_at proves the kitchen made the order.';


--
-- Name: finalize_stocktake(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_stocktake(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  PERFORM session.id
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;

  RETURN public.complete_stocktake(p_session_id);
END;
$$;


--
-- Name: finance_views_last_refresh(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_views_last_refresh() RETURNS TABLE(last_run timestamp with time zone, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT d.end_time, d.status
  FROM cron.job_run_details d
  JOIN cron.job j ON j.jobid = d.jobid
  WHERE j.jobname = 'refresh-finance-views-daily'
  ORDER BY d.start_time DESC
  LIMIT 1;
END;
$$;


--
-- Name: find_payment_order_desync(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_payment_order_desync(p_since timestamp with time zone DEFAULT (now() - '30 days'::interval)) RETURNS TABLE(payment_id bigint, order_id bigint, tenant_id bigint, branch_id bigint, amount numeric, payment_method text, payment_status text, payment_paid_at timestamp with time zone, order_status text, order_payment_status text, order_created_at timestamp with time zone, age_minutes integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    p.id                                     AS payment_id,
    p.order_id                               AS order_id,
    p.tenant_id                              AS tenant_id,
    p.branch_id                              AS branch_id,
    p.amount                                 AS amount,
    p.method                                 AS payment_method,
    p.status                                 AS payment_status,
    p.paid_at                                AS payment_paid_at,
    o.status                                 AS order_status,
    o.payment_status                         AS order_payment_status,
    o.created_at                             AS order_created_at,
    GREATEST(
      EXTRACT(EPOCH FROM (now() - p.paid_at))::INTEGER / 60,
      0
    )                                        AS age_minutes
  FROM public.payments p
  JOIN public.orders   o ON o.id = p.order_id AND o.tenant_id = p.tenant_id
  WHERE p.tenant_id = public.auth_tenant_id()
    AND p.status = 'completed'
    AND COALESCE(o.payment_status, 'unpaid') <> 'paid'
    AND p.paid_at >= p_since
    AND public.has_permission_any('finance:view')
  ORDER BY p.paid_at DESC;
$$;


--
-- Name: FUNCTION find_payment_order_desync(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.find_payment_order_desync(p_since timestamp with time zone) IS 'Ops reconciliation: rows are payments marked completed whose order did not flip to paid. Returns empty for callers without finance:view. Lookback window defaults to 30 days.';


--
-- Name: finish_tax_invoice_issue_job_as_system(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_tax_invoice_issue_job_as_system(p_job_id bigint, p_status text, p_last_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job public.tax_invoice_issue_jobs%ROWTYPE;
  v_invoice_status text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('completed', 'blocked', 'reconcile_required', 'queued') THEN
    RAISE EXCEPTION 'invalid_tax_invoice_issue_job_status' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_job
  FROM public.tax_invoice_issue_jobs
  WHERE id = p_job_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_issue_job_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_job.status <> 'processing' THEN
    RAISE EXCEPTION 'tax_invoice_issue_job_not_processing' USING ERRCODE = '22023';
  END IF;

  IF p_status = 'completed' THEN
    SELECT invoice.status INTO v_invoice_status
    FROM public.tax_invoices invoice
    WHERE invoice.id = v_job.tax_invoice_id
      AND invoice.tenant_id = v_job.tenant_id;
    IF NOT FOUND OR v_invoice_status <> 'issued' THEN
      RAISE EXCEPTION 'tax_invoice_issue_job_not_issued' USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.tax_invoice_issue_jobs
  SET status = p_status,
      locked_until = NULL,
      last_error = p_last_error,
      updated_at = now()
  WHERE id = v_job.id;

  RETURN jsonb_build_object('job_id', v_job.id, 'status', p_status);
END;
$$;


--
-- Name: force_close_stale_attendance(bigint, bigint, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.force_close_stale_attendance(p_tenant_id bigint, p_branch_id bigint, p_attendance_id bigint, p_approved_by uuid, p_note text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_record public.attendance_records%ROWTYPE;
  v_requester uuid;
  v_shift_start time;
  v_shift_end time;
  v_shift_end_at timestamp;
  v_now_local timestamp := now() AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_check_out timestamptz;
BEGIN
  IF v_actor IS NULL
     OR v_actor <> p_approved_by
     OR p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'not_authenticated_or_mismatch' USING ERRCODE = '28000';
  END IF;

  SELECT attendance.*
  INTO v_record
  FROM public.attendance_records attendance
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = p_tenant_id
    AND attendance.branch_id IS NOT DISTINCT FROM p_branch_id
    AND attendance.check_in IS NOT NULL
    AND attendance.check_out IS NULL
  FOR UPDATE;
  IF v_record.id IS NULL THEN
    RAISE EXCEPTION 'stale_attendance_request_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_record.branch_id, 'hr:force_close_attendance') THEN
    RAISE EXCEPTION 'force_close_scope_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT employee.profile_id, shift_row.start_time, shift_row.end_time
  INTO v_requester, v_shift_start, v_shift_end
  FROM public.employees employee
  LEFT JOIN public.shifts shift_row
    ON shift_row.id = v_record.shift_id
   AND shift_row.tenant_id = v_record.tenant_id
  WHERE employee.id = v_record.employee_id
    AND employee.tenant_id = v_record.tenant_id;
  IF v_requester IS NULL OR v_actor = v_requester THEN
    RAISE EXCEPTION 'cannot_force_close_own_attendance' USING ERRCODE = '42501';
  END IF;

  IF v_shift_start IS NULL OR v_shift_end IS NULL THEN
    IF v_record.date >= v_now_local::date THEN
      RAISE EXCEPTION 'stale_attendance_request_not_found' USING ERRCODE = 'P0002';
    END IF;
  ELSE
    v_shift_end_at := v_record.date + v_shift_end;
    IF v_shift_end <= v_shift_start THEN
      v_shift_end_at := v_shift_end_at + interval '1 day';
    END IF;
    IF v_now_local < v_shift_end_at THEN
      RAISE EXCEPTION 'stale_attendance_request_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  UPDATE public.attendance_records attendance
  SET check_out = v_record.check_in,
      checkout_approved_at = now(),
      checkout_approved_by = v_actor,
      checkout_approval_note = COALESCE(
        NULLIF(btrim(p_note), ''),
        'Force closed: missed checkout, no workday credit'
      ),
      updated_at = now()
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = p_tenant_id
    AND attendance.branch_id IS NOT DISTINCT FROM p_branch_id
    AND attendance.check_out IS NULL
  RETURNING attendance.check_out INTO v_check_out;

  PERFORM public.log_audit(
    'update',
    'attendance_record',
    p_attendance_id,
    jsonb_build_object('check_out', NULL),
    jsonb_build_object(
      'check_out', v_check_out,
      'reason', NULLIF(btrim(COALESCE(p_note, '')), '')
    )
  );

  RETURN v_check_out;
END;
$$;


--
-- Name: FUNCTION force_close_stale_attendance(p_tenant_id bigint, p_branch_id bigint, p_attendance_id bigint, p_approved_by uuid, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.force_close_stale_attendance(p_tenant_id bigint, p_branch_id bigint, p_attendance_id bigint, p_approved_by uuid, p_note text) IS 'Exact-branch stale attendance close for Owner or Branch Manager, with self and role-hierarchy guards.';


--
-- Name: fulfill_stock_request_lines(bigint, text, bigint, bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfill_stock_request_lines(p_request_id bigint, p_fulfill_site_kind text, p_from_branch_id bigint, p_from_location_id bigint, p_item_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_request public.stock_requests%ROWTYPE;
  v_from_kind text;
  v_to_location_id bigint;
  v_lines jsonb := '[]'::jsonb;
  v_item public.stock_request_items%ROWTYPE;
  v_result jsonb;
  v_transfer_id bigint;
  v_stock numeric(15,3);
  v_required numeric(15,3);
  v_count integer := 0;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_fulfill_site_kind NOT IN ('central_supply', 'central_kitchen')
     OR p_item_ids IS NULL
     OR cardinality(p_item_ids) = 0
     OR cardinality(p_item_ids) <> (
       SELECT count(DISTINCT item_id)
       FROM unnest(p_item_ids) AS ids(item_id)
     ) THEN
    RAISE EXCEPTION 'stock_request_fulfill_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission_any('inventory:request_fulfill') THEN
    RAISE EXCEPTION 'forbidden_request_fulfill' USING ERRCODE = '42501';
  END IF;

  SELECT request.*
  INTO v_request
  FROM public.stock_requests AS request
  WHERE request.id = p_request_id
    AND request.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND OR v_request.status <> 'submitted' THEN
    RAISE EXCEPTION 'stock_request_not_fulfillable'
      USING ERRCODE = '23514';
  END IF;

  SELECT branch.branch_kind
  INTO v_from_kind
  FROM public.branches AS branch
  WHERE branch.id = p_from_branch_id
    AND branch.tenant_id = v_tenant
    AND branch.is_active;

  IF v_from_kind IS DISTINCT FROM p_fulfill_site_kind THEN
    RAISE EXCEPTION 'fulfill_from_site_mismatch'
      USING ERRCODE = '23514';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND (
       public.auth_branch_id() IS DISTINCT FROM p_from_branch_id
       OR CASE public.auth_role()
         WHEN 'central_supply_ops' THEN 'central_supply'
         WHEN 'central_kitchen_lead' THEN 'central_kitchen'
         ELSE NULL
       END IS DISTINCT FROM p_fulfill_site_kind
     ) THEN
    RAISE EXCEPTION 'forbidden_request_fulfill_scope'
      USING ERRCODE = '42501';
  END IF;

  SELECT location.id
  INTO v_to_location_id
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = v_tenant
    AND location.branch_id = v_request.branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active
  ORDER BY location.id
  LIMIT 1;

  IF v_to_location_id IS NULL THEN
    RAISE EXCEPTION 'stock_request_destination_warehouse_missing'
      USING ERRCODE = '23514';
  END IF;

  FOR v_item IN
    SELECT item.*
    FROM public.stock_request_items AS item
    WHERE item.request_id = p_request_id
      AND item.tenant_id = v_tenant
      AND item.id = ANY (p_item_ids)
      AND item.fulfill_site_kind = p_fulfill_site_kind
      AND item.status = 'pending'
    ORDER BY item.ingredient_id
    FOR UPDATE
  LOOP
    v_count := v_count + 1;
    v_required := public.inv_to_base(
      v_item.ingredient_id,
      v_item.entry_unit_id,
      v_item.quantity
    );

    SELECT stock.current_quantity
    INTO v_stock
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = p_from_branch_id
      AND stock.location_id = p_from_location_id
      AND stock.ingredient_id = v_item.ingredient_id
    FOR UPDATE;

    IF NOT FOUND OR COALESCE(v_stock, 0) < v_required THEN
      RAISE EXCEPTION 'insufficient_stock:%', v_item.ingredient_id
        USING ERRCODE = 'P0001';
    END IF;

    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object(
        'ingredient_id', v_item.ingredient_id,
        'entry_unit_id', v_item.entry_unit_id,
        'quantity', v_item.quantity
      )
    );
  END LOOP;

  IF v_count <> cardinality(p_item_ids) THEN
    RAISE EXCEPTION 'stock_request_lines_not_pending'
      USING ERRCODE = '23514';
  END IF;

  v_result := public.create_stock_transfer_draft(
    p_from_branch_id,
    v_request.branch_id,
    '',
    'Fulfill stock request ' || v_request.request_number,
    NULL,
    v_lines,
    p_from_location_id,
    v_to_location_id
  );

  v_transfer_id := COALESCE(
    (v_result ->> 'id')::bigint,
    (v_result ->> 'transfer_id')::bigint
  );

  UPDATE public.stock_transfers
  SET stock_request_id = p_request_id,
      updated_at = now()
  WHERE id = v_transfer_id
    AND tenant_id = v_tenant;

  UPDATE public.stock_request_items
  SET status = 'allocated',
      transfer_id = v_transfer_id,
      updated_at = now()
  WHERE request_id = p_request_id
    AND tenant_id = v_tenant
    AND id = ANY (p_item_ids)
    AND status = 'pending';

  RETURN jsonb_build_object(
    'request_id', p_request_id,
    'transfer_id', v_transfer_id,
    'transfer_number', v_result ->> 'transfer_number'
  );
END;
$$;


--
-- Name: generate_order_payment_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_order_payment_code() RETURNS text
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  SELECT public.vietqr_payment_code_prefix() || ' ' || string_agg(
    substr(
      'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',
      1 + (get_byte(extensions.gen_random_bytes(1), 0) % 36),
      1
    ),
    ''
  )
  FROM generate_series(1, 12);
$$;


--
-- Name: get_ap_aging(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ap_aging() RETURNS TABLE(supplier_id bigint, supplier_name text, buckets jsonb, total_outstanding numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_today date;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.auth_is_owner(auth.uid())
    OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  v_today := (pg_catalog.now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;

  RETURN QUERY
  WITH scoped AS (
    SELECT
      si.supplier_id AS s_id,
      GREATEST(
        si.total_amount
          - COALESCE(si.paid_amount, 0)
          - COALESCE(si.credit_applied_amount, 0),
        0
      ) AS outstanding,
      CASE
        WHEN si.due_date IS NULL OR (v_today - si.due_date) <= 0 THEN 'current'
        WHEN (v_today - si.due_date) <= 30 THEN 'days_1_30'
        WHEN (v_today - si.due_date) <= 60 THEN 'days_31_60'
        WHEN (v_today - si.due_date) <= 90 THEN 'days_61_90'
        ELSE 'days_over_90'
      END AS bucket
    FROM public.supplier_invoices AS si
    WHERE si.tenant_id = v_tenant
      AND si.total_amount
        - COALESCE(si.paid_amount, 0)
        - COALESCE(si.credit_applied_amount, 0) > 0
  )
  SELECT
    a.s_id AS supplier_id,
    COALESCE(s.name, 'NCC #' || a.s_id) AS supplier_name,
    pg_catalog.jsonb_build_object(
      'current', pg_catalog.jsonb_build_object(
        'count', COUNT(*) FILTER (WHERE a.bucket = 'current'),
        'total', COALESCE(SUM(a.outstanding) FILTER (WHERE a.bucket = 'current'), 0)
      ),
      'days_1_30', pg_catalog.jsonb_build_object(
        'count', COUNT(*) FILTER (WHERE a.bucket = 'days_1_30'),
        'total', COALESCE(SUM(a.outstanding) FILTER (WHERE a.bucket = 'days_1_30'), 0)
      ),
      'days_31_60', pg_catalog.jsonb_build_object(
        'count', COUNT(*) FILTER (WHERE a.bucket = 'days_31_60'),
        'total', COALESCE(SUM(a.outstanding) FILTER (WHERE a.bucket = 'days_31_60'), 0)
      ),
      'days_61_90', pg_catalog.jsonb_build_object(
        'count', COUNT(*) FILTER (WHERE a.bucket = 'days_61_90'),
        'total', COALESCE(SUM(a.outstanding) FILTER (WHERE a.bucket = 'days_61_90'), 0)
      ),
      'days_over_90', pg_catalog.jsonb_build_object(
        'count', COUNT(*) FILTER (WHERE a.bucket = 'days_over_90'),
        'total', COALESCE(SUM(a.outstanding) FILTER (WHERE a.bucket = 'days_over_90'), 0)
      )
    ) AS buckets,
    COALESCE(SUM(a.outstanding), 0) AS total_outstanding
  FROM scoped AS a
  LEFT JOIN public.suppliers AS s
    ON s.id = a.s_id
    AND s.tenant_id = v_tenant
  GROUP BY a.s_id, s.name
  ORDER BY COALESCE(SUM(a.outstanding), 0) DESC;
END;
$$;


--
-- Name: get_bank_ledger_movement_since(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bank_ledger_movement_since(p_since timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_bank_in numeric;
  v_bank_out numeric;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT
    COALESCE(sum(transaction.amount) FILTER (
      WHERE transaction.transfer_type = 'in'
    ), 0),
    COALESCE(sum(transaction.amount) FILTER (
      WHERE transaction.transfer_type = 'out'
    ), 0)
  INTO v_bank_in, v_bank_out
  FROM public.bank_transactions transaction
  WHERE transaction.tenant_id = v_tenant_id
    AND transaction.occurred_at >= p_since;

  RETURN jsonb_build_object(
    'bank_in', v_bank_in,
    'bank_out', v_bank_out
  );
END;
$$;


--
-- Name: FUNCTION get_bank_ledger_movement_since(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_bank_ledger_movement_since(p_since timestamp with time zone) IS 'Returns signed movement from canonical bank_transactions only. Matching state never changes bank balance.';


--
-- Name: get_branch_menu_daily_limits_for_pos(bigint, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_branch_menu_daily_limits_for_pos(p_branch_id bigint, p_exclude_hold_tokens uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(menu_item_id bigint, is_disabled boolean, sold_today integer, stock_capacity integer, manual_limit_quantity integer, pending_unfinalized_demand integer, active_hold_demand integer, available_to_sell integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH ctx AS (
    SELECT public.auth_tenant_id() AS tenant_id,
           public.auth_role() AS role,
           public.auth_branch_id() AS branch_id,
           (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS limit_date,
           public.is_feature_enabled(p_branch_id, 'pos_stock_outcome_posting') AS gate_eff
  )
  SELECT
    a.menu_item_id,
    a.is_disabled,
    a.sold_today,
    a.stock_capacity,
    a.manual_limit_quantity,
    a.pending_unfinalized_demand,
    a.active_hold_demand,
    a.available_to_sell
  FROM ctx
  JOIN LATERAL public.branch_menu_limit_availability(
    ctx.tenant_id,
    p_branch_id,
    ctx.limit_date,
    ctx.gate_eff,
    p_exclude_hold_tokens
  ) a ON TRUE
  WHERE ctx.tenant_id IS NOT NULL
    AND (
      ctx.role = 'owner'
      OR ctx.branch_id = p_branch_id
    )
    AND (
      a.limit_id IS NOT NULL
      OR ctx.gate_eff
    );
$$;


--
-- Name: FUNCTION get_branch_menu_daily_limits_for_pos(p_branch_id bigint, p_exclude_hold_tokens uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_branch_menu_daily_limits_for_pos(p_branch_id bigint, p_exclude_hold_tokens uuid[]) IS 'Row filter and availability gate both key on gate_eff = pos_stock_outcome_posting alone — D065 §1 collapses the two-flag AND into one owner-facing switch. p_exclude_hold_tokens passes the caller''s live hold token(s) through so its own reservation is not double-counted on refetch. Slimmed shape — see branch_menu_limit_availability comment.';


--
-- Name: get_branch_menu_stock_capacity(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_branch_menu_stock_capacity(p_branch_id bigint) RETURNS TABLE(menu_item_id bigint, stock_capacity integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ctx AS (
    SELECT b.tenant_id, b.id AS branch_id
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = public.auth_tenant_id()
      AND (public.auth_role() IN ('owner') OR public.auth_branch_id() = p_branch_id)
  )
  SELECT r.menu_item_id,
         public.compute_menu_item_stock_capacity(c.tenant_id, c.branch_id, r.menu_item_id)
  FROM ctx c
  JOIN (SELECT DISTINCT menu_item_id, tenant_id FROM public.recipes) r
    ON r.tenant_id = c.tenant_id;
$$;


--
-- Name: FUNCTION get_branch_menu_stock_capacity(p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_branch_menu_stock_capacity(p_branch_id bigint) IS 'Per menu item with a recipe: live sellable portions from warehouse stock at p_branch_id (owner or own-branch). Admin display for Định mức món bán.';


--
-- Name: get_branch_revenue_target_progress(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_branch_revenue_target_progress(p_branch_id bigint, p_year_month date DEFAULT NULL::date) RETURNS TABLE(branch_id bigint, year_month date, net_revenue_mtd numeric, target_amount numeric, progress_pct numeric, gap_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_role text := public.auth_role();
  v_caller_branch bigint := public.auth_branch_id();
  v_month date;
  v_today date;
  v_end date;
  v_start_utc timestamptz;
  v_end_utc timestamptz;
  v_has_tenant_scope boolean;
  v_branch_ids bigint[];
  v_net numeric := 0;
  v_target numeric;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL THEN
    RAISE EXCEPTION 'invalid_branch' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = v_tenant
      AND b.branch_kind = 'branch'
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'branch_manager' THEN
    IF v_caller_branch IS NULL OR v_caller_branch <> p_branch_id THEN
      RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
    END IF;
  ELSIF v_role IN ('owner', 'accountant') THEN
    SELECT scope.has_tenant_scope, scope.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
    FROM private.finance_scope(v_uid, 'finance:view') scope;

    IF NOT (
      v_has_tenant_scope
      OR p_branch_id = ANY(COALESCE(v_branch_ids, ARRAY[]::bigint[]))
    ) THEN
      RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_today := (timezone('Asia/Ho_Chi_Minh', now()))::date;
  v_month := date_trunc(
    'month',
    COALESCE(p_year_month, v_today)::timestamp
  )::date;

  IF date_trunc('month', v_today::timestamp)::date = v_month THEN
    v_end := v_today;
  ELSE
    v_end := (v_month + interval '1 month' - interval '1 day')::date;
  END IF;

  v_start_utc := v_month::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end_utc := (v_end + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  WITH paid AS (
    SELECT
      payment.order_id,
      payment.id AS payment_id,
      payment.paid_at,
      orders.subtotal,
      orders.discount_amount
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_tenant
      AND payment.branch_id = p_branch_id
      AND payment.status = 'completed'
      AND payment.paid_at >= v_start_utc
      AND payment.paid_at < v_end_utc
  ),
  order_facts AS (
    SELECT DISTINCT ON (paid.order_id)
      paid.subtotal,
      paid.discount_amount
    FROM paid
    ORDER BY paid.order_id, paid.paid_at, paid.payment_id
  )
  SELECT COALESCE(sum(order_facts.subtotal - order_facts.discount_amount), 0)
  INTO v_net
  FROM order_facts;

  SELECT targets.target_amount
  INTO v_target
  FROM public.branch_revenue_targets targets
  WHERE targets.tenant_id = v_tenant
    AND targets.branch_id = p_branch_id
    AND targets.year_month = v_month;

  RETURN QUERY
  SELECT
    p_branch_id,
    v_month,
    v_net,
    v_target,
    CASE
      WHEN v_target IS NULL OR v_target <= 0 THEN NULL::numeric
      ELSE round((v_net / v_target) * 100, 1)
    END,
    CASE
      WHEN v_target IS NULL THEN NULL::numeric
      ELSE greatest(v_target - v_net, 0)
    END;
END;
$$;


--
-- Name: FUNCTION get_branch_revenue_target_progress(p_branch_id bigint, p_year_month date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_branch_revenue_target_progress(p_branch_id bigint, p_year_month date) IS 'Branch-scoped MTD/month Doanh thu thuần vs monthly target. BM same-branch or finance:view.';


--
-- Name: get_cash_ledger_movement_since(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cash_ledger_movement_since(p_since timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_cash_collections numeric;
  v_cash_refunds numeric;
  v_cash_expenses numeric;
  v_cash_supplier_payments numeric;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(sum(payment.amount), 0)
  INTO v_cash_collections
  FROM public.payments payment
  WHERE payment.tenant_id = v_tenant_id
    AND payment.method = 'cash'
    AND payment.status IN ('completed', 'refunded')
    AND payment.paid_at >= p_since;

  SELECT COALESCE(sum(refund.amount), 0)
  INTO v_cash_refunds
  FROM public.refunds refund
  WHERE refund.tenant_id = v_tenant_id
    AND refund.status = 'approved'
    AND refund.payout_method = 'cash'
    AND refund.approved_at >= p_since;

  SELECT COALESCE(sum(expense.amount), 0)
  INTO v_cash_expenses
  FROM public.expenses expense
  WHERE expense.tenant_id = v_tenant_id
    AND expense.payment_method = 'cash'
    AND expense.paid_at >= p_since;

  SELECT COALESCE(sum(supplier_payment.amount), 0)
  INTO v_cash_supplier_payments
  FROM public.supplier_payments supplier_payment
  WHERE supplier_payment.tenant_id = v_tenant_id
    AND supplier_payment.payment_method = 'cash'
    AND supplier_payment.payment_date >= p_since;

  RETURN jsonb_build_object(
    'cash_collections', v_cash_collections,
    'cash_refunds', v_cash_refunds,
    'cash_expenses', v_cash_expenses,
    'cash_supplier_payments', v_cash_supplier_payments,
    'cash_variance_adjustments', 0
  );
END;
$$;


--
-- Name: FUNCTION get_cash_ledger_movement_since(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_cash_ledger_movement_since(p_since timestamp with time zone) IS 'Returns tenant cash-book movements from order payments, refunds, cash expenses, and cash supplier payments. POS session counts and variances are reconciliation evidence only.';


--
-- Name: get_cash_variance_action_target(bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cash_variance_action_target(p_branch_id bigint, p_start_date date, p_end_date date) RETURNS TABLE(session_id bigint, branch_id bigint, cash_difference numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_start timestamptz;
  v_end timestamptz;
BEGIN
  IF v_actor IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;
  IF p_branch_id IS NOT NULL THEN
    IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_start := p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end := (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  SELECT session.id, session.branch_id, session.cash_difference
  FROM public.pos_sessions session
  WHERE session.tenant_id = v_tenant
    AND session.status = 'closed'
    AND session.closed_at >= v_start
    AND session.closed_at < v_end
    AND session.cash_difference IS NOT NULL
    AND session.variance_resolution_type IS NULL
    AND abs(session.cash_difference) > GREATEST(
      50000::numeric,
      ROUND(COALESCE(session.expected_cash, 0) * 0.005, 2)
    )
    AND (p_branch_id IS NULL OR session.branch_id = p_branch_id)
    AND public.has_permission(session.branch_id, 'finance:view')
  ORDER BY abs(session.cash_difference) DESC, session.closed_at, session.id
  LIMIT 1;
END;
$$;


--
-- Name: FUNCTION get_cash_variance_action_target(p_branch_id bigint, p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_cash_variance_action_target(p_branch_id bigint, p_start_date date, p_end_date date) IS 'Returns the highest-value unresolved POS cash variance so Finance can deep-link to the exact session.';


--
-- Name: get_cash_variance_summary(bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cash_variance_summary(p_branch_id bigint, p_start_date date, p_end_date date) RETURNS TABLE(session_count bigint, total_variance numeric, abs_variance_total numeric, short_count bigint, short_total numeric, over_count bigint, over_total numeric, worst_cashiers jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid    uuid;
  v_tenant bigint;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'start/end required' USING ERRCODE = '22023';
  END IF;

  IF p_start_date > p_end_date THEN
    RAISE EXCEPTION 'start > end' USING ERRCODE = '22023';
  END IF;

  IF p_branch_id IS NOT NULL THEN
    IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission_any('finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH closed_in_range AS (
    SELECT
      ps.id,
      ps.opened_by AS cashier_id,
      ps.cash_difference
    FROM public.pos_sessions ps
    WHERE ps.tenant_id = v_tenant
      AND ps.status = 'closed'
      AND ps.closed_at IS NOT NULL
      AND ps.cash_difference IS NOT NULL
      AND ps.variance_approval_note IS NULL
      AND abs(ps.cash_difference) > GREATEST(
        50000::numeric,
        ROUND(COALESCE(ps.expected_cash, 0) * 0.005, 2)
      )
      AND (ps.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date >= p_start_date
      AND (ps.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= p_end_date
      AND (
        (p_branch_id IS NOT NULL AND ps.branch_id = p_branch_id)
        OR (p_branch_id IS NULL AND public.has_permission(ps.branch_id, 'finance:view'))
      )
  ),
  agg AS (
    SELECT
      COUNT(*)::bigint AS session_count,
      COALESCE(SUM(c.cash_difference), 0) AS total_variance,
      COALESCE(SUM(ABS(c.cash_difference)), 0) AS abs_variance_total,
      COUNT(*) FILTER (WHERE c.cash_difference < 0)::bigint AS short_count,
      COALESCE(SUM(c.cash_difference) FILTER (WHERE c.cash_difference < 0), 0) AS short_total,
      COUNT(*) FILTER (WHERE c.cash_difference > 0)::bigint AS over_count,
      COALESCE(SUM(c.cash_difference) FILTER (WHERE c.cash_difference > 0), 0) AS over_total
    FROM closed_in_range c
  ),
  by_cashier AS (
    SELECT
      c.cashier_id,
      COALESCE(pr.full_name, '—') AS cashier_name,
      COUNT(*)::bigint AS session_count,
      SUM(c.cash_difference) AS net_variance,
      SUM(ABS(c.cash_difference)) AS abs_variance
    FROM closed_in_range c
    LEFT JOIN public.profiles pr ON pr.id = c.cashier_id
    GROUP BY c.cashier_id, pr.full_name
  ),
  worst_top3 AS (
    SELECT bc.*
    FROM by_cashier bc
    WHERE bc.abs_variance > 0
    ORDER BY bc.abs_variance DESC
    LIMIT 3
  ),
  worst_json AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'cashier_id',     w.cashier_id,
          'cashier_name',   w.cashier_name,
          'session_count',  w.session_count,
          'net_variance',   w.net_variance,
          'abs_variance',   w.abs_variance
        )
        ORDER BY w.abs_variance DESC
      ),
      '[]'::jsonb
    ) AS rows
    FROM worst_top3 w
  )
  SELECT
    agg.session_count,
    agg.total_variance,
    agg.abs_variance_total,
    agg.short_count,
    agg.short_total,
    agg.over_count,
    agg.over_total,
    worst_json.rows AS worst_cashiers
  FROM agg
  CROSS JOIN worst_json;
END;
$$;


--
-- Name: FUNCTION get_cash_variance_summary(p_branch_id bigint, p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_cash_variance_summary(p_branch_id bigint, p_start_date date, p_end_date date) IS 'Aggregate unresolved over-threshold POS cash variance over closed sessions in range. A session is unresolved while variance_approval_note is NULL.';


--
-- Name: get_checkout_review_queue(bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_checkout_review_queue(p_branch_id bigint, p_include_rows boolean DEFAULT true) RETURNS TABLE(pending_count bigint, rows jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_role text := public.auth_role();
  v_actor_branch_id bigint;
  v_is_owner boolean;
BEGIN
  SELECT profile.branch_id INTO v_actor_branch_id
  FROM public.profiles profile
  WHERE profile.id = v_actor AND profile.tenant_id = v_tenant_id AND profile.is_active;
  v_is_owner := v_role = 'owner' AND public.auth_is_owner(v_actor);

  IF v_actor IS NULL OR (
    NOT v_is_owner
    AND (
      v_role <> 'branch_manager'
      OR p_branch_id IS NULL
      OR v_actor_branch_id IS DISTINCT FROM p_branch_id
      OR NOT public.has_permission(p_branch_id, 'hr:approve_checkout')
    )
  ) THEN
    RAISE EXCEPTION 'checkout_review_queue_not_allowed' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH visible_requests AS MATERIALIZED (
    SELECT attendance.id, attendance.date, attendance.branch_id,
           attendance.check_in, attendance.checkout_requested_at,
           attendance.checkout_requested_by_role,
           attendance.checkout_approval_target_roles, attendance.employee_id,
           branch.name AS branch_name, employee.employee_code,
           requester.full_name AS employee_full_name,
           private.staff_role_from_position_code(position.code) AS requester_role,
           shift_row.name AS shift_name, shift_row.start_time AS shift_start_time,
           shift_row.end_time AS shift_end_time
    FROM public.attendance_records attendance
    JOIN public.employees employee
      ON employee.id = attendance.employee_id AND employee.tenant_id = attendance.tenant_id
    JOIN public.profiles requester
      ON requester.id = employee.profile_id AND requester.tenant_id = employee.tenant_id
    JOIN public.positions position
      ON position.id = requester.position_id AND position.tenant_id = requester.tenant_id
    LEFT JOIN public.branches branch
      ON branch.id = attendance.branch_id AND branch.tenant_id = attendance.tenant_id
    LEFT JOIN public.shifts shift_row
      ON shift_row.id = attendance.shift_id AND shift_row.tenant_id = attendance.tenant_id
    WHERE attendance.tenant_id = v_tenant_id
      AND attendance.check_out IS NULL
      AND attendance.checkout_requested_at IS NOT NULL
      AND requester.id <> v_actor
      AND employee.is_active
      AND requester.is_active
      AND position.is_active
      AND (
        (
          v_is_owner
          AND 'owner' = ANY(attendance.checkout_approval_target_roles)
          AND (p_branch_id IS NULL OR attendance.branch_id IS NOT DISTINCT FROM p_branch_id)
        )
        OR (
          NOT v_is_owner
          AND attendance.branch_id = p_branch_id
          AND 'branch_manager' = ANY(attendance.checkout_approval_target_roles)
        )
      )
  ), limited_requests AS (
    SELECT * FROM visible_requests
    ORDER BY checkout_requested_at, id
    LIMIT 100
  )
  SELECT count(*)::bigint,
    CASE WHEN p_include_rows THEN COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', limited.id,
        'date', limited.date,
        'branch_id', limited.branch_id,
        'check_in', limited.check_in,
        'checkout_requested_at', limited.checkout_requested_at,
        'checkout_requested_by_role', limited.checkout_requested_by_role,
        'checkout_approval_target_roles', limited.checkout_approval_target_roles,
        'employee_id', limited.employee_id,
        'branch_name', limited.branch_name,
        'employee_code', limited.employee_code,
        'employee_full_name', limited.employee_full_name,
        'requester_role', limited.requester_role,
        'shift_name', limited.shift_name,
        'shift_start_time', limited.shift_start_time,
        'shift_end_time', limited.shift_end_time,
        'checklist', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', item.id, 'title', item.title,
            'is_done', item.is_done, 'is_required', item.is_required
          ) ORDER BY item.sort_order, item.id)
          FROM public.attendance_checklist_items item
          WHERE item.attendance_record_id = limited.id
            AND item.tenant_id = v_tenant_id
        ), '[]'::jsonb)
      ) ORDER BY limited.checkout_requested_at, limited.id)
      FROM limited_requests limited
    ), '[]'::jsonb) ELSE '[]'::jsonb END
  FROM visible_requests;
END;
$$;


--
-- Name: FUNCTION get_checkout_review_queue(p_branch_id bigint, p_include_rows boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_checkout_review_queue(p_branch_id bigint, p_include_rows boolean) IS 'Returns only checkout requests actionable by the live exact-branch hierarchy: Branch Manager reviews current staff; Owner reviews the current Branch Manager.';


--
-- Name: get_daily_revenue(bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_daily_revenue(p_branch_id bigint, p_start_date date, p_end_date date) RETURNS TABLE(date date, branch_id bigint, tenant_id bigint, order_count bigint, total_revenue numeric, total_tax numeric, cash_revenue numeric, vietqr_revenue numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH paid_payments AS MATERIALIZED (
    SELECT
      (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS paid_date,
      p.id AS payment_id,
      p.order_id,
      p.branch_id,
      p.tenant_id,
      p.method,
      p.amount AS payment_amount,
      p.paid_at,
      o.tax_amount
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.branch_id = p_branch_id
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
  ),
  payment_daily AS (
    SELECT
      pp.paid_date,
      pp.branch_id,
      pp.tenant_id,
      COALESCE(SUM(pp.payment_amount), 0) AS total_revenue,
      COALESCE(SUM(pp.payment_amount) FILTER (WHERE pp.method = 'cash'), 0) AS cash_revenue,
      COALESCE(SUM(pp.payment_amount) FILTER (WHERE pp.method = 'vietqr'), 0) AS vietqr_revenue
    FROM paid_payments pp
    GROUP BY pp.paid_date, pp.branch_id, pp.tenant_id
  ),
  order_daily AS (
    SELECT
      oq.paid_date,
      oq.branch_id,
      oq.tenant_id,
      COUNT(*)::BIGINT AS order_count,
      COALESCE(SUM(oq.tax_amount), 0) AS total_tax
    FROM (
      SELECT DISTINCT ON (pp.paid_date, pp.branch_id, pp.tenant_id, pp.order_id)
        pp.paid_date,
        pp.branch_id,
        pp.tenant_id,
        pp.order_id,
        pp.tax_amount,
        pp.paid_at,
        pp.payment_id
      FROM paid_payments pp
      ORDER BY pp.paid_date, pp.branch_id, pp.tenant_id, pp.order_id, pp.paid_at, pp.payment_id
    ) oq
    GROUP BY oq.paid_date, oq.branch_id, oq.tenant_id
  )
  SELECT
    pd.paid_date AS date,
    pd.branch_id,
    pd.tenant_id,
    od.order_count,
    pd.total_revenue,
    od.total_tax,
    pd.cash_revenue,
    pd.vietqr_revenue
  FROM payment_daily pd
  JOIN order_daily od
    ON od.paid_date = pd.paid_date
   AND od.branch_id = pd.branch_id
   AND od.tenant_id = pd.tenant_id
  ORDER BY pd.paid_date;
END;
$$;


--
-- Name: FUNCTION get_daily_revenue(p_branch_id bigint, p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_daily_revenue(p_branch_id bigint, p_start_date date, p_end_date date) IS 'Live paid-at money collected by day for one branch. total_revenue and method breakdowns use payments.amount; order_count and tax use distinct paid orders.';


--
-- Name: get_finance_current_funds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_finance_current_funds() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_opening public.finance_fund_entries%ROWTYPE;
  v_cash_movement jsonb;
  v_bank_movement jsonb;
  v_cash_adjustments numeric;
  v_bank_adjustments numeric;
  v_cash_collections numeric;
  v_cash_refunds numeric;
  v_cash_expenses numeric;
  v_cash_supplier_payments numeric;
  v_bank_in numeric;
  v_bank_out numeric;
  v_legacy_settings_present boolean;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_opening
  FROM public.finance_fund_entries entry
  WHERE entry.tenant_id = v_tenant_id
    AND entry.entry_type = 'opening';

  SELECT EXISTS (
    SELECT 1
    FROM public.system_settings setting
    WHERE setting.tenant_id = v_tenant_id
      AND setting.key IN (
        'cash_opening_balance',
        'bank_opening_balance',
        'cash_opening_date'
      )
  )
  INTO v_legacy_settings_present;

  IF v_opening.id IS NULL THEN
    RETURN jsonb_build_object(
      'has_opening', false,
      'opening_entry_id', NULL,
      'opening_cash', 0,
      'opening_bank', 0,
      'opening_effective_at', NULL,
      'cash_collections', 0,
      'cash_refunds', 0,
      'cash_expenses', 0,
      'cash_supplier_payments', 0,
      'cash_variance_adjustments', 0,
      'cash_adjustments', 0,
      'cash_current', 0,
      'bank_in', 0,
      'bank_out', 0,
      'bank_adjustments', 0,
      'bank_current', 0,
      'legacy_settings_present', v_legacy_settings_present
    );
  END IF;

  v_cash_movement :=
    public.get_cash_ledger_movement_since(v_opening.effective_at);
  v_bank_movement :=
    public.get_bank_ledger_movement_since(v_opening.effective_at);

  SELECT
    COALESCE(sum(entry.cash_delta), 0),
    COALESCE(sum(entry.bank_delta), 0)
  INTO v_cash_adjustments, v_bank_adjustments
  FROM public.finance_fund_entries entry
  WHERE entry.tenant_id = v_tenant_id
    AND entry.entry_type = 'adjustment'
    AND entry.effective_at >= v_opening.effective_at;

  v_cash_collections :=
    COALESCE((v_cash_movement ->> 'cash_collections')::numeric, 0);
  v_cash_refunds :=
    COALESCE((v_cash_movement ->> 'cash_refunds')::numeric, 0);
  v_cash_expenses :=
    COALESCE((v_cash_movement ->> 'cash_expenses')::numeric, 0);
  v_cash_supplier_payments :=
    COALESCE((v_cash_movement ->> 'cash_supplier_payments')::numeric, 0);
  v_bank_in := COALESCE((v_bank_movement ->> 'bank_in')::numeric, 0);
  v_bank_out := COALESCE((v_bank_movement ->> 'bank_out')::numeric, 0);

  RETURN jsonb_build_object(
    'has_opening', true,
    'opening_entry_id', v_opening.id,
    'opening_cash', v_opening.cash_delta,
    'opening_bank', v_opening.bank_delta,
    'opening_effective_at', v_opening.effective_at,
    'cash_collections', v_cash_collections,
    'cash_refunds', v_cash_refunds,
    'cash_expenses', v_cash_expenses,
    'cash_supplier_payments', v_cash_supplier_payments,
    'cash_variance_adjustments', 0,
    'cash_adjustments', v_cash_adjustments,
    'cash_current',
      v_opening.cash_delta
      + v_cash_collections
      - v_cash_refunds
      - v_cash_expenses
      - v_cash_supplier_payments
      + v_cash_adjustments,
    'bank_in', v_bank_in,
    'bank_out', v_bank_out,
    'bank_adjustments', v_bank_adjustments,
    'bank_current',
      v_opening.bank_delta
      + v_bank_in
      - v_bank_out
      + v_bank_adjustments,
    'legacy_settings_present', v_legacy_settings_present
  );
END;
$$;


--
-- Name: FUNCTION get_finance_current_funds(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_finance_current_funds() IS 'Returns immutable opening funds, canonical cash and bank movements, audited adjustments, and current balances for callers with finance:view.';


--
-- Name: get_finance_dashboard_summary(date, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_finance_dashboard_summary(p_start_date date, p_end_date date, p_branch_id bigint DEFAULT NULL::bigint) RETURNS TABLE(invoice_attention_count bigint, invoice_issued_count bigint, invoice_not_required_count bigint, failed_webhook_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.branches b
      WHERE b.id = p_branch_id
        AND b.tenant_id = v_tenant
    ) THEN
      RAISE EXCEPTION 'branch not found' USING ERRCODE = '22023';
    END IF;
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH scoped_tax_invoices AS MATERIALIZED (
    SELECT ti.*
    FROM public.tax_invoices ti
    WHERE ti.tenant_id = v_tenant
      AND (
        (p_branch_id IS NOT NULL AND ti.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR ti.branch_id = ANY(v_branch_ids)
          )
        )
      )
  ),
  scoped_failed_webhooks AS MATERIALIZED (
    SELECT we.id
    FROM public.webhook_events we
    LEFT JOIN public.payments p
      ON p.id = we.payment_id
     AND p.tenant_id = we.tenant_id
    WHERE we.tenant_id = v_tenant
      AND we.processing_status = 'failed'
      AND we.created_at >= v_start_utc
      AND we.created_at < v_end_utc
      AND (
        (p_branch_id IS NOT NULL AND p.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR p.branch_id = ANY(v_branch_ids)
          )
        )
      )
  )
  SELECT
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_tax_invoices ti
      WHERE ti.status IN ('draft', 'signing', 'submitted')
    ) AS invoice_attention_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_tax_invoices ti
      WHERE ti.status = 'issued'
        AND ti.issued_at >= v_start_utc
        AND ti.issued_at < v_end_utc
    ) AS invoice_issued_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_tax_invoices ti
      WHERE ti.status = 'not_required'
        AND ti.created_at >= v_start_utc
        AND ti.created_at < v_end_utc
    ) AS invoice_not_required_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_failed_webhooks
    ) AS failed_webhook_count;
END;
$$;


--
-- Name: get_finance_reconciliation_attention(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_finance_reconciliation_attention(p_start_date date, p_end_date date) RETURNS TABLE(unmatched_bank_count bigint, unmatched_bank_amount numeric, unmatched_money_in_count bigint, unmatched_money_out_count bigint, missing_vietqr_count bigint, missing_vietqr_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_start timestamptz;
  v_end timestamptz;
BEGIN
  IF v_actor IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  v_start := p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end := (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  WITH unmatched_bank AS (
    SELECT transaction.transfer_type, transaction.amount
    FROM public.bank_transactions transaction
    WHERE transaction.tenant_id = v_tenant
      AND transaction.occurred_at >= v_start
      AND transaction.occurred_at < v_end
      AND NOT EXISTS (
        SELECT 1
        FROM public.bank_transaction_reconciliation_matches reconciliation
        WHERE reconciliation.tenant_id = transaction.tenant_id
          AND reconciliation.bank_transaction_id = transaction.id
      )
  ),
  missing_vietqr AS (
    SELECT payment.amount
    FROM public.payments payment
    WHERE payment.tenant_id = v_tenant
      AND payment.method = 'vietqr'
      AND payment.status = 'completed'
      AND payment.paid_at >= v_start
      AND payment.paid_at < v_end
      AND NOT EXISTS (
        SELECT 1
        FROM public.bank_transaction_reconciliation_matches reconciliation
        WHERE reconciliation.tenant_id = payment.tenant_id
          AND reconciliation.payment_id = payment.id
      )
  )
  SELECT
    (SELECT COUNT(*)::bigint FROM unmatched_bank),
    (SELECT COALESCE(SUM(entry.amount), 0) FROM unmatched_bank entry),
    (SELECT COUNT(*)::bigint FROM unmatched_bank entry WHERE entry.transfer_type = 'in'),
    (SELECT COUNT(*)::bigint FROM unmatched_bank entry WHERE entry.transfer_type = 'out'),
    (SELECT COUNT(*)::bigint FROM missing_vietqr),
    (SELECT COALESCE(SUM(entry.amount), 0) FROM missing_vietqr entry);
END;
$$;


--
-- Name: FUNCTION get_finance_reconciliation_attention(p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_finance_reconciliation_attention(p_start_date date, p_end_date date) IS 'Counts unmatched canonical SePay movements and completed VietQR payments without canonical bank evidence for the selected VN business-date range.';


--
-- Name: get_food_cost(bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_food_cost(p_branch_id bigint DEFAULT NULL::bigint, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(period_start date, period_end date, branch_id bigint, tenant_id bigint, menu_item_id bigint, item_name text, quantity_sold numeric, revenue numeric, ingredient_cost numeric, food_cost_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    UUID;
  v_tenant BIGINT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant FROM public.profiles pr WHERE pr.id = v_uid;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL THEN
    IF NOT public.has_permission_any('finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
    SELECT
      m.period_start,
      m.period_end,
      m.branch_id,
      m.tenant_id,
      m.menu_item_id,
      m.item_name,
      m.quantity_sold::NUMERIC,
      m.revenue,
      m.ingredient_cost,
      m.food_cost_pct
    FROM public.mv_food_cost m
    WHERE m.tenant_id = v_tenant
      AND (p_branch_id IS NOT NULL OR public.has_permission(m.branch_id, 'finance:view'))
      AND (p_branch_id IS NULL OR m.branch_id = p_branch_id)
      AND (p_start_date IS NULL OR m.period_start >= p_start_date)
      AND (p_end_date IS NULL OR m.period_start <= p_end_date)
    ORDER BY m.food_cost_pct DESC NULLS LAST;
END;
$$;


--
-- Name: get_ingredient_abc_class(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ingredient_abc_class(p_branch_id bigint, p_ingredient_id bigint) RETURNS character
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id(); v_class CHAR; v_age INT;
BEGIN
  IF v_tenant IS NULL THEN RETURN NULL; END IF;
  SELECT class INTO v_class FROM public.ingredient_abc_class
    WHERE tenant_id = v_tenant AND branch_id = p_branch_id AND ingredient_id = p_ingredient_id;
  IF FOUND THEN RETURN v_class; END IF;
  SELECT EXTRACT(DAY FROM now() - created_at)::INT INTO v_age FROM public.branches WHERE id = p_branch_id;
  IF v_age IS NULL OR v_age < 30 THEN
    SELECT MODE() WITHIN GROUP (ORDER BY class) INTO v_class
    FROM public.ingredient_abc_class
    WHERE tenant_id = v_tenant AND ingredient_id = p_ingredient_id;
    IF v_class IS NOT NULL THEN RETURN v_class; END IF;
  END IF;
  RETURN NULL;
END; $$;


--
-- Name: get_inventory_alerts(bigint, text[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_alerts(p_branch_id bigint, p_types text[] DEFAULT ARRAY['low_stock'::text, 'out_of_stock'::text, 'negative_stock'::text], p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(alert_type text, severity_rank integer, ingredient_id bigint, ingredient_name text, location_id bigint, location_name text, current_quantity numeric, reorder_point numeric, shortage_ratio numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT (public.has_permission(p_branch_id, 'inventory:read') OR public.has_permission(NULL, 'reports:view_branch') OR public.has_permission(NULL, 'reports:view_tenant')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT (CASE WHEN m.current_quantity < 0 THEN 'negative_stock' WHEN m.current_quantity = 0 THEN 'out_of_stock' ELSE 'low_stock' END)::TEXT,
    (CASE WHEN m.current_quantity < 0 THEN 0 WHEN m.current_quantity = 0 THEN 1 ELSE 2 END)::INT,
    m.ingredient_id, m.ingredient_name, m.location_id, m.location_name, m.current_quantity, m.reorder_point,
    (CASE WHEN m.reorder_point > 0 THEN (m.reorder_point - m.current_quantity) / m.reorder_point ELSE 0 END)::NUMERIC
  FROM public.mv_inventory_stock_current m
  WHERE m.tenant_id = v_tenant AND m.branch_id = p_branch_id AND m.reorder_point IS NOT NULL AND m.current_quantity < m.reorder_point
    AND (('low_stock' = ANY(p_types) AND m.current_quantity > 0) OR ('out_of_stock' = ANY(p_types) AND m.current_quantity = 0) OR ('negative_stock' = ANY(p_types) AND m.current_quantity < 0))
  ORDER BY CASE WHEN m.current_quantity < 0 THEN 0 WHEN m.current_quantity = 0 THEN 1 ELSE 2 END,
           CASE WHEN m.reorder_point > 0 THEN (m.reorder_point - m.current_quantity) / m.reorder_point ELSE 0 END DESC
  LIMIT p_limit OFFSET p_offset;
END; $$;


--
-- Name: get_inventory_dashboard(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_dashboard(p_branch_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_can_cost boolean;
  v_summary jsonb;
  v_locations jsonb;
  v_alerts jsonb;
  v_in_transit jsonb;
  v_refreshed_at timestamptz;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT (
    public.has_permission(p_branch_id, 'inventory:read')
    OR public.has_permission(NULL, 'reports:view_branch')
    OR public.has_permission(NULL, 'reports:view_tenant')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  v_can_cost :=
    public.can_read_inventory_monetary('inventory:valuation_read');

  SELECT refreshed_at
  INTO v_refreshed_at
  FROM public.mv_refresh_log
  WHERE view_name = 'mv_inventory_stock_current';

  SELECT jsonb_build_object(
    'total_skus', COALESCE(COUNT(DISTINCT stock.ingredient_id), 0),
    'location_count', COALESCE(COUNT(DISTINCT stock.location_id), 0),
    'total_quantity', COALESCE(SUM(stock.current_quantity), 0),
    'total_value_vnd',
      CASE WHEN v_can_cost THEN COALESCE(SUM(stock.stock_value), 0) END,
    'alerts_count', (
      SELECT COUNT(*)
      FROM public.mv_inventory_stock_current alert
      WHERE alert.tenant_id = v_tenant
        AND alert.branch_id = p_branch_id
        AND alert.reorder_point IS NOT NULL
        AND alert.current_quantity < alert.reorder_point
    )
  )
  INTO v_summary
  FROM public.mv_inventory_stock_current stock
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = p_branch_id;

  SELECT COALESCE(
    jsonb_agg(location ORDER BY location->>'location_kind', location->>'location_name'),
    '[]'::jsonb
  )
  INTO v_locations
  FROM (
    SELECT jsonb_build_object(
      'location_id', stock.location_id,
      'location_name', MAX(stock.location_name),
      'location_kind', MAX(stock.location_kind),
      'sku_count', COUNT(DISTINCT stock.ingredient_id),
      'total_quantity', SUM(stock.current_quantity),
      'total_value_vnd',
        CASE WHEN v_can_cost THEN SUM(stock.stock_value) END,
      'alerts_count',
        COUNT(*) FILTER (
          WHERE stock.reorder_point IS NOT NULL
            AND stock.current_quantity < stock.reorder_point
        )
    ) AS location
    FROM public.mv_inventory_stock_current stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = p_branch_id
    GROUP BY stock.location_id
  ) grouped_locations;

  SELECT COALESCE(
    jsonb_agg(alert ORDER BY alert->>'severity_rank', alert->>'shortage_ratio' DESC),
    '[]'::jsonb
  )
  INTO v_alerts
  FROM (
    SELECT jsonb_build_object(
      'alert_type',
        CASE
          WHEN stock.current_quantity < 0 THEN 'negative_stock'
          WHEN stock.current_quantity = 0 THEN 'out_of_stock'
          ELSE 'low_stock'
        END,
      'severity_rank',
        CASE
          WHEN stock.current_quantity < 0 THEN 0
          WHEN stock.current_quantity = 0 THEN 1
          ELSE 2
        END,
      'ingredient_id', stock.ingredient_id,
      'ingredient_name', stock.ingredient_name,
      'location_id', stock.location_id,
      'location_name', stock.location_name,
      'current_quantity', stock.current_quantity,
      'reorder_point', stock.reorder_point,
      'shortage_ratio',
        CASE
          WHEN stock.reorder_point > 0
            THEN (stock.reorder_point - stock.current_quantity) / stock.reorder_point
          ELSE 0
        END
    ) AS alert
    FROM public.mv_inventory_stock_current stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = p_branch_id
      AND stock.reorder_point IS NOT NULL
      AND stock.current_quantity < stock.reorder_point
  ) grouped_alerts;

  SELECT COALESCE(jsonb_agg(item ORDER BY item->>'id' DESC), '[]'::jsonb)
  INTO v_in_transit
  FROM (
    SELECT jsonb_build_object(
      'id', transfer.id,
      'transfer_number', transfer.transfer_number,
      'from_branch_name', source_branch.name,
      'to_branch_name', target_branch.name,
      'status', transfer.status
    ) AS item
    FROM public.stock_transfers transfer
    JOIN public.branches source_branch ON source_branch.id = transfer.from_branch_id
    JOIN public.branches target_branch ON target_branch.id = transfer.to_branch_id
    WHERE transfer.tenant_id = v_tenant
      AND (
        transfer.from_branch_id = p_branch_id
        OR transfer.to_branch_id = p_branch_id
      )
      AND transfer.status IN (
        'draft',
        'confirmed_ship',
        'in_transit',
        'confirmed_receive'
      )
  ) grouped_transfers;

  RETURN jsonb_build_object(
    'branch_id', p_branch_id,
    'computed_at', COALESCE(v_refreshed_at, now()),
    'can_view_cost', v_can_cost,
    'summary', v_summary,
    'locations', v_locations,
    'top_alerts', v_alerts,
    'in_transit', v_in_transit
  );
END;
$$;


--
-- Name: get_inventory_valuation_bootstrap_readiness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_valuation_bootstrap_readiness() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     OR NOT public.has_permission_any('inventory:valuation_read') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN private.inventory_valuation_bootstrap_readiness(v_tenant);
END;
$$;


--
-- Name: get_inventory_valuation_period_value(date, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_valuation_period_value(p_start_date date, p_end_date date, p_branch_id bigint DEFAULT NULL::bigint) RETURNS TABLE(branch_id bigint, opening_value numeric, closing_value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('inventory:valuation_read') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'inventory_valuation_period_invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH allocation_impacts AS (
    SELECT
      event.effective_at,
      coalesce(to_account.branch_id, from_account.branch_id) AS event_branch_id,
      CASE
        WHEN event.event_type IN ('invoice_reprice', 'credit_reprice')
          AND to_account.id IS NOT NULL
          THEN allocation.allocated_value
        WHEN to_account.id IS NOT NULL
          THEN allocation.allocated_value
        WHEN from_account.id IS NOT NULL
          THEN -allocation.allocated_value
        ELSE 0::numeric
      END AS value_impact
    FROM public.inventory_value_allocations AS allocation
    JOIN public.inventory_valuation_events AS event
      ON event.id = allocation.valuation_event_id
     AND event.tenant_id = allocation.tenant_id
    LEFT JOIN public.inventory_origin_balances AS to_balance
      ON to_balance.id = allocation.to_balance_id
     AND to_balance.tenant_id = allocation.tenant_id
    LEFT JOIN public.inventory_valuation_accounts AS to_account
      ON to_account.id = to_balance.valuation_account_id
     AND to_account.tenant_id = to_balance.tenant_id
    LEFT JOIN public.inventory_origin_balances AS from_balance
      ON from_balance.id = allocation.from_balance_id
     AND from_balance.tenant_id = allocation.tenant_id
    LEFT JOIN public.inventory_valuation_accounts AS from_account
      ON from_account.id = from_balance.valuation_account_id
     AND from_account.tenant_id = from_balance.tenant_id
    WHERE allocation.tenant_id = v_tenant
      AND coalesce(to_account.branch_id, from_account.branch_id) IS NOT NULL
      AND (
        p_branch_id IS NULL
        OR coalesce(to_account.branch_id, from_account.branch_id) = p_branch_id
      )
  ),
  branch_scope AS (
    SELECT branch.id
    FROM public.branches AS branch
    WHERE branch.tenant_id = v_tenant
      AND (p_branch_id IS NULL OR branch.id = p_branch_id)
  )
  SELECT
    branch.id,
    coalesce(pg_catalog.sum(impact.value_impact) FILTER (
      WHERE impact.effective_at
        < p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'
    ), 0),
    coalesce(pg_catalog.sum(impact.value_impact) FILTER (
      WHERE impact.effective_at
        < (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'
    ), 0)
  FROM branch_scope AS branch
  LEFT JOIN allocation_impacts AS impact
    ON impact.event_branch_id = branch.id
  GROUP BY branch.id
  ORDER BY branch.id;
END;
$$;


--
-- Name: get_inventory_valuation_reconciliation(integer, integer, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_valuation_reconciliation(p_year integer, p_month integer, p_branch_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_quantity_mismatches integer;
  v_value_mismatches integer;
  v_origin_mismatches integer;
  v_total_quantity numeric(20,3);
  v_total_value numeric(20,2);
BEGIN
  IF v_tenant IS NULL OR auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('inventory:valuation_read') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_year < 2000 OR p_month NOT BETWEEN 1 AND 12 THEN
    RAISE EXCEPTION 'inventory_valuation_period_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    pg_catalog.count(*) FILTER (
      WHERE account.quantity IS DISTINCT FROM stock.current_quantity
    ),
    coalesce(pg_catalog.sum(account.quantity), 0),
    coalesce(pg_catalog.sum(account.book_value), 0)
  INTO v_quantity_mismatches, v_total_quantity, v_total_value
  FROM public.inventory_valuation_accounts AS account
  FULL JOIN public.stock_levels AS stock
    ON stock.tenant_id = account.tenant_id
   AND stock.branch_id = account.branch_id
   AND stock.location_id = account.location_id
   AND stock.ingredient_id = account.ingredient_id
  WHERE coalesce(account.tenant_id, stock.tenant_id) = v_tenant
    AND (
      p_branch_id IS NULL
      OR coalesce(account.branch_id, stock.branch_id) = p_branch_id
    );

  SELECT pg_catalog.count(*)
  INTO v_value_mismatches
  FROM public.inventory_valuation_accounts AS account
  LEFT JOIN LATERAL (
    SELECT coalesce(pg_catalog.sum(balance.book_value), 0) AS value
    FROM public.inventory_origin_balances AS balance
    WHERE balance.tenant_id = account.tenant_id
      AND balance.valuation_account_id = account.id
      AND balance.holder_kind = 'stock_pool'
  ) AS origin_value ON TRUE
  WHERE account.tenant_id = v_tenant
    AND (p_branch_id IS NULL OR account.branch_id = p_branch_id)
    AND account.book_value IS DISTINCT FROM origin_value.value;

  SELECT pg_catalog.count(*)
  INTO v_origin_mismatches
  FROM public.inventory_valuation_accounts AS account
  LEFT JOIN LATERAL (
    SELECT coalesce(pg_catalog.sum(balance.quantity), 0) AS quantity
    FROM public.inventory_origin_balances AS balance
    WHERE balance.tenant_id = account.tenant_id
      AND balance.valuation_account_id = account.id
      AND balance.holder_kind = 'stock_pool'
  ) AS origin_quantity ON TRUE
  WHERE account.tenant_id = v_tenant
    AND (p_branch_id IS NULL OR account.branch_id = p_branch_id)
    AND account.quantity IS DISTINCT FROM origin_quantity.quantity;

  RETURN pg_catalog.jsonb_build_object(
    'year', p_year,
    'month', p_month,
    'branch_id', p_branch_id,
    'quantity_mismatches', v_quantity_mismatches,
    'value_mismatches', v_value_mismatches,
    'origin_mismatches', v_origin_mismatches,
    'total_quantity', v_total_quantity,
    'total_value', v_total_value,
    'is_reconciled',
      v_quantity_mismatches = 0
      AND v_value_mismatches = 0
      AND v_origin_mismatches = 0
  );
END;
$$;


--
-- Name: get_inventory_value_period(date, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_value_period(p_start_date date, p_end_date date, p_branch_id bigint DEFAULT NULL::bigint) RETURNS TABLE(branch_id bigint, opening_value numeric, closing_value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_start timestamptz;
  v_end timestamptz;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.can_read_inventory_monetary('inventory:valuation_read') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_branch_id IS NULL AND NOT public.auth_is_owner(auth.uid()) THEN
    RAISE EXCEPTION 'system_valuation_owner_only' USING ERRCODE = '42501';
  END IF;
  IF p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  v_start := p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end := (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  WITH allowed_branches AS (
    SELECT branch.id
    FROM public.branches branch
    WHERE branch.tenant_id = v_tenant
      AND branch.is_active
      AND (p_branch_id IS NULL OR branch.id = p_branch_id)
  ),
  stock_locations AS (
    SELECT location.id, location.branch_id
    FROM public.inventory_locations location
    JOIN public.branches branch ON branch.id = location.branch_id
    WHERE location.tenant_id = v_tenant
      AND location.branch_id IN (SELECT allowed.id FROM allowed_branches allowed)
      AND location.is_active
      AND (
        location.location_kind = 'warehouse'
        OR (
          branch.branch_kind = 'central_kitchen'
          AND location.location_kind = 'production_storage'
        )
      )
  ),
  current_value AS (
    SELECT
      stock.branch_id,
      COALESCE(SUM(
        stock.current_quantity
        * COALESCE(stock.avg_unit_cost, ingredient.unit_cost, 0)
      ), 0) AS amount
    FROM public.stock_levels stock
    JOIN stock_locations location ON location.id = stock.location_id
    LEFT JOIN public.ingredients ingredient
      ON ingredient.id = stock.ingredient_id
     AND ingredient.tenant_id = stock.tenant_id
    WHERE stock.tenant_id = v_tenant
    GROUP BY stock.branch_id
  ),
  after_period_value AS (
    SELECT
      movement.branch_id,
      COALESCE(SUM(
        movement.quantity_change
        * COALESCE(movement.unit_cost, ingredient.unit_cost, 0)
      ), 0) AS amount
    FROM public.stock_movements movement
    JOIN stock_locations location ON location.id = movement.location_id
    LEFT JOIN public.ingredients ingredient
      ON ingredient.id = movement.ingredient_id
     AND ingredient.tenant_id = movement.tenant_id
    WHERE movement.tenant_id = v_tenant
      AND movement.created_at >= v_end
    GROUP BY movement.branch_id
  ),
  period_value AS (
    SELECT
      movement.branch_id,
      COALESCE(SUM(
        movement.quantity_change
        * COALESCE(movement.unit_cost, ingredient.unit_cost, 0)
      ), 0) AS amount
    FROM public.stock_movements movement
    JOIN stock_locations location ON location.id = movement.location_id
    LEFT JOIN public.ingredients ingredient
      ON ingredient.id = movement.ingredient_id
     AND ingredient.tenant_id = movement.tenant_id
    WHERE movement.tenant_id = v_tenant
      AND movement.created_at >= v_start
      AND movement.created_at < v_end
    GROUP BY movement.branch_id
  )
  SELECT
    branch.id,
    COALESCE(current_value.amount, 0)
      - COALESCE(after_period_value.amount, 0)
      - COALESCE(period_value.amount, 0),
    COALESCE(current_value.amount, 0)
      - COALESCE(after_period_value.amount, 0)
  FROM allowed_branches branch
  LEFT JOIN current_value ON current_value.branch_id = branch.id
  LEFT JOIN after_period_value ON after_period_value.branch_id = branch.id
  LEFT JOIN period_value ON period_value.branch_id = branch.id
  ORDER BY branch.id;
END;
$$;


--
-- Name: FUNCTION get_inventory_value_period(p_start_date date, p_end_date date, p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_inventory_value_period(p_start_date date, p_end_date date, p_branch_id bigint) IS 'Returns opening and period-end operational inventory value by reversing post-period and in-period stock movements from current stock value. Movement unit cost falls back to the ingredient reference cost.';


--
-- Name: get_invoice_buyer_request_as_system(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invoice_buyer_request_as_system(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.tax_invoice_buyer_requests%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_branch public.branches%ROWTYPE;
  v_job public.tax_invoice_issue_jobs%ROWTYPE;
  v_invoice public.tax_invoices%ROWTYPE;
  v_state text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_request
  FROM public.tax_invoice_buyer_requests request
  WHERE request.token_hash = p_token_hash;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = v_request.order_id
    AND tenant_id = v_request.tenant_id;
  SELECT * INTO v_branch
  FROM public.branches
  WHERE id = v_request.branch_id
    AND tenant_id = v_request.tenant_id;
  SELECT * INTO v_job
  FROM public.tax_invoice_issue_jobs
  WHERE tenant_id = v_request.tenant_id
    AND order_id = v_request.order_id;
  IF v_job.tax_invoice_id IS NOT NULL THEN
    SELECT * INTO v_invoice
    FROM public.tax_invoices
    WHERE id = v_job.tax_invoice_id
      AND tenant_id = v_request.tenant_id;
  END IF;

  v_state := CASE
    WHEN v_request.status = 'submitted' THEN 'submitted'
    WHEN v_request.status = 'expired' THEN 'expired'
    WHEN v_request.expires_at <= now() THEN 'expired'
    WHEN v_job.status = 'queued' AND v_invoice.status = 'draft' THEN 'open'
    ELSE 'closed'
  END;

  RETURN jsonb_build_object(
    'state', v_state,
    'orderNumber', v_order.order_number,
    'branchName', v_branch.name,
    'expiresAt', v_request.expires_at
  );
END;
$$;


--
-- Name: get_kds_ticket_history(bigint, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_kds_ticket_history(p_branch_id bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id bigint DEFAULT NULL::bigint, p_order_id bigint DEFAULT NULL::bigint, p_event_type text DEFAULT NULL::text) RETURNS TABLE(event_id bigint, event_type text, occurred_at timestamp with time zone, actor_id uuid, actor_name text, order_id bigint, ticket_id bigint, order_item_id bigint, station_id bigint, kitchen_send_batch_id bigint, from_status text, to_status text, reason text, item_snapshot jsonb, context jsonb, print_jobs jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 1000);
BEGIN
  IF auth.uid() IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL OR p_branch_id <= 0 THEN
    RAISE EXCEPTION 'invalid_branch' USING ERRCODE = '22023';
  END IF;

  IF p_event_type IS NOT NULL AND p_event_type NOT IN (
    'sent',
    'preparing',
    'completed',
    'recalled',
    'served',
    'cancelled',
    'out_of_stock'
  ) THEN
    RAISE EXCEPTION 'invalid_kds_event_type' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'kds:use') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches branch
    WHERE branch.id = p_branch_id
      AND branch.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    event.id,
    event.event_type,
    event.occurred_at,
    event.actor_id,
    actor.full_name,
    event.order_id,
    event.ticket_id,
    event.order_item_id,
    event.station_id,
    event.kitchen_send_batch_id,
    event.from_status,
    event.to_status,
    event.reason,
    event.item_snapshot,
    event.context,
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', job.id,
          'job_type', job.job_type,
          'status', job.status,
          'created_at', job.created_at
        )
        ORDER BY job.created_at, job.id
      )
      FROM public.print_jobs job
      WHERE job.tenant_id = event.tenant_id
        AND job.order_id = event.order_id
        AND COALESCE(job.payload->'ticket_ids', '[]'::jsonb)
          @> jsonb_build_array(event.ticket_id)
    ), '[]'::jsonb)
  FROM public.kds_ticket_events event
  LEFT JOIN public.profiles actor
    ON actor.id = event.actor_id
   AND actor.tenant_id = event.tenant_id
  WHERE event.tenant_id = v_tenant_id
    AND event.branch_id = p_branch_id
    AND (p_from IS NULL OR event.occurred_at >= p_from)
    AND (p_to IS NULL OR event.occurred_at < p_to)
    AND (p_order_id IS NULL OR event.order_id = p_order_id)
    AND (p_event_type IS NULL OR event.event_type = p_event_type)
    AND (
      p_before_at IS NULL
      OR event.occurred_at < p_before_at
      OR (
        event.occurred_at = p_before_at
        AND p_before_id IS NOT NULL
        AND event.id < p_before_id
      )
    )
  ORDER BY event.occurred_at DESC, event.id DESC
  LIMIT v_limit;
END;
$$;


--
-- Name: FUNCTION get_kds_ticket_history(p_branch_id bigint, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_before_at timestamp with time zone, p_before_id bigint, p_order_id bigint, p_event_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_kds_ticket_history(p_branch_id bigint, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_before_at timestamp with time zone, p_before_id bigint, p_order_id bigint, p_event_type text) IS 'Branch-scoped immutable KDS history. Cursor ordering is (occurred_at, id); live ticket cleanup does not affect results.';


--
-- Name: get_leave_review_queue(bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_leave_review_queue(p_branch_id bigint, p_include_rows boolean DEFAULT true) RETURNS TABLE(pending_count bigint, rows jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_tenant_id bigint;
  v_actor_role text;
  v_actor_branch_id bigint;
  v_is_owner boolean := false;
BEGIN
  IF v_actor_id IS NULL OR p_branch_id IS NULL OR p_branch_id <= 0 THEN
    RAISE EXCEPTION 'leave_review_queue_not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT
    pr.tenant_id,
    private.staff_role_from_position_code(po.code),
    pr.branch_id
  INTO v_tenant_id, v_actor_role, v_actor_branch_id
  FROM public.profiles pr
  JOIN public.positions po
    ON po.id = pr.position_id
   AND po.tenant_id = pr.tenant_id
  WHERE pr.id = v_actor_id
    AND COALESCE(pr.is_active, true) = true
    AND COALESCE(po.is_active, true) = true;

  IF v_tenant_id IS NULL OR v_actor_role IS NULL THEN
    RAISE EXCEPTION 'leave_review_queue_not_allowed' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = v_tenant_id
      AND b.branch_kind = 'branch'
      AND COALESCE(b.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'leave_review_queue_branch_not_allowed' USING ERRCODE = '42501';
  END IF;

  v_is_owner :=
    v_actor_role = 'owner'
    AND public.auth_is_owner(v_actor_id);

  IF NOT v_is_owner AND (
    v_actor_role <> 'branch_manager'
    OR v_actor_branch_id IS DISTINCT FROM p_branch_id
    OR NOT public.has_permission(
      p_branch_id,
      'hr:approve_leave_request'
    )
  ) THEN
    RAISE EXCEPTION 'leave_review_queue_not_allowed' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH visible_requests AS MATERIALIZED (
    SELECT
      lr.id,
      lr.status,
      lr.start_date,
      lr.end_date,
      lr.leave_type,
      lr.reason,
      lr.rejected_reason,
      lr.created_at,
      lr.reviewed_at,
      lr.branch_id,
      e.id AS employee_id,
      e.employee_code,
      e.start_date AS employee_start_date,
      requester_profile.full_name AS employee_full_name,
      requester_position.code AS position_code
    FROM public.leave_requests lr
    JOIN public.employees e
      ON e.id = lr.employee_id
     AND e.tenant_id = lr.tenant_id
    JOIN public.profiles requester_profile
      ON requester_profile.id = e.profile_id
     AND requester_profile.tenant_id = e.tenant_id
    LEFT JOIN public.positions requester_position
      ON requester_position.id = requester_profile.position_id
     AND requester_position.tenant_id = requester_profile.tenant_id
    WHERE lr.tenant_id = v_tenant_id
      AND lr.branch_id = p_branch_id
      AND (
        v_is_owner
        OR (
          requester_profile.branch_id = p_branch_id
          AND private.staff_role_from_position_code(requester_position.code)
            IN ('cashier', 'chef', 'branch_staff')
        )
      )
  ), limited_requests AS (
    SELECT *
    FROM visible_requests
    ORDER BY start_date DESC, created_at DESC
    LIMIT 100
  )
  SELECT
    count(*) FILTER (WHERE request.status = 'pending')::bigint,
    CASE
      WHEN p_include_rows THEN COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', limited.id,
              'status', limited.status,
              'start_date', limited.start_date,
              'end_date', limited.end_date,
              'leave_type', limited.leave_type,
              'reason', limited.reason,
              'rejected_reason', limited.rejected_reason,
              'created_at', limited.created_at,
              'reviewed_at', limited.reviewed_at,
              'branch_id', limited.branch_id,
              'employee_id', limited.employee_id,
              'employee_code', limited.employee_code,
              'employee_start_date', limited.employee_start_date,
              'employee_full_name', limited.employee_full_name,
              'position_code', limited.position_code,
              'approved_annual_ranges',
                CASE
                  WHEN limited.leave_type = 'annual' THEN COALESCE(
                    (
                      SELECT jsonb_agg(
                        jsonb_build_object(
                          'start_date', approved.start_date,
                          'end_date', approved.end_date
                        )
                        ORDER BY approved.start_date, approved.end_date
                      )
                      FROM public.leave_requests approved
                      WHERE approved.tenant_id = v_tenant_id
                        AND approved.employee_id = limited.employee_id
                        AND approved.leave_type = 'annual'
                        AND approved.status = 'approved'
                        AND approved.start_date <= make_date(
                          EXTRACT(YEAR FROM limited.start_date)::integer,
                          12,
                          31
                        )
                        AND approved.end_date >= make_date(
                          EXTRACT(YEAR FROM limited.start_date)::integer,
                          1,
                          1
                        )
                    ),
                    '[]'::jsonb
                  )
                  ELSE '[]'::jsonb
                END
            )
            ORDER BY limited.start_date DESC, limited.created_at DESC
          )
          FROM limited_requests limited
        ),
        '[]'::jsonb
      )
      ELSE '[]'::jsonb
    END
  FROM visible_requests request;
END;
$$;


--
-- Name: FUNCTION get_leave_review_queue(p_branch_id bigint, p_include_rows boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_leave_review_queue(p_branch_id bigint, p_include_rows boolean) IS 'Returns an authenticated exact-branch leave-review projection without exposing salary, payroll, contract, insurance, bank, or identity-document fields.';


--
-- Name: get_menu_item_sales_agg(bigint, timestamp with time zone, timestamp with time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_menu_item_sales_agg(p_branch_id bigint DEFAULT NULL::bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_order_statuses text[] DEFAULT NULL::text[]) RETURNS TABLE(branch_id bigint, menu_item_id bigint, item_name text, quantity_sold numeric, revenue numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_uid uuid;
  v_tenant bigint;
  v_has_tenant_scope boolean;
  v_branch_ids bigint[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id
  INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
  INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NULL THEN
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH paid_orders AS MATERIALIZED (
    SELECT DISTINCT ON (p.tenant_id, p.branch_id, p.order_id)
      o.id,
      o.branch_id,
      o.tenant_id,
      o.subtotal,
      o.discount_amount
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at >= COALESCE(p_from, '-infinity'::timestamptz)
      AND p.paid_at < COALESCE(p_to, 'infinity'::timestamptz)
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (p_order_statuses IS NULL OR o.status = ANY(p_order_statuses))
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
    ORDER BY p.tenant_id, p.branch_id, p.order_id, p.paid_at, p.id
  ),
  paid_items AS MATERIALIZED (
    SELECT
      po.id AS order_id,
      po.branch_id,
      po.tenant_id,
      po.subtotal,
      po.discount_amount,
      oi.id AS order_item_id,
      oi.menu_item_id,
      oi.item_name,
      oi.quantity::numeric AS parent_quantity,
      COALESCE(oi.subtotal, 0)::numeric AS line_revenue,
      CASE
        WHEN jsonb_typeof(oi.sides) = 'array' THEN oi.sides
        ELSE '[]'::jsonb
      END AS sides
    FROM paid_orders po
    JOIN public.order_items oi
      ON oi.order_id = po.id
     AND oi.tenant_id = po.tenant_id
    WHERE oi.status <> 'cancelled'
  ),
  side_lines AS (
    SELECT
      pi.order_id,
      pi.branch_id,
      pi.tenant_id,
      pi.subtotal,
      pi.discount_amount,
      pi.order_item_id,
      (side_el ->> 'side_item_id')::bigint AS menu_item_id,
      COALESCE(NULLIF(side_el ->> 'name', ''), 'Món ăn kèm')::text AS item_name,
      pi.parent_quantity,
      CASE
        WHEN COALESCE(side_el ->> 'quantity', '') ~ '^[0-9]+(\.[0-9]+)?$'
          THEN GREATEST((side_el ->> 'quantity')::numeric, 0)
        ELSE 1
      END AS quantity_per_parent,
      CASE
        WHEN COALESCE(side_el ->> 'price', '') ~ '^[0-9]+(\.[0-9]+)?$'
          THEN GREATEST((side_el ->> 'price')::numeric, 0)
        ELSE 0
      END AS unit_price
    FROM paid_items pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  ),
  side_totals_by_line AS (
    SELECT
      sl.order_item_id,
      COALESCE(
        SUM(sl.parent_quantity * sl.quantity_per_parent * sl.unit_price),
        0
      )::numeric AS side_revenue
    FROM side_lines sl
    GROUP BY sl.order_item_id
  ),
  component_rows AS (
    SELECT
      pi.order_id,
      pi.branch_id,
      pi.menu_item_id,
      pi.item_name,
      pi.parent_quantity AS quantity_sold,
      GREATEST(pi.line_revenue - COALESCE(st.side_revenue, 0), 0) AS revenue_before_discount,
      pi.subtotal,
      pi.discount_amount
    FROM paid_items pi
    LEFT JOIN side_totals_by_line st
      ON st.order_item_id = pi.order_item_id

    UNION ALL

    SELECT
      sl.order_id,
      sl.branch_id,
      sl.menu_item_id,
      sl.item_name,
      sl.parent_quantity * sl.quantity_per_parent AS quantity_sold,
      sl.parent_quantity * sl.quantity_per_parent * sl.unit_price AS revenue_before_discount,
      sl.subtotal,
      sl.discount_amount
    FROM side_lines sl
  ),
  item_rows AS (
    SELECT
      cr.*,
      SUM(cr.revenue_before_discount) OVER (PARTITION BY cr.order_id) AS order_item_subtotal
    FROM component_rows cr
  )
  SELECT
    ir.branch_id,
    ir.menu_item_id,
    (array_agg(ir.item_name ORDER BY ir.item_name))[1] AS item_name,
    SUM(ir.quantity_sold)::numeric AS quantity_sold,
    COALESCE(SUM(
      CASE
        WHEN ir.order_item_subtotal > 0 THEN
          ir.revenue_before_discount * (ir.subtotal - ir.discount_amount) / ir.order_item_subtotal
        ELSE 0
      END
    ), 0)::numeric AS revenue
  FROM item_rows ir
  GROUP BY ir.branch_id, ir.menu_item_id;
END;
$_$;


--
-- Name: get_my_count_slip(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_count_slip(p_slip_id bigint) RETURNS TABLE(ingredient_id bigint, counted_quantity numeric, entry_unit_id bigint, note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT l.ingredient_id, l.counted_quantity, l.entry_unit_id, l.note
  FROM public.inventory_count_slip_lines l
  JOIN public.inventory_count_slips s ON s.id = l.slip_id
  JOIN public.employees e ON e.id = s.employee_id
  WHERE l.slip_id = p_slip_id
    AND s.tenant_id = public.auth_tenant_id()
    AND e.profile_id = auth.uid();
$$;


--
-- Name: FUNCTION get_my_count_slip(p_slip_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_my_count_slip(p_slip_id bigint) IS 'Blind read of the caller''s own count slip lines (counted_quantity and entry_unit_id only; never system_quantity/variance).';


--
-- Name: get_operating_cash_movement_for_period(date, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_operating_cash_movement_for_period(p_start_date date, p_end_date date, p_branch_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_start_at timestamptz;
  v_end_at timestamptz;
  v_cash_collections numeric;
  v_cash_refunds numeric;
  v_cash_expenses numeric;
  v_cash_supplier_payments numeric;
  v_cash_out numeric;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL OR p_end_date < p_start_date
  THEN
    RAISE EXCEPTION 'invalid_period' USING ERRCODE = '22023';
  END IF;

  v_start_at := p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end_at := (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  SELECT COALESCE(sum(payment.amount), 0)
  INTO v_cash_collections
  FROM public.payments payment
  WHERE payment.tenant_id = v_tenant_id
    AND payment.method = 'cash'
    AND payment.status IN ('completed', 'refunded')
    AND payment.paid_at >= v_start_at
    AND payment.paid_at < v_end_at
    AND (p_branch_id IS NULL OR payment.branch_id = p_branch_id);

  SELECT COALESCE(sum(refund.amount), 0)
  INTO v_cash_refunds
  FROM public.refunds refund
  WHERE refund.tenant_id = v_tenant_id
    AND refund.status = 'approved'
    AND refund.payout_method = 'cash'
    AND refund.approved_at >= v_start_at
    AND refund.approved_at < v_end_at
    AND (p_branch_id IS NULL OR refund.branch_id = p_branch_id);

  SELECT COALESCE(sum(expense.amount), 0)
  INTO v_cash_expenses
  FROM public.expenses expense
  WHERE expense.tenant_id = v_tenant_id
    AND expense.payment_method = 'cash'
    AND expense.paid_at >= v_start_at
    AND expense.paid_at < v_end_at
    AND expense.category IN (
      'rent',
      'utilities',
      'gas_fuel',
      'salary',
      'supplies',
      'repair',
      'marketing',
      'fees_tax',
      'hospitality',
      'other'
    )
    AND (p_branch_id IS NULL OR expense.branch_id = p_branch_id);

  SELECT COALESCE(sum(supplier_payment.amount), 0)
  INTO v_cash_supplier_payments
  FROM public.supplier_payments supplier_payment
  JOIN public.supplier_invoices supplier_invoice
    ON supplier_invoice.id = supplier_payment.supplier_invoice_id
   AND supplier_invoice.tenant_id = supplier_payment.tenant_id
  LEFT JOIN public.goods_received_notes grn
    ON grn.id = supplier_invoice.grn_id
   AND grn.tenant_id = supplier_invoice.tenant_id
  WHERE supplier_payment.tenant_id = v_tenant_id
    AND supplier_payment.payment_method = 'cash'
    AND supplier_payment.payment_date >= v_start_at
    AND supplier_payment.payment_date < v_end_at
    AND (p_branch_id IS NULL OR grn.branch_id = p_branch_id);

  v_cash_out := v_cash_refunds + v_cash_expenses + v_cash_supplier_payments;

  RETURN jsonb_build_object(
    'cash_collections', v_cash_collections,
    'cash_refunds', v_cash_refunds,
    'cash_expenses', v_cash_expenses,
    'cash_supplier_payments', v_cash_supplier_payments,
    'cash_out', v_cash_out,
    'net_cash_movement', v_cash_collections - v_cash_out
  );
END;
$$;


--
-- Name: get_order_operational_trace(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_order_operational_trace(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_order public.orders%ROWTYPE;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR public.auth_tenant_id() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT *
  INTO v_order
  FROM public.orders orders
  WHERE orders.id = p_order_id
    AND orders.tenant_id = public.auth_tenant_id();

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'orders:read') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'order_id', v_order.id,
    'branch_id', v_order.branch_id,
    'pos_session_id', v_order.pos_session_id,
    'item_summary', (
      SELECT jsonb_build_object(
        'item_row_count', count(*)::bigint,
        'item_quantity', COALESCE(sum(item.quantity), 0)::bigint,
        'main_dish_quantity', COALESCE(sum(item.quantity) FILTER (
          WHERE item.category_type_snapshot = 'main_dish'
        ), 0)::bigint,
        'side_dish_quantity', COALESCE(sum(item.quantity) FILTER (
          WHERE item.category_type_snapshot = 'side_dish'
        ), 0)::bigint,
        'included_side_quantity', COALESCE(sum(
          item.quantity * COALESCE((
            SELECT sum(
              CASE
                WHEN COALESCE(side->>'quantity', '') ~ '^[0-9]+$'
                  THEN (side->>'quantity')::integer
                ELSE 1
              END
            )
            FROM jsonb_array_elements(item.sides) side
          ), 0)
        ), 0)::bigint,
        'served_item_quantity', COALESCE(sum(item.quantity) FILTER (
          WHERE item.status = 'served'
        ), 0)::bigint,
        'legacy_unclassified_quantity', COALESCE(sum(item.quantity) FILTER (
          WHERE item.category_type_snapshot IS NULL
        ), 0)::bigint,
        'legacy_current_main_dish_quantity', COALESCE(sum(item.quantity) FILTER (
          WHERE item.category_type_snapshot IS NULL
            AND current_category.type = 'main_dish'
        ), 0)::bigint,
        'legacy_current_side_dish_quantity', COALESCE(sum(item.quantity) FILTER (
          WHERE item.category_type_snapshot IS NULL
            AND current_category.type = 'side_dish'
        ), 0)::bigint
      )
      FROM public.order_items item
      LEFT JOIN public.menu_items current_item
        ON current_item.id = item.menu_item_id
       AND current_item.tenant_id = item.tenant_id
      LEFT JOIN public.menu_categories current_category
        ON current_category.id = current_item.category_id
       AND current_category.tenant_id = current_item.tenant_id
      WHERE item.tenant_id = v_order.tenant_id
        AND item.order_id = v_order.id
        AND item.status <> 'cancelled'
    ),
    'payments', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', payment.id,
          'method', payment.method,
          'amount', payment.amount,
          'status', payment.status,
          'provider_ref', payment.provider_ref,
          'paid_at', payment.paid_at,
          'created_at', payment.created_at,
          'reconciliation_status', CASE
            WHEN payment.method <> 'vietqr' THEN 'not_applicable'
            WHEN EXISTS (
              SELECT 1
              FROM public.bank_transaction_reconciliation_matches match
              WHERE match.tenant_id = payment.tenant_id
                AND match.payment_id = payment.id
            ) THEN 'matched'
            ELSE 'missing'
          END
        )
        ORDER BY
          COALESCE(payment.paid_at, payment.created_at),
          payment.id
      )
      FROM public.payments payment
      WHERE payment.tenant_id = v_order.tenant_id
        AND payment.order_id = v_order.id
    ), '[]'::jsonb),
    'kds_events', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', event.id,
          'event_type', event.event_type,
          'occurred_at', event.occurred_at,
          'actor_id', event.actor_id,
          'actor_name', actor.full_name,
          'ticket_id', event.ticket_id,
          'order_item_id', event.order_item_id,
          'station_id', event.station_id,
          'kitchen_send_batch_id', event.kitchen_send_batch_id,
          'from_status', event.from_status,
          'to_status', event.to_status,
          'reason', event.reason,
          'item_snapshot', event.item_snapshot,
          'context', event.context
        )
        ORDER BY event.occurred_at, event.id
      )
      FROM public.kds_ticket_events event
      LEFT JOIN public.profiles actor
        ON actor.id = event.actor_id
       AND actor.tenant_id = event.tenant_id
      WHERE event.tenant_id = v_order.tenant_id
        AND event.order_id = v_order.id
    ), '[]'::jsonb),
    'print_jobs', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', job.id,
          'job_type', job.job_type,
          'printer_id', job.printer_id,
          'status', job.status,
          'attempts', job.attempts,
          'retry_count', job.retry_count,
          'created_at', job.created_at,
          'printed_at', job.printed_at,
          'payload_summary', jsonb_strip_nulls(jsonb_build_object(
            'kind', job.payload->>'kind',
            'kitchen_ticket_number',
              job.payload->>'kitchen_ticket_number',
            'source_order_number', job.payload->>'source_order_number',
            'send_seq', job.payload->'send_seq',
            'send_kind', job.payload->>'send_kind',
            'ticket_ids', job.payload->'ticket_ids',
            'order_item_ids', job.payload->'order_item_ids',
            'items', job.payload->'items'
          ))
        )
        ORDER BY job.created_at, job.id
      )
      FROM public.print_jobs job
      WHERE job.tenant_id = v_order.tenant_id
        AND job.order_id = v_order.id
    ), '[]'::jsonb),
    'tax_invoices', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', invoice.id,
          'invoice_kind', invoice.invoice_kind,
          'status', invoice.status,
          'invoice_number', invoice.invoice_number,
          'provider', invoice.provider,
          'provider_ref', invoice.provider_ref,
          'issued_at', invoice.issued_at,
          'created_at', invoice.created_at
        )
        ORDER BY invoice.created_at, invoice.id
      )
      FROM (
        SELECT tax_invoice.*
        FROM public.tax_invoices tax_invoice
        WHERE tax_invoice.tenant_id = v_order.tenant_id
          AND tax_invoice.order_id = v_order.id

        UNION ALL

        SELECT tax_invoice.*
        FROM public.tax_invoice_orders invoice_order
        JOIN public.tax_invoices tax_invoice
          ON tax_invoice.id = invoice_order.tax_invoice_id
         AND tax_invoice.tenant_id = invoice_order.tenant_id
        WHERE invoice_order.tenant_id = v_order.tenant_id
          AND invoice_order.order_id = v_order.id
      ) invoice
    ), '[]'::jsonb),
    'audit_events', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', audit.id,
          'action', audit.action,
          'entity_type', audit.entity_type,
          'entity_id', audit.entity_id,
          'actor_id', audit.user_id,
          'actor_name', actor.full_name,
          'created_at', audit.created_at
        )
        ORDER BY audit.created_at, audit.id
      )
      FROM public.audit_logs audit
      LEFT JOIN public.profiles actor
        ON actor.id = audit.user_id
       AND actor.tenant_id = audit.tenant_id
      WHERE audit.tenant_id = v_order.tenant_id
        AND (
          (audit.entity_type = 'order' AND audit.entity_id = v_order.id)
          OR (
            audit.entity_type = 'payment'
            AND audit.entity_id IN (
              SELECT payment.id
              FROM public.payments payment
              WHERE payment.tenant_id = v_order.tenant_id
                AND payment.order_id = v_order.id
            )
          )
          OR (
            audit.entity_type = 'webhook_event'
            AND audit.entity_id IN (
              SELECT event.id
              FROM public.webhook_events event
              WHERE event.tenant_id = v_order.tenant_id
                AND event.order_id = v_order.id
            )
          )
        )
    ), '[]'::jsonb)
  )
  INTO v_result;

  RETURN v_result;
END;
$_$;


--
-- Name: FUNCTION get_order_operational_trace(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_order_operational_trace(p_order_id bigint) IS 'Order-scoped immutable operational trace across payment, KDS, printing, HĐĐT, and server audit evidence.';


--
-- Name: get_orders_for_day(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_orders_for_day(p_branch_id bigint, p_date date) RETURNS TABLE(order_id bigint, order_number text, branch_id bigint, branch_name text, paid_at timestamp with time zone, paid_hour integer, order_type text, subtotal numeric, discount_amount numeric, tax_amount numeric, total_amount numeric, payment_method text, item_count bigint, invoice_status text, invoice_number text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    UUID;
  v_tenant BIGINT;
BEGIN
  IF p_branch_id IS NULL THEN
    RAISE EXCEPTION 'branch_id required for drill-down'
      USING ERRCODE = '22023';
  END IF;

  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
    FROM public.profiles pr WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT
      o.id AS order_id,
      o.order_number,
      o.branch_id,
      b.name AS branch_name,
      p.paid_at,
      EXTRACT(HOUR FROM (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'))::INT
        AS paid_hour,
      o.order_type,
      o.subtotal,
      o.discount_amount,
      o.tax_amount,
      o.total_amount,
      o.payment_method,
      (SELECT COUNT(*) FROM public.order_items oi
        WHERE oi.order_id = o.id AND oi.status <> 'cancelled')::BIGINT
        AS item_count,
      ti.status         AS invoice_status,
      ti.invoice_number
    FROM public.orders o
    JOIN public.branches b
      ON b.id = o.branch_id
     AND b.tenant_id = o.tenant_id
    JOIN public.payments p
      ON p.order_id  = o.id
     AND p.tenant_id = o.tenant_id
     AND p.status    = 'completed'
     AND p.paid_at IS NOT NULL
    LEFT JOIN public.tax_invoices ti
      ON ti.order_id  = o.id
     AND ti.tenant_id = o.tenant_id
     AND ti.status NOT IN ('cancelled', 'replaced')
    WHERE o.tenant_id = v_tenant
      AND o.branch_id = p_branch_id
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = p_date
    ORDER BY p.paid_at;
END;
$$;


--
-- Name: get_orders_for_day_v2(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_orders_for_day_v2(p_branch_id bigint, p_date date) RETURNS TABLE(payment_id bigint, order_id bigint, order_number text, order_status text, order_payment_status text, order_payment_state_mismatch boolean, branch_id bigint, branch_name text, paid_at timestamp with time zone, paid_hour integer, order_type text, subtotal numeric, discount_amount numeric, tax_amount numeric, order_total_amount numeric, total_amount numeric, payment_method text, item_count bigint, item_row_count bigint, main_dish_quantity bigint, side_dish_quantity bigint, included_side_quantity bigint, served_item_quantity bigint, legacy_unclassified_quantity bigint, legacy_current_main_dish_quantity bigint, legacy_current_side_dish_quantity bigint, kds_ticket_count bigint, kds_completed_ticket_count bigint, kds_completed_item_quantity bigint, kds_legacy_completed_ticket_count bigint, kds_legacy_completed_item_quantity bigint, print_job_count bigint, printed_job_count bigint, print_failed_count bigint, pos_session_id bigint, payment_attempt_count bigint, completed_payment_count bigint, payment_attempts jsonb, reconciliation_status text, invoice_kind text, invoice_status text, invoice_number text, invoice_provider_ref text, invoice_evidence jsonb, audit_event_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL OR p_branch_id <= 0 OR p_date IS NULL THEN
    RAISE EXCEPTION 'invalid_day_scope' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches branch
    WHERE branch.id = p_branch_id
      AND branch.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    payment.id,
    orders.id,
    orders.order_number,
    orders.status,
    orders.payment_status,
    orders.status = 'cancelled'
      OR orders.payment_status IS DISTINCT FROM 'paid'
      OR payment.amount IS DISTINCT FROM orders.total_amount
      OR payment_summary.completed_count <> 1,
    orders.branch_id,
    branch.name,
    payment.paid_at,
    EXTRACT(
      HOUR FROM payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
    )::integer,
    orders.order_type,
    orders.subtotal,
    orders.discount_amount,
    orders.tax_amount,
    orders.total_amount,
    payment.amount,
    payment.method,
    item_summary.item_quantity,
    item_summary.item_row_count,
    item_summary.main_dish_quantity,
    item_summary.side_dish_quantity,
    item_summary.included_side_quantity,
    item_summary.served_item_quantity,
    item_summary.legacy_unclassified_quantity,
    item_summary.legacy_current_main_dish_quantity,
    item_summary.legacy_current_side_dish_quantity,
    kds_summary.ticket_count,
    kds_summary.completed_ticket_count,
    kds_summary.completed_item_quantity,
    kds_summary.legacy_completed_ticket_count,
    kds_summary.legacy_completed_item_quantity,
    print_summary.job_count,
    print_summary.printed_count,
    print_summary.failed_count,
    orders.pos_session_id,
    payment_summary.attempt_count,
    payment_summary.completed_count,
    payment_summary.attempts,
    CASE
      WHEN payment.method <> 'vietqr' THEN 'not_applicable'
      WHEN reconciliation.payment_id IS NOT NULL THEN 'matched'
      ELSE 'missing'
    END,
    invoice_selected.invoice_kind,
    invoice_selected.status,
    invoice_selected.invoice_number,
    invoice_selected.provider_ref,
    invoice_summary.evidence,
    audit_summary.event_count
  FROM public.orders orders
  JOIN public.branches branch
    ON branch.id = orders.branch_id
   AND branch.tenant_id = orders.tenant_id
  JOIN LATERAL (
    SELECT candidate.*
    FROM public.payments candidate
    WHERE candidate.tenant_id = orders.tenant_id
      AND candidate.branch_id = orders.branch_id
      AND candidate.order_id = orders.id
      AND candidate.status = 'completed'
      AND candidate.paid_at IS NOT NULL
      AND (
        candidate.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
      )::date = p_date
    ORDER BY candidate.paid_at DESC, candidate.id DESC
    LIMIT 1
  ) payment ON true
  LEFT JOIN LATERAL (
    SELECT
      count(*)::bigint AS item_row_count,
      COALESCE(sum(item.quantity), 0)::bigint AS item_quantity,
      COALESCE(sum(item.quantity) FILTER (
        WHERE item.category_type_snapshot = 'main_dish'
      ), 0)::bigint AS main_dish_quantity,
      COALESCE(sum(item.quantity) FILTER (
        WHERE item.category_type_snapshot = 'side_dish'
      ), 0)::bigint AS side_dish_quantity,
      COALESCE(sum(item.quantity) FILTER (
        WHERE item.status = 'served'
      ), 0)::bigint AS served_item_quantity,
      COALESCE(sum(item.quantity) FILTER (
        WHERE item.category_type_snapshot IS NULL
      ), 0)::bigint AS legacy_unclassified_quantity,
      COALESCE(sum(item.quantity) FILTER (
        WHERE item.category_type_snapshot IS NULL
          AND current_category.type = 'main_dish'
      ), 0)::bigint AS legacy_current_main_dish_quantity,
      COALESCE(sum(item.quantity) FILTER (
        WHERE item.category_type_snapshot IS NULL
          AND current_category.type = 'side_dish'
      ), 0)::bigint AS legacy_current_side_dish_quantity,
      COALESCE(sum(
        item.quantity * COALESCE((
          SELECT sum(
            CASE
              WHEN COALESCE(side->>'quantity', '') ~ '^[0-9]+$'
                THEN (side->>'quantity')::integer
              ELSE 1
            END
          )
          FROM jsonb_array_elements(item.sides) side
        ), 0)
      ), 0)::bigint AS included_side_quantity
    FROM public.order_items item
    LEFT JOIN public.menu_items current_item
      ON current_item.id = item.menu_item_id
     AND current_item.tenant_id = item.tenant_id
    LEFT JOIN public.menu_categories current_category
      ON current_category.id = current_item.category_id
     AND current_category.tenant_id = current_item.tenant_id
    WHERE item.tenant_id = orders.tenant_id
      AND item.order_id = orders.id
      AND item.status <> 'cancelled'
  ) item_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      (
        SELECT count(DISTINCT event.ticket_id)::bigint
        FROM public.kds_ticket_events event
        WHERE event.tenant_id = orders.tenant_id
          AND event.order_id = orders.id
      ) AS ticket_count,
      (
        SELECT count(DISTINCT event.ticket_id)::bigint
        FROM public.kds_ticket_events event
        WHERE event.tenant_id = orders.tenant_id
          AND event.order_id = orders.id
          AND event.event_type = 'completed'
          AND event.context->>'evidence_source'
            IS DISTINCT FROM 'legacy_live_snapshot'
      ) AS completed_ticket_count,
      COALESCE((
        SELECT sum(completed.quantity)::bigint
        FROM (
          SELECT DISTINCT ON (event.order_item_id)
            CASE
              WHEN COALESCE(
                event.item_snapshot->>'quantity',
                ''
              ) ~ '^[0-9]+$'
                THEN (event.item_snapshot->>'quantity')::bigint
              ELSE 0
            END AS quantity
          FROM public.kds_ticket_events event
          WHERE event.tenant_id = orders.tenant_id
            AND event.order_id = orders.id
            AND event.event_type = 'completed'
            AND event.context->>'evidence_source'
              IS DISTINCT FROM 'legacy_live_snapshot'
          ORDER BY
            event.order_item_id,
            event.occurred_at,
            event.id
        ) completed
      ), 0)::bigint AS completed_item_quantity,
      (
        SELECT count(DISTINCT event.ticket_id)::bigint
        FROM public.kds_ticket_events event
        WHERE event.tenant_id = orders.tenant_id
          AND event.order_id = orders.id
          AND event.event_type = 'completed'
          AND event.context->>'evidence_source' = 'legacy_live_snapshot'
          AND NOT EXISTS (
            SELECT 1
            FROM public.kds_ticket_events canonical
            WHERE canonical.tenant_id = event.tenant_id
              AND canonical.order_item_id = event.order_item_id
              AND canonical.event_type = 'completed'
              AND canonical.context->>'evidence_source'
                IS DISTINCT FROM 'legacy_live_snapshot'
          )
      ) AS legacy_completed_ticket_count,
      COALESCE((
        SELECT sum(completed.quantity)::bigint
        FROM (
          SELECT DISTINCT ON (event.order_item_id)
            CASE
              WHEN COALESCE(
                event.item_snapshot->>'quantity',
                ''
              ) ~ '^[0-9]+$'
                THEN (event.item_snapshot->>'quantity')::bigint
              ELSE 0
            END AS quantity
          FROM public.kds_ticket_events event
          WHERE event.tenant_id = orders.tenant_id
            AND event.order_id = orders.id
            AND event.event_type = 'completed'
            AND event.context->>'evidence_source' = 'legacy_live_snapshot'
            AND NOT EXISTS (
              SELECT 1
              FROM public.kds_ticket_events canonical
              WHERE canonical.tenant_id = event.tenant_id
                AND canonical.order_item_id = event.order_item_id
                AND canonical.event_type = 'completed'
                AND canonical.context->>'evidence_source'
                  IS DISTINCT FROM 'legacy_live_snapshot'
            )
          ORDER BY
            event.order_item_id,
            event.occurred_at,
            event.id
        ) completed
      ), 0)::bigint AS legacy_completed_item_quantity
  ) kds_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      count(*)::bigint AS job_count,
      count(*) FILTER (WHERE job.status = 'printed')::bigint
        AS printed_count,
      count(*) FILTER (
        WHERE job.status IN ('failed', 'expired')
      )::bigint AS failed_count
    FROM public.print_jobs job
    WHERE job.tenant_id = orders.tenant_id
      AND job.order_id = orders.id
  ) print_summary ON true
  LEFT JOIN LATERAL (
    SELECT
      count(*)::bigint AS attempt_count,
      count(*) FILTER (
        WHERE attempt.status = 'completed'
      )::bigint AS completed_count,
      jsonb_agg(
        jsonb_build_object(
          'id', attempt.id,
          'method', attempt.method,
          'amount', attempt.amount,
          'status', attempt.status,
          'paid_at', attempt.paid_at,
          'created_at', attempt.created_at
        )
        ORDER BY COALESCE(attempt.paid_at, attempt.created_at), attempt.id
      ) AS attempts
    FROM public.payments attempt
    WHERE attempt.tenant_id = orders.tenant_id
      AND attempt.order_id = orders.id
  ) payment_summary ON true
  LEFT JOIN public.bank_transaction_reconciliation_matches reconciliation
    ON reconciliation.tenant_id = payment.tenant_id
   AND reconciliation.payment_id = payment.id
  LEFT JOIN LATERAL (
    SELECT evidence.*
    FROM (
      SELECT
        invoice.id,
        invoice.invoice_kind,
        invoice.status,
        invoice.invoice_number,
        invoice.provider_ref,
        invoice.created_at
      FROM public.tax_invoices invoice
      WHERE invoice.tenant_id = orders.tenant_id
        AND invoice.order_id = orders.id

      UNION ALL

      SELECT
        invoice.id,
        invoice.invoice_kind,
        invoice.status,
        invoice.invoice_number,
        invoice.provider_ref,
        invoice.created_at
      FROM public.tax_invoice_orders invoice_order
      JOIN public.tax_invoices invoice
        ON invoice.id = invoice_order.tax_invoice_id
       AND invoice.tenant_id = invoice_order.tenant_id
      WHERE invoice_order.tenant_id = orders.tenant_id
        AND invoice_order.order_id = orders.id
    ) evidence
    ORDER BY
      CASE evidence.status
        WHEN 'issued' THEN 1
        WHEN 'submitted' THEN 2
        WHEN 'signing' THEN 3
        WHEN 'draft' THEN 4
        WHEN 'not_required' THEN 5
        WHEN 'replaced' THEN 6
        WHEN 'cancelled' THEN 7
        ELSE 8
      END,
      evidence.created_at DESC,
      evidence.id DESC
    LIMIT 1
  ) invoice_selected ON true
  LEFT JOIN LATERAL (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', evidence.id,
        'invoice_kind', evidence.invoice_kind,
        'status', evidence.status,
        'invoice_number', evidence.invoice_number,
        'provider_ref', evidence.provider_ref,
        'created_at', evidence.created_at
      )
      ORDER BY evidence.created_at, evidence.id
    ), '[]'::jsonb) AS evidence
    FROM (
      SELECT
        invoice.id,
        invoice.invoice_kind,
        invoice.status,
        invoice.invoice_number,
        invoice.provider_ref,
        invoice.created_at
      FROM public.tax_invoices invoice
      WHERE invoice.tenant_id = orders.tenant_id
        AND invoice.order_id = orders.id

      UNION ALL

      SELECT
        invoice.id,
        invoice.invoice_kind,
        invoice.status,
        invoice.invoice_number,
        invoice.provider_ref,
        invoice.created_at
      FROM public.tax_invoice_orders invoice_order
      JOIN public.tax_invoices invoice
        ON invoice.id = invoice_order.tax_invoice_id
       AND invoice.tenant_id = invoice_order.tenant_id
      WHERE invoice_order.tenant_id = orders.tenant_id
        AND invoice_order.order_id = orders.id
    ) evidence
  ) invoice_summary ON true
  LEFT JOIN LATERAL (
    SELECT count(*)::bigint AS event_count
    FROM public.audit_logs audit
    WHERE audit.tenant_id = orders.tenant_id
      AND (
        (audit.entity_type = 'order' AND audit.entity_id = orders.id)
        OR (
          audit.entity_type = 'payment'
          AND audit.entity_id IN (
            SELECT attempt.id
            FROM public.payments attempt
            WHERE attempt.tenant_id = orders.tenant_id
              AND attempt.order_id = orders.id
          )
        )
        OR (
          audit.entity_type = 'webhook_event'
          AND audit.entity_id IN (
            SELECT event.id
            FROM public.webhook_events event
            WHERE event.tenant_id = orders.tenant_id
              AND event.order_id = orders.id
          )
        )
      )
  ) audit_summary ON true
  WHERE orders.tenant_id = v_tenant_id
    AND orders.branch_id = p_branch_id
  ORDER BY payment.paid_at, payment.id;
END;
$_$;


--
-- Name: FUNCTION get_orders_for_day_v2(p_branch_id bigint, p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_orders_for_day_v2(p_branch_id bigint, p_date date) IS 'One row per order with its canonical completed payment bucketed by payments.paid_at in Asia/Ho_Chi_Minh. Order mirror mismatches remain visible as exceptions.';


--
-- Name: get_orders_paid_summary(text, bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_orders_paid_summary(p_status text DEFAULT NULL::text, p_branch_id bigint DEFAULT NULL::bigint, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date) RETURNS TABLE(paid_count bigint, paid_revenue numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    count(*)::bigint,
    COALESCE(sum(o.total_amount), 0)::numeric(15, 2)
  FROM public.orders o
  WHERE o.payment_status = 'paid'
    AND o.status <> 'cancelled'
    AND (p_status IS NULL OR o.status = p_status)
    AND (p_branch_id IS NULL OR o.branch_id = p_branch_id)
    AND (p_date_from IS NULL OR o.created_at >= (p_date_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'))
    AND (p_date_to IS NULL OR o.created_at < ((p_date_to + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'));
$$;


--
-- Name: get_orders_summary(text, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_orders_summary(p_status text DEFAULT NULL::text, p_branch_id bigint DEFAULT NULL::bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_count bigint, in_progress_count bigint, paid_count bigint, paid_revenue numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH allowed AS (
    SELECT branch.id
    FROM public.branches branch
    WHERE branch.tenant_id = public.auth_tenant_id()
      AND (
        public.has_permission(branch.id, 'orders:read')
        OR public.has_permission(branch.id, 'kds:use')
      )
  ),
  scoped_orders AS MATERIALIZED (
    SELECT orders.id, orders.tenant_id, orders.status
    FROM public.orders orders
    WHERE orders.tenant_id = public.auth_tenant_id()
      AND orders.branch_id IN (SELECT allowed.id FROM allowed)
      AND (p_status IS NULL OR orders.status = p_status)
      AND (p_branch_id IS NULL OR orders.branch_id = p_branch_id)
      AND (p_from IS NULL OR orders.created_at >= p_from)
      AND (p_to IS NULL OR orders.created_at < p_to)
  ),
  collected AS (
    SELECT
      payment.order_id,
      sum(payment.amount)::numeric AS amount
    FROM public.payments payment
    JOIN scoped_orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
    WHERE payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
    GROUP BY payment.order_id
  )
  SELECT
    count(*)::bigint,
    count(*) FILTER (
      WHERE orders.status NOT IN ('completed', 'cancelled')
    )::bigint,
    count(collected.order_id)::bigint,
    COALESCE(sum(collected.amount), 0)::numeric(15, 2)
  FROM scoped_orders orders
  LEFT JOIN collected
    ON collected.order_id = orders.id;
$$;


--
-- Name: FUNCTION get_orders_summary(p_status text, p_branch_id bigint, p_from timestamp with time zone, p_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_orders_summary(p_status text, p_branch_id bigint, p_from timestamp with time zone, p_to timestamp with time zone) IS 'Order-list counters. Paid count and revenue come from completed payments with paid_at; order.payment_status remains only a display mirror.';


--
-- Name: get_pos_session_report(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_session_report(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_session public.pos_sessions%ROWTYPE;
  v_report jsonb;
  v_money jsonb;
  v_payment_mix jsonb;
  v_hourly jsonb;
  v_peak_hour jsonb;
  v_aov_bins jsonb;
  v_item_counts jsonb;
  v_top_items jsonb;
  v_categories jsonb;
  v_discounts jsonb;
  v_payment_attempts jsonb;
  v_operational_evidence jsonb;
BEGIN
  IF auth.uid() IS NULL OR public.auth_tenant_id() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT *
  INTO v_session
  FROM public.pos_sessions session
  WHERE session.id = p_session_id
    AND session.tenant_id = public.auth_tenant_id();

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.has_permission(v_session.branch_id, 'settings:branch')
    OR public.has_permission(v_session.branch_id, 'finance:view')
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT public.get_pos_session_report_legacy_20260725(p_session_id)
  INTO v_report;

  WITH eligible_payments AS MATERIALIZED (
    SELECT
      payment.id,
      payment.order_id,
      payment.method,
      payment.amount,
      payment.paid_at
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  ),
  paid_orders AS MATERIALIZED (
    SELECT DISTINCT
      orders.id,
      orders.subtotal,
      orders.discount_amount,
      orders.tax_amount,
      orders.service_charge
    FROM public.orders orders
    JOIN eligible_payments payment
      ON payment.order_id = orders.id
    WHERE orders.tenant_id = v_session.tenant_id
  ),
  payment_totals AS (
    SELECT
      COALESCE(sum(payment.amount), 0)::numeric AS net_revenue,
      COALESCE(sum(payment.amount) FILTER (
        WHERE payment.method = 'cash'
      ), 0)::numeric AS cash_revenue,
      COALESCE(sum(payment.amount) FILTER (
        WHERE payment.method <> 'cash'
      ), 0)::numeric AS noncash_revenue
    FROM eligible_payments payment
  ),
  order_totals AS (
    SELECT
      count(*)::integer AS paid_order_count,
      COALESCE(sum(orders.subtotal), 0)::numeric AS gross_revenue,
      COALESCE(sum(orders.discount_amount), 0)::numeric
        AS discount_total,
      COALESCE(sum(orders.tax_amount), 0)::numeric AS tax_total,
      COALESCE(sum(orders.service_charge), 0)::numeric
        AS service_charge_total
    FROM paid_orders orders
  ),
  order_counts AS (
    SELECT
      count(*) FILTER (
        WHERE orders.status <> 'cancelled'
          AND NOT EXISTS (
            SELECT 1
            FROM eligible_payments payment
            WHERE payment.order_id = orders.id
          )
      )::integer AS unpaid_order_count,
      count(*) FILTER (
        WHERE orders.status = 'cancelled'
      )::integer AS cancelled_order_count
    FROM public.orders orders
    WHERE orders.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
  )
  SELECT jsonb_build_object(
    'gross_revenue', orders.gross_revenue,
    'discount_total', orders.discount_total,
    'tax_total', orders.tax_total,
    'service_charge_total', orders.service_charge_total,
    'net_revenue', payment.net_revenue,
    'cash_revenue', payment.cash_revenue,
    'noncash_revenue', payment.noncash_revenue,
    'paid_order_count', orders.paid_order_count,
    'unpaid_order_count', counts.unpaid_order_count,
    'cancelled_order_count', counts.cancelled_order_count,
    'aov', CASE
      WHEN orders.paid_order_count > 0
        THEN round(
          payment.net_revenue / orders.paid_order_count,
          2
        )
      ELSE 0
    END
  )
  INTO v_money
  FROM order_totals orders
  CROSS JOIN payment_totals payment
  CROSS JOIN order_counts counts;

  WITH eligible_payments AS (
    SELECT
      payment.order_id,
      payment.method,
      payment.amount
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'method', mix.method,
      'count', mix.payment_count,
      'order_count', mix.order_count,
      'amount', mix.amount
    )
    ORDER BY mix.amount DESC, mix.method
  ), '[]'::jsonb)
  INTO v_payment_mix
  FROM (
    SELECT
      payment.method,
      count(*)::integer AS payment_count,
      count(DISTINCT payment.order_id)::integer AS order_count,
      COALESCE(sum(payment.amount), 0)::numeric AS amount
    FROM eligible_payments payment
    GROUP BY payment.method
  ) mix;

  WITH eligible_payments AS (
    SELECT
      payment.id,
      payment.order_id,
      payment.amount,
      payment.paid_at
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  ),
  buckets AS (
    SELECT
      EXTRACT(
        HOUR FROM payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
      )::integer AS hour,
      count(DISTINCT payment.order_id)::integer AS order_count,
      count(*)::integer AS payment_count,
      COALESCE(sum(payment.amount), 0)::numeric AS revenue
    FROM eligible_payments payment
    GROUP BY 1
  )
  SELECT
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'hour', bucket.hour,
        'order_count', bucket.order_count,
        'payment_count', bucket.payment_count,
        'revenue', bucket.revenue
      )
      ORDER BY bucket.hour
    ), '[]'::jsonb),
    (
      SELECT jsonb_build_object(
        'hour', peak.hour,
        'order_count', peak.order_count,
        'payment_count', peak.payment_count,
        'revenue', peak.revenue
      )
      FROM buckets peak
      ORDER BY peak.revenue DESC, peak.order_count DESC, peak.hour
      LIMIT 1
    )
  INTO v_hourly, v_peak_hour
  FROM buckets bucket;

  WITH eligible_payments AS (
    SELECT
      payment.order_id,
      payment.amount
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  ),
  order_payments AS (
    SELECT
      payment.order_id,
      sum(payment.amount)::numeric AS amount
    FROM eligible_payments payment
    GROUP BY payment.order_id
  ),
  bins AS (
    SELECT
      CASE
        WHEN payment.amount <= 50000 THEN '≤50.000đ'
        WHEN payment.amount <= 100000 THEN '50.000–100.000đ'
        WHEN payment.amount <= 200000 THEN '100.000–200.000đ'
        WHEN payment.amount <= 500000 THEN '200.000–500.000đ'
        ELSE '>500.000đ'
      END AS label,
      CASE
        WHEN payment.amount <= 50000 THEN 1
        WHEN payment.amount <= 100000 THEN 2
        WHEN payment.amount <= 200000 THEN 3
        WHEN payment.amount <= 500000 THEN 4
        ELSE 5
      END AS ordinal
    FROM order_payments payment
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('label', grouped.label, 'count', grouped.count)
    ORDER BY grouped.ordinal
  ), '[]'::jsonb)
  INTO v_aov_bins
  FROM (
    SELECT
      bin.label,
      bin.ordinal,
      count(*)::integer AS count
    FROM bins bin
    GROUP BY bin.label, bin.ordinal
  ) grouped;

  WITH paid_order_ids AS (
    SELECT DISTINCT orders.id
    FROM public.orders orders
    JOIN public.payments payment
      ON payment.order_id = orders.id
     AND payment.tenant_id = orders.tenant_id
     AND payment.branch_id = orders.branch_id
    WHERE orders.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  )
  SELECT jsonb_build_object(
    'total_items', COALESCE(sum(item.quantity), 0)::integer,
    'item_row_count', count(*)::integer,
    'item_quantity', COALESCE(sum(item.quantity), 0)::integer,
    'main_dish_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot = 'main_dish'
    ), 0)::integer,
    'side_dish_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot = 'side_dish'
    ), 0)::integer,
    'legacy_unclassified_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot IS NULL
    ), 0)::integer,
    'legacy_current_main_dish_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.category_type_snapshot IS NULL
        AND current_category.type = 'main_dish'
    ), 0)::integer,
    'served_item_quantity', COALESCE(sum(item.quantity) FILTER (
      WHERE item.status = 'served'
    ), 0)::integer,
    'included_side_quantity', COALESCE(sum(
      item.quantity * COALESCE((
        SELECT sum(
          CASE
            WHEN COALESCE(side->>'quantity', '') ~ '^[0-9]+$'
              THEN (side->>'quantity')::integer
            ELSE 1
          END
        )
        FROM jsonb_array_elements(item.sides) side
      ), 0)
    ), 0)::integer
  )
  INTO v_item_counts
  FROM public.order_items item
  JOIN paid_order_ids paid_order
    ON paid_order.id = item.order_id
  LEFT JOIN public.menu_items current_item
    ON current_item.id = item.menu_item_id
   AND current_item.tenant_id = item.tenant_id
  LEFT JOIN public.menu_categories current_category
    ON current_category.id = current_item.category_id
   AND current_category.tenant_id = current_item.tenant_id
  WHERE item.tenant_id = v_session.tenant_id
    AND item.status <> 'cancelled';

  WITH paid_order_ids AS (
    SELECT DISTINCT orders.id
    FROM public.orders orders
    JOIN public.payments payment
      ON payment.order_id = orders.id
     AND payment.tenant_id = orders.tenant_id
     AND payment.branch_id = orders.branch_id
    WHERE orders.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  ),
  paid_items AS (
    SELECT
      item.item_name,
      item.quantity,
      item.subtotal,
      item.modifiers,
      item.sides,
      item.category_type_snapshot,
      current_category.id AS current_category_id,
      current_category.name AS current_category_name
    FROM public.order_items item
    JOIN paid_order_ids paid_order
      ON paid_order.id = item.order_id
    LEFT JOIN public.menu_items current_item
      ON current_item.id = item.menu_item_id
     AND current_item.tenant_id = item.tenant_id
    LEFT JOIN public.menu_categories current_category
      ON current_category.id = current_item.category_id
     AND current_category.tenant_id = current_item.tenant_id
    WHERE item.tenant_id = v_session.tenant_id
      AND item.status <> 'cancelled'
  ),
  main_items AS (
    SELECT
      item.item_name AS name,
      'main'::text AS source,
      COALESCE(sum(item.quantity), 0)::integer AS qty,
      COALESCE(sum(item.subtotal), 0)::numeric AS revenue
    FROM paid_items item
    GROUP BY item.item_name
  ),
  side_items AS (
    SELECT
      COALESCE(side->>'name', 'Side')::text AS name,
      'side'::text AS source,
      COALESCE(sum(
        CASE
          WHEN COALESCE(side->>'quantity', '') ~ '^[0-9]+$'
            THEN (side->>'quantity')::integer
          ELSE 1
        END * item.quantity
      ), 0)::integer AS qty,
      COALESCE(sum(
        CASE
          WHEN COALESCE(side->>'price', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (side->>'price')::numeric
          ELSE 0
        END
          * CASE
            WHEN COALESCE(side->>'quantity', '') ~ '^[0-9]+$'
              THEN (side->>'quantity')::integer
            ELSE 1
          END
          * item.quantity
      ), 0)::numeric AS revenue
    FROM paid_items item
    CROSS JOIN LATERAL jsonb_array_elements(item.sides) side
    GROUP BY side->>'name'
  ),
  modifier_items AS (
    SELECT
      COALESCE(modifier->>'name', 'Modifier')::text AS name,
      'modifier'::text AS source,
      COALESCE(sum(item.quantity), 0)::integer AS qty,
      COALESCE(sum(
        CASE
          WHEN COALESCE(modifier->>'price', '')
            ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (modifier->>'price')::numeric
          ELSE 0
        END * item.quantity
      ), 0)::numeric AS revenue
    FROM paid_items item
    CROSS JOIN LATERAL jsonb_array_elements(item.modifiers) modifier
    GROUP BY modifier->>'name'
  ),
  all_items AS (
    SELECT * FROM main_items
    UNION ALL
    SELECT * FROM side_items
    UNION ALL
    SELECT * FROM modifier_items
  ),
  categories AS (
    SELECT
      COALESCE(item.current_category_id, 0)::bigint AS category_id,
      CASE
        WHEN item.category_type_snapshot IS NULL
          THEN 'Dữ liệu cũ chưa có snapshot'
        ELSE COALESCE(item.current_category_name, 'Khác')
      END AS category_name,
      COALESCE(sum(item.quantity), 0)::integer AS qty,
      COALESCE(sum(item.subtotal), 0)::numeric AS revenue
    FROM paid_items item
    GROUP BY
      COALESCE(item.current_category_id, 0),
      CASE
        WHEN item.category_type_snapshot IS NULL
          THEN 'Dữ liệu cũ chưa có snapshot'
        ELSE COALESCE(item.current_category_name, 'Khác')
      END
  )
  SELECT
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'name', top_item.name,
          'source', top_item.source,
          'qty', top_item.qty,
          'revenue', top_item.revenue
        )
        ORDER BY top_item.qty DESC, top_item.revenue DESC, top_item.name
      )
      FROM (
        SELECT *
        FROM all_items
        ORDER BY qty DESC, revenue DESC, name
        LIMIT 10
      ) top_item
    ), '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'category_id', category.category_id,
          'category_name', category.category_name,
          'qty', category.qty,
          'revenue', category.revenue
        )
        ORDER BY category.revenue DESC, category.category_name
      )
      FROM categories category
    ), '[]'::jsonb)
  INTO v_top_items, v_categories;

  WITH paid_orders AS (
    SELECT DISTINCT orders.id
    FROM public.orders orders
    JOIN public.payments payment
      ON payment.order_id = orders.id
     AND payment.tenant_id = orders.tenant_id
     AND payment.branch_id = orders.branch_id
    WHERE orders.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
      AND payment.status = 'completed'
      AND payment.paid_at IS NOT NULL
  ),
  discount_orders AS (
    SELECT
      orders.id,
      orders.order_number,
      orders.discount_amount,
      orders.discount_note,
      orders.discount_type,
      orders.discount_value
    FROM public.orders orders
    JOIN paid_orders paid_order
      ON paid_order.id = orders.id
    WHERE orders.tenant_id = v_session.tenant_id
      AND orders.discount_amount > 0
  )
  SELECT jsonb_build_object(
    'count', count(*)::integer,
    'total', COALESCE(sum(discount.discount_amount), 0)::numeric,
    'top_orders', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'order_id', top_order.id,
          'order_number', top_order.order_number,
          'amount', top_order.discount_amount,
          'note', top_order.discount_note,
          'type', top_order.discount_type,
          'value', top_order.discount_value
        )
        ORDER BY top_order.discount_amount DESC, top_order.id
      )
      FROM (
        SELECT *
        FROM discount_orders
        ORDER BY discount_amount DESC, id
        LIMIT 10
      ) top_order
    ), '[]'::jsonb)
  )
  INTO v_discounts
  FROM discount_orders discount;

  SELECT jsonb_build_object(
    'total', count(*)::integer,
    'completed', count(*) FILTER (
      WHERE payment.status = 'completed'
    )::integer,
    'pending', count(*) FILTER (
      WHERE payment.status = 'pending'
    )::integer,
    'failed', count(*) FILTER (
      WHERE payment.status = 'failed'
    )::integer,
    'refunded', count(*) FILTER (
      WHERE payment.status = 'refunded'
    )::integer
  )
  INTO v_payment_attempts
  FROM public.payments payment
  JOIN public.orders orders
    ON orders.id = payment.order_id
   AND orders.tenant_id = payment.tenant_id
  WHERE payment.tenant_id = v_session.tenant_id
    AND orders.pos_session_id = v_session.id;

  WITH session_orders AS (
    SELECT orders.id
    FROM public.orders orders
    WHERE orders.tenant_id = v_session.tenant_id
      AND orders.pos_session_id = v_session.id
  ),
  completed_items AS (
    SELECT DISTINCT ON (event.order_item_id)
      CASE
        WHEN COALESCE(
          event.item_snapshot->>'quantity',
          ''
        ) ~ '^[0-9]+$'
          THEN (event.item_snapshot->>'quantity')::integer
        ELSE 0
      END AS quantity
    FROM public.kds_ticket_events event
    JOIN session_orders orders
      ON orders.id = event.order_id
    WHERE event.tenant_id = v_session.tenant_id
      AND event.event_type = 'completed'
      AND event.context->>'evidence_source'
        IS DISTINCT FROM 'legacy_live_snapshot'
    ORDER BY event.order_item_id, event.occurred_at, event.id
  ),
  legacy_completed_items AS (
    SELECT DISTINCT ON (event.order_item_id)
      CASE
        WHEN COALESCE(
          event.item_snapshot->>'quantity',
          ''
        ) ~ '^[0-9]+$'
          THEN (event.item_snapshot->>'quantity')::integer
        ELSE 0
      END AS quantity
    FROM public.kds_ticket_events event
    JOIN session_orders orders
      ON orders.id = event.order_id
    WHERE event.tenant_id = v_session.tenant_id
      AND event.event_type = 'completed'
      AND event.context->>'evidence_source' = 'legacy_live_snapshot'
      AND NOT EXISTS (
        SELECT 1
        FROM public.kds_ticket_events canonical
        WHERE canonical.tenant_id = event.tenant_id
          AND canonical.order_item_id = event.order_item_id
          AND canonical.event_type = 'completed'
          AND canonical.context->>'evidence_source'
            IS DISTINCT FROM 'legacy_live_snapshot'
      )
    ORDER BY event.order_item_id, event.occurred_at, event.id
  ),
  invoice_evidence AS (
    SELECT DISTINCT invoice.id, invoice.status
    FROM session_orders orders
    JOIN public.tax_invoices invoice
      ON invoice.order_id = orders.id
     AND invoice.tenant_id = v_session.tenant_id

    UNION

    SELECT DISTINCT invoice.id, invoice.status
    FROM session_orders orders
    JOIN public.tax_invoice_orders invoice_order
      ON invoice_order.order_id = orders.id
     AND invoice_order.tenant_id = v_session.tenant_id
    JOIN public.tax_invoices invoice
      ON invoice.id = invoice_order.tax_invoice_id
     AND invoice.tenant_id = invoice_order.tenant_id
  )
  SELECT jsonb_build_object(
    'kds_event_count', (
      SELECT count(*)::integer
      FROM public.kds_ticket_events event
      JOIN session_orders orders
        ON orders.id = event.order_id
      WHERE event.tenant_id = v_session.tenant_id
    ),
    'kds_completed_item_quantity', COALESCE((
      SELECT sum(item.quantity)::integer
      FROM completed_items item
    ), 0),
    'kds_legacy_completed_item_quantity', COALESCE((
      SELECT sum(item.quantity)::integer
      FROM legacy_completed_items item
    ), 0),
    'print_job_count', (
      SELECT count(*)::integer
      FROM public.print_jobs job
      JOIN session_orders orders
        ON orders.id = job.order_id
      WHERE job.tenant_id = v_session.tenant_id
    ),
    'printed_job_count', (
      SELECT count(*)::integer
      FROM public.print_jobs job
      JOIN session_orders orders
        ON orders.id = job.order_id
      WHERE job.tenant_id = v_session.tenant_id
        AND job.status = 'printed'
    ),
    'print_failed_count', (
      SELECT count(*)::integer
      FROM public.print_jobs job
      JOIN session_orders orders
        ON orders.id = job.order_id
      WHERE job.tenant_id = v_session.tenant_id
        AND job.status IN ('failed', 'expired')
    ),
    'invoice_count', (
      SELECT count(*)::integer FROM invoice_evidence
    ),
    'invoice_attention_count', (
      SELECT count(*)::integer
      FROM invoice_evidence invoice
      WHERE invoice.status IN ('draft', 'signing', 'submitted')
    ),
    'audit_event_count', (
      SELECT count(*)::integer
      FROM public.audit_logs audit
      WHERE audit.tenant_id = v_session.tenant_id
        AND (
          (
            audit.entity_type = 'order'
            AND audit.entity_id IN (
              SELECT orders.id FROM session_orders orders
            )
          )
          OR (
            audit.entity_type = 'payment'
            AND audit.entity_id IN (
              SELECT payment.id
              FROM public.payments payment
              JOIN session_orders orders
                ON orders.id = payment.order_id
              WHERE payment.tenant_id = v_session.tenant_id
            )
          )
          OR (
            audit.entity_type = 'webhook_event'
            AND audit.entity_id IN (
              SELECT event.id
              FROM public.webhook_events event
              JOIN session_orders orders
                ON orders.id = event.order_id
              WHERE event.tenant_id = v_session.tenant_id
            )
          )
        )
    ),
    'order_payment_state_mismatch_count', (
      SELECT count(DISTINCT orders.id)::integer
      FROM public.orders orders
      JOIN public.payments payment
        ON payment.order_id = orders.id
       AND payment.tenant_id = orders.tenant_id
       AND payment.branch_id = orders.branch_id
      WHERE orders.tenant_id = v_session.tenant_id
        AND orders.pos_session_id = v_session.id
        AND payment.status = 'completed'
        AND payment.paid_at IS NOT NULL
        AND (
          orders.payment_status IS DISTINCT FROM 'paid'
          OR orders.status = 'cancelled'
          OR payment.amount IS DISTINCT FROM orders.total_amount
        )
    ),
    'late_payment_count', (
      SELECT count(*)::integer
      FROM public.payments payment
      JOIN public.orders orders
        ON orders.id = payment.order_id
       AND orders.tenant_id = payment.tenant_id
       AND orders.branch_id = payment.branch_id
      WHERE payment.tenant_id = v_session.tenant_id
        AND orders.pos_session_id = v_session.id
        AND payment.status = 'completed'
        AND payment.paid_at IS NOT NULL
        AND (
          payment.paid_at < v_session.opened_at
          OR (
            v_session.closed_at IS NOT NULL
            AND payment.paid_at > v_session.closed_at
          )
        )
    ),
    'late_payment_amount', (
      SELECT COALESCE(sum(payment.amount), 0)::numeric
      FROM public.payments payment
      JOIN public.orders orders
        ON orders.id = payment.order_id
       AND orders.tenant_id = payment.tenant_id
       AND orders.branch_id = payment.branch_id
      WHERE payment.tenant_id = v_session.tenant_id
        AND orders.pos_session_id = v_session.id
        AND payment.status = 'completed'
        AND payment.paid_at IS NOT NULL
        AND (
          payment.paid_at < v_session.opened_at
          OR (
            v_session.closed_at IS NOT NULL
            AND payment.paid_at > v_session.closed_at
          )
        )
    )
  )
  INTO v_operational_evidence;

  v_report := jsonb_set(
    v_report,
    '{totals}',
    COALESCE(v_report->'totals', '{}'::jsonb)
      || v_money
      || v_item_counts,
    true
  );
  v_report := jsonb_set(v_report, '{payment_mix}', v_payment_mix, true);
  v_report := jsonb_set(v_report, '{hourly}', v_hourly, true);
  v_report := jsonb_set(
    v_report,
    '{peak_hour}',
    COALESCE(v_peak_hour, 'null'::jsonb),
    true
  );
  v_report := jsonb_set(v_report, '{aov_bins}', v_aov_bins, true);
  v_report := jsonb_set(v_report, '{top_items}', v_top_items, true);
  v_report := jsonb_set(
    v_report,
    '{category_breakdown}',
    v_categories,
    true
  );
  v_report := jsonb_set(v_report, '{discounts}', v_discounts, true);

  RETURN v_report || jsonb_build_object(
    'payment_attempt_summary', v_payment_attempts,
    'operational_evidence', v_operational_evidence,
    'generated_at', now()
  );
END;
$_$;


--
-- Name: FUNCTION get_pos_session_report(p_session_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_pos_session_report(p_session_id bigint) IS 'POS-session membership follows orders.pos_session_id. Money comes from completed payments, hourly buckets use payments.paid_at, and payments outside opened_at/closed_at are retained but flagged as late.';


--
-- Name: get_pos_session_report_legacy_20260725(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_session_report_legacy_20260725(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session              RECORD;
  v_totals               RECORD;
  v_payment_mix          JSONB;
  v_top_items            JSONB;
  v_categories           JSONB;
  v_total_items          INT;
  v_hourly               JSONB;
  v_peak_hour            JSONB;
  v_aov_bins             JSONB;
  v_discount_count       INT;
  v_discount_total       NUMERIC(15,2);
  v_top_discount_orders  JSONB;
  v_void_item_count      INT;
BEGIN
  SELECT
    s.id, s.tenant_id, s.branch_id, s.terminal_id,
    s.opened_at, s.closed_at, s.opening_cash, s.closing_cash,
    s.expected_cash, s.cash_difference, s.status, s.note,
    s.variance_approval_note,
    t.name AS terminal_name,
    pop.full_name AS opened_by_name,
    pcl.full_name AS closed_by_name
  INTO v_session
  FROM public.pos_sessions s
  LEFT JOIN public.pos_terminals t  ON t.id  = s.terminal_id
  LEFT JOIN public.profiles pop     ON pop.id = s.opened_by
  LEFT JOIN public.profiles pcl     ON pcl.id = s.closed_by
  WHERE s.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_session.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT
    COUNT(*) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled') AS paid_count,
    COUNT(*) FILTER (WHERE payment_status <> 'paid' AND status <> 'cancelled') AS unpaid_count,
    COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled_count,
    COALESCE(SUM(subtotal) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS gross,
    COALESCE(SUM(discount_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS discount_total,
    COALESCE(SUM(tax_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS tax_total,
    COALESCE(SUM(service_charge) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS service_total,
    COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS net,
    COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled' AND payment_method = 'cash'), 0) AS cash_revenue,
    COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled' AND (payment_method IS NULL OR payment_method <> 'cash')), 0) AS noncash_revenue
  INTO v_totals
  FROM public.orders
  WHERE pos_session_id = p_session_id
    AND tenant_id = v_session.tenant_id;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('method', payment_method, 'count', cnt, 'amount', amount)
    ORDER BY amount DESC
  ), '[]'::JSONB)
  INTO v_payment_mix
  FROM (
    SELECT payment_method, COUNT(*)::INT AS cnt, COALESCE(SUM(total_amount), 0) AS amount
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY payment_method
  ) pm;

  WITH paid_items AS (
    SELECT
      oi.menu_item_id, oi.item_name,
      mi.category_id, mc.name AS category_name,
      oi.quantity, oi.subtotal, oi.modifiers, oi.sides
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    LEFT JOIN public.menu_items mi      ON mi.id = oi.menu_item_id
    LEFT JOIN public.menu_categories mc ON mc.id = mi.category_id
    WHERE o.pos_session_id = p_session_id
      AND o.tenant_id = v_session.tenant_id
      AND o.payment_status = 'paid'
      AND o.status <> 'cancelled'
      AND oi.status <> 'cancelled'
  ),
  main_agg AS (
    SELECT item_name AS name, 'main'::TEXT AS source,
      COALESCE(SUM(quantity), 0)::INT AS qty,
      COALESCE(SUM(subtotal), 0) AS revenue
    FROM paid_items
    GROUP BY item_name
  ),
  side_agg AS (
    SELECT
      COALESCE(s ->> 'name', 'Side')::TEXT AS name,
      'side'::TEXT AS source,
      COALESCE(SUM(COALESCE((s ->> 'quantity')::INT, 1) * pi.quantity), 0)::INT AS qty,
      COALESCE(SUM(COALESCE((s ->> 'price')::NUMERIC, 0) * COALESCE((s ->> 'quantity')::INT, 1) * pi.quantity), 0) AS revenue
    FROM paid_items pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.sides) AS s
    GROUP BY s ->> 'name'
  ),
  mod_agg AS (
    SELECT
      COALESCE(m ->> 'name', 'Modifier')::TEXT AS name,
      'modifier'::TEXT AS source,
      COALESCE(SUM(pi.quantity), 0)::INT AS qty,
      COALESCE(SUM(COALESCE((m ->> 'price')::NUMERIC, 0) * pi.quantity), 0) AS revenue
    FROM paid_items pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.modifiers) AS m
    GROUP BY m ->> 'name'
  ),
  all_items AS (
    SELECT name, source, qty, revenue FROM main_agg
    UNION ALL
    SELECT name, source, qty, revenue FROM side_agg
    UNION ALL
    SELECT name, source, qty, revenue FROM mod_agg
  ),
  cat_agg AS (
    SELECT
      COALESCE(category_id, 0) AS category_id,
      COALESCE(category_name, 'Khác') AS category_name,
      COALESCE(SUM(quantity), 0)::INT AS qty,
      COALESCE(SUM(subtotal), 0) AS revenue
    FROM paid_items
    GROUP BY category_id, category_name
  )
  SELECT
    (SELECT COALESCE(jsonb_agg(jsonb_build_object('name', name, 'source', source, 'qty', qty, 'revenue', revenue) ORDER BY qty DESC, revenue DESC), '[]'::JSONB)
     FROM (SELECT name, source, qty, revenue FROM all_items ORDER BY qty DESC, revenue DESC LIMIT 10) ti),
    (SELECT COALESCE(jsonb_agg(jsonb_build_object('category_id', category_id, 'category_name', category_name, 'qty', qty, 'revenue', revenue) ORDER BY revenue DESC), '[]'::JSONB)
     FROM cat_agg),
    COALESCE((SELECT SUM(qty) FROM all_items), 0)::INT
  INTO v_top_items, v_categories, v_total_items;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('hour', hour, 'order_count', cnt, 'revenue', revenue)
    ORDER BY hour
  ), '[]'::JSONB)
  INTO v_hourly
  FROM (
    SELECT
      EXTRACT(HOUR FROM (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh'))::INT AS hour,
      COUNT(*)::INT AS cnt,
      COALESCE(SUM(total_amount), 0) AS revenue
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY 1
  ) h;

  SELECT
    CASE WHEN cnt > 0 THEN
      jsonb_build_object('hour', hour, 'order_count', cnt, 'revenue', revenue)
    ELSE NULL END
  INTO v_peak_hour
  FROM (
    SELECT
      EXTRACT(HOUR FROM (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh'))::INT AS hour,
      COUNT(*)::INT AS cnt,
      COALESCE(SUM(total_amount), 0) AS revenue
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY 1
    ORDER BY revenue DESC, cnt DESC
    LIMIT 1
  ) p;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('label', label, 'count', cnt) ORDER BY ord
  ), '[]'::JSONB)
  INTO v_aov_bins
  FROM (
    SELECT label, ord, COUNT(*)::INT AS cnt
    FROM (
      SELECT
        CASE
          WHEN total_amount <= 50000  THEN '≤50.000đ'
          WHEN total_amount <= 100000 THEN '50.000–100.000đ'
          WHEN total_amount <= 200000 THEN '100.000–200.000đ'
          WHEN total_amount <= 500000 THEN '200.000–500.000đ'
          ELSE '>500.000đ'
        END AS label,
        CASE
          WHEN total_amount <= 50000  THEN 1
          WHEN total_amount <= 100000 THEN 2
          WHEN total_amount <= 200000 THEN 3
          WHEN total_amount <= 500000 THEN 4
          ELSE 5
        END AS ord
      FROM public.orders
      WHERE pos_session_id = p_session_id
        AND tenant_id = v_session.tenant_id
        AND payment_status = 'paid'
        AND status <> 'cancelled'
    ) b
    GROUP BY label, ord
  ) g;

  SELECT COUNT(*)::INT, COALESCE(SUM(discount_amount), 0)
  INTO v_discount_count, v_discount_total
  FROM public.orders
  WHERE pos_session_id = p_session_id
    AND tenant_id = v_session.tenant_id
    AND discount_amount > 0
    AND status <> 'cancelled';

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'order_id', order_id, 'order_number', order_number,
      'amount', amount, 'note', note, 'type', type, 'value', value
    ) ORDER BY amount DESC
  ), '[]'::JSONB)
  INTO v_top_discount_orders
  FROM (
    SELECT
      id AS order_id, order_number,
      discount_amount AS amount, discount_note AS note,
      discount_type AS type, discount_value AS value
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND discount_amount > 0
      AND status <> 'cancelled'
    ORDER BY discount_amount DESC
    LIMIT 10
  ) d;

  SELECT COUNT(*)::INT
  INTO v_void_item_count
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE o.pos_session_id = p_session_id
    AND o.tenant_id = v_session.tenant_id
    AND oi.status = 'cancelled';

  RETURN jsonb_build_object(
    'session', jsonb_build_object(
      'id', v_session.id, 'opened_at', v_session.opened_at,
      'closed_at', v_session.closed_at, 'status', v_session.status,
      'terminal_name', v_session.terminal_name,
      'opened_by_name', v_session.opened_by_name,
      'closed_by_name', v_session.closed_by_name,
      'opening_cash', v_session.opening_cash,
      'closing_cash', v_session.closing_cash,
      'expected_cash', v_session.expected_cash,
      'cash_difference', v_session.cash_difference,
      'note', v_session.note,
      'variance_approval_note', v_session.variance_approval_note
    ),
    'totals', jsonb_build_object(
      'gross_revenue', v_totals.gross,
      'discount_total', v_totals.discount_total,
      'tax_total', v_totals.tax_total,
      'service_charge_total', v_totals.service_total,
      'net_revenue', v_totals.net,
      'cash_revenue', v_totals.cash_revenue,
      'noncash_revenue', v_totals.noncash_revenue,
      'paid_order_count', v_totals.paid_count,
      'unpaid_order_count', v_totals.unpaid_count,
      'cancelled_order_count', v_totals.cancelled_count,
      'void_item_count', v_void_item_count,
      'total_items', v_total_items,
      'aov', CASE WHEN v_totals.paid_count > 0 THEN ROUND(v_totals.net / v_totals.paid_count, 2) ELSE 0 END
    ),
    'payment_mix', v_payment_mix,
    'top_items', v_top_items,
    'category_breakdown', v_categories,
    'aov_bins', v_aov_bins,
    'hourly', v_hourly,
    'peak_hour', v_peak_hour,
    'discounts', jsonb_build_object(
      'count', v_discount_count, 'total', v_discount_total,
      'top_orders', v_top_discount_orders
    ),
    'generated_at', now()
  );
END;
$$;


