--
-- Name: get_revenue_by_hour(bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_by_hour(p_branch_id bigint DEFAULT NULL::bigint, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(dow smallint, hour smallint, order_count bigint, net_revenue numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_start_utc timestamptz;
  v_end_utc timestamptz;
  v_has_tenant_scope boolean;
  v_branch_ids bigint[];
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_start_date IS NULL
    OR p_end_date IS NULL
    OR p_start_date > p_end_date
    OR (p_end_date - p_start_date) + 1 > 90
  THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  SELECT scope.has_tenant_scope, scope.branch_ids
  INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') scope;

  IF p_branch_id IS NULL THEN
    IF NOT (
      v_has_tenant_scope
      OR COALESCE(cardinality(v_branch_ids), 0) > 0
    ) THEN
      RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (
    v_has_tenant_scope
    OR p_branch_id = ANY(COALESCE(v_branch_ids, ARRAY[]::bigint[]))
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  v_start_utc :=
    p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end_utc :=
    (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  SELECT
    EXTRACT(
      DOW FROM payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
    )::smallint,
    EXTRACT(
      HOUR FROM payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
    )::smallint,
    count(DISTINCT payment.order_id)::bigint,
    COALESCE(sum(payment.amount), 0)::numeric
  FROM public.payments payment
  JOIN public.orders orders
    ON orders.id = payment.order_id
   AND orders.tenant_id = payment.tenant_id
   AND orders.branch_id = payment.branch_id
  WHERE payment.tenant_id = v_tenant
    AND payment.status = 'completed'
    AND payment.paid_at >= v_start_utc
    AND payment.paid_at < v_end_utc
    AND (
      (p_branch_id IS NOT NULL AND payment.branch_id = p_branch_id)
      OR (
        p_branch_id IS NULL
        AND (
          v_has_tenant_scope
          OR payment.branch_id = ANY(
            COALESCE(v_branch_ids, ARRAY[]::bigint[])
          )
        )
      )
    )
  GROUP BY 1, 2
  ORDER BY 1, 2;
END;
$$;


--
-- Name: FUNCTION get_revenue_by_hour(p_branch_id bigint, p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_revenue_by_hour(p_branch_id bigint, p_start_date date, p_end_date date) IS 'Hourly collected revenue from completed payments, bucketed by payments.paid_at in Asia/Ho_Chi_Minh. Order mirror state never suppresses payment truth.';


--
-- Name: get_revenue_kpis(bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_kpis(p_branch_id bigint, p_start_date date, p_end_date date) RETURNS TABLE(net_revenue numeric, subtotal_revenue numeric, discount_amount numeric, total_tax numeric, vat_by_rate jsonb, vat_total numeric, order_count bigint, total_covers bigint, cash_revenue numeric, vietqr_revenue numeric, dine_in_revenue numeric, takeaway_revenue numeric, voided_amount numeric, voided_count bigint, refreshed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_start_utc timestamptz;
  v_end_utc timestamptz;
  v_has_tenant_scope boolean;
  v_branch_ids bigint[];
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_start_date IS NULL
    OR p_end_date IS NULL
    OR p_start_date > p_end_date
  THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  SELECT scope.has_tenant_scope, scope.branch_ids
  INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') scope;

  IF p_branch_id IS NULL THEN
    IF NOT (
      v_has_tenant_scope
      OR COALESCE(cardinality(v_branch_ids), 0) > 0
    ) THEN
      RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (
    v_has_tenant_scope
    OR p_branch_id = ANY(COALESCE(v_branch_ids, ARRAY[]::bigint[]))
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  v_start_utc :=
    p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end_utc :=
    (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  WITH paid AS MATERIALIZED (
    SELECT
      payment.id AS payment_id,
      payment.order_id,
      payment.branch_id,
      payment.tenant_id,
      payment.method,
      payment.amount AS payment_amount,
      payment.paid_at,
      orders.total_amount,
      orders.subtotal,
      orders.discount_amount,
      orders.tax_amount,
      orders.order_type
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_tenant
      AND payment.status = 'completed'
      AND payment.paid_at >= v_start_utc
      AND payment.paid_at < v_end_utc
      AND (
        (p_branch_id IS NOT NULL AND payment.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR payment.branch_id = ANY(
              COALESCE(v_branch_ids, ARRAY[]::bigint[])
            )
          )
        )
      )
  ),
  order_facts AS MATERIALIZED (
    SELECT DISTINCT ON (paid.tenant_id, paid.branch_id, paid.order_id)
      paid.order_id AS id,
      paid.tenant_id,
      paid.branch_id,
      paid.total_amount,
      paid.subtotal,
      paid.discount_amount,
      paid.tax_amount,
      paid.order_type
    FROM paid
    ORDER BY
      paid.tenant_id,
      paid.branch_id,
      paid.order_id,
      paid.paid_at,
      paid.payment_id
  ),
  payment_sales AS (
    SELECT
      COALESCE(sum(paid.payment_amount), 0)::numeric AS net_revenue,
      COALESCE(sum(paid.payment_amount) FILTER (
        WHERE paid.method = 'cash'
      ), 0)::numeric AS cash_revenue,
      COALESCE(sum(paid.payment_amount) FILTER (
        WHERE paid.method = 'vietqr'
      ), 0)::numeric AS vietqr_revenue,
      COALESCE(sum(paid.payment_amount) FILTER (
        WHERE paid.order_type = 'dine_in'
      ), 0)::numeric AS dine_in_revenue,
      COALESCE(sum(paid.payment_amount) FILTER (
        WHERE paid.order_type = 'takeaway'
      ), 0)::numeric AS takeaway_revenue
    FROM paid
  ),
  order_sales AS (
    SELECT
      COALESCE(sum(fact.subtotal), 0)::numeric AS subtotal_revenue,
      COALESCE(sum(fact.discount_amount), 0)::numeric AS discount_amount,
      COALESCE(sum(fact.tax_amount), 0)::numeric AS total_tax,
      count(*)::bigint AS order_count
    FROM order_facts fact
  ),
  vat_lines AS (
    SELECT
      round(item.vat_rate::numeric, 2) AS rate,
      sum(
        (item.subtotal * scale.scale)
          - (
            (item.subtotal * scale.scale)
              / (1 + item.vat_rate / 100)
          )
      ) AS vat
    FROM (
      SELECT
        fact.id AS order_id,
        fact.tenant_id,
        CASE
          WHEN sum(item.subtotal) > 0
            THEN fact.total_amount / sum(item.subtotal)
          ELSE 1
        END AS scale
      FROM order_facts fact
      JOIN public.order_items item
        ON item.tenant_id = fact.tenant_id
       AND item.order_id = fact.id
       AND item.status <> 'cancelled'
      GROUP BY fact.id, fact.tenant_id, fact.total_amount
    ) scale
    JOIN public.order_items item
      ON item.tenant_id = scale.tenant_id
     AND item.order_id = scale.order_id
     AND item.status <> 'cancelled'
    GROUP BY round(item.vat_rate::numeric, 2)
  ),
  vat_split AS (
    SELECT
      COALESCE(
        jsonb_object_agg(vat_lines.rate::text, vat_lines.vat),
        '{}'::jsonb
      ) AS vat_by_rate,
      COALESCE(sum(vat_lines.vat), 0)::numeric AS vat_total
    FROM vat_lines
  ),
  refunds AS (
    SELECT
      COALESCE(sum(payment.amount), 0)::numeric AS voided_amount,
      count(DISTINCT payment.order_id)::bigint AS voided_count
    FROM public.payments payment
    WHERE payment.tenant_id = v_tenant
      AND payment.status = 'refunded'
      AND payment.paid_at >= v_start_utc
      AND payment.paid_at < v_end_utc
      AND (
        (p_branch_id IS NOT NULL AND payment.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR payment.branch_id = ANY(
              COALESCE(v_branch_ids, ARRAY[]::bigint[])
            )
          )
        )
      )
  )
  SELECT
    payment_sales.net_revenue,
    order_sales.subtotal_revenue,
    order_sales.discount_amount,
    order_sales.total_tax,
    vat_split.vat_by_rate,
    vat_split.vat_total,
    order_sales.order_count,
    order_sales.order_count,
    payment_sales.cash_revenue,
    payment_sales.vietqr_revenue,
    payment_sales.dine_in_revenue,
    payment_sales.takeaway_revenue,
    refunds.voided_amount,
    refunds.voided_count,
    now()
  FROM payment_sales
  CROSS JOIN order_sales
  CROSS JOIN vat_split
  CROSS JOIN refunds;
END;
$$;


--
-- Name: FUNCTION get_revenue_kpis(p_branch_id bigint, p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_revenue_kpis(p_branch_id bigint, p_start_date date, p_end_date date) IS 'Finance KPIs whose collected-money fields come only from completed payments. Distinct-order sales facts remain visible even when the order payment mirror is stale.';


--
-- Name: get_revenue_rollup(bigint, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_rollup(p_branch_id bigint, p_start_date date, p_end_date date, p_granularity text) RETURNS TABLE(period_start date, period_end date, period_label text, branch_id bigint, order_count bigint, total_revenue numeric, total_tax numeric, subtotal_revenue numeric, discount_amount numeric, cash_revenue numeric, vietqr_revenue numeric, dine_in_revenue numeric, takeaway_revenue numeric, total_covers bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_start_utc timestamptz;
  v_end_utc timestamptz;
  v_has_tenant_scope boolean;
  v_branch_ids bigint[];
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_granularity NOT IN ('day', 'week', 'month')
    OR p_start_date IS NULL
    OR p_end_date IS NULL
    OR p_start_date > p_end_date
  THEN
    RAISE EXCEPTION 'invalid_revenue_scope' USING ERRCODE = '22023';
  END IF;

  SELECT scope.has_tenant_scope, scope.branch_ids
  INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') scope;

  IF p_branch_id IS NULL THEN
    IF NOT (
      v_has_tenant_scope
      OR COALESCE(cardinality(v_branch_ids), 0) > 0
    ) THEN
      RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (
    v_has_tenant_scope
    OR p_branch_id = ANY(COALESCE(v_branch_ids, ARRAY[]::bigint[]))
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  v_start_utc :=
    p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end_utc :=
    (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  WITH paid AS MATERIALIZED (
    SELECT
      CASE p_granularity
        WHEN 'day' THEN (
          payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
        )::date
        WHEN 'week' THEN date_trunc(
          'week',
          payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
        )::date
        WHEN 'month' THEN date_trunc(
          'month',
          payment.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
        )::date
      END AS bucket_start,
      payment.id AS payment_id,
      payment.order_id,
      payment.branch_id,
      payment.tenant_id,
      payment.method,
      payment.amount,
      payment.paid_at,
      orders.total_amount,
      orders.tax_amount,
      orders.subtotal,
      orders.discount_amount,
      orders.order_type
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_tenant
      AND payment.status = 'completed'
      AND payment.paid_at >= v_start_utc
      AND payment.paid_at < v_end_utc
      AND (
        (p_branch_id IS NOT NULL AND payment.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR payment.branch_id = ANY(
              COALESCE(v_branch_ids, ARRAY[]::bigint[])
            )
          )
        )
      )
  ),
  payment_buckets AS (
    SELECT
      paid.bucket_start,
      paid.branch_id,
      COALESCE(sum(paid.amount), 0)::numeric AS total_revenue,
      COALESCE(sum(paid.amount) FILTER (
        WHERE paid.method = 'cash'
      ), 0)::numeric AS cash_revenue,
      COALESCE(sum(paid.amount) FILTER (
        WHERE paid.method = 'vietqr'
      ), 0)::numeric AS vietqr_revenue,
      COALESCE(sum(paid.amount) FILTER (
        WHERE paid.order_type = 'dine_in'
      ), 0)::numeric AS dine_in_revenue,
      COALESCE(sum(paid.amount) FILTER (
        WHERE paid.order_type = 'takeaway'
      ), 0)::numeric AS takeaway_revenue
    FROM paid
    GROUP BY paid.bucket_start, paid.branch_id
  ),
  order_facts AS (
    SELECT DISTINCT ON (
      paid.bucket_start,
      paid.branch_id,
      paid.tenant_id,
      paid.order_id
    )
      paid.bucket_start,
      paid.branch_id,
      paid.tenant_id,
      paid.order_id,
      paid.tax_amount,
      paid.subtotal,
      paid.discount_amount
    FROM paid
    ORDER BY
      paid.bucket_start,
      paid.branch_id,
      paid.tenant_id,
      paid.order_id,
      paid.paid_at,
      paid.payment_id
  ),
  order_buckets AS (
    SELECT
      fact.bucket_start,
      fact.branch_id,
      count(*)::bigint AS order_count,
      COALESCE(sum(fact.tax_amount), 0)::numeric AS total_tax,
      COALESCE(sum(fact.subtotal), 0)::numeric AS subtotal_revenue,
      COALESCE(sum(fact.discount_amount), 0)::numeric AS discount_amount
    FROM order_facts fact
    GROUP BY fact.bucket_start, fact.branch_id
  )
  SELECT
    payment.bucket_start,
    CASE p_granularity
      WHEN 'day' THEN payment.bucket_start
      WHEN 'week' THEN payment.bucket_start + 6
      WHEN 'month' THEN (
        payment.bucket_start + INTERVAL '1 month - 1 day'
      )::date
    END,
    CASE p_granularity
      WHEN 'day' THEN to_char(payment.bucket_start, 'DD/MM/YYYY')
      WHEN 'week' THEN
        'Tuần ' || to_char(payment.bucket_start, 'IW') || ' ('
          || to_char(payment.bucket_start, 'DD/MM') || '-'
          || to_char(payment.bucket_start + 6, 'DD/MM/YYYY') || ')'
      WHEN 'month' THEN
        'Tháng ' || to_char(payment.bucket_start, 'MM/YYYY')
    END,
    payment.branch_id,
    orders.order_count,
    payment.total_revenue,
    orders.total_tax,
    orders.subtotal_revenue,
    orders.discount_amount,
    payment.cash_revenue,
    payment.vietqr_revenue,
    payment.dine_in_revenue,
    payment.takeaway_revenue,
    orders.order_count
  FROM payment_buckets payment
  JOIN order_buckets orders
    ON orders.bucket_start = payment.bucket_start
   AND orders.branch_id = payment.branch_id
  ORDER BY payment.bucket_start, payment.branch_id;
END;
$$;


--
-- Name: FUNCTION get_revenue_rollup(p_branch_id bigint, p_start_date date, p_end_date date, p_granularity text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_revenue_rollup(p_branch_id bigint, p_start_date date, p_end_date date, p_granularity text) IS 'Revenue rollup from completed payments and payments.paid_at. Order mirror state never suppresses collected money; daily drill exposes mismatches.';


--
-- Name: get_stock_movement_report(date, date, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stock_movement_report(p_start_date date, p_end_date date, p_branch_id bigint DEFAULT NULL::bigint) RETURNS TABLE(ingredient_id bigint, ingredient_name text, unit text, opening numeric, grn_receipt numeric, transfer_in numeric, transfer_out numeric, consumption numeric, production_consumption numeric, production_output numeric, adjustment numeric, closing numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_start timestamptz;
  v_end timestamptz;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL THEN
    IF NOT (
      public.has_permission_any('inventory:read')
      OR public.has_permission_any('reports:view_branch')
      OR public.has_permission_any('reports:view_tenant')
    ) THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (
    public.has_permission(p_branch_id, 'inventory:read')
    OR public.has_permission(NULL, 'reports:view_branch')
    OR public.has_permission(NULL, 'reports:view_tenant')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_start := p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end := (p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  WITH loc AS (
    SELECT il.id
    FROM public.inventory_locations il
    JOIN public.branches b ON b.id = il.branch_id
    WHERE il.tenant_id = v_tenant
      AND il.is_active = true
      AND (p_branch_id IS NULL OR il.branch_id = p_branch_id)
      AND (
        il.location_kind = 'warehouse'
        OR (b.branch_kind = 'central_kitchen' AND il.location_kind = 'production_storage')
      )
  ),
  cur AS (
    SELECT sl.ingredient_id, SUM(sl.current_quantity) AS current_quantity
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.location_id IN (SELECT id FROM loc)
      AND (p_branch_id IS NULL OR sl.branch_id = p_branch_id)
    GROUP BY sl.ingredient_id
  ),
  aft AS (
    SELECT sm.ingredient_id, SUM(sm.quantity_change) AS after_sum
    FROM public.stock_movements sm
    WHERE sm.tenant_id = v_tenant
      AND sm.location_id IN (SELECT id FROM loc)
      AND (p_branch_id IS NULL OR sm.branch_id = p_branch_id)
      AND sm.created_at >= v_end
    GROUP BY sm.ingredient_id
  ),
  per AS (
    SELECT
      sm.ingredient_id,
      SUM(sm.quantity_change) FILTER (WHERE sm.type IN ('grn_receipt', 'grn_amend')) AS grn_receipt,
      SUM(sm.quantity_change) FILTER (WHERE sm.type = 'transfer_in') AS transfer_in,
      SUM(sm.quantity_change) FILTER (WHERE sm.type = 'transfer_out') AS transfer_out,
      SUM(sm.quantity_change) FILTER (WHERE sm.type = 'consumption') AS consumption,
      SUM(sm.quantity_change) FILTER (WHERE sm.type = 'production_consumption') AS production_consumption,
      SUM(sm.quantity_change) FILTER (WHERE sm.type = 'production_output') AS production_output,
      SUM(sm.quantity_change) FILTER (WHERE sm.type IN ('adjustment', 'count_adjustment', 'supplier_return', 'refund_restore')) AS adjustment
    FROM public.stock_movements sm
    WHERE sm.tenant_id = v_tenant
      AND sm.location_id IN (SELECT id FROM loc)
      AND (p_branch_id IS NULL OR sm.branch_id = p_branch_id)
      AND sm.created_at >= v_start
      AND sm.created_at < v_end
    GROUP BY sm.ingredient_id
  ),
  computed AS (
    SELECT
      ing.id AS ingredient_id,
      ing.name AS ingredient_name,
      public.inventory_entry_unit_code(v_tenant, ing.id, NULL) AS unit,
      COALESCE(cur.current_quantity, 0) - COALESCE(aft.after_sum, 0) AS closing,
      COALESCE(per.grn_receipt, 0)
        + COALESCE(per.transfer_in, 0)
        + COALESCE(per.transfer_out, 0)
        + COALESCE(per.consumption, 0)
        + COALESCE(per.production_consumption, 0)
        + COALESCE(per.production_output, 0)
        + COALESCE(per.adjustment, 0) AS period_total,
      COALESCE(per.grn_receipt, 0) AS grn_receipt,
      COALESCE(per.transfer_in, 0) AS transfer_in,
      COALESCE(per.transfer_out, 0) AS transfer_out,
      COALESCE(per.consumption, 0) AS consumption,
      COALESCE(per.production_consumption, 0) AS production_consumption,
      COALESCE(per.production_output, 0) AS production_output,
      COALESCE(per.adjustment, 0) AS adjustment
    FROM public.ingredients ing
    LEFT JOIN cur ON cur.ingredient_id = ing.id
    LEFT JOIN aft ON aft.ingredient_id = ing.id
    LEFT JOIN per ON per.ingredient_id = ing.id
    WHERE ing.tenant_id = v_tenant
      AND ing.is_active = true
  )
  SELECT
    c.ingredient_id,
    c.ingredient_name,
    c.unit,
    c.closing - c.period_total AS opening,
    c.grn_receipt,
    c.transfer_in,
    c.transfer_out,
    c.consumption,
    c.production_consumption,
    c.production_output,
    c.adjustment,
    c.closing
  FROM computed c
  WHERE c.closing - c.period_total <> 0
     OR c.closing <> 0
     OR c.period_total <> 0
  ORDER BY c.ingredient_name;
END;
$$;


--
-- Name: get_stocktake_lines_blind(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stocktake_lines_blind(p_session_id bigint) RETURNS TABLE(line_id bigint, ingredient_id bigint, ingredient_name text, unit text, abc_class character, round_no smallint, counted_quantity numeric, counted_by uuid, counted_at timestamp with time zone, needs_recount boolean, is_final boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_ss record;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT s.branch_id, s.tenant_id
  INTO v_ss
  FROM public.stocktake_sessions s
  WHERE s.id = p_session_id;

  IF NOT FOUND OR v_ss.tenant_id <> v_tenant THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    sl.id,
    sl.ingredient_id,
    ing.name,
    public.inventory_entry_unit_code(v_tenant, ing.id, NULL),
    sl.abc_class,
    sl.round_no,
    sl.counted_quantity,
    sl.counted_by,
    sl.counted_at,
    sl.needs_recount,
    sl.is_final
  FROM public.stocktake_lines sl
  JOIN public.ingredients ing ON ing.id = sl.ingredient_id
  WHERE sl.session_id = p_session_id
  ORDER BY sl.round_no, ing.name;
END;
$$;


--
-- Name: get_supplier_invoice_valuation_summary(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_supplier_invoice_valuation_summary(p_invoice_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_kind text;
  v_status text;
  v_provisional numeric(20,2);
  v_final numeric(20,2);
  v_warning boolean;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT (
    public.has_permission_any('procurement:invoice_match')
    OR public.has_permission_any('inventory:valuation_read')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT invoice.invoice_kind
  INTO v_kind
  FROM public.supplier_invoices AS invoice
  WHERE invoice.id = p_invoice_id
    AND invoice.tenant_id = v_tenant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_kind = 'service' THEN
    RETURN pg_catalog.jsonb_build_object(
      'status', 'not_applicable',
      'provisionalValue', 0,
      'finalNetValue', 0,
      'inventoryAdjustment', 0,
      'productionInventoryAdjustment', 0,
      'foodCostVariance', 0,
      'wasteVariance', 0,
      'supplierReturnVariance', 0,
      'currentPeriodVariance', 0,
      'warning', FALSE
    );
  END IF;

  SELECT
    CASE
      WHEN pg_catalog.bool_or(
        allocation.valuation_status = 'settled_current_period'
      ) THEN 'settled_current_period'
      WHEN pg_catalog.bool_and(allocation.valuation_status = 'settled')
        THEN 'settled'
      ELSE 'not_applicable'
    END,
    coalesce(pg_catalog.sum(
      allocation.confirmed_net_inventory_amount - event.value_delta
    ), 0),
    coalesce(pg_catalog.sum(allocation.confirmed_net_inventory_amount), 0)
  INTO v_status, v_provisional, v_final
  FROM public.supplier_invoice_receipt_allocations AS allocation
  LEFT JOIN public.inventory_valuation_events AS event
    ON event.id = allocation.valuation_event_id
   AND event.tenant_id = allocation.tenant_id
  WHERE allocation.tenant_id = v_tenant
    AND allocation.supplier_invoice_id = p_invoice_id;

  SELECT coalesce(pg_catalog.bool_or(
    pg_catalog.abs(event.value_delta) >= settings.variance_warning_amount
    OR (
      allocation.confirmed_net_inventory_amount - event.value_delta > 0
      AND pg_catalog.abs(event.value_delta) * 100
        / (
          allocation.confirmed_net_inventory_amount - event.value_delta
        ) >= settings.variance_warning_percent
    )
  ), FALSE)
  INTO v_warning
  FROM public.inventory_valuation_events AS event
  JOIN public.supplier_invoice_receipt_allocations AS allocation
    ON allocation.valuation_event_id = event.id
   AND allocation.tenant_id = event.tenant_id
  JOIN public.inventory_valuation_settings AS settings
    ON settings.tenant_id = event.tenant_id
  WHERE event.tenant_id = v_tenant
    AND event.source_invoice_id = p_invoice_id;

  RETURN pg_catalog.jsonb_build_object(
    'status', coalesce(v_status, 'not_applicable'),
    'provisionalValue', v_provisional,
    'finalNetValue', v_final,
    'inventoryAdjustment', coalesce((
      SELECT pg_catalog.sum(value_allocation.allocated_value)
      FROM public.inventory_value_allocations AS value_allocation
      JOIN public.inventory_valuation_events AS event
        ON event.id = value_allocation.valuation_event_id
       AND event.tenant_id = value_allocation.tenant_id
      WHERE event.tenant_id = v_tenant
        AND event.source_invoice_id = p_invoice_id
        AND value_allocation.allocation_bucket IN (
          'inventory',
          'transfer_holder'
        )
    ), 0),
    'productionInventoryAdjustment', coalesce((
      SELECT pg_catalog.sum(value_allocation.allocated_value)
      FROM public.inventory_value_allocations AS value_allocation
      JOIN public.inventory_valuation_events AS event
        ON event.id = value_allocation.valuation_event_id
       AND event.tenant_id = value_allocation.tenant_id
      WHERE event.tenant_id = v_tenant
        AND event.source_invoice_id = p_invoice_id
        AND value_allocation.allocation_bucket = 'production_inventory'
    ), 0),
    'foodCostVariance', coalesce((
      SELECT pg_catalog.sum(value_allocation.allocated_value)
      FROM public.inventory_value_allocations AS value_allocation
      JOIN public.inventory_valuation_events AS event
        ON event.id = value_allocation.valuation_event_id
       AND event.tenant_id = value_allocation.tenant_id
      WHERE event.tenant_id = v_tenant
        AND event.source_invoice_id = p_invoice_id
        AND value_allocation.allocation_bucket = 'food_cost'
    ), 0),
    'wasteVariance', coalesce((
      SELECT pg_catalog.sum(value_allocation.allocated_value)
      FROM public.inventory_value_allocations AS value_allocation
      JOIN public.inventory_valuation_events AS event
        ON event.id = value_allocation.valuation_event_id
       AND event.tenant_id = value_allocation.tenant_id
      WHERE event.tenant_id = v_tenant
        AND event.source_invoice_id = p_invoice_id
        AND value_allocation.allocation_bucket IN (
          'waste',
          'stocktake_loss',
          'transfer_loss'
        )
    ), 0),
    'supplierReturnVariance', coalesce((
      SELECT pg_catalog.sum(value_allocation.allocated_value)
      FROM public.inventory_value_allocations AS value_allocation
      JOIN public.inventory_valuation_events AS event
        ON event.id = value_allocation.valuation_event_id
       AND event.tenant_id = value_allocation.tenant_id
      WHERE event.tenant_id = v_tenant
        AND event.source_invoice_id = p_invoice_id
        AND value_allocation.allocation_bucket = 'supplier_return'
    ), 0),
    'currentPeriodVariance', coalesce((
      SELECT pg_catalog.sum(value_allocation.allocated_value)
      FROM public.inventory_value_allocations AS value_allocation
      JOIN public.inventory_valuation_events AS event
        ON event.id = value_allocation.valuation_event_id
       AND event.tenant_id = value_allocation.tenant_id
      WHERE event.tenant_id = v_tenant
        AND event.source_invoice_id = p_invoice_id
        AND value_allocation.allocation_bucket IN (
          'legacy_purchase_price_variance',
          'rounding'
        )
    ), 0),
    'warning', v_warning
  );
END;
$$;


--
-- Name: get_tax_invoice_submission_snapshot_as_system(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tax_invoice_submission_snapshot_as_system(p_job_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role_required' USING ERRCODE = '42501';
  END IF;
  RETURN (
    SELECT submission_snapshot
    FROM public.tax_invoice_issue_jobs
    WHERE id = p_job_id
  );
END;
$$;


--
-- Name: get_theoretical_consumption(bigint, timestamp with time zone, timestamp with time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_theoretical_consumption(p_branch_id bigint DEFAULT NULL::bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_order_statuses text[] DEFAULT NULL::text[]) RETURNS TABLE(ingredient_id bigint, theoretical_qty numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH allowed AS (
    SELECT b.id
    FROM public.branches b
    WHERE b.tenant_id = public.auth_tenant_id()
      AND (
        public.has_permission(b.id, 'orders:read')
        OR public.has_permission(b.id, 'kds:use')
      )
  )
  SELECT
    r.ingredient_id,
    sum(oi.quantity * r.quantity / CASE WHEN COALESCE(r.yield_factor, 1) > 0 THEN r.yield_factor ELSE 1 END)::numeric
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  JOIN public.recipes r ON r.menu_item_id = oi.menu_item_id AND r.tenant_id = oi.tenant_id
  WHERE oi.tenant_id = public.auth_tenant_id()
    AND o.branch_id IN (SELECT id FROM allowed)
    AND oi.status <> 'cancelled'
    AND (p_order_statuses IS NULL OR o.status = ANY (p_order_statuses))
    AND (p_branch_id IS NULL OR o.branch_id = p_branch_id)
    AND (p_from IS NULL OR o.created_at >= p_from)
    AND (p_to IS NULL OR o.created_at < p_to)
  GROUP BY r.ingredient_id;
$$;


--
-- Name: get_top_items(bigint, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_items(p_branch_id bigint DEFAULT NULL::bigint, p_period_start date DEFAULT NULL::date, p_limit integer DEFAULT 20) RETURNS TABLE(period_start date, period_end date, branch_id bigint, tenant_id bigint, menu_item_id bigint, item_name text, quantity_sold numeric, revenue numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_period_start DATE;
  v_period_end DATE;
BEGIN
  v_period_start := COALESCE(
    p_period_start,
    date_trunc('month', (now() AT TIME ZONE 'Asia/Ho_Chi_Minh'))::date
  );
  v_period_end := (date_trunc('month', v_period_start)::date + INTERVAL '1 month - 1 day')::date;

  RETURN QUERY
  SELECT *
  FROM public.get_top_items(
    p_branch_id,
    v_period_start,
    v_period_end,
    p_limit
  );
END;
$$;


--
-- Name: FUNCTION get_top_items(p_branch_id bigint, p_period_start date, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_top_items(p_branch_id bigint, p_period_start date, p_limit integer) IS 'Compatibility wrapper for month-bucket top items; delegates to get_top_items(branch, start, end, limit).';


--
-- Name: get_top_items(bigint, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_items(p_branch_id bigint, p_start_date date, p_end_date date, p_limit integer DEFAULT 20) RETURNS TABLE(period_start date, period_end date, branch_id bigint, tenant_id bigint, menu_item_id bigint, item_name text, quantity_sold numeric, revenue numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_effective_limit INT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'start/end required' USING ERRCODE = '22023';
  END IF;

  IF p_start_date > p_end_date THEN
    RAISE EXCEPTION 'start > end' USING ERRCODE = '22023';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NULL THEN
    IF NOT (v_has_tenant_scope OR COALESCE(cardinality(v_branch_ids), 0) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_effective_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 200));
  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH paid_orders AS MATERIALIZED (
    SELECT DISTINCT
      o.id,
      o.branch_id,
      o.tenant_id
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
  ),
  paid_items AS MATERIALIZED (
    SELECT
      oi.id AS order_item_id,
      po.branch_id,
      po.tenant_id,
      oi.menu_item_id,
      oi.item_name,
      oi.quantity::NUMERIC AS parent_quantity,
      COALESCE(oi.subtotal, 0)::NUMERIC AS line_revenue,
      CASE
        WHEN jsonb_typeof(oi.sides) = 'array' THEN oi.sides
        ELSE '[]'::JSONB
      END AS sides
    FROM paid_orders po
    JOIN public.order_items oi
      ON oi.tenant_id = po.tenant_id
     AND oi.order_id = po.id
     AND oi.status <> 'cancelled'
  ),
  side_lines AS (
    SELECT
      pi.order_item_id,
      pi.branch_id,
      pi.tenant_id,
      (side_el ->> 'side_item_id')::BIGINT AS menu_item_id,
      COALESCE(NULLIF(side_el ->> 'name', ''), 'Mon an kem')::TEXT AS item_name,
      pi.parent_quantity,
      CASE
        WHEN COALESCE(side_el ->> 'quantity', '') ~ '^[0-9]+(\.[0-9]+)?$'
          THEN GREATEST((side_el ->> 'quantity')::NUMERIC, 0)
        ELSE 1
      END AS quantity_per_parent,
      CASE
        WHEN COALESCE(side_el ->> 'price', '') ~ '^[0-9]+(\.[0-9]+)?$'
          THEN GREATEST((side_el ->> 'price')::NUMERIC, 0)
        ELSE 0
      END AS unit_price
    FROM paid_items pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  ),
  side_totals_by_line AS (
    SELECT
      order_item_id,
      COALESCE(SUM(quantity_per_parent * unit_price * parent_quantity), 0)::NUMERIC AS side_revenue
    FROM side_lines
    GROUP BY order_item_id
  ),
  main_components AS (
    SELECT
      pi.branch_id,
      pi.tenant_id,
      pi.menu_item_id,
      pi.item_name,
      COALESCE(SUM(pi.parent_quantity), 0)::NUMERIC AS quantity_sold,
      COALESCE(
        SUM(GREATEST(pi.line_revenue - COALESCE(st.side_revenue, 0), 0)),
        0
      )::NUMERIC AS revenue
    FROM paid_items pi
    LEFT JOIN side_totals_by_line st
      ON st.order_item_id = pi.order_item_id
    GROUP BY pi.branch_id, pi.tenant_id, pi.menu_item_id, pi.item_name
  ),
  side_components AS (
    SELECT
      sl.branch_id,
      sl.tenant_id,
      sl.menu_item_id,
      MAX(sl.item_name) AS item_name,
      COALESCE(SUM(sl.parent_quantity * sl.quantity_per_parent), 0)::NUMERIC AS quantity_sold,
      COALESCE(SUM(sl.parent_quantity * sl.quantity_per_parent * sl.unit_price), 0)::NUMERIC AS revenue
    FROM side_lines sl
    GROUP BY sl.branch_id, sl.tenant_id, sl.menu_item_id
  ),
  component_rows AS (
    SELECT
      mc.branch_id,
      mc.tenant_id,
      mc.menu_item_id,
      mc.item_name,
      mc.quantity_sold,
      mc.revenue
    FROM main_components mc
    UNION ALL
    SELECT
      sc.branch_id,
      sc.tenant_id,
      sc.menu_item_id,
      sc.item_name,
      sc.quantity_sold,
      sc.revenue
    FROM side_components sc
  ),
  component_agg AS (
    SELECT
      cr.branch_id,
      cr.tenant_id,
      cr.menu_item_id,
      MAX(cr.item_name) AS item_name,
      COALESCE(SUM(cr.quantity_sold), 0)::NUMERIC AS quantity_sold,
      COALESCE(SUM(cr.revenue), 0)::NUMERIC AS revenue
    FROM component_rows cr
    GROUP BY cr.branch_id, cr.tenant_id, cr.menu_item_id
  )
  SELECT
    p_start_date AS period_start,
    p_end_date AS period_end,
    ca.branch_id,
    ca.tenant_id,
    ca.menu_item_id,
    ca.item_name,
    ca.quantity_sold,
    ca.revenue
  FROM component_agg ca
  ORDER BY ca.quantity_sold DESC, ca.revenue DESC, ca.item_name ASC
  LIMIT v_effective_limit;
END;
$_$;


--
-- Name: FUNCTION get_top_items(p_branch_id bigint, p_start_date date, p_end_date date, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_top_items(p_branch_id bigint, p_start_date date, p_end_date date, p_limit integer) IS 'Live paid-at top items for an explicit Vietnam-local date range. Decomposes order_items.sides into separate menu-item rows and subtracts side revenue from the main line.';


--
-- Name: grant_permission(uuid, bigint, text, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_permission(p_target_user uuid, p_branch_id bigint, p_permission_key text, p_source_template bigint DEFAULT NULL::bigint, p_valid_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT;
  v_target_tenant BIGINT;
  v_grant_id  BIGINT;
  v_scope     TEXT;
  v_from      TIMESTAMPTZ := COALESCE(p_valid_from, now());
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'staff:assign_permission') THEN
    RAISE EXCEPTION 'forbidden: missing staff:assign_permission' USING ERRCODE = '42501';
  END IF;

  IF p_target_user = auth.uid() THEN
    RAISE EXCEPTION 'cannot_self_assign_permissions' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.profiles WHERE id = auth.uid();
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'actor_no_profile' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_target_tenant FROM public.profiles WHERE id = p_target_user;
  IF v_target_tenant IS NULL OR v_target_tenant <> v_tenant_id THEN
    RAISE EXCEPTION 'target_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF public.auth_is_owner(p_target_user) THEN
    RAISE EXCEPTION 'cannot_manage_owner_permissions' USING ERRCODE = '42501';
  END IF;

  SELECT scope INTO v_scope
  FROM public.permission_keys
  WHERE key = p_permission_key;

  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'unknown_permission_key: %', p_permission_key USING ERRCODE = '22023';
  END IF;

  IF v_scope = 'branch' AND p_branch_id IS NULL THEN
    RAISE EXCEPTION 'permission_scope_requires_branch: %', p_permission_key USING ERRCODE = '22023';
  END IF;

  IF v_scope = 'tenant' AND p_branch_id IS NOT NULL THEN
    RAISE EXCEPTION 'permission_scope_requires_tenant: %', p_permission_key USING ERRCODE = '22023';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches WHERE id = p_branch_id AND tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'branch_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF p_valid_until IS NOT NULL AND p_valid_until <= v_from THEN
    RAISE EXCEPTION 'invalid_validity_window: valid_until must be after valid_from' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_grant_id
  FROM public.staff_permissions
  WHERE user_id = p_target_user
    AND permission_key = p_permission_key
    AND (
      (p_branch_id IS NULL AND branch_id IS NULL)
      OR branch_id = p_branch_id
    )
  LIMIT 1;

  IF v_grant_id IS NULL THEN
    INSERT INTO public.staff_permissions (
      user_id, tenant_id, branch_id, permission_key, source_template, granted_by,
      valid_from, valid_until
    ) VALUES (
      p_target_user, v_tenant_id, p_branch_id, p_permission_key, p_source_template, auth.uid(),
      v_from, p_valid_until
    )
    RETURNING id INTO v_grant_id;

    INSERT INTO public.permission_audit_log (
      tenant_id, actor_user_id, target_user_id, branch_id,
      permission_key, action, source_template_id, metadata
    ) VALUES (
      v_tenant_id, auth.uid(), p_target_user, p_branch_id,
      p_permission_key, 'grant', p_source_template,
      jsonb_build_object(
        'valid_from',  v_from,
        'valid_until', p_valid_until
      )
    );
  ELSE
    UPDATE public.staff_permissions
    SET valid_from  = LEAST(valid_from, v_from),
        valid_until = CASE
          WHEN p_valid_until IS NULL THEN NULL
          WHEN valid_until  IS NULL THEN valid_until
          ELSE GREATEST(valid_until, p_valid_until)
        END
    WHERE id = v_grant_id;
  END IF;

  RETURN v_grant_id;
END;
$$;


--
-- Name: guard_approved_refund_facts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_approved_refund_facts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.status = 'approved' THEN
    RAISE EXCEPTION 'approved_refund_immutable' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'approved' AND (
    NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
    OR NEW.payment_id IS DISTINCT FROM OLD.payment_id
    OR NEW.order_id IS DISTINCT FROM OLD.order_id
    OR NEW.amount IS DISTINCT FROM OLD.amount
    OR NEW.reason IS DISTINCT FROM OLD.reason
    OR NEW.status IS DISTINCT FROM OLD.status
    OR NEW.approved_by IS DISTINCT FROM OLD.approved_by
    OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
    OR (
      OLD.payout_method IS NOT NULL
      AND NEW.payout_method IS DISTINCT FROM OLD.payout_method
    )
  ) THEN
    RAISE EXCEPTION 'approved_refund_immutable' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_expense_match_without_supplier_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_expense_match_without_supplier_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.supplier_payments payment
    WHERE payment.tenant_id = NEW.tenant_id
      AND payment.webhook_event_id = NEW.webhook_event_id
  ) OR EXISTS (
    SELECT 1
    FROM public.refunds refund
    WHERE refund.tenant_id = NEW.tenant_id
      AND refund.webhook_event_id = NEW.webhook_event_id
  ) THEN
    RAISE EXCEPTION 'webhook_event_already_linked' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_finance_expense_evidence_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_finance_expense_evidence_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_expense_id bigint;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.transfer_content IS NOT NULL
      AND (
        auth.uid() IS NULL
        OR NEW.tenant_id IS DISTINCT FROM public.auth_tenant_id()
        OR NOT public.auth_is_owner(auth.uid())
      )
    THEN
      RAISE EXCEPTION 'expense_transfer_intent_owner_required'
        USING ERRCODE = '42501';
    END IF;

    RETURN NEW;
  END IF;

  v_expense_id := OLD.id;

  IF TG_OP = 'UPDATE'
    AND current_setting('app.expense_payment_transition_id', true) = OLD.id::text
    AND auth.uid() IS NOT NULL
    AND OLD.tenant_id IS NOT DISTINCT FROM public.auth_tenant_id()
    AND (
      public.auth_is_owner(auth.uid())
      OR public.has_position('accountant')
    )
    AND public.has_permission_any('finance:expense_create')
    AND OLD.category <> 'bank_deposit'
    AND to_jsonb(NEW)
      - 'payment_method'
      - 'paid_at'
      - 'transfer_content'
      - 'updated_at'
      = to_jsonb(OLD)
      - 'payment_method'
      - 'paid_at'
      - 'transfer_content'
      - 'updated_at'
    AND NOT EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches match
      WHERE match.tenant_id = OLD.tenant_id
        AND match.expense_id = OLD.id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.webhook_events event
      WHERE event.tenant_id = OLD.tenant_id
        AND event.provider = 'sepay'
        AND event.expense_id = OLD.id
    )
    AND (
      (
        OLD.payment_method = 'unpaid'
        AND OLD.paid_at IS NULL
        AND (
          (
            NEW.payment_method = 'cash'
            AND NEW.paid_at IS NOT NULL
            AND NEW.transfer_content IS NULL
          ) OR (
            NEW.payment_method = 'transfer'
            AND NEW.paid_at IS NOT NULL
          ) OR (
            NEW.payment_method = 'unpaid'
            AND NEW.paid_at IS NULL
          )
        )
      ) OR (
        OLD.paid_at IS NOT NULL
        AND OLD.payment_method IN ('cash', 'transfer')
        AND (
          (
            NEW.payment_method = 'cash'
            AND NEW.paid_at IS NOT NULL
            AND NEW.transfer_content IS NULL
          ) OR (
            NEW.payment_method = 'transfer'
            AND NEW.paid_at IS NOT NULL
            AND NEW.transfer_content IS NULL
          ) OR (
            NEW.payment_method = 'unpaid'
            AND NEW.paid_at IS NULL
            AND NEW.transfer_content IS NULL
          )
        )
      )
    )
  THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
    AND current_setting('app.expense_update_id', true) = OLD.id::text
    AND auth.uid() IS NOT NULL
    AND OLD.tenant_id IS NOT DISTINCT FROM public.auth_tenant_id()
    AND (
      public.auth_is_owner(auth.uid())
      OR public.has_position('accountant')
    )
    AND public.has_permission_any('finance:expense_create')
    AND OLD.transfer_content IS NULL
    AND NEW.transfer_content IS NULL
    AND OLD.payment_method IS NOT DISTINCT FROM NEW.payment_method
    AND OLD.paid_at IS NOT DISTINCT FROM NEW.paid_at
    AND OLD.category = ANY (ARRAY[
      'rent',
      'utilities',
      'gas_fuel',
      'salary',
      'supplies',
      'repair',
      'marketing',
      'fees_tax',
      'hospitality',
      'other'
    ]::text[])
    AND NEW.category = ANY (ARRAY[
      'rent',
      'utilities',
      'gas_fuel',
      'salary',
      'supplies',
      'repair',
      'marketing',
      'fees_tax',
      'hospitality',
      'other'
    ]::text[])
    AND to_jsonb(NEW)
      - 'branch_id'
      - 'expense_date'
      - 'category'
      - 'vat_breakdown'
      - 'subtotal'
      - 'vat_amount'
      - 'amount'
      - 'note'
      - 'invoice_attachment_url'
      - 'updated_at'
      = to_jsonb(OLD)
      - 'branch_id'
      - 'expense_date'
      - 'category'
      - 'vat_breakdown'
      - 'subtotal'
      - 'vat_amount'
      - 'amount'
      - 'note'
      - 'invoice_attachment_url'
      - 'updated_at'
    AND NOT EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches match
      WHERE match.tenant_id = OLD.tenant_id
        AND match.expense_id = OLD.id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.webhook_events event
      WHERE event.tenant_id = OLD.tenant_id
        AND event.provider = 'sepay'
        AND event.expense_id = OLD.id
    )
  THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE'
    AND current_setting('app.expense_cancel_id', true) = OLD.id::text
    AND auth.uid() IS NOT NULL
    AND OLD.tenant_id IS NOT DISTINCT FROM public.auth_tenant_id()
    AND (
      public.auth_is_owner(auth.uid())
      OR public.has_position('accountant')
    )
    AND public.has_permission_any('finance:expense_create')
    AND OLD.category <> 'bank_deposit'
    AND NOT EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches match
      WHERE match.tenant_id = OLD.tenant_id
        AND match.expense_id = OLD.id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.webhook_events event
      WHERE event.tenant_id = OLD.tenant_id
        AND event.provider = 'sepay'
        AND event.expense_id = OLD.id
    )
  THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE'
    AND OLD.transfer_content IS NULL
    AND NEW.transfer_content IS NOT NULL
  THEN
    RAISE EXCEPTION 'expense_transfer_intent_requires_atomic_create'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE'
    AND OLD.category <> 'bank_deposit'
    AND OLD.payment_method = 'unpaid'
    AND OLD.paid_at IS NULL
    AND NEW.payment_method = 'transfer'
    AND NEW.paid_at IS NOT NULL
    AND to_jsonb(NEW) - 'payment_method' - 'paid_at' - 'updated_at'
      = to_jsonb(OLD) - 'payment_method' - 'paid_at' - 'updated_at'
    AND EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches match
      JOIN public.webhook_events event
        ON event.tenant_id = match.tenant_id
       AND event.id = match.webhook_event_id
      WHERE match.tenant_id = OLD.tenant_id
        AND match.expense_id = OLD.id
        AND event.provider = 'sepay'
        AND event.signature_valid IS TRUE
        AND event.processing_status IS DISTINCT FROM 'failed'
        AND event.payment_id IS NULL
        AND lower(COALESCE(event.payload->>'transferType', '')) = 'out'
        AND COALESCE(event.payload->>'transferAmount', '')
          ~ '^-?[0-9]+(\.[0-9]+)?$'
        AND NEW.paid_at IS NOT DISTINCT FROM event.created_at
        AND (
          OLD.transfer_content IS NULL
          OR (
            abs((event.payload->>'transferAmount')::numeric) = OLD.amount
            AND private.sepay_payload_contains_transfer_content(
              event.payload,
              OLD.transfer_content
            )
          )
        )
    )
    AND (
      OLD.transfer_content IS NULL
      OR (
        SELECT count(*)
        FROM public.bank_transaction_expense_matches match
        WHERE match.tenant_id = OLD.tenant_id
          AND match.expense_id = OLD.id
      ) = 1
    )
  THEN
    RETURN NEW;
  END IF;

  IF OLD.transfer_content IS NOT NULL THEN
    RAISE EXCEPTION 'expense_transfer_intent_immutable'
      USING ERRCODE = '42501';
  END IF;

  IF (
    OLD.category = 'bank_deposit'
    OR (TG_OP = 'UPDATE' AND NEW.category = 'bank_deposit')
    OR EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches match
      WHERE match.tenant_id = OLD.tenant_id
        AND match.expense_id = v_expense_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.webhook_events event
      WHERE event.tenant_id = OLD.tenant_id
        AND event.provider = 'sepay'
        AND event.expense_id = v_expense_id
    )
  ) THEN
    RAISE EXCEPTION 'reconciled_expense_immutable'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM public.log_audit(
      'delete',
      'expense',
      OLD.id,
      to_jsonb(OLD),
      NULL
    );
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: guard_historical_expense_split_match_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_historical_expense_split_match_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.expenses expense
    WHERE expense.tenant_id = OLD.tenant_id
      AND expense.id = OLD.expense_id
      AND expense.transfer_content IS NOT NULL
  )
    OR (
      TG_OP = 'UPDATE'
      AND EXISTS (
        SELECT 1
        FROM public.expenses expense
        WHERE expense.tenant_id = NEW.tenant_id
          AND expense.id = NEW.expense_id
          AND expense.transfer_content IS NOT NULL
      )
    )
  THEN
    RAISE EXCEPTION 'transfer_intent_match_immutable'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches sibling
    WHERE sibling.tenant_id = OLD.tenant_id
      AND sibling.expense_id = OLD.expense_id
      AND sibling.webhook_event_id <> OLD.webhook_event_id
  ) THEN
    RAISE EXCEPTION 'historical_split_match_immutable'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_supplier_payment_without_refund(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_supplier_payment_without_refund() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.webhook_event_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.refunds refund
    WHERE refund.tenant_id = NEW.tenant_id
      AND refund.webhook_event_id = NEW.webhook_event_id
  ) THEN
    RAISE EXCEPTION 'webhook_event_already_linked' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_webhook_finance_evidence_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_webhook_finance_evidence_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches m
    WHERE m.tenant_id = OLD.tenant_id
      AND m.webhook_event_id = OLD.id
  )
    OR EXISTS (
      SELECT 1
      FROM public.expenses e
      WHERE e.tenant_id = OLD.tenant_id
        AND e.id = OLD.expense_id
        AND e.category = 'bank_deposit'
    )
  THEN
    RAISE EXCEPTION 'reconciled_webhook_evidence_immutable'
      USING ERRCODE = '42501';
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_token uuid;
  v_request record;
  v_tenant_id bigint;
  v_branch_id bigint;
  v_position_code text;
  v_full_name text;
  v_provisioned_by uuid;
BEGIN
  v_token := NULLIF(
    NEW.raw_user_meta_data ->> 'provisioning_token',
    ''
  )::uuid;

  IF v_token IS NOT NULL THEN
    SELECT request.*
    INTO v_request
    FROM private.auth_user_provisioning_requests request
    WHERE request.token = v_token
      AND request.email = lower(COALESCE(NEW.email, ''))
      AND request.expires_at > now()
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'handle_new_user: invalid_or_expired_provisioning_token'
        USING ERRCODE = '42501';
    END IF;

    v_tenant_id := v_request.tenant_id;
    v_branch_id := v_request.branch_id;
    v_position_code := v_request.position_code;
    v_full_name := v_request.full_name;
    v_provisioned_by := v_request.provisioned_by;
  ELSE
    v_tenant_id := NULLIF(NEW.raw_app_meta_data ->> 'tenant_id', '')::bigint;
    v_branch_id := NULLIF(NEW.raw_app_meta_data ->> 'branch_id', '')::bigint;
    v_position_code := NULLIF(NEW.raw_app_meta_data ->> 'position_code', '');
    v_full_name := COALESCE(
      NULLIF(NEW.raw_app_meta_data ->> 'full_name', ''),
      NULLIF(NEW.raw_user_meta_data ->> 'full_name', ''),
      ''
    );
    v_provisioned_by := NULLIF(
      NEW.raw_app_meta_data ->> 'provisioned_by',
      ''
    )::uuid;
  END IF;

  IF v_tenant_id IS NULL OR v_position_code IS NULL THEN
    RAISE EXCEPTION 'handle_new_user: tenant_id_and_position_code_required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM private.provision_auth_user(
    NEW.id,
    v_tenant_id,
    v_branch_id,
    v_position_code,
    v_full_name,
    v_provisioned_by
  );

  IF v_token IS NOT NULL THEN
    DELETE FROM private.auth_user_provisioning_requests
    WHERE token = v_token;
  END IF;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb)
        - ARRAY[
          'tenant_id',
          'branch_id',
          'position_code',
          'user_role',
          'provisioned_by'
        ]::text[],
      raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb)
        - 'provisioning_token'
  WHERE id = NEW.id;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION handle_new_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_user() IS 'Creates an explicitly scoped profile and atomically materializes its exact position permission template. D088 unlocks central_supply/central_kitchen pins for central ops roles; accountant is tenant-level. Temporary until ADR 0015.';


--
-- Name: has_permission(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_branch_id bigint, p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT private.has_role_capability(
      auth.uid(),
      public.auth_tenant_id(),
      p_branch_id,
      p_key
    )
    OR EXISTS (
      SELECT 1
      FROM public.staff_permissions sp
      JOIN public.profiles pr
        ON pr.id = sp.user_id
       AND pr.tenant_id = sp.tenant_id
      JOIN public.positions po
        ON po.id = pr.position_id
       AND po.tenant_id = pr.tenant_id
      JOIN public.permission_keys pk ON pk.key = sp.permission_key
      WHERE sp.user_id = auth.uid()
        AND pr.tenant_id = public.auth_tenant_id()
        AND pr.is_active
        AND po.is_active
        AND sp.permission_key = p_key
        AND pk.is_delegable_to_staff
        AND sp.valid_from <= now()
        AND (sp.valid_until IS NULL OR sp.valid_until > now())
        AND CASE pk.scope
          WHEN 'tenant' THEN sp.branch_id IS NULL
          WHEN 'branch' THEN
            p_branch_id IS NOT NULL
            AND sp.branch_id = p_branch_id
            AND pr.branch_id = p_branch_id
          ELSE
            sp.branch_id IS NULL
            OR (
              p_branch_id IS NOT NULL
              AND sp.branch_id = p_branch_id
              AND pr.branch_id = p_branch_id
            )
        END
        AND (
          p_key <> ALL (ARRAY[
            'hr:approve_checkout',
            'hr:approve_leave_request'
          ]::text[])
          OR (
            private.staff_role_from_position_code(po.code) = 'branch_manager'
            AND p_branch_id IS NOT NULL
            AND pr.branch_id = p_branch_id
            AND sp.branch_id = p_branch_id
          )
        )
    );
$$;


--
-- Name: FUNCTION has_permission(p_branch_id bigint, p_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_permission(p_branch_id bigint, p_key text) IS 'Authoritative authz check. Call from RLS policies as has_permission(row.branch_id, ''module:action'').';


--
-- Name: has_permission_any(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission_any(p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT private.has_role_capability(
      auth.uid(),
      public.auth_tenant_id(),
      NULL,
      p_key
    )
    OR EXISTS (
      SELECT 1
      FROM public.auth_role_bindings binding
      JOIN public.auth_access_role_capabilities capability
        ON capability.role_code = binding.role_code
       AND capability.permission_key = p_key
      JOIN public.profiles profile
        ON profile.id = binding.user_id
       AND profile.tenant_id = binding.tenant_id
       AND profile.is_active
      WHERE binding.user_id = auth.uid()
        AND binding.tenant_id = public.auth_tenant_id()
        AND binding.scope_type = 'branch'
        AND binding.valid_from <= now()
        AND (binding.valid_until IS NULL OR binding.valid_until > now())
    )
    OR EXISTS (
      SELECT 1
      FROM public.staff_permissions sp
      JOIN public.profiles pr
        ON pr.id = sp.user_id
       AND pr.tenant_id = sp.tenant_id
      JOIN public.positions po
        ON po.id = pr.position_id
       AND po.tenant_id = pr.tenant_id
      JOIN public.permission_keys pk ON pk.key = sp.permission_key
      WHERE sp.user_id = auth.uid()
        AND pr.tenant_id = public.auth_tenant_id()
        AND pr.is_active
        AND po.is_active
        AND sp.permission_key = p_key
        AND pk.is_delegable_to_staff
        AND sp.valid_from <= now()
        AND (sp.valid_until IS NULL OR sp.valid_until > now())
        AND CASE pk.scope
          WHEN 'tenant' THEN sp.branch_id IS NULL
          WHEN 'branch' THEN sp.branch_id IS NOT NULL AND sp.branch_id = pr.branch_id
          ELSE sp.branch_id IS NULL OR sp.branch_id = pr.branch_id
        END
        AND (
          p_key <> ALL (ARRAY[
            'hr:approve_checkout',
            'hr:approve_leave_request'
          ]::text[])
          OR (
            private.staff_role_from_position_code(po.code) = 'branch_manager'
            AND pr.branch_id IS NOT NULL
            AND sp.branch_id = pr.branch_id
          )
        )
    );
$$;


--
-- Name: FUNCTION has_permission_any(p_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_permission_any(p_key text) IS 'Returns TRUE if user has the permission for at least one branch or tenant-wide. Use for tenant-scoped tables without branch_id.';


--
-- Name: has_position(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_position(p_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles pr
    JOIN public.positions po
      ON po.id = pr.position_id
     AND po.tenant_id = pr.tenant_id
    WHERE pr.id = auth.uid()
      AND COALESCE(pr.is_active, true) = true
      AND COALESCE(po.is_active, true) = true
      AND po.code = p_code
  )
$$;


--
-- Name: FUNCTION has_position(p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_position(p_code text) IS 'Checks the active HR position_code associated with the authenticated profile.';


--
-- Name: hddt_assert_per_order_invoice_slot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hddt_assert_per_order_invoice_slot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.order_id IS NULL
     OR NEW.status IN ('cancelled', 'replaced', 'not_required') THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('hddt-order:' || NEW.order_id::text, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM public.tax_invoice_orders tio
    JOIN public.tax_invoices summary_invoice
      ON summary_invoice.id = tio.tax_invoice_id
    WHERE tio.tenant_id = NEW.tenant_id
      AND tio.order_id = NEW.order_id
      AND summary_invoice.status NOT IN ('cancelled', 'replaced')
  ) THEN
    RAISE EXCEPTION 'order % already in active daily summary', NEW.order_id
      USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: heartbeat_zone_lock(bigint, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.heartbeat_zone_lock(p_session_id bigint, p_zone_id text, p_ttl_seconds integer DEFAULT 1800) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_branch bigint;
  v_expires_at timestamptz;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_ttl_seconds IS NULL
     OR p_ttl_seconds <= 0
     OR p_ttl_seconds > 7200 THEN
    RAISE EXCEPTION 'ttl_seconds must be in (0, 7200]'
      USING ERRCODE = '22023';
  END IF;

  SELECT session.branch_id
  INTO v_branch
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_branch,
    'inventory:stocktake_create'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.stocktake_zone_locks
  SET last_heartbeat_at = now(),
      expires_at = now() + make_interval(secs => p_ttl_seconds)
  WHERE tenant_id = v_tenant
    AND session_id = p_session_id
    AND zone_id = p_zone_id
    AND locked_by = v_uid
  RETURNING expires_at INTO v_expires_at;

  IF v_expires_at IS NULL THEN
    RAISE EXCEPTION 'zone lock not held by caller'
      USING ERRCODE = '42501';
  END IF;

  RETURN v_expires_at;
END;
$$;


--
-- Name: import_sepay_bank_transactions(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_sepay_bank_transactions(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_row jsonb;
  v_provider_transaction_id text;
  v_transfer_type text;
  v_amount numeric(15,2);
  v_balance_after numeric(15,2);
  v_occurred_at timestamptz;
  v_existing public.bank_transactions%ROWTYPE;
  v_processed_count integer := 0;
  v_inserted_count integer := 0;
  v_existing_count integer := 0;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
    OR NOT EXISTS (
      SELECT 1
      FROM public.profiles profile
      WHERE profile.id = v_actor
        AND profile.tenant_id = v_tenant_id
        AND COALESCE(profile.is_active, true)
    )
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_rows IS NULL
    OR jsonb_typeof(p_rows) <> 'array'
    OR jsonb_array_length(p_rows) = 0
    OR jsonb_array_length(p_rows) > 5000
  THEN
    RAISE EXCEPTION 'invalid_bank_transaction_rows' USING ERRCODE = '22023';
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_provider_transaction_id := NULLIF(
      btrim(v_row->>'provider_transaction_id'),
      ''
    );
    v_transfer_type := lower(COALESCE(v_row->>'transfer_type', ''));

    BEGIN
      v_amount := (v_row->>'amount')::numeric;
      v_occurred_at := (v_row->>'occurred_at')::timestamptz;
      v_balance_after := CASE
        WHEN NULLIF(btrim(v_row->>'balance_after'), '') IS NULL THEN NULL
        ELSE (v_row->>'balance_after')::numeric
      END;
    EXCEPTION
      WHEN invalid_text_representation
        OR datetime_field_overflow
        OR numeric_value_out_of_range
      THEN
        RAISE EXCEPTION 'invalid_bank_transaction_row'
          USING ERRCODE = '22023';
    END;

    IF v_provider_transaction_id IS NULL
      OR length(v_provider_transaction_id) > 128
      OR v_transfer_type NOT IN ('in', 'out')
      OR v_amount IS NULL
      OR v_amount <= 0
      OR v_occurred_at IS NULL
    THEN
      RAISE EXCEPTION 'invalid_bank_transaction_row'
        USING ERRCODE = '22023';
    END IF;

    SELECT transaction.*
    INTO v_existing
    FROM public.bank_transactions transaction
    WHERE transaction.tenant_id = v_tenant_id
      AND transaction.provider_transaction_id = v_provider_transaction_id
    FOR UPDATE;

    IF FOUND THEN
      IF v_existing.transfer_type <> v_transfer_type
        OR v_existing.amount <> v_amount
        OR date_trunc('second', v_existing.occurred_at)
          <> date_trunc('second', v_occurred_at)
      THEN
        RAISE EXCEPTION 'bank_transaction_conflict'
          USING ERRCODE = '23505';
      END IF;

      UPDATE public.bank_transactions
      SET
        balance_after = COALESCE(v_balance_after, balance_after),
        account_number = COALESCE(
          NULLIF(btrim(v_row->>'account_number'), ''),
          account_number
        ),
        code = COALESCE(NULLIF(btrim(v_row->>'code'), ''), code),
        content = COALESCE(NULLIF(btrim(v_row->>'content'), ''), content),
        reference_code = COALESCE(
          NULLIF(btrim(v_row->>'reference_code'), ''),
          reference_code
        ),
        raw_payload = CASE
          WHEN ingest_source = 'sepay_webhook' THEN raw_payload
          ELSE COALESCE(v_row->'raw_payload', v_row)
        END,
        updated_at = now()
      WHERE id = v_existing.id;

      v_existing_count := v_existing_count + 1;
    ELSE
      INSERT INTO public.bank_transactions (
        tenant_id,
        provider_transaction_id,
        occurred_at,
        transfer_type,
        amount,
        balance_after,
        account_number,
        code,
        content,
        reference_code,
        ingest_source,
        raw_payload
      ) VALUES (
        v_tenant_id,
        v_provider_transaction_id,
        v_occurred_at,
        v_transfer_type,
        v_amount,
        v_balance_after,
        NULLIF(btrim(v_row->>'account_number'), ''),
        NULLIF(btrim(v_row->>'code'), ''),
        NULLIF(btrim(v_row->>'content'), ''),
        NULLIF(btrim(v_row->>'reference_code'), ''),
        'sepay_export',
        COALESCE(v_row->'raw_payload', v_row)
      );

      v_inserted_count := v_inserted_count + 1;
    END IF;

    v_processed_count := v_processed_count + 1;
  END LOOP;

  PERFORM public.log_audit(
    'bank_transactions.sepay_import',
    'bank_transaction_import',
    NULL,
    NULL,
    jsonb_build_object(
      'processed_count', v_processed_count,
      'inserted_count', v_inserted_count,
      'existing_count', v_existing_count
    )
  );

  RETURN jsonb_build_object(
    'processed_count', v_processed_count,
    'inserted_count', v_inserted_count,
    'existing_count', v_existing_count
  );
END;
$$;


--
-- Name: FUNCTION import_sepay_bank_transactions(p_rows jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.import_sepay_bank_transactions(p_rows jsonb) IS 'Atomically imports normalized SePay export rows. Re-imports are idempotent; conflicting facts for one SePay ID fail the whole import.';


--
-- Name: initialize_finance_funds(numeric, numeric, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_finance_funds(p_cash_opening numeric, p_bank_opening numeric, p_effective_at timestamp with time zone, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_now timestamptz := statement_timestamp();
  v_effective_at timestamptz := COALESCE(p_effective_at, statement_timestamp());
  v_reason text := btrim(p_reason);
  v_existing public.finance_fund_entries%ROWTYPE;
  v_entry public.finance_fund_entries%ROWTYPE;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT (public.auth_is_owner(v_actor) OR public.has_position('accountant'))
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_cash_opening IS NULL
    OR p_bank_opening IS NULL
    OR p_cash_opening < 0
    OR p_bank_opening < 0
    OR abs(p_cash_opening) > 100000000000
    OR abs(p_bank_opening) > 100000000000
    OR NOT isfinite(v_effective_at)
    OR v_effective_at > v_now
    OR v_reason IS NULL
    OR char_length(v_reason) NOT BETWEEN 5 AND 500
    OR p_idempotency_key IS NULL
  THEN
    RAISE EXCEPTION 'finance_fund_opening_invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('finance_funds:' || v_tenant_id::text, 0)
  );

  SELECT *
  INTO v_existing
  FROM public.finance_fund_entries entry
  WHERE entry.tenant_id = v_tenant_id
    AND entry.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.entry_type = 'opening'
      AND v_existing.cash_delta = p_cash_opening
      AND v_existing.bank_delta = p_bank_opening
      AND (
        v_existing.effective_at = p_effective_at
        OR (
          p_effective_at IS NULL
          AND v_existing.effective_at = v_existing.created_at
        )
      )
      AND v_existing.reason = v_reason
    THEN
      RETURN to_jsonb(v_existing);
    END IF;

    RAISE EXCEPTION 'finance_fund_idempotency_conflict'
      USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.finance_fund_entries entry
    WHERE entry.tenant_id = v_tenant_id
      AND entry.entry_type = 'opening'
  ) THEN
    RAISE EXCEPTION 'finance_funds_already_initialized'
      USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.system_settings setting
    WHERE setting.tenant_id = v_tenant_id
      AND setting.key IN (
        'cash_opening_balance',
        'bank_opening_balance',
        'cash_opening_date'
      )
  )
    AND current_setting(
      'app.finance_legacy_cutover_idempotency_key',
      true
    ) IS DISTINCT FROM p_idempotency_key::text
  THEN
    RAISE EXCEPTION 'finance_fund_legacy_cutover_required'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.finance_fund_entries (
    tenant_id,
    entry_type,
    cash_delta,
    bank_delta,
    effective_at,
    reason,
    created_by,
    idempotency_key,
    created_at
  ) VALUES (
    v_tenant_id,
    'opening',
    p_cash_opening,
    p_bank_opening,
    v_effective_at,
    v_reason,
    v_actor,
    p_idempotency_key,
    v_now
  )
  RETURNING * INTO v_entry;

  PERFORM public.log_audit(
    'finance_fund_opening_created',
    'finance_fund_entry',
    v_entry.id,
    NULL,
    jsonb_build_object(
      'entry_type', v_entry.entry_type,
      'cash_delta', v_entry.cash_delta,
      'bank_delta', v_entry.bank_delta,
      'effective_at', v_entry.effective_at,
      'reason', v_entry.reason,
      'idempotency_key', v_entry.idempotency_key
    )
  );

  RETURN to_jsonb(v_entry);
END;
$$;


--
-- Name: FUNCTION initialize_finance_funds(p_cash_opening numeric, p_bank_opening numeric, p_effective_at timestamp with time zone, p_reason text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.initialize_finance_funds(p_cash_opening numeric, p_bank_opening numeric, p_effective_at timestamp with time zone, p_reason text, p_idempotency_key uuid) IS 'Creates one immutable tenant fund opening. Legacy evidence requires an operator-controlled transaction whose local cutover key exactly matches the request idempotency key.';


--
-- Name: inv_catalog_unit_to_base(bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_catalog_unit_to_base(p_base_unit_id bigint, p_unit jsonb, p_all_units jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_anchor_unit bigint := nullif(p_unit->>'anchor_unit_id', '')::bigint;
BEGIN
  IF coalesce((p_unit->>'is_base')::boolean, false) THEN
    RETURN 1;
  END IF;

  IF v_anchor_unit IS NOT NULL THEN
    RETURN public.inv_derive_to_base_factor(
      p_base_unit_id,
      (p_unit->>'unit_id')::bigint,
      false,
      v_anchor_unit,
      nullif(p_unit->>'anchor_factor', '')::numeric,
      p_all_units
    );
  END IF;

  RETURN coalesce((p_unit->>'to_base_factor')::numeric, 1);
END $$;


--
-- Name: inv_derive_to_base_factor(bigint, bigint, boolean, bigint, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_derive_to_base_factor(p_base_unit_id bigint, p_unit_id bigint, p_is_base boolean, p_anchor_unit_id bigint, p_anchor_factor numeric, p_all_units jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant            bigint := public.auth_tenant_id();
  v_base_dimension    text;
  v_base_is_standard  boolean;
  v_unit_dimension    text;
  v_unit_is_standard  boolean;
  v_unit_std_factor   numeric;
  v_base_std_factor   numeric;
  v_seen              bigint[] := ARRAY[]::bigint[];
  v_current_unit      bigint;
  v_current_anchor    bigint;
  v_current_factor    numeric;
  v_hop_dimension     text;
  v_hop_is_standard   boolean;
  v_hop_std_factor    numeric;
  v_acc_factor        numeric := 1;
BEGIN
  IF p_is_base THEN
    RETURN 1;
  END IF;

  SELECT dimension, is_standard, standard_factor
  INTO v_base_dimension, v_base_is_standard, v_base_std_factor
  FROM public.units
  WHERE id = p_base_unit_id AND tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'base_unit_not_found' USING ERRCODE = '23503';
  END IF;

  SELECT dimension, is_standard, standard_factor
  INTO v_unit_dimension, v_unit_is_standard, v_unit_std_factor
  FROM public.units
  WHERE id = p_unit_id AND tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unit_not_found' USING ERRCODE = '23503';
  END IF;

  -- Case 1: this unit is itself a standard unit. Only valid when the
  -- ingredient's base is a standard unit of the SAME dimension; the ratio
  -- is then a pure system constant (never user-entered).
  -- MODIFICATION: skip this if an anchor unit is explicitly specified,
  -- allowing standard units to be anchored manually when base is non-standard.
  IF v_unit_is_standard AND p_anchor_unit_id IS NULL THEN
    IF NOT v_base_is_standard OR v_base_dimension IS DISTINCT FROM v_unit_dimension THEN
      RAISE EXCEPTION 'standard_unit_dimension_mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN v_unit_std_factor / v_base_std_factor;
  END IF;

  -- Case 2: packaging unit (or manually-anchored standard unit). Walk the anchor chain until it reaches either
  -- the base unit or a standard unit, multiplying anchor_factor at each hop.
  -- Fail-closed on a missing anchor, a cycle, or a cross-dimension anchor
  -- once the chain reaches a standard unit.
  IF p_anchor_unit_id IS NULL OR p_anchor_factor IS NULL THEN
    RAISE EXCEPTION 'packaging_unit_requires_anchor' USING ERRCODE = '23514';
  END IF;

  v_current_unit := p_unit_id;
  v_current_anchor := p_anchor_unit_id;
  v_current_factor := p_anchor_factor;
  v_acc_factor := 1;

  LOOP
    IF v_current_unit = ANY (v_seen) THEN
      RAISE EXCEPTION 'unit_anchor_cycle' USING ERRCODE = '23514';
    END IF;
    v_seen := v_seen || v_current_unit;

    v_acc_factor := v_acc_factor * v_current_factor;

    IF v_current_anchor = p_base_unit_id THEN
      RETURN v_acc_factor;
    END IF;

    SELECT dimension, is_standard, standard_factor
    INTO v_hop_dimension, v_hop_is_standard, v_hop_std_factor
    FROM public.units
    WHERE id = v_current_anchor AND tenant_id = v_tenant;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'anchor_unit_not_found' USING ERRCODE = '23503';
    END IF;

    IF v_hop_is_standard THEN
      IF NOT v_base_is_standard OR v_base_dimension IS DISTINCT FROM v_hop_dimension THEN
        RAISE EXCEPTION 'standard_unit_dimension_mismatch' USING ERRCODE = '23514';
      END IF;
      RETURN v_acc_factor * (v_hop_std_factor / v_base_std_factor);
    END IF;

    -- Next hop: the anchor must itself be a packaging row on this
    -- ingredient (present in p_all_units), anchored further down the chain.
    v_current_unit := v_current_anchor;

    SELECT (e->>'anchor_unit_id')::bigint, (e->>'anchor_factor')::numeric
    INTO v_current_anchor, v_current_factor
    FROM jsonb_array_elements(p_all_units) e
    WHERE (e->>'unit_id')::bigint = v_current_unit;

    IF v_current_anchor IS NULL OR v_current_factor IS NULL THEN
      RAISE EXCEPTION 'unit_anchor_cycle' USING ERRCODE = '23514';
    END IF;
  END LOOP;
END;
$$;


--
-- Name: inv_to_base(bigint, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_to_base(p_ingredient_id bigint, p_unit_id bigint, p_qty numeric) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_factor numeric;
BEGIN
  IF p_qty IS NULL THEN
    RETURN NULL;
  END IF;
  IF p_unit_id IS NULL THEN
    RETURN p_qty;
  END IF;

  SELECT to_base_factor INTO v_factor
  FROM public.ingredient_units
  WHERE ingredient_id = p_ingredient_id
    AND unit_id = p_unit_id
    AND tenant_id = public.auth_tenant_id()
    AND is_active;

  IF v_factor IS NULL THEN
    RAISE EXCEPTION 'unit % is not valid for ingredient %', p_unit_id, p_ingredient_id
      USING ERRCODE = '23503';
  END IF;
  RETURN p_qty * v_factor;
END $$;


--
-- Name: inv_to_base_for_tenant(bigint, bigint, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_to_base_for_tenant(p_tenant_id bigint, p_ingredient_id bigint, p_unit_id bigint, p_qty numeric) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_factor numeric;
BEGIN
  IF p_qty IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_required' USING ERRCODE = '22023';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role'
     AND p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_unit_id IS NULL THEN
    RETURN p_qty;
  END IF;

  SELECT iu.to_base_factor
  INTO v_factor
  FROM public.ingredient_units iu
  WHERE iu.tenant_id = p_tenant_id
    AND iu.ingredient_id = p_ingredient_id
    AND iu.unit_id = p_unit_id
    AND iu.is_active = TRUE;

  IF v_factor IS NULL THEN
    RAISE EXCEPTION 'recipe_unit_conversion_missing:%', p_ingredient_id USING ERRCODE = '23503';
  END IF;

  RETURN p_qty * v_factor;
END;
$$;


--
-- Name: FUNCTION inv_to_base_for_tenant(p_tenant_id bigint, p_ingredient_id bigint, p_unit_id bigint, p_qty numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inv_to_base_for_tenant(p_tenant_id bigint, p_ingredient_id bigint, p_unit_id bigint, p_qty numeric) IS 'Tenant-explicit unit conversion for SECURITY DEFINER and service-role stock posting paths.';


--
-- Name: inventory_entry_unit_code(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_entry_unit_code(p_tenant_id bigint, p_ingredient_id bigint, p_entry_unit_id bigint DEFAULT NULL::bigint) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_code text;
BEGIN
  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_required' USING ERRCODE = '22023';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role'
     AND p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_ingredient_id IS NULL THEN
    RAISE EXCEPTION 'ingredient_required' USING ERRCODE = '22023';
  END IF;

  IF p_entry_unit_id IS NOT NULL THEN
    SELECT u.code
    INTO v_code
    FROM public.ingredient_units iu
    JOIN public.units u
      ON u.id = iu.unit_id
     AND u.tenant_id = iu.tenant_id
    WHERE iu.tenant_id = p_tenant_id
      AND iu.ingredient_id = p_ingredient_id
      AND iu.unit_id = p_entry_unit_id
      AND iu.is_active = TRUE
      AND u.is_active = TRUE;
  ELSE
    SELECT u.code
    INTO v_code
    FROM public.ingredient_units iu
    JOIN public.units u
      ON u.id = iu.unit_id
     AND u.tenant_id = iu.tenant_id
    WHERE iu.tenant_id = p_tenant_id
      AND iu.ingredient_id = p_ingredient_id
      AND iu.is_base = TRUE
      AND iu.is_active = TRUE
      AND u.is_active = TRUE
    ORDER BY iu.sort_order ASC, iu.id ASC
    LIMIT 1;
  END IF;

  IF NULLIF(btrim(v_code), '') IS NULL THEN
    RAISE EXCEPTION 'entry_unit_not_found:%', p_ingredient_id
      USING ERRCODE = '23503';
  END IF;

  RETURN btrim(v_code);
END;
$$;


--
-- Name: FUNCTION inventory_entry_unit_code(p_tenant_id bigint, p_ingredient_id bigint, p_entry_unit_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_entry_unit_code(p_tenant_id bigint, p_ingredient_id bigint, p_entry_unit_id bigint) IS 'Returns the persisted unit code for an ingredient entry_unit_id. NULL entry_unit_id resolves to the ingredient base unit.';


--
-- Name: inventory_shift_key(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_shift_key(p_branch_id bigint, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tz           TEXT;
  v_local        TIMESTAMP;
  v_hour         INT;
  v_segment      TEXT;
  v_anchor_date  DATE;
BEGIN
  SELECT timezone INTO v_tz
  FROM public.branches
  WHERE id = p_branch_id;

  IF v_tz IS NULL THEN
    v_tz := 'Asia/Ho_Chi_Minh';
  END IF;

  v_local := p_at AT TIME ZONE v_tz;
  v_hour  := EXTRACT(HOUR FROM v_local)::INT;

  IF v_hour < 4 THEN
    v_anchor_date := (v_local - INTERVAL '1 day')::DATE;
    v_segment     := 'evening';
  ELSIF v_hour < 12 THEN
    v_anchor_date := v_local::DATE;
    v_segment     := 'morning';
  ELSIF v_hour < 18 THEN
    v_anchor_date := v_local::DATE;
    v_segment     := 'afternoon';
  ELSE
    v_anchor_date := v_local::DATE;
    v_segment     := 'evening';
  END IF;

  RETURN to_char(v_anchor_date, 'YYYY-MM-DD') || '_' || v_segment;
END;
$$;


--
-- Name: FUNCTION inventory_shift_key(p_branch_id bigint, p_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_shift_key(p_branch_id bigint, p_at timestamp with time zone) IS 'Canonical shift key YYYY-MM-DD_{morning|afternoon|evening} per branch local time with 04:00 business-day cutoff.';


--
-- Name: is_feature_enabled(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_feature_enabled(p_branch_id bigint, p_flag_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT bff.enabled
    FROM public.branch_feature_flags bff
    JOIN public.branches b ON b.id = bff.branch_id
    WHERE bff.branch_id = p_branch_id
      AND bff.flag_key = p_flag_key
      AND (
        auth.role() = 'service_role'
        OR b.tenant_id = public.auth_tenant_id()
      )
  ), false);
$$;


--
-- Name: is_inventory_production_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_inventory_production_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT public.auth_is_owner(auth.uid())
    OR public.auth_role() = 'central_kitchen_lead';
$$;


--
-- Name: FUNCTION is_inventory_production_operator(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_inventory_production_operator() IS 'Canonical application-role guard for Inventory production surfaces.';


--
-- Name: link_sepay_transaction_to_payment(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_sepay_transaction_to_payment(p_event_id bigint, p_payment_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_user_id uuid := auth.uid();
  v_event public.webhook_events%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_raw_amount text;
  v_amount numeric;
BEGIN
  IF v_user_id IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_user_id)
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id
    AND tenant_id = v_tenant_id
    AND provider = 'sepay'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'webhook_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_event.payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'webhook_event_already_linked' USING ERRCODE = '23505';
  END IF;

  IF v_event.expense_id IS NOT NULL THEN
    RAISE EXCEPTION 'webhook_event_matches_expense' USING ERRCODE = '23514';
  END IF;

  IF NOT v_event.signature_valid THEN
    RAISE EXCEPTION 'webhook_event_signature_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_event.processing_status <> 'processed'
     OR (
       v_event.error_code IS NOT NULL
       AND v_event.error_code NOT IN (
          'missing_payment_code_needs_review',
          'order_not_found_needs_review',
          'ambiguous_payment_code_needs_review',
          'amount_mismatch_needs_review'
       )
     ) THEN
    RAISE EXCEPTION 'webhook_event_failed' USING ERRCODE = '23514';
  END IF;

  IF lower(COALESCE(v_event.payload ->> 'transferType', '')) <> 'in' THEN
    RAISE EXCEPTION 'webhook_event_not_in' USING ERRCODE = '23514';
  END IF;

  v_raw_amount := btrim(COALESCE(v_event.payload ->> 'transferAmount', ''));
  IF v_raw_amount !~ '^[0-9]+([.][0-9]+)?$' THEN
    RAISE EXCEPTION 'webhook_event_amount_invalid' USING ERRCODE = '22023';
  END IF;

  v_amount := v_raw_amount::numeric;
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'webhook_event_amount_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_payment
  FROM public.payments
  WHERE id = p_payment_id
    AND tenant_id = v_tenant_id
    AND method = 'vietqr'
    AND status = 'completed'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_payment.branch_id, 'finance:view') THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF v_payment.amount <> v_amount THEN
    RAISE EXCEPTION 'payment_amount_mismatch' USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.webhook_events other_event
    WHERE other_event.tenant_id = v_tenant_id
      AND other_event.payment_id = p_payment_id
      AND other_event.id <> p_event_id
      AND other_event.provider = 'sepay'
      AND other_event.signature_valid
      AND lower(COALESCE(other_event.payload ->> 'transferType', '')) = 'in'
      AND other_event.processing_status = 'processed'
      AND other_event.error_code IS NULL
  ) THEN
    RAISE EXCEPTION 'payment_already_has_bank_webhook' USING ERRCODE = '23505';
  END IF;

  UPDATE public.webhook_events
  SET order_id = v_payment.order_id,
      payment_id = p_payment_id,
      processing_status = 'processed',
      http_status = 200,
      error_code = NULL,
      processed_at = COALESCE(processed_at, now())
  WHERE id = p_event_id
    AND tenant_id = v_tenant_id;

  PERFORM public.log_audit(
    'link_sepay_transaction_to_payment',
    'webhook_event',
    p_event_id,
    jsonb_build_object(
      'order_id', v_event.order_id,
      'payment_id', v_event.payment_id,
      'processing_status', v_event.processing_status,
      'error_code', v_event.error_code
    ),
    jsonb_build_object(
      'order_id', v_payment.order_id,
      'payment_id', p_payment_id,
      'processing_status', 'processed',
      'error_code', NULL,
      'amount', v_amount
    )
  );

  RETURN jsonb_build_object(
    'event_id', p_event_id,
    'payment_id', p_payment_id,
    'order_id', v_payment.order_id,
    'amount', v_amount
  );
END;
$_$;


--
-- Name: list_branch_menu_daily_limits(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_branch_menu_daily_limits(p_branch_id bigint, p_limit_date date DEFAULT NULL::date) RETURNS TABLE(menu_item_id bigint, item_name text, category_id bigint, category_name text, base_price numeric, limit_id bigint, limit_date date, is_disabled boolean, sold_today integer, stock_capacity integer, manual_limit_quantity integer, pending_unfinalized_demand integer, active_hold_demand integer, available_to_sell integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_role      TEXT   := public.auth_role();
  v_branch    BIGINT := public.auth_branch_id();
  v_date      DATE   := COALESCE(
    p_limit_date,
    (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  );
  v_gate_eff  BOOLEAN;
BEGIN
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF v_role NOT IN ('owner', 'branch_manager') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'branch_manager'
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.branches b
   WHERE b.id = p_branch_id AND b.tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  v_gate_eff := public.is_feature_enabled(p_branch_id, 'pos_stock_outcome_posting');

  RETURN QUERY
  SELECT
    a.menu_item_id,
    a.item_name,
    a.category_id,
    a.category_name,
    a.base_price,
    a.limit_id,
    a.limit_date,
    a.is_disabled,
    a.sold_today,
    a.stock_capacity,
    a.manual_limit_quantity,
    a.pending_unfinalized_demand,
    a.active_hold_demand,
    a.available_to_sell
  FROM public.branch_menu_limit_availability(
    v_tenant_id,
    p_branch_id,
    v_date,
    v_gate_eff
  ) a
  ORDER BY a.category_name, a.item_name;
END;
$$;


--
-- Name: FUNCTION list_branch_menu_daily_limits(p_branch_id bigint, p_limit_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_branch_menu_daily_limits(p_branch_id bigint, p_limit_date date) IS 'Manager Giới hạn bán page. gate_eff = pos_stock_outcome_posting alone (D065 §1), same source as get_branch_menu_daily_limits_for_pos.';


--
-- Name: list_branch_revenue_target_progress(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_branch_revenue_target_progress(p_year_month date) RETURNS TABLE(branch_id bigint, branch_name text, year_month date, net_revenue numeric, target_amount numeric, progress_pct numeric, gap_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_month date;
  v_today date;
  v_end date;
  v_start_utc timestamptz;
  v_end_utc timestamptz;
  v_has_tenant_scope boolean;
  v_branch_ids bigint[];
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT scope.has_tenant_scope, scope.branch_ids
  INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') scope;

  IF NOT (
    v_has_tenant_scope
    OR COALESCE(cardinality(v_branch_ids), 0) > 0
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF p_year_month IS NULL THEN
    RAISE EXCEPTION 'invalid_year_month' USING ERRCODE = '22023';
  END IF;

  v_today := (timezone('Asia/Ho_Chi_Minh', now()))::date;
  v_month := date_trunc('month', p_year_month::timestamp)::date;

  IF date_trunc('month', v_today::timestamp)::date = v_month THEN
    v_end := v_today;
  ELSE
    v_end := (v_month + interval '1 month' - interval '1 day')::date;
  END IF;

  v_start_utc := v_month::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_end_utc := (v_end + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  WITH branches AS (
    SELECT b.id, b.name
    FROM public.branches b
    WHERE b.tenant_id = v_tenant
      AND b.branch_kind = 'branch'
      AND b.is_active IS TRUE
      AND (
        v_has_tenant_scope
        OR b.id = ANY(COALESCE(v_branch_ids, ARRAY[]::bigint[]))
      )
  ),
  paid AS (
    SELECT
      payment.branch_id,
      payment.order_id,
      payment.id AS payment_id,
      payment.paid_at,
      orders.subtotal,
      orders.discount_amount
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_tenant
      AND payment.status = 'completed'
      AND payment.paid_at >= v_start_utc
      AND payment.paid_at < v_end_utc
      AND payment.branch_id IN (SELECT branches.id FROM branches)
  ),
  order_facts AS (
    SELECT DISTINCT ON (paid.branch_id, paid.order_id)
      paid.branch_id,
      paid.subtotal,
      paid.discount_amount
    FROM paid
    ORDER BY
      paid.branch_id,
      paid.order_id,
      paid.paid_at,
      paid.payment_id
  ),
  net AS (
    SELECT
      order_facts.branch_id,
      COALESCE(
        sum(order_facts.subtotal - order_facts.discount_amount),
        0
      )::numeric AS net_revenue
    FROM order_facts
    GROUP BY order_facts.branch_id
  )
  SELECT
    branches.id AS branch_id,
    branches.name AS branch_name,
    v_month AS year_month,
    COALESCE(net.net_revenue, 0)::numeric AS net_revenue,
    targets.target_amount,
    CASE
      WHEN targets.target_amount IS NULL OR targets.target_amount <= 0
        THEN NULL::numeric
      ELSE round((COALESCE(net.net_revenue, 0) / targets.target_amount) * 100, 1)
    END AS progress_pct,
    CASE
      WHEN targets.target_amount IS NULL THEN NULL::numeric
      ELSE greatest(targets.target_amount - COALESCE(net.net_revenue, 0), 0)
    END AS gap_amount
  FROM branches
  LEFT JOIN net ON net.branch_id = branches.id
  LEFT JOIN public.branch_revenue_targets targets
    ON targets.branch_id = branches.id
   AND targets.year_month = v_month
   AND targets.tenant_id = v_tenant
  ORDER BY
    progress_pct DESC NULLS LAST,
    net_revenue DESC,
    branches.name;
END;
$$;


--
-- Name: FUNCTION list_branch_revenue_target_progress(p_year_month date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_branch_revenue_target_progress(p_year_month date) IS 'Finance-scope progress of monthly Doanh thu thuần vs target for all visible branches.';


--
-- Name: list_branch_revenue_target_reward_tiers(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_branch_revenue_target_reward_tiers(p_year_month date) RETURNS TABLE(branch_id bigint, reward_tiers jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_month date;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT (public.auth_is_owner(v_uid) OR public.has_position('accountant'))
     OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_year_month IS NULL THEN
    RAISE EXCEPTION 'invalid_year_month' USING ERRCODE = '22023';
  END IF;

  v_month := date_trunc('month', p_year_month::timestamp)::date;

  RETURN QUERY
  SELECT targets.branch_id, targets.reward_tiers
  FROM public.branch_revenue_targets targets
  WHERE targets.tenant_id = v_tenant
    AND targets.year_month = v_month;
END;
$$;


--
-- Name: FUNCTION list_branch_revenue_target_reward_tiers(p_year_month date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_branch_revenue_target_reward_tiers(p_year_month date) IS 'Owner-only reward tier configuration for branch monthly revenue targets.';


--
-- Name: list_branch_revenue_targets(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_branch_revenue_targets(p_year_month date) RETURNS TABLE(branch_id bigint, branch_name text, year_month date, target_amount numeric, prior_month_net_revenue numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_month date;
  v_prior_start date;
  v_prior_end date;
  v_prior_start_utc timestamptz;
  v_prior_end_utc timestamptz;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT (public.auth_is_owner(v_uid) OR public.has_position('accountant'))
     OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_year_month IS NULL THEN
    RAISE EXCEPTION 'invalid_year_month' USING ERRCODE = '22023';
  END IF;

  v_month := date_trunc('month', p_year_month::timestamp)::date;
  v_prior_start := (v_month - interval '1 month')::date;
  v_prior_end := (v_month - interval '1 day')::date;
  v_prior_start_utc := v_prior_start::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_prior_end_utc := (v_prior_end + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh';

  RETURN QUERY
  WITH branches AS (
    SELECT b.id, b.name
    FROM public.branches b
    WHERE b.tenant_id = v_tenant
      AND b.branch_kind = 'branch'
      AND b.is_active IS TRUE
  ),
  prior_paid AS (
    SELECT
      payment.branch_id,
      payment.order_id,
      payment.id AS payment_id,
      payment.paid_at,
      orders.subtotal,
      orders.discount_amount
    FROM public.payments payment
    JOIN public.orders orders
      ON orders.id = payment.order_id
     AND orders.tenant_id = payment.tenant_id
     AND orders.branch_id = payment.branch_id
    WHERE payment.tenant_id = v_tenant
      AND payment.status = 'completed'
      AND payment.paid_at >= v_prior_start_utc
      AND payment.paid_at < v_prior_end_utc
      AND payment.branch_id IN (SELECT branches.id FROM branches)
  ),
  prior_facts AS (
    SELECT DISTINCT ON (prior_paid.branch_id, prior_paid.order_id)
      prior_paid.branch_id,
      prior_paid.subtotal,
      prior_paid.discount_amount
    FROM prior_paid
    ORDER BY
      prior_paid.branch_id,
      prior_paid.order_id,
      prior_paid.paid_at,
      prior_paid.payment_id
  ),
  prior_net AS (
    SELECT
      prior_facts.branch_id,
      COALESCE(
        sum(prior_facts.subtotal - prior_facts.discount_amount),
        0
      )::numeric AS net_revenue
    FROM prior_facts
    GROUP BY prior_facts.branch_id
  )
  SELECT
    branches.id AS branch_id,
    branches.name AS branch_name,
    v_month AS year_month,
    targets.target_amount,
    COALESCE(prior_net.net_revenue, 0)::numeric AS prior_month_net_revenue
  FROM branches
  LEFT JOIN public.branch_revenue_targets targets
    ON targets.branch_id = branches.id
   AND targets.year_month = v_month
   AND targets.tenant_id = v_tenant
  LEFT JOIN prior_net
    ON prior_net.branch_id = branches.id
  ORDER BY branches.name;
END;
$$;


--
-- Name: FUNCTION list_branch_revenue_targets(p_year_month date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_branch_revenue_targets(p_year_month date) IS 'Owner-only list of active branches with monthly Doanh thu thuần target and prior-month net revenue.';


--
-- Name: list_goods_receipt_notes(text, text, bigint, text, date, date, bigint, bigint, bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_goods_receipt_notes(p_query text DEFAULT NULL::text, p_status text DEFAULT 'draft'::text, p_supplier_id bigint DEFAULT NULL::bigint, p_date_field text DEFAULT 'expected'::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_po_id bigint DEFAULT NULL::bigint, p_purchase_request_id bigint DEFAULT NULL::bigint, p_branch_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_can_money boolean;
  v_rows jsonb;
  v_total bigint;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_status NOT IN ('draft', 'confirmed', 'cancelled', 'all')
     OR p_date_field NOT IN ('expected', 'received')
     OR p_limit NOT BETWEEN 1 AND 200
     OR p_offset < 0 THEN
    RAISE EXCEPTION 'grn_list_filter_invalid' USING ERRCODE = '22023';
  END IF;

  v_can_money := public.can_read_inventory_monetary(
    'procurement:price_list_read'
  );

  WITH filtered AS (
    SELECT
      grn.*,
      purchase_order.po_number,
      purchase_order.display_id,
      purchase_order.supplier_id AS list_supplier_id,
      purchase_order.purchase_request_id,
      request.request_number,
      supplier.name AS supplier_name,
      branch.name AS receiving_site_name,
      profile.full_name AS handled_by,
      metrics.line_count,
      metrics.completed_line_count,
      metrics.shortage_line_count,
      metrics.excess_line_count,
      metrics.rejected_line_count,
      metrics.receipt_value,
      invoice.id AS invoice_id,
      invoice.matching_status AS invoice_status
    FROM public.goods_received_notes grn
    JOIN public.purchase_orders purchase_order
      ON purchase_order.id = grn.po_id
     AND purchase_order.tenant_id = grn.tenant_id
    LEFT JOIN public.purchase_requests request
      ON request.id = purchase_order.purchase_request_id
     AND request.tenant_id = purchase_order.tenant_id
    JOIN public.suppliers supplier
      ON supplier.id = purchase_order.supplier_id
     AND supplier.tenant_id = purchase_order.tenant_id
    JOIN public.branches branch
      ON branch.id = grn.branch_id
     AND branch.tenant_id = grn.tenant_id
    LEFT JOIN public.profiles profile
      ON profile.id = COALESCE(grn.received_by, grn.created_by)
     AND profile.tenant_id = grn.tenant_id
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS line_count,
        count(*) FILTER (
          WHERE item.received_quantity - item.rejected_quantity > 0
        )::integer AS completed_line_count,
        count(*) FILTER (
          WHERE (
            grn.status = 'confirmed'
            AND item.po_applied_quantity < remaining.quantity
          ) OR (
            grn.status = 'draft'
            AND item.received_quantity - item.rejected_quantity > 0
            AND least(
              item.received_quantity - item.rejected_quantity,
              remaining.quantity
            ) < remaining.quantity
          )
        )::integer AS shortage_line_count,
        count(*) FILTER (
          WHERE CASE
            WHEN grn.status = 'confirmed'
              THEN item.received_quantity - item.rejected_quantity
                > item.po_applied_quantity
            ELSE item.received_quantity - item.rejected_quantity
              > remaining.quantity
          END
        )::integer AS excess_line_count,
        count(*) FILTER (
          WHERE item.rejected_quantity > 0
        )::integer AS rejected_line_count,
        COALESCE(sum(item.total_cost), 0)::numeric(15,2)
          AS receipt_value
      FROM public.grn_items item
      LEFT JOIN public.purchase_order_items po_item
        ON po_item.id = item.purchase_order_item_id
       AND po_item.tenant_id = item.tenant_id
      LEFT JOIN LATERAL (
        SELECT greatest(
          COALESCE(po_item.quantity, 0) - COALESCE(sum(
            previous_item.po_applied_quantity
          ), 0),
          0
        ) AS quantity
        FROM public.grn_items previous_item
        JOIN public.goods_received_notes previous_grn
          ON previous_grn.id = previous_item.grn_id
         AND previous_grn.tenant_id = previous_item.tenant_id
        WHERE previous_item.tenant_id = item.tenant_id
          AND previous_item.purchase_order_item_id =
            item.purchase_order_item_id
          AND previous_grn.status = 'confirmed'
          AND previous_grn.id <> grn.id
      ) remaining ON TRUE
      WHERE item.grn_id = grn.id
        AND item.tenant_id = grn.tenant_id
    ) metrics ON TRUE
    LEFT JOIN LATERAL (
      SELECT matched_invoice.id, matched_invoice.matching_status
      FROM public.supplier_invoices matched_invoice
      WHERE matched_invoice.tenant_id = grn.tenant_id
        AND (
          matched_invoice.grn_id = grn.id
          OR EXISTS (
            SELECT 1
            FROM public.supplier_invoice_receipt_allocations allocation
            WHERE allocation.tenant_id = grn.tenant_id
              AND allocation.supplier_invoice_id = matched_invoice.id
              AND allocation.grn_id = grn.id
          )
        )
      ORDER BY matched_invoice.id DESC
      LIMIT 1
    ) invoice ON TRUE
    WHERE grn.tenant_id = v_tenant
      AND public.has_permission(grn.branch_id, 'procurement:read')
      AND (p_branch_id IS NULL OR grn.branch_id = p_branch_id)
      AND (p_status = 'all' OR grn.status = p_status)
      AND (p_supplier_id IS NULL OR purchase_order.supplier_id = p_supplier_id)
      AND (p_po_id IS NULL OR purchase_order.id = p_po_id)
      AND (
        p_purchase_request_id IS NULL
        OR purchase_order.purchase_request_id = p_purchase_request_id
      )
      AND (
        p_date_from IS NULL
        OR CASE p_date_field
          WHEN 'expected' THEN grn.expected_receive_date >= p_date_from
          ELSE grn.received_date::date >= p_date_from
        END
      )
      AND (
        p_date_to IS NULL
        OR CASE p_date_field
          WHEN 'expected' THEN grn.expected_receive_date <= p_date_to
          ELSE grn.received_date::date <= p_date_to
        END
      )
      AND (
        NULLIF(btrim(p_query), '') IS NULL
        OR grn.grn_number ILIKE '%' || btrim(p_query) || '%'
        OR purchase_order.po_number ILIKE '%' || btrim(p_query) || '%'
        OR purchase_order.display_id ILIKE '%' || btrim(p_query) || '%'
        OR request.request_number ILIKE '%' || btrim(p_query) || '%'
        OR supplier.name ILIKE '%' || btrim(p_query) || '%'
      )
  ),
  counted AS (
    SELECT count(*)::bigint AS total
    FROM filtered
  ),
  paged AS (
    SELECT *
    FROM filtered
    ORDER BY
      CASE WHEN status = 'draft' THEN 0 ELSE 1 END,
      expected_receive_date ASC NULLS LAST,
      updated_at DESC,
      id DESC
    LIMIT p_limit
    OFFSET p_offset
  )
  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', paged.id,
          'code', paged.grn_number,
          'status', paged.status,
          'supplierId', paged.list_supplier_id,
          'supplierName', paged.supplier_name,
          'poId', paged.po_id,
          'poCode', COALESCE(paged.display_id, paged.po_number),
          'purchaseRequestId', paged.purchase_request_id,
          'purchaseRequestCode', paged.request_number,
          'receivingSiteId', paged.branch_id,
          'receivingSiteName', paged.receiving_site_name,
          'expectedReceiveDate', paged.expected_receive_date,
          'receivedDate', paged.received_date,
          'lineCount', paged.line_count,
          'completedLineCount', paged.completed_line_count,
          'shortageLineCount', paged.shortage_line_count,
          'excessLineCount', paged.excess_line_count,
          'rejectedLineCount', paged.rejected_line_count,
          'updatedAt', paged.updated_at,
          'handledBy', paged.handled_by,
          'monetary', CASE
            WHEN v_can_money THEN jsonb_build_object(
              'receiptValue', paged.receipt_value,
              'invoiceId', paged.invoice_id,
              'invoiceStatus', paged.invoice_status
            )
            ELSE 'null'::jsonb
          END
        )
        ORDER BY
          CASE WHEN paged.status = 'draft' THEN 0 ELSE 1 END,
          paged.expected_receive_date ASC NULLS LAST,
          paged.updated_at DESC,
          paged.id DESC
      ),
      '[]'::jsonb
    ),
    COALESCE((SELECT total FROM counted), 0)
  INTO v_rows, v_total
  FROM paged;

  RETURN jsonb_build_object('rows', v_rows, 'total', v_total);
END;
$$;


--
-- Name: list_notifications(integer, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_notifications(p_limit integer DEFAULT 20, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_unread_only boolean DEFAULT false) RETURNS TABLE(id bigint, tenant_id bigint, target_branch_id bigint, target_roles text[], kind text, severity text, title text, body text, entity_type text, entity_id bigint, action_url text, meta jsonb, created_at timestamp with time zone, expires_at timestamp with time zone, read_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    n.id, n.tenant_id, n.target_branch_id, n.target_roles,
    n.kind, n.severity, n.title, n.body,
    n.entity_type, n.entity_id, n.action_url, n.meta,
    n.created_at, n.expires_at,
    r.read_at
  FROM public.notifications n
  LEFT JOIN public.notification_reads r
    ON r.notification_id = n.id
   AND r.user_id = (SELECT auth.uid())
  WHERE (p_before IS NULL OR n.created_at < p_before)
    AND (NOT p_unread_only OR r.read_at IS NULL)
  ORDER BY n.created_at DESC, n.id DESC
  LIMIT least(greatest(p_limit, 1), 50) + 1;
$$;


--
-- Name: log_audit(text, text, bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_audit(p_action text, p_entity_type text, p_entity_id bigint DEFAULT NULL::bigint, p_old jsonb DEFAULT NULL::jsonb, p_new jsonb DEFAULT NULL::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id   UUID   := auth.uid();
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_id        BIGINT;
BEGIN
  -- Reject anonymous / missing-claim callers — append-only audit must
  -- always have a real actor.
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'audit.log_audit: anonymous caller'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'audit.log_audit: missing tenant_id claim'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_action IS NULL OR length(p_action) = 0 THEN
    RAISE EXCEPTION 'audit.log_audit: action required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_entity_type IS NULL OR length(p_entity_type) = 0 THEN
    RAISE EXCEPTION 'audit.log_audit: entity_type required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  INSERT INTO public.audit_logs (
    tenant_id,
    user_id,
    action,
    entity_type,
    entity_id,
    old_data,
    new_data
  ) VALUES (
    v_tenant_id,
    v_user_id,
    p_action,
    p_entity_type,
    p_entity_id,
    p_old,
    p_new
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION log_audit(p_action text, p_entity_type text, p_entity_id bigint, p_old jsonb, p_new jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.log_audit(p_action text, p_entity_type text, p_entity_id bigint, p_old jsonb, p_new jsonb) IS 'Append a row to audit_logs. tenant_id and user_id are forced server-side from auth claims — callers cannot spoof them. Only path to write audit_logs (direct INSERT revoked).';


--
-- Name: mark_all_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_notifications_read() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_count BIGINT;
BEGIN
  WITH ctx AS MATERIALIZED (
    SELECT
      auth.uid() AS user_id,
      public.auth_tenant_id() AS tenant_id,
      public.auth_branch_id() AS branch_id,
      public.auth_role() AS user_role
  ),
  visible_unread AS (
    SELECT n.id, ctx.user_id
    FROM ctx
    JOIN public.notifications n
      ON n.tenant_id = ctx.tenant_id
    WHERE ctx.user_id IS NOT NULL
      AND ctx.tenant_id IS NOT NULL
      AND ctx.user_role IS NOT NULL
      AND n.target_roles @> ARRAY[ctx.user_role]::text[]
      AND (
        n.target_branch_id IS NULL
        OR n.target_branch_id = ctx.branch_id
        OR ctx.user_role IN ('owner')
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.notification_reads r
        WHERE r.notification_id = n.id
          AND r.user_id = ctx.user_id
      )
      AND (n.expires_at IS NULL OR n.expires_at > now())
  )
  INSERT INTO public.notification_reads (notification_id, user_id)
  SELECT id, user_id
  FROM visible_unread
  ON CONFLICT (notification_id, user_id) DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: mark_kds_item_out_of_stock(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_kds_item_out_of_stock(p_ticket_id bigint, p_disable_for_day boolean DEFAULT true, p_reason text DEFAULT 'Hết món'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID := auth.uid();
  v_reason          TEXT := COALESCE(NULLIF(trim(p_reason), ''), 'Hết món');
  v_row             RECORD;
  v_subtotal        NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_limit           RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('kds:mark_ready') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF length(v_reason) < 2 THEN
    RAISE EXCEPTION 'reason too short' USING ERRCODE = '22023';
  END IF;

  SELECT
    kt.id AS ticket_id,
    kt.tenant_id,
    kt.branch_id,
    kt.status AS ticket_status,
    kt.order_id,
    kt.order_item_id,
    oi.menu_item_id,
    oi.item_name,
    oi.status AS item_status,
    o.order_number,
    o.status AS order_status,
    o.payment_status,
    o.service_charge,
    o.discount_type,
    o.discount_value
  INTO v_row
  FROM public.kds_tickets kt
  JOIN public.order_items oi
    ON oi.id = kt.order_item_id
   AND oi.tenant_id = kt.tenant_id
  JOIN public.orders o
    ON o.id = kt.order_id
   AND o.tenant_id = kt.tenant_id
  WHERE kt.id = p_ticket_id
    AND kt.tenant_id = public.auth_tenant_id()
    AND (public.auth_role() = 'owner' OR kt.branch_id = public.auth_branch_id())
  FOR UPDATE OF kt, oi, o;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ticket_not_found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_row.order_id);

  IF v_row.order_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order_terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_row.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order_already_paid' USING ERRCODE = '22023';
  END IF;

  IF v_row.ticket_status NOT IN ('pending', 'preparing')
     OR v_row.item_status NOT IN ('pending', 'preparing') THEN
    RAISE EXCEPTION 'item_not_out_of_stockable' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = 'kds_out_of_stock: ' || v_reason,
      updated_at = now()
  WHERE id = v_row.order_item_id
    AND tenant_id = v_row.tenant_id;

  UPDATE public.kds_tickets
  SET status = 'cancelled',
      bumped_at = now(),
      bumped_by = v_uid,
      updated_at = now()
  WHERE id = v_row.ticket_id
    AND tenant_id = v_row.tenant_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal
  FROM public.order_items
  WHERE order_id = v_row.order_id
    AND tenant_id = v_row.tenant_id
    AND status <> 'cancelled';

  v_discount_amount := public.compute_discount_amount(
    v_row.discount_type,
    v_row.discount_value,
    v_subtotal
  );

  UPDATE public.orders o
  SET
    subtotal        = v_subtotal,
    discount_type   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_type END,
    discount_value  = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_value END,
    discount_note   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_note END,
    discount_amount = v_discount_amount,
    total_amount    = v_subtotal + COALESCE(o.service_charge, 0) - v_discount_amount,
    updated_at      = now()
  WHERE o.id = v_row.order_id
    AND o.tenant_id = v_row.tenant_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_row.tenant_id,
    v_row.order_id,
    v_row.order_status,
    v_row.order_status,
    v_uid,
    'kds_out_of_stock_item ' || v_row.order_item_id::TEXT || ': ' || v_reason
  );

  IF p_disable_for_day THEN
    INSERT INTO public.branch_menu_item_daily_limits (
      tenant_id,
      branch_id,
      menu_item_id,
      limit_date,
      limit_quantity,
      is_disabled,
      sold_today
    )
    VALUES (
      v_row.tenant_id,
      v_row.branch_id,
      v_row.menu_item_id,
      (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
      NULL,
      TRUE,
      0
    )
    ON CONFLICT (branch_id, menu_item_id, limit_date)
    DO UPDATE SET
      is_disabled = TRUE,
      updated_at = now()
    RETURNING limit_quantity, is_disabled, sold_today
    INTO v_limit;
  ELSE
    SELECT limit_quantity, is_disabled, sold_today
    INTO v_limit
    FROM public.branch_menu_item_daily_limits
    WHERE branch_id = v_row.branch_id
      AND menu_item_id = v_row.menu_item_id
      AND limit_date = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;

    IF NOT FOUND THEN
      SELECT NULL::INT AS limit_quantity,
             FALSE AS is_disabled,
             0::INT AS sold_today
      INTO v_limit;
    END IF;
  END IF;

  INSERT INTO public.notifications (
    tenant_id,
    target_branch_id,
    target_roles,
    kind,
    severity,
    title,
    body,
    entity_type,
    entity_id,
    action_url,
    dedup_key,
    meta
  )
  VALUES (
    v_row.tenant_id,
    v_row.branch_id,
    ARRAY['cashier', 'branch_manager']::TEXT[],
    'pos.kds_out_of_stock',
    'warning',
    format('Bếp báo hết món #%s', v_row.order_number),
    format('%s cần đổi món hoặc bỏ khỏi đơn.', v_row.item_name),
    'order_item',
    v_row.order_item_id,
    format('/br/%s/pos?order=%s', v_row.branch_id, v_row.order_id),
    format('kds_out_of_stock:%s', v_row.ticket_id),
    jsonb_build_object(
      'order_id', v_row.order_id,
      'order_number', v_row.order_number,
      'order_item_id', v_row.order_item_id,
      'menu_item_id', v_row.menu_item_id,
      'item_name', v_row.item_name,
      'reason', v_reason,
      'disabled_for_day', p_disable_for_day
    )
  )
  ON CONFLICT (tenant_id, dedup_key) WHERE dedup_key IS NOT NULL
  DO UPDATE SET
    severity = EXCLUDED.severity,
    title = EXCLUDED.title,
    body = EXCLUDED.body,
    action_url = EXCLUDED.action_url,
    meta = EXCLUDED.meta,
    created_at = now(),
    expires_at = NULL;

  PERFORM public.check_order_ready(v_row.order_id);

  RETURN jsonb_build_object(
    'ticket_id', v_row.ticket_id,
    'order_id', v_row.order_id,
    'order_item_id', v_row.order_item_id,
    'menu_item_id', v_row.menu_item_id,
    'item_name', v_row.item_name,
    'disabled_for_day', p_disable_for_day,
    'limit_quantity', v_limit.limit_quantity,
    'is_disabled', COALESCE(v_limit.is_disabled, p_disable_for_day),
    'sold_today', COALESCE(v_limit.sold_today, 0)
  );
END;
$$;


--
-- Name: FUNCTION mark_kds_item_out_of_stock(p_ticket_id bigint, p_disable_for_day boolean, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mark_kds_item_out_of_stock(p_ticket_id bigint, p_disable_for_day boolean, p_reason text) IS 'KDS dispatch exception. Cancels one active kitchen ticket/order item as out-of-stock, optionally disables the menu item for the branch/day, and notifies POS.';


--
-- Name: mark_order_item_served(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_order_item_served(p_item_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_prof_tenant bigint;
  v_prof_branch bigint;
  v_prof_role text;
  v_order_id bigint;
  v_item record;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT oi.order_id
  INTO v_order_id
  FROM public.order_items oi
  WHERE oi.id = p_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_order_id);

  SELECT
    oi.id,
    oi.order_id,
    oi.tenant_id,
    oi.status AS item_status,
    o.branch_id,
    o.status AS order_status
  INTO v_item
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_item_id
  FOR UPDATE OF oi;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_item.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role <> 'owner' THEN
    IF v_prof_branch IS NULL THEN
      RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
    END IF;
    IF v_item.branch_id <> v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NOT public.has_permission(v_item.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'forbidden: missing pos:use' USING ERRCODE = '42501';
  END IF;

  IF v_item.order_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF v_item.item_status NOT IN ('pending', 'preparing', 'ready') THEN
    RAISE EXCEPTION 'invalid item transition to served' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'served',
      updated_at = now()
  WHERE id = p_item_id;

  UPDATE public.kds_tickets
  SET status = 'served',
      bumped_at = COALESCE(bumped_at, now()),
      bumped_by = COALESCE(bumped_by, v_uid),
      first_ready_at = COALESCE(first_ready_at, now()),
      updated_at = now()
  WHERE order_item_id = p_item_id
    AND tenant_id = v_item.tenant_id
    AND status <> 'cancelled';

  PERFORM public.post_pos_sale_consumption_if_ready(v_item.order_id, v_uid);

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_item.tenant_id, v_item.order_id, v_item.order_status, v_item.order_status,
    v_uid, 'mark_item_served ' || p_item_id::text
  );

  RETURN jsonb_build_object(
    'item_id', p_item_id,
    'order_id', v_item.order_id,
    'status', 'served'
  );
END;
$$;


--
-- Name: FUNCTION mark_order_item_served(p_item_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mark_order_item_served(p_item_id bigint) IS 'Marks one POS order item and its KDS ticket as served. Cashier and Branch Manager operation remains branch-scoped.';


--
-- Name: match_sepay_transaction_expenses(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_sepay_transaction_expenses(p_event_id bigint, p_expense_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_is_service boolean := COALESCE(auth.role() = 'service_role', false);
  v_tenant_id bigint := public.auth_tenant_id();
  v_user_id uuid := auth.uid();
  v_event public.webhook_events%ROWTYPE;
  v_expense_ids bigint[];
  v_current_expense_ids bigint[];
  v_first_expense_id bigint;
  v_transfer_amount numeric;
  v_expense_total numeric;
  v_current_has_historical_split boolean;
BEGIN
  IF NOT v_is_service THEN
    IF v_user_id IS NULL
      OR v_tenant_id IS NULL
      OR NOT public.auth_is_owner(v_user_id)
    THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT COALESCE(
    array_agg(DISTINCT expense_id ORDER BY expense_id),
    ARRAY[]::bigint[]
  )
  INTO v_expense_ids
  FROM unnest(COALESCE(p_expense_ids, ARRAY[]::bigint[])) AS selected(expense_id)
  WHERE selected.expense_id IS NOT NULL;

  IF v_is_service AND cardinality(v_expense_ids) <> 1 THEN
    RAISE EXCEPTION 'system_expense_match_requires_single_expense'
      USING ERRCODE = '23514';
  END IF;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id
    AND provider = 'sepay'
    AND (v_is_service OR tenant_id = v_tenant_id)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'webhook_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_is_service THEN
    v_tenant_id := v_event.tenant_id;
  END IF;

  IF v_event.signature_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'webhook_event_signature_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_event.processing_status = 'failed' THEN
    RAISE EXCEPTION 'webhook_event_failed' USING ERRCODE = '23514';
  END IF;

  IF v_event.payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'webhook_event_matches_payment' USING ERRCODE = '23514';
  END IF;

  IF lower(COALESCE(v_event.payload->>'transferType', '')) <> 'out' THEN
    RAISE EXCEPTION 'webhook_event_not_out' USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN COALESCE(v_event.payload->>'transferAmount', '')
      ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN abs((v_event.payload->>'transferAmount')::numeric)
    ELSE NULL
  END
  INTO v_transfer_amount;

  IF v_transfer_amount IS NULL OR v_transfer_amount <= 0 THEN
    RAISE EXCEPTION 'expense_amount_mismatch' USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(
    array_agg(match.expense_id ORDER BY match.expense_id),
    ARRAY[]::bigint[]
  )
  INTO v_current_expense_ids
  FROM public.bank_transaction_expense_matches match
  WHERE match.tenant_id = v_tenant_id
    AND match.webhook_event_id = p_event_id;

  PERFORM 1
  FROM public.expenses expense
  WHERE expense.tenant_id = v_tenant_id
    AND expense.id = ANY(v_current_expense_ids || v_expense_ids)
  ORDER BY expense.id
  FOR UPDATE;

  IF v_current_expense_ids <> v_expense_ids
    AND EXISTS (
      SELECT 1
      FROM public.expenses expense
      WHERE expense.tenant_id = v_tenant_id
        AND expense.id = ANY(v_current_expense_ids)
        AND expense.transfer_content IS NOT NULL
    )
  THEN
    RAISE EXCEPTION 'transfer_intent_match_immutable'
      USING ERRCODE = '23514';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches match
    WHERE match.tenant_id = v_tenant_id
      AND match.expense_id = ANY(v_current_expense_ids)
      AND match.webhook_event_id <> p_event_id
  )
  INTO v_current_has_historical_split;

  IF v_current_has_historical_split
    AND v_current_expense_ids = v_expense_ids
  THEN
    RETURN jsonb_build_object(
      'matched_count', cardinality(v_current_expense_ids),
      'expense_ids', to_jsonb(v_current_expense_ids),
      'matched_amount', v_transfer_amount
    );
  END IF;

  IF v_current_has_historical_split THEN
    RAISE EXCEPTION 'historical_split_match_immutable'
      USING ERRCODE = '23514';
  END IF;

  IF cardinality(v_expense_ids) > 0 THEN
    IF EXISTS (
      SELECT 1
      FROM unnest(v_expense_ids) AS selected(expense_id)
      LEFT JOIN public.expenses expense
        ON expense.id = selected.expense_id
       AND expense.tenant_id = v_tenant_id
       AND expense.payment_method IN ('transfer', 'unpaid')
       AND expense.category <> 'bank_deposit'
      WHERE expense.id IS NULL
    ) THEN
      RAISE EXCEPTION 'expense_not_found' USING ERRCODE = 'P0002';
    END IF;

    IF cardinality(v_expense_ids) > 1
      AND EXISTS (
        SELECT 1
        FROM public.expenses expense
        WHERE expense.tenant_id = v_tenant_id
          AND expense.id = ANY(v_expense_ids)
          AND expense.transfer_content IS NOT NULL
      )
    THEN
      RAISE EXCEPTION 'transfer_intent_requires_single_expense'
        USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.expenses expense
      WHERE expense.tenant_id = v_tenant_id
        AND expense.id = ANY(v_expense_ids)
        AND expense.transfer_content IS NOT NULL
        AND NOT private.sepay_payload_contains_transfer_content(
          v_event.payload,
          expense.transfer_content
        )
    ) THEN
      RAISE EXCEPTION 'expense_transfer_content_mismatch'
        USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches match
      WHERE match.tenant_id = v_tenant_id
        AND match.expense_id = ANY(v_expense_ids)
        AND match.webhook_event_id <> p_event_id
    ) THEN
      RAISE EXCEPTION 'expense_already_matched' USING ERRCODE = '23505';
    END IF;

    SELECT COALESCE(sum(expense.amount), 0)
    INTO v_expense_total
    FROM public.expenses expense
    WHERE expense.tenant_id = v_tenant_id
      AND expense.id = ANY(v_expense_ids);

    IF v_expense_total <> v_transfer_amount THEN
      RAISE EXCEPTION 'expense_amount_mismatch' USING ERRCODE = '23514';
    END IF;
  END IF;

  -- The evidence graph spans three tables, so its constraint triggers must
  -- observe the final graph rather than any intermediate statement.
  SET CONSTRAINTS
    public.trg_expenses_require_bank_deposit_evidence,
    public.trg_webhook_events_require_finance_evidence,
    public.trg_expense_matches_require_sepay_evidence,
    public.trg_expenses_require_transfer_content_evidence,
    public.trg_expense_matches_require_transfer_content_evidence,
    public.trg_webhook_events_require_transfer_content_evidence
  DEFERRED;

  DELETE FROM public.bank_transaction_expense_matches
  WHERE tenant_id = v_tenant_id
    AND webhook_event_id = p_event_id
    AND NOT (expense_id = ANY(v_expense_ids));

  INSERT INTO public.bank_transaction_expense_matches (
    tenant_id,
    webhook_event_id,
    expense_id,
    created_by
  )
  SELECT
    v_tenant_id,
    p_event_id,
    selected.expense_id,
    CASE WHEN v_is_service THEN NULL ELSE v_user_id END
  FROM unnest(v_expense_ids) AS selected(expense_id)
  ON CONFLICT DO NOTHING;

  IF cardinality(v_expense_ids) > 0 THEN
    UPDATE public.expenses
    SET
      payment_method = 'transfer',
      paid_at = COALESCE(paid_at, v_event.created_at, now())
    WHERE tenant_id = v_tenant_id
      AND id = ANY(v_expense_ids)
      AND payment_method = 'unpaid';
  END IF;

  v_first_expense_id := v_expense_ids[1];

  UPDATE public.webhook_events
  SET expense_id = v_first_expense_id
  WHERE id = p_event_id
    AND tenant_id = v_tenant_id;

  SET CONSTRAINTS
    public.trg_expenses_require_bank_deposit_evidence,
    public.trg_webhook_events_require_finance_evidence,
    public.trg_expense_matches_require_sepay_evidence,
    public.trg_expenses_require_transfer_content_evidence,
    public.trg_expense_matches_require_transfer_content_evidence,
    public.trg_webhook_events_require_transfer_content_evidence
  IMMEDIATE;

  RETURN jsonb_build_object(
    'matched_count', cardinality(v_expense_ids),
    'expense_ids', to_jsonb(v_expense_ids),
    'matched_amount', CASE
      WHEN cardinality(v_expense_ids) = 0 THEN 0
      ELSE v_transfer_amount
    END
  );
END;
$_$;


--
-- Name: match_sepay_transaction_refunds(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_sepay_transaction_refunds(p_event_id bigint, p_refund_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_event public.webhook_events%ROWTYPE;
  v_refund_ids bigint[];
  v_previous_refund_ids bigint[];
  v_transfer_amount numeric;
  v_refund_count integer;
  v_refund_total numeric;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(
    array_agg(DISTINCT refund_id ORDER BY refund_id),
    ARRAY[]::bigint[]
  )
  INTO v_refund_ids
  FROM unnest(COALESCE(p_refund_ids, ARRAY[]::bigint[])) selected(refund_id)
  WHERE selected.refund_id IS NOT NULL;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id
    AND tenant_id = v_tenant_id
    AND provider = 'sepay'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'webhook_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(array_agg(refund.id ORDER BY refund.id), ARRAY[]::bigint[])
  INTO v_previous_refund_ids
  FROM public.refunds refund
  WHERE refund.tenant_id = v_tenant_id
    AND refund.webhook_event_id = p_event_id;

  IF cardinality(v_refund_ids) = 0 THEN
    UPDATE public.refunds
    SET webhook_event_id = NULL,
        updated_at = now()
    WHERE tenant_id = v_tenant_id
      AND webhook_event_id = p_event_id;

    PERFORM public.log_audit(
      'refund.sepay_match',
      'webhook_event',
      p_event_id,
      jsonb_build_object('refund_ids', to_jsonb(v_previous_refund_ids)),
      jsonb_build_object('refund_ids', '[]'::jsonb, 'matched_amount', 0)
    );

    RETURN jsonb_build_object(
      'matched_count', 0,
      'refund_ids', '[]'::jsonb,
      'matched_amount', 0
    );
  END IF;

  IF v_event.signature_valid IS NOT TRUE
    OR v_event.processing_status = 'failed'
    OR v_event.order_id IS NOT NULL
    OR v_event.payment_id IS NOT NULL
    OR v_event.expense_id IS NOT NULL
    OR lower(COALESCE(v_event.payload->>'transferType', '')) <> 'out'
  THEN
    RAISE EXCEPTION 'webhook_event_not_refund' USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN COALESCE(v_event.payload->>'transferAmount', '')
      ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN abs((v_event.payload->>'transferAmount')::numeric)
    ELSE NULL
  END
  INTO v_transfer_amount;

  IF v_transfer_amount IS NULL OR v_transfer_amount <= 0 THEN
    RAISE EXCEPTION 'refund_amount_mismatch' USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches expense_match
    WHERE expense_match.tenant_id = v_tenant_id
      AND expense_match.webhook_event_id = p_event_id
  ) OR EXISTS (
    SELECT 1
    FROM public.supplier_payments supplier_payment
    WHERE supplier_payment.tenant_id = v_tenant_id
      AND supplier_payment.webhook_event_id = p_event_id
  ) THEN
    RAISE EXCEPTION 'webhook_event_already_linked' USING ERRCODE = '23514';
  END IF;

  PERFORM 1
  FROM public.refunds refund
  WHERE refund.tenant_id = v_tenant_id
    AND refund.id = ANY(v_refund_ids)
  ORDER BY refund.id
  FOR UPDATE;

  SELECT count(*), COALESCE(sum(refund.amount), 0)
  INTO v_refund_count, v_refund_total
  FROM public.refunds refund
  WHERE refund.tenant_id = v_tenant_id
    AND refund.id = ANY(v_refund_ids)
    AND refund.status = 'approved'
    AND refund.payout_method = 'bank_transfer'
    AND (
      refund.webhook_event_id IS NULL
      OR refund.webhook_event_id = p_event_id
    );

  IF v_refund_count <> cardinality(v_refund_ids) THEN
    RAISE EXCEPTION 'refund_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_refund_total <> v_transfer_amount THEN
    RAISE EXCEPTION 'refund_amount_mismatch' USING ERRCODE = '23514';
  END IF;

  UPDATE public.refunds
  SET webhook_event_id = NULL,
      updated_at = now()
  WHERE tenant_id = v_tenant_id
    AND webhook_event_id = p_event_id
    AND NOT (id = ANY(v_refund_ids));

  UPDATE public.refunds
  SET webhook_event_id = p_event_id,
      updated_at = now()
  WHERE tenant_id = v_tenant_id
    AND id = ANY(v_refund_ids);

  PERFORM public.log_audit(
    'refund.sepay_match',
    'webhook_event',
    p_event_id,
    jsonb_build_object('refund_ids', to_jsonb(v_previous_refund_ids)),
    jsonb_build_object(
      'refund_ids', to_jsonb(v_refund_ids),
      'matched_amount', v_transfer_amount
    )
  );

  RETURN jsonb_build_object(
    'matched_count', cardinality(v_refund_ids),
    'refund_ids', to_jsonb(v_refund_ids),
    'matched_amount', v_transfer_amount
  );
END;
$_$;


--
-- Name: match_sepay_transaction_supplier_payments(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_sepay_transaction_supplier_payments(p_event_id bigint, p_supplier_payment_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_user_id uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_event public.webhook_events%ROWTYPE;
  v_supplier_payment_ids bigint[];
  v_transfer_amount numeric;
  v_payment_count integer;
  v_payment_total numeric;
BEGIN
  IF v_user_id IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_user_id)
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(
    array_agg(DISTINCT supplier_payment_id ORDER BY supplier_payment_id),
    ARRAY[]::bigint[]
  )
  INTO v_supplier_payment_ids
  FROM unnest(
    COALESCE(p_supplier_payment_ids, ARRAY[]::bigint[])
  ) AS selected(supplier_payment_id)
  WHERE selected.supplier_payment_id IS NOT NULL;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id
    AND tenant_id = v_tenant_id
    AND provider = 'sepay'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'webhook_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_event.signature_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'webhook_event_signature_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_event.processing_status = 'failed' THEN
    RAISE EXCEPTION 'webhook_event_failed' USING ERRCODE = '23514';
  END IF;

  IF v_event.payment_id IS NOT NULL
    OR lower(COALESCE(v_event.payload->>'transferType', '')) <> 'out'
  THEN
    RAISE EXCEPTION 'webhook_event_not_supplier_payment'
      USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN COALESCE(v_event.payload->>'transferAmount', '')
      ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN abs((v_event.payload->>'transferAmount')::numeric)
    ELSE NULL
  END
  INTO v_transfer_amount;

  IF v_transfer_amount IS NULL OR v_transfer_amount <= 0 THEN
    RAISE EXCEPTION 'supplier_payment_amount_mismatch'
      USING ERRCODE = '23514';
  END IF;

  IF cardinality(v_supplier_payment_ids) = 0 THEN
    UPDATE public.supplier_payments
    SET webhook_event_id = NULL,
        updated_at = now()
    WHERE tenant_id = v_tenant_id
      AND webhook_event_id = p_event_id;

    RETURN jsonb_build_object(
      'matched_count', 0,
      'supplier_payment_ids', '[]'::jsonb,
      'matched_amount', 0
    );
  END IF;

  IF v_event.expense_id IS NOT NULL
    OR EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches expense_match
      WHERE expense_match.tenant_id = v_tenant_id
        AND expense_match.webhook_event_id = p_event_id
    )
  THEN
    RAISE EXCEPTION 'webhook_event_already_linked'
      USING ERRCODE = '23514';
  END IF;

  PERFORM 1
  FROM public.supplier_payments payment
  WHERE payment.tenant_id = v_tenant_id
    AND payment.id = ANY(v_supplier_payment_ids)
  ORDER BY payment.id
  FOR UPDATE;

  SELECT count(*), COALESCE(sum(payment.amount), 0)
  INTO v_payment_count, v_payment_total
  FROM public.supplier_payments payment
  WHERE payment.tenant_id = v_tenant_id
    AND payment.id = ANY(v_supplier_payment_ids)
    AND payment.payment_method = 'bank_transfer'
    AND (
      payment.webhook_event_id IS NULL
      OR payment.webhook_event_id = p_event_id
    );

  IF v_payment_count <> cardinality(v_supplier_payment_ids) THEN
    RAISE EXCEPTION 'supplier_payment_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_payment_total <> v_transfer_amount THEN
    RAISE EXCEPTION 'supplier_payment_amount_mismatch'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.supplier_payments
  SET webhook_event_id = NULL,
      updated_at = now()
  WHERE tenant_id = v_tenant_id
    AND webhook_event_id = p_event_id
    AND NOT (id = ANY(v_supplier_payment_ids));

  UPDATE public.supplier_payments
  SET webhook_event_id = p_event_id,
      updated_at = now()
  WHERE tenant_id = v_tenant_id
    AND id = ANY(v_supplier_payment_ids);

  RETURN jsonb_build_object(
    'matched_count', cardinality(v_supplier_payment_ids),
    'supplier_payment_ids', to_jsonb(v_supplier_payment_ids),
    'matched_amount', v_transfer_amount
  );
END;
$_$;


--
-- Name: match_sepay_transfer_intent_event(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_sepay_transfer_intent_event(p_event_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_event public.webhook_events%ROWTYPE;
  v_locked_expense public.expenses%ROWTYPE;
  v_transfer_amount numeric;
  v_candidate_ids bigint[];
  v_expense_id bigint;
  v_match_result jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT event.*
  INTO v_event
  FROM public.webhook_events event
  WHERE event.id = p_event_id
    AND event.provider = 'sepay'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'webhook_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_event.signature_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'webhook_event_signature_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_event.processing_status = 'failed' THEN
    RAISE EXCEPTION 'webhook_event_failed' USING ERRCODE = '23514';
  END IF;

  IF v_event.payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'webhook_event_matches_payment' USING ERRCODE = '23514';
  END IF;

  IF lower(COALESCE(v_event.payload->>'transferType', '')) <> 'out' THEN
    RAISE EXCEPTION 'webhook_event_not_out' USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN COALESCE(v_event.payload->>'transferAmount', '')
      ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN abs((v_event.payload->>'transferAmount')::numeric)
    ELSE NULL
  END
  INTO v_transfer_amount;

  IF v_transfer_amount IS NULL OR v_transfer_amount <= 0 THEN
    RAISE EXCEPTION 'expense_amount_mismatch' USING ERRCODE = '23514';
  END IF;

  WITH payload_tokens AS (
    SELECT DISTINCT token.value::bigint AS expense_id
    FROM unnest(ARRAY[
      COALESCE(v_event.payload->>'content', ''),
      COALESCE(v_event.payload->>'description', ''),
      COALESCE(v_event.payload->>'code', '')
    ]) AS candidate(raw_value)
    CROSS JOIN LATERAL regexp_split_to_table(
      btrim(regexp_replace(candidate.raw_value, '[^0-9]+', ' ', 'g')),
      ' +'
    ) AS token(value)
    WHERE token.value ~ '^[0-9]{1,18}$'
  )
  SELECT COALESCE(
    array_agg(expense.id ORDER BY expense.id),
    ARRAY[]::bigint[]
  )
  INTO v_candidate_ids
  FROM payload_tokens token
  JOIN public.expenses expense
    ON expense.id = token.expense_id
   AND expense.tenant_id = v_event.tenant_id
  WHERE expense.transfer_content IS NOT NULL
    AND expense.category <> 'bank_deposit'
    AND expense.payment_method IN ('unpaid', 'transfer')
    AND expense.amount = v_transfer_amount
    AND private.sepay_payload_contains_transfer_content(
      v_event.payload,
      expense.transfer_content
    );

  IF cardinality(v_candidate_ids) = 0 THEN
    RETURN jsonb_build_object('matched', false);
  END IF;

  IF cardinality(v_candidate_ids) <> 1 THEN
    RAISE EXCEPTION 'expense_transfer_intent_ambiguous'
      USING ERRCODE = '23505';
  END IF;

  v_expense_id := v_candidate_ids[1];

  SELECT expense.*
  INTO v_locked_expense
  FROM public.expenses expense
  WHERE expense.id = v_expense_id
    AND expense.tenant_id = v_event.tenant_id
    AND expense.transfer_content IS NOT NULL
    AND expense.category <> 'bank_deposit'
    AND expense.payment_method IN ('unpaid', 'transfer')
    AND expense.amount = v_transfer_amount
    AND private.sepay_payload_contains_transfer_content(
      v_event.payload,
      expense.transfer_content
    )
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('matched', false);
  END IF;

  v_match_result := public.match_sepay_transaction_expenses(
    p_event_id,
    ARRAY[v_expense_id]
  );

  UPDATE public.webhook_events
  SET processing_status = 'processed',
      http_status = 200,
      error_code = NULL,
      processed_at = COALESCE(processed_at, now())
  WHERE id = p_event_id
    AND tenant_id = v_event.tenant_id;

  RETURN v_match_result || jsonb_build_object(
    'matched', true,
    'expense_id', v_expense_id
  );
END;
$_$;


--
-- Name: materialize_employee_weekly_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.materialize_employee_weekly_schedules() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT private.materialize_employee_weekly_schedules();
$$;


--
-- Name: materialize_print_document(text, jsonb, bigint, integer, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.materialize_print_document(p_kind text, p_payload jsonb, p_template_id bigint, p_template_version integer, p_paper_width_mm integer, p_font_profile text, p_content jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_blocks JSONB;
  v_block JSONB;
  v_render_block JSONB;
  v_type TEXT;
  v_left TEXT;
  v_right TEXT;
  v_out JSONB := '[]'::jsonb;
BEGIN
  v_blocks := p_content->'blocks';
  IF v_blocks IS NULL
     OR jsonb_typeof(v_blocks) <> 'array'
     OR COALESCE(jsonb_array_length(v_blocks), 0) = 0 THEN
    v_blocks := public.print_template_default_content(p_kind)->'blocks';
  END IF;

  FOR v_block IN SELECT value FROM jsonb_array_elements(v_blocks)
  LOOP
    v_type := v_block->>'type';
    IF v_type IS NULL THEN
      CONTINUE;
    END IF;

    IF NOT public.print_template_block_visible(v_block, p_payload) THEN
      CONTINUE;
    END IF;

    v_render_block := v_block
      - 'when_field'
      - 'when_equals'
      - 'when_not_equals'
      - 'when_not_equals_field'
      - 'when_not_empty'
      - 'when_min';

    CASE v_type
      WHEN 'text' THEN
        v_out := v_out || jsonb_build_array(
          jsonb_set(
            v_render_block,
            '{text}',
            to_jsonb(public.print_template_interpolate(v_block->>'text', p_payload)),
            true
          )
        );
      WHEN 'row' THEN
        v_left := public.print_template_interpolate(v_block->>'left', p_payload);
        v_right := public.print_template_interpolate(v_block->>'right', p_payload);
        v_out := v_out || jsonb_build_array(
          jsonb_set(
            jsonb_set(v_render_block, '{left}', to_jsonb(v_left), true),
            '{right}',
            to_jsonb(v_right),
            true
          )
        );
      WHEN 'branchInfo' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'branch_name', COALESCE(p_payload->>'branch_name', ''),
            'branch_address', COALESCE(p_payload->>'branch_address', ''),
            'branch_phone', COALESCE(p_payload->>'branch_phone', ''),
            'branch_tax_code', COALESCE(p_payload->>'branch_tax_code', '')
          )
        );
      WHEN 'billMeta' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'order_number', COALESCE(p_payload->>'order_number', ''),
            'order_type', COALESCE(p_payload->>'order_type', ''),
            'table_number', p_payload->'table_number',
            'cashier_name', COALESCE(p_payload->>'cashier_name', ''),
            'created_at', COALESCE(p_payload->>'created_at', '')
          )
        );
      WHEN 'paymentMethod' THEN
        IF COALESCE(p_payload->>'payment_method', '') = '' THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('method', p_payload->>'payment_method')
        );
      WHEN 'itemsTable' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('items', COALESCE(p_payload->'items', '[]'::jsonb))
        );
      WHEN 'totals' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'subtotal', p_payload->'subtotal',
            'tax_amount', p_payload->'tax_amount',
            'service_charge', p_payload->'service_charge',
            'discount_amount', p_payload->'discount_amount',
            'total_amount', p_payload->'total_amount'
          )
        );
      WHEN 'cashChange' THEN
        IF NOT (p_payload ? 'cash_received' OR p_payload ? 'cash_change') THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'cash_received', p_payload->'cash_received',
            'cash_change', p_payload->'cash_change',
            'total_amount', p_payload->'total_amount'
          )
        );
      WHEN 'note' THEN
        IF COALESCE(NULLIF(trim(p_payload->>'note'), ''), '') = '' THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('text', p_payload->>'note')
        );
      WHEN 'paymentQr' THEN
        IF jsonb_typeof(p_payload->'payment_qr') <> 'object'
           OR COALESCE(p_payload#>>'{payment_qr,content}', '') = '' THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('qr', p_payload->'payment_qr')
        );
      WHEN 'kitchenItems' THEN
        v_out := v_out || public.print_template_kitchen_item_blocks(p_payload, false);
      WHEN 'cancelItems' THEN
        v_out := v_out || public.print_template_kitchen_item_blocks(p_payload, true);
      WHEN 'shiftCashReconciliation' THEN
        v_out := v_out || public.print_template_shift_cash_blocks(p_payload);
      WHEN 'paymentBreakdown' THEN
        v_out := v_out || public.print_template_payment_breakdown_blocks(p_payload);
      WHEN 'shiftOrderSummary' THEN
        v_out := v_out || public.print_template_shift_summary_blocks(p_payload);
      WHEN 'shiftItemBreakdown' THEN
        v_out := v_out || public.print_template_shift_item_breakdown_blocks(p_payload);
      WHEN 'shiftVarianceNotice' THEN
        v_out := v_out || public.print_template_shift_variance_notice_blocks(p_payload);
      WHEN 'shiftSignature' THEN
        v_out := v_out || public.print_template_shift_signature_blocks();
      WHEN 'varianceApproval' THEN
        v_out := v_out || public.print_template_variance_approval_blocks(p_payload);
      WHEN 'kitchenTicket' THEN
        v_out := v_out || (
          public.materialize_print_document(
            'kitchen_ticket',
            p_payload,
            p_template_id,
            p_template_version,
            p_paper_width_mm,
            p_font_profile,
            public.print_template_default_content('kitchen_ticket')
          )->'blocks'
        );
      WHEN 'cancelTicket' THEN
        v_out := v_out || (
          public.materialize_print_document(
            'cancel_ticket',
            p_payload,
            p_template_id,
            p_template_version,
            p_paper_width_mm,
            p_font_profile,
            public.print_template_default_content('cancel_ticket')
          )->'blocks'
        );
      WHEN 'shiftCloseReport' THEN
        v_out := v_out || (
          public.materialize_print_document(
            'shift_close_report',
            p_payload,
            p_template_id,
            p_template_version,
            p_paper_width_mm,
            p_font_profile,
            public.print_template_default_content('shift_close_report')
          )->'blocks'
        );
      ELSE
        v_out := v_out || jsonb_build_array(v_render_block);
    END CASE;
  END LOOP;

  IF jsonb_array_length(v_out) = 0 THEN
    v_out := jsonb_build_array(
      jsonb_build_object('type', 'text', 'text', COALESCE(p_payload->>'kind', p_kind))
    );
  END IF;

  RETURN jsonb_build_object(
    'schema_version', 1,
    'template_id', COALESCE(p_template_id, 0),
    'template_version', COALESCE(p_template_version, 1),
    'paper_width_mm', COALESCE(p_paper_width_mm, 80),
    'font_profile', COALESCE(p_font_profile, 'thermal_vietnamese'),
    'blocks', v_out
  );
END;
$$;


--
-- Name: FUNCTION materialize_print_document(p_kind text, p_payload jsonb, p_template_id bigint, p_template_version integer, p_paper_width_mm integer, p_font_profile text, p_content jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.materialize_print_document(p_kind text, p_payload jsonb, p_template_id bigint, p_template_version integer, p_paper_width_mm integer, p_font_profile text, p_content jsonb) IS 'Materialize active print templates into primitive schema_version=1 document blocks. New ticket layouts should be changed in print_template_versions, not in branch print-agent deployments.';


--
-- Name: merge_orders(bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_orders(p_source_order_id bigint, p_target_order_id bigint, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid                  UUID;
  v_prof_tenant          BIGINT;
  v_prof_branch          BIGINT;
  v_prof_role            TEXT;
  v_source               RECORD;
  v_target               RECORD;
  v_lock_lo              BIGINT;
  v_lock_hi              BIGINT;
  v_flag_enabled         TEXT;
  v_moved_count          INT;
  v_target_subtotal      NUMERIC(15,2);
  v_target_discount_type   TEXT;
  v_target_discount_value  NUMERIC(15,2);
  v_target_discount_note   TEXT;
  v_target_total           NUMERIC(15,2);
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'cashier')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_source_order_id = p_target_order_id THEN
    RAISE EXCEPTION 'merge_self' USING ERRCODE = '22023';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT t.id INTO v_lock_lo
    FROM public.orders t
    WHERE t.id = p_target_order_id
      AND t.merge_request_key = p_idempotency_key
    LIMIT 1;
    IF FOUND THEN
      SELECT subtotal, total_amount INTO v_target_subtotal, v_target_total
      FROM public.orders WHERE id = p_target_order_id;
      RETURN jsonb_build_object(
        'source_order_id',  p_source_order_id,
        'target_order_id',  p_target_order_id,
        'target_subtotal',  COALESCE(v_target_subtotal, 0),
        'target_total',     COALESCE(v_target_total, 0),
        'idempotent',       true
      );
    END IF;
  END IF;

  v_lock_lo := LEAST(p_source_order_id, p_target_order_id);
  v_lock_hi := GREATEST(p_source_order_id, p_target_order_id);
  PERFORM pg_advisory_xact_lock(v_lock_lo);
  PERFORM pg_advisory_xact_lock(v_lock_hi);

  IF v_lock_lo = p_source_order_id THEN
    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.order_number
    INTO v_source FROM public.orders o WHERE o.id = p_source_order_id FOR UPDATE;

    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.order_number
    INTO v_target FROM public.orders o WHERE o.id = p_target_order_id FOR UPDATE;
  ELSE
    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.order_number
    INTO v_target FROM public.orders o WHERE o.id = p_target_order_id FOR UPDATE;

    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.order_number
    INTO v_source FROM public.orders o WHERE o.id = p_source_order_id FOR UPDATE;
  END IF;

  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'source order not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'target order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_source.tenant_id <> v_prof_tenant OR v_target.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_source.branch_id <> v_target.branch_id THEN
    RAISE EXCEPTION 'merge_different_branch' USING ERRCODE = '22023';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_source.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_source.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_source.tenant_id AND key = 'pos_split_merge_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'split_merge_disabled' USING ERRCODE = 'P0001';
  END IF;

  IF v_source.order_type <> 'dine_in' OR v_target.order_type <> 'dine_in' THEN
    RAISE EXCEPTION 'merge_dine_in_only' USING ERRCODE = '22023';
  END IF;

  IF v_source.table_id IS NULL OR v_target.table_id IS NULL
     OR v_source.table_id <> v_target.table_id
  THEN
    RAISE EXCEPTION 'merge_different_tables' USING ERRCODE = '22023';
  END IF;

  IF v_source.status IN ('completed', 'cancelled')
     OR v_target.status IN ('completed', 'cancelled')
  THEN
    RAISE EXCEPTION 'merge_terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_source.payment_status, 'unpaid') = 'paid'
     OR COALESCE(v_target.payment_status, 'unpaid') = 'paid'
  THEN
    RAISE EXCEPTION 'merge_paid' USING ERRCODE = '22023';
  END IF;

  IF v_source.merged_into_order_id IS NOT NULL OR v_target.merged_into_order_id IS NOT NULL THEN
    RAISE EXCEPTION 'merge_already_merged' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.payments
  WHERE order_id IN (p_source_order_id, p_target_order_id)
    AND status NOT IN ('failed', 'completed');
  IF FOUND THEN
    RAISE EXCEPTION 'merge_payment_pending' USING ERRCODE = '22023';
  END IF;

  IF (v_source.discount_type = 'pct' AND COALESCE(v_source.discount_amount, 0) > 0)
     OR (v_target.discount_type = 'pct' AND COALESCE(v_target.discount_amount, 0) > 0)
  THEN
    RAISE EXCEPTION 'merge_pct_discount_blocked' USING ERRCODE = '22023';
  END IF;

  IF v_source.discount_type = 'vnd' AND v_target.discount_type = 'vnd' THEN
    v_target_discount_type  := 'vnd';
    v_target_discount_value := COALESCE(v_source.discount_value, 0)
                             + COALESCE(v_target.discount_value, 0);
    v_target_discount_note  := COALESCE(v_target.discount_note, '')
      || ' + ' || COALESCE(v_source.discount_note, '');
  ELSIF v_source.discount_type = 'vnd' AND v_target.discount_type IS NULL THEN
    v_target_discount_type  := 'vnd';
    v_target_discount_value := v_source.discount_value;
    v_target_discount_note  := v_source.discount_note;
  ELSIF v_target.discount_type = 'vnd' AND v_source.discount_type IS NULL THEN
    v_target_discount_type  := 'vnd';
    v_target_discount_value := v_target.discount_value;
    v_target_discount_note  := v_target.discount_note;
  ELSE
    v_target_discount_type  := NULL;
    v_target_discount_value := NULL;
    v_target_discount_note  := NULL;
  END IF;

  UPDATE public.order_items
     SET order_id   = p_target_order_id,
         updated_at = now()
   WHERE order_id = p_source_order_id
     AND status <> 'cancelled';
  GET DIAGNOSTICS v_moved_count = ROW_COUNT;

  UPDATE public.kds_tickets
     SET order_id   = p_target_order_id,
         updated_at = now()
   WHERE order_id = p_source_order_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_target_subtotal
  FROM public.order_items
  WHERE order_id = p_target_order_id AND status <> 'cancelled';

  -- Set only the trigger inputs. pos_normalize_order_discount_totals fires on
  -- subtotal/discount_* and computes discount_amount, item_discount_amount,
  -- order_discount_amount, and total_amount (including the re-pointed items'
  -- per-item discounts), nulling the order-level metadata if it resolves to 0.
  UPDATE public.orders
     SET subtotal             = v_target_subtotal,
         discount_type        = v_target_discount_type,
         discount_value       = v_target_discount_value,
         discount_note        = v_target_discount_note,
         note                 = CASE
                                  WHEN v_source.note IS NOT NULL AND length(trim(v_source.note)) > 0
                                  THEN COALESCE(v_target.note || E'\n', '')
                                       || '[Gộp từ ' || v_source.order_number || ']: ' || v_source.note
                                  ELSE v_target.note
                                END,
         merge_request_key    = p_idempotency_key,
         updated_at           = now()
   WHERE id = p_target_order_id;

  UPDATE public.orders
     SET status               = 'cancelled',
         subtotal             = 0,
         discount_type        = NULL,
         discount_value       = NULL,
         discount_note        = NULL,
         merged_into_order_id = p_target_order_id,
         updated_at           = now()
   WHERE id = p_source_order_id;

  SELECT total_amount INTO v_target_total
  FROM public.orders WHERE id = p_target_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES
    (v_source.tenant_id, p_source_order_id, v_source.status, 'cancelled', v_uid,
     'merged_into: ' || v_target.order_number || ' (#' || p_target_order_id::TEXT
       || '), moved ' || v_moved_count::TEXT || ' items'),
    (v_target.tenant_id, p_target_order_id, v_target.status, v_target.status, v_uid,
     'merged_from: ' || v_source.order_number || ' (#' || p_source_order_id::TEXT
       || '), received ' || v_moved_count::TEXT || ' items');

  RETURN jsonb_build_object(
    'source_order_id',  p_source_order_id,
    'target_order_id',  p_target_order_id,
    'moved_count',      v_moved_count,
    'target_subtotal',  v_target_subtotal,
    'target_total',     COALESCE(v_target_total, 0)
  );
END;
$$;


--
-- Name: FUNCTION merge_orders(p_source_order_id bigint, p_target_order_id bigint, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.merge_orders(p_source_order_id bigint, p_target_order_id bigint, p_idempotency_key uuid) IS 'Gộp source vào target (cùng table + branch + dine_in, cả 2 chưa paid). Source bị cancel với merged_into_order_id pointer. Items + KDS tickets re-point sang target. Discount: pct ở bên nào → BLOCK; VND cộng dồn. Source-side clears discount_type/value/note when subtotal collapses to 0 (satisfies orders_discount_metadata_paired). Lock LEAST/GREATEST(a,b) tránh deadlock cross-merge. Idempotent qua p_idempotency_key.';


--
-- Name: next_inventory_doc_number(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_inventory_doc_number(p_tenant_id bigint, p_doc_kind text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_year smallint;
  v_seq bigint;
  v_prefix text;
  v_kind text :=
    pg_catalog.lower(pg_catalog.btrim(COALESCE(p_doc_kind, '')));
BEGIN
  IF p_tenant_id IS NULL OR p_tenant_id <= 0 THEN
    RAISE EXCEPTION 'next_inventory_doc_number: invalid tenant_id'
      USING ERRCODE = '22023';
  END IF;
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND (
       public.auth_tenant_id() IS NULL
       OR public.auth_tenant_id() <> p_tenant_id
     ) THEN
    RAISE EXCEPTION 'next_inventory_doc_number: tenant scope mismatch'
      USING ERRCODE = '42501';
  END IF;

  v_prefix := CASE v_kind
    WHEN 'grn' THEN 'GRN'
    WHEN 'transfer' THEN 'DC'
    WHEN 'issue' THEN 'PXK'
    WHEN 'waste' THEN 'HH'
    WHEN 'production' THEN 'LSX'
    WHEN 'stocktake' THEN 'KK'
    WHEN 'count_slip' THEN 'PD'
    WHEN 'stock_request' THEN 'YC'
    WHEN 'purchase_request' THEN 'YCM'
    ELSE NULL
  END;

  IF v_prefix IS NULL THEN
    RAISE EXCEPTION 'next_inventory_doc_number: invalid doc_kind'
      USING ERRCODE = '22023';
  END IF;

  v_year := EXTRACT(
    year FROM (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')
  )::smallint;

  INSERT INTO public.tenant_inventory_doc_counters (
    tenant_id, doc_kind, year, next_seq, updated_at
  )
  VALUES (p_tenant_id, v_kind, v_year, 2, now())
  ON CONFLICT (tenant_id, doc_kind, year) DO UPDATE
  SET next_seq =
        public.tenant_inventory_doc_counters.next_seq + 1,
      updated_at = now()
  RETURNING public.tenant_inventory_doc_counters.next_seq - 1
  INTO v_seq;

  RETURN v_prefix
    || '-'
    || pg_catalog.to_char(
      now() AT TIME ZONE 'Asia/Ho_Chi_Minh',
      'DDMMYYYY'
    )
    || '-'
    || pg_catalog.lpad(v_seq::text, 4, '0');
END;
$$;


--
-- Name: FUNCTION next_inventory_doc_number(p_tenant_id bigint, p_doc_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.next_inventory_doc_number(p_tenant_id bigint, p_doc_kind text) IS 'Atomically allocates PREFIX-DDMMYYYY-#### for new inventory documents using the VN business date and a tenant/kind/year sequence.';


--
-- Name: next_po_display_id(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_po_display_id(p_tenant_id bigint) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_year smallint;
  v_seq bigint;
BEGIN
  IF p_tenant_id IS NULL OR p_tenant_id <= 0 THEN
    RAISE EXCEPTION 'next_po_display_id: invalid tenant_id'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF public.auth_tenant_id() IS NULL
     OR public.auth_tenant_id() <> p_tenant_id THEN
    RAISE EXCEPTION 'next_po_display_id: tenant scope mismatch'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_year := EXTRACT(
    year FROM (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')
  )::smallint;

  INSERT INTO public.tenant_po_counters (
    tenant_id, year, next_seq, updated_at
  )
  VALUES (p_tenant_id, v_year, 2, now())
  ON CONFLICT (tenant_id, year) DO UPDATE
  SET next_seq = public.tenant_po_counters.next_seq + 1,
      updated_at = now()
  RETURNING (
    CASE
      WHEN xmax::text::int = 0 THEN 1
      ELSE public.tenant_po_counters.next_seq - 1
    END
  )
  INTO v_seq;

  RETURN 'PO-'
    || pg_catalog.to_char(
      now() AT TIME ZONE 'Asia/Ho_Chi_Minh',
      'DDMMYYYY'
    )
    || '-'
    || pg_catalog.lpad(v_seq::text, 4, '0');
END;
$$;


--
-- Name: FUNCTION next_po_display_id(p_tenant_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.next_po_display_id(p_tenant_id bigint) IS 'Atomically allocates PO-DDMMYYYY-#### using the VN business date and a tenant/year sequence.';


--
-- Name: normalize_expense_vat_breakdown(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_expense_vat_breakdown() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_line jsonb;
  v_rate numeric;
  v_raw_taxable_amount numeric;
  v_raw_vat_amount numeric;
  v_taxable_amount numeric(15,2);
  v_vat_amount numeric(15,2);
  v_rates numeric[] := ARRAY[]::numeric[];
  v_subtotal numeric := 0;
  v_total_vat numeric := 0;
  v_line_count integer;
  v_normalized_breakdown jsonb := '[]'::jsonb;
BEGIN
  IF TG_OP = 'UPDATE'
     AND current_setting('app.expense_update_id', true) IS DISTINCT FROM OLD.id::text
     AND (
       NEW.vat_breakdown IS DISTINCT FROM OLD.vat_breakdown
       OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
       OR NEW.vat_amount IS DISTINCT FROM OLD.vat_amount
       OR NEW.amount IS DISTINCT FROM OLD.amount
     ) THEN
    RAISE EXCEPTION 'expense_vat_snapshot_immutable'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.vat_breakdown IS NULL
    OR pg_catalog.jsonb_typeof(NEW.vat_breakdown) <> 'array'
    OR pg_catalog.jsonb_array_length(NEW.vat_breakdown) = 0 THEN
    RAISE EXCEPTION 'expense_vat_breakdown_required'
      USING ERRCODE = '22023';
  END IF;

  v_line_count := pg_catalog.jsonb_array_length(NEW.vat_breakdown);
  IF v_line_count < 1 OR v_line_count > 4 THEN
    RAISE EXCEPTION 'invalid_expense_vat_breakdown_count'
      USING ERRCODE = '22023';
  END IF;

  FOR v_line IN
    SELECT value
    FROM pg_catalog.jsonb_array_elements(NEW.vat_breakdown)
  LOOP
    IF pg_catalog.jsonb_typeof(v_line) <> 'object' THEN
      RAISE EXCEPTION 'invalid_expense_vat_breakdown_line'
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_rate := (v_line->>'vat_rate')::numeric;
      v_raw_taxable_amount :=
        (v_line->>'taxable_amount')::numeric;
      v_raw_vat_amount := (v_line->>'vat_amount')::numeric;
    EXCEPTION
      WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RAISE EXCEPTION 'invalid_expense_vat_breakdown_line'
          USING ERRCODE = '22023';
    END;

    IF v_raw_taxable_amount
        <> pg_catalog.round(v_raw_taxable_amount, 2)
       OR v_raw_vat_amount <> pg_catalog.round(v_raw_vat_amount, 2) THEN
      RAISE EXCEPTION 'expense_vat_amount_scale_invalid'
        USING ERRCODE = '22023';
    END IF;

    IF v_rate IS NULL
      OR v_raw_taxable_amount IS NULL
      OR v_raw_vat_amount IS NULL
      OR NOT v_rate = ANY (ARRAY[0, 5, 8, 10]::numeric[])
      OR v_raw_taxable_amount <= 0
      OR v_raw_vat_amount < 0
      OR v_raw_taxable_amount > 9999999999999.99
      OR v_raw_vat_amount > 9999999999999.99
      OR (v_rate = 0 AND v_raw_vat_amount <> 0) THEN
      RAISE EXCEPTION 'invalid_expense_vat_breakdown_line'
        USING ERRCODE = '22023';
    END IF;

    IF v_rate = ANY (v_rates) THEN
      RAISE EXCEPTION 'duplicate_expense_vat_rate'
        USING ERRCODE = '22023';
    END IF;

    v_taxable_amount := v_raw_taxable_amount;
    v_vat_amount := v_raw_vat_amount;
    v_rates := pg_catalog.array_append(v_rates, v_rate);
    v_subtotal := v_subtotal + v_taxable_amount;
    v_total_vat := v_total_vat + v_vat_amount;
    v_normalized_breakdown := v_normalized_breakdown
      || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'vat_rate', v_rate,
          'taxable_amount', v_taxable_amount,
          'vat_amount', v_vat_amount
        )
      );
  END LOOP;

  IF v_subtotal > 9999999999999.99
    OR v_total_vat > 9999999999999.99
    OR v_subtotal + v_total_vat > 9999999999999.99 THEN
    RAISE EXCEPTION 'invalid_expense_vat_breakdown_total'
      USING ERRCODE = '22003';
  END IF;

  NEW.subtotal := v_subtotal;
  NEW.vat_amount := v_total_vat;
  NEW.amount := NEW.subtotal + NEW.vat_amount;

  SELECT pg_catalog.jsonb_agg(
    line.value
    ORDER BY (line.value->>'vat_rate')::numeric
  )
  INTO NEW.vat_breakdown
  FROM pg_catalog.jsonb_array_elements(v_normalized_breakdown)
    AS line(value);

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION normalize_expense_vat_breakdown(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_expense_vat_breakdown() IS 'Rejects excess money scale, normalizes expense VAT buckets, and derives immutable header totals.';


--
-- Name: normalize_supplier_invoice_vat_breakdown(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_supplier_invoice_vat_breakdown() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_line jsonb;
  v_rate numeric(5,2);
  v_taxable numeric(15,2);
  v_vat numeric(15,2);
  v_rates numeric[] := ARRAY[]::numeric[];
  v_subtotal numeric(15,2) := 0;
  v_total_vat numeric(15,2) := 0;
  v_line_count integer;
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.document_status <> 'draft'
     AND OLD.confirmed_at IS NOT NULL
     AND (
       NEW.vat_breakdown IS DISTINCT FROM OLD.vat_breakdown
       OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
       OR NEW.vat_rate IS DISTINCT FROM OLD.vat_rate
       OR NEW.vat_amount IS DISTINCT FROM OLD.vat_amount
       OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
       OR NEW.document_discount_amount IS DISTINCT FROM
         OLD.document_discount_amount
     ) THEN
    RAISE EXCEPTION 'supplier_invoice_confirmed_immutable'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.vat_breakdown IS NULL
     OR pg_catalog.jsonb_typeof(NEW.vat_breakdown) <> 'array' THEN
    RAISE EXCEPTION 'supplier_invoice_vat_breakdown_required'
      USING ERRCODE = '22023';
  END IF;

  v_line_count := pg_catalog.jsonb_array_length(NEW.vat_breakdown);
  IF v_line_count < 1 OR v_line_count > 4 THEN
    RAISE EXCEPTION 'invalid_supplier_invoice_vat_breakdown_count'
      USING ERRCODE = '22023';
  END IF;

  FOR v_line IN
    SELECT value
    FROM pg_catalog.jsonb_array_elements(NEW.vat_breakdown)
  LOOP
    BEGIN
      v_rate := (v_line->>'vat_rate')::numeric;
      v_taxable := (v_line->>'taxable_amount')::numeric;
      v_vat := (v_line->>'vat_amount')::numeric;
    EXCEPTION
      WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RAISE EXCEPTION 'invalid_supplier_invoice_vat_breakdown_line'
          USING ERRCODE = '22023';
    END;

    IF v_rate IS NULL
       OR v_taxable IS NULL
       OR v_vat IS NULL
       OR NOT v_rate = ANY (ARRAY[0, 5, 8, 10]::numeric[])
       OR v_taxable <= 0
       OR v_vat < 0
       OR (v_rate = 0 AND v_vat <> 0)
       OR v_rate = ANY (v_rates) THEN
      RAISE EXCEPTION 'invalid_supplier_invoice_vat_breakdown_line'
        USING ERRCODE = '22023';
    END IF;

    v_rates := pg_catalog.array_append(v_rates, v_rate);
    v_subtotal := v_subtotal + v_taxable;
    v_total_vat := v_total_vat + v_vat;
  END LOOP;

  IF NEW.document_discount_amount < 0
     OR NEW.document_discount_amount > v_subtotal THEN
    RAISE EXCEPTION 'supplier_invoice_document_discount_invalid'
      USING ERRCODE = '22023';
  END IF;

  NEW.subtotal := pg_catalog.round(v_subtotal, 2);
  NEW.vat_amount := pg_catalog.round(v_total_vat, 2);
  NEW.total_amount := NEW.subtotal
    - NEW.document_discount_amount
    + NEW.vat_amount;
  NEW.vat_rate := CASE WHEN v_line_count = 1 THEN v_rates[1] ELSE NULL END;
  IF TG_OP = 'UPDATE'
     AND NEW.document_status = 'confirmed'
     AND OLD.confirmed_at IS NULL THEN
    NEW.confirmed_at := pg_catalog.now();
    NEW.confirmed_by := auth.uid();
  END IF;

  SELECT pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'vat_rate', line.vat_rate,
      'taxable_amount', line.taxable_amount,
      'vat_amount', line.vat_amount
    )
    ORDER BY line.vat_rate
  )
  INTO NEW.vat_breakdown
  FROM pg_catalog.jsonb_to_recordset(NEW.vat_breakdown) AS line(
    vat_rate numeric,
    taxable_amount numeric,
    vat_amount numeric
  );

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION normalize_supplier_invoice_vat_breakdown(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_supplier_invoice_vat_breakdown() IS 'Validates each supplier-invoice VAT bucket and derives header totals before persistence.';


--
-- Name: order_payment_code_is_exposed(bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_payment_code_is_exposed(p_order_id bigint, p_tenant_id bigint, p_branch_id bigint, p_payment_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.payments p
     WHERE p.order_id = p_order_id
       AND p.tenant_id = p_tenant_id
       AND p.branch_id = p_branch_id
       AND p.method = 'vietqr'
       AND p.status = 'pending'
       AND p.provider_ref IS NOT NULL
       AND lower(p.provider_ref) = lower(p_payment_code)
  );
$$;


--
-- Name: FUNCTION order_payment_code_is_exposed(p_order_id bigint, p_tenant_id bigint, p_branch_id bigint, p_payment_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.order_payment_code_is_exposed(p_order_id bigint, p_tenant_id bigint, p_branch_id bigint, p_payment_code text) IS 'Returns true only when a VietQR payment code still belongs to an active pending payment.';


--
-- Name: period_status_at(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.period_status_at(p_tenant_id bigint, p_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_year INT := EXTRACT(YEAR FROM p_at)::INT; v_month INT := EXTRACT(MONTH FROM p_at)::INT; v_p public.accounting_periods%ROWTYPE;
BEGIN
  SELECT * INTO v_p FROM public.accounting_periods WHERE tenant_id = p_tenant_id AND year = v_year AND month = v_month;
  IF NOT FOUND THEN RETURN 'open'; END IF;
  IF v_p.hard_closed_at IS NOT NULL THEN RETURN 'hard_closed'; END IF;
  IF v_p.soft_closed_at IS NOT NULL THEN RETURN 'soft_closed'; END IF;
  RETURN 'open';
END; $$;


--
-- Name: populate_order_item_vat_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.populate_order_item_vat_rate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vat_rate numeric(5,2);
BEGIN
  SELECT menu_items.vat_rate
    INTO v_vat_rate
    FROM public.menu_items
   WHERE menu_items.id = NEW.menu_item_id
     AND menu_items.tenant_id = NEW.tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'menu_item_tax_profile_missing'
      USING ERRCODE = 'no_data_found';
  END IF;

  NEW.vat_rate := v_vat_rate;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION populate_order_item_vat_rate(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.populate_order_item_vat_rate() IS 'Snapshots menu_items.vat_rate on each new order line.';


--
-- Name: pos_daily_limit_item_quantities(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_daily_limit_item_quantities(p_items jsonb) RETURNS TABLE(menu_item_id bigint, quantity integer)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  WITH input AS (
    SELECT elem AS item
    FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) AS item_rows(elem)
  ),
  agg AS (
    SELECT
      (item ->> 'menu_item_id')::bigint AS menu_item_id,
      COALESCE(NULLIF(item ->> 'quantity', '')::integer, 0) AS quantity
    FROM input
    WHERE item ? 'menu_item_id'
      AND (item ->> 'menu_item_id') ~ '^[0-9]+$'

    UNION ALL

    SELECT
      (side_rows.elem ->> 'side_item_id')::bigint AS menu_item_id,
      (
        COALESCE(NULLIF(input.item ->> 'quantity', '')::integer, 0)
        * GREATEST(
            COALESCE(NULLIF(side_rows.elem ->> 'quantity', '')::integer, 1),
            1
          )
      )::integer AS quantity
    FROM input
    CROSS JOIN LATERAL jsonb_array_elements(
      COALESCE(input.item -> 'sides', '[]'::jsonb)
    ) AS side_rows(elem)
    WHERE side_rows.elem ? 'side_item_id'
      AND (side_rows.elem ->> 'side_item_id') ~ '^[0-9]+$'
  )
  SELECT agg.menu_item_id, SUM(agg.quantity)::integer
  FROM agg
  WHERE agg.menu_item_id IS NOT NULL
    AND agg.quantity > 0
  GROUP BY agg.menu_item_id
  ORDER BY agg.menu_item_id ASC;
$_$;


--
-- Name: FUNCTION pos_daily_limit_item_quantities(p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pos_daily_limit_item_quantities(p_items jsonb) IS 'Aggregate POS RPC items into daily-limit demand. Counts each main item quantity and side_item_id demand as parent quantity times side quantity.';


--
-- Name: pos_enrich_order_sides(bigint, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_enrich_order_sides(p_tenant_id bigint, p_main_item_id bigint, p_sides jsonb) RETURNS TABLE(sides_sum numeric, enriched_sides jsonb)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_raw_count   INT := 0;
  v_valid_count INT := 0;
  v_live_count  INT := 0;
BEGIN
  IF p_sides IS NULL THEN
    RETURN QUERY SELECT 0::NUMERIC(15,2), '[]'::JSONB;
    RETURN;
  END IF;

  IF jsonb_typeof(p_sides) <> 'array' THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  v_raw_count := jsonb_array_length(p_sides);
  IF v_raw_count = 0 THEN
    RETURN QUERY SELECT 0::NUMERIC(15,2), '[]'::JSONB;
    RETURN;
  END IF;

  WITH side_input AS (
    SELECT
      (side_el ->> 'side_item_id')::BIGINT AS side_item_id,
      CASE
        WHEN (side_el ->> 'quantity') ~ '^[0-9]+$'
          THEN LEAST(99, GREATEST(1, (side_el ->> 'quantity')::INT))
        ELSE 1
      END AS quantity
    FROM jsonb_array_elements(p_sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  )
  SELECT COUNT(*)::INT INTO v_valid_count
  FROM side_input;

  IF v_valid_count <> v_raw_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  WITH side_input AS (
    SELECT
      (side_el ->> 'side_item_id')::BIGINT AS side_item_id,
      CASE
        WHEN (side_el ->> 'quantity') ~ '^[0-9]+$'
          THEN LEAST(99, GREATEST(1, (side_el ->> 'quantity')::INT))
        ELSE 1
      END AS quantity
    FROM jsonb_array_elements(p_sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  ),
  live_sides AS (
    SELECT 1
    FROM side_input si
    JOIN public.menu_item_available_sides mas
      ON mas.tenant_id = p_tenant_id
     AND mas.main_item_id = p_main_item_id
     AND mas.side_item_id = si.side_item_id
    JOIN public.menu_items mi
      ON mi.id = si.side_item_id
     AND mi.tenant_id = p_tenant_id
     AND mi.is_active = TRUE
  )
  SELECT COUNT(*)::INT INTO v_live_count
  FROM live_sides;

  IF v_live_count <> v_valid_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH side_input AS (
    SELECT
      (side_el ->> 'side_item_id')::BIGINT AS side_item_id,
      CASE
        WHEN (side_el ->> 'quantity') ~ '^[0-9]+$'
          THEN LEAST(99, GREATEST(1, (side_el ->> 'quantity')::INT))
        ELSE 1
      END AS quantity
    FROM jsonb_array_elements(p_sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  ),
  live_sides AS (
    SELECT
      mi.id,
      mi.name,
      mi.base_price,
      mas.is_default,
      si.quantity
    FROM side_input si
    JOIN public.menu_item_available_sides mas
      ON mas.tenant_id = p_tenant_id
     AND mas.main_item_id = p_main_item_id
     AND mas.side_item_id = si.side_item_id
    JOIN public.menu_items mi
      ON mi.id = si.side_item_id
     AND mi.tenant_id = p_tenant_id
     AND mi.is_active = TRUE
  )
  SELECT
    COALESCE(SUM(base_price * quantity), 0)::NUMERIC(15,2),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'side_item_id', id,
          'name', name,
          'price', base_price,
          'quantity', quantity,
          'is_default', is_default
        )
        ORDER BY name
      ),
      '[]'::JSONB
    )
  FROM live_sides;
END;
$_$;


--
-- Name: pos_normalize_order_discount_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_normalize_order_discount_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item_discount NUMERIC(15,2) := 0;
  v_order_discount NUMERIC(15,2) := 0;
  v_discount_base NUMERIC(15,2) := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_item_discount := COALESCE(NEW.item_discount_amount, 0);
  ELSE
    SELECT COALESCE(SUM(LEAST(COALESCE(oi.discount_amount, 0), COALESCE(oi.subtotal, 0))), 0)
    INTO v_item_discount
    FROM public.order_items oi
    WHERE oi.order_id = NEW.id
      AND oi.tenant_id = NEW.tenant_id
      AND oi.status <> 'cancelled';
  END IF;

  IF NEW.status = 'cancelled' THEN
    NEW.item_discount_amount := 0;
    NEW.order_discount_amount := 0;
    NEW.discount_amount := 0;
    NEW.discount_type := NULL;
    NEW.discount_value := NULL;
    NEW.discount_note := NULL;
    NEW.total_amount := GREATEST(0, COALESCE(NEW.service_charge, 0));
    RETURN NEW;
  END IF;

  v_item_discount := LEAST(GREATEST(v_item_discount, 0), COALESCE(NEW.subtotal, 0));
  v_discount_base := GREATEST(COALESCE(NEW.subtotal, 0) - v_item_discount, 0);

  IF NEW.discount_type IS NOT NULL AND NEW.discount_value IS NOT NULL THEN
    IF NEW.discount_type = 'pct' THEN
      NEW.discount_value := LEAST(GREATEST(COALESCE(NEW.discount_value, 0), 0), 100);
    ELSIF NEW.discount_type = 'vnd' THEN
      NEW.discount_value := LEAST(GREATEST(COALESCE(NEW.discount_value, 0), 0), v_discount_base);
    END IF;

    v_order_discount := public.compute_discount_amount(
      NEW.discount_type,
      NEW.discount_value,
      v_discount_base
    );
  END IF;

  IF v_order_discount <= 0 THEN
    NEW.order_discount_amount := 0;
    NEW.discount_type := NULL;
    NEW.discount_value := NULL;
    NEW.discount_note := NULL;
  ELSE
    NEW.order_discount_amount := v_order_discount;
    NEW.discount_note := NULLIF(trim(COALESCE(NEW.discount_note, '')), '');
  END IF;

  NEW.item_discount_amount := v_item_discount;
  NEW.discount_amount := COALESCE(NEW.order_discount_amount, 0) + v_item_discount;
  NEW.total_amount := GREATEST(
    0,
    COALESCE(NEW.subtotal, 0)
      + COALESCE(NEW.service_charge, 0)
      - COALESCE(NEW.discount_amount, 0)
  );

  RETURN NEW;
END;
$$;


--
-- Name: pos_normalize_order_item_discount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_normalize_order_item_discount() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_discount NUMERIC(15,2);
BEGIN
  IF NEW.discount_type IS NULL OR NEW.discount_value IS NULL THEN
    NEW.discount_type := NULL;
    NEW.discount_value := NULL;
    NEW.discount_note := NULL;
    NEW.discount_amount := 0;
    RETURN NEW;
  END IF;

  IF NEW.discount_type NOT IN ('pct', 'vnd') THEN
    RETURN NEW;
  END IF;

  IF NEW.discount_type = 'pct' THEN
    NEW.discount_value := LEAST(GREATEST(COALESCE(NEW.discount_value, 0), 0), 100);
  ELSE
    NEW.discount_value := LEAST(GREATEST(COALESCE(NEW.discount_value, 0), 0), COALESCE(NEW.subtotal, 0));
  END IF;

  v_discount := public.compute_discount_amount(
    NEW.discount_type,
    NEW.discount_value,
    COALESCE(NEW.subtotal, 0)
  );

  IF v_discount <= 0 THEN
    NEW.discount_type := NULL;
    NEW.discount_value := NULL;
    NEW.discount_note := NULL;
    NEW.discount_amount := 0;
  ELSE
    NEW.discount_amount := v_discount;
    NEW.discount_note := NULLIF(trim(COALESCE(NEW.discount_note, '')), '');
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: pos_order_modifier_sum(bigint, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_order_modifier_sum(p_tenant_id bigint, p_main_item_id bigint, p_modifiers jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_raw_count   INT := 0;
  v_valid_count INT := 0;
  v_live_count  INT := 0;
  v_sum         NUMERIC(15,2) := 0;
BEGIN
  IF p_modifiers IS NULL THEN
    RETURN 0;
  END IF;

  IF jsonb_typeof(p_modifiers) <> 'array' THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  v_raw_count := jsonb_array_length(p_modifiers);
  IF v_raw_count = 0 THEN
    RETURN 0;
  END IF;

  WITH modifier_input AS (
    SELECT (mod_el ->> 'modifier_id')::BIGINT AS modifier_id
    FROM jsonb_array_elements(p_modifiers) AS mod_el
    WHERE mod_el ? 'modifier_id'
      AND (mod_el ->> 'modifier_id') ~ '^[0-9]+$'
  )
  SELECT COUNT(*)::INT INTO v_valid_count
  FROM modifier_input;

  IF v_valid_count <> v_raw_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  WITH modifier_input AS (
    SELECT (mod_el ->> 'modifier_id')::BIGINT AS modifier_id
    FROM jsonb_array_elements(p_modifiers) AS mod_el
    WHERE mod_el ? 'modifier_id'
      AND (mod_el ->> 'modifier_id') ~ '^[0-9]+$'
  ),
  live_modifiers AS (
    SELECT m.price
    FROM modifier_input mi
    JOIN public.menu_item_modifiers m
      ON m.id = mi.modifier_id
     AND m.item_id = p_main_item_id
     AND m.tenant_id = p_tenant_id
     AND m.is_active = TRUE
  )
  SELECT COUNT(*)::INT, COALESCE(SUM(price), 0)::NUMERIC(15,2)
  INTO v_live_count, v_sum
  FROM live_modifiers;

  IF v_live_count <> v_valid_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  RETURN v_sum;
END;
$_$;


--
-- Name: pos_touch_order_discount_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_touch_order_discount_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_id BIGINT;
  v_tenant_id BIGINT;
BEGIN
  v_order_id := COALESCE(NEW.order_id, OLD.order_id);
  v_tenant_id := COALESCE(NEW.tenant_id, OLD.tenant_id);

  IF v_order_id IS NOT NULL THEN
    UPDATE public.orders
       SET updated_at = now()
     WHERE id = v_order_id
       AND tenant_id = v_tenant_id;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: post_pos_cancelled_ready_waste(bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_cancelled_ready_waste(p_order_id bigint, p_actor_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_actor uuid := COALESCE(p_actor_id, auth.uid());
  v_order record;
  v_location_id bigint;
  v_location_is_default boolean;
  v_need record;
  v_available numeric(15,3);
  v_inserted int := 0;
  v_row_count int := 0;
  v_reason text := COALESCE(NULLIF(trim(p_reason), ''), 'cancelled_after_kds_ready');
BEGIN
  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.created_by
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'order_not_found');
  END IF;

  v_actor := COALESCE(v_actor, v_order.created_by);

  IF NOT COALESCE((
    SELECT bff.enabled
    FROM public.branch_feature_flags bff
    WHERE bff.branch_id = v_order.branch_id
      AND bff.flag_key = 'pos_stock_outcome_posting'
  ), false) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stock_movements sm
    WHERE sm.tenant_id = v_order.tenant_id
      AND sm.order_id = p_order_id
      AND sm.movement_subtype = 'cancelled_after_kds_ready'
  ) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', true, 'skipped', true, 'reason', 'already_posted');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.kds_tickets kt
    JOIN public.order_items oi
      ON oi.id = kt.order_item_id
     AND oi.tenant_id = kt.tenant_id
    WHERE kt.order_id = p_order_id
      AND kt.tenant_id = v_order.tenant_id
      AND kt.first_ready_at IS NOT NULL
      AND kt.status <> 'cancelled'
      AND oi.status <> 'cancelled'
  ) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'no_ready_kds_items');
  END IF;

  SELECT il.id, il.is_default_consumption
  INTO v_location_id, v_location_is_default
  FROM public.inventory_locations il
  WHERE il.branch_id = v_order.branch_id
    AND il.tenant_id = v_order.tenant_id
    AND il.location_kind = 'warehouse'
    AND il.is_active = TRUE
  ORDER BY il.is_default_consumption DESC, il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'issue_location_missing:%', v_order.branch_id USING ERRCODE = 'P0002';
  END IF;

  IF v_location_is_default IS DISTINCT FROM TRUE THEN
    RAISE WARNING 'default_consumption_location_missing:branch %; using warehouse location %',
      v_order.branch_id,
      v_location_id;
  END IF;

  -- Availability pre-check (hard-fail: cancel-after-ready must not post phantom
  -- waste when stock is insufficient). Preserved verbatim.
  FOR v_need IN
    WITH consumption_lines AS (
      SELECT oi.menu_item_id::bigint AS menu_item_id,
             oi.quantity::numeric AS line_quantity
      FROM public.order_items oi
      WHERE oi.order_id = p_order_id
        AND oi.tenant_id = v_order.tenant_id
        AND oi.status <> 'cancelled'
        AND EXISTS (
          SELECT 1
          FROM public.kds_tickets kt
          WHERE kt.order_item_id = oi.id
            AND kt.tenant_id = oi.tenant_id
            AND kt.order_id = oi.order_id
            AND kt.first_ready_at IS NOT NULL
            AND kt.status <> 'cancelled'
        )

      UNION ALL

      SELECT (s.elem ->> 'side_item_id')::bigint AS menu_item_id,
             oi.quantity::numeric *
               CASE
                 WHEN COALESCE(s.elem ->> 'quantity', '') ~ '^[0-9]+$'
                   THEN (s.elem ->> 'quantity')::numeric
                 ELSE 1
               END AS line_quantity
      FROM public.order_items oi
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(oi.sides, '[]'::jsonb)) AS s(elem)
      WHERE oi.order_id = p_order_id
        AND oi.tenant_id = v_order.tenant_id
        AND oi.status <> 'cancelled'
        AND s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
        AND EXISTS (
          SELECT 1
          FROM public.kds_tickets kt
          WHERE kt.order_item_id = oi.id
            AND kt.tenant_id = oi.tenant_id
            AND kt.order_id = oi.order_id
            AND kt.first_ready_at IS NOT NULL
            AND kt.status <> 'cancelled'
        )
    )
    SELECT
      r.ingredient_id,
      ROUND(SUM(public.inv_to_base_for_tenant(
        v_order.tenant_id,
        r.ingredient_id,
        r.entry_unit_id,
        cl.line_quantity * r.quantity / r.yield_factor
      )), 3)::numeric(15,3) AS need_qty
    FROM consumption_lines cl
    JOIN public.recipes r
      ON r.menu_item_id = cl.menu_item_id
     AND r.tenant_id = v_order.tenant_id
    GROUP BY r.ingredient_id
    HAVING ROUND(SUM(public.inv_to_base_for_tenant(
      v_order.tenant_id,
      r.ingredient_id,
      r.entry_unit_id,
      cl.line_quantity * r.quantity / r.yield_factor
    )), 3) > 0
    ORDER BY r.ingredient_id
  LOOP
    SELECT sl.current_quantity
    INTO v_available
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_order.tenant_id
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id
    FOR UPDATE;

    IF COALESCE(v_available, 0) < v_need.need_qty THEN
      RAISE EXCEPTION 'insufficient_stock_ingredient:%', v_need.ingredient_id USING ERRCODE = 'P0001';
    END IF;
  END LOOP;

  -- INSERT loop: same CTE as the pre-check, with an added entry_unit_id subquery.
  FOR v_need IN
    WITH consumption_lines AS (
      SELECT oi.menu_item_id::bigint AS menu_item_id,
             oi.quantity::numeric AS line_quantity
      FROM public.order_items oi
      WHERE oi.order_id = p_order_id
        AND oi.tenant_id = v_order.tenant_id
        AND oi.status <> 'cancelled'
        AND EXISTS (
          SELECT 1
          FROM public.kds_tickets kt
          WHERE kt.order_item_id = oi.id
            AND kt.tenant_id = oi.tenant_id
            AND kt.order_id = oi.order_id
            AND kt.first_ready_at IS NOT NULL
            AND kt.status <> 'cancelled'
        )

      UNION ALL

      SELECT (s.elem ->> 'side_item_id')::bigint AS menu_item_id,
             oi.quantity::numeric *
               CASE
                 WHEN COALESCE(s.elem ->> 'quantity', '') ~ '^[0-9]+$'
                   THEN (s.elem ->> 'quantity')::numeric
                 ELSE 1
               END AS line_quantity
      FROM public.order_items oi
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(oi.sides, '[]'::jsonb)) AS s(elem)
      WHERE oi.order_id = p_order_id
        AND oi.tenant_id = v_order.tenant_id
        AND oi.status <> 'cancelled'
        AND s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
        AND EXISTS (
          SELECT 1
          FROM public.kds_tickets kt
          WHERE kt.order_item_id = oi.id
            AND kt.tenant_id = oi.tenant_id
            AND kt.order_id = oi.order_id
            AND kt.first_ready_at IS NOT NULL
            AND kt.status <> 'cancelled'
        )
    )
    SELECT
      r.ingredient_id,
      ROUND(SUM(public.inv_to_base_for_tenant(
        v_order.tenant_id,
        r.ingredient_id,
        r.entry_unit_id,
        cl.line_quantity * r.quantity / r.yield_factor
      )), 3)::numeric(15,3) AS need_qty,
      (
        SELECT iu.unit_id
        FROM public.ingredient_units iu
        JOIN public.units u
          ON u.id = iu.unit_id
         AND u.tenant_id = iu.tenant_id
         AND u.is_active = TRUE
        WHERE iu.tenant_id = v_order.tenant_id
          AND iu.ingredient_id = r.ingredient_id
          AND iu.is_base = TRUE
          AND iu.is_active = TRUE
        ORDER BY iu.sort_order ASC, iu.id ASC
        LIMIT 1
      ) AS entry_unit_id
    FROM consumption_lines cl
    JOIN public.recipes r
      ON r.menu_item_id = cl.menu_item_id
     AND r.tenant_id = v_order.tenant_id
    GROUP BY r.ingredient_id
    HAVING ROUND(SUM(public.inv_to_base_for_tenant(
      v_order.tenant_id,
      r.ingredient_id,
      r.entry_unit_id,
      cl.line_quantity * r.quantity / r.yield_factor
    )), 3) > 0
    ORDER BY r.ingredient_id
  LOOP
    IF v_need.entry_unit_id IS NULL THEN
      RAISE EXCEPTION 'entry_unit_not_found:%', v_need.ingredient_id USING ERRCODE = '23503';
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      movement_subtype,
      quantity_change,
      reason,
      created_by,
      order_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    SELECT
      v_order.tenant_id,
      v_order.branch_id,
      v_need.ingredient_id,
      'consumption',
      'cancelled_after_kds_ready',
      -v_need.need_qty,
      'Order ' || p_order_id::text || ' cancelled after KDS ready: ' || v_reason,
      v_actor,
      p_order_id,
      COALESCE(sl.avg_unit_cost, 0),
      v_location_id,
      v_need.entry_unit_id,
      v_need.need_qty
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_order.tenant_id
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id
    ON CONFLICT (
      tenant_id,
      order_id,
      movement_subtype,
      ingredient_id,
      location_id
    )
    WHERE order_id IS NOT NULL
      AND movement_subtype IN (
        'sale_consumption',
        'cancelled_after_kds_ready'
      )
    DO NOTHING;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    v_inserted := v_inserted + v_row_count;
  END LOOP;

  IF v_inserted = 0 THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'no_recipe_movements');
  END IF;

  RETURN jsonb_build_object('order_id', p_order_id, 'consumed', true, 'movements_created', v_inserted);
END;
$_$;


--
-- Name: FUNCTION post_pos_cancelled_ready_waste(p_order_id bigint, p_actor_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_pos_cancelled_ready_waste(p_order_id bigint, p_actor_id uuid, p_reason text) IS 'Internal POS stock outcome helper: posts cancelled_after_kds_ready for ready KDS lines before an active order is cancelled.';


--
-- Name: post_pos_sale_consumption_if_ready(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_sale_consumption_if_ready(p_order_id bigint, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_actor uuid := COALESCE(p_actor_id, auth.uid());
  v_order record;
  v_location_id bigint;
  v_location_is_default boolean;
  v_need record;
  v_available numeric(15,3);
  v_inserted int := 0;
  v_row_count int := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status, o.created_by
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'order_not_found');
  END IF;

  v_actor := COALESCE(v_actor, v_order.created_by);

  IF NOT COALESCE((
    SELECT bff.enabled
    FROM public.branch_feature_flags bff
    WHERE bff.branch_id = v_order.branch_id
      AND bff.flag_key = 'pos_stock_outcome_posting'
  ), false) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') <> 'paid'
     OR v_order.status <> 'completed' THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'pending', true, 'reason', 'order_not_paid_completed');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stock_movements sm
    WHERE sm.tenant_id = v_order.tenant_id
      AND sm.order_id = p_order_id
      AND sm.type = 'consumption'
      AND (sm.movement_subtype IS NULL OR sm.movement_subtype = 'sale_consumption')
  ) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', true, 'skipped', true, 'reason', 'already_posted');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.kds_tickets kt
    JOIN public.order_items oi
      ON oi.id = kt.order_item_id
     AND oi.tenant_id = kt.tenant_id
    WHERE kt.order_id = p_order_id
      AND kt.tenant_id = v_order.tenant_id
      AND kt.status <> 'cancelled'
      AND oi.status <> 'cancelled'
  ) THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.kds_tickets kt
      JOIN public.order_items oi
        ON oi.id = kt.order_item_id
       AND oi.tenant_id = kt.tenant_id
      WHERE kt.order_id = p_order_id
        AND kt.tenant_id = v_order.tenant_id
        AND kt.first_ready_at IS NOT NULL
        AND kt.status <> 'cancelled'
        AND oi.status <> 'cancelled'
    ) THEN
      RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'pending', true, 'reason', 'no_ready_kds_items');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.kds_tickets kt
      JOIN public.order_items oi
        ON oi.id = kt.order_item_id
       AND oi.tenant_id = kt.tenant_id
      WHERE kt.order_id = p_order_id
        AND kt.tenant_id = v_order.tenant_id
        AND kt.status <> 'cancelled'
        AND oi.status <> 'cancelled'
        AND kt.first_ready_at IS NULL
    ) THEN
      RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'pending', true, 'reason', 'kds_not_fully_ready');
    END IF;
  END IF;

  SELECT il.id, il.is_default_consumption
  INTO v_location_id, v_location_is_default
  FROM public.inventory_locations il
  WHERE il.branch_id = v_order.branch_id
    AND il.tenant_id = v_order.tenant_id
    AND il.location_kind = 'warehouse'
    AND il.is_active = TRUE
  ORDER BY il.is_default_consumption DESC, il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'issue_location_missing:%', v_order.branch_id USING ERRCODE = 'P0002';
  END IF;

  IF v_location_is_default IS DISTINCT FROM TRUE THEN
    RAISE WARNING 'default_consumption_location_missing:branch %; using warehouse location %',
      v_order.branch_id,
      v_location_id;
  END IF;

  -- Availability pre-check (fail-soft: a shortage caught here never fails payment
  -- completion; drift is caught by stocktake). Preserved verbatim.
  FOR v_need IN
    WITH qualifying_order_items AS (
      SELECT
        oi.id AS order_item_id,
        oi.menu_item_id::bigint AS menu_item_id,
        oi.quantity::numeric AS line_quantity,
        oi.sides
      FROM public.order_items oi
      JOIN public.menu_items mi
        ON mi.id = oi.menu_item_id
       AND mi.tenant_id = oi.tenant_id
      WHERE oi.order_id = p_order_id
        AND oi.tenant_id = v_order.tenant_id
        AND oi.status <> 'cancelled'
        AND (
          EXISTS (
            SELECT 1
            FROM public.kds_tickets kt
            WHERE kt.order_item_id = oi.id
              AND kt.tenant_id = oi.tenant_id
              AND kt.order_id = oi.order_id
              AND kt.first_ready_at IS NOT NULL
              AND kt.status <> 'cancelled'
          )
          OR (
            oi.sent_to_kitchen_at IS NOT NULL
            AND NOT EXISTS (
              SELECT 1
              FROM public.kds_tickets kt
              WHERE kt.order_item_id = oi.id
                AND kt.tenant_id = oi.tenant_id
                AND kt.order_id = oi.order_id
                AND kt.status <> 'cancelled'
            )
          )
        )
    ),
    consumption_lines AS (
      SELECT menu_item_id, line_quantity
      FROM qualifying_order_items

      UNION ALL

      SELECT (s.elem ->> 'side_item_id')::bigint AS menu_item_id,
             qoi.line_quantity *
               CASE
                 WHEN COALESCE(s.elem ->> 'quantity', '') ~ '^[0-9]+$'
                   THEN (s.elem ->> 'quantity')::numeric
                 ELSE 1
               END AS line_quantity
      FROM qualifying_order_items qoi
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(qoi.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT
      r.ingredient_id,
      ROUND(SUM(public.inv_to_base_for_tenant(
        v_order.tenant_id,
        r.ingredient_id,
        r.entry_unit_id,
        cl.line_quantity * r.quantity / r.yield_factor
      )), 3)::numeric(15,3) AS need_qty
    FROM consumption_lines cl
    JOIN public.recipes r
      ON r.menu_item_id = cl.menu_item_id
     AND r.tenant_id = v_order.tenant_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.recipes r2
      WHERE r2.menu_item_id = cl.menu_item_id
        AND r2.tenant_id = v_order.tenant_id
        AND r2.entry_unit_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.ingredient_units iu
          WHERE iu.tenant_id = v_order.tenant_id
            AND iu.ingredient_id = r2.ingredient_id
            AND iu.unit_id = r2.entry_unit_id
            AND iu.is_active = TRUE
        )
    )
    GROUP BY r.ingredient_id
    HAVING ROUND(SUM(public.inv_to_base_for_tenant(
      v_order.tenant_id,
      r.ingredient_id,
      r.entry_unit_id,
      cl.line_quantity * r.quantity / r.yield_factor
    )), 3) > 0
    ORDER BY r.ingredient_id
  LOOP
    SELECT sl.current_quantity
    INTO v_available
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_order.tenant_id
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id
    FOR UPDATE;

    IF COALESCE(v_available, 0) < v_need.need_qty THEN
      RAISE WARNING 'insufficient_stock_at_posting: order %, ingredient %', p_order_id, v_need.ingredient_id;
      RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'insufficient_stock_at_posting');
    END IF;
  END LOOP;

  -- INSERT loop: same CTE as the pre-check, with an added entry_unit_id subquery.
  FOR v_need IN
    WITH qualifying_order_items AS (
      SELECT
        oi.id AS order_item_id,
        oi.menu_item_id::bigint AS menu_item_id,
        oi.quantity::numeric AS line_quantity,
        oi.sides
      FROM public.order_items oi
      JOIN public.menu_items mi
        ON mi.id = oi.menu_item_id
       AND mi.tenant_id = oi.tenant_id
      WHERE oi.order_id = p_order_id
        AND oi.tenant_id = v_order.tenant_id
        AND oi.status <> 'cancelled'
        AND (
          EXISTS (
            SELECT 1
            FROM public.kds_tickets kt
            WHERE kt.order_item_id = oi.id
              AND kt.tenant_id = oi.tenant_id
              AND kt.order_id = oi.order_id
              AND kt.first_ready_at IS NOT NULL
              AND kt.status <> 'cancelled'
          )
          OR (
            oi.sent_to_kitchen_at IS NOT NULL
            AND NOT EXISTS (
              SELECT 1
              FROM public.kds_tickets kt
              WHERE kt.order_item_id = oi.id
                AND kt.tenant_id = oi.tenant_id
                AND kt.order_id = oi.order_id
                AND kt.status <> 'cancelled'
            )
          )
        )
    ),
    consumption_lines AS (
      SELECT menu_item_id, line_quantity
      FROM qualifying_order_items

      UNION ALL

      SELECT (s.elem ->> 'side_item_id')::bigint AS menu_item_id,
             qoi.line_quantity *
               CASE
                 WHEN COALESCE(s.elem ->> 'quantity', '') ~ '^[0-9]+$'
                   THEN (s.elem ->> 'quantity')::numeric
                 ELSE 1
               END AS line_quantity
      FROM qualifying_order_items qoi
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(qoi.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT
      r.ingredient_id,
      ROUND(SUM(public.inv_to_base_for_tenant(
        v_order.tenant_id,
        r.ingredient_id,
        r.entry_unit_id,
        cl.line_quantity * r.quantity / r.yield_factor
      )), 3)::numeric(15,3) AS need_qty,
      (
        SELECT iu.unit_id
        FROM public.ingredient_units iu
        JOIN public.units u
          ON u.id = iu.unit_id
         AND u.tenant_id = iu.tenant_id
         AND u.is_active = TRUE
        WHERE iu.tenant_id = v_order.tenant_id
          AND iu.ingredient_id = r.ingredient_id
          AND iu.is_base = TRUE
          AND iu.is_active = TRUE
        ORDER BY iu.sort_order ASC, iu.id ASC
        LIMIT 1
      ) AS entry_unit_id
    FROM consumption_lines cl
    JOIN public.recipes r
      ON r.menu_item_id = cl.menu_item_id
     AND r.tenant_id = v_order.tenant_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.recipes r2
      WHERE r2.menu_item_id = cl.menu_item_id
        AND r2.tenant_id = v_order.tenant_id
        AND r2.entry_unit_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.ingredient_units iu
          WHERE iu.tenant_id = v_order.tenant_id
            AND iu.ingredient_id = r2.ingredient_id
            AND iu.unit_id = r2.entry_unit_id
            AND iu.is_active = TRUE
        )
    )
    GROUP BY r.ingredient_id
    HAVING ROUND(SUM(public.inv_to_base_for_tenant(
      v_order.tenant_id,
      r.ingredient_id,
      r.entry_unit_id,
      cl.line_quantity * r.quantity / r.yield_factor
    )), 3) > 0
    ORDER BY r.ingredient_id
  LOOP
    IF v_need.entry_unit_id IS NULL THEN
      RAISE EXCEPTION 'entry_unit_not_found:%', v_need.ingredient_id USING ERRCODE = '23503';
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      movement_subtype,
      quantity_change,
      reason,
      created_by,
      order_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity
    )
    SELECT
      v_order.tenant_id,
      v_order.branch_id,
      v_need.ingredient_id,
      'consumption',
      'sale_consumption',
      -v_need.need_qty,
      'Order ' || p_order_id::text || ' sale consumption',
      v_actor,
      p_order_id,
      COALESCE(sl.avg_unit_cost, 0),
      v_location_id,
      v_need.entry_unit_id,
      v_need.need_qty
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_order.tenant_id
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id
    ON CONFLICT (
      tenant_id,
      order_id,
      movement_subtype,
      ingredient_id,
      location_id
    )
    WHERE order_id IS NOT NULL
      AND movement_subtype IN (
        'sale_consumption',
        'cancelled_after_kds_ready'
      )
    DO NOTHING;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    v_inserted := v_inserted + v_row_count;
  END LOOP;

  IF v_inserted = 0 THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'consumed', false, 'skipped', true, 'reason', 'no_recipe_movements');
  END IF;

  RETURN jsonb_build_object('order_id', p_order_id, 'consumed', true, 'movements_created', v_inserted);
END;
$_$;


--
-- Name: FUNCTION post_pos_sale_consumption_if_ready(p_order_id bigint, p_actor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_pos_sale_consumption_if_ready(p_order_id bigint, p_actor_id uuid) IS 'Posts ready paid-order consumption at the active branch warehouse and returns a fail-soft result when stock is insufficient.';


--
-- Name: post_pos_sale_refund_restore(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_sale_refund_restore(p_order_id bigint, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor  uuid    := COALESCE(p_actor_id, auth.uid());
  v_order  record;
  v_count  int     := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.tenant_id, o.branch_id
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'restored', false, 'skipped', true, 'reason', 'order_not_found');
  END IF;

  -- Idempotency short-circuit: already restored.
  IF EXISTS (
    SELECT 1
    FROM public.stock_movements sm
    WHERE sm.tenant_id = v_order.tenant_id
      AND sm.order_id = p_order_id
      AND sm.movement_subtype = 'sale_consumption_restore'
  ) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'restored', true, 'skipped', true, 'reason', 'already_restored');
  END IF;

  -- Exact inverse of the sale_consumption rows for this order. Each consumption
  -- row has quantity_change <= 0; the inverse is -orig.quantity_change (>= 0),
  -- satisfying the sign-vs-type CHECK on type='refund_restore'.
  INSERT INTO public.stock_movements (
    tenant_id,
    branch_id,
    ingredient_id,
    type,
    movement_subtype,
    quantity_change,
    reason,
    created_by,
    order_id,
    unit_cost,
    location_id,
    entry_unit_id,
    entry_quantity
  )
  SELECT
    orig.tenant_id,
    orig.branch_id,
    orig.ingredient_id,
    'refund_restore',
    'sale_consumption_restore',
    -orig.quantity_change,
    'Refund restore for order ' || p_order_id::text,
    v_actor,
    orig.order_id,
    orig.unit_cost,
    orig.location_id,
    orig.entry_unit_id,
    orig.entry_quantity
  FROM public.stock_movements orig
  WHERE orig.tenant_id = v_order.tenant_id
    AND orig.order_id = p_order_id
    AND orig.type = 'consumption'
    AND orig.movement_subtype = 'sale_consumption'
  ON CONFLICT (tenant_id, order_id, movement_subtype, ingredient_id, location_id)
    WHERE order_id IS NOT NULL
      AND movement_subtype = 'sale_consumption_restore'
  DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'restored', v_count > 0,
    'movements_created', v_count
  );
END;
$$;


--
-- Name: prepare_inventory_valuation_cutover(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_inventory_valuation_cutover(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     OR NOT public.has_permission_any('inventory:valuation_read') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'inventory_valuation_cutover_invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN private.bootstrap_inventory_valuation_from_invoices(v_tenant);
END;
$$;


--
-- Name: prepare_staff_user_provisioning(uuid, text, bigint, bigint, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_staff_user_provisioning(p_token uuid, p_email text, p_tenant_id bigint, p_branch_id bigint, p_position_code text, p_full_name text, p_provisioned_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_token IS NULL
     OR NULLIF(trim(p_email), '') IS NULL
     OR p_tenant_id IS NULL
     OR NULLIF(trim(p_position_code), '') IS NULL
     OR NULLIF(trim(p_full_name), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_staff_provisioning_request'
      USING ERRCODE = '22023';
  END IF;

  DELETE FROM private.auth_user_provisioning_requests
  WHERE expires_at <= now();

  INSERT INTO private.auth_user_provisioning_requests (
    token, email, tenant_id, branch_id, position_code, full_name, provisioned_by
  ) VALUES (
    p_token,
    lower(trim(p_email)),
    p_tenant_id,
    p_branch_id,
    trim(p_position_code),
    trim(p_full_name),
    p_provisioned_by
  );
END;
$$;


--
-- Name: prepare_tax_invoice_issue_job_as_system(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_tax_invoice_issue_job_as_system(p_job_id bigint, p_tax_invoice_id bigint, p_provider_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job public.tax_invoice_issue_jobs%ROWTYPE;
  v_request public.tax_invoice_buyer_requests%ROWTYPE;
  v_invoice public.tax_invoices%ROWTYPE;
  v_has_request boolean := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_provider_ref), '') IS NULL THEN
    RAISE EXCEPTION 'provider_ref_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_job
  FROM public.tax_invoice_issue_jobs job
  WHERE job.id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_issue_job_not_processing' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_request
  FROM public.tax_invoice_buyer_requests request
  WHERE request.tenant_id = v_job.tenant_id
    AND request.order_id = v_job.order_id
  FOR UPDATE;
  v_has_request := FOUND;

  SELECT * INTO v_job
  FROM public.tax_invoice_issue_jobs job
  WHERE job.id = p_job_id
  FOR UPDATE;
  IF NOT FOUND
    OR v_job.status <> 'processing'
    OR v_job.tax_invoice_id IS DISTINCT FROM p_tax_invoice_id
    OR jsonb_typeof(v_job.invoice_payload -> 'draftSnapshot') IS DISTINCT FROM 'object'
    THEN
    RAISE EXCEPTION 'tax_invoice_issue_job_not_processing' USING ERRCODE = '22023';
  END IF;

  IF v_has_request AND v_request.status = 'open' THEN
    IF v_request.expires_at > now() THEN
      RAISE EXCEPTION 'tax_invoice_issue_job_not_ready' USING ERRCODE = '22023';
    END IF;

    UPDATE public.tax_invoice_buyer_requests
    SET status = 'expired',
        closed_at = now(),
        close_reason = 'deadline_elapsed',
        updated_at = now()
    WHERE id = v_request.id;
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices invoice
  WHERE invoice.id = p_tax_invoice_id
    AND invoice.tenant_id = v_job.tenant_id
    AND invoice.order_id = v_job.order_id
  FOR UPDATE;
  IF NOT FOUND
    OR v_invoice.status <> 'draft'
    OR v_invoice.invoice_number IS NOT NULL
    OR v_invoice.invoice_time IS NULL THEN
    RAISE EXCEPTION 'tax_invoice_draft_not_issuable' USING ERRCODE = '22023';
  END IF;
  IF v_invoice.provider_ref IS NOT NULL
    AND v_invoice.provider_ref IS DISTINCT FROM btrim(p_provider_ref) THEN
    RAISE EXCEPTION 'tax_invoice_provider_ref_mismatch' USING ERRCODE = '22023';
  END IF;

  UPDATE public.tax_invoices
  SET status = 'signing',
      provider_ref = btrim(p_provider_ref),
      signing_started_at = now(),
      updated_at = now()
  WHERE id = v_invoice.id;

  INSERT INTO public.tax_invoice_events (
    tax_invoice_id,
    tenant_id,
    from_status,
    to_status,
    actor_id,
    payload,
    note
  ) VALUES (
    v_invoice.id,
    v_invoice.tenant_id,
    'draft',
    'signing',
    NULL,
    jsonb_build_object(
      'job_id', v_job.id,
      'provider_ref', btrim(p_provider_ref),
      'invoice_time', v_invoice.invoice_time
    ),
    'Payment-time draft reserved for provider submission'
  );

  RETURN jsonb_build_object(
    'id', v_invoice.id,
    'status', 'signing',
    'provider_ref', btrim(p_provider_ref)
  );
END;
$$;


--
-- Name: prepare_tax_invoice_issue_job_as_system(bigint, bigint, text, jsonb, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_tax_invoice_issue_job_as_system(p_job_id bigint, p_tax_invoice_id bigint, p_provider_ref text, p_submission_snapshot jsonb, p_subtotal numeric, p_vat_amount numeric, p_total_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job public.tax_invoice_issue_jobs%ROWTYPE;
  v_invoice public.tax_invoices%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role_required' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_submission_snapshot) IS DISTINCT FROM 'object'
    OR p_subtotal < 0 OR p_vat_amount < 0
    OR p_subtotal + p_vat_amount IS DISTINCT FROM p_total_amount THEN
    RAISE EXCEPTION 'invoice_submission_snapshot_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_job
  FROM public.tax_invoice_issue_jobs
  WHERE id = p_job_id AND tax_invoice_id = p_tax_invoice_id
  FOR UPDATE;
  SELECT * INTO v_invoice
  FROM public.tax_invoices
  WHERE id = p_tax_invoice_id AND id = v_job.tax_invoice_id
  FOR UPDATE;

  IF v_job.id IS NULL OR v_invoice.id IS NULL
    OR v_job.status <> 'processing' OR v_invoice.status <> 'draft'
    OR v_invoice.invoice_snapshot IS NULL THEN
    RAISE EXCEPTION 'invoice_prepare_state_invalid' USING ERRCODE = '55000';
  END IF;
  IF v_job.submission_snapshot IS NOT NULL
    AND v_job.submission_snapshot IS DISTINCT FROM p_submission_snapshot THEN
    RAISE EXCEPTION 'invoice_submission_snapshot_immutable'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.tax_invoice_issue_jobs
  SET submission_snapshot = COALESCE(submission_snapshot, p_submission_snapshot),
      updated_at = now()
  WHERE id = v_job.id;

  UPDATE public.tax_invoices
  SET subtotal = p_subtotal,
      vat_rate = NULL,
      vat_amount = p_vat_amount,
      total_amount = p_total_amount,
      provider_ref = btrim(p_provider_ref),
      invoice_snapshot = invoice_snapshot
        || jsonb_build_object('submissionSnapshot', p_submission_snapshot),
      status = 'signing',
      signing_started_at = now(),
      updated_at = now()
  WHERE id = v_invoice.id
  RETURNING * INTO v_invoice;

  RETURN jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status);
END;
$$;


--
-- Name: prepare_tax_invoice_provider_submission(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_tax_invoice_provider_submission(p_tax_invoice_id bigint, p_provider_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_invoice public.tax_invoices%ROWTYPE;
BEGIN
  IF v_actor IS NULL
    OR v_tenant IS NULL
    OR NOT public.auth_is_owner(v_actor)
    OR NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_provider_ref), '') IS NULL THEN
    RAISE EXCEPTION 'provider_ref_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices invoice
  WHERE invoice.id = p_tax_invoice_id
    AND invoice.tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND OR v_invoice.status <> 'signing' THEN
    RAISE EXCEPTION 'tax_invoice_not_signing' USING ERRCODE = '22023';
  END IF;
  IF v_invoice.provider_ref IS NOT NULL
    AND v_invoice.provider_ref IS DISTINCT FROM btrim(p_provider_ref) THEN
    RAISE EXCEPTION 'tax_invoice_provider_ref_mismatch' USING ERRCODE = '22023';
  END IF;

  UPDATE public.tax_invoices
  SET provider_ref = btrim(p_provider_ref), updated_at = now()
  WHERE id = v_invoice.id;

  RETURN jsonb_build_object('id', v_invoice.id, 'provider_ref', btrim(p_provider_ref));
END;
$$;


--
-- Name: prevent_order_amount_mutation_after_payment_code_exposed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_order_amount_mutation_after_payment_code_exposed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_money_changed boolean;
  v_cancelled_unpaid boolean;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF COALESCE(OLD.payment_status, 'unpaid') = 'paid' THEN
    RETURN NEW;
  END IF;

  v_money_changed :=
    NEW.subtotal IS DISTINCT FROM OLD.subtotal
    OR NEW.tax_amount IS DISTINCT FROM OLD.tax_amount
    OR NEW.service_charge IS DISTINCT FROM OLD.service_charge
    OR NEW.discount_type IS DISTINCT FROM OLD.discount_type
    OR NEW.discount_value IS DISTINCT FROM OLD.discount_value
    OR NEW.discount_note IS DISTINCT FROM OLD.discount_note
    OR NEW.order_discount_amount IS DISTINCT FROM OLD.order_discount_amount
    OR NEW.item_discount_amount IS DISTINCT FROM OLD.item_discount_amount
    OR NEW.discount_amount IS DISTINCT FROM OLD.discount_amount
    OR NEW.total_amount IS DISTINCT FROM OLD.total_amount;

  v_cancelled_unpaid :=
    NEW.status = 'cancelled'
    AND OLD.status IS DISTINCT FROM NEW.status
    AND COALESCE(OLD.payment_status, 'unpaid') <> 'paid';

  IF (v_money_changed OR v_cancelled_unpaid)
     AND public.order_payment_code_is_exposed(
       OLD.id,
       OLD.tenant_id,
       OLD.branch_id,
       OLD.payment_code
     )
  THEN
    RAISE EXCEPTION 'payment_code_locked' USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_recipe_entry_unit_invalidation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_recipe_entry_unit_invalidation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.unit_id IS NOT DISTINCT FROM NEW.unit_id
       AND (OLD.is_active IS NOT TRUE OR NEW.is_active IS TRUE) THEN
      RETURN NEW;
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.recipes r
    WHERE r.tenant_id = OLD.tenant_id
      AND r.ingredient_id = OLD.ingredient_id
      AND r.entry_unit_id = OLD.unit_id
  ) THEN
    RAISE EXCEPTION 'ingredient_unit_in_use_by_recipe' USING ERRCODE = '23503';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.production_recipes pr
    WHERE pr.tenant_id = OLD.tenant_id
      AND pr.ingredient_id = OLD.ingredient_id
      AND pr.entry_unit_id = OLD.unit_id
  ) THEN
    RAISE EXCEPTION 'ingredient_unit_in_use_by_production_recipe' USING ERRCODE = '23503';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: print_jobs_attach_document_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_jobs_attach_document_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.payload IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.job_type NOT IN (
    'receipt',
    'provisional_bill',
    'kitchen_ticket',
    'cancel_ticket',
    'shift_close_report'
  ) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.payload ? 'document' THEN
      NEW.payload := NEW.payload - 'document' - 'template_version';
      NEW.payload := NEW.payload || jsonb_build_object('document', OLD.payload->'document');
      IF OLD.payload ? 'template_version' THEN
        NEW.payload := NEW.payload || jsonb_build_object(
          'template_version',
          OLD.payload->'template_version'
        );
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.payload ? 'document' THEN
    RETURN NEW;
  END IF;

  BEGIN
    NEW.payload := public.attach_print_document_to_payload(
      NEW.tenant_id,
      NEW.branch_id,
      NEW.job_type,
      NEW.payload
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[print_jobs_attach_document_trigger] template apply failed for tenant=% branch=% job_type=%: %',
      NEW.tenant_id, NEW.branch_id, NEW.job_type, SQLERRM;
    RETURN NEW;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION print_jobs_attach_document_trigger(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.print_jobs_attach_document_trigger() IS 'M5 observability (2026-05-07): template apply fail-soft now emits RAISE WARNING. Behavior unchanged — RETURN NEW preserves legacy payload for agent fallback.';


--
-- Name: print_template_block_visible(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_template_block_visible(p_block jsonb, p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_field TEXT := p_block->>'when_field';
  v_value TEXT;
  v_other_field TEXT := p_block->>'when_not_equals_field';
  v_numeric NUMERIC;
BEGIN
  IF v_field IS NULL OR v_field = '' THEN
    RETURN true;
  END IF;

  v_value := public.print_template_payload_text(p_payload, v_field);

  IF COALESCE((p_block->>'when_not_empty')::BOOLEAN, false)
     AND COALESCE(NULLIF(btrim(v_value), ''), '') = '' THEN
    RETURN false;
  END IF;

  IF p_block ? 'when_equals'
     AND v_value <> COALESCE(p_block->>'when_equals', '') THEN
    RETURN false;
  END IF;

  IF p_block ? 'when_not_equals'
     AND v_value = COALESCE(p_block->>'when_not_equals', '') THEN
    RETURN false;
  END IF;

  IF v_other_field IS NOT NULL
     AND v_other_field <> ''
     AND v_value = public.print_template_payload_text(p_payload, v_other_field) THEN
    RETURN false;
  END IF;

  IF p_block ? 'when_min' THEN
    BEGIN
      v_numeric := NULLIF(v_value, '')::numeric;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    IF v_numeric IS NULL OR v_numeric < (p_block->>'when_min')::numeric THEN
      RETURN false;
    END IF;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: print_template_datetime(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_template_datetime(p_iso text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(p_iso, '') = '' THEN
    RETURN '';
  END IF;

  IF p_iso ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}' THEN
    RETURN substring(p_iso FROM 12 FOR 5)
      || ' '
      || substring(p_iso FROM 9 FOR 2)
      || '/'
      || substring(p_iso FROM 6 FOR 2)
      || '/'
      || substring(p_iso FROM 1 FOR 4);
  END IF;

  RETURN p_iso;
END;
$$;


