--
-- Name: print_vietqr_crc16(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_vietqr_crc16(p_input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_crc INT := 65535;
  v_i INT;
  v_j INT;
BEGIN
  FOR v_i IN 1..length(COALESCE(p_input, '')) LOOP
    v_crc := (v_crc # ((ascii(substring(p_input FROM v_i FOR 1)) << 8) & 65535)) & 65535;
    FOR v_j IN 1..8 LOOP
      IF (v_crc & 32768) <> 0 THEN
        v_crc := ((v_crc << 1) # 4129) & 65535;
      ELSE
        v_crc := (v_crc << 1) & 65535;
      END IF;
    END LOOP;
  END LOOP;
  RETURN lpad(upper(to_hex(v_crc)), 4, '0');
END;
$$;


--
-- Name: print_vietqr_emvco(text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_vietqr_emvco(p_bank_code text, p_account_no text, p_account_name text, p_amount numeric, p_description text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bin TEXT;
  v_amount TEXT;
  v_description TEXT;
  v_merchant_name TEXT;
  v_beneficiary TEXT;
  v_merchant_account_info TEXT;
  v_additional TEXT := '';
  v_payload TEXT;
BEGIN
  IF COALESCE(p_bank_code, '') = ''
     OR COALESCE(p_account_no, '') = ''
     OR COALESCE(p_amount, 0) <= 0 THEN
    RETURN NULL;
  END IF;

  v_bin := public.print_vietqr_bank_bin(p_bank_code);
  v_amount := trim(to_char(round(p_amount), 'FM9999999999999999'));
  v_description := public.print_vietqr_ascii(p_description, 50);
  v_merchant_name := COALESCE(
    NULLIF(public.print_vietqr_ascii(p_account_name, 25), ''),
    'MERCHANT'
  );

  v_beneficiary :=
    '00' || lpad(length(v_bin)::text, 2, '0') || v_bin
    || '01' || lpad(length(p_account_no)::text, 2, '0') || p_account_no;
  v_merchant_account_info :=
    '0010A000000727'
    || '01' || lpad(length(v_beneficiary)::text, 2, '0') || v_beneficiary
    || '0208QRIBFTTA';

  IF v_description <> '' THEN
    v_additional := '08' || lpad(length(v_description)::text, 2, '0') || v_description;
  END IF;

  v_payload :=
    '000201'
    || '010212'
    || '38' || lpad(length(v_merchant_account_info)::text, 2, '0') || v_merchant_account_info
    || '5303704'
    || '54' || lpad(length(v_amount)::text, 2, '0') || v_amount
    || '5802VN'
    || '59' || lpad(length(v_merchant_name)::text, 2, '0') || v_merchant_name
    || '6007VIETNAM'
    || CASE WHEN v_additional <> ''
         THEN '62' || lpad(length(v_additional)::text, 2, '0') || v_additional
         ELSE ''
       END;

  v_payload := v_payload || '6304';
  RETURN v_payload || public.print_vietqr_crc16(v_payload);
END;
$$;


--
-- Name: FUNCTION print_vietqr_emvco(p_bank_code text, p_account_no text, p_account_name text, p_amount numeric, p_description text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.print_vietqr_emvco(p_bank_code text, p_account_no text, p_account_name text, p_amount numeric, p_description text) IS 'VietQR EMVCo payload for thermal printing. Mirrors buildVietQrEmvco in packages/shared/src/providers/impl/vietqr.ts; keep outputs identical.';


--
-- Name: queue_tax_invoice_issue_job_for_completed_order(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_tax_invoice_issue_job_for_completed_order(p_order_id bigint, p_invoice_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_order public.orders%ROWTYPE;
  v_payment public.payments%ROWTYPE;
BEGIN
  IF v_actor IS NULL
    OR v_tenant IS NULL
    OR NOT (public.auth_is_owner(v_actor) OR public.has_position('accountant'))
    OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND
    OR v_order.payment_status <> 'paid'
    OR v_order.status <> 'completed' THEN
    RAISE EXCEPTION 'tax_invoice_issue_order_not_completed' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_payment
  FROM public.payments
  WHERE tenant_id = v_order.tenant_id
    AND branch_id = v_order.branch_id
    AND order_id = v_order.id
    AND status = 'completed'
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_issue_payment_not_completed' USING ERRCODE = '22023';
  END IF;

  RETURN private.upsert_tax_invoice_issue_job(
    v_order.tenant_id,
    v_order.branch_id,
    v_order.id,
    v_payment.id,
    p_invoice_payload,
    'queued'
  );
END;
$$;


--
-- Name: recall_kds_ticket(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_kds_ticket(p_ticket_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket record;
  v_new_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('kds:recall') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT id, tenant_id, branch_id, status
  INTO v_ticket
  FROM public.kds_tickets
  WHERE id = p_ticket_id
    AND tenant_id = public.auth_tenant_id()
    AND (public.auth_role() = 'owner' OR branch_id = public.auth_branch_id())
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_ticket.status = 'ready' THEN
    v_new_status := 'preparing';
  ELSIF v_ticket.status = 'preparing' THEN
    v_new_status := 'pending';
  ELSE
    RAISE EXCEPTION 'Ticket cannot be recalled from status %', v_ticket.status
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.kds_tickets
  SET status = v_new_status,
      bumped_at = NULL,
      bumped_by = NULL,
      updated_at = now()
  WHERE id = p_ticket_id;

  RETURN v_new_status;
END;
$$;


--
-- Name: recompute_supplier_invoice_matching(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_supplier_invoice_matching(p_invoice_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_old jsonb;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_match') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT pg_catalog.jsonb_build_object(
    'matching_status', invoice.matching_status,
    'matching_reason_code', invoice.matching_reason_code,
    'matching_difference_amount', invoice.matching_difference_amount
  )
  INTO v_old
  FROM public.supplier_invoices invoice
  WHERE invoice.id = p_invoice_id
    AND invoice.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_result := private.apply_supplier_invoice_matching(p_invoice_id);

  PERFORM public.log_audit(
    'supplier_invoice.matching_recomputed',
    'supplier_invoice',
    p_invoice_id,
    v_old,
    v_result
  );

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION recompute_supplier_invoice_matching(p_invoice_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recompute_supplier_invoice_matching(p_invoice_id bigint) IS 'Matches supplier-invoice pre-VAT subtotal to confirmed net accepted GRN value for the invoice supplier (header or line-scoped) and, when fully priced, the linked source or legacy PO subtotal.';


--
-- Name: reconcile_bank_transaction_targets(bigint, text, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_bank_transaction_targets(p_bank_transaction_id bigint, p_target_type text, p_target_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_transaction public.bank_transactions%ROWTYPE;
  v_target_ids bigint[];
  v_target_count integer;
  v_target_total numeric(15,2);
  v_old_matches jsonb;
  v_legacy_result jsonb;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_target_type NOT IN ('payment', 'expense', 'supplier_payment', 'refund')
  THEN
    RAISE EXCEPTION 'invalid_bank_reconciliation_target'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_target_ids, ARRAY[]::bigint[])) selected(target_id)
    WHERE selected.target_id IS NULL OR selected.target_id <= 0
  ) THEN
    RAISE EXCEPTION 'invalid_bank_reconciliation_target'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(
    array_agg(DISTINCT target_id ORDER BY target_id),
    ARRAY[]::bigint[]
  )
  INTO v_target_ids
  FROM unnest(COALESCE(p_target_ids, ARRAY[]::bigint[])) selected(target_id)
  WHERE selected.target_id IS NOT NULL AND selected.target_id > 0;

  IF cardinality(v_target_ids) > 20
    OR (p_target_type = 'payment' AND cardinality(v_target_ids) <> 1)
  THEN
    RAISE EXCEPTION 'invalid_bank_reconciliation_target'
      USING ERRCODE = '22023';
  END IF;

  SELECT transaction.*
  INTO v_transaction
  FROM public.bank_transactions transaction
  WHERE transaction.id = p_bank_transaction_id
    AND transaction.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'bank_transaction_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(match) ORDER BY match.id), '[]'::jsonb)
  INTO v_old_matches
  FROM public.bank_transaction_reconciliation_matches match
  WHERE match.tenant_id = v_tenant_id
    AND match.bank_transaction_id = v_transaction.id;

  IF v_transaction.webhook_event_id IS NOT NULL THEN
    CASE p_target_type
      WHEN 'payment' THEN
        v_legacy_result := public.link_sepay_transaction_to_payment(
          v_transaction.webhook_event_id,
          v_target_ids[1]
        );
      WHEN 'expense' THEN
        v_legacy_result := public.match_sepay_transaction_expenses(
          v_transaction.webhook_event_id,
          v_target_ids
        );
      WHEN 'supplier_payment' THEN
        v_legacy_result := public.match_sepay_transaction_supplier_payments(
          v_transaction.webhook_event_id,
          v_target_ids
        );
      WHEN 'refund' THEN
        v_legacy_result := public.match_sepay_transaction_refunds(
          v_transaction.webhook_event_id,
          v_target_ids
        );
    END CASE;
  END IF;

  IF cardinality(v_target_ids) = 0 THEN
    DELETE FROM public.bank_transaction_reconciliation_matches match
    WHERE match.tenant_id = v_tenant_id
      AND match.bank_transaction_id = v_transaction.id
      AND (
        (p_target_type = 'expense' AND match.expense_id IS NOT NULL)
        OR (
          p_target_type = 'supplier_payment'
          AND match.supplier_payment_id IS NOT NULL
        )
        OR (p_target_type = 'refund' AND match.refund_id IS NOT NULL)
      );

    PERFORM public.log_audit(
      'bank_transaction.reconcile',
      'bank_transaction',
      v_transaction.id,
      v_old_matches,
      jsonb_build_object(
        'target_type', p_target_type,
        'target_ids', '[]'::jsonb,
        'matched_amount', 0
      )
    );

    RETURN jsonb_build_object(
      'bank_transaction_id', v_transaction.id,
      'target_type', p_target_type,
      'target_ids', '[]'::jsonb,
      'matched_amount', 0,
      'legacy_result', v_legacy_result
    );
  END IF;

  CASE p_target_type
    WHEN 'payment' THEN
      IF v_transaction.transfer_type <> 'in' THEN
        RAISE EXCEPTION 'bank_transaction_direction_mismatch'
          USING ERRCODE = '23514';
      END IF;

      SELECT count(*), COALESCE(sum(payment.amount), 0)
      INTO v_target_count, v_target_total
      FROM public.payments payment
      WHERE payment.tenant_id = v_tenant_id
        AND payment.id = ANY(v_target_ids)
        AND payment.method = 'vietqr'
        AND payment.status = 'completed';
    WHEN 'expense' THEN
      IF v_transaction.transfer_type <> 'out' THEN
        RAISE EXCEPTION 'bank_transaction_direction_mismatch'
          USING ERRCODE = '23514';
      END IF;

      SELECT count(*), COALESCE(sum(expense.amount), 0)
      INTO v_target_count, v_target_total
      FROM public.expenses expense
      WHERE expense.tenant_id = v_tenant_id
        AND expense.id = ANY(v_target_ids)
        AND expense.category IN (
          'rent',
          'utilities',
          'gas_fuel',
          'salary',
          'supplies',
          'repair',
          'marketing',
          'fees_tax',
          'hospitality',
          'other'
        )
        AND (
          v_transaction.webhook_event_id IS NOT NULL
          OR (
            expense.payment_method = 'transfer'
            AND expense.paid_at IS NOT NULL
          )
        );
    WHEN 'supplier_payment' THEN
      IF v_transaction.transfer_type <> 'out' THEN
        RAISE EXCEPTION 'bank_transaction_direction_mismatch'
          USING ERRCODE = '23514';
      END IF;

      SELECT count(*), COALESCE(sum(payment.amount), 0)
      INTO v_target_count, v_target_total
      FROM public.supplier_payments payment
      WHERE payment.tenant_id = v_tenant_id
        AND payment.id = ANY(v_target_ids)
        AND payment.payment_method = 'bank_transfer';
    WHEN 'refund' THEN
      IF v_transaction.transfer_type <> 'out' THEN
        RAISE EXCEPTION 'bank_transaction_direction_mismatch'
          USING ERRCODE = '23514';
      END IF;

      SELECT count(*), COALESCE(sum(refund.amount), 0)
      INTO v_target_count, v_target_total
      FROM public.refunds refund
      WHERE refund.tenant_id = v_tenant_id
        AND refund.id = ANY(v_target_ids)
        AND refund.status = 'approved'
        AND refund.payout_method = 'bank_transfer';
  END CASE;

  IF v_target_count <> cardinality(v_target_ids) THEN
    RAISE EXCEPTION 'bank_reconciliation_target_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_target_total <> v_transaction.amount THEN
    RAISE EXCEPTION 'bank_reconciliation_amount_mismatch'
      USING ERRCODE = '23514';
  END IF;

  IF v_transaction.webhook_event_id IS NULL THEN
    IF p_target_type = 'payment' AND EXISTS (
      SELECT 1
      FROM public.webhook_events event
      WHERE event.tenant_id = v_tenant_id
        AND event.payment_id = ANY(v_target_ids)
        AND event.provider = 'sepay'
        AND event.signature_valid IS TRUE
    ) THEN
      RAISE EXCEPTION 'bank_reconciliation_target_already_matched'
        USING ERRCODE = '23505';
    ELSIF p_target_type = 'expense' AND EXISTS (
      SELECT 1
      FROM public.bank_transaction_expense_matches match
      WHERE match.tenant_id = v_tenant_id
        AND match.expense_id = ANY(v_target_ids)
    ) THEN
      RAISE EXCEPTION 'bank_reconciliation_target_already_matched'
        USING ERRCODE = '23505';
    ELSIF p_target_type = 'supplier_payment' AND EXISTS (
      SELECT 1
      FROM public.supplier_payments payment
      WHERE payment.tenant_id = v_tenant_id
        AND payment.id = ANY(v_target_ids)
        AND payment.webhook_event_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'bank_reconciliation_target_already_matched'
        USING ERRCODE = '23505';
    ELSIF p_target_type = 'refund' AND EXISTS (
      SELECT 1
      FROM public.refunds refund
      WHERE refund.tenant_id = v_tenant_id
        AND refund.id = ANY(v_target_ids)
        AND refund.webhook_event_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'bank_reconciliation_target_already_matched'
        USING ERRCODE = '23505';
    END IF;
  END IF;

  DELETE FROM public.bank_transaction_reconciliation_matches match
  WHERE match.tenant_id = v_tenant_id
    AND match.bank_transaction_id = v_transaction.id;

  CASE p_target_type
    WHEN 'payment' THEN
      INSERT INTO public.bank_transaction_reconciliation_matches (
        tenant_id,
        bank_transaction_id,
        payment_id,
        matched_amount,
        created_by
      )
      SELECT
        v_tenant_id,
        v_transaction.id,
        payment.id,
        payment.amount,
        v_actor
      FROM public.payments payment
      WHERE payment.tenant_id = v_tenant_id
        AND payment.id = ANY(v_target_ids);
    WHEN 'expense' THEN
      INSERT INTO public.bank_transaction_reconciliation_matches (
        tenant_id,
        bank_transaction_id,
        expense_id,
        matched_amount,
        created_by
      )
      SELECT
        v_tenant_id,
        v_transaction.id,
        expense.id,
        expense.amount,
        v_actor
      FROM public.expenses expense
      WHERE expense.tenant_id = v_tenant_id
        AND expense.id = ANY(v_target_ids);
    WHEN 'supplier_payment' THEN
      INSERT INTO public.bank_transaction_reconciliation_matches (
        tenant_id,
        bank_transaction_id,
        supplier_payment_id,
        matched_amount,
        created_by
      )
      SELECT
        v_tenant_id,
        v_transaction.id,
        payment.id,
        payment.amount,
        v_actor
      FROM public.supplier_payments payment
      WHERE payment.tenant_id = v_tenant_id
        AND payment.id = ANY(v_target_ids);
    WHEN 'refund' THEN
      INSERT INTO public.bank_transaction_reconciliation_matches (
        tenant_id,
        bank_transaction_id,
        refund_id,
        matched_amount,
        created_by
      )
      SELECT
        v_tenant_id,
        v_transaction.id,
        refund.id,
        refund.amount,
        v_actor
      FROM public.refunds refund
      WHERE refund.tenant_id = v_tenant_id
        AND refund.id = ANY(v_target_ids);
  END CASE;

  PERFORM public.log_audit(
    'bank_transaction.reconcile',
    'bank_transaction',
    v_transaction.id,
    v_old_matches,
    jsonb_build_object(
      'target_type', p_target_type,
      'target_ids', to_jsonb(v_target_ids),
      'matched_amount', v_target_total
    )
  );

  RETURN jsonb_build_object(
    'bank_transaction_id', v_transaction.id,
    'target_type', p_target_type,
    'target_ids', to_jsonb(v_target_ids),
    'matched_amount', v_target_total,
    'legacy_result', v_legacy_result
  );
END;
$$;


--
-- Name: FUNCTION reconcile_bank_transaction_targets(p_bank_transaction_id bigint, p_target_type text, p_target_ids bigint[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_bank_transaction_targets(p_bank_transaction_id bigint, p_target_type text, p_target_ids bigint[]) IS 'Owner-only reconciliation. It classifies a canonical bank movement against operational evidence without changing bank balance; webhook-backed rows retain legacy evidence invariants.';


--
-- Name: reconcile_sepay_order_evidence(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_sepay_order_evidence(p_event_id bigint, p_payment_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result jsonb;
  v_payment_id bigint;
  v_canonical jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT public.reconcile_sepay_order_evidence_core(
    p_event_id,
    p_payment_code
  )
  INTO v_result;

  IF v_result->>'status' = 'matched' THEN
    v_payment_id := NULLIF(v_result->>'payment_id', '')::bigint;
    IF v_payment_id IS NOT NULL THEN
      v_canonical := private.ensure_sepay_payment_reconciliation(
        p_event_id,
        v_payment_id
      );
      v_result := v_result || jsonb_build_object(
        'canonical_reconciliation',
        v_canonical
      );
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION reconcile_sepay_order_evidence(p_event_id bigint, p_payment_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_sepay_order_evidence(p_event_id bigint, p_payment_code text) IS 'Service-role SePay settlement wrapper. The original settlement contract runs first, then the exact bank-to-payment canonical match is repaired in the same transaction.';


--
-- Name: reconcile_sepay_order_evidence_core(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_sepay_order_evidence_core(p_event_id bigint, p_payment_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_event public.webhook_events%ROWTYPE;
  v_order record;
  v_payment record;
  v_payment_code text := btrim(COALESCE(p_payment_code, ''));
  v_amount numeric;
  v_order_count integer := 0;
  v_payment_count integer := 0;
  v_payment_found boolean := false;
  v_order_id bigint;
  v_payment_id bigint;
  v_confirmation jsonb;
  v_confirmation_status text;
  v_review_code text;
  v_can_confirm boolean := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id
    AND provider = 'sepay'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'webhook_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_event.signature_valid
    OR lower(COALESCE(v_event.payload ->> 'transferType', '')) <> 'in'
  THEN
    RAISE EXCEPTION 'webhook_event_invalid' USING ERRCODE = '22023';
  END IF;

  IF v_event.processing_status = 'processed'
     AND v_event.error_code IS NULL
     AND v_event.payment_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'matched',
      'order_id', v_event.order_id,
      'payment_id', v_event.payment_id,
      'idempotent', true
    );
  END IF;

  IF v_event.processing_status = 'processed'
     AND v_event.payment_id IS NULL
     AND v_event.error_code IN (
       'missing_payment_code_needs_review',
       'order_not_found_needs_review',
       'ambiguous_payment_code_needs_review',
       'amount_mismatch_needs_review'
     ) THEN
    RETURN jsonb_build_object(
      'status', CASE v_event.error_code
        WHEN 'missing_payment_code_needs_review' THEN 'missing_payment_code'
        WHEN 'order_not_found_needs_review' THEN 'order_not_found'
        WHEN 'ambiguous_payment_code_needs_review' THEN 'ambiguous_payment_code'
        ELSE 'amount_mismatch'
      END,
      'order_id', v_event.order_id,
      'idempotent', true
    );
  END IF;

  IF v_event.processing_status = 'processed'
     AND v_event.payment_id IS NULL
     AND v_event.error_code IN (
       'payment_method_conflict_needs_review',
       'payment_state_conflict_needs_review',
       'overpayment_needs_review'
     ) THEN
    RETURN jsonb_build_object(
      'status', 'payment_confirmation_failed',
      'review_code', v_event.error_code,
      'order_id', v_event.order_id,
      'idempotent', true
    );
  END IF;

  IF v_payment_code = '' THEN
    UPDATE public.webhook_events
    SET processing_status = 'processed',
        http_status = 200,
        error_code = 'missing_payment_code_needs_review',
        processed_at = COALESCE(processed_at, now())
    WHERE id = v_event.id;

    RETURN jsonb_build_object('status', 'missing_payment_code');
  END IF;

  IF btrim(COALESCE(v_event.payload ->> 'transferAmount', ''))
       !~ '^[0-9]+([.][0-9]+)?$' THEN
    UPDATE public.webhook_events
    SET processing_status = 'failed',
        http_status = 200,
        error_code = 'invalid_amount',
        processed_at = now()
    WHERE id = v_event.id;

    RETURN jsonb_build_object('status', 'invalid_amount');
  END IF;

  v_amount := (v_event.payload ->> 'transferAmount')::numeric;
  IF v_amount <= 0 THEN
    UPDATE public.webhook_events
    SET processing_status = 'failed',
        http_status = 200,
        error_code = 'invalid_amount',
        processed_at = now()
    WHERE id = v_event.id;

    RETURN jsonb_build_object('status', 'invalid_amount');
  END IF;

  SELECT count(*)::integer, min(id)
  INTO v_order_count, v_order_id
  FROM public.orders
  WHERE tenant_id = v_event.tenant_id
    AND lower(COALESCE(payment_code, '')) = lower(v_payment_code)
    AND status <> 'cancelled';

  IF v_order_count = 0 THEN
    UPDATE public.webhook_events
    SET processing_status = 'processed',
        http_status = 200,
        error_code = 'order_not_found_needs_review',
        processed_at = COALESCE(processed_at, now())
    WHERE id = v_event.id;

    RETURN jsonb_build_object('status', 'order_not_found');
  END IF;

  IF v_order_count > 1 THEN
    UPDATE public.webhook_events
    SET processing_status = 'processed',
        http_status = 200,
        error_code = 'ambiguous_payment_code_needs_review',
        processed_at = COALESCE(processed_at, now())
    WHERE id = v_event.id;

    RETURN jsonb_build_object('status', 'ambiguous_payment_code');
  END IF;

  PERFORM pg_advisory_xact_lock(v_order_id);

  SELECT
    id,
    tenant_id,
    branch_id,
    total_amount,
    payment_status,
    payment_method,
    payment_code,
    created_by
  INTO v_order
  FROM public.orders
  WHERE id = v_order_id
    AND tenant_id = v_event.tenant_id
    AND lower(COALESCE(payment_code, '')) = lower(v_payment_code)
    AND status <> 'cancelled'
  FOR UPDATE;

  IF NOT FOUND THEN
    UPDATE public.webhook_events
    SET processing_status = 'processed',
        http_status = 200,
        error_code = 'order_not_found_needs_review',
        processed_at = COALESCE(processed_at, now())
    WHERE id = v_event.id;

    RETURN jsonb_build_object('status', 'order_not_found');
  END IF;

  IF v_amount <> v_order.total_amount THEN
    UPDATE public.webhook_events
    SET order_id = v_order.id,
        processing_status = 'processed',
        http_status = 200,
        error_code = 'amount_mismatch_needs_review',
        processed_at = COALESCE(processed_at, now())
    WHERE id = v_event.id;

    RETURN jsonb_build_object(
      'status', 'amount_mismatch',
      'order_id', v_order.id
    );
  END IF;

  PERFORM p.id
  FROM public.payments p
  WHERE p.tenant_id = v_event.tenant_id
    AND p.order_id = v_order.id
    AND p.status <> 'failed'
  ORDER BY p.id
  FOR UPDATE;

  SELECT count(*)::integer
  INTO v_payment_count
  FROM public.payments p
  WHERE p.tenant_id = v_event.tenant_id
    AND p.order_id = v_order.id
    AND p.status <> 'failed';

  SELECT
    p.id,
    p.method,
    p.amount,
    p.status,
    p.provider_ref,
    p.created_by
  INTO v_payment
  FROM public.payments p
  WHERE p.tenant_id = v_event.tenant_id
    AND p.order_id = v_order.id
    AND p.status <> 'failed'
  ORDER BY p.id DESC
  LIMIT 1;
  v_payment_found := FOUND;

  v_can_confirm := COALESCE(v_payment_count <= 1 AND (
    (
      NOT v_payment_found
      AND COALESCE(v_order.payment_status, 'unpaid') = 'unpaid'
      AND COALESCE(v_order.payment_method, '') IN ('', 'vietqr')
    )
    OR (
      v_payment_found
      AND v_payment.status = 'pending'
      AND v_payment.method = 'vietqr'
      AND v_payment.amount = v_order.total_amount
      AND lower(COALESCE(v_payment.provider_ref, '')) = lower(v_order.payment_code)
      AND v_order.payment_status IN ('unpaid', 'pending')
      AND v_order.payment_method = 'vietqr'
    )
    OR (
      v_payment_found
      AND v_payment.status = 'completed'
      AND v_payment.method = 'vietqr'
      AND v_payment.amount = v_order.total_amount
      AND lower(COALESCE(v_payment.provider_ref, '')) = lower(v_order.payment_code)
      AND v_order.payment_status = 'paid'
      AND v_order.payment_method = 'vietqr'
    )
  ), false);

  IF NOT v_can_confirm THEN
    v_review_code := CASE
      WHEN (
        v_payment_found
        AND v_payment.method IS DISTINCT FROM 'vietqr'
      ) OR COALESCE(v_order.payment_method, '') NOT IN ('', 'vietqr')
      THEN 'payment_method_conflict_needs_review'
      ELSE 'payment_state_conflict_needs_review'
    END;

    UPDATE public.webhook_events
    SET order_id = v_order.id,
        payment_id = NULL,
        processing_status = 'processed',
        http_status = 200,
        error_code = v_review_code,
        processed_at = COALESCE(processed_at, now())
    WHERE id = v_event.id;

    RETURN jsonb_build_object(
      'status', 'payment_confirmation_failed',
      'review_code', v_review_code,
      'order_id', v_order.id
    );
  END IF;

  IF v_payment_found
     AND v_payment.status = 'completed'
     AND EXISTS (
       SELECT 1
       FROM public.webhook_events prior_event
       LEFT JOIN public.payments prior_payment
         ON prior_payment.id = prior_event.payment_id
        AND prior_payment.tenant_id = prior_event.tenant_id
       WHERE prior_event.tenant_id = v_event.tenant_id
         AND prior_event.provider = 'sepay'
         AND prior_event.id <> v_event.id
         AND prior_event.signature_valid
         AND lower(COALESCE(prior_event.payload ->> 'transferType', '')) = 'in'
         AND prior_event.processing_status = 'processed'
         AND prior_event.error_code IS NULL
         AND prior_event.payment_id IS NOT NULL
         AND (
           prior_event.order_id = v_order.id
           OR prior_payment.order_id = v_order.id
         )
     ) THEN
    UPDATE public.webhook_events
    SET order_id = v_order.id,
        payment_id = NULL,
        processing_status = 'processed',
        http_status = 200,
        error_code = 'overpayment_needs_review',
        processed_at = COALESCE(processed_at, now())
    WHERE id = v_event.id;

    RETURN jsonb_build_object(
      'status', 'payment_confirmation_failed',
      'review_code', 'overpayment_needs_review',
      'order_id', v_order.id
    );
  END IF;

  SELECT public.confirm_sepay_payment(
    v_event.tenant_id,
    v_order.id,
    v_order.payment_code,
    v_amount,
    COALESCE(v_event.payload ->> 'accountNumber', ''),
    COALESCE(v_event.payload ->> 'referenceCode', ''),
    v_event.payload
  )
  INTO v_confirmation;

  v_confirmation_status := v_confirmation ->> 'status';
  IF v_confirmation_status IS DISTINCT FROM 'completed'
     AND v_confirmation_status IS DISTINCT FROM 'already_completed' THEN
    UPDATE public.webhook_events
    SET order_id = v_order.id,
        payment_id = NULL,
        processing_status = 'failed',
        http_status = 500,
        error_code = COALESCE(
          NULLIF(v_confirmation_status, ''),
          'payment_confirmation_failed'
        ),
        processed_at = now()
    WHERE id = v_event.id;

    RETURN jsonb_build_object(
      'status', 'payment_confirmation_failed',
      'order_id', v_order.id
    );
  END IF;

  v_payment_id := NULLIF(v_confirmation ->> 'payment_id', '')::bigint;
  IF v_payment_id IS NULL THEN
    UPDATE public.webhook_events
    SET order_id = v_order.id,
        payment_id = NULL,
        processing_status = 'failed',
        http_status = 500,
        error_code = 'payment_confirmation_missing_payment',
        processed_at = now()
    WHERE id = v_event.id;

    RETURN jsonb_build_object(
      'status', 'payment_confirmation_failed',
      'order_id', v_order.id
    );
  END IF;

  UPDATE public.webhook_events
  SET order_id = v_order.id,
      payment_id = v_payment_id,
      processing_status = 'processed',
      http_status = 200,
      error_code = NULL,
      processed_at = now()
  WHERE id = v_event.id;

  RETURN jsonb_build_object(
    'status', 'matched',
    'order_id', v_order.id,
    'payment_id', v_payment_id
  );
END;
$_$;


--
-- Name: reconcile_shift_assignments_week(bigint, bigint, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_shift_assignments_week(p_tenant_id bigint, p_branch_id bigint, p_week_start date, p_assignments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_role text := public.auth_role();
  v_actor_branch bigint := public.auth_branch_id();
  v_tenant bigint := public.auth_tenant_id();
  v_week_end date := p_week_start + 6;
  v_created int := 0;
  v_updated int := 0;
  v_deleted int := 0;
  v_skipped int := 0;
  v_item jsonb;
  v_employee_id bigint;
  v_work_date date;
  v_shift_id bigint;
  v_emp_branch bigint;
  v_lock_key bigint;
  v_existing_id bigint;
  v_existing_shift bigint;
BEGIN
  IF v_actor IS NULL OR v_tenant IS NULL OR v_tenant IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF (
    public.has_permission(p_branch_id, 'hr:assign_shift')
    OR public.has_permission(NULL::bigint, 'hr:assign_shift')
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_role = 'branch_manager' AND (
    p_branch_id IS NULL OR v_actor_branch IS DISTINCT FROM p_branch_id
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_week_start IS NULL OR extract(isodow FROM p_week_start) <> 1 THEN
    RAISE EXCEPTION 'week_start_must_be_monday' USING ERRCODE = '22023';
  END IF;
  IF p_assignments IS NULL OR jsonb_typeof(p_assignments) <> 'array' THEN
    RAISE EXCEPTION 'assignments_must_be_array' USING ERRCODE = '22023';
  END IF;

  v_lock_key := pg_catalog.hashtextextended(
    format('%s:%s:%s', p_tenant_id, coalesce(p_branch_id::text, 'null'), p_week_start::text),
    0
  );
  PERFORM pg_advisory_xact_lock(v_lock_key);

  WITH desired AS (
    SELECT DISTINCT
      (element->>'employee_id')::bigint AS employee_id,
      (element->>'work_date')::date AS work_date,
      (element->>'shift_id')::bigint AS shift_id
    FROM jsonb_array_elements(p_assignments) element
  ),
  omitted AS (
    SELECT assignment.id
    FROM public.shift_assignments assignment
    WHERE assignment.tenant_id = p_tenant_id
      AND assignment.branch_id IS NOT DISTINCT FROM p_branch_id
      AND assignment.work_date BETWEEN p_week_start AND v_week_end
      AND NOT EXISTS (
        SELECT 1
        FROM desired
        WHERE desired.employee_id = assignment.employee_id
          AND desired.work_date = assignment.work_date
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.attendance_records attendance
        WHERE attendance.tenant_id = assignment.tenant_id
          AND attendance.employee_id = assignment.employee_id
          AND attendance.date = assignment.work_date
      )
  ),
  marked_off AS (
    UPDATE public.shift_assignments assignment
    SET shift_id = NULL,
        source = 'day_off',
        assigned_by = v_actor,
        assigned_at = now(),
        updated_at = now()
    FROM omitted
    JOIN public.employee_weekly_schedules schedule
      ON schedule.tenant_id = p_tenant_id
    WHERE assignment.id = omitted.id
      AND schedule.employee_id = assignment.employee_id
      AND assignment.work_date >= schedule.effective_from
      AND CASE extract(isodow FROM assignment.work_date)::integer
        WHEN 1 THEN schedule.monday_shift_id
        WHEN 2 THEN schedule.tuesday_shift_id
        WHEN 3 THEN schedule.wednesday_shift_id
        WHEN 4 THEN schedule.thursday_shift_id
        WHEN 5 THEN schedule.friday_shift_id
        WHEN 6 THEN schedule.saturday_shift_id
        WHEN 7 THEN schedule.sunday_shift_id
      END IS NOT NULL
    RETURNING assignment.id
  ),
  removed AS (
    DELETE FROM public.shift_assignments assignment
    USING omitted
    WHERE assignment.id = omitted.id
      AND NOT EXISTS (
        SELECT 1 FROM marked_off WHERE marked_off.id = assignment.id
      )
    RETURNING assignment.id
  )
  SELECT count(*) INTO v_deleted FROM removed;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_assignments)
  LOOP
    v_employee_id := (v_item->>'employee_id')::bigint;
    v_work_date := (v_item->>'work_date')::date;
    v_shift_id := (v_item->>'shift_id')::bigint;

    IF v_employee_id IS NULL OR v_work_date IS NULL OR v_shift_id IS NULL THEN
      RAISE EXCEPTION 'assignment_fields_required' USING ERRCODE = '22023';
    END IF;
    IF v_work_date < p_week_start OR v_work_date > v_week_end THEN
      RAISE EXCEPTION 'work_date_outside_week' USING ERRCODE = '22023';
    END IF;

    SELECT profile.branch_id
    INTO v_emp_branch
    FROM public.employees employee
    JOIN public.profiles profile
      ON profile.id = employee.profile_id
     AND profile.tenant_id = employee.tenant_id
    WHERE employee.id = v_employee_id
      AND employee.tenant_id = p_tenant_id
      AND employee.is_active
      AND profile.is_active;
    IF NOT FOUND OR v_emp_branch IS DISTINCT FROM p_branch_id THEN
      RAISE EXCEPTION 'employee_not_in_site' USING ERRCODE = '22023';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.shifts shift
      WHERE shift.id = v_shift_id
        AND shift.tenant_id = p_tenant_id
        AND shift.is_active
        AND shift.branch_id IS NULL
    ) THEN
      RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.attendance_records attendance
      WHERE attendance.tenant_id = p_tenant_id
        AND attendance.employee_id = v_employee_id
        AND attendance.date = v_work_date
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    SELECT assignment.id, assignment.shift_id
    INTO v_existing_id, v_existing_shift
    FROM public.shift_assignments assignment
    WHERE assignment.tenant_id = p_tenant_id
      AND assignment.employee_id = v_employee_id
      AND assignment.work_date = v_work_date;

    IF v_existing_id IS NULL THEN
      INSERT INTO public.shift_assignments (
        tenant_id, branch_id, employee_id, shift_id, work_date,
        assigned_by, assigned_at, source
      )
      VALUES (
        p_tenant_id, p_branch_id, v_employee_id, v_shift_id, v_work_date,
        v_actor, now(), 'manual'
      );
      v_created := v_created + 1;
    ELSIF v_existing_shift IS DISTINCT FROM v_shift_id THEN
      UPDATE public.shift_assignments
      SET shift_id = v_shift_id,
          branch_id = p_branch_id,
          source = 'manual',
          assigned_by = v_actor,
          assigned_at = now(),
          updated_at = now()
      WHERE id = v_existing_id;
      v_updated := v_updated + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'created', v_created,
    'updated', v_updated,
    'deleted', v_deleted,
    'skipped', v_skipped
  );
END;
$$;


--
-- Name: reconcile_tax_invoice_provider_issued(bigint, text, text, text, jsonb, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_tax_invoice_provider_issued(p_tax_invoice_id bigint, p_provider_ref text, p_invoice_number text, p_cqt_code text DEFAULT NULL::text, p_provider_data jsonb DEFAULT NULL::jsonb, p_issued_at timestamp with time zone DEFAULT now(), p_trigger_source text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_invoice public.tax_invoices%ROWTYPE;
  v_before_status text;
BEGIN
  IF p_trigger_source NOT IN ('manual', 'cron') THEN
    RAISE EXCEPTION 'invalid_reconcile_trigger_source' USING ERRCODE = '22023';
  END IF;
  IF auth.role() <> 'service_role' THEN
    IF v_actor IS NULL
      OR v_tenant IS NULL
      OR NOT (public.auth_is_owner(v_actor) OR public.has_position('accountant'))
      OR NOT public.has_permission_any('finance:view') THEN
      RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF NULLIF(btrim(p_provider_ref), '') IS NULL
    OR NULLIF(btrim(p_invoice_number), '') IS NULL THEN
    RAISE EXCEPTION 'provider_ref_and_invoice_number_required'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices invoice
  WHERE invoice.id = p_tax_invoice_id
    AND (auth.role() = 'service_role' OR invoice.tenant_id = v_tenant)
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_invoice.status NOT IN ('signing', 'submitted') THEN
    RAISE EXCEPTION 'tax_invoice_reconcile_status_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF v_invoice.provider_ref IS DISTINCT FROM btrim(p_provider_ref) THEN
    RAISE EXCEPTION 'tax_invoice_provider_ref_mismatch'
      USING ERRCODE = '22023';
  END IF;

  v_before_status := v_invoice.status;
  UPDATE public.tax_invoices
  SET invoice_number = btrim(p_invoice_number),
      cqt_code = NULLIF(btrim(p_cqt_code), ''),
      provider_data = COALESCE(p_provider_data, provider_data),
      issued_at = COALESCE(p_issued_at, now()),
      status = 'issued',
      updated_at = now()
  WHERE id = v_invoice.id;

  INSERT INTO public.tax_invoice_events (
    tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note
  ) VALUES (
    v_invoice.id,
    v_invoice.tenant_id,
    v_before_status,
    'issued',
    v_actor,
    jsonb_build_object(
      'provider_ref', btrim(p_provider_ref),
      'invoice_number', btrim(p_invoice_number),
      'cqt_code', NULLIF(btrim(p_cqt_code), ''),
      'trigger_source', p_trigger_source
    ) || COALESCE(p_provider_data, '{}'::jsonb),
    'Provider-issued invoice reconciled'
  );

  INSERT INTO public.reconcile_run_log (
    tenant_id, branch_id, tax_invoice_id, trigger_source, triggered_by,
    before_status, after_status, provider_returned, outcome, error,
    attempt_age_seconds
  ) VALUES (
    v_invoice.tenant_id,
    v_invoice.branch_id,
    v_invoice.id,
    p_trigger_source,
    v_actor,
    v_before_status,
    'issued',
    'issued',
    'transitioned',
    NULL,
    GREATEST(
      0,
      EXTRACT(
        EPOCH FROM (
          now() - COALESCE(v_invoice.signing_started_at, v_invoice.updated_at)
        )
      )::integer
    )
  );

  UPDATE public.tax_invoice_issue_jobs job
  SET status = 'completed',
      locked_until = NULL,
      last_error = NULL,
      updated_at = now()
  WHERE job.tax_invoice_id = v_invoice.id
    AND job.status <> 'completed';

  RETURN jsonb_build_object(
    'id', v_invoice.id,
    'status', 'issued',
    'invoice_number', btrim(p_invoice_number)
  );
END;
$$;


--
-- Name: record_bank_transaction_cash_deposit(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_bank_transaction_cash_deposit(p_bank_transaction_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_transaction public.bank_transactions%ROWTYPE;
  v_event public.webhook_events%ROWTYPE;
  v_expense_id bigint;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
    OR NOT public.has_permission_any('finance:view')
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  SELECT transaction.*
  INTO v_transaction
  FROM public.bank_transactions transaction
  WHERE transaction.id = p_bank_transaction_id
    AND transaction.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'bank_transaction_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_transaction.transfer_type <> 'in' THEN
    RAISE EXCEPTION 'bank_transaction_direction_mismatch'
      USING ERRCODE = '23514';
  END IF;

  SELECT expense.id
  INTO v_expense_id
  FROM public.bank_transaction_reconciliation_matches match
  JOIN public.expenses expense
    ON expense.id = match.expense_id
   AND expense.tenant_id = match.tenant_id
  WHERE match.tenant_id = v_tenant_id
    AND match.bank_transaction_id = v_transaction.id
    AND expense.category = 'bank_deposit'
    AND expense.payment_method = 'cash'
    AND expense.amount = v_transaction.amount
    AND match.matched_amount = v_transaction.amount;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'status', 'already_recorded',
      'expense_id', v_expense_id
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_reconciliation_matches match
    WHERE match.tenant_id = v_tenant_id
      AND match.bank_transaction_id = v_transaction.id
  ) THEN
    RAISE EXCEPTION 'bank_transaction_already_reconciled'
      USING ERRCODE = '23514';
  END IF;

  IF v_transaction.webhook_event_id IS NOT NULL THEN
    SELECT *
    INTO v_event
    FROM public.webhook_events event
    WHERE event.id = v_transaction.webhook_event_id
      AND event.tenant_id = v_tenant_id
    FOR UPDATE;

    IF NOT FOUND
      OR v_event.provider <> 'sepay'
      OR v_event.signature_valid IS NOT TRUE
      OR v_event.processing_status = 'failed'
      OR v_event.payment_id IS NOT NULL
    THEN
      RAISE EXCEPTION 'bank_transaction_already_reconciled'
        USING ERRCODE = '23514';
    END IF;

    IF v_event.expense_id IS NOT NULL THEN
      SELECT expense.id
      INTO v_expense_id
      FROM public.expenses expense
      WHERE expense.id = v_event.expense_id
        AND expense.tenant_id = v_tenant_id
        AND expense.category = 'bank_deposit'
        AND expense.payment_method = 'cash'
        AND expense.amount = v_transaction.amount;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'cash_deposit_link_invalid'
          USING ERRCODE = '23514';
      END IF;

      RETURN jsonb_build_object(
        'status', 'already_recorded',
        'expense_id', v_expense_id
      );
    END IF;
  END IF;

  INSERT INTO public.expenses (
    tenant_id,
    category,
    amount,
    payment_method,
    paid_at,
    expense_date,
    note,
    created_by
  ) VALUES (
    v_tenant_id,
    'bank_deposit',
    v_transaction.amount,
    'cash',
    v_transaction.occurred_at,
    (v_transaction.occurred_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    'Nộp tiền mặt vào ngân hàng',
    v_actor
  )
  RETURNING id INTO v_expense_id;

  INSERT INTO public.bank_transaction_reconciliation_matches (
    tenant_id,
    bank_transaction_id,
    expense_id,
    matched_amount,
    created_by
  ) VALUES (
    v_tenant_id,
    v_transaction.id,
    v_expense_id,
    v_transaction.amount,
    v_actor
  );

  IF v_transaction.webhook_event_id IS NOT NULL THEN
    UPDATE public.webhook_events
    SET expense_id = v_expense_id
    WHERE id = v_transaction.webhook_event_id
      AND tenant_id = v_tenant_id;
  END IF;

  SET CONSTRAINTS
    public.trg_expenses_require_bank_deposit_evidence,
    public.trg_webhook_events_require_finance_evidence,
    public.trg_bank_reconciliation_matches_require_evidence
  IMMEDIATE;

  PERFORM public.log_audit(
    'bank_transaction.cash_deposit',
    'bank_transaction',
    v_transaction.id,
    NULL,
    jsonb_build_object(
      'expense_id', v_expense_id,
      'matched_amount', v_transaction.amount
    )
  );

  RETURN jsonb_build_object(
    'status', 'recorded',
    'expense_id', v_expense_id,
    'bank_transaction_id', v_transaction.id
  );
END;
$$;


--
-- Name: FUNCTION record_bank_transaction_cash_deposit(p_bank_transaction_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_bank_transaction_cash_deposit(p_bank_transaction_id bigint) IS 'Owner-only classification of a trusted inbound bank movement as a cash deposit; it never changes bank balance.';


--
-- Name: record_production_run(bigint, bigint, numeric, bigint, numeric, text, bigint, jsonb, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_production_run(p_branch_id bigint, p_finished_good_id bigint, p_planned_quantity numeric, p_entry_unit_id bigint, p_actual_quantity numeric, p_notes text DEFAULT NULL::text, p_target_branch_id bigint DEFAULT NULL::bigint, p_actual_ingredients jsonb DEFAULT NULL::jsonb, p_source_location_id bigint DEFAULT NULL::bigint, p_target_location_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
  PERFORM auth.role();
  RAISE EXCEPTION 'production_maintenance_legacy_rpc' USING ERRCODE = '55000';
END; $$;


--
-- Name: record_sepay_cash_deposit_as_system(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_sepay_cash_deposit_as_system(p_event_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_event public.webhook_events%ROWTYPE;
  v_amount numeric;
  v_expense_date date;
  v_expense_id bigint;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id
    AND provider = 'sepay'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'webhook_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_event.signature_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'webhook_event_signature_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_event.payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'webhook_event_matches_payment' USING ERRCODE = '23514';
  END IF;

  IF lower(COALESCE(v_event.payload->>'transferType', '')) <> 'in' THEN
    RAISE EXCEPTION 'webhook_event_not_in' USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN COALESCE(v_event.payload->>'transferAmount', '') ~ '^[0-9]+(\.[0-9]+)?$'
      THEN (v_event.payload->>'transferAmount')::numeric
    ELSE NULL
  END
  INTO v_amount;

  IF v_amount IS NULL OR v_amount <= 0 THEN
    RAISE EXCEPTION 'cash_deposit_amount_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_event.expense_id IS NOT NULL THEN
    SELECT e.id
    INTO v_expense_id
    FROM public.expenses e
    WHERE e.id = v_event.expense_id
      AND e.tenant_id = v_event.tenant_id
      AND e.category = 'bank_deposit'
      AND e.payment_method = 'cash'
      AND e.amount = v_amount;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'cash_deposit_link_invalid' USING ERRCODE = '23514';
    END IF;

    RETURN jsonb_build_object(
      'status', 'already_recorded',
      'expense_id', v_expense_id
    );
  END IF;

  SELECT CASE
    WHEN COALESCE(v_event.payload->>'transactionDate', '') ~ '^\d{4}-\d{2}-\d{2}'
      THEN substring(v_event.payload->>'transactionDate' FROM 1 FOR 10)::date
    ELSE (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  END
  INTO v_expense_date;

  INSERT INTO public.expenses (
    tenant_id,
    category,
    amount,
    payment_method,
    paid_at,
    expense_date,
    note
  )
  VALUES (
    v_event.tenant_id,
    'bank_deposit',
    v_amount,
    'cash',
    COALESCE(v_event.processed_at, v_event.created_at, now()),
    v_expense_date,
    COALESCE(NULLIF(v_event.payload->>'content', ''), 'Nộp tiền mặt vào ngân hàng')
  )
  RETURNING id
  INTO v_expense_id;

  UPDATE public.webhook_events
  SET expense_id = v_expense_id
  WHERE id = p_event_id
    AND tenant_id = v_event.tenant_id;

  RETURN jsonb_build_object(
    'status', 'recorded',
    'expense_id', v_expense_id
  );
END;
$_$;


--
-- Name: record_supplier_payment(bigint, bigint, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_supplier_payment(p_tenant_id bigint, p_supplier_invoice_id bigint, p_amount numeric, p_payment_method text, p_idempotency_key uuid, p_reference_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_supplier_id bigint;
  v_outstanding numeric(15,2);
  v_allocations jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT (
       public.auth_is_owner(v_uid)
       OR public.has_position('accountant')
     )
     OR NOT public.has_permission_any('finance:ap_pay')
     OR p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'forbidden_supplier_payment' USING ERRCODE = '42501';
  END IF;

  SELECT
    payment.supplier_id,
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'invoice_id', allocation.supplier_invoice_id,
        'amount', allocation.amount
      )
      ORDER BY allocation.id
    )
  INTO v_supplier_id, v_allocations
  FROM public.supplier_payments payment
  JOIN public.supplier_payment_allocations allocation
    ON allocation.supplier_payment_id = payment.id
   AND allocation.tenant_id = payment.tenant_id
   AND allocation.allocation_intent_key = p_idempotency_key
  WHERE payment.tenant_id = p_tenant_id
    AND payment.idempotency_key = p_idempotency_key
  GROUP BY payment.supplier_id;

  IF v_allocations IS NULL THEN
    SELECT
      invoice.supplier_id,
      invoice.total_amount
        - invoice.paid_amount
        - invoice.credit_applied_amount
    INTO v_supplier_id, v_outstanding
    FROM public.supplier_invoices invoice
    WHERE invoice.id = p_supplier_invoice_id
      AND invoice.tenant_id = p_tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_outstanding <= 0 THEN
      RAISE EXCEPTION 'invoice_already_paid' USING ERRCODE = 'P0001';
    END IF;

    v_allocations := pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'invoice_id', p_supplier_invoice_id,
        'amount', LEAST(p_amount, v_outstanding)
      )
    );
  END IF;

  RETURN public.record_supplier_payment_allocated(
    p_tenant_id,
    v_supplier_id,
    p_amount,
    p_payment_method,
    p_idempotency_key,
    p_reference_note,
    v_allocations
  );
END;
$$;


--
-- Name: record_supplier_payment_allocated(bigint, bigint, numeric, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_supplier_payment_allocated(p_tenant_id bigint, p_supplier_id bigint, p_amount numeric, p_payment_method text, p_idempotency_key uuid, p_reference_note text, p_allocations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_payment_id bigint;
  v_existing public.supplier_payments%ROWTYPE;
  v_allocated numeric(15,2);
  v_advance numeric(15,2);
  v_result_status text := 'partial';
  v_single_invoice_id bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT (
       public.auth_is_owner(v_uid)
       OR public.has_position('accountant')
     )
     OR NOT public.has_permission_any('finance:ap_pay')
     OR p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'forbidden_supplier_payment' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL
     OR p_amount IS NULL
     OR p_amount <= 0
     OR p_amount <> pg_catalog.round(p_amount, 2)
     OR p_payment_method NOT IN ('cash', 'bank_transfer')
     OR pg_catalog.jsonb_typeof(p_allocations) <> 'array' THEN
    RAISE EXCEPTION 'supplier_payment_invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.suppliers supplier
    WHERE supplier.id = p_supplier_id
      AND supplier.tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'supplier_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF (
    SELECT count(DISTINCT (allocation.value->>'invoice_id')::bigint)
    FROM pg_catalog.jsonb_array_elements(p_allocations) allocation
  ) <> pg_catalog.jsonb_array_length(p_allocations) THEN
    RAISE EXCEPTION 'supplier_payment_invoice_duplicate'
      USING ERRCODE = '23505';
  END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'supplier-payment:' || p_tenant_id::text || ':'
        || p_idempotency_key::text,
      0
    )
  );

  SELECT *
  INTO v_existing
  FROM public.supplier_payments payment
  WHERE payment.tenant_id = p_tenant_id
    AND payment.idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.supplier_id IS DISTINCT FROM p_supplier_id
       OR v_existing.amount IS DISTINCT FROM p_amount
       OR v_existing.payment_method IS DISTINCT FROM p_payment_method
       OR v_existing.reference_note IS DISTINCT FROM
         NULLIF(btrim(p_reference_note), '')
       OR (
         SELECT count(*)
         FROM public.supplier_payment_allocations allocation
         WHERE allocation.supplier_payment_id = v_existing.id
           AND allocation.tenant_id = p_tenant_id
           AND allocation.allocation_intent_key = p_idempotency_key
       ) <> pg_catalog.jsonb_array_length(p_allocations)
       OR EXISTS (
         SELECT 1
         FROM pg_catalog.jsonb_array_elements(p_allocations) requested
         WHERE NOT EXISTS (
           SELECT 1
           FROM public.supplier_payment_allocations allocation
           WHERE allocation.supplier_payment_id = v_existing.id
             AND allocation.tenant_id = p_tenant_id
             AND allocation.allocation_intent_key = p_idempotency_key
             AND allocation.supplier_invoice_id =
               (requested.value->>'invoice_id')::bigint
             AND allocation.amount =
               (requested.value->>'amount')::numeric
         )
       ) THEN
      RAISE EXCEPTION 'supplier_payment_idempotency_conflict'
        USING ERRCODE = '22023';
    END IF;

    SELECT COALESCE(sum(allocation.amount), 0)
    INTO v_allocated
    FROM public.supplier_payment_allocations allocation
    WHERE allocation.supplier_payment_id = v_existing.id
      AND allocation.tenant_id = p_tenant_id
      AND allocation.allocation_intent_key = p_idempotency_key;

    RETURN pg_catalog.jsonb_build_object(
      'payment_id', v_existing.id,
      'payment_status', v_existing.idempotency_result_status,
      'allocated_amount', v_allocated,
      'advance_amount', v_existing.amount - v_allocated
    );
  END IF;

  SELECT COALESCE(sum((allocation.value->>'amount')::numeric), 0)
  INTO v_allocated
  FROM pg_catalog.jsonb_array_elements(p_allocations) allocation;
  v_allocated := v_allocated::numeric(15,2);

  PERFORM 1
  FROM public.supplier_invoices invoice
  JOIN pg_catalog.jsonb_array_elements(p_allocations) allocation
    ON invoice.id = (allocation.value->>'invoice_id')::bigint
  WHERE invoice.tenant_id = p_tenant_id
  ORDER BY invoice.id
  FOR UPDATE OF invoice;

  IF v_allocated > p_amount
     OR EXISTS (
       SELECT 1
       FROM pg_catalog.jsonb_array_elements(p_allocations) allocation
       LEFT JOIN public.supplier_invoices invoice
         ON invoice.id = (allocation.value->>'invoice_id')::bigint
        AND invoice.tenant_id = p_tenant_id
       WHERE invoice.id IS NULL
          OR invoice.supplier_id IS DISTINCT FROM p_supplier_id
          OR (allocation.value->>'amount')::numeric <= 0
          OR (allocation.value->>'amount')::numeric
            <> pg_catalog.round(
              (allocation.value->>'amount')::numeric,
              2
            )
          OR invoice.matching_status <> 'matched'
          OR invoice.vat_invoice_attachment_path IS NULL
          OR btrim(invoice.vat_invoice_attachment_path) = ''
          OR (
            invoice.invoice_kind = 'service'
            AND invoice.service_verified_at IS NULL
          )
          OR (
            invoice.invoice_kind = 'goods'
            AND (
              NOT EXISTS (
                SELECT 1
                FROM public.supplier_invoice_receipt_allocations receipt
                WHERE receipt.tenant_id = p_tenant_id
                  AND receipt.supplier_invoice_id = invoice.id
              )
              OR EXISTS (
                SELECT 1
                FROM public.supplier_invoice_receipt_allocations receipt
                LEFT JOIN public.goods_received_notes grn
                  ON grn.id = receipt.grn_id
                 AND grn.tenant_id = receipt.tenant_id
                LEFT JOIN public.purchase_orders purchase_order
                  ON purchase_order.id = receipt.po_id
                 AND purchase_order.tenant_id = receipt.tenant_id
                WHERE receipt.tenant_id = p_tenant_id
                  AND receipt.supplier_invoice_id = invoice.id
                  AND (
                    grn.id IS NULL
                    OR grn.status <> 'confirmed'
                    OR grn.po_id IS DISTINCT FROM receipt.po_id
                    OR purchase_order.supplier_id
                      IS DISTINCT FROM invoice.supplier_id
                  )
              )
            )
          )
          OR (allocation.value->>'amount')::numeric >
            invoice.total_amount
              - invoice.paid_amount
              - invoice.credit_applied_amount
     ) THEN
    RAISE EXCEPTION 'supplier_payment_allocation_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT CASE
    WHEN pg_catalog.jsonb_array_length(p_allocations) = 1
    THEN (p_allocations->0->>'invoice_id')::bigint
    ELSE NULL
  END
  INTO v_single_invoice_id;

  INSERT INTO public.supplier_payments (
    tenant_id,
    supplier_id,
    supplier_invoice_id,
    payment_method,
    amount,
    payment_date,
    reference_note,
    created_by,
    idempotency_key,
    idempotency_result_status
  )
  VALUES (
    p_tenant_id,
    p_supplier_id,
    v_single_invoice_id,
    p_payment_method,
    p_amount,
    pg_catalog.now(),
    NULLIF(btrim(p_reference_note), ''),
    v_uid,
    p_idempotency_key,
    'partial'
  )
  RETURNING id INTO v_payment_id;

  INSERT INTO public.supplier_payment_allocations (
    tenant_id,
    supplier_payment_id,
    supplier_invoice_id,
    amount,
    allocation_intent_key
  )
  SELECT
    p_tenant_id,
    v_payment_id,
    (allocation.value->>'invoice_id')::bigint,
    (allocation.value->>'amount')::numeric(15,2),
    p_idempotency_key
  FROM pg_catalog.jsonb_array_elements(p_allocations) allocation;

  WITH allocated AS (
    SELECT
      (allocation.value->>'invoice_id')::bigint AS invoice_id,
      sum((allocation.value->>'amount')::numeric(15,2)) AS amount
    FROM pg_catalog.jsonb_array_elements(p_allocations) allocation
    GROUP BY (allocation.value->>'invoice_id')::bigint
  )
  UPDATE public.supplier_invoices invoice
  SET paid_amount = invoice.paid_amount + allocated.amount,
      payment_status = CASE
        WHEN invoice.paid_amount
           + allocated.amount
           + invoice.credit_applied_amount
             >= invoice.total_amount THEN 'paid'
        ELSE 'partial'
      END,
      paid_at = CASE
        WHEN invoice.paid_amount
           + allocated.amount
           + invoice.credit_applied_amount
             >= invoice.total_amount THEN pg_catalog.now()
        ELSE invoice.paid_at
      END,
      updated_at = pg_catalog.now()
  FROM allocated
  WHERE invoice.id = allocated.invoice_id
    AND invoice.tenant_id = p_tenant_id;

  v_advance := (p_amount - v_allocated)::numeric(15,2);
  IF v_advance = 0
     AND NOT EXISTS (
       SELECT 1
       FROM pg_catalog.jsonb_array_elements(p_allocations) allocation
       JOIN public.supplier_invoices invoice
         ON invoice.id = (allocation.value->>'invoice_id')::bigint
        AND invoice.tenant_id = p_tenant_id
       WHERE invoice.payment_status <> 'paid'
     ) THEN
    v_result_status := 'paid';
  END IF;

  UPDATE public.supplier_payments
  SET idempotency_result_status = v_result_status,
      updated_at = pg_catalog.now()
  WHERE id = v_payment_id
    AND tenant_id = p_tenant_id;

  PERFORM public.log_audit(
    'supplier_payment.recorded',
    'supplier_payment',
    v_payment_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'supplier_id', p_supplier_id,
      'amount', p_amount,
      'allocated_amount', v_allocated,
      'advance_amount', v_advance,
      'payment_method', p_payment_method
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'payment_id', v_payment_id,
    'payment_status', v_result_status,
    'allocated_amount', v_allocated,
    'advance_amount', v_advance
  );
END;
$$;


--
-- Name: recreate_grn_at_receiving_site(bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recreate_grn_at_receiving_site(p_grn_id bigint, p_target_branch_id bigint, p_target_location_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  c_numeric_15_3_max CONSTANT numeric := 999999999999.999;
  c_numeric_15_2_max CONSTANT numeric := 9999999999999.99;
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_old_grn record;
  v_target_location record;
  v_old_location_id bigint;
  v_new_grn_id bigint;
  v_new_po_id bigint;
  v_new_grn_number text;
  v_new_po_display text;
  v_line record;
  v_net_qty numeric;
  v_net_base numeric;
  v_cost_base numeric;
  v_old_current_qty numeric;
  v_target_current_qty numeric;
  v_target_wac numeric;
  v_next_wac numeric;
  v_old_po_auto boolean := false;
  v_auto_po_lines integer := 0;
  v_invoice_id bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'reason_required_min_10_chars' USING ERRCODE = '22023';
  END IF;

  SELECT grn.*
  INTO v_old_grn
  FROM public.goods_received_notes AS grn
  WHERE grn.id = p_grn_id
    AND grn.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_old_grn.status <> 'confirmed' THEN
    RAISE EXCEPTION 'grn_not_confirmed' USING ERRCODE = '22023';
  END IF;

  IF v_old_grn.branch_id = p_target_branch_id THEN
    RAISE EXCEPTION 'same_branch_use_location_amend' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission(v_old_grn.branch_id, 'procurement:grn_amend') THEN
    RAISE EXCEPTION 'forbidden_source_branch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(p_target_branch_id, 'procurement:grn_amend')
     OR NOT public.has_permission(p_target_branch_id, 'procurement:grn_confirm') THEN
    RAISE EXCEPTION 'forbidden_target_branch' USING ERRCODE = '42501';
  END IF;

  SELECT location.id, location.branch_id, location.location_kind
  INTO v_target_location
  FROM public.inventory_locations AS location
  WHERE location.id = p_target_location_id
    AND location.tenant_id = v_tenant
    AND location.branch_id = p_target_branch_id
    AND location.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_location_invalid' USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.supplier_returns AS supplier_return
    WHERE supplier_return.tenant_id = v_tenant
      AND supplier_return.grn_id = p_grn_id
      AND supplier_return.status <> 'cancelled'
  )
  OR EXISTS (
    SELECT 1
    FROM public.supplier_return_items AS return_item
    JOIN public.supplier_returns AS supplier_return
      ON supplier_return.id = return_item.return_id
     AND supplier_return.tenant_id = return_item.tenant_id
    JOIN public.grn_items AS grn_item
      ON grn_item.id = return_item.grn_item_id
     AND grn_item.tenant_id = return_item.tenant_id
    WHERE return_item.tenant_id = v_tenant
      AND grn_item.grn_id = p_grn_id
      AND supplier_return.status <> 'cancelled'
  ) THEN
    RAISE EXCEPTION 'has_active_supplier_return' USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.supplier_invoices AS invoice
    WHERE invoice.tenant_id = v_tenant
      AND invoice.grn_id = p_grn_id
      AND (
        COALESCE(invoice.payment_status, 'unpaid') <> 'unpaid'
        OR COALESCE(invoice.paid_amount, 0) > 0
        OR COALESCE(invoice.credit_applied_amount, 0) > 0
      )
  ) THEN
    RAISE EXCEPTION 'has_paid_invoice' USING ERRCODE = '23514';
  END IF;

  IF v_old_grn.po_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.audit_logs AS audit_log
      WHERE audit_log.tenant_id = v_tenant
        AND audit_log.action = 'inventory.po.created_from_grn'
        AND audit_log.entity_type = 'purchase_order'
        AND audit_log.entity_id = v_old_grn.po_id
        AND audit_log.new_data ->> 'grn_id' = p_grn_id::text
    ) INTO v_old_po_auto;

    IF NOT v_old_po_auto THEN
      RAISE EXCEPTION 'source_po_attached' USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.goods_received_notes AS grn
      WHERE grn.tenant_id = v_tenant
        AND grn.po_id = v_old_grn.po_id
        AND grn.id <> p_grn_id
        AND grn.status = 'confirmed'
    ) THEN
      RAISE EXCEPTION 'source_po_shared' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_old_grn.location_id IS NOT NULL THEN
    SELECT location.id
    INTO v_old_location_id
    FROM public.inventory_locations AS location
    WHERE location.id = v_old_grn.location_id
      AND location.tenant_id = v_tenant
      AND location.branch_id = v_old_grn.branch_id
      AND location.is_active IS TRUE;
  ELSE
    SELECT location.id
    INTO v_old_location_id
    FROM public.inventory_locations AS location
    WHERE location.tenant_id = v_tenant
      AND location.branch_id = v_old_grn.branch_id
      AND location.location_kind = 'warehouse'
      AND location.is_default_receive IS TRUE
      AND location.is_active IS TRUE
    ORDER BY location.id
    LIMIT 1;
  END IF;

  IF v_old_location_id IS NULL THEN
    RAISE EXCEPTION 'source_location_missing' USING ERRCODE = '23502';
  END IF;

  FOR v_line IN
    SELECT item.*
    FROM public.grn_items AS item
    WHERE item.tenant_id = v_tenant
      AND item.grn_id = p_grn_id
    ORDER BY item.id
    FOR UPDATE
  LOOP
    v_net_qty := v_line.received_quantity - v_line.rejected_quantity;
    v_net_base := public.inv_to_base(
      v_line.ingredient_id,
      v_line.entry_unit_id,
      v_net_qty
    );
    v_cost_base := CASE
      WHEN v_net_base <> 0 THEN ROUND(
        (v_net_qty * v_line.unit_cost) / v_net_base,
        2
      )
      ELSE v_line.unit_cost
    END;

    IF abs(v_net_base) > c_numeric_15_3_max
       OR abs(v_cost_base) > c_numeric_15_2_max THEN
      RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
    END IF;

    IF v_net_base <= 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.stock_levels (
      tenant_id,
      branch_id,
      ingredient_id,
      location_id,
      current_quantity
    ) VALUES (
      v_tenant,
      p_target_branch_id,
      v_line.ingredient_id,
      p_target_location_id,
      0
    )
    ON CONFLICT ON CONSTRAINT stock_levels_ingredient_branch_location_tenant_key
    DO NOTHING;

    PERFORM 1
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.ingredient_id = v_line.ingredient_id
      AND (
        (
          stock.branch_id = v_old_grn.branch_id
          AND stock.location_id = v_old_location_id
        )
        OR (
          stock.branch_id = p_target_branch_id
          AND stock.location_id = p_target_location_id
        )
      )
    ORDER BY stock.branch_id, stock.location_id, stock.ingredient_id
    FOR UPDATE;

    SELECT stock.current_quantity
    INTO v_old_current_qty
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = v_old_grn.branch_id
      AND stock.location_id = v_old_location_id
      AND stock.ingredient_id = v_line.ingredient_id;

    IF COALESCE(v_old_current_qty, 0) < v_net_base THEN
      RAISE EXCEPTION 'insufficient_source_stock:%', v_line.ingredient_id
        USING ERRCODE = '23514';
    END IF;
  END LOOP;

  v_new_grn_number := public.next_inventory_doc_number(v_tenant, 'grn');

  INSERT INTO public.goods_received_notes (
    tenant_id,
    branch_id,
    location_id,
    supplier_id,
    po_id,
    grn_number,
    received_date,
    received_by,
    status,
    notes,
    created_by
  ) VALUES (
    v_tenant,
    p_target_branch_id,
    p_target_location_id,
    v_old_grn.supplier_id,
    NULL,
    v_new_grn_number,
    v_old_grn.received_date,
    v_uid,
    'confirmed',
    NULLIF(btrim(v_old_grn.notes), ''),
    v_uid
  )
  RETURNING id INTO v_new_grn_id;

  INSERT INTO public.grn_items (
    tenant_id,
    grn_id,
    ingredient_id,
    supplier_id,
    received_quantity,
    entry_unit_id,
    unit_cost,
    total_cost,
    rejected_quantity,
    rejection_reason,
    rejected_photo_url
  )
  SELECT
    item.tenant_id,
    v_new_grn_id,
    item.ingredient_id,
    item.supplier_id,
    item.received_quantity,
    item.entry_unit_id,
    item.unit_cost,
    item.total_cost,
    item.rejected_quantity,
    item.rejection_reason,
    item.rejected_photo_url
  FROM public.grn_items AS item
  WHERE item.tenant_id = v_tenant
    AND item.grn_id = p_grn_id
  ORDER BY item.id;

  IF EXISTS (
    SELECT 1
    FROM public.grn_items AS item
    WHERE item.tenant_id = v_tenant
      AND item.grn_id = v_new_grn_id
      AND item.received_quantity - item.rejected_quantity > 0
  ) THEN
    v_new_po_display := public.next_po_display_id(v_tenant);

    INSERT INTO public.purchase_orders (
      tenant_id,
      branch_id,
      supplier_id,
      po_number,
      display_id,
      status,
      notes,
      created_by,
      source_grn_id
    ) VALUES (
      v_tenant,
      p_target_branch_id,
      COALESCE(
        v_old_grn.supplier_id,
        (
          SELECT item.supplier_id
          FROM public.grn_items AS item
          WHERE item.grn_id = v_new_grn_id
            AND item.tenant_id = v_tenant
          ORDER BY item.id
          LIMIT 1
        )
      ),
      v_new_po_display,
      v_new_po_display,
      'received',
      NULLIF(btrim(v_old_grn.notes), ''),
      v_uid,
      v_new_grn_id
    )
    RETURNING id INTO v_new_po_id;

    INSERT INTO public.purchase_order_items (
      tenant_id,
      po_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      unit_price_est,
      line_total
    )
    SELECT
      v_tenant,
      v_new_po_id,
      item.ingredient_id,
      (
        item.received_quantity - item.rejected_quantity
      )::numeric(15,3),
      item.entry_unit_id,
      item.unit_cost,
      ROUND(
        (item.received_quantity - item.rejected_quantity) * item.unit_cost,
        2
      )
    FROM public.grn_items AS item
    WHERE item.tenant_id = v_tenant
      AND item.grn_id = v_new_grn_id
      AND item.received_quantity - item.rejected_quantity > 0;

    GET DIAGNOSTICS v_auto_po_lines = ROW_COUNT;

    UPDATE public.goods_received_notes
    SET po_id = v_new_po_id,
        updated_at = now()
    WHERE id = v_new_grn_id
      AND tenant_id = v_tenant;

    PERFORM public.log_audit(
      'inventory.po.created_from_grn',
      'purchase_order',
      v_new_po_id,
      NULL,
      jsonb_build_object(
        'grn_id', v_new_grn_id,
        'lines', v_auto_po_lines,
        'branch_id', p_target_branch_id
      )
    );
  END IF;

  FOR v_line IN
    SELECT item.*
    FROM public.grn_items AS item
    WHERE item.tenant_id = v_tenant
      AND item.grn_id = p_grn_id
    ORDER BY item.id
  LOOP
    v_net_qty := v_line.received_quantity - v_line.rejected_quantity;
    v_net_base := public.inv_to_base(
      v_line.ingredient_id,
      v_line.entry_unit_id,
      v_net_qty
    );
    v_cost_base := CASE
      WHEN v_net_base <> 0 THEN ROUND(
        (v_net_qty * v_line.unit_cost) / v_net_base,
        2
      )
      ELSE v_line.unit_cost
    END;

    IF v_net_base <= 0 THEN
      CONTINUE;
    END IF;

    SELECT stock.current_quantity, stock.avg_unit_cost
    INTO v_target_current_qty, v_target_wac
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = p_target_branch_id
      AND stock.location_id = p_target_location_id
      AND stock.ingredient_id = v_line.ingredient_id;

    v_target_current_qty := COALESCE(v_target_current_qty, 0);

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      quantity_change,
      reason,
      created_by,
      grn_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity
    ) VALUES (
      v_tenant,
      v_old_grn.branch_id,
      v_line.ingredient_id,
      'grn_amend',
      -v_net_base,
      'GRN ' || v_old_grn.grn_number || ' recreated at ' || v_new_grn_number ||
        ': reverse source receipt - ' || trim(p_reason),
      v_uid,
      p_grn_id,
      v_cost_base,
      v_old_location_id,
      v_line.entry_unit_id,
      v_net_qty
    );

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      quantity_change,
      reason,
      created_by,
      grn_id,
      unit_cost,
      location_id,
      entry_unit_id,
      entry_quantity
    ) VALUES (
      v_tenant,
      p_target_branch_id,
      v_line.ingredient_id,
      'grn_receipt',
      v_net_base,
      'GRN ' || v_new_grn_number || ' recreated from ' || v_old_grn.grn_number ||
        ': target receipt - ' || trim(p_reason),
      v_uid,
      v_new_grn_id,
      v_cost_base,
      p_target_location_id,
      v_line.entry_unit_id,
      v_net_qty
    );

    v_next_wac := CASE
      WHEN v_target_current_qty + v_net_base > 0 THEN ROUND(
        (
          (v_target_current_qty * COALESCE(v_target_wac, 0))
          + (v_net_base * v_cost_base)
        ) / (v_target_current_qty + v_net_base),
        2
      )
      ELSE v_cost_base
    END;

    IF abs(v_next_wac) > c_numeric_15_2_max THEN
      RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
    END IF;

    UPDATE public.stock_levels AS stock
    SET avg_unit_cost = v_next_wac,
        updated_at = now()
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = p_target_branch_id
      AND stock.location_id = p_target_location_id
      AND stock.ingredient_id = v_line.ingredient_id;

    UPDATE public.ingredients AS ingredient
    SET unit_cost = v_cost_base,
        updated_at = now()
    WHERE ingredient.tenant_id = v_tenant
      AND ingredient.id = v_line.ingredient_id;
  END LOOP;

  UPDATE public.goods_received_notes
  SET status = 'cancelled',
      updated_at = now()
  WHERE id = p_grn_id
    AND tenant_id = v_tenant;

  IF v_old_po_auto THEN
    UPDATE public.purchase_orders
    SET status = 'cancelled',
        updated_at = now()
    WHERE id = v_old_grn.po_id
      AND tenant_id = v_tenant
      AND status IN ('sent', 'partially_received', 'received');
  END IF;

  UPDATE public.supplier_invoices
  SET grn_id = v_new_grn_id,
      po_id = v_new_po_id,
      updated_at = now()
  WHERE tenant_id = v_tenant
    AND grn_id = p_grn_id
    AND COALESCE(payment_status, 'unpaid') = 'unpaid'
    AND COALESCE(paid_amount, 0) = 0
    AND COALESCE(credit_applied_amount, 0) = 0;

  FOR v_invoice_id IN
    SELECT invoice.id
    FROM public.supplier_invoices AS invoice
    WHERE invoice.tenant_id = v_tenant
      AND invoice.grn_id = v_new_grn_id
  LOOP
    PERFORM public.recompute_supplier_invoice_matching(v_invoice_id);
  END LOOP;

  PERFORM public.log_audit(
    'inventory.grn.recreated_receiving_site',
    'goods_received_note',
    p_grn_id,
    jsonb_build_object(
      'grn_id', p_grn_id,
      'grn_number', v_old_grn.grn_number,
      'branch_id', v_old_grn.branch_id,
      'location_id', v_old_location_id,
      'po_id', v_old_grn.po_id,
      'status', 'confirmed'
    ),
    jsonb_build_object(
      'new_grn_id', v_new_grn_id,
      'new_grn_number', v_new_grn_number,
      'branch_id', p_target_branch_id,
      'location_id', p_target_location_id,
      'po_id', v_new_po_id,
      'old_auto_po_cancelled', v_old_po_auto,
      'reason', trim(p_reason)
    )
  );

  PERFORM public.log_audit(
    'inventory.grn.recreated_from_source',
    'goods_received_note',
    v_new_grn_id,
    NULL,
    jsonb_build_object(
      'source_grn_id', p_grn_id,
      'source_grn_number', v_old_grn.grn_number,
      'reason', trim(p_reason)
    )
  );

  RETURN jsonb_build_object(
    'old_grn_id', p_grn_id,
    'old_grn_number', v_old_grn.grn_number,
    'new_grn_id', v_new_grn_id,
    'new_grn_number', v_new_grn_number,
    'new_po_id', v_new_po_id,
    'old_auto_po_cancelled', v_old_po_auto
  );
END;
$$;


--
-- Name: reduce_order_item_quantity(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reduce_order_item_quantity(p_order_item_id bigint, p_new_quantity integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid           UUID;
  v_prof_tenant   BIGINT;
  v_prof_branch   BIGINT;
  v_prof_role     TEXT;
  v_item          public.order_items%ROWTYPE;
  v_order         public.orders%ROWTYPE;
  v_old_qty       INT;
  v_qty_diff      INT;
  v_new_subtotal  NUMERIC(15,2);
  v_subtotal_sum  NUMERIC(15,2);
  v_disc_amount   NUMERIC(15,2);
  v_total_amount  NUMERIC(15,2);
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'cashier') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'reason too short' USING ERRCODE = '22023';
  END IF;

  IF p_new_quantity IS NULL OR p_new_quantity < 1 THEN
    RAISE EXCEPTION 'new quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_item.status IN ('served', 'cancelled') THEN
    RAISE EXCEPTION 'item not reducible' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  v_old_qty := v_item.quantity;

  IF p_new_quantity >= v_old_qty THEN
    RAISE EXCEPTION 'no reduction needed' USING ERRCODE = '22023';
  END IF;

  v_qty_diff := v_old_qty - p_new_quantity;
  v_new_subtotal := v_item.unit_price * p_new_quantity;

  UPDATE public.order_items
  SET quantity   = p_new_quantity,
      subtotal   = v_new_subtotal,
      updated_at = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET updated_at = now()
  WHERE order_item_id = p_order_item_id
    AND tenant_id = v_item.tenant_id
    AND status NOT IN ('served', 'cancelled');

  IF v_item.menu_item_id IS NOT NULL THEN
    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = GREATEST(sold_today - v_qty_diff, 0),
        updated_at = now()
    WHERE branch_id = v_order.branch_id
      AND menu_item_id = v_item.menu_item_id
      AND limit_date = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  END IF;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal_sum
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  v_disc_amount := public.compute_discount_amount(
    v_order.discount_type, v_order.discount_value, v_subtotal_sum
  );
  v_total_amount := v_subtotal_sum
    + COALESCE(v_order.service_charge, 0)
    - v_disc_amount;

  UPDATE public.orders
  SET subtotal        = v_subtotal_sum,
      discount_amount = v_disc_amount,
      total_amount    = v_total_amount,
      updated_at      = now()
  WHERE id = v_item.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
    'reduce_item ' || p_order_item_id::text
      || ': ' || v_old_qty::text || '->' || p_new_quantity::text
      || ': ' || p_reason
  );

  RETURN jsonb_build_object(
    'order_id',           v_item.order_id,
    'order_item_id',      p_order_item_id,
    'old_quantity',       v_old_qty,
    'new_quantity',       p_new_quantity,
    'qty_reduced',        v_qty_diff,
    'subtotal',           v_subtotal_sum,
    'discount_amount',    v_disc_amount,
    'total_amount',       v_total_amount,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


--
-- Name: FUNCTION reduce_order_item_quantity(p_order_item_id bigint, p_new_quantity integer, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reduce_order_item_quantity(p_order_item_id bigint, p_new_quantity integer, p_reason text) IS 'Giảm SL món đã gửi (qty: từ N xuống M, M<N, M>=1). Lock order + item, permission pos:void_order, recompute subtotal/discount/total qua compute_discount_amount, bump kds_tickets.updated_at, decrement branch_menu_item_daily_limits.sold_today cho menu_item của row (DAILY-LIMIT-REDUCE-QTY-LEAK fix). Reason >=5 ký tự, ghi order_status_history. Block khi item served/cancelled, order completed/cancelled, hoặc payment_status=paid.';


--
-- Name: refresh_abc_classification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_abc_classification() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count INT;
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_inventory_value_ranking;
  DELETE FROM public.ingredient_abc_class;
  INSERT INTO public.ingredient_abc_class (tenant_id, branch_id, ingredient_id, class, stock_value, cumulative_share)
  WITH ranked AS (
    SELECT r.tenant_id, r.branch_id, r.ingredient_id, r.total_value,
      SUM(r.total_value) OVER (PARTITION BY r.tenant_id, r.branch_id ORDER BY r.total_value DESC
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum,
      SUM(r.total_value) OVER (PARTITION BY r.tenant_id, r.branch_id) AS branch_total
    FROM public.mv_inventory_value_ranking r WHERE r.total_value > 0
  )
  SELECT tenant_id, branch_id, ingredient_id,
    CASE WHEN running_sum / NULLIF(branch_total, 0) <= 0.80 THEN 'A'
         WHEN running_sum / NULLIF(branch_total, 0) <= 0.95 THEN 'B'
         ELSE 'C' END,
    total_value, COALESCE(running_sum / NULLIF(branch_total, 0), 0)::NUMERIC(5,4)
  FROM ranked;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END; $$;


--
-- Name: refresh_finance_views(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_finance_views() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Authenticated callers must hold settings:tenant (matches the server action);
  -- pg_cron runs with no JWT (auth.uid() IS NULL) and bypasses the check.
  IF auth.uid() IS NOT NULL AND NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'permission denied: settings:tenant required' USING ERRCODE = '42501';
  END IF;

  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_food_cost;
  INSERT INTO public.mv_refresh_log(view_name, refreshed_at)
    VALUES ('mv_food_cost', now())
    ON CONFLICT (view_name) DO UPDATE SET refreshed_at = EXCLUDED.refreshed_at;
END;
$$;


--
-- Name: refresh_inventory_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_inventory_dashboard() RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Authenticated callers must hold appropriate permissions;
  -- pg_cron runs with no JWT (auth.uid() IS NULL) and bypasses the check.
  IF auth.uid() IS NOT NULL THEN
    IF NOT (public.has_permission(NULL, 'reports:view_branch') OR public.has_permission(NULL, 'reports:view_tenant')
         OR public.has_permission(NULL, 'settings:branch') OR public.has_permission(NULL, 'settings:tenant')) THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_inventory_stock_current;

  INSERT INTO public.mv_refresh_log(view_name, refreshed_at)
    VALUES ('mv_inventory_stock_current', now())
    ON CONFLICT (view_name) DO UPDATE SET refreshed_at = EXCLUDED.refreshed_at;

  RETURN now();
END; $$;


--
-- Name: refund_paid_order(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_paid_order(p_order_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor          uuid   := auth.uid();
  v_tenant         bigint := public.auth_tenant_id();
  v_order          record;
  v_payment        record;
  v_invoice        record;
  v_refund_id      bigint;
  v_in_summary     boolean := false;
  v_invoice_action text   := 'none';
BEGIN
  IF v_actor IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 20 THEN
    RAISE EXCEPTION 'reason_too_short' USING ERRCODE = '22023';
  END IF;
  IF length(p_reason) > 500 THEN
    RAISE EXCEPTION 'reason_too_long' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT id, tenant_id, branch_id, status, payment_status
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_order.tenant_id <> v_tenant THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(v_order.branch_id, 'pos:void_paid_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_order.status = 'cancelled' THEN
    RAISE EXCEPTION 'order_already_cancelled' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.payment_status <> 'paid' THEN
    RAISE EXCEPTION 'order_not_paid' USING ERRCODE = 'P0001';
  END IF;

  SELECT id, branch_id, amount, status, method
  INTO v_payment
  FROM public.payments
  WHERE order_id = p_order_id
    AND tenant_id = v_tenant
    AND status = 'completed'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_completed_payment' USING ERRCODE = 'P0001';
  END IF;
  PERFORM 1
  FROM public.payments
  WHERE order_id = p_order_id
    AND tenant_id = v_tenant
    AND status = 'completed'
    AND id <> v_payment.id;
  IF FOUND THEN
    RAISE EXCEPTION 'multiple_payments' USING ERRCODE = 'P0001';
  END IF;

  IF v_payment.amount > 0 THEN
    PERFORM 1
    FROM public.refunds
    WHERE payment_id = v_payment.id
      AND status IN ('pending', 'approved');
    IF FOUND THEN
      RAISE EXCEPTION 'already_refunded' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- HĐĐT: block daily_summary (B2C summary correction is accountant-only on portal).
  SELECT EXISTS (
    SELECT 1
    FROM public.tax_invoice_orders tio
    JOIN public.tax_invoices ti ON ti.id = tio.tax_invoice_id
    WHERE tio.order_id = p_order_id
      AND ti.invoice_kind = 'daily_summary'
      AND ti.status NOT IN ('cancelled', 'replaced')
  )
  INTO v_in_summary;
  IF v_in_summary THEN
    RAISE EXCEPTION 'order_in_daily_summary' USING ERRCODE = 'P0001';
  END IF;

  -- Classify the active per_order invoice (draft/signing/submitted/issued).
  SELECT id, status, provider_ref, provider, issued_at
  INTO v_invoice
  FROM public.tax_invoices
  WHERE order_id = p_order_id
    AND tenant_id = v_tenant
    AND invoice_kind = 'per_order'
    AND status IN ('draft', 'signing', 'submitted', 'issued')
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;
  IF FOUND THEN
    IF v_invoice.status IN ('signing', 'submitted', 'issued')
       AND v_invoice.provider_ref IS NOT NULL
       AND v_invoice.issued_at IS NOT NULL
       AND (v_invoice.issued_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
             < date_trunc('month', (now() AT TIME ZONE 'Asia/Ho_Chi_Minh'))::date THEN
      RAISE EXCEPTION 'cross_period_invoice' USING ERRCODE = 'P0001';
    END IF;

    UPDATE public.tax_invoices
    SET status = 'cancelled',
        cancelled_at = now(),
        provider_data = COALESCE(provider_data, '{}'::jsonb)
          || jsonb_build_object(
               'cancelled',
               jsonb_build_object('cancel_reason', p_reason, 'source', 'pos_void_paid_order')
             ),
        updated_at = now()
    WHERE id = v_invoice.id;

    INSERT INTO public.tax_invoice_events
      (tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note)
    VALUES (
      v_invoice.id, v_tenant, v_invoice.status, 'cancelled', v_actor,
      jsonb_build_object('cancel_reason', p_reason, 'source', 'pos_void_paid_order'),
      p_reason
    );

    v_invoice_action := CASE
      WHEN v_invoice.status = 'issued' THEN 'cancel_issued'
      ELSE 'cancel_predispatch'
    END;
  END IF;

  -- Money leg: a refund row only when there is money to return
  IF v_payment.amount > 0 THEN
    INSERT INTO public.refunds
      (tenant_id, branch_id, payment_id, order_id, amount, reason,
       status, created_by, approved_by, approved_at, tax_invoice_id)
    VALUES (
      v_tenant, v_payment.branch_id, v_payment.id, p_order_id, v_payment.amount, p_reason,
      'approved', v_actor, v_actor, now(), v_invoice.id
    )
    RETURNING id INTO v_refund_id;
  END IF;

  UPDATE public.payments
  SET status = 'refunded', updated_at = now()
  WHERE id = v_payment.id;

  UPDATE public.orders
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_order_id;

  PERFORM set_config('comtammatu.skip_quota_enforcement', 'true', true);
  UPDATE public.order_items
  SET status = 'cancelled', updated_at = now()
  WHERE order_id = p_order_id
    AND status <> 'cancelled';
  PERFORM set_config('comtammatu.skip_quota_enforcement', 'false', true);

  UPDATE public.kds_tickets
  SET status = 'cancelled', updated_at = now()
  WHERE order_id = p_order_id
    AND status NOT IN ('cancelled', 'served');

  -- Stock restore: post the inverse of this order's sale_consumption rows.
  -- No-op when no consumption was posted (flag was OFF at sale time).
  PERFORM public.post_pos_sale_refund_restore(p_order_id, v_actor);

  PERFORM public.log_audit(
    'refund.pos_void_after_paid',
    'order',
    p_order_id,
    NULL,
    jsonb_build_object(
      'refund_id', v_refund_id,
      'order_id', p_order_id,
      'payment_id', v_payment.id,
      'amount', v_payment.amount,
      'method', v_payment.method,
      'invoice_id', v_invoice.id,
      'invoice_action', v_invoice_action,
      'reason', p_reason
    )
  );

  RETURN jsonb_build_object(
    'status', 'refunded',
    'refund_id', v_refund_id,
    'amount', v_payment.amount,
    'method', v_payment.method,
    'invoice_id', v_invoice.id,
    'invoice_action', v_invoice_action,
    'invoice_provider_ref', v_invoice.provider_ref,
    'invoice_provider', v_invoice.provider
  );
END;
$$;


--
-- Name: refund_paid_order_with_payout(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_paid_order_with_payout(p_order_id bigint, p_reason text, p_payout_method text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_result jsonb;
  v_refund_id bigint;
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_payout_method IS NULL
    OR p_payout_method NOT IN ('cash', 'bank_transfer')
  THEN
    RAISE EXCEPTION 'refund_payout_method_invalid' USING ERRCODE = '22023';
  END IF;

  v_result := public.refund_paid_order(p_order_id, p_reason);
  v_refund_id := NULLIF(v_result->>'refund_id', '')::bigint;

  IF v_refund_id IS NOT NULL THEN
    UPDATE public.refunds
    SET payout_method = p_payout_method,
        updated_at = now()
    WHERE id = v_refund_id
      AND tenant_id = v_tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'refund_not_found' USING ERRCODE = 'P0002';
    END IF;

    PERFORM public.log_audit(
      'refund.payout_method_set',
      'refund',
      v_refund_id,
      NULL,
      jsonb_build_object('payout_method', p_payout_method)
    );
  END IF;

  RETURN v_result || jsonb_build_object('payout_method', p_payout_method);
END;
$$;


--
-- Name: register_branch_presence(bigint, bigint, text, text, inet); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_branch_presence(p_tenant_id bigint, p_branch_id bigint, p_agent_id text, p_token_sha256 text, p_ip_address inet) RETURNS TABLE(ok boolean, status text, ip text, skipped boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now TIMESTAMPTZ := now();
  v_token_id BIGINT;
  v_token_revoked_at TIMESTAMPTZ;
  v_agent_branch_id BIGINT;
  v_existing RECORD;
  v_updated_id BIGINT;
BEGIN
  SELECT id, revoked_at
    INTO v_token_id, v_token_revoked_at
  FROM public.printer_agent_presence_tokens
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND agent_id = p_agent_id
    AND token_sha256 = lower(p_token_sha256)
  FOR UPDATE;

  IF v_token_id IS NULL OR v_token_revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'invalid_token', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  UPDATE public.printer_agent_presence_tokens
  SET last_attempt_at = v_now
  WHERE id = v_token_id
    AND (
      last_attempt_at IS NULL
      OR last_attempt_at <= v_now - INTERVAL '30 seconds'
    )
  RETURNING id INTO v_updated_id;

  IF v_updated_id IS NULL THEN
    RETURN QUERY SELECT false, 'rate_limited', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  SELECT branch_id
    INTO v_agent_branch_id
  FROM public.printer_agents
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND agent_id = p_agent_id;

  IF v_agent_branch_id IS NULL THEN
    RETURN QUERY SELECT false, 'agent_not_registered', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  SELECT id, last_seen_at, revoked_at
    INTO v_existing
  FROM public.branch_trusted_egress_ips
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND ip_address = p_ip_address
  FOR UPDATE;

  IF v_existing.id IS NOT NULL AND v_existing.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'ip_revoked', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  IF v_existing.id IS NOT NULL
     AND v_existing.last_seen_at > v_now - INTERVAL '60 seconds' THEN
    UPDATE public.printer_agent_presence_tokens
    SET last_used_at = v_now
    WHERE id = v_token_id;

    RETURN QUERY SELECT true, 'skipped', p_ip_address::TEXT, true;
    RETURN;
  END IF;

  IF v_existing.id IS NOT NULL THEN
    v_updated_id := NULL;

    UPDATE public.branch_trusted_egress_ips
    SET
      registered_via = 'agent',
      registered_by_agent_id = p_agent_id,
      last_seen_at = v_now
    WHERE id = v_existing.id
      AND revoked_at IS NULL
    RETURNING id INTO v_updated_id;

    IF v_updated_id IS NULL THEN
      RETURN QUERY SELECT false, 'ip_revoked', p_ip_address::TEXT, false;
      RETURN;
    END IF;
  ELSE
    INSERT INTO public.branch_trusted_egress_ips (
      tenant_id,
      branch_id,
      ip_address,
      registered_via,
      registered_by_agent_id,
      last_seen_at
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      p_ip_address,
      'agent',
      p_agent_id,
      v_now
    );
  END IF;

  UPDATE public.printer_agent_presence_tokens
  SET last_used_at = v_now
  WHERE id = v_token_id;

  RETURN QUERY SELECT true, 'ok', p_ip_address::TEXT, false;
END;
$$;


--
-- Name: FUNCTION register_branch_presence(p_tenant_id bigint, p_branch_id bigint, p_agent_id text, p_token_sha256 text, p_ip_address inet); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.register_branch_presence(p_tenant_id bigint, p_branch_id bigint, p_agent_id text, p_token_sha256 text, p_ip_address inet) IS 'Service-role-only atomic branch presence registration. Validates per-agent token hash, rate-limits 1/30s, and never clears revoked trusted IP rows.';


--
-- Name: reject_employee_clock_out(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_employee_clock_out(p_attendance_id bigint, p_note text DEFAULT NULL::text) RETURNS TABLE(branch_id bigint, rejected boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_actor_role text := public.auth_role();
  v_actor_branch_id bigint;
  v_requester_profile_id uuid;
  v_requester_role text;
  v_branch_id bigint;
  v_branch_kind text;
BEGIN
  SELECT profile.branch_id INTO v_actor_branch_id
  FROM public.profiles profile
  WHERE profile.id = v_actor AND profile.tenant_id = v_tenant_id AND profile.is_active;

  SELECT requester.id, private.staff_role_from_position_code(position.code),
         attendance.branch_id, branch.branch_kind
  INTO v_requester_profile_id, v_requester_role, v_branch_id, v_branch_kind
  FROM public.attendance_records attendance
  JOIN public.employees employee
    ON employee.id = attendance.employee_id AND employee.tenant_id = attendance.tenant_id
  JOIN public.profiles requester
    ON requester.id = employee.profile_id AND requester.tenant_id = employee.tenant_id
  JOIN public.positions position
    ON position.id = requester.position_id AND position.tenant_id = requester.tenant_id
  LEFT JOIN public.branches branch
    ON branch.id = attendance.branch_id AND branch.tenant_id = attendance.tenant_id
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = v_tenant_id
    AND attendance.check_out IS NULL
    AND attendance.checkout_requested_at IS NOT NULL
  FOR UPDATE OF attendance;
  IF NOT FOUND OR v_actor IS NULL OR v_requester_profile_id = v_actor THEN
    RAISE EXCEPTION 'checkout_request_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_branch_kind = 'branch'
     AND v_requester_role IN ('cashier', 'chef', 'branch_staff')
     AND v_branch_id IS NOT NULL THEN
    IF v_actor_role <> 'owner'
       AND (v_actor_role <> 'branch_manager' OR v_actor_branch_id IS DISTINCT FROM v_branch_id
            OR NOT public.has_permission(v_branch_id, 'hr:approve_checkout')) THEN
      RAISE EXCEPTION 'checkout_approver_wrong_branch' USING ERRCODE = '42501';
    END IF;
  ELSIF v_actor_role <> 'owner' OR NOT public.auth_is_owner(v_actor) THEN
    RAISE EXCEPTION 'checkout_requires_owner' USING ERRCODE = '42501';
  END IF;

  UPDATE public.attendance_records attendance
  SET checkout_requested_at = NULL,
      checkout_requested_by_role = NULL,
      checkout_approval_target_roles = ARRAY[]::text[],
      checkout_approval_note = NULLIF(btrim(p_note), ''),
      updated_at = now()
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = v_tenant_id
    AND attendance.check_out IS NULL
    AND attendance.checkout_requested_at IS NOT NULL;

  RETURN QUERY SELECT v_branch_id, true;
END;
$$;


--
-- Name: FUNCTION reject_employee_clock_out(p_attendance_id bigint, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reject_employee_clock_out(p_attendance_id bigint, p_note text) IS 'Authenticated checkout rejection using live tenant, branch, position, self-review, and hierarchy checks.';


--
-- Name: reject_leave_request(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_leave_request(p_request_id bigint, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.leave_requests%ROWTYPE;
BEGIN
  IF p_reason IS NOT NULL AND char_length(p_reason) > 500 THEN
    RAISE EXCEPTION 'reject_leave_request: reason too long' USING ERRCODE = '22001';
  END IF;
  v_request := private.authorize_leave_review(p_request_id);
  UPDATE public.leave_requests
  SET status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(),
      rejected_reason = NULLIF(btrim(p_reason), '')
  WHERE id = v_request.id AND status = 'pending';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_request_not_pending' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public.log_audit(
    'reject', 'leave_request', p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'rejected', 'reason', NULLIF(btrim(p_reason), ''))
  );
END;
$$;


--
-- Name: FUNCTION reject_leave_request(p_request_id bigint, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reject_leave_request(p_request_id bigint, p_reason text) IS 'Manager rejects a pending leave_request within branch scope and records an optional reason.';


--
-- Name: reject_refund(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_refund(p_refund_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
BEGIN
  IF v_actor IS NULL
    OR v_tenant_id IS NULL
    OR NOT public.auth_is_owner(v_actor)
  THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.refunds refund
  WHERE refund.id = p_refund_id
    AND refund.tenant_id = v_tenant_id
    AND refund.status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'refund_not_pending' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.refunds
  SET status = 'rejected',
      approved_by = v_actor,
      updated_at = now()
  WHERE id = p_refund_id
    AND tenant_id = v_tenant_id;

  PERFORM public.log_audit(
    'refund.rejected',
    'refund',
    p_refund_id,
    NULL,
    jsonb_build_object('status', 'rejected')
  );

  RETURN jsonb_build_object('refund_id', p_refund_id, 'status', 'rejected');
END;
$$;


--
-- Name: reject_stock_request_lines(bigint, text, bigint[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_stock_request_lines(p_request_id bigint, p_fulfill_site_kind text, p_item_ids bigint[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_actor_kind text;
  v_count integer;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;
  IF p_fulfill_site_kind NOT IN ('central_supply', 'central_kitchen')
     OR p_item_ids IS NULL
     OR cardinality(p_item_ids) = 0 THEN
    RAISE EXCEPTION 'stock_request_reject_invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission_any('inventory:request_fulfill') THEN
    RAISE EXCEPTION 'forbidden_request_fulfill' USING ERRCODE = '42501';
  END IF;

  v_actor_kind := CASE public.auth_role()
    WHEN 'central_supply_ops' THEN 'central_supply'
    WHEN 'central_kitchen_lead' THEN 'central_kitchen'
    ELSE p_fulfill_site_kind
  END;

  IF v_actor_kind IS DISTINCT FROM p_fulfill_site_kind THEN
    RAISE EXCEPTION 'forbidden_request_fulfill_scope'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.stock_requests AS request
  WHERE request.id = p_request_id
    AND request.tenant_id = v_tenant
    AND request.status = 'submitted'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stock_request_not_fulfillable'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.stock_request_items
  SET status = 'rejected',
      notes = concat_ws(E'\n', NULLIF(notes, ''), btrim(p_reason)),
      updated_at = now()
  WHERE request_id = p_request_id
    AND tenant_id = v_tenant
    AND id = ANY (p_item_ids)
    AND fulfill_site_kind = p_fulfill_site_kind
    AND status = 'pending';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> cardinality(p_item_ids) THEN
    RAISE EXCEPTION 'stock_request_lines_not_pending'
      USING ERRCODE = '23514';
  END IF;

  PERFORM public.log_audit(
    'inventory.request.lines_rejected',
    'stock_request',
    p_request_id,
    NULL,
    jsonb_build_object(
      'item_ids', p_item_ids,
      'fulfill_site_kind', p_fulfill_site_kind,
      'reason', btrim(p_reason)
    )
  );

  RETURN jsonb_build_object(
    'request_id', p_request_id,
    'rejected_count', v_count
  );
END;
$$;


--
-- Name: release_branch_menu_daily_holds(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_branch_id bigint := public.auth_branch_id();
  v_role text := public.auth_role();
  v_released integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_hold_token IS NULL THEN
    RAISE EXCEPTION 'hold_token required' USING ERRCODE = '22023';
  END IF;

  IF v_role NOT IN ('owner', 'branch_manager', 'cashier', 'cashier') THEN
    RAISE EXCEPTION 'permission denied: pos daily-limit hold' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('owner')
     AND (v_branch_id IS NULL OR v_branch_id <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  UPDATE public.branch_menu_item_daily_holds h
  SET released_at = now(),
      updated_at = now()
  WHERE h.tenant_id = v_tenant_id
    AND h.branch_id = p_branch_id
    AND h.hold_token = p_hold_token
    AND h.held_by = v_uid
    AND h.committed_at IS NULL
    AND h.released_at IS NULL;

  GET DIAGNOSTICS v_released = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'hold_token', p_hold_token,
    'released_count', v_released
  );
END;
$$;


--
-- Name: FUNCTION release_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.release_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid) IS 'Release active POS daily-limit holds owned by the caller token for a branch.';


--
-- Name: release_table(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_table(p_table_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.tables
  SET status = 'available'
  WHERE id = p_table_id
    AND branch_id = public.auth_branch_id()
    AND tenant_id = public.auth_tenant_id();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Table not found or not in your branch' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: release_zone_lock(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_zone_lock(p_session_id bigint, p_zone_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_branch bigint;
  v_count integer;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT session.branch_id
  INTO v_branch
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_branch,
    'inventory:stocktake_create'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.stocktake_zone_locks
  WHERE tenant_id = v_tenant
    AND session_id = p_session_id
    AND zone_id = p_zone_id
    AND locked_by = v_uid;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN v_count > 0;
END;
$$;


--
-- Name: reopen_period(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_period(p_tenant_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'cross-tenant reopen forbidden' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  UPDATE public.accounting_periods SET soft_closed_at = NULL, hard_closed_at = NULL, closed_by = v_uid
   WHERE tenant_id = p_tenant_id AND year = p_year AND month = p_month;
END; $$;


--
-- Name: replay_signed_sepay_payment_evidence(bigint, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_signed_sepay_payment_evidence(p_event_id bigint, p_payment_id bigint, p_payment_code text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_event public.webhook_events%ROWTYPE;
  v_payment record;
  v_actor_is_owner boolean := false;
  v_raw_amount text;
  v_amount numeric;
  v_payment_code text := btrim(COALESCE(p_payment_code, ''));
  v_result jsonb;
  v_result_payment_id bigint;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_event
  FROM public.webhook_events
  WHERE id = p_event_id
    AND provider = 'sepay'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sepay_replay_event_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.profiles profile
    JOIN public.positions position
      ON position.id = profile.position_id
     AND position.tenant_id = profile.tenant_id
    WHERE profile.id = p_actor_id
      AND profile.tenant_id = v_event.tenant_id
      AND COALESCE(profile.is_active, true)
      AND position.code = 'owner'
  )
  INTO v_actor_is_owner;

  IF NOT v_actor_is_owner THEN
    RAISE EXCEPTION 'sepay_replay_actor_forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT v_event.signature_valid
    OR lower(COALESCE(v_event.payload ->> 'transferType', '')) <> 'in'
    OR v_event.payment_id IS NOT NULL
    OR v_event.expense_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'sepay_replay_event_invalid' USING ERRCODE = '23514';
  END IF;

  IF NOT (
    (
      v_event.processing_status = 'processed'
      AND v_event.error_code IN (
        'missing_payment_code_needs_review',
        'order_not_found_needs_review',
        'ambiguous_payment_code_needs_review',
        'amount_mismatch_needs_review'
      )
    )
    OR (
      v_event.processing_status = 'failed'
      AND COALESCE(v_event.http_status, 0) >= 500
    )
  ) THEN
    RAISE EXCEPTION 'sepay_replay_event_not_recoverable' USING ERRCODE = '23514';
  END IF;

  IF v_payment_code = '' THEN
    RAISE EXCEPTION 'sepay_replay_payment_code_required' USING ERRCODE = '22023';
  END IF;

  v_raw_amount := btrim(COALESCE(v_event.payload ->> 'transferAmount', ''));
  IF v_raw_amount !~ '^[0-9]+([.][0-9]+)?$' THEN
    RAISE EXCEPTION 'sepay_replay_amount_invalid' USING ERRCODE = '22023';
  END IF;

  v_amount := v_raw_amount::numeric;
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'sepay_replay_amount_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT
    payment.id,
    payment.tenant_id,
    payment.branch_id,
    payment.order_id,
    payment.amount,
    payment.provider_ref,
    orders.payment_code,
    orders.total_amount
  INTO v_payment
  FROM public.payments payment
  JOIN public.orders orders
    ON orders.id = payment.order_id
   AND orders.tenant_id = payment.tenant_id
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = v_event.tenant_id
    AND payment.method = 'vietqr'
    AND payment.status = 'pending'
    AND orders.status <> 'cancelled'
  FOR UPDATE OF payment, orders;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sepay_replay_payment_not_pending' USING ERRCODE = 'P0002';
  END IF;

  IF lower(COALESCE(v_payment.payment_code, '')) <> lower(v_payment_code)
    OR lower(COALESCE(v_payment.provider_ref, '')) <> lower(v_payment_code)
  THEN
    RAISE EXCEPTION 'sepay_replay_payment_code_mismatch' USING ERRCODE = '23514';
  END IF;

  IF v_amount <> v_payment.amount OR v_amount <> v_payment.total_amount THEN
    RAISE EXCEPTION 'sepay_replay_amount_mismatch' USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.webhook_events other_event
    WHERE other_event.tenant_id = v_event.tenant_id
      AND other_event.id <> v_event.id
      AND other_event.provider = 'sepay'
      AND other_event.signature_valid
      AND lower(COALESCE(other_event.payload ->> 'transferType', '')) = 'in'
      AND other_event.processing_status = 'processed'
      AND other_event.error_code IS NULL
      AND (
        other_event.payment_id = v_payment.id
        OR other_event.order_id = v_payment.order_id
      )
  ) THEN
    RAISE EXCEPTION 'sepay_replay_payment_already_linked' USING ERRCODE = '23505';
  END IF;

  UPDATE public.webhook_events
  SET processing_status = 'received',
      http_status = NULL,
      error_code = NULL,
      processed_at = NULL
  WHERE id = v_event.id;

  SELECT public.reconcile_sepay_order_evidence(v_event.id, v_payment_code)
  INTO v_result;

  v_result_payment_id := NULLIF(v_result ->> 'payment_id', '')::bigint;
  IF v_result ->> 'status' IS DISTINCT FROM 'matched'
    OR v_result_payment_id IS DISTINCT FROM v_payment.id
  THEN
    RAISE EXCEPTION 'sepay_replay_failed' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.audit_logs (
    tenant_id,
    user_id,
    action,
    entity_type,
    entity_id,
    old_data,
    new_data
  ) VALUES (
    v_event.tenant_id,
    p_actor_id,
    'replay_signed_sepay_payment_evidence',
    'webhook_event',
    v_event.id,
    jsonb_build_object(
      'processing_status', v_event.processing_status,
      'http_status', v_event.http_status,
      'error_code', v_event.error_code,
      'order_id', v_event.order_id,
      'payment_id', v_event.payment_id
    ),
    jsonb_build_object(
      'processing_status', 'processed',
      'http_status', 200,
      'error_code', NULL,
      'order_id', v_payment.order_id,
      'payment_id', v_payment.id
    )
  );

  RETURN v_result || jsonb_build_object('replayed', true);
END;
$_$;


--
-- Name: FUNCTION replay_signed_sepay_payment_evidence(p_event_id bigint, p_payment_id bigint, p_payment_code text, p_actor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replay_signed_sepay_payment_evidence(p_event_id bigint, p_payment_id bigint, p_payment_code text, p_actor_id uuid) IS 'Replays one signed incoming SePay event against its exact pending VietQR payment. The service caller supplies an authenticated Owner actor, which is revalidated and audited in the same transaction.';


--
-- Name: request_inventory_count_recount(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_inventory_count_recount(p_slip_id bigint, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant          BIGINT := public.auth_tenant_id();
  v_uid             UUID   := auth.uid();
  v_slip            public.inventory_count_slips%ROWTYPE;
  v_note            TEXT := NULLIF(trim(COALESCE(p_note, '')), '');
  v_employee_bucket TEXT;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_note IS NOT NULL AND char_length(v_note) > 1000 THEN
    RAISE EXCEPTION 'note_too_long' USING ERRCODE = 'string_data_right_truncation';
  END IF;

  SELECT * INTO v_slip
  FROM public.inventory_count_slips
  WHERE id = p_slip_id AND tenant_id = v_tenant
  FOR UPDATE;

  IF v_slip.id IS NULL THEN
    RAISE EXCEPTION 'slip_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_slip.branch_id, 'inventory:count_approve') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_slip.status <> 'submitted' THEN
    RAISE EXCEPTION 'slip_not_submitted' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = v_slip.employee_id AND e.profile_id = v_uid
  ) THEN
    RAISE EXCEPTION 'cannot_review_own_slip' USING ERRCODE = '42501';
  END IF;

  UPDATE public.inventory_count_slips
  SET status = 'needs_changes', review_note = v_note, reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
  WHERE id = p_slip_id;

  PERFORM public.log_audit(
    'request_recount'::TEXT,
    'inventory_count_slip'::TEXT,
    p_slip_id,
    jsonb_build_object('status', 'submitted'),
    jsonb_build_object('status', 'needs_changes')
  );

  SELECT COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
    INTO v_employee_bucket
    FROM public.employees e
    JOIN public.profiles p ON p.id = e.profile_id AND p.tenant_id = e.tenant_id
    LEFT JOIN public.positions po ON po.id = p.position_id AND po.tenant_id = p.tenant_id
   WHERE e.id = v_slip.employee_id AND e.tenant_id = v_tenant;

  INSERT INTO public.notifications (
    tenant_id, target_branch_id, target_roles, kind, severity, title, body,
    entity_type, entity_id, action_url, meta, dedup_key
  )
  VALUES (
    v_tenant,
    v_slip.branch_id,
    ARRAY[COALESCE(v_employee_bucket, 'unassigned')]::text[],
    'inventory.count_slip_recount',
    'warning',
    'Phiếu đếm tồn cần đếm lại',
    COALESCE(format('Quản lý yêu cầu đếm lại: %s', v_note), 'Quản lý yêu cầu đếm lại phiếu đếm tồn của bạn.'),
    'inventory_count_slip',
    p_slip_id,
    format('/br/%s/stock/count', v_slip.branch_id),
    jsonb_build_object(
      'slip_id', p_slip_id, 'employee_id', v_slip.employee_id,
      'branch_id', v_slip.branch_id, 'result', 'needs_changes'
    ),
    format('inventory.count_slip:%s:recount', p_slip_id)
  )
  ON CONFLICT (tenant_id, dedup_key) WHERE dedup_key IS NOT NULL
  DO UPDATE SET created_at = EXCLUDED.created_at, expires_at = NULL, meta = EXCLUDED.meta;
END;
$$;


--
-- Name: FUNCTION request_inventory_count_recount(p_slip_id bigint, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_inventory_count_recount(p_slip_id bigint, p_note text) IS 'Manager sends a submitted count slip back to needs_changes for recount with an optional note. Branch-scoped, self-review blocked.';


--
-- Name: requeue_tax_invoice_issue_job(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requeue_tax_invoice_issue_job(p_job_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_job public.tax_invoice_issue_jobs%ROWTYPE;
  v_invoice public.tax_invoices%ROWTYPE;
BEGIN
  IF v_actor IS NULL
    OR v_tenant IS NULL
    OR NOT (public.auth_is_owner(v_actor) OR public.has_position('accountant'))
    OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_job
  FROM public.tax_invoice_issue_jobs
  WHERE id = p_job_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND OR v_job.status NOT IN ('blocked', 'reconcile_required') THEN
    RAISE EXCEPTION 'tax_invoice_issue_job_not_requeueable' USING ERRCODE = '22023';
  END IF;

  IF v_job.tax_invoice_id IS NOT NULL THEN
    SELECT * INTO v_invoice FROM public.tax_invoices WHERE id = v_job.tax_invoice_id FOR UPDATE;
    IF NOT FOUND OR v_invoice.status <> 'draft' THEN
      RAISE EXCEPTION 'tax_invoice_issue_job_requires_draft_invoice' USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.tax_invoice_issue_jobs
  SET status = 'queued', locked_until = NULL, last_error = NULL, updated_at = now()
  WHERE id = v_job.id;

  RETURN jsonb_build_object('job_id', v_job.id, 'status', 'queued');
END;
$$;


--
-- Name: reserve_branch_menu_daily_holds(bigint, uuid, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid, p_items jsonb, p_source text DEFAULT 'pos_cart'::text, p_ttl_seconds integer DEFAULT 180) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_branch_id bigint := public.auth_branch_id();
  v_role text := public.auth_role();
  v_limit_date date := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_ttl_seconds integer := LEAST(GREATEST(COALESCE(p_ttl_seconds, 180), 30), 600);
  v_expires_at timestamptz := now() + make_interval(secs => LEAST(GREATEST(COALESCE(p_ttl_seconds, 180), 30), 600));
  v_target record;
  v_limit record;
  v_other_hold_qty integer;
  v_items jsonb := '[]'::jsonb;
  v_released integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_hold_token IS NULL THEN
    RAISE EXCEPTION 'hold_token required' USING ERRCODE = '22023';
  END IF;

  IF p_source NOT IN ('pos_cart', 'pos_append') THEN
    RAISE EXCEPTION 'invalid hold source' USING ERRCODE = '22023';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items must be a JSON array' USING ERRCODE = '22023';
  END IF;

  IF v_role NOT IN ('owner', 'branch_manager', 'cashier', 'cashier') THEN
    RAISE EXCEPTION 'permission denied: pos daily-limit hold' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('owner')
     AND (v_branch_id IS NULL OR v_branch_id <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.branches b
  WHERE b.id = p_branch_id
    AND b.tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.branch_menu_item_daily_holds h
  SET released_at = h.expires_at,
      updated_at = now()
  WHERE h.tenant_id = v_tenant_id
    AND h.branch_id = p_branch_id
    AND h.limit_date = v_limit_date
    AND h.committed_at IS NULL
    AND h.released_at IS NULL
    AND h.expires_at <= now();

  IF jsonb_array_length(p_items) = 0 THEN
    UPDATE public.branch_menu_item_daily_holds h
    SET released_at = now(),
        updated_at = now()
    WHERE h.tenant_id = v_tenant_id
      AND h.branch_id = p_branch_id
      AND h.hold_token = p_hold_token
      AND h.held_by = v_uid
      AND h.committed_at IS NULL
      AND h.released_at IS NULL;

    GET DIAGNOSTICS v_released = ROW_COUNT;

    RETURN jsonb_build_object(
      'success', true,
      'hold_token', p_hold_token,
      'items', '[]'::jsonb,
      'released_count', v_released
    );
  END IF;

  FOR v_target IN
    SELECT *
    FROM public.pos_daily_limit_item_quantities(p_items)
  LOOP
    SELECT * INTO v_limit
    FROM public.branch_menu_item_daily_limits bl
    WHERE bl.tenant_id = v_tenant_id
      AND bl.branch_id = p_branch_id
      AND bl.menu_item_id = v_target.menu_item_id
      AND bl.limit_date = v_limit_date
    FOR UPDATE;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    IF v_limit.is_disabled THEN
      RAISE EXCEPTION 'daily_limit_item_disabled'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_item_disabled',
                'menu_item_id', v_target.menu_item_id
              )::text;
    END IF;

    IF v_limit.limit_quantity IS NULL THEN
      CONTINUE;
    END IF;

    SELECT COALESCE(SUM(h.quantity), 0)::integer
    INTO v_other_hold_qty
    FROM public.branch_menu_item_daily_holds h
    WHERE h.tenant_id = v_tenant_id
      AND h.branch_id = p_branch_id
      AND h.menu_item_id = v_target.menu_item_id
      AND h.limit_date = v_limit_date
      AND h.hold_token <> p_hold_token
      AND h.committed_at IS NULL
      AND h.released_at IS NULL
      AND h.expires_at > now();

    IF v_limit.sold_today + v_other_hold_qty + v_target.quantity > v_limit.limit_quantity THEN
      RAISE EXCEPTION 'daily_limit_exceeded'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_exceeded',
                'menu_item_id', v_target.menu_item_id,
                'limit_quantity', v_limit.limit_quantity,
                'sold_today', v_limit.sold_today,
                'held_quantity', v_other_hold_qty,
                'requested_quantity', v_target.quantity
              )::text;
    END IF;
  END LOOP;

  UPDATE public.branch_menu_item_daily_holds h
  SET released_at = now(),
      updated_at = now()
  WHERE h.tenant_id = v_tenant_id
    AND h.branch_id = p_branch_id
    AND h.hold_token = p_hold_token
    AND h.held_by = v_uid
    AND h.committed_at IS NULL
    AND h.released_at IS NULL;

  WITH requested AS (
    SELECT *
    FROM public.pos_daily_limit_item_quantities(p_items)
  ),
  inserted AS (
    INSERT INTO public.branch_menu_item_daily_holds (
      tenant_id,
      branch_id,
      menu_item_id,
      limit_date,
      hold_token,
      held_by,
      source,
      quantity,
      expires_at
    )
    SELECT
      v_tenant_id,
      p_branch_id,
      r.menu_item_id,
      v_limit_date,
      p_hold_token,
      v_uid,
      p_source,
      r.quantity,
      v_expires_at
    FROM requested r
    JOIN public.branch_menu_item_daily_limits bl
      ON bl.tenant_id = v_tenant_id
     AND bl.branch_id = p_branch_id
     AND bl.menu_item_id = r.menu_item_id
     AND bl.limit_date = v_limit_date
    WHERE bl.limit_quantity IS NOT NULL
      AND bl.is_disabled = false
    RETURNING menu_item_id, quantity, expires_at
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'menu_item_id', inserted.menu_item_id,
        'quantity', inserted.quantity,
        'expires_at', inserted.expires_at
      )
      ORDER BY inserted.menu_item_id
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM inserted;

  RETURN jsonb_build_object(
    'success', true,
    'hold_token', p_hold_token,
    'expires_at', v_expires_at,
    'ttl_seconds', v_ttl_seconds,
    'items', v_items
  );
END;
$$;


--
-- Name: FUNCTION reserve_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid, p_items jsonb, p_source text, p_ttl_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reserve_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid, p_items jsonb, p_source text, p_ttl_seconds integer) IS 'Replace a POS cart daily-limit hold snapshot. Locks limit rows by menu_item_id ASC, excludes the caller token, raises daily_limit_item_disabled / daily_limit_exceeded, and stores short-lived active holds.';


--
-- Name: reserve_tax_invoice_replacement(bigint, text, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_tax_invoice_replacement(p_old_id bigint, p_reason text, p_agreement_ref text, p_agreement_date timestamp with time zone, p_buyer_name text, p_buyer_tax_code text, p_buyer_address text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_old public.tax_invoices%ROWTYPE;
  v_actor uuid := auth.uid();
  v_new_id bigint;
  v_payload jsonb;
  v_payment_id bigint;
BEGIN
  IF v_actor IS NULL
    OR NOT (public.auth_is_owner(v_actor) OR public.has_position('accountant'))
    OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'replacement_forbidden' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_reason), '') IS NULL OR length(btrim(p_reason)) < 20
    OR length(p_reason) > 255
    OR NULLIF(btrim(p_agreement_ref), '') IS NULL
    OR length(p_agreement_ref) > 225 THEN
    RAISE EXCEPTION 'replacement_reference_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_old
  FROM public.tax_invoices
  WHERE id = p_old_id
  FOR UPDATE;
  IF v_old.id IS NULL OR v_old.tenant_id IS DISTINCT FROM public.auth_tenant_id()
    OR v_old.status <> 'issued' OR v_old.replaced_by IS NOT NULL
    OR v_old.invoice_kind <> 'per_order' OR v_old.invoice_snapshot IS NULL THEN
    RAISE EXCEPTION 'replacement_original_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_agreement_date > now()
    OR (v_old.issued_at IS NOT NULL AND p_agreement_date < v_old.issued_at) THEN
    RAISE EXCEPTION 'replacement_agreement_date_invalid'
      USING ERRCODE = '22008';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tax_invoices
    WHERE replaced_for = v_old.id
      AND status IN ('draft', 'signing', 'submitted', 'issued')
  ) THEN
    RAISE EXCEPTION 'replacement_already_pending' USING ERRCODE = '55000';
  END IF;

  v_payload := jsonb_set(
    v_old.invoice_snapshot - 'submissionSnapshot',
    '{draftSnapshot,invoiceTime}',
    to_jsonb(now()),
    true
  ) || jsonb_build_object(
    'buyerName', COALESCE(p_buyer_name, ''),
    'buyerTaxCode', NULLIF(btrim(p_buyer_tax_code), ''),
    'buyerAddress', NULLIF(btrim(p_buyer_address), ''),
    'buyerNotGetInvoice',
      NULLIF(btrim(p_buyer_name), '') IS NULL
      AND NULLIF(btrim(p_buyer_tax_code), '') IS NULL
      AND NULLIF(btrim(p_buyer_address), '') IS NULL,
    'replacement',
      jsonb_build_object(
        'originalInvoiceNumber', v_old.invoice_number,
        'originalIssuedAt', v_old.issued_at,
        'originalInvoiceType', '1',
        'originalTemplateCode', split_part(v_old.template_code, '/', 1),
        'reason', p_reason,
        'agreementRef', p_agreement_ref,
        'agreementDate', p_agreement_date
      )
  );

  INSERT INTO public.tax_invoices (
    tenant_id, branch_id, order_id, status, invoice_kind,
    buyer_name, buyer_tax_code, buyer_address,
    subtotal, vat_rate, vat_amount, total_amount,
    provider, replaced_for, created_by,
    invoice_profile_id, invoice_profile_version, template_code, invoice_series,
    seller_name, seller_tax_code, seller_address, invoice_snapshot
  ) VALUES (
    v_old.tenant_id, v_old.branch_id, v_old.order_id, 'draft', 'per_order',
    p_buyer_name, NULLIF(btrim(p_buyer_tax_code), ''),
    NULLIF(btrim(p_buyer_address), ''),
    v_old.subtotal, NULL, v_old.vat_amount, v_old.total_amount,
    v_old.provider, v_old.id, v_actor,
    v_old.invoice_profile_id, v_old.invoice_profile_version,
    v_old.template_code, v_old.invoice_series,
    v_old.seller_name, v_old.seller_tax_code, v_old.seller_address, v_payload
  ) RETURNING id INTO v_new_id;

  SELECT payment_id INTO v_payment_id
  FROM public.tax_invoice_issue_jobs
  WHERE tax_invoice_id = v_old.id
  ORDER BY id DESC LIMIT 1;

  INSERT INTO public.tax_invoice_issue_jobs (
    tenant_id, branch_id, order_id, payment_id, invoice_payload,
    tax_invoice_id, status, available_at, operation
  ) VALUES (
    v_old.tenant_id, v_old.branch_id, v_old.order_id, v_payment_id, v_payload,
    v_new_id, 'queued', now(), 'replace'
  );

  INSERT INTO public.tax_invoice_events (
    tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note
  ) VALUES (
    v_new_id, v_old.tenant_id, NULL, 'draft', v_actor,
    jsonb_build_object('replaces', v_old.id),
    'Replacement reserved; original remains issued'
  );
  RETURN v_new_id;
END;
$$;


--
-- Name: resolve_branch_printer_for_type(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_branch_printer_for_type(p_tenant_id bigint, p_branch_id bigint, p_print_type text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id
  FROM public.printers p
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = p_print_type
  WHERE p.tenant_id = p_tenant_id
    AND p.branch_id = p_branch_id
    AND (
      auth.role() = 'service_role'
      OR (
        p_tenant_id = public.auth_tenant_id()
        AND (
          public.auth_branch_id() IS NULL
          OR p_branch_id = public.auth_branch_id()
        )
      )
    )
    AND p.is_active = TRUE
  ORDER BY p.sort_order, p.id
  LIMIT 1;
$$;


--
-- Name: resolve_po_price(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_po_price(p_supplier_id bigint, p_ingredient_id bigint, p_uom text) RETURNS TABLE(unit_price numeric, source text, effective_from date, min_order_qty numeric, lead_time_days smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.can_read_inventory_monetary('procurement:price_list_read') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT
    price.unit_price,
    price.source,
    price.effective_from,
    price.min_order_qty,
    price.lead_time_days
  FROM public.supplier_price_list price
  WHERE price.tenant_id = v_tenant
    AND price.supplier_id = p_supplier_id
    AND price.ingredient_id = p_ingredient_id
    AND price.uom = p_uom
    AND price.effective_from <= CURRENT_DATE
    AND (price.effective_to IS NULL OR price.effective_to >= CURRENT_DATE)
  ORDER BY price.priority, price.effective_from DESC
  LIMIT 1;
END;
$$;


--
-- Name: resolve_po_prices_batch(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_po_prices_batch(p_supplier_id bigint, p_items jsonb) RETURNS TABLE(ingredient_id bigint, uom text, unit_price numeric, source text, effective_from date, min_order_qty numeric, lead_time_days smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(NULL, 'procurement:price_list_read') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY
  WITH inputs AS (
    SELECT (v->>'ingredient_id')::BIGINT AS ing_id, (v->>'uom')::TEXT AS u
    FROM jsonb_array_elements(p_items) AS v
  ),
  ranked AS (
    SELECT i.ing_id, i.u, spl.unit_price, spl.source, spl.effective_from, spl.min_order_qty, spl.lead_time_days,
           ROW_NUMBER() OVER (PARTITION BY i.ing_id, i.u ORDER BY spl.priority ASC, spl.effective_from DESC) AS rn
    FROM inputs i
    LEFT JOIN public.supplier_price_list spl
      ON spl.tenant_id = v_tenant AND spl.supplier_id = p_supplier_id
     AND spl.ingredient_id = i.ing_id AND spl.uom = i.u
     AND spl.effective_from <= CURRENT_DATE AND (spl.effective_to IS NULL OR spl.effective_to >= CURRENT_DATE)
  )
  SELECT r.ing_id, r.u, r.unit_price, r.source, r.effective_from, r.min_order_qty, r.lead_time_days
  FROM ranked r WHERE r.rn = 1;
END; $$;


--
-- Name: resolve_pos_session_variance(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_pos_session_variance(p_session_id bigint, p_resolution_type text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_session record;
  v_threshold numeric(15,2);
  v_settlement numeric(15,2);
BEGIN
  IF v_actor IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_resolution_type NOT IN ('staff_repaid', 'accepted_adjustment') THEN
    RAISE EXCEPTION 'invalid_resolution_type' USING ERRCODE = '22023';
  END IF;
  IF p_note IS NULL OR length(btrim(p_note)) < 10 OR length(p_note) > 500 THEN
    RAISE EXCEPTION 'invalid_resolution_note' USING ERRCODE = '22023';
  END IF;

  SELECT ps.*
  INTO v_session
  FROM public.pos_sessions ps
  WHERE ps.id = p_session_id
    AND ps.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_session.branch_id, 'pos:close_shift') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_session.status <> 'closed' THEN
    RAISE EXCEPTION 'session_not_closed' USING ERRCODE = 'P0001';
  END IF;

  v_threshold := GREATEST(
    50000::numeric,
    ROUND(COALESCE(v_session.expected_cash, 0) * 0.005, 2)
  );
  IF v_session.cash_difference IS NULL
     OR abs(v_session.cash_difference) <= v_threshold THEN
    RAISE EXCEPTION 'variance_not_actionable' USING ERRCODE = 'P0001';
  END IF;
  IF v_session.variance_resolution_type IS NOT NULL
     OR v_session.variance_approval_note IS NOT NULL THEN
    RAISE EXCEPTION 'variance_already_resolved' USING ERRCODE = 'P0001';
  END IF;
  IF p_resolution_type = 'staff_repaid'
     AND v_session.cash_difference >= 0 THEN
    RAISE EXCEPTION 'staff_repayment_requires_shortage' USING ERRCODE = '22023';
  END IF;

  v_settlement := CASE
    WHEN p_resolution_type = 'staff_repaid'
      THEN abs(v_session.cash_difference)
    ELSE 0
  END;

  UPDATE public.pos_sessions
  SET
    variance_approval_note = btrim(p_note),
    variance_approver_user_id = v_actor,
    variance_resolution_type = p_resolution_type,
    variance_settlement_amount = v_settlement,
    variance_resolved_at = now(),
    updated_at = now()
  WHERE id = v_session.id;

  PERFORM public.log_audit(
    'pos_session.variance_resolve',
    'pos_session',
    v_session.id,
    jsonb_build_object(
      'cash_difference', v_session.cash_difference,
      'resolution_type', NULL
    ),
    jsonb_build_object(
      'cash_difference', v_session.cash_difference,
      'resolution_type', p_resolution_type,
      'settlement_amount', v_settlement,
      'note', btrim(p_note)
    )
  );

  RETURN jsonb_build_object(
    'session_id', v_session.id,
    'resolution_type', p_resolution_type,
    'settlement_amount', v_settlement,
    'cash_difference', v_session.cash_difference
  );
END;
$$;


--
-- Name: FUNCTION resolve_pos_session_variance(p_session_id bigint, p_resolution_type text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_pos_session_variance(p_session_id bigint, p_resolution_type text, p_note text) IS 'Resolves an over-threshold closed-session variance as a full staff repayment for a shortage or an accepted cash-book adjustment. The original counted cash and difference remain immutable.';


--
-- Name: resolve_print_template_version(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_print_template_version(p_tenant_id bigint, p_branch_id bigint, p_kind text) RETURNS TABLE(template_id bigint, template_version integer, paper_width_mm integer, font_profile text, content jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT pt.id, pt.version, pt.paper_width_mm, pt.font_profile, pt.content
  FROM public.print_template_versions pt
  WHERE pt.is_active = true AND pt.kind = p_kind
    AND (
      (pt.tenant_id = p_tenant_id AND pt.branch_id = p_branch_id)
      OR (pt.tenant_id = p_tenant_id AND pt.branch_id IS NULL)
      OR (pt.tenant_id IS NULL AND pt.branch_id IS NULL)
    )
  ORDER BY
    CASE
      WHEN pt.tenant_id = p_tenant_id AND pt.branch_id = p_branch_id THEN 1
      WHEN pt.tenant_id = p_tenant_id AND pt.branch_id IS NULL THEN 2
      WHEN pt.tenant_id IS NULL AND pt.branch_id IS NULL THEN 3
      ELSE 4
    END,
    pt.version DESC, pt.id DESC
  LIMIT 1;
$$;


--
-- Name: resolve_stocktake_conflict(bigint, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_stocktake_conflict(p_conflict_id bigint, p_resolution text, p_manual_qty numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_conflict public.stocktake_conflicts%ROWTYPE;
  v_session public.stocktake_sessions%ROWTYPE;
  v_session_id bigint;
  v_final_qty numeric;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_resolution NOT IN (
    'keep_server',
    'apply_client',
    'manual_value',
    'reject'
  ) THEN
    RAISE EXCEPTION 'invalid resolution' USING ERRCODE = '22023';
  END IF;

  SELECT conflict.session_id
  INTO v_session_id
  FROM public.stocktake_conflicts AS conflict
  WHERE conflict.id = p_conflict_id
    AND conflict.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'conflict not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT session.*
  INTO v_session
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = v_session_id
    AND session.tenant_id = v_tenant
  FOR UPDATE OF session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_session.branch_id,
    'inventory:stocktake_recount'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_session.status <> 'in_progress' THEN
    RAISE EXCEPTION 'session not in_progress'
      USING ERRCODE = '22023';
  END IF;

  SELECT conflict.*
  INTO v_conflict
  FROM public.stocktake_conflicts AS conflict
  WHERE conflict.id = p_conflict_id
    AND conflict.tenant_id = v_tenant
    AND conflict.session_id = v_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'conflict not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_conflict.resolved_at IS NOT NULL THEN
    RAISE EXCEPTION 'conflict already resolved'
      USING ERRCODE = '22023';
  END IF;

  v_final_qty := CASE p_resolution
    WHEN 'keep_server'
      THEN (v_conflict.server_payload
        ->> 'existing_counted_quantity')::numeric
    WHEN 'apply_client'
      THEN (v_conflict.client_payload ->> 'counted_quantity')::numeric
    WHEN 'manual_value' THEN p_manual_qty
    WHEN 'reject' THEN NULL
  END;

  IF p_resolution = 'manual_value' AND p_manual_qty IS NULL THEN
    RAISE EXCEPTION 'manual_qty required' USING ERRCODE = '22023';
  END IF;
  IF p_resolution <> 'reject'
     AND (
       v_final_qty IS NULL
       OR v_final_qty < 0
       OR v_final_qty = 'NaN'::numeric
       OR v_final_qty = 'Infinity'::numeric
       OR v_final_qty = '-Infinity'::numeric
     ) THEN
    RAISE EXCEPTION 'resolution_quantity_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF p_resolution <> 'reject' AND v_final_qty IS NOT NULL THEN
    UPDATE public.stocktake_lines
    SET counted_quantity = v_final_qty,
        counted_by = v_uid,
        counted_at = now(),
        variance_reason = coalesce(variance_reason, '')
          || E'\n[conflict#'
          || p_conflict_id::text
          || ' resolved='
          || p_resolution
          || coalesce(': ' || p_note, '')
          || ']'
    WHERE tenant_id = v_tenant
      AND session_id = v_conflict.session_id
      AND ingredient_id = v_conflict.ingredient_id
      AND round_no = v_conflict.round_no;
  END IF;

  UPDATE public.stocktake_conflicts
  SET resolved_at = now(),
      resolved_by = v_uid,
      resolution = p_resolution,
      resolution_qty = v_final_qty,
      resolution_note = p_note
  WHERE id = p_conflict_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'conflict_id',
    p_conflict_id,
    'resolution',
    p_resolution,
    'final_qty',
    v_final_qty,
    'resolved_at',
    now()
  );
END;
$$;


--
-- Name: retry_print_job(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_print_job(p_job_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      UUID := auth.uid();
  v_tenant   BIGINT := public.auth_tenant_id();
  v_updated  INT;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant context missing' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_permission_any('printer:manage')
    OR public.has_permission_any('pos:print')
  ) THEN
    RAISE EXCEPTION 'permission denied: printer:manage' USING ERRCODE = '42501';
  END IF;

  UPDATE public.print_jobs
     SET status           = 'pending',
         last_error       = NULL,
         claimed_by_agent = NULL,
         claimed_at       = NULL,
         retry_count      = retry_count + 1,
         last_retried_at  = now(),
         last_retried_by  = v_uid
   WHERE id = p_job_id
     AND tenant_id = v_tenant
     AND status IN ('failed', 'expired');

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated = 1;
END;
$$;


--
-- Name: reverse_payment_and_post(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_payment_and_post(p_refund_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_refund          RECORD;
  v_payment         RECORD;
  v_order           RECORD;
  v_actor           UUID := auth.uid();
  v_tenant          BIGINT := public.auth_tenant_id();
  v_stock_count     INT := 0;
  v_restore_result  jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, payment_id, order_id, amount, status
  INTO v_refund
  FROM public.refunds
  WHERE id = p_refund_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'refund % not found', p_refund_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_refund.branch_id, 'orders:refund_approve') THEN
    RAISE EXCEPTION 'permission denied: orders:refund_approve required'
      USING ERRCODE = '42501';
  END IF;

  IF v_refund.status = 'approved' THEN
    RETURN jsonb_build_object(
      'status', 'already_approved',
      'refund_id', v_refund.id
    );
  END IF;
  IF v_refund.status <> 'pending' THEN
    RAISE EXCEPTION 'refund cannot transition from % to approved', v_refund.status
      USING ERRCODE = 'P0001';
  END IF;

  SELECT id, tenant_id, branch_id, amount, status
  INTO v_payment
  FROM public.payments
  WHERE id = v_refund.payment_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment % not found', v_refund.payment_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_payment.status <> 'completed' THEN
    RAISE EXCEPTION 'payment status=% - refund requires completed',
      v_payment.status USING ERRCODE = 'P0001';
  END IF;
  IF v_refund.amount > v_payment.amount THEN
    RAISE EXCEPTION 'refund amount % exceeds payment amount %',
      v_refund.amount, v_payment.amount USING ERRCODE = 'P0001';
  END IF;

  SELECT id, tenant_id, branch_id, payment_status
  INTO v_order
  FROM public.orders
  WHERE id = v_refund.order_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order % not found', v_refund.order_id
      USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.payments
     SET status = 'refunded', updated_at = now()
   WHERE id = v_payment.id;

  UPDATE public.refunds
     SET status      = 'approved',
         approved_by = v_actor,
         approved_at = now(),
         updated_at  = now()
   WHERE id = v_refund.id;

  -- Stock restore: inverse of this order's sale_consumption rows.
  v_restore_result := public.post_pos_sale_refund_restore(v_refund.order_id, v_actor);
  IF v_restore_result ? 'movements_created' THEN
    v_stock_count := COALESCE((v_restore_result ->> 'movements_created')::int, 0);
  END IF;

  PERFORM public.log_audit(
    'refund.approve',
    'refund',
    v_refund.id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object(
      'status', 'approved',
      'stock_movements_created', v_stock_count
    )
  );

  RETURN jsonb_build_object(
    'status', 'approved',
    'refund_id', v_refund.id,
    'stock_movements_created', v_stock_count,
    'payment_new_status', 'refunded'
  );
END;
$$;


--
-- Name: FUNCTION reverse_payment_and_post(p_refund_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reverse_payment_and_post(p_refund_id bigint) IS 'Atomic refund reversal with branch-scoped orders:refund_approve permission. Locks refund/payment/order, flips payment and refund, and audits. orders.payment_status intentionally stays ''paid'' (CHECK allows unpaid/pending/paid only; partial refunds make an order-level refunded label wrong) — refund truth = payments.status + refunds.';


--
-- Name: review_completed_vietqr_bank_webhook(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_completed_vietqr_bank_webhook(p_payment_id bigint, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_payment public.payments%ROWTYPE;
  v_old_review jsonb;
  v_new_review jsonb;
  v_provider_data jsonb;
BEGIN
  IF v_actor IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.auth_is_owner(v_actor) THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF p_status IS NULL
    OR p_status NOT IN ('reviewing', 'resolved', 'ignored')
  THEN
    RAISE EXCEPTION 'invalid_review_status' USING ERRCODE = '22023';
  END IF;

  SELECT payment.*
  INTO v_payment
  FROM public.payments payment
  WHERE payment.id = p_payment_id
    AND payment.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_payment.branch_id, 'finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_payment.method <> 'vietqr' OR v_payment.status <> 'completed' THEN
    RAISE EXCEPTION 'payment_not_reviewable' USING ERRCODE = '23514';
  END IF;

  v_provider_data := CASE
    WHEN jsonb_typeof(v_payment.provider_data) = 'object'
      THEN v_payment.provider_data
    ELSE '{}'::jsonb
  END;
  v_old_review := v_provider_data -> 'bankWebhookReview';
  v_new_review := jsonb_build_object(
    'status', p_status,
    'reviewedAt', now(),
    'reviewedBy', v_actor
  );

  UPDATE public.payments
  SET provider_data = v_provider_data || jsonb_build_object(
        'bankWebhookReview',
        v_new_review
      ),
      updated_at = now()
  WHERE id = v_payment.id;

  PERFORM public.log_audit(
    'update_bank_webhook_review',
    'payment',
    v_payment.id,
    jsonb_build_object('bankWebhookReview', v_old_review),
    jsonb_build_object('bankWebhookReview', v_new_review)
  );

  RETURN jsonb_build_object(
    'payment_id', v_payment.id,
    'bank_webhook_review', v_new_review
  );
END;
$$;


--
-- Name: FUNCTION review_completed_vietqr_bank_webhook(p_payment_id bigint, p_status text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.review_completed_vietqr_bank_webhook(p_payment_id bigint, p_status text) IS 'Owner-only atomic review marker and audit append for a completed VietQR payment missing bank evidence.';


--
-- Name: review_purchase_demand(bigint, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_purchase_demand(p_demand_id bigint, p_action text, p_allocations jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_demand public.purchase_requests%ROWTYPE;
  v_action text :=
    pg_catalog.lower(pg_catalog.btrim(coalesce(p_action, '')));
  v_reason text :=
    nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_group_key uuid;
  v_group_code text;
  v_max_sequence integer := 0;
  v_sequence integer;
  v_supplier record;
  v_po_id bigint;
  v_status text;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_action NOT IN ('approve', 'request_changes', 'reject') THEN
    RAISE EXCEPTION 'purchase_demand_review_action_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF v_action IN ('request_changes', 'reject')
     AND pg_catalog.length(coalesce(v_reason, '')) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT demand.*
  INTO v_demand
  FROM public.purchase_requests AS demand
  WHERE demand.id = p_demand_id
    AND demand.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_demand_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_demand.branch_id,
    'procurement:po_approve'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_action = 'approve' AND p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'purchase_demand_idempotency_required'
      USING ERRCODE = '22023';
  END IF;

  IF v_action = 'approve' THEN
    SELECT purchase_order.purchase_group_key
    INTO v_group_key
    FROM public.purchase_orders AS purchase_order
    WHERE purchase_order.tenant_id = v_tenant
      AND purchase_order.purchase_request_id = p_demand_id
      AND purchase_order.group_save_idempotency_key = p_idempotency_key
    ORDER BY purchase_order.group_sequence
    LIMIT 1;

    IF FOUND THEN
      SELECT pg_catalog.jsonb_build_object(
        'demand_id', p_demand_id,
        'status', v_demand.status,
        'purchase_group_key', v_group_key,
        'purchase_group_code',
          pg_catalog.min(purchase_order.purchase_group_code),
        'purchase_orders',
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'po_id', purchase_order.id,
              'po_number',
                coalesce(
                  purchase_order.display_id,
                  purchase_order.po_number
                ),
              'supplier_id', purchase_order.supplier_id,
              'status', purchase_order.status
            )
            ORDER BY purchase_order.group_sequence
          )
      )
      INTO v_result
      FROM public.purchase_orders AS purchase_order
      WHERE purchase_order.tenant_id = v_tenant
        AND purchase_order.purchase_request_id = p_demand_id
        AND purchase_order.group_save_idempotency_key = p_idempotency_key;
      RETURN v_result;
    END IF;
  END IF;

  IF v_action IN ('request_changes', 'reject') THEN
    IF v_demand.status NOT IN ('submitted', 'pending_allocation')
       OR EXISTS (
         SELECT 1
         FROM public.purchase_orders AS purchase_order
         WHERE purchase_order.tenant_id = v_tenant
           AND purchase_order.purchase_request_id = p_demand_id
           AND purchase_order.status <> 'cancelled'
       ) THEN
      RAISE EXCEPTION 'purchase_demand_not_reviewable'
        USING ERRCODE = '23514';
    END IF;

    v_status := CASE
      WHEN v_action = 'request_changes' THEN 'changes_requested'
      ELSE 'cancelled'
    END;
    UPDATE public.purchase_requests
    SET status = v_status,
        status_reason = v_reason,
        cancelled_at = CASE
          WHEN v_action = 'reject' THEN pg_catalog.now()
          ELSE cancelled_at
        END,
        updated_at = pg_catalog.now()
    WHERE id = p_demand_id
      AND tenant_id = v_tenant;

    PERFORM public.log_audit(
      'procurement.demand.' || v_action,
      'purchase_request',
      p_demand_id,
      pg_catalog.to_jsonb(v_demand),
      pg_catalog.jsonb_build_object(
        'status', v_status,
        'reason', v_reason
      )
    );

    RETURN pg_catalog.jsonb_build_object(
      'demand_id', p_demand_id,
      'status', v_status
    );
  END IF;

  IF v_demand.status NOT IN (
    'submitted',
    'pending_allocation',
    'partially_ordered'
  ) THEN
    RAISE EXCEPTION 'purchase_demand_not_reviewable'
      USING ERRCODE = '23514';
  END IF;

  IF p_allocations IS NOT NULL THEN
    PERFORM public.save_purchase_demand_allocations(
      p_demand_id,
      p_allocations,
      p_idempotency_key
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.purchase_request_items AS demand_item
    LEFT JOIN LATERAL (
      SELECT coalesce(
        pg_catalog.sum(allocation.quantity),
        0
      ) AS quantity
      FROM public.purchase_request_allocations AS allocation
      WHERE allocation.tenant_id = v_tenant
        AND allocation.purchase_request_id = p_demand_id
        AND allocation.purchase_request_item_id = demand_item.id
    ) AS planned ON TRUE
    WHERE demand_item.tenant_id = v_tenant
      AND demand_item.purchase_request_id = p_demand_id
      AND planned.quantity IS DISTINCT FROM
        private.purchase_request_item_remaining_demand_qty(
          v_tenant,
          demand_item.id
        )
  ) THEN
    RAISE EXCEPTION 'purchase_demand_allocation_incomplete'
      USING ERRCODE = '23514';
  END IF;

  PERFORM 1
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.tenant_id = v_tenant
    AND purchase_order.purchase_request_id = p_demand_id
  FOR UPDATE;

  SELECT
    purchase_order.purchase_group_key,
    purchase_order.purchase_group_code,
    coalesce(
      pg_catalog.max(purchase_order.group_sequence),
      0
    )
  INTO v_group_key, v_group_code, v_max_sequence
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.tenant_id = v_tenant
    AND purchase_order.purchase_request_id = p_demand_id
    AND purchase_order.purchase_group_key IS NOT NULL
  GROUP BY
    purchase_order.purchase_group_key,
    purchase_order.purchase_group_code
  ORDER BY pg_catalog.max(purchase_order.group_sequence) DESC
  LIMIT 1;

  IF v_group_key IS NULL THEN
    v_group_key := pg_catalog.gen_random_uuid();
    v_group_code := public.next_po_display_id(v_tenant);
    v_max_sequence := 0;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.purchase_request_allocations AS allocation
    JOIN public.purchase_request_items AS demand_item
      ON demand_item.id = allocation.purchase_request_item_id
     AND demand_item.tenant_id = allocation.tenant_id
     AND demand_item.purchase_request_id = allocation.purchase_request_id
    LEFT JOIN public.ingredients AS ingredient
      ON ingredient.id = demand_item.ingredient_id
     AND ingredient.tenant_id = demand_item.tenant_id
    LEFT JOIN public.ingredient_units AS request_unit
      ON request_unit.tenant_id = demand_item.tenant_id
     AND request_unit.ingredient_id = demand_item.ingredient_id
     AND request_unit.unit_id = demand_item.entry_unit_id
    LEFT JOIN public.ingredient_units AS receipt_unit
      ON receipt_unit.tenant_id = ingredient.tenant_id
     AND receipt_unit.ingredient_id = ingredient.id
     AND receipt_unit.unit_id = ingredient.receipt_unit_id
    WHERE allocation.tenant_id = v_tenant
      AND allocation.purchase_request_id = p_demand_id
      AND (
        ingredient.id IS NULL
        OR ingredient.receipt_unit_id IS NULL
        OR request_unit.unit_id IS NULL
        OR receipt_unit.unit_id IS NULL
        OR receipt_unit.is_active IS NOT TRUE
        OR request_unit.to_base_factor <= 0
        OR receipt_unit.to_base_factor <= 0
        OR allocation.quantity * request_unit.to_base_factor
          / receipt_unit.to_base_factor
          <> pg_catalog.round(
            allocation.quantity * request_unit.to_base_factor
              / receipt_unit.to_base_factor,
            3
          )
      )
  ) THEN
    RAISE EXCEPTION 'purchase_demand_receipt_unit_conversion_invalid'
      USING ERRCODE = '23514';
  END IF;

  FOR v_supplier IN
    SELECT
      allocation.supplier_id,
      pg_catalog.row_number() OVER (
        ORDER BY allocation.supplier_id
      )::integer AS ordinal
    FROM public.purchase_request_allocations AS allocation
    WHERE allocation.tenant_id = v_tenant
      AND allocation.purchase_request_id = p_demand_id
    GROUP BY allocation.supplier_id
    ORDER BY allocation.supplier_id
  LOOP
    v_sequence := v_max_sequence + v_supplier.ordinal;
    IF v_sequence > 99 THEN
      RAISE EXCEPTION 'purchase_order_group_supplier_limit'
        USING ERRCODE = '54000';
    END IF;

    INSERT INTO public.purchase_orders (
      tenant_id,
      branch_id,
      supplier_id,
      purchase_request_id,
      po_number,
      display_id,
      status,
      ordered_at,
      expected_delivery_date,
      notes,
      created_by,
      purchase_group_key,
      purchase_group_code,
      group_sequence,
      group_save_idempotency_key,
      submitted_at,
      submitted_by
    )
    VALUES (
      v_tenant,
      v_demand.branch_id,
      v_supplier.supplier_id,
      p_demand_id,
      v_group_code || '-' ||
        pg_catalog.lpad(v_sequence::text, 2, '0'),
      v_group_code || '-' ||
        pg_catalog.lpad(v_sequence::text, 2, '0'),
      'pending_approval',
      pg_catalog.now(),
      v_demand.needed_by,
      v_demand.notes,
      v_uid,
      v_group_key,
      v_group_code,
      v_sequence,
      p_idempotency_key,
      pg_catalog.now(),
      v_uid
    )
    RETURNING id INTO v_po_id;

    INSERT INTO public.purchase_order_items (
      tenant_id,
      po_id,
      purchase_request_item_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      unit_price_est,
      line_total
    )
    SELECT
      v_tenant,
      v_po_id,
      demand_item.id,
      demand_item.ingredient_id,
      allocation.quantity * request_unit.to_base_factor / receipt_unit.to_base_factor,
      ingredient.receipt_unit_id,
      NULL,
      NULL
    FROM public.purchase_request_allocations AS allocation
    JOIN public.purchase_request_items AS demand_item
      ON demand_item.id = allocation.purchase_request_item_id
     AND demand_item.tenant_id = allocation.tenant_id
     AND demand_item.purchase_request_id = allocation.purchase_request_id
    JOIN public.ingredients AS ingredient
      ON ingredient.id = demand_item.ingredient_id
     AND ingredient.tenant_id = demand_item.tenant_id
    JOIN public.ingredient_units AS request_unit
      ON request_unit.tenant_id = demand_item.tenant_id
     AND request_unit.ingredient_id = demand_item.ingredient_id
     AND request_unit.unit_id = demand_item.entry_unit_id
    JOIN public.ingredient_units AS receipt_unit
      ON receipt_unit.tenant_id = ingredient.tenant_id
     AND receipt_unit.ingredient_id = ingredient.id
     AND receipt_unit.unit_id = ingredient.receipt_unit_id
    WHERE allocation.tenant_id = v_tenant
      AND allocation.purchase_request_id = p_demand_id
      AND allocation.supplier_id = v_supplier.supplier_id
    ORDER BY demand_item.id;

    UPDATE public.purchase_orders
    SET status = 'approved',
        reviewed_at = pg_catalog.now(),
        reviewed_by = v_uid,
        updated_at = pg_catalog.now()
    WHERE id = v_po_id
      AND tenant_id = v_tenant;
  END LOOP;

  v_status := private.recompute_purchase_request_status(
    p_demand_id,
    v_tenant
  );

  SELECT pg_catalog.jsonb_build_object(
    'demand_id', p_demand_id,
    'status', v_status,
    'purchase_group_key', v_group_key,
    'purchase_group_code', v_group_code,
    'purchase_orders',
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'po_id', purchase_order.id,
          'po_number',
            coalesce(
              purchase_order.display_id,
              purchase_order.po_number
            ),
          'supplier_id', purchase_order.supplier_id,
          'status', purchase_order.status
        )
        ORDER BY purchase_order.group_sequence
      )
  )
  INTO v_result
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.tenant_id = v_tenant
    AND purchase_order.purchase_request_id = p_demand_id
    AND purchase_order.group_save_idempotency_key = p_idempotency_key;

  PERFORM public.log_audit(
    'procurement.demand.approved',
    'purchase_request',
    p_demand_id,
    pg_catalog.to_jsonb(v_demand),
    v_result
  );

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION review_purchase_demand(p_demand_id bigint, p_action text, p_allocations jsonb, p_reason text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.review_purchase_demand(p_demand_id bigint, p_action text, p_allocations jsonb, p_reason text, p_idempotency_key uuid) IS 'Reviews demand and atomically creates approved supplier POs and GRN drafts.';


--
-- Name: review_purchase_order(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_purchase_order(p_po_id bigint, p_action text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_po public.purchase_orders%ROWTYPE;
  v_action text :=
    pg_catalog.lower(pg_catalog.btrim(coalesce(p_action, '')));
  v_reason text := nullif(
    pg_catalog.btrim(coalesce(p_reason, '')),
    ''
  );
  v_grn jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_action NOT IN ('approve', 'request_changes', 'reject') THEN
    RAISE EXCEPTION 'purchase_order_review_action_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF v_action IN ('request_changes', 'reject')
     AND pg_catalog.length(coalesce(v_reason, '')) < 5 THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT po.*
  INTO v_po
  FROM public.purchase_orders AS po
  WHERE po.id = p_po_id
    AND po.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_po.branch_id,
    'procurement:po_approve'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_action = 'approve'
     AND v_po.status IN (
       'approved',
       'partially_received',
       'received',
       'closed'
     ) THEN
    SELECT pg_catalog.jsonb_build_object(
      'grn_id', grn.id,
      'grn_number', grn.grn_number,
      'status', grn.status
    )
    INTO v_grn
    FROM public.goods_received_notes AS grn
    WHERE grn.tenant_id = v_tenant
      AND grn.po_id = p_po_id
    ORDER BY (grn.status = 'draft') DESC, grn.id DESC
    LIMIT 1;

    RETURN pg_catalog.jsonb_build_object(
      'po_id', p_po_id,
      'status', v_po.status,
      'grn', v_grn
    );
  END IF;
  IF v_po.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'purchase_order_not_reviewable'
      USING ERRCODE = '23514';
  END IF;

  IF v_action = 'approve' THEN
    UPDATE public.purchase_orders
    SET status = 'approved',
        status_reason = NULL,
        reviewed_at = pg_catalog.now(),
        reviewed_by = v_uid,
        updated_at = pg_catalog.now()
    WHERE id = p_po_id
      AND tenant_id = v_tenant;

    v_grn := private.ensure_grn_draft_for_po(
      v_tenant,
      p_po_id,
      v_uid,
      pg_catalog.gen_random_uuid()
    );
  ELSIF v_action = 'request_changes' THEN
    UPDATE public.purchase_orders
    SET status = 'changes_requested',
        status_reason = v_reason,
        reviewed_at = pg_catalog.now(),
        reviewed_by = v_uid,
        updated_at = pg_catalog.now()
    WHERE id = p_po_id
      AND tenant_id = v_tenant;
  ELSE
    UPDATE public.purchase_orders
    SET status = 'cancelled',
        status_reason = v_reason,
        reviewed_at = pg_catalog.now(),
        reviewed_by = v_uid,
        cancelled_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    WHERE id = p_po_id
      AND tenant_id = v_tenant;
  END IF;

  PERFORM public.log_audit(
    'procurement.po.' || v_action,
    'purchase_order',
    p_po_id,
    pg_catalog.to_jsonb(v_po),
    pg_catalog.jsonb_build_object(
      'status',
      CASE v_action
        WHEN 'approve' THEN 'approved'
        WHEN 'request_changes' THEN 'changes_requested'
        ELSE 'cancelled'
      END,
      'reason',
      v_reason,
      'grn',
      v_grn
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'po_id', p_po_id,
    'status',
    CASE v_action
      WHEN 'approve' THEN 'approved'
      WHEN 'request_changes' THEN 'changes_requested'
      ELSE 'cancelled'
    END,
    'grn',
    v_grn
  );
END;
$$;


--
-- Name: FUNCTION review_purchase_order(p_po_id bigint, p_action text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.review_purchase_order(p_po_id bigint, p_action text, p_reason text) IS 'Approves, returns, or rejects a pending PO. Approval creates exactly one active draft GRN in the same transaction.';


--
-- Name: revoke_permission(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_permission(p_target_user uuid, p_branch_id bigint, p_permission_key text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT;
  v_target_tenant BIGINT;
  v_deleted INTEGER;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'staff:assign_permission') THEN
    RAISE EXCEPTION 'forbidden: missing staff:assign_permission' USING ERRCODE = '42501';
  END IF;

  IF p_target_user = auth.uid() THEN
    RAISE EXCEPTION 'cannot_self_assign_permissions' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.profiles WHERE id = auth.uid();
  SELECT tenant_id INTO v_target_tenant FROM public.profiles WHERE id = p_target_user;
  IF v_target_tenant IS NULL OR v_target_tenant <> v_tenant_id THEN
    RAISE EXCEPTION 'target_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF public.auth_is_owner(p_target_user) THEN
    RAISE EXCEPTION 'cannot_manage_owner_permissions' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.staff_permissions
  WHERE user_id = p_target_user
    AND permission_key = p_permission_key
    AND (
      (p_branch_id IS NULL AND branch_id IS NULL)
      OR branch_id = p_branch_id
    );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted > 0 THEN
    INSERT INTO public.permission_audit_log (
      tenant_id, actor_user_id, target_user_id, branch_id,
      permission_key, action
    ) VALUES (
      v_tenant_id, auth.uid(), p_target_user, p_branch_id,
      p_permission_key, 'revoke'
    );
  END IF;

  RETURN v_deleted;
END;
$$;


--
-- Name: rotate_table_self_order_qr(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_table_self_order_qr(p_table_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_table record;
  v_token text;
  v_rotated_at timestamptz := now();
BEGIN
  IF v_uid IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('self-order-table'),
    hashtext(p_table_id::text)
  );

  SELECT t.*
  INTO v_table
  FROM public.tables t
  WHERE t.id = p_table_id
    AND t.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_table_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_table.branch_id, 'settings:branch') THEN
    RAISE EXCEPTION 'permission denied: settings:branch' USING ERRCODE = '42501';
  END IF;

  v_token := translate(
    encode(extensions.gen_random_bytes(24), 'base64'),
    '+/=',
    '-_'
  );

  UPDATE public.tables
  SET self_order_token = v_token,
      self_order_enabled = true,
      self_order_token_rotated_at = v_rotated_at
  WHERE id = v_table.id
    AND tenant_id = v_table.tenant_id;

  RETURN jsonb_build_object(
    'token', v_token,
    'enabled', true,
    'rotatedAt', v_rotated_at
  );
END;
$$;


--
-- Name: route_order_to_kds(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_order_to_kds(p_order_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_order RECORD;
  v_item RECORD;
  v_station_id BIGINT;
  v_has_printer_route BOOLEAN := FALSE;
  v_batch_id BIGINT;
  v_send_seq INT;
  v_ticket_seq INT;
  v_order_number_clean TEXT;
  v_order_number_match TEXT[];
  v_ticket_base TEXT;
  v_ticket_number TEXT;
  v_ticket_id BIGINT;
  v_table_no INT;
  v_cashier_name TEXT;
  v_route RECORD;
  v_payload JSONB;
  v_idempotency TEXT;
  v_job_id BIGINT;
  v_unrouted INT;
BEGIN
  SELECT tenant_id, branch_id, order_number, order_type, note, created_by,
         table_id, kitchen_send_count
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = public.auth_tenant_id()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  FOR v_item IN
    SELECT oi.id AS order_item_id, mi.category_id
    FROM public.order_items oi
    JOIN public.menu_items mi
      ON mi.id = oi.menu_item_id
     AND mi.tenant_id = oi.tenant_id
    WHERE oi.order_id = p_order_id
      AND oi.sent_to_kitchen_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.kds_tickets kt
        WHERE kt.tenant_id = v_order.tenant_id
          AND kt.order_item_id = oi.id
      )
    ORDER BY oi.id
  LOOP
    v_station_id := NULL;
    v_has_printer_route := FALSE;

    SELECT sc.station_id INTO v_station_id
    FROM public.kds_station_categories sc
    JOIN public.kds_stations s ON s.id = sc.station_id
    WHERE sc.category_id = v_item.category_id
      AND s.branch_id = v_order.branch_id
      AND s.tenant_id = v_order.tenant_id
      AND s.is_active = TRUE
    ORDER BY s.position, s.id
    LIMIT 1;

    SELECT EXISTS (
      SELECT 1
      FROM public.printers p
      JOIN public.printer_print_types ppt
        ON ppt.printer_id = p.id
       AND ppt.tenant_id = p.tenant_id
       AND ppt.branch_id = p.branch_id
       AND ppt.print_type = 'kitchen_ticket'
      LEFT JOIN public.printer_menu_categories pmc
        ON pmc.printer_id = p.id
       AND pmc.tenant_id = p.tenant_id
       AND pmc.branch_id = p.branch_id
       AND pmc.category_id = v_item.category_id
      WHERE p.tenant_id = v_order.tenant_id
        AND p.branch_id = v_order.branch_id
        AND p.is_active = TRUE
        AND (
          pmc.id IS NOT NULL
          OR NOT EXISTS (
            SELECT 1
            FROM public.printer_menu_categories pmc_any
            WHERE pmc_any.tenant_id = v_order.tenant_id
              AND pmc_any.branch_id = v_order.branch_id
              AND pmc_any.category_id = v_item.category_id
          )
        )
    ) INTO v_has_printer_route;

    IF v_station_id IS NULL AND v_has_printer_route THEN
      CONTINUE;
    END IF;

    IF v_station_id IS NOT NULL THEN
      IF v_batch_id IS NULL THEN
        UPDATE public.orders
           SET kitchen_send_count = kitchen_send_count + 1
         WHERE id = p_order_id
         RETURNING kitchen_send_count INTO v_send_seq;

        INSERT INTO public.kitchen_daily_counters (
          tenant_id, branch_id, counter_date, last_seq
        )
        VALUES (
          v_order.tenant_id,
          v_order.branch_id,
          (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
          1
        )
        ON CONFLICT (tenant_id, branch_id, counter_date)
        DO UPDATE SET
          last_seq = public.kitchen_daily_counters.last_seq + 1,
          updated_at = now()
        RETURNING last_seq INTO v_ticket_seq;

        v_order_number_clean := regexp_replace(
          btrim(COALESCE(v_order.order_number, '')),
          '^#+',
          ''
        );
        v_order_number_match := regexp_match(
          v_order_number_clean,
          '^(?:TC|MV)-(?:(?:[0-9]{6}|[0-9]{8})-)?([0-9]{1,5})(?:-.+)?$',
          'i'
        );
        v_ticket_base := COALESCE(
          v_order_number_match[1],
          NULLIF(v_order_number_clean, ''),
          p_order_id::TEXT
        );
        v_ticket_number := '#' || v_ticket_base
          || CASE WHEN v_send_seq > 1 THEN '-' || v_send_seq::TEXT ELSE '' END;

        INSERT INTO public.kitchen_send_batches (
          tenant_id, branch_id, order_id, counter_date, ticket_seq,
          kitchen_ticket_number, send_seq, kind, created_by
        )
        VALUES (
          v_order.tenant_id,
          v_order.branch_id,
          p_order_id,
          (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
          v_ticket_seq,
          v_ticket_number,
          v_send_seq,
          CASE WHEN v_send_seq = 1 THEN 'initial' ELSE 'append' END,
          auth.uid()
        )
        RETURNING id INTO v_batch_id;
      END IF;

      INSERT INTO public.kds_tickets (
        tenant_id, branch_id, station_id, order_id, order_item_id,
        kitchen_send_batch_id
      )
      VALUES (
        v_order.tenant_id, v_order.branch_id, v_station_id,
        p_order_id, v_item.order_item_id, v_batch_id
      )
      ON CONFLICT (order_item_id, station_id, tenant_id) DO NOTHING
      RETURNING id INTO v_ticket_id;
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.order_items oi
    JOIN public.menu_items mi
      ON mi.id = oi.menu_item_id
     AND mi.tenant_id = oi.tenant_id
    JOIN LATERAL (
      SELECT p.id AS printer_id
      FROM public.printers p
      JOIN public.printer_print_types ppt
        ON ppt.printer_id = p.id
       AND ppt.tenant_id = p.tenant_id
       AND ppt.branch_id = p.branch_id
       AND ppt.print_type = 'kitchen_ticket'
      LEFT JOIN public.printer_menu_categories pmc
        ON pmc.printer_id = p.id
       AND pmc.tenant_id = p.tenant_id
       AND pmc.branch_id = p.branch_id
       AND pmc.category_id = mi.category_id
      WHERE p.tenant_id = v_order.tenant_id
        AND p.branch_id = v_order.branch_id
        AND p.is_active = TRUE
        AND (
          pmc.id IS NOT NULL
          OR NOT EXISTS (
            SELECT 1
            FROM public.printer_menu_categories pmc_any
            WHERE pmc_any.tenant_id = v_order.tenant_id
              AND pmc_any.branch_id = v_order.branch_id
              AND pmc_any.category_id = mi.category_id
          )
        )
      ORDER BY
        CASE WHEN pmc.id IS NOT NULL THEN 0 ELSE 1 END,
        p.sort_order, p.id
      LIMIT 1
    ) pr ON TRUE
    WHERE oi.order_id = p_order_id
      AND oi.sent_to_kitchen_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.kds_tickets kt
        WHERE kt.tenant_id = v_order.tenant_id
          AND kt.order_item_id = oi.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.kds_station_categories sc
        JOIN public.kds_stations s ON s.id = sc.station_id
        WHERE sc.category_id = mi.category_id
          AND s.branch_id = v_order.branch_id
          AND s.tenant_id = v_order.tenant_id
          AND s.is_active = TRUE
      )
    LIMIT 1
  ) THEN
    IF v_batch_id IS NULL THEN
      UPDATE public.orders
         SET kitchen_send_count = kitchen_send_count + 1
       WHERE id = p_order_id
       RETURNING kitchen_send_count INTO v_send_seq;

      INSERT INTO public.kitchen_daily_counters (
        tenant_id, branch_id, counter_date, last_seq
      )
      VALUES (
        v_order.tenant_id,
        v_order.branch_id,
        (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
        1
      )
      ON CONFLICT (tenant_id, branch_id, counter_date)
      DO UPDATE SET
        last_seq = public.kitchen_daily_counters.last_seq + 1,
        updated_at = now()
      RETURNING last_seq INTO v_ticket_seq;

      v_order_number_clean := regexp_replace(
        btrim(COALESCE(v_order.order_number, '')),
        '^#+',
        ''
      );
      v_order_number_match := regexp_match(
        v_order_number_clean,
        '^(?:TC|MV)-(?:(?:[0-9]{6}|[0-9]{8})-)?([0-9]{1,5})(?:-.+)?$',
        'i'
      );
      v_ticket_base := COALESCE(
        v_order_number_match[1],
        NULLIF(v_order_number_clean, ''),
        p_order_id::TEXT
      );
      v_ticket_number := '#' || v_ticket_base
        || CASE WHEN v_send_seq > 1 THEN '-' || v_send_seq::TEXT ELSE '' END;

      INSERT INTO public.kitchen_send_batches (
        tenant_id, branch_id, order_id, counter_date, ticket_seq,
        kitchen_ticket_number, send_seq, kind, created_by
      )
      VALUES (
        v_order.tenant_id,
        v_order.branch_id,
        p_order_id,
        (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
        v_ticket_seq,
        v_ticket_number,
        v_send_seq,
        CASE WHEN v_send_seq = 1 THEN 'initial' ELSE 'append' END,
        auth.uid()
      )
      RETURNING id INTO v_batch_id;
    ELSE
      SELECT kitchen_ticket_number, send_seq
        INTO v_ticket_number, v_send_seq
      FROM public.kitchen_send_batches
      WHERE id = v_batch_id;
    END IF;

    IF v_order.table_id IS NOT NULL THEN
      SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
    END IF;

    SELECT full_name INTO v_cashier_name
    FROM public.profiles WHERE id = v_order.created_by;

    FOR v_route IN
      WITH routed_items AS (
        SELECT
          pr.printer_id,
          pr.printer_role,
          pr.slot,
          oi.id AS order_item_id,
          jsonb_build_object(
            'item_name', oi.item_name,
            'variant_name', oi.variant_name,
            'quantity', oi.quantity,
            'modifiers', oi.modifiers,
            'sides', oi.sides,
            'note', oi.note
          ) AS item_payload
        FROM public.order_items oi
        JOIN public.menu_items mi
          ON mi.id = oi.menu_item_id
         AND mi.tenant_id = oi.tenant_id
        JOIN LATERAL (
          SELECT
            p.id AS printer_id,
            p.role AS printer_role,
            (p.sort_order + 1)::smallint AS slot
          FROM public.printers p
          JOIN public.printer_print_types ppt
            ON ppt.printer_id = p.id
           AND ppt.tenant_id = p.tenant_id
           AND ppt.branch_id = p.branch_id
           AND ppt.print_type = 'kitchen_ticket'
          LEFT JOIN public.printer_menu_categories pmc
            ON pmc.printer_id = p.id
           AND pmc.tenant_id = p.tenant_id
           AND pmc.branch_id = p.branch_id
           AND pmc.category_id = mi.category_id
          WHERE p.tenant_id = v_order.tenant_id
            AND p.branch_id = v_order.branch_id
            AND p.is_active = TRUE
            AND (
              pmc.id IS NOT NULL
              OR NOT EXISTS (
                SELECT 1
                FROM public.printer_menu_categories pmc_any
                WHERE pmc_any.tenant_id = v_order.tenant_id
                  AND pmc_any.branch_id = v_order.branch_id
                  AND pmc_any.category_id = mi.category_id
              )
            )
          ORDER BY
            CASE WHEN pmc.id IS NOT NULL THEN 0 ELSE 1 END,
            p.sort_order, p.id
          LIMIT 1
        ) pr ON TRUE
        WHERE oi.order_id = p_order_id
          AND oi.sent_to_kitchen_at IS NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.kds_tickets kt
            WHERE kt.tenant_id = v_order.tenant_id
              AND kt.order_item_id = oi.id
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.kds_station_categories sc
            JOIN public.kds_stations s ON s.id = sc.station_id
            WHERE sc.category_id = mi.category_id
              AND s.branch_id = v_order.branch_id
              AND s.tenant_id = v_order.tenant_id
              AND s.is_active = TRUE
          )
      ),
      grouped_routes AS (
        SELECT
          printer_id,
          printer_role,
          slot,
          array_agg(order_item_id ORDER BY order_item_id) AS item_ids,
          jsonb_agg(item_payload ORDER BY order_item_id) AS items
        FROM routed_items
        GROUP BY printer_id, printer_role, slot
      )
      SELECT *
      FROM grouped_routes
      ORDER BY printer_role, printer_id
    LOOP
      v_job_id := NULL;

      v_payload := jsonb_build_object(
        'kind', 'kitchen_ticket',
        'kitchen_ticket_number', v_ticket_number,
        'source_order_number', v_order.order_number,
        'order_number', v_order.order_number,
        'order_type', v_order.order_type,
        'table_number', v_table_no,
        'cashier_name', COALESCE(v_cashier_name, ''),
        'send_seq', v_send_seq,
        'send_kind', CASE WHEN v_send_seq = 1 THEN 'initial' ELSE 'append' END,
        'slot', v_route.slot,
        'note', v_order.note,
        'items', v_route.items,
        'printed_at', to_char(now() AT TIME ZONE 'Asia/Ho_Chi_Minh',
                              'YYYY-MM-DD"T"HH24:MI:SS')
      );

      v_idempotency := 'order:' || p_order_id::TEXT
        || ':non-kds-dispatch:printer:' || v_route.printer_id::TEXT
        || ':batch:' || v_batch_id::TEXT
        || ':items:' || md5(array_to_string(v_route.item_ids, ','));

      INSERT INTO public.print_jobs (
        tenant_id, branch_id, printer_id, job_type,
        order_id, payload, idempotency_key, created_by
      )
      VALUES (
        v_order.tenant_id, v_order.branch_id, v_route.printer_id,
        'kitchen_ticket', p_order_id, v_payload, v_idempotency, auth.uid()
      )
      ON CONFLICT (idempotency_key) DO NOTHING
      RETURNING id INTO v_job_id;

      IF v_job_id IS NULL THEN
        SELECT id INTO v_job_id
        FROM public.print_jobs
        WHERE idempotency_key = v_idempotency;
      END IF;

      UPDATE public.order_items
         SET sent_to_kitchen_at = COALESCE(sent_to_kitchen_at, now())
       WHERE id = ANY(v_route.item_ids)
         AND sent_to_kitchen_at IS NULL;
    END LOOP;
  END IF;

  SELECT count(*)::int INTO v_unrouted
  FROM public.order_items oi
  WHERE oi.order_id = p_order_id
    AND oi.status <> 'cancelled'
    AND oi.sent_to_kitchen_at IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.kds_tickets kt
      WHERE kt.tenant_id = v_order.tenant_id
        AND kt.order_item_id = oi.id
    );

  IF v_unrouted > 0 THEN
    RAISE EXCEPTION 'kds_no_route: order % has % unroutable item(s)',
      p_order_id, v_unrouted
      USING ERRCODE = '22023';
  END IF;
END;
$_$;


--
-- Name: FUNCTION route_order_to_kds(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.route_order_to_kds(p_order_id bigint) IS 'Routes explicit KDS categories to KDS tickets; otherwise queues kitchen printer jobs from category-specific or default kitchen printer routing. Missing KDS and printer routing fails loud.';


--
-- Name: run_inventory_valuation_reconciliation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_inventory_valuation_reconciliation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_tenant bigint := public.auth_tenant_id();
  v_tenant record;
  v_quantity_mismatches integer;
  v_value_mismatches integer;
  v_result jsonb := '[]'::jsonb;
  v_today date := (pg_catalog.now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_year integer := extract(
    YEAR FROM pg_catalog.now() AT TIME ZONE 'Asia/Ho_Chi_Minh'
  )::integer;
  v_month integer := extract(
    MONTH FROM pg_catalog.now() AT TIME ZONE 'Asia/Ho_Chi_Minh'
  )::integer;
BEGIN
  IF v_actor IS NOT NULL
     AND (
       v_actor_tenant IS NULL
       OR NOT public.has_permission_any('inventory:valuation_read')
     ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  FOR v_tenant IN
    SELECT cutover.tenant_id, cutover.status
    FROM public.inventory_valuation_cutovers AS cutover
    WHERE cutover.status IN ('shadow', 'active')
      AND (
        v_actor IS NULL
        OR cutover.tenant_id = v_actor_tenant
      )
    ORDER BY cutover.tenant_id
  LOOP
    SELECT
      pg_catalog.count(*) FILTER (
        WHERE account.quantity IS DISTINCT FROM stock.current_quantity
      ),
      pg_catalog.count(*) FILTER (
        WHERE account.book_value IS DISTINCT FROM origin_totals.book_value
           OR account.quantity IS DISTINCT FROM origin_totals.quantity
      )
    INTO v_quantity_mismatches, v_value_mismatches
    FROM public.inventory_valuation_accounts AS account
    FULL JOIN public.stock_levels AS stock
      ON stock.tenant_id = account.tenant_id
     AND stock.branch_id = account.branch_id
     AND stock.location_id = account.location_id
     AND stock.ingredient_id = account.ingredient_id
    LEFT JOIN LATERAL (
      SELECT
        coalesce(pg_catalog.sum(balance.quantity), 0) AS quantity,
        coalesce(pg_catalog.sum(balance.book_value), 0) AS book_value
      FROM public.inventory_origin_balances AS balance
      WHERE balance.tenant_id = account.tenant_id
        AND balance.valuation_account_id = account.id
        AND balance.holder_kind = 'stock_pool'
    ) AS origin_totals ON TRUE
    WHERE coalesce(account.tenant_id, stock.tenant_id) = v_tenant.tenant_id;

    IF v_quantity_mismatches > 0 THEN
      INSERT INTO public.notifications (
        tenant_id,
        target_roles,
        kind,
        severity,
        title,
        body,
        action_url,
        dedup_key,
        meta
      )
      VALUES (
        v_tenant.tenant_id,
        ARRAY['owner']::text[],
        'inventory.valuation_reconciliation_failed',
        'critical',
        'Số lượng tồn kho và sổ giá trị đang lệch',
        'Hệ thống đã dừng khóa kỳ; cần đối soát movement và valuation account.',
        '/finance/cost-close?year=' || v_year::text || '&month=' || v_month::text,
        'inventory.valuation_reconciliation_failed:'
          || v_today::text || ':quantity',
        pg_catalog.jsonb_build_object(
          'drift_type', 'quantity',
          'mismatch_count', v_quantity_mismatches,
          'source', 'scheduled_job'
        )
      )
      ON CONFLICT (tenant_id, dedup_key)
        WHERE dedup_key IS NOT NULL
      DO UPDATE SET
        body = EXCLUDED.body,
        meta = EXCLUDED.meta,
        created_at = pg_catalog.now(),
        expires_at = NULL;
    END IF;

    IF v_value_mismatches > 0 THEN
      INSERT INTO public.notifications (
        tenant_id,
        target_roles,
        kind,
        severity,
        title,
        body,
        action_url,
        dedup_key,
        meta
      )
      VALUES (
        v_tenant.tenant_id,
        ARRAY['owner']::text[],
        'inventory.valuation_reconciliation_failed',
        'critical',
        'Giá trị tồn kho và cost origin đang lệch',
        'Hệ thống đã dừng khóa kỳ; cần đối soát valuation account và origin balance.',
        '/finance/cost-close?year=' || v_year::text || '&month=' || v_month::text,
        'inventory.valuation_reconciliation_failed:'
          || v_today::text || ':value',
        pg_catalog.jsonb_build_object(
          'drift_type', 'value',
          'mismatch_count', v_value_mismatches,
          'source', 'scheduled_job'
        )
      )
      ON CONFLICT (tenant_id, dedup_key)
        WHERE dedup_key IS NOT NULL
      DO UPDATE SET
        body = EXCLUDED.body,
        meta = EXCLUDED.meta,
        created_at = pg_catalog.now(),
        expires_at = NULL;
    END IF;

    v_result := v_result || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'tenant_id', v_tenant.tenant_id,
        'status', v_tenant.status,
        'quantity_mismatches', v_quantity_mismatches,
        'value_mismatches', v_value_mismatches,
        'is_reconciled',
          v_quantity_mismatches = 0 AND v_value_mismatches = 0
      )
    );
  END LOOP;

  RETURN v_result;
END;
$$;


--
-- Name: save_employee_shift_task_override(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_employee_shift_task_override(p_employee_id bigint, p_tasks jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_template_id bigint;
  v_employee_name text;
  v_task jsonb;
  v_item_id bigint;
  v_sort_order integer := 0;
  v_ingredient_id bigint;
  v_ingredient_sort_order integer;
BEGIN
  IF auth.uid() IS NULL OR v_tenant_id IS NULL
     OR NOT public.has_permission(NULL, 'hr:manage_position_tasks') THEN
    RAISE EXCEPTION 'position_tasks_forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_tasks IS NULL OR jsonb_typeof(p_tasks) <> 'array'
     OR jsonb_array_length(p_tasks) > 40 THEN
    RAISE EXCEPTION 'too_many_tasks' USING ERRCODE = '22023';
  END IF;

  SELECT profile.full_name, employee.default_checklist_template_id
  INTO v_employee_name, v_template_id
  FROM public.employees employee
  JOIN public.profiles profile
    ON profile.id = employee.profile_id
   AND profile.tenant_id = employee.tenant_id
  WHERE employee.id = p_employee_id
    AND employee.tenant_id = v_tenant_id
    AND employee.is_active
  FOR UPDATE OF employee;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_template_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.shift_checklist_templates template
    WHERE template.id = v_template_id
      AND template.tenant_id = v_tenant_id
      AND template.employee_id = p_employee_id
  ) THEN
    v_template_id := NULL;
  END IF;

  IF v_template_id IS NULL THEN
    SELECT template.id
    INTO v_template_id
    FROM public.shift_checklist_templates template
    WHERE template.tenant_id = v_tenant_id
      AND template.employee_id = p_employee_id
      AND template.is_active
    FOR UPDATE;
  END IF;

  IF v_template_id IS NULL THEN
    INSERT INTO public.shift_checklist_templates (
      tenant_id, branch_id, employee_id, name, is_active
    ) VALUES (
      v_tenant_id,
      NULL,
      p_employee_id,
      format('Mẫu riêng · %s', COALESCE(NULLIF(btrim(v_employee_name), ''), 'Nhân viên')),
      true
    )
    RETURNING id INTO v_template_id;
  ELSE
    UPDATE public.shift_checklist_templates
    SET branch_id = NULL,
        employee_id = p_employee_id,
        is_active = true,
        updated_at = now()
    WHERE id = v_template_id
      AND tenant_id = v_tenant_id;
  END IF;

  UPDATE public.employees
  SET default_checklist_template_id = v_template_id,
      updated_at = now()
  WHERE id = p_employee_id
    AND tenant_id = v_tenant_id;

  DELETE FROM public.shift_checklist_template_items item
  WHERE item.tenant_id = v_tenant_id
    AND item.template_id = v_template_id;

  FOR v_task IN SELECT value FROM jsonb_array_elements(p_tasks)
  LOOP
    v_sort_order := v_sort_order + 1;
    IF btrim(COALESCE(v_task ->> 'title', '')) = ''
       OR char_length(v_task ->> 'title') > 120 THEN
      RAISE EXCEPTION 'task_title_invalid' USING ERRCODE = '22023';
    END IF;
    IF COALESCE(v_task ->> 'kind', 'standard') NOT IN ('standard', 'consumption_report') THEN
      RAISE EXCEPTION 'task_kind_invalid' USING ERRCODE = '22023';
    END IF;
    IF COALESCE(v_task ->> 'applicability', 'every_shift') NOT IN ('every_shift', 'opening', 'closing') THEN
      RAISE EXCEPTION 'task_applicability_invalid' USING ERRCODE = '22023';
    END IF;
    IF COALESCE(v_task ->> 'phase', 'start_of_shift') NOT IN ('start_of_shift', 'end_of_shift') THEN
      RAISE EXCEPTION 'task_phase_invalid' USING ERRCODE = '22023';
    END IF;
    IF char_length(COALESCE(v_task ->> 'doneDefinition', '')) > 240 THEN
      RAISE EXCEPTION 'done_definition_too_long' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.shift_checklist_template_items (
      tenant_id, template_id, title, sort_order, is_active, phase,
      done_definition, is_required, scope, task_kind
    ) VALUES (
      v_tenant_id,
      v_template_id,
      btrim(v_task ->> 'title'),
      v_sort_order,
      true,
      COALESCE(v_task ->> 'phase', 'start_of_shift'),
      btrim(COALESCE(v_task ->> 'doneDefinition', '')),
      COALESCE((v_task ->> 'isRequired')::boolean, true),
      COALESCE(v_task ->> 'applicability', 'every_shift'),
      COALESCE(v_task ->> 'kind', 'standard')
    )
    RETURNING id INTO v_item_id;

    IF COALESCE(v_task ->> 'kind', 'standard') = 'consumption_report' THEN
      v_ingredient_sort_order := 0;
      FOR v_ingredient_id IN
        SELECT DISTINCT value::bigint
        FROM jsonb_array_elements_text(COALESCE(v_task -> 'ingredientIds', '[]'::jsonb))
      LOOP
        v_ingredient_sort_order := v_ingredient_sort_order + 1;
        IF NOT EXISTS (
          SELECT 1 FROM public.ingredients ingredient
          WHERE ingredient.id = v_ingredient_id
            AND ingredient.tenant_id = v_tenant_id
            AND ingredient.is_active
        ) THEN
          RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
        END IF;

        INSERT INTO public.shift_checklist_consumption_default_items (
          tenant_id, template_item_id, ingredient_id, sort_order, is_active
        ) VALUES (
          v_tenant_id, v_item_id, v_ingredient_id, v_ingredient_sort_order, true
        );
      END LOOP;
    END IF;
  END LOOP;

  PERFORM public.log_audit(
    'update',
    'employee_shift_task_override',
    p_employee_id,
    NULL,
    jsonb_build_object(
      'template_id', v_template_id,
      'task_count', jsonb_array_length(p_tasks)
    )
  );

  RETURN v_template_id;
END;
$$;


--
-- Name: save_employee_weekly_schedule(bigint, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_employee_weekly_schedule(p_employee_id bigint, p_effective_from date, p_days jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_branch_id bigint;
  v_start_date date;
  v_day jsonb;
  v_weekday integer;
  v_shift_id bigint;
  v_shift_ids bigint[] := ARRAY[]::bigint[];
  v_shift_by_day bigint[] := ARRAY[NULL, NULL, NULL, NULL, NULL, NULL, NULL]::bigint[];
BEGIN
  IF v_actor IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_effective_from IS NULL THEN
    RAISE EXCEPTION 'effective_from_required' USING ERRCODE = '22023';
  END IF;
  IF p_days IS NULL OR jsonb_typeof(p_days) <> 'array' THEN
    RAISE EXCEPTION 'schedule_days_must_be_array' USING ERRCODE = '22023';
  END IF;

  SELECT profile.branch_id, employee.start_date
  INTO v_branch_id, v_start_date
  FROM public.employees employee
  JOIN public.profiles profile
    ON profile.id = employee.profile_id
   AND profile.tenant_id = employee.tenant_id
  WHERE employee.id = p_employee_id
    AND employee.tenant_id = v_tenant_id
    AND employee.is_active
    AND profile.is_active
  FOR UPDATE OF employee;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF (
    public.has_permission(v_branch_id, 'hr:assign_shift')
    OR public.has_permission(NULL::bigint, 'hr:assign_shift')
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_start_date IS NOT NULL AND p_effective_from < v_start_date THEN
    RAISE EXCEPTION 'schedule_before_employee_start' USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_days) = 0 THEN
    DELETE FROM public.employee_weekly_schedules schedule
    WHERE schedule.tenant_id = v_tenant_id
      AND schedule.employee_id = p_employee_id;

    DELETE FROM public.shift_assignments assignment
    WHERE assignment.tenant_id = v_tenant_id
      AND assignment.employee_id = p_employee_id
      AND assignment.source IN ('recurring', 'day_off')
      AND assignment.work_date >= (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
      AND NOT EXISTS (
        SELECT 1
        FROM public.attendance_records attendance
        WHERE attendance.tenant_id = assignment.tenant_id
          AND attendance.employee_id = assignment.employee_id
          AND attendance.date = assignment.work_date
      );

    RETURN jsonb_build_object('cleared', true);
  END IF;

  FOR v_day IN SELECT * FROM jsonb_array_elements(p_days)
  LOOP
    v_weekday := (v_day->>'weekday')::integer;
    v_shift_id := (v_day->>'shift_id')::bigint;
    IF v_weekday < 1 OR v_weekday > 7 OR v_shift_id IS NULL THEN
      RAISE EXCEPTION 'schedule_day_invalid' USING ERRCODE = '22023';
    END IF;
    IF v_shift_by_day[v_weekday] IS NOT NULL THEN
      RAISE EXCEPTION 'schedule_day_duplicate' USING ERRCODE = '22023';
    END IF;
    v_shift_by_day[v_weekday] := v_shift_id;
    v_shift_ids := array_append(v_shift_ids, v_shift_id);
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM unnest(v_shift_ids) requested_shift_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.shifts shift
      WHERE shift.id = requested_shift_id
        AND shift.tenant_id = v_tenant_id
        AND shift.branch_id IS NULL
        AND shift.is_active
    )
  ) THEN
    RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.employee_weekly_schedules (
    tenant_id,
    employee_id,
    effective_from,
    monday_shift_id,
    tuesday_shift_id,
    wednesday_shift_id,
    thursday_shift_id,
    friday_shift_id,
    saturday_shift_id,
    sunday_shift_id,
    updated_by
  )
  VALUES (
    v_tenant_id,
    p_employee_id,
    p_effective_from,
    v_shift_by_day[1],
    v_shift_by_day[2],
    v_shift_by_day[3],
    v_shift_by_day[4],
    v_shift_by_day[5],
    v_shift_by_day[6],
    v_shift_by_day[7],
    v_actor
  )
  ON CONFLICT (tenant_id, employee_id)
  DO UPDATE SET
    effective_from = EXCLUDED.effective_from,
    monday_shift_id = EXCLUDED.monday_shift_id,
    tuesday_shift_id = EXCLUDED.tuesday_shift_id,
    wednesday_shift_id = EXCLUDED.wednesday_shift_id,
    thursday_shift_id = EXCLUDED.thursday_shift_id,
    friday_shift_id = EXCLUDED.friday_shift_id,
    saturday_shift_id = EXCLUDED.saturday_shift_id,
    sunday_shift_id = EXCLUDED.sunday_shift_id,
    updated_by = EXCLUDED.updated_by,
    updated_at = now();

  DELETE FROM public.shift_assignments assignment
  WHERE assignment.tenant_id = v_tenant_id
    AND assignment.employee_id = p_employee_id
    AND assignment.source = 'recurring'
    AND assignment.work_date >= (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
    AND NOT EXISTS (
      SELECT 1
      FROM public.attendance_records attendance
      WHERE attendance.tenant_id = assignment.tenant_id
        AND attendance.employee_id = assignment.employee_id
        AND attendance.date = assignment.work_date
    );

  PERFORM private.materialize_employee_weekly_schedules(p_employee_id);
  RETURN jsonb_build_object('cleared', false);
END;
$$;


--
-- Name: save_goods_receipt_note(bigint, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_goods_receipt_note(p_grn_id bigint, p_received_date timestamp with time zone, p_notes text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_grn public.goods_received_notes%ROWTYPE;
  v_input_count integer;
  v_distinct_count integer;
  v_expected_count integer;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'grn_lines_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT grn.*
  INTO v_grn
  FROM public.goods_received_notes AS grn
  WHERE grn.id = p_grn_id
    AND grn.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_grn.branch_id, 'procurement:grn_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_grn.status <> 'draft' THEN
    RAISE EXCEPTION 'grn_not_draft' USING ERRCODE = '23514';
  END IF;

  SELECT count(*), count(DISTINCT line.line_id)
  INTO v_input_count, v_distinct_count
  FROM jsonb_to_recordset(p_lines)
    AS line(line_id bigint);

  SELECT count(*)
  INTO v_expected_count
  FROM public.grn_items AS item
  WHERE item.grn_id = p_grn_id
    AND item.tenant_id = v_tenant;

  IF v_input_count <> v_distinct_count
     OR v_input_count <> v_expected_count
     OR EXISTS (
       SELECT 1
       FROM jsonb_to_recordset(p_lines)
         AS line(
           line_id bigint,
           received_quantity numeric,
           rejected_quantity numeric,
           rejection_reason text,
           rejected_photo_url text
         )
       LEFT JOIN public.grn_items AS item
         ON item.id = line.line_id
        AND item.grn_id = p_grn_id
        AND item.tenant_id = v_tenant
       WHERE item.id IS NULL
          OR line.received_quantity IS NULL
          OR line.received_quantity < 0
          OR COALESCE(line.rejected_quantity, 0) < 0
          OR COALESCE(line.rejected_quantity, 0) > line.received_quantity
          OR (
            COALESCE(line.rejected_quantity, 0) > 0
            AND (
              length(btrim(COALESCE(line.rejection_reason, ''))) = 0
              OR length(btrim(COALESCE(line.rejected_photo_url, ''))) = 0
            )
          )
     ) THEN
    RAISE EXCEPTION 'grn_lines_invalid' USING ERRCODE = '23514';
  END IF;

  UPDATE public.grn_items AS item
  SET received_quantity = line.received_quantity::numeric(15,3),
      rejected_quantity = COALESCE(
        line.rejected_quantity,
        0
      )::numeric(15,3),
      rejection_reason = NULLIF(btrim(line.rejection_reason), ''),
      rejected_photo_url = NULLIF(btrim(line.rejected_photo_url), '')
  FROM jsonb_to_recordset(p_lines)
    AS line(
      line_id bigint,
      received_quantity numeric,
      rejected_quantity numeric,
      rejection_reason text,
      rejected_photo_url text
    )
  WHERE item.id = line.line_id
    AND item.grn_id = p_grn_id
    AND item.tenant_id = v_tenant;

  UPDATE public.goods_received_notes
  SET received_date = COALESCE(p_received_date, received_date),
      notes = CASE
        WHEN p_notes IS NULL THEN notes
        ELSE NULLIF(btrim(p_notes), '')
      END,
      updated_at = now()
  WHERE id = p_grn_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'inventory.grn.saved',
    'goods_received_note',
    p_grn_id,
    to_jsonb(v_grn),
    jsonb_build_object(
      'status', 'draft',
      'line_count', v_input_count,
      'received_date', p_received_date
    )
  );

  RETURN jsonb_build_object(
    'id', p_grn_id,
    'status', 'draft',
    'updated_lines', v_input_count
  );
END;
$$;


--
-- Name: save_ingredient_catalog(bigint, text, text, bigint, text, text, numeric, numeric, numeric, integer, jsonb, text, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_ingredient_catalog(p_ingredient_id bigint, p_name text, p_sku text, p_category_id bigint, p_item_kind text, p_storage_type text, p_min_stock_level numeric, p_max_stock_level numeric, p_reorder_point numeric, p_shelf_life_days integer, p_units jsonb, p_default_fulfill_site_kind text, p_receipt_unit_id bigint, p_issue_unit_id bigint, p_production_unit_id bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_id bigint := p_ingredient_id;
  v_base_unit_id bigint;
  v_old_base_unit_id bigint;
  v_category_name text;
  v_preserved_unit_cost numeric;
  v_receipt_factor numeric;
  v_issue_factor numeric;
  v_production_factor numeric;
  v_receipt_dimension text;
  v_issue_dimension text;
  v_production_dimension text;
  v_scale numeric := 1;
  v_bridge_factor numeric;
  v_min_stock numeric;
  v_max_stock numeric;
  v_reorder numeric;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF public.auth_role() <> 'owner'
     OR NOT public.has_permission_any('inventory:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_units IS NULL
     OR jsonb_typeof(p_units) <> 'array'
     OR jsonb_array_length(p_units) NOT BETWEEN 1 AND 3
     OR p_receipt_unit_id IS NULL
     OR p_issue_unit_id IS NULL THEN
    RAISE EXCEPTION 'inventory_unit_roles_invalid' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_units) AS incoming
    LEFT JOIN public.units AS unit_row
      ON unit_row.id = (incoming ->> 'unit_id')::bigint
     AND unit_row.tenant_id = v_tenant
     AND unit_row.is_active
    WHERE unit_row.id IS NULL
       OR COALESCE((incoming ->> 'to_base_factor')::numeric, 0) <= 0
  ) OR (
    SELECT count(*)
    FROM jsonb_array_elements(p_units)
  ) <> (
    SELECT count(DISTINCT (incoming ->> 'unit_id')::bigint)
    FROM jsonb_array_elements(p_units) AS incoming
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_units) AS incoming
    WHERE COALESCE((incoming ->> 'is_base')::boolean, false)
      AND (incoming ->> 'to_base_factor')::numeric IS DISTINCT FROM 1
  ) THEN
    RAISE EXCEPTION 'inventory_unit_roles_invalid' USING ERRCODE = '23514';
  END IF;
  IF (
    SELECT count(*)
    FROM jsonb_array_elements(p_units) AS incoming
    WHERE COALESCE((incoming ->> 'is_base')::boolean, false)
  ) <> 1 THEN
    RAISE EXCEPTION 'exactly_one_standard_unit_required' USING ERRCODE = '23514';
  END IF;

  SELECT (incoming ->> 'unit_id')::bigint
  INTO v_base_unit_id
  FROM jsonb_array_elements(p_units) AS incoming
  WHERE COALESCE((incoming ->> 'is_base')::boolean, false)
  LIMIT 1;

  IF v_base_unit_id IS DISTINCT FROM p_receipt_unit_id
     AND v_base_unit_id IS DISTINCT FROM p_issue_unit_id
     AND v_base_unit_id IS DISTINCT FROM p_production_unit_id THEN
    RAISE EXCEPTION 'inventory_standard_unit_role_mismatch' USING ERRCODE = '23514';
  END IF;

  SELECT public.inv_catalog_unit_to_base(v_base_unit_id, incoming, p_units)
  INTO v_receipt_factor
  FROM jsonb_array_elements(p_units) AS incoming
  WHERE (incoming ->> 'unit_id')::bigint = p_receipt_unit_id;
  SELECT public.inv_catalog_unit_to_base(v_base_unit_id, incoming, p_units)
  INTO v_issue_factor
  FROM jsonb_array_elements(p_units) AS incoming
  WHERE (incoming ->> 'unit_id')::bigint = p_issue_unit_id;
  SELECT public.inv_catalog_unit_to_base(v_base_unit_id, incoming, p_units)
  INTO v_production_factor
  FROM jsonb_array_elements(p_units) AS incoming
  WHERE (incoming ->> 'unit_id')::bigint = p_production_unit_id;

  IF v_receipt_factor IS NULL
     OR v_issue_factor IS NULL
     OR (p_production_unit_id IS NOT NULL AND v_production_factor IS NULL) THEN
    RAISE EXCEPTION 'inventory_unit_roles_invalid' USING ERRCODE = '23514';
  END IF;

  SELECT CASE WHEN is_standard THEN dimension END
  INTO v_receipt_dimension
  FROM public.units
  WHERE tenant_id = v_tenant AND id = p_receipt_unit_id;
  SELECT CASE WHEN is_standard THEN dimension END
  INTO v_issue_dimension
  FROM public.units
  WHERE tenant_id = v_tenant AND id = p_issue_unit_id;
  SELECT CASE WHEN is_standard THEN dimension END
  INTO v_production_dimension
  FROM public.units
  WHERE tenant_id = v_tenant AND id = p_production_unit_id;

  IF (v_receipt_dimension IS NOT NULL AND v_issue_dimension IS NOT NULL AND v_receipt_dimension IS DISTINCT FROM v_issue_dimension)
     OR (v_production_dimension IS NOT NULL AND (
       (v_receipt_dimension IS NOT NULL AND v_production_dimension IS DISTINCT FROM v_receipt_dimension)
       OR (v_issue_dimension IS NOT NULL AND v_production_dimension IS DISTINCT FROM v_issue_dimension)
     )) THEN
    RAISE EXCEPTION 'standard_unit_dimension_mismatch' USING ERRCODE = '23514';
  END IF;

  IF p_category_id IS NOT NULL THEN
    SELECT name
    INTO v_category_name
    FROM public.ingredient_categories
    WHERE id = p_category_id
      AND tenant_id = v_tenant
      AND is_active;
    IF v_category_name IS NULL THEN
      RAISE EXCEPTION 'category not found' USING ERRCODE = '23503';
    END IF;
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO public.ingredients (
      tenant_id, name, sku, category_id, category, unit_cost, item_kind,
      storage_type, min_stock_level, max_stock_level, reorder_point,
      shelf_life_days, default_fulfill_site_kind, receipt_unit_id,
      issue_unit_id, production_unit_id
    ) VALUES (
      v_tenant, p_name, p_sku, p_category_id, v_category_name, 0,
      COALESCE(p_item_kind, 'raw_material'), COALESCE(p_storage_type, 'ambient'),
      COALESCE(p_min_stock_level, 0), p_max_stock_level, p_reorder_point,
      p_shelf_life_days, p_default_fulfill_site_kind, p_receipt_unit_id,
      p_issue_unit_id, p_production_unit_id
    ) RETURNING id INTO v_id;
  ELSE
    SELECT unit_cost,
           min_stock_level,
           max_stock_level,
           reorder_point
    INTO v_preserved_unit_cost,
         v_min_stock,
         v_max_stock,
         v_reorder
    FROM public.ingredients
    WHERE id = v_id
      AND tenant_id = v_tenant
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'ingredient not found' USING ERRCODE = 'P0002';
    END IF;

    SELECT unit_id
    INTO v_old_base_unit_id
    FROM public.ingredient_units
    WHERE tenant_id = v_tenant
      AND ingredient_id = v_id
      AND is_base
    LIMIT 1;

    IF EXISTS (
      SELECT 1
      FROM public.production_recipes AS recipe
      WHERE recipe.tenant_id = v_tenant
        AND recipe.ingredient_id = v_id
        AND recipe.entry_unit_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(p_units) AS incoming
          WHERE (incoming ->> 'unit_id')::bigint = recipe.entry_unit_id
        )
    ) THEN
      RAISE EXCEPTION 'ingredient_unit_in_use_by_production_recipe' USING ERRCODE = '23503';
    END IF;

    -- How many new-base units equal one old-base unit.
    IF v_old_base_unit_id IS NOT NULL
       AND v_old_base_unit_id IS DISTINCT FROM v_base_unit_id THEN
      SELECT public.inv_catalog_unit_to_base(v_base_unit_id, incoming, p_units)
      INTO v_scale
      FROM jsonb_array_elements(p_units) AS incoming
      WHERE (incoming ->> 'unit_id')::bigint = v_old_base_unit_id
      LIMIT 1;

      IF v_scale IS NULL THEN
        SELECT unit_row.to_base_factor
        INTO v_bridge_factor
        FROM public.ingredient_units AS unit_row
        WHERE unit_row.tenant_id = v_tenant
          AND unit_row.ingredient_id = v_id
          AND unit_row.unit_id = v_base_unit_id;
        IF v_bridge_factor IS NOT NULL AND v_bridge_factor > 0 THEN
          v_scale := 1 / v_bridge_factor;
        ELSE
          -- Sole-unit rename / swap without an explicit bridge: treat as 1:1.
          v_scale := 1;
        END IF;
      END IF;
    END IF;

    IF abs(v_scale - 1) > 0.000000001 THEN
      v_min_stock := COALESCE(p_min_stock_level, v_min_stock, 0) * v_scale;
      v_max_stock := CASE
        WHEN p_max_stock_level IS NOT NULL THEN p_max_stock_level * v_scale
        WHEN v_max_stock IS NOT NULL THEN v_max_stock * v_scale
        ELSE NULL
      END;
      v_reorder := CASE
        WHEN p_reorder_point IS NOT NULL THEN p_reorder_point * v_scale
        WHEN v_reorder IS NOT NULL THEN v_reorder * v_scale
        ELSE NULL
      END;
      v_preserved_unit_cost := CASE
        WHEN v_preserved_unit_cost IS NULL THEN NULL
        ELSE v_preserved_unit_cost / v_scale
      END;

      UPDATE public.stock_levels
      SET current_quantity = current_quantity * v_scale,
          avg_unit_cost = CASE
            WHEN avg_unit_cost IS NULL THEN NULL
            ELSE avg_unit_cost / v_scale
          END,
          updated_at = now()
      WHERE tenant_id = v_tenant
        AND ingredient_id = v_id;

      UPDATE public.inventory_valuation_accounts
      SET quantity = quantity * v_scale,
          valuation_version = valuation_version + 1,
          updated_at = pg_catalog.now()
      WHERE tenant_id = v_tenant
        AND ingredient_id = v_id;

      UPDATE public.inventory_cost_origins
      SET original_quantity = original_quantity * v_scale,
          finalized_quantity = finalized_quantity * v_scale
      WHERE tenant_id = v_tenant
        AND ingredient_id = v_id;

      UPDATE public.inventory_origin_balances AS balance
      SET quantity = balance.quantity * v_scale,
          updated_at = pg_catalog.now()
      FROM public.inventory_cost_origins AS origin
      WHERE origin.tenant_id = v_tenant
        AND origin.ingredient_id = v_id
        AND balance.tenant_id = v_tenant
        AND balance.origin_id = origin.id;
    ELSE
      v_min_stock := COALESCE(p_min_stock_level, 0);
      v_max_stock := p_max_stock_level;
      v_reorder := p_reorder_point;
    END IF;

    UPDATE public.ingredients
    SET name = p_name,
        sku = p_sku,
        category_id = p_category_id,
        category = v_category_name,
        unit_cost = COALESCE(v_preserved_unit_cost, unit_cost),
        item_kind = COALESCE(p_item_kind, item_kind),
        storage_type = COALESCE(p_storage_type, storage_type),
        min_stock_level = v_min_stock,
        max_stock_level = v_max_stock,
        reorder_point = v_reorder,
        shelf_life_days = p_shelf_life_days,
        default_fulfill_site_kind = p_default_fulfill_site_kind,
        receipt_unit_id = p_receipt_unit_id,
        issue_unit_id = p_issue_unit_id,
        production_unit_id = p_production_unit_id,
        updated_at = now()
    WHERE id = v_id
      AND tenant_id = v_tenant;
  END IF;

  UPDATE public.ingredient_units
  SET is_base = false
  WHERE tenant_id = v_tenant
    AND ingredient_id = v_id
    AND is_base
    AND unit_id IS DISTINCT FROM v_base_unit_id;

  INSERT INTO public.ingredient_units (
    tenant_id, ingredient_id, unit_id, to_base_factor, is_base,
    anchor_unit_id, anchor_factor, sort_order
  )
  SELECT
    v_tenant,
    v_id,
    (incoming ->> 'unit_id')::bigint,
    public.inv_catalog_unit_to_base(v_base_unit_id, incoming, p_units),
    COALESCE((incoming ->> 'is_base')::boolean, false),
    NULLIF(incoming ->> 'anchor_unit_id', '')::bigint,
    NULLIF(incoming ->> 'anchor_factor', '')::numeric,
    COALESCE((incoming ->> 'sort_order')::integer, 0)
  FROM jsonb_array_elements(p_units) AS incoming
  ON CONFLICT ON CONSTRAINT ingredient_units_ing_unit_key DO UPDATE
  SET to_base_factor = EXCLUDED.to_base_factor,
      is_base = EXCLUDED.is_base,
      anchor_unit_id = EXCLUDED.anchor_unit_id,
      anchor_factor = EXCLUDED.anchor_factor,
      sort_order = EXCLUDED.sort_order,
      is_active = true;

  DELETE FROM public.ingredient_units AS unit_row
  WHERE unit_row.tenant_id = v_tenant
    AND unit_row.ingredient_id = v_id
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_units) AS incoming
      WHERE (incoming ->> 'unit_id')::bigint = unit_row.unit_id
    );

  -- Living master/draft snapshots track the current unit factors; confirmed
  -- documents and stock_movements keep their historical snapshots.
  UPDATE public.production_recipes AS recipe
  SET entry_to_base_factor = unit_row.to_base_factor,
      entry_unit_code = units.code
  FROM public.ingredient_units AS unit_row,
       public.units AS units
  WHERE recipe.tenant_id = v_tenant
    AND recipe.ingredient_id = v_id
    AND recipe.entry_unit_id = unit_row.unit_id
    AND unit_row.tenant_id = v_tenant
    AND unit_row.ingredient_id = v_id
    AND units.id = unit_row.unit_id
    AND units.tenant_id = unit_row.tenant_id;

  UPDATE public.purchase_order_items AS item
  SET entry_to_base_factor = unit_row.to_base_factor,
      entry_unit_code = units.code
  FROM public.purchase_orders AS po,
       public.ingredient_units AS unit_row,
       public.units AS units
  WHERE item.tenant_id = v_tenant
    AND item.ingredient_id = v_id
    AND item.entry_unit_id = unit_row.unit_id
    AND unit_row.tenant_id = v_tenant
    AND unit_row.ingredient_id = v_id
    AND units.id = unit_row.unit_id
    AND units.tenant_id = unit_row.tenant_id
    AND po.id = item.po_id
    AND po.tenant_id = v_tenant
    AND po.status = 'draft';

  UPDATE public.grn_items AS item
  SET entry_to_base_factor = unit_row.to_base_factor,
      entry_unit_code = units.code
  FROM public.goods_received_notes AS grn,
       public.ingredient_units AS unit_row,
       public.units AS units
  WHERE item.tenant_id = v_tenant
    AND item.ingredient_id = v_id
    AND item.entry_unit_id = unit_row.unit_id
    AND unit_row.tenant_id = v_tenant
    AND unit_row.ingredient_id = v_id
    AND units.id = unit_row.unit_id
    AND units.tenant_id = unit_row.tenant_id
    AND grn.id = item.grn_id
    AND grn.tenant_id = v_tenant
    AND grn.status = 'draft';

  UPDATE public.stock_transfer_items AS item
  SET entry_to_base_factor = unit_row.to_base_factor,
      entry_unit_code = units.code
  FROM public.stock_transfers AS transfer,
       public.ingredient_units AS unit_row,
       public.units AS units
  WHERE item.tenant_id = v_tenant
    AND item.ingredient_id = v_id
    AND item.entry_unit_id = unit_row.unit_id
    AND unit_row.tenant_id = v_tenant
    AND unit_row.ingredient_id = v_id
    AND units.id = unit_row.unit_id
    AND units.tenant_id = unit_row.tenant_id
    AND transfer.id = item.transfer_id
    AND transfer.tenant_id = v_tenant
    AND transfer.status = 'draft';

  UPDATE public.stock_issue_items AS item
  SET entry_to_base_factor = unit_row.to_base_factor,
      entry_unit_code = units.code
  FROM public.stock_issues AS issue,
       public.ingredient_units AS unit_row,
       public.units AS units
  WHERE item.tenant_id = v_tenant
    AND item.ingredient_id = v_id
    AND item.entry_unit_id = unit_row.unit_id
    AND unit_row.tenant_id = v_tenant
    AND unit_row.ingredient_id = v_id
    AND units.id = unit_row.unit_id
    AND units.tenant_id = unit_row.tenant_id
    AND issue.id = item.issue_id
    AND issue.tenant_id = v_tenant
    AND issue.status = 'draft';

  RETURN v_id;
END;
$$;


--
-- Name: save_item_modifiers(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_item_modifiers(p_item_id bigint, p_modifiers jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT;
  m JSONB;
  i INT := 0;
BEGIN
  IF p_modifiers IS NULL OR jsonb_typeof(p_modifiers) <> 'array' THEN
    RAISE EXCEPTION 'p_modifiers must be a JSON array' USING ERRCODE = '22023';
  END IF;

  v_tenant_id := public.auth_tenant_id();

  PERFORM 1 FROM public.menu_items
    WHERE id = p_item_id AND tenant_id = v_tenant_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.menu_item_modifiers
    WHERE item_id = p_item_id AND tenant_id = v_tenant_id;

  FOR m IN SELECT * FROM jsonb_array_elements(p_modifiers)
  LOOP
    INSERT INTO public.menu_item_modifiers (tenant_id, item_id, name, price, sort_order)
    VALUES (
      v_tenant_id,
      p_item_id,
      m ->> 'name',
      (m ->> 'price')::NUMERIC(15,2),
      COALESCE((m ->> 'sort_order')::INT, i)
    );
    i := i + 1;
  END LOOP;
END;
$$;


--
-- Name: save_item_sides(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_item_sides(p_main_item_id bigint, p_sides jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT;
  s JSONB;
BEGIN
  IF p_sides IS NULL OR jsonb_typeof(p_sides) <> 'array' THEN
    RAISE EXCEPTION 'p_sides must be a JSON array' USING ERRCODE = '22023';
  END IF;

  v_tenant_id := public.auth_tenant_id();

  PERFORM 1 FROM public.menu_items
    WHERE id = p_main_item_id AND tenant_id = v_tenant_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.menu_item_available_sides
    WHERE main_item_id = p_main_item_id AND tenant_id = v_tenant_id;

  FOR s IN SELECT * FROM jsonb_array_elements(p_sides)
  LOOP
    INSERT INTO public.menu_item_available_sides (tenant_id, main_item_id, side_item_id, is_default)
    VALUES (
      v_tenant_id,
      p_main_item_id,
      (s ->> 'side_item_id')::BIGINT,
      COALESCE((s ->> 'is_default')::BOOLEAN, false)
    );
  END LOOP;
END;
$$;


--
-- Name: save_item_variants(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_item_variants(p_item_id bigint, p_variants jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT;
  v JSONB;
  i INT := 0;
BEGIN
  IF p_variants IS NULL OR jsonb_typeof(p_variants) <> 'array' THEN
    RAISE EXCEPTION 'p_variants must be a JSON array' USING ERRCODE = '22023';
  END IF;

  v_tenant_id := public.auth_tenant_id();

  -- Lock parent row to serialize concurrent replace operations
  PERFORM 1 FROM public.menu_items
    WHERE id = p_item_id AND tenant_id = v_tenant_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.menu_item_variants
    WHERE item_id = p_item_id AND tenant_id = v_tenant_id;

  FOR v IN SELECT * FROM jsonb_array_elements(p_variants)
  LOOP
    INSERT INTO public.menu_item_variants (tenant_id, item_id, name, price_adjustment, sort_order)
    VALUES (
      v_tenant_id,
      p_item_id,
      v ->> 'name',
      (v ->> 'price_adjustment')::NUMERIC(15,2),
      COALESCE((v ->> 'sort_order')::INT, i)
    );
    i := i + 1;
  END LOOP;
END;
$$;


--
-- Name: save_print_template_version(text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_print_template_version(p_kind text, p_name text, p_paper_width_mm integer, p_content jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant  BIGINT := public.auth_tenant_id();
  v_uid     UUID := auth.uid();
  v_name    TEXT := NULLIF(btrim(COALESCE(p_name, '')), '');
  v_version INT;
  v_id      BIGINT;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_kind NOT IN (
    'receipt', 'provisional_bill', 'kitchen_ticket',
    'cancel_ticket', 'shift_close_report'
  ) THEN
    RAISE EXCEPTION 'invalid kind' USING ERRCODE = '22023';
  END IF;

  IF p_paper_width_mm NOT IN (58, 80) THEN
    RAISE EXCEPTION 'invalid paper width' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_content) <> 'object'
     OR jsonb_typeof(p_content->'blocks') <> 'array' THEN
    RAISE EXCEPTION 'invalid content' USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_content->'blocks') > 160 THEN
    RAISE EXCEPTION 'too many blocks' USING ERRCODE = '22023';
  END IF;

  UPDATE public.print_template_versions
     SET is_active = false,
         updated_by = v_uid,
         updated_at = now()
   WHERE tenant_id = v_tenant
     AND branch_id IS NULL
     AND kind = p_kind
     AND is_active;

  SELECT COALESCE(MAX(version), 0) + 1
    INTO v_version
    FROM public.print_template_versions
   WHERE tenant_id = v_tenant
     AND branch_id IS NULL
     AND kind = p_kind;

  INSERT INTO public.print_template_versions (
    tenant_id, branch_id, kind, version, name,
    paper_width_mm, content, is_active, created_by, updated_by
  )
  VALUES (
    v_tenant, NULL, p_kind, v_version,
    COALESCE(v_name, 'Bản tùy chỉnh v' || v_version::TEXT),
    p_paper_width_mm, p_content, true, v_uid, v_uid
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'version', v_version);
END;
$$;


--
-- Name: FUNCTION save_print_template_version(p_kind text, p_name text, p_paper_width_mm integer, p_content jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_print_template_version(p_kind text, p_name text, p_paper_width_mm integer, p_content jsonb) IS 'Template editor save: deactivates the active tenant-scope template for the kind and inserts the next version atomically. SECURITY INVOKER — RLS policies on print_template_versions decide authorization.';


--
-- Name: save_purchase_demand(bigint, bigint, date, text, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_purchase_demand(p_demand_id bigint, p_branch_id bigint, p_needed_by date, p_notes text, p_lines jsonb, p_submit boolean DEFAULT true, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_demand public.purchase_requests%ROWTYPE;
  v_saved jsonb;
  v_demand_id bigint;
  v_status text;
  v_was_pending boolean := FALSE;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_demand_id IS NULL AND p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'purchase_demand_idempotency_required'
      USING ERRCODE = '22023';
  END IF;

  IF p_demand_id IS NOT NULL THEN
    SELECT demand.*
    INTO v_demand
    FROM public.purchase_requests AS demand
    WHERE demand.id = p_demand_id
      AND demand.tenant_id = v_tenant
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_demand_not_found'
        USING ERRCODE = 'P0002';
    END IF;
    IF NOT public.has_permission(
      v_demand.branch_id,
      'procurement:request_manage'
    ) THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;

    v_was_pending := v_demand.status = 'pending_allocation';
    IF v_was_pending
       AND EXISTS (
         SELECT 1
         FROM public.purchase_request_allocations AS allocation
         WHERE allocation.tenant_id = v_tenant
           AND allocation.purchase_request_id = p_demand_id
       ) THEN
      RAISE EXCEPTION 'purchase_demand_allocation_started'
        USING ERRCODE = '23514';
    END IF;

    IF v_demand.status NOT IN (
      'draft',
      'changes_requested',
      'pending_allocation'
    )
       OR EXISTS (
         SELECT 1
         FROM public.purchase_orders AS purchase_order
         WHERE purchase_order.tenant_id = v_tenant
           AND purchase_order.purchase_request_id = p_demand_id
           AND purchase_order.status <> 'cancelled'
       ) THEN
      RAISE EXCEPTION 'purchase_demand_not_editable'
        USING ERRCODE = '23514';
    END IF;

    IF v_demand.status = 'changes_requested' THEN
      UPDATE public.purchase_requests
      SET status = 'draft',
          updated_at = pg_catalog.now()
      WHERE id = p_demand_id
        AND tenant_id = v_tenant;
    END IF;
  END IF;

  v_status := CASE
    WHEN v_was_pending THEN 'pending_allocation'
    WHEN p_submit THEN 'pending_allocation'
    ELSE 'draft'
  END;
  v_saved := public.save_purchase_request(
    p_demand_id,
    p_branch_id,
    p_needed_by,
    p_notes,
    p_lines,
    FALSE,
    p_idempotency_key
  );
  v_demand_id := (v_saved ->> 'request_id')::bigint;

  IF v_status = 'pending_allocation'
     AND EXISTS (
       SELECT 1
       FROM public.purchase_request_items AS demand_item
       WHERE demand_item.tenant_id = v_tenant
         AND demand_item.purchase_request_id = v_demand_id
         AND NOT EXISTS (
           SELECT 1
           FROM public.supplier_items AS supplier_item
           JOIN public.suppliers AS supplier
             ON supplier.id = supplier_item.supplier_id
            AND supplier.tenant_id = supplier_item.tenant_id
            AND supplier.is_active
           WHERE supplier_item.tenant_id = v_tenant
             AND supplier_item.ingredient_id = demand_item.ingredient_id
             AND supplier_item.is_active
         )
     ) THEN
    RAISE EXCEPTION 'supplier_item_mapping_required'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.purchase_requests
  SET status = v_status,
      status_reason = NULL,
      submitted_by = CASE
        WHEN v_was_pending THEN v_demand.submitted_by
        WHEN p_submit THEN v_uid
        ELSE NULL
      END,
      submitted_at = CASE
        WHEN v_was_pending THEN v_demand.submitted_at
        WHEN p_submit THEN pg_catalog.now()
        ELSE NULL
      END,
      updated_at = pg_catalog.now()
  WHERE id = v_demand_id
    AND tenant_id = v_tenant;

  IF NOT v_was_pending THEN
    PERFORM public.log_audit(
      CASE
        WHEN p_submit THEN 'procurement.demand.submitted'
        ELSE 'procurement.demand.draft_saved'
      END,
      'purchase_request',
      v_demand_id,
      NULL,
      pg_catalog.jsonb_build_object('status', v_status)
    );
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'demand_id', v_demand_id,
    'demand_number', v_saved ->> 'request_number',
    'status', v_status
  );
END;
$$;


--
-- Name: FUNCTION save_purchase_demand(p_demand_id bigint, p_branch_id bigint, p_needed_by date, p_notes text, p_lines jsonb, p_submit boolean, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_purchase_demand(p_demand_id bigint, p_branch_id bigint, p_needed_by date, p_notes text, p_lines jsonb, p_submit boolean, p_idempotency_key uuid) IS 'Atomically saves warehouse demand without assigning a supplier or price.';


--
-- Name: save_purchase_demand_allocations(bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_purchase_demand_allocations(p_demand_id bigint, p_allocations jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_demand public.purchase_requests%ROWTYPE;
  v_old jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_demand_id IS NULL
     OR p_idempotency_key IS NULL
     OR p_allocations IS NULL
     OR pg_catalog.jsonb_typeof(p_allocations) <> 'array'
     OR pg_catalog.jsonb_array_length(p_allocations) > 500 THEN
    RAISE EXCEPTION 'purchase_demand_allocations_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT demand.*
  INTO v_demand
  FROM public.purchase_requests AS demand
  WHERE demand.id = p_demand_id
    AND demand.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_demand_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    v_demand.branch_id,
    'procurement:po_approve'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_demand.status NOT IN (
    'submitted',
    'pending_allocation',
    'partially_ordered'
  ) THEN
    RAISE EXCEPTION 'purchase_demand_not_allocatable'
      USING ERRCODE = '23514';
  END IF;

  IF v_demand.allocation_save_idempotency_key = p_idempotency_key THEN
    RETURN private.purchase_demand_allocation_result(
      v_tenant,
      p_demand_id
    );
  END IF;

  IF (
    SELECT pg_catalog.count(*) <> pg_catalog.count(
      DISTINCT (allocation.request_item_id, allocation.supplier_id)
    )
    FROM pg_catalog.jsonb_to_recordset(p_allocations)
      AS allocation(
        request_item_id bigint,
        supplier_id bigint
      )
  )
  OR EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_allocations)
      AS allocation(
        request_item_id bigint,
        supplier_id bigint,
        quantity numeric
      )
    LEFT JOIN public.purchase_request_items AS demand_item
      ON demand_item.id = allocation.request_item_id
     AND demand_item.tenant_id = v_tenant
     AND demand_item.purchase_request_id = p_demand_id
    LEFT JOIN public.supplier_items AS supplier_item
      ON supplier_item.tenant_id = v_tenant
     AND supplier_item.supplier_id = allocation.supplier_id
     AND supplier_item.ingredient_id = demand_item.ingredient_id
     AND supplier_item.is_active
    LEFT JOIN public.suppliers AS supplier
      ON supplier.id = allocation.supplier_id
     AND supplier.tenant_id = v_tenant
     AND supplier.is_active
    WHERE allocation.request_item_id IS NULL
       OR allocation.supplier_id IS NULL
       OR allocation.quantity IS NULL
       OR allocation.quantity <= 0
       OR demand_item.id IS NULL
       OR supplier_item.id IS NULL
       OR supplier.id IS NULL
  )
  OR EXISTS (
    SELECT 1
    FROM public.purchase_request_items AS demand_item
    LEFT JOIN LATERAL (
      SELECT coalesce(
        pg_catalog.sum(allocation.quantity),
        0
      ) AS quantity
      FROM pg_catalog.jsonb_to_recordset(p_allocations)
        AS allocation(request_item_id bigint, quantity numeric)
      WHERE allocation.request_item_id = demand_item.id
    ) AS planned ON TRUE
    WHERE demand_item.tenant_id = v_tenant
      AND demand_item.purchase_request_id = p_demand_id
      AND planned.quantity >
        private.purchase_request_item_remaining_demand_qty(
          v_tenant,
          demand_item.id
        )
  ) THEN
    RAISE EXCEPTION 'purchase_demand_allocations_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(allocation))
  INTO v_old
  FROM public.purchase_request_allocations AS allocation
  WHERE allocation.tenant_id = v_tenant
    AND allocation.purchase_request_id = p_demand_id;

  DELETE FROM public.purchase_request_allocations
  WHERE tenant_id = v_tenant
    AND purchase_request_id = p_demand_id;

  INSERT INTO public.purchase_request_allocations (
    tenant_id,
    purchase_request_id,
    purchase_request_item_id,
    supplier_id,
    quantity,
    created_by
  )
  SELECT
    v_tenant,
    p_demand_id,
    allocation.request_item_id,
    allocation.supplier_id,
    allocation.quantity::numeric(15,3),
    v_uid
  FROM pg_catalog.jsonb_to_recordset(p_allocations)
    AS allocation(
      request_item_id bigint,
      supplier_id bigint,
      quantity numeric
    );

  UPDATE public.purchase_requests
  SET allocation_save_idempotency_key = p_idempotency_key,
      updated_at = pg_catalog.now()
  WHERE id = p_demand_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'procurement.demand.allocations_saved',
    'purchase_request',
    p_demand_id,
    v_old,
    p_allocations
  );

  RETURN private.purchase_demand_allocation_result(
    v_tenant,
    p_demand_id
  );
END;
$$;


--
-- Name: save_purchase_order(bigint, date, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_purchase_order(p_po_id bigint, p_expected_delivery_date date, p_notes text, p_lines jsonb, p_send boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_po public.purchase_orders%ROWTYPE;
  v_line_count integer;
  v_expected_count integer;
  v_status text;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT purchase_order.*
  INTO v_po
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.id = p_po_id
    AND purchase_order.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_po.branch_id, 'procurement:po_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_po.status NOT IN ('draft', 'sent')
     OR EXISTS (
       SELECT 1
       FROM public.goods_received_notes AS grn
       WHERE grn.tenant_id = v_tenant
         AND grn.po_id = p_po_id
         AND grn.status = 'confirmed'
     ) THEN
    RAISE EXCEPTION 'purchase_order_not_editable'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.purchase_orders
  SET expected_delivery_date = p_expected_delivery_date,
      notes = NULLIF(btrim(p_notes), ''),
      updated_at = now()
  WHERE id = p_po_id
    AND tenant_id = v_tenant;

  IF p_lines IS NOT NULL THEN
    IF jsonb_typeof(p_lines) <> 'array'
       OR EXISTS (
         SELECT 1
         FROM public.goods_received_notes AS grn
         WHERE grn.tenant_id = v_tenant
           AND grn.po_id = p_po_id
           AND grn.status = 'draft'
       ) THEN
      RAISE EXCEPTION 'purchase_order_lines_locked'
        USING ERRCODE = '23514';
    END IF;

    SELECT count(*), count(DISTINCT line.line_id)
    INTO v_line_count, v_expected_count
    FROM jsonb_to_recordset(p_lines)
      AS line(line_id bigint);

    IF v_line_count <> v_expected_count
       OR v_line_count <> (
         SELECT count(*)
         FROM public.purchase_order_items AS item
         WHERE item.po_id = p_po_id
           AND item.tenant_id = v_tenant
       )
       OR EXISTS (
         SELECT 1
         FROM jsonb_to_recordset(p_lines)
           AS line(line_id bigint, quantity numeric, unit_price numeric)
         LEFT JOIN public.purchase_order_items AS item
           ON item.id = line.line_id
          AND item.po_id = p_po_id
          AND item.tenant_id = v_tenant
         WHERE item.id IS NULL
            OR line.quantity IS NULL
            OR line.quantity <= 0
            OR line.unit_price IS NULL
            OR line.unit_price < 0
       ) THEN
      RAISE EXCEPTION 'purchase_order_lines_invalid'
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.purchase_order_items AS item
    SET quantity = line.quantity::numeric(15,3),
        unit_price_est = line.unit_price::numeric(15,2),
        line_total = round(line.quantity * line.unit_price, 2)
    FROM jsonb_to_recordset(p_lines)
      AS line(line_id bigint, quantity numeric, unit_price numeric)
    WHERE item.id = line.line_id
      AND item.po_id = p_po_id
      AND item.tenant_id = v_tenant;

    IF v_po.purchase_request_id IS NOT NULL THEN
      PERFORM private.recompute_purchase_request_status(
        v_po.purchase_request_id,
        v_tenant
      );
    END IF;
  END IF;

  IF p_send AND v_po.status = 'draft' THEN
    v_status := public.send_purchase_order(p_po_id) ->> 'status';
  ELSE
    v_status := v_po.status;
  END IF;

  PERFORM public.log_audit(
    'procurement.po.saved',
    'purchase_order',
    p_po_id,
    to_jsonb(v_po),
    jsonb_build_object(
      'status', v_status,
      'expected_delivery_date', p_expected_delivery_date,
      'line_count', CASE
        WHEN p_lines IS NULL THEN NULL
        ELSE jsonb_array_length(p_lines)
      END
    )
  );

  RETURN jsonb_build_object('id', p_po_id, 'status', v_status);
END;
$$;


--
-- Name: save_purchase_order_group(uuid, bigint, date, text, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_purchase_order_group(p_group_key uuid, p_branch_id bigint, p_expected_delivery_date date, p_notes text, p_lines jsonb, p_submit boolean DEFAULT true, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_group_key uuid := p_group_key;
  v_group_code text;
  v_status text := CASE
    WHEN p_submit THEN 'pending_approval'
    ELSE 'draft'
  END;
  v_missing jsonb;
  v_supplier record;
  v_po_id bigint;
  v_sequence smallint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_branch_id IS NULL
     OR p_lines IS NULL
     OR pg_catalog.jsonb_typeof(p_lines) <> 'array'
     OR pg_catalog.jsonb_array_length(p_lines) = 0
     OR pg_catalog.jsonb_array_length(p_lines) > 200
     OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'purchase_order_group_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(
    p_branch_id,
    'procurement:po_create'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.branches AS branch
    WHERE branch.id = p_branch_id
      AND branch.tenant_id = v_tenant
      AND branch.is_active
      AND branch.branch_kind IN ('central_supply', 'central_kitchen')
  ) THEN
    RAISE EXCEPTION 'purchase_order_central_site_required'
      USING ERRCODE = '23514';
  END IF;
  IF (
    SELECT count(*) <> count(DISTINCT line.ingredient_id)
    FROM pg_catalog.jsonb_to_recordset(p_lines)
      AS line(ingredient_id bigint)
  )
  OR EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_lines)
      AS line(
        ingredient_id bigint,
        quantity numeric,
        entry_unit_id bigint
      )
    WHERE line.ingredient_id IS NULL
       OR line.entry_unit_id IS NULL
       OR line.quantity IS NULL
       OR line.quantity <= 0
       OR NOT EXISTS (
         SELECT 1
         FROM public.ingredients AS ingredient
         JOIN public.ingredient_units AS ingredient_unit
           ON ingredient_unit.ingredient_id = ingredient.id
          AND ingredient_unit.tenant_id = ingredient.tenant_id
         WHERE ingredient.id = line.ingredient_id
           AND ingredient.tenant_id = v_tenant
           AND ingredient.is_active
           AND ingredient_unit.unit_id = line.entry_unit_id
           AND ingredient_unit.is_active
       )
  ) THEN
    RAISE EXCEPTION 'purchase_order_line_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT po.purchase_group_key
  INTO v_group_key
  FROM public.purchase_orders AS po
  WHERE po.tenant_id = v_tenant
    AND po.group_save_idempotency_key = p_idempotency_key
  ORDER BY po.group_sequence
  LIMIT 1;

  IF FOUND THEN
    RETURN private.po_group_result(v_tenant, v_group_key);
  END IF;

  SELECT pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'ingredient_id', ingredient.id,
      'ingredient_name', ingredient.name
    )
    ORDER BY ingredient.name, ingredient.id
  )
  INTO v_missing
  FROM pg_catalog.jsonb_to_recordset(p_lines)
    AS line(ingredient_id bigint)
  JOIN public.ingredients AS ingredient
    ON ingredient.id = line.ingredient_id
   AND ingredient.tenant_id = v_tenant
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.supplier_items AS supplier_item
    JOIN public.suppliers AS supplier
      ON supplier.id = supplier_item.supplier_id
     AND supplier.tenant_id = supplier_item.tenant_id
     AND supplier.is_active
    WHERE supplier_item.tenant_id = v_tenant
      AND supplier_item.ingredient_id = line.ingredient_id
      AND supplier_item.is_active
      AND supplier_item.is_preferred
  );

  IF v_missing IS NOT NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', FALSE,
      'error_code', 'supplier_default_missing',
      'missing_supplier_items', v_missing
    );
  END IF;

  IF p_group_key IS NULL THEN
    v_group_key := pg_catalog.gen_random_uuid();
    v_group_code := public.next_po_display_id(v_tenant);
  ELSE
    SELECT po.purchase_group_code
    INTO v_group_code
    FROM public.purchase_orders AS po
    WHERE po.tenant_id = v_tenant
      AND po.purchase_group_key = p_group_key
    ORDER BY po.group_sequence
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_order_group_not_found'
        USING ERRCODE = 'P0002';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.purchase_orders AS po
      WHERE po.tenant_id = v_tenant
        AND po.purchase_group_key = p_group_key
        AND po.status IN ('draft', 'changes_requested')
    ) THEN
      RAISE EXCEPTION 'purchase_order_group_not_editable'
        USING ERRCODE = '23514';
    END IF;

    DELETE FROM public.purchase_order_items AS po_item
    USING public.purchase_orders AS po
    WHERE po.id = po_item.po_id
      AND po.tenant_id = po_item.tenant_id
      AND po.tenant_id = v_tenant
      AND po.purchase_group_key = v_group_key
      AND po.status IN ('draft', 'changes_requested');
  END IF;

  FOR v_supplier IN
    SELECT
      supplier_item.supplier_id,
      pg_catalog.row_number() OVER (
        ORDER BY supplier_item.supplier_id
      )::smallint AS initial_sequence
    FROM pg_catalog.jsonb_to_recordset(p_lines)
      AS line(ingredient_id bigint)
    JOIN public.supplier_items AS supplier_item
      ON supplier_item.tenant_id = v_tenant
     AND supplier_item.ingredient_id = line.ingredient_id
     AND supplier_item.is_active
     AND supplier_item.is_preferred
    GROUP BY supplier_item.supplier_id
    ORDER BY supplier_item.supplier_id
  LOOP
    SELECT po.id, po.group_sequence
    INTO v_po_id, v_sequence
    FROM public.purchase_orders AS po
    WHERE po.tenant_id = v_tenant
      AND po.purchase_group_key = v_group_key
      AND po.supplier_id = v_supplier.supplier_id
      AND po.status IN ('draft', 'changes_requested')
    ORDER BY po.group_sequence
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      IF p_group_key IS NULL THEN
        v_sequence := v_supplier.initial_sequence;
      ELSE
        SELECT (
          coalesce(pg_catalog.max(po.group_sequence), 0) + 1
        )::smallint
        INTO v_sequence
        FROM public.purchase_orders AS po
        WHERE po.tenant_id = v_tenant
          AND po.purchase_group_key = v_group_key;
      END IF;
      IF v_sequence > 99 THEN
        RAISE EXCEPTION 'purchase_order_group_supplier_limit'
          USING ERRCODE = '54000';
      END IF;

      INSERT INTO public.purchase_orders (
        tenant_id,
        branch_id,
        supplier_id,
        po_number,
        display_id,
        ordered_at,
        expected_delivery_date,
        status,
        notes,
        created_by,
        purchase_group_key,
        purchase_group_code,
        group_sequence,
        group_save_idempotency_key,
        submitted_at,
        submitted_by
      )
      VALUES (
        v_tenant,
        p_branch_id,
        v_supplier.supplier_id,
        v_group_code || '-' || pg_catalog.lpad(v_sequence::text, 2, '0'),
        v_group_code || '-' || pg_catalog.lpad(v_sequence::text, 2, '0'),
        pg_catalog.now(),
        p_expected_delivery_date,
        v_status,
        nullif(pg_catalog.btrim(p_notes), ''),
        v_uid,
        v_group_key,
        v_group_code,
        v_sequence,
        p_idempotency_key,
        CASE WHEN p_submit THEN pg_catalog.now() ELSE NULL END,
        CASE WHEN p_submit THEN v_uid ELSE NULL END
      )
      RETURNING id INTO v_po_id;
    ELSE
      DELETE FROM public.purchase_order_items AS po_item
      WHERE po_item.tenant_id = v_tenant
        AND po_item.po_id = v_po_id;

      UPDATE public.purchase_orders
      SET branch_id = p_branch_id,
          expected_delivery_date = p_expected_delivery_date,
          notes = nullif(pg_catalog.btrim(p_notes), ''),
          status = v_status,
          status_reason = NULL,
          group_save_idempotency_key = p_idempotency_key,
          submitted_at = CASE
            WHEN p_submit THEN pg_catalog.now()
            ELSE submitted_at
          END,
          submitted_by = CASE
            WHEN p_submit THEN v_uid
            ELSE submitted_by
          END,
          updated_at = pg_catalog.now()
      WHERE id = v_po_id
        AND tenant_id = v_tenant;
    END IF;

    INSERT INTO public.purchase_order_items (
      tenant_id,
      po_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      unit_price_est,
      line_total
    )
    SELECT
      v_tenant,
      v_po_id,
      line.ingredient_id,
      line.quantity::numeric(15,3),
      line.entry_unit_id,
      NULL,
      NULL
    FROM pg_catalog.jsonb_to_recordset(p_lines)
      AS line(
        ingredient_id bigint,
        quantity numeric,
        entry_unit_id bigint
      )
    JOIN public.supplier_items AS supplier_item
      ON supplier_item.tenant_id = v_tenant
     AND supplier_item.ingredient_id = line.ingredient_id
     AND supplier_item.supplier_id = v_supplier.supplier_id
     AND supplier_item.is_active
     AND supplier_item.is_preferred
    ORDER BY line.ingredient_id;
  END LOOP;

  UPDATE public.purchase_orders AS po
  SET status = 'cancelled',
      status_reason = 'NCC mặc định đã thay đổi khi gửi lại',
      cancelled_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  WHERE po.tenant_id = v_tenant
    AND po.purchase_group_key = v_group_key
    AND po.status IN ('draft', 'changes_requested')
    AND NOT EXISTS (
      SELECT 1
      FROM public.purchase_order_items AS po_item
      WHERE po_item.tenant_id = v_tenant
        AND po_item.po_id = po.id
    );

  PERFORM public.log_audit(
    CASE
      WHEN p_group_key IS NULL
        THEN 'procurement.po_group.created'
      ELSE 'procurement.po_group.resubmitted'
    END,
    'purchase_order_group',
    NULL,
    NULL,
    pg_catalog.jsonb_build_object(
      'purchase_group_key', v_group_key,
      'purchase_group_code', v_group_code,
      'status', v_status
    )
  );

  RETURN private.po_group_result(v_tenant, v_group_key);
END;
$$;


--
-- Name: FUNCTION save_purchase_order_group(p_group_key uuid, p_branch_id bigint, p_expected_delivery_date date, p_notes text, p_lines jsonb, p_submit boolean, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_purchase_order_group(p_group_key uuid, p_branch_id bigint, p_expected_delivery_date date, p_notes text, p_lines jsonb, p_submit boolean, p_idempotency_key uuid) IS 'Atomically saves one warehouse purchase group as one PO per preferred supplier. Missing preferred suppliers return structured validation and create no rows.';


--
-- Name: save_purchase_orders_from_request(bigint, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_purchase_orders_from_request(p_request_id bigint, p_orders jsonb, p_send boolean DEFAULT true, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_result jsonb;
  v_po jsonb;
  v_po_id bigint;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_orders IS NULL
     OR jsonb_typeof(p_orders) <> 'array'
     OR jsonb_array_length(p_orders) = 0
     OR jsonb_array_length(p_orders) > 100 THEN
    RAISE EXCEPTION 'purchase_orders_invalid' USING ERRCODE = '22023';
  END IF;

  IF p_idempotency_key IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.purchase_orders AS purchase_order
       WHERE purchase_order.tenant_id = v_tenant
         AND purchase_order.purchase_request_id = p_request_id
         AND purchase_order.save_idempotency_key = p_idempotency_key
     ) THEN
    SELECT jsonb_build_object(
      'purchase_orders',
      jsonb_agg(
        jsonb_build_object(
          'po_id', purchase_order.id,
          'po_number', purchase_order.po_number,
          'status', purchase_order.status
        )
        ORDER BY purchase_order.id
      )
    )
    INTO v_result
    FROM public.purchase_orders AS purchase_order
    WHERE purchase_order.tenant_id = v_tenant
      AND purchase_order.purchase_request_id = p_request_id
      AND purchase_order.save_idempotency_key = p_idempotency_key;
    RETURN v_result;
  END IF;

  v_result := public.create_purchase_orders_from_request(
    p_request_id,
    p_orders
  );

  FOR v_po IN
    SELECT value
    FROM jsonb_array_elements(v_result -> 'purchase_orders')
  LOOP
    v_po_id := (v_po ->> 'po_id')::bigint;
    UPDATE public.purchase_orders
    SET save_idempotency_key = p_idempotency_key
    WHERE id = v_po_id
      AND tenant_id = v_tenant;

    IF p_send THEN
      v_po := v_po || public.send_purchase_order(v_po_id);
    END IF;
    v_results := v_results || jsonb_build_array(v_po);
  END LOOP;

  RETURN jsonb_build_object('purchase_orders', v_results);
END;
$$;


--
-- Name: save_purchase_request(bigint, bigint, date, text, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_purchase_request(p_request_id bigint, p_branch_id bigint, p_needed_by date, p_notes text, p_lines jsonb, p_submit boolean DEFAULT true, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request public.purchase_requests%ROWTYPE;
  v_request_id bigint;
  v_number text;
  v_status text;
  v_old jsonb;
  v_was_pending boolean := FALSE;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_branch_id IS NULL
     OR p_lines IS NULL
     OR pg_catalog.jsonb_typeof(p_lines) <> 'array'
     OR pg_catalog.jsonb_array_length(p_lines) = 0
     OR pg_catalog.jsonb_array_length(p_lines) > 200 THEN
    RAISE EXCEPTION 'purchase_request_invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(
    p_branch_id,
    'procurement:request_manage'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.branches AS branch
    WHERE branch.id = p_branch_id
      AND branch.tenant_id = v_tenant
      AND branch.is_active
      AND branch.branch_kind IN ('central_supply', 'central_kitchen')
  ) THEN
    RAISE EXCEPTION 'purchase_request_central_site_required'
      USING ERRCODE = '23514';
  END IF;
  IF (
    SELECT pg_catalog.count(*) <>
      pg_catalog.count(DISTINCT line.ingredient_id)
    FROM pg_catalog.jsonb_to_recordset(p_lines)
      AS line(ingredient_id bigint)
  )
  OR EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_lines)
      AS line(
        ingredient_id bigint,
        quantity numeric,
        entry_unit_id bigint
      )
    WHERE line.ingredient_id IS NULL
       OR line.entry_unit_id IS NULL
       OR line.quantity IS NULL
       OR line.quantity <= 0
       OR NOT EXISTS (
         SELECT 1
         FROM public.ingredients AS ingredient
         JOIN public.ingredient_units AS ingredient_unit
           ON ingredient_unit.ingredient_id = ingredient.id
          AND ingredient_unit.tenant_id = ingredient.tenant_id
         WHERE ingredient.id = line.ingredient_id
           AND ingredient.tenant_id = v_tenant
           AND ingredient.is_active
           AND ingredient_unit.unit_id = line.entry_unit_id
           AND ingredient_unit.is_active
       )
  ) THEN
    RAISE EXCEPTION 'purchase_request_line_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF p_request_id IS NULL
     AND p_idempotency_key IS NOT NULL THEN
    SELECT request.*
    INTO v_request
    FROM public.purchase_requests AS request
    WHERE request.tenant_id = v_tenant
      AND request.creation_idempotency_key = p_idempotency_key
    FOR UPDATE;

    IF FOUND THEN
      RETURN pg_catalog.jsonb_build_object(
        'request_id', v_request.id,
        'request_number', v_request.request_number,
        'status', v_request.status
      );
    END IF;
  END IF;

  IF p_request_id IS NULL THEN
    v_number := public.next_inventory_doc_number(
      v_tenant,
      'purchase_request'
    );
    INSERT INTO public.purchase_requests (
      tenant_id,
      branch_id,
      request_number,
      status,
      needed_by,
      notes,
      created_by,
      creation_idempotency_key
    )
    VALUES (
      v_tenant,
      p_branch_id,
      v_number,
      'draft',
      p_needed_by,
      nullif(pg_catalog.btrim(p_notes), ''),
      v_uid,
      p_idempotency_key
    )
    RETURNING id INTO v_request_id;
    v_old := NULL;
  ELSE
    SELECT request.*
    INTO v_request
    FROM public.purchase_requests AS request
    WHERE request.id = p_request_id
      AND request.tenant_id = v_tenant
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_request_not_found'
        USING ERRCODE = 'P0002';
    END IF;
    v_old := pg_catalog.to_jsonb(v_request);
    v_was_pending := v_request.status = 'pending_allocation';

    IF v_request.status IN ('submitted', 'pending_allocation')
       AND EXISTS (
         SELECT 1
         FROM public.purchase_request_allocations AS allocation
         WHERE allocation.tenant_id = v_tenant
           AND allocation.purchase_request_id = p_request_id
       ) THEN
      RAISE EXCEPTION 'purchase_demand_allocation_started'
        USING ERRCODE = '23514';
    END IF;

    IF v_request.branch_id <> p_branch_id
       OR v_request.status NOT IN (
         'draft',
         'submitted',
         'pending_allocation'
       )
       OR EXISTS (
         SELECT 1
         FROM public.purchase_orders AS purchase_order
         WHERE purchase_order.tenant_id = v_tenant
           AND purchase_order.purchase_request_id = p_request_id
           AND purchase_order.status <> 'cancelled'
       ) THEN
      RAISE EXCEPTION 'purchase_request_not_editable'
        USING ERRCODE = '23514';
    END IF;

    v_request_id := p_request_id;
    v_number := v_request.request_number;
    DELETE FROM public.purchase_request_items
    WHERE purchase_request_id = v_request_id
      AND tenant_id = v_tenant;

    UPDATE public.purchase_requests
    SET needed_by = p_needed_by,
        notes = nullif(pg_catalog.btrim(p_notes), ''),
        updated_at = pg_catalog.now()
    WHERE id = v_request_id
      AND tenant_id = v_tenant;
  END IF;

  INSERT INTO public.purchase_request_items (
    tenant_id,
    purchase_request_id,
    ingredient_id,
    quantity,
    entry_unit_id,
    notes
  )
  SELECT
    v_tenant,
    v_request_id,
    line.ingredient_id,
    line.quantity::numeric(15,3),
    line.entry_unit_id,
    nullif(pg_catalog.btrim(line.notes), '')
  FROM pg_catalog.jsonb_to_recordset(p_lines)
    AS line(
      ingredient_id bigint,
      quantity numeric,
      entry_unit_id bigint,
      notes text
    );

  v_status := CASE
    WHEN v_was_pending THEN 'pending_allocation'
    WHEN p_submit THEN 'submitted'
    ELSE 'draft'
  END;
  UPDATE public.purchase_requests
  SET status = v_status,
      submitted_by = CASE
        WHEN v_was_pending THEN v_request.submitted_by
        WHEN p_submit THEN v_uid
        ELSE NULL
      END,
      submitted_at = CASE
        WHEN v_was_pending THEN v_request.submitted_at
        WHEN p_submit THEN pg_catalog.now()
        ELSE NULL
      END,
      updated_at = pg_catalog.now()
  WHERE id = v_request_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    CASE
      WHEN v_was_pending THEN
        'procurement.demand.updated_pending_allocation'
      WHEN p_request_id IS NULL AND p_submit THEN
        'procurement.request.created_submitted'
      WHEN p_request_id IS NULL THEN
        'procurement.request.created_draft'
      WHEN p_submit THEN
        'procurement.request.saved_submitted'
      ELSE
        'procurement.request.saved_draft'
    END,
    'purchase_request',
    v_request_id,
    v_old,
    pg_catalog.jsonb_build_object(
      'status', v_status,
      'branch_id', p_branch_id,
      'line_count', pg_catalog.jsonb_array_length(p_lines)
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'request_id', v_request_id,
    'request_number', v_number,
    'status', v_status
  );
END;
$$;


--
-- Name: save_station_categories(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_station_categories(p_station_id bigint, p_category_ids bigint[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_station RECORD;
  v_distinct_category_count INT;
  v_valid_category_count INT;
BEGIN
  SELECT id, tenant_id, branch_id
    INTO v_station
  FROM public.kds_stations
  WHERE id = p_station_id
    AND tenant_id = public.auth_tenant_id();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Station not found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    SELECT COUNT(DISTINCT x.category_id)
      INTO v_distinct_category_count
    FROM unnest(p_category_ids) AS x(category_id)
    WHERE x.category_id IS NOT NULL;

    SELECT COUNT(DISTINCT c.id)
      INTO v_valid_category_count
    FROM public.menu_categories c
    WHERE c.tenant_id = v_station.tenant_id
      AND c.id = ANY(p_category_ids);

    IF v_valid_category_count <> v_distinct_category_count THEN
      RAISE EXCEPTION 'Invalid station category' USING ERRCODE = '22023';
    END IF;
  END IF;

  DELETE FROM public.kds_station_categories
  WHERE station_id = p_station_id
    AND tenant_id = v_station.tenant_id;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    INSERT INTO public.kds_station_categories (tenant_id, station_id, category_id)
    SELECT DISTINCT v_station.tenant_id, p_station_id, x.category_id
    FROM unnest(p_category_ids) AS x(category_id)
    WHERE x.category_id IS NOT NULL
    ON CONFLICT (station_id, category_id, tenant_id) DO NOTHING;
  END IF;
END;
$$;


--
-- Name: save_stock_issue_line(bigint, bigint, numeric, bigint, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_stock_issue_line(p_issue_id bigint, p_ingredient_id bigint, p_quantity numeric, p_entry_unit_id bigint, p_reason text DEFAULT NULL::text, p_photo_urls text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_issue public.stock_issues%ROWTYPE;
  v_base_quantity numeric;
  v_available_quantity numeric;
  v_item_id bigint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_quantity IS NULL
     OR p_quantity <= 0
     OR p_quantity = 'NaN'::numeric
     OR p_quantity = 'Infinity'::numeric
     OR p_quantity = '-Infinity'::numeric THEN
    RAISE EXCEPTION 'issue_line_quantity_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_photo_urls IS NOT NULL
     AND pg_catalog.cardinality(p_photo_urls) > 1 THEN
    RAISE EXCEPTION 'issue_line_photo_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT issue.*
  INTO v_issue
  FROM public.stock_issues AS issue
  WHERE issue.id = p_issue_id
    AND issue.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_issue.created_by IS DISTINCT FROM v_uid
     OR NOT public.has_permission(v_issue.branch_id, 'inventory:write') THEN
    RAISE EXCEPTION 'forbidden_inventory_write' USING ERRCODE = '42501';
  END IF;
  IF v_issue.status <> 'draft' THEN
    RAISE EXCEPTION 'issue_not_draft' USING ERRCODE = '22023';
  END IF;
  IF v_issue.issue_type = 'writeoff'
     AND v_issue.approval_status <> 'not_required' THEN
    RAISE EXCEPTION 'writeoff_locked' USING ERRCODE = '42501';
  END IF;
  IF v_issue.source_location_id IS NULL THEN
    RAISE EXCEPTION 'issue_source_location_missing' USING ERRCODE = '23502';
  END IF;

  PERFORM location.id
  FROM public.inventory_locations AS location
  WHERE location.id = v_issue.source_location_id
    AND location.tenant_id = v_tenant
    AND location.branch_id = v_issue.branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_source_location_invalid' USING ERRCODE = '23514';
  END IF;

  PERFORM ingredient.id
  FROM public.ingredients AS ingredient
  JOIN public.ingredient_units AS ingredient_unit
    ON ingredient_unit.tenant_id = ingredient.tenant_id
   AND ingredient_unit.ingredient_id = ingredient.id
   AND ingredient_unit.unit_id = p_entry_unit_id
   AND ingredient_unit.is_active IS TRUE
  JOIN public.units AS unit
    ON unit.tenant_id = ingredient_unit.tenant_id
   AND unit.id = ingredient_unit.unit_id
   AND unit.is_active IS TRUE
  WHERE ingredient.id = p_ingredient_id
    AND ingredient.tenant_id = v_tenant
    AND ingredient.is_active IS TRUE
    AND p_entry_unit_id IN (
      ingredient.issue_unit_id,
      ingredient.receipt_unit_id
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_line_unit_invalid' USING ERRCODE = '23503';
  END IF;

  v_base_quantity := public.inv_to_base_for_tenant(
    v_tenant,
    p_ingredient_id,
    p_entry_unit_id,
    p_quantity
  );

  SELECT stock.current_quantity
  INTO v_available_quantity
  FROM public.stock_levels AS stock
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = v_issue.branch_id
    AND stock.location_id = v_issue.source_location_id
    AND stock.ingredient_id = p_ingredient_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_base_quantity > v_available_quantity THEN
    RAISE EXCEPTION 'insufficient_stock' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.stock_issue_items (
    tenant_id,
    issue_id,
    ingredient_id,
    quantity,
    entry_unit_id,
    unit_cost,
    reason,
    photo_urls
  ) VALUES (
    v_tenant,
    p_issue_id,
    p_ingredient_id,
    p_quantity,
    p_entry_unit_id,
    0,
    nullif(pg_catalog.btrim(p_reason), ''),
    coalesce(p_photo_urls, ARRAY[]::text[])
  )
  ON CONFLICT (issue_id, ingredient_id, tenant_id)
  DO UPDATE SET
    quantity = EXCLUDED.quantity,
    entry_unit_id = EXCLUDED.entry_unit_id,
    reason = EXCLUDED.reason,
    photo_urls = CASE
      WHEN p_photo_urls IS NULL
        THEN stock_issue_items.photo_urls
      ELSE EXCLUDED.photo_urls
    END
  RETURNING id INTO v_item_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'item_id', v_item_id
  );
END;
$$;


--
-- Name: FUNCTION save_stock_issue_line(p_issue_id bigint, p_ingredient_id bigint, p_quantity numeric, p_entry_unit_id bigint, p_reason text, p_photo_urls text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_stock_issue_line(p_issue_id bigint, p_ingredient_id bigint, p_quantity numeric, p_entry_unit_id bigint, p_reason text, p_photo_urls text[]) IS 'Saves one draft stock-issue line after enforcing actor, tenant, issue-unit, location, and stock boundaries.';


--
-- Name: save_stock_request(bigint, bigint, timestamp with time zone, text, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_stock_request(p_request_id bigint, p_branch_id bigint, p_needed_at timestamp with time zone, p_notes text, p_lines jsonb, p_submit boolean DEFAULT true, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request public.stock_requests%ROWTYPE;
  v_request_id bigint;
  v_number text;
  v_status text;
  v_requester_kind text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_branch_id IS NULL
     OR p_lines IS NULL
     OR jsonb_typeof(p_lines) <> 'array'
     OR jsonb_array_length(p_lines) = 0
     OR jsonb_array_length(p_lines) > 200 THEN
    RAISE EXCEPTION 'stock_request_invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT public.auth_is_owner(v_uid)
     AND (
       NOT public.has_permission(p_branch_id, 'inventory:request_create')
       OR (
         p_submit
         AND NOT public.has_permission(p_branch_id, 'inventory:request_submit')
       )
     ) THEN
    RAISE EXCEPTION 'forbidden_request_save' USING ERRCODE = '42501';
  END IF;

  SELECT branch.branch_kind
  INTO v_requester_kind
  FROM public.branches AS branch
  WHERE branch.id = p_branch_id
    AND branch.tenant_id = v_tenant
    AND branch.is_active
    AND branch.branch_kind IN ('branch', 'central_kitchen');

  IF v_requester_kind IS NULL THEN
    RAISE EXCEPTION 'stock_request_requester_site_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF (
    SELECT count(*) <> count(DISTINCT line.ingredient_id)
    FROM jsonb_to_recordset(p_lines) AS line(ingredient_id bigint)
  )
  OR EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_lines)
      AS line(
        ingredient_id bigint,
        entry_unit_id bigint,
        quantity numeric
      )
    WHERE line.ingredient_id IS NULL
       OR line.entry_unit_id IS NULL
       OR line.quantity IS NULL
       OR line.quantity <= 0
       OR NOT EXISTS (
         SELECT 1
         FROM public.ingredients AS ingredient
         JOIN public.ingredient_units AS ingredient_unit
           ON ingredient_unit.ingredient_id = ingredient.id
          AND ingredient_unit.tenant_id = ingredient.tenant_id
         WHERE ingredient.id = line.ingredient_id
           AND ingredient.tenant_id = v_tenant
           AND ingredient.is_active
           AND ingredient.default_fulfill_site_kind IN (
             'central_supply',
             'central_kitchen'
           )
           AND (
             v_requester_kind <> 'central_kitchen'
             OR ingredient.default_fulfill_site_kind = 'central_supply'
           )
           AND ingredient_unit.unit_id = line.entry_unit_id
           AND ingredient_unit.is_active
       )
  ) THEN
    RAISE EXCEPTION 'stock_request_line_invalid'
      USING ERRCODE = '23514';
  END IF;

  IF p_request_id IS NULL AND p_idempotency_key IS NOT NULL THEN
    SELECT request.*
    INTO v_request
    FROM public.stock_requests AS request
    WHERE request.tenant_id = v_tenant
      AND request.creation_idempotency_key = p_idempotency_key
    FOR UPDATE;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'request_id', v_request.id,
        'request_number', v_request.request_number,
        'status', v_request.status
      );
    END IF;
  END IF;

  IF p_request_id IS NULL THEN
    v_number := public.next_inventory_doc_number(v_tenant, 'stock_request');
    INSERT INTO public.stock_requests (
      tenant_id,
      branch_id,
      request_number,
      status,
      needed_at,
      notes,
      created_by,
      creation_idempotency_key
    )
    VALUES (
      v_tenant,
      p_branch_id,
      v_number,
      'draft',
      p_needed_at,
      NULLIF(btrim(p_notes), ''),
      v_uid,
      p_idempotency_key
    )
    ON CONFLICT (tenant_id, creation_idempotency_key)
      WHERE creation_idempotency_key IS NOT NULL
      DO NOTHING
    RETURNING id INTO v_request_id;

    IF v_request_id IS NULL THEN
      SELECT request.*
      INTO v_request
      FROM public.stock_requests AS request
      WHERE request.tenant_id = v_tenant
        AND request.creation_idempotency_key = p_idempotency_key
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'stock_request_idempotency_conflict'
          USING ERRCODE = '40001';
      END IF;

      RETURN jsonb_build_object(
        'request_id', v_request.id,
        'request_number', v_request.request_number,
        'status', v_request.status
      );
    END IF;
  ELSE
    SELECT request.*
    INTO v_request
    FROM public.stock_requests AS request
    WHERE request.id = p_request_id
      AND request.tenant_id = v_tenant
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'stock_request_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_request.branch_id <> p_branch_id
       OR v_request.status NOT IN ('draft', 'submitted')
       OR EXISTS (
         SELECT 1
         FROM public.stock_request_items AS item
         WHERE item.request_id = p_request_id
           AND item.tenant_id = v_tenant
           AND item.status <> 'pending'
       ) THEN
      RAISE EXCEPTION 'stock_request_not_editable'
        USING ERRCODE = '23514';
    END IF;

    v_request_id := p_request_id;
    v_number := v_request.request_number;

    DELETE FROM public.stock_request_items
    WHERE request_id = v_request_id
      AND tenant_id = v_tenant;
  END IF;

  INSERT INTO public.stock_request_items (
    tenant_id,
    request_id,
    ingredient_id,
    entry_unit_id,
    quantity,
    fulfill_site_kind,
    status,
    notes
  )
  SELECT
    v_tenant,
    v_request_id,
    line.ingredient_id,
    line.entry_unit_id,
    line.quantity::numeric(15,3),
    ingredient.default_fulfill_site_kind,
    'pending',
    NULLIF(btrim(line.notes), '')
  FROM jsonb_to_recordset(p_lines)
    AS line(
      ingredient_id bigint,
      entry_unit_id bigint,
      quantity numeric,
      notes text
    )
  JOIN public.ingredients AS ingredient
    ON ingredient.id = line.ingredient_id
   AND ingredient.tenant_id = v_tenant;

  v_status := CASE
    WHEN p_submit OR v_request.status = 'submitted' THEN 'submitted'
    ELSE 'draft'
  END;

  UPDATE public.stock_requests
  SET status = v_status,
      needed_at = p_needed_at,
      notes = NULLIF(btrim(p_notes), ''),
      submitted_at = CASE
        WHEN v_status = 'submitted' THEN COALESCE(submitted_at, now())
        ELSE NULL
      END,
      status_reason = NULL,
      updated_at = now()
  WHERE id = v_request_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    CASE
      WHEN p_request_id IS NULL AND p_submit
        THEN 'inventory.request.created_submitted'
      WHEN p_request_id IS NULL THEN 'inventory.request.created_draft'
      WHEN p_submit THEN 'inventory.request.saved_submitted'
      ELSE 'inventory.request.saved_draft'
    END,
    'stock_request',
    v_request_id,
    CASE WHEN p_request_id IS NULL THEN NULL ELSE to_jsonb(v_request) END,
    jsonb_build_object(
      'status', v_status,
      'branch_id', p_branch_id,
      'line_count', jsonb_array_length(p_lines),
      'needed_at', p_needed_at
    )
  );

  RETURN jsonb_build_object(
    'request_id', v_request_id,
    'request_number', v_number,
    'status', v_status
  );
END;
$$;


--
-- Name: save_supplier_invoice_draft(bigint, jsonb, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_supplier_invoice_draft(p_invoice_id bigint, p_invoice jsonb, p_lines jsonb, p_allocations jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_raw_discount numeric;
  v_client_subtotal numeric;
  v_client_vat numeric;
  v_client_total numeric;
  v_derived_subtotal numeric;
  v_derived_vat numeric;
  v_derived_gross numeric;
  v_derived_total numeric;
  v_result jsonb;
  v_invoice_id bigint;
  v_updated_count integer;
BEGIN
  IF p_idempotency_key IS NULL
    OR pg_catalog.jsonb_typeof(p_invoice) <> 'object'
    OR pg_catalog.jsonb_typeof(p_lines) <> 'array'
    OR pg_catalog.jsonb_array_length(p_lines) = 0
    OR pg_catalog.jsonb_array_length(p_lines) > 200
    OR pg_catalog.jsonb_typeof(p_allocations) <> 'array' THEN
    RAISE EXCEPTION 'supplier_invoice_draft_invalid'
      USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_raw_discount := COALESCE(
      (p_invoice->>'document_discount_amount')::numeric,
      0::numeric
    );
    v_client_subtotal := (p_invoice->>'subtotal')::numeric;
    v_client_vat := (p_invoice->>'vat_amount')::numeric;
    v_client_total := (p_invoice->>'total_amount')::numeric;
  EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'supplier_invoice_header_invalid'
        USING ERRCODE = '22023';
  END;

  IF v_raw_discount <> pg_catalog.round(v_raw_discount, 2)
    OR v_client_subtotal <> pg_catalog.round(v_client_subtotal, 2)
    OR v_client_vat <> pg_catalog.round(v_client_vat, 2)
    OR v_client_total <> pg_catalog.round(v_client_total, 2) THEN
    RAISE EXCEPTION 'supplier_invoice_money_scale_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_lines) AS line(
      quantity numeric,
      unit_price numeric,
      gross_line_total numeric,
      line_discount numeric,
      vat_rate numeric,
      vat_amount numeric,
      line_total numeric
    )
    WHERE line.quantity IS NULL
       OR line.quantity <= 0
       OR line.quantity <> pg_catalog.round(line.quantity, 3)
       OR line.unit_price IS NULL
       OR line.unit_price < 0
       OR line.unit_price <> pg_catalog.round(line.unit_price, 2)
       OR line.gross_line_total IS NULL
       OR line.gross_line_total < 0
       OR line.gross_line_total <> pg_catalog.round(line.gross_line_total, 2)
       OR line.line_discount IS NULL
       OR line.line_discount < 0
       OR line.line_discount <> pg_catalog.round(line.line_discount, 2)
       OR line.vat_amount IS NULL
       OR line.vat_amount < 0
       OR line.vat_amount <> pg_catalog.round(line.vat_amount, 2)
       OR line.line_total IS NULL
       OR line.line_total < 0
       OR line.line_total <> pg_catalog.round(line.line_total, 2)
  ) OR EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_allocations) AS allocation(
      quantity numeric
    )
    WHERE allocation.quantity IS NULL
       OR allocation.quantity <= 0
       OR allocation.quantity <> pg_catalog.round(allocation.quantity, 3)
  ) THEN
    RAISE EXCEPTION 'supplier_invoice_money_scale_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_lines) AS line(
      quantity numeric,
      unit_price numeric,
      gross_line_total numeric,
      line_discount numeric,
      vat_rate numeric,
      vat_amount numeric,
      line_total numeric
    )
    WHERE line.vat_rate NOT IN (0, 5, 8, 10)
       OR (line.vat_rate = 0 AND line.vat_amount <> 0)
       OR line.line_discount
          > pg_catalog.round(line.quantity * line.unit_price, 2)
       OR pg_catalog.abs(
          line.line_total
            - GREATEST(
              pg_catalog.round(line.quantity * line.unit_price, 2) - line.line_discount,
              0::numeric
            )
       ) > 1
       OR line.gross_line_total
          IS DISTINCT FROM line.line_total + line.vat_amount
  ) THEN
    RAISE EXCEPTION 'supplier_invoice_line_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    pg_catalog.sum(line.line_total),
    pg_catalog.sum(line.vat_amount),
    pg_catalog.sum(line.gross_line_total)
  INTO v_derived_subtotal, v_derived_vat, v_derived_gross
  FROM pg_catalog.jsonb_to_recordset(p_lines) AS line(
    line_total numeric,
    vat_amount numeric,
    gross_line_total numeric
  );
  v_derived_total := v_derived_gross - v_raw_discount;

  IF v_derived_subtotal <= 0
    OR v_derived_gross
       IS DISTINCT FROM v_derived_subtotal + v_derived_vat
    OR v_raw_discount < 0
    OR v_raw_discount > v_derived_subtotal
    OR v_derived_total < 0
    OR v_client_subtotal IS DISTINCT FROM v_derived_subtotal
    OR v_client_vat IS DISTINCT FROM v_derived_vat
    OR v_client_total IS DISTINCT FROM v_derived_total THEN
    RAISE EXCEPTION 'supplier_invoice_total_mismatch'
      USING ERRCODE = '23514';
  END IF;

  v_result := public.save_supplier_invoice_draft_unchecked(
    p_invoice_id,
    p_invoice,
    p_lines,
    p_allocations,
    p_idempotency_key
  );

  IF COALESCE((v_result->>'replayed')::boolean, FALSE) THEN
    RETURN v_result;
  END IF;

  v_invoice_id := (v_result->>'invoice_id')::bigint;

  UPDATE public.supplier_invoice_lines AS stored
  SET gross_line_total = source.gross_line_total,
      line_discount_amount = source.line_discount
  FROM pg_catalog.jsonb_to_recordset(p_lines) AS source(
    line_key text,
    gross_line_total numeric,
    line_discount numeric
  )
  WHERE stored.supplier_invoice_id = v_invoice_id
    AND stored.tenant_id = public.auth_tenant_id()
    AND stored.source_line_key = source.line_key;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> pg_catalog.jsonb_array_length(p_lines) THEN
    RAISE EXCEPTION 'supplier_invoice_line_update_mismatch'
      USING ERRCODE = '23514';
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION save_supplier_invoice_draft(p_invoice_id bigint, p_invoice jsonb, p_lines jsonb, p_allocations jsonb, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_supplier_invoice_draft(p_invoice_id bigint, p_invoice jsonb, p_lines jsonb, p_allocations jsonb, p_idempotency_key uuid) IS 'Validates additive-VAT supplier invoice lines: net unit_price, line_total = qty*unit_price - discount, gross_line_total = line_total + vat_amount.';


--
-- Name: save_supplier_invoice_draft_unchecked(bigint, jsonb, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_supplier_invoice_draft_unchecked(p_invoice_id bigint, p_invoice jsonb, p_lines jsonb, p_allocations jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_invoice_id bigint := p_invoice_id;
  v_supplier_id bigint;
  v_kind text;
  v_discount numeric(15,2);
  v_subtotal numeric(15,2);
  v_vat numeric(15,2);
  v_total numeric(15,2);
  v_vat_breakdown jsonb;
  v_first_allocation jsonb;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL
     OR pg_catalog.jsonb_typeof(p_invoice) <> 'object'
     OR pg_catalog.jsonb_typeof(p_lines) <> 'array'
     OR pg_catalog.jsonb_array_length(p_lines) = 0
     OR pg_catalog.jsonb_array_length(p_lines) > 200
     OR pg_catalog.jsonb_typeof(p_allocations) <> 'array' THEN
    RAISE EXCEPTION 'supplier_invoice_draft_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT invoice.id
  INTO v_invoice_id
  FROM public.supplier_invoices AS invoice
  WHERE invoice.tenant_id = v_tenant
    AND invoice.save_idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'invoice_id', v_invoice_id,
      'document_status', 'draft',
      'replayed', TRUE
    );
  END IF;

  v_supplier_id := (p_invoice->>'supplier_id')::bigint;
  v_kind := p_invoice->>'invoice_kind';
  v_discount := coalesce(
    (p_invoice->>'document_discount_amount')::numeric,
    0
  );
  IF v_kind NOT IN ('goods', 'service')
     OR v_supplier_id IS NULL
     OR v_discount < 0
     OR (p_invoice->>'invoice_date')::date IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM public.suppliers AS supplier
       WHERE supplier.id = v_supplier_id
         AND supplier.tenant_id = v_tenant
         AND supplier.is_active
     ) THEN
    RAISE EXCEPTION 'supplier_invoice_header_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_lines) AS line(
      line_key text,
      ingredient_id bigint,
      description text,
      quantity numeric,
      unit_id bigint,
      unit_price numeric,
      line_discount numeric,
      vat_rate numeric,
      vat_amount numeric,
      line_total numeric
    )
    WHERE nullif(pg_catalog.btrim(line.line_key), '') IS NULL
       OR nullif(pg_catalog.btrim(line.description), '') IS NULL
       OR line.quantity IS NULL
       OR line.quantity <= 0
       OR line.unit_price IS NULL
       OR line.unit_price < 0
       OR line.line_discount IS NULL
       OR line.line_discount < 0
       OR line.vat_rate NOT IN (0, 5, 8, 10)
       OR line.vat_amount IS NULL
       OR line.vat_amount < 0
       OR (line.vat_rate = 0 AND line.vat_amount <> 0)
       OR line.line_total IS NULL
       OR pg_catalog.abs(
         line.line_total
           - (
             line.quantity * line.unit_price
             - line.line_discount
           )
       ) > 1
       OR (
         v_kind = 'goods'
         AND (
           line.ingredient_id IS NULL
           OR line.unit_id IS NULL
           OR NOT EXISTS (
             SELECT 1
             FROM public.ingredient_units AS ingredient_unit
             WHERE ingredient_unit.tenant_id = v_tenant
               AND ingredient_unit.ingredient_id = line.ingredient_id
               AND ingredient_unit.unit_id = line.unit_id
               AND ingredient_unit.is_active
           )
         )
       )
  )
  OR (
    SELECT count(DISTINCT line.line_key)
    FROM pg_catalog.jsonb_to_recordset(p_lines)
      AS line(line_key text)
  ) <> pg_catalog.jsonb_array_length(p_lines) THEN
    RAISE EXCEPTION 'supplier_invoice_line_invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    pg_catalog.round(pg_catalog.sum(line.line_total), 2),
    pg_catalog.round(pg_catalog.sum(line.vat_amount), 2)
  INTO v_subtotal, v_vat
  FROM pg_catalog.jsonb_to_recordset(p_lines) AS line(
    line_total numeric,
    vat_amount numeric
  );
  v_total := v_subtotal - v_discount + v_vat;

  IF v_subtotal <= 0
     OR v_discount > v_subtotal
     OR pg_catalog.abs(
       v_subtotal - (p_invoice->>'subtotal')::numeric
     ) > 1
     OR pg_catalog.abs(v_vat - (p_invoice->>'vat_amount')::numeric) > 1
     OR pg_catalog.abs(
       v_total - (p_invoice->>'total_amount')::numeric
     ) > 1 THEN
    RAISE EXCEPTION 'supplier_invoice_total_mismatch'
      USING ERRCODE = '23514';
  END IF;

  SELECT pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'vat_rate', grouped.vat_rate,
      'taxable_amount', grouped.taxable_amount,
      'vat_amount', grouped.vat_amount
    )
    ORDER BY grouped.vat_rate
  )
  INTO v_vat_breakdown
  FROM (
    SELECT
      line.vat_rate,
      pg_catalog.round(pg_catalog.sum(line.line_total), 2)
        AS taxable_amount,
      pg_catalog.round(pg_catalog.sum(line.vat_amount), 2) AS vat_amount
    FROM pg_catalog.jsonb_to_recordset(p_lines) AS line(
      vat_rate numeric,
      line_total numeric,
      vat_amount numeric
    )
    GROUP BY line.vat_rate
  ) AS grouped;

  IF v_kind = 'goods'
     AND pg_catalog.jsonb_array_length(p_allocations) = 0 THEN
    RAISE EXCEPTION 'goods_invoice_receipts_required'
      USING ERRCODE = '23514';
  END IF;
  IF v_kind = 'service'
     AND pg_catalog.jsonb_array_length(p_allocations) <> 0 THEN
    RAISE EXCEPTION 'service_invoice_receipts_forbidden'
      USING ERRCODE = '23514';
  END IF;

  IF v_kind = 'goods' AND EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_allocations) AS allocation(
      line_key text,
      grn_id bigint,
      po_id bigint,
      purchase_order_item_id bigint,
      quantity numeric
    )
    JOIN pg_catalog.jsonb_to_recordset(p_lines) AS line(
      line_key text,
      ingredient_id bigint,
      unit_id bigint
    )
      ON line.line_key = allocation.line_key
    LEFT JOIN public.goods_received_notes AS grn
      ON grn.id = allocation.grn_id
     AND grn.tenant_id = v_tenant
    LEFT JOIN public.purchase_orders AS purchase_order
      ON purchase_order.id = allocation.po_id
     AND purchase_order.tenant_id = v_tenant
     AND purchase_order.id = grn.po_id
    LEFT JOIN public.purchase_order_items AS po_item
      ON po_item.id = allocation.purchase_order_item_id
     AND po_item.tenant_id = v_tenant
     AND po_item.po_id = purchase_order.id
    LEFT JOIN public.grn_items AS grn_item
      ON grn_item.grn_id = grn.id
     AND grn_item.tenant_id = v_tenant
     AND grn_item.purchase_order_item_id = po_item.id
    WHERE allocation.quantity IS NULL
       OR allocation.quantity <= 0
       OR grn.id IS NULL
       OR grn.status <> 'confirmed'
       OR purchase_order.supplier_id IS DISTINCT FROM v_supplier_id
       OR po_item.ingredient_id IS DISTINCT FROM line.ingredient_id
       OR grn_item.entry_unit_id IS DISTINCT FROM line.unit_id
       OR allocation.quantity > grn_item.po_applied_quantity
  ) THEN
    RAISE EXCEPTION 'supplier_invoice_receipt_line_mismatch'
      USING ERRCODE = '23514';
  END IF;

  IF v_kind = 'goods' AND EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_to_recordset(p_allocations) AS requested(
      line_key text,
      grn_id bigint,
      po_id bigint,
      purchase_order_item_id bigint,
      quantity numeric
    )
    JOIN public.grn_items AS grn_item
      ON grn_item.grn_id = requested.grn_id
     AND grn_item.tenant_id = v_tenant
     AND grn_item.purchase_order_item_id =
       requested.purchase_order_item_id
    LEFT JOIN LATERAL (
      SELECT coalesce(pg_catalog.sum(existing.billed_quantity), 0)
        AS quantity
      FROM public.supplier_invoice_receipt_allocations AS existing
      JOIN public.supplier_invoices AS existing_invoice
        ON existing_invoice.id = existing.supplier_invoice_id
       AND existing_invoice.tenant_id = existing.tenant_id
      WHERE existing.tenant_id = v_tenant
        AND existing.grn_id = requested.grn_id
        AND existing.purchase_order_item_id =
          requested.purchase_order_item_id
        AND existing_invoice.id IS DISTINCT FROM p_invoice_id
        AND existing_invoice.document_status <> 'cancelled'
    ) AS already_billed ON TRUE
    LEFT JOIN LATERAL (
      SELECT pg_catalog.sum(same_request.quantity) AS quantity
      FROM pg_catalog.jsonb_to_recordset(p_allocations) AS same_request(
        line_key text,
        grn_id bigint,
        po_id bigint,
        purchase_order_item_id bigint,
        quantity numeric
      )
      WHERE same_request.grn_id = requested.grn_id
        AND same_request.purchase_order_item_id =
          requested.purchase_order_item_id
    ) AS requested_total ON TRUE
    WHERE already_billed.quantity + requested_total.quantity
      > grn_item.po_applied_quantity
  ) THEN
    RAISE EXCEPTION 'supplier_invoice_over_allocation'
      USING ERRCODE = '23514';
  END IF;

  IF v_invoice_id IS NULL THEN
    v_first_allocation := p_allocations->0;
    INSERT INTO public.supplier_invoices (
      tenant_id,
      supplier_id,
      grn_id,
      po_id,
      invoice_date,
      subtotal,
      vat_rate,
      vat_amount,
      total_amount,
      matching_status,
      matching_notes,
      created_by,
      due_date,
      vat_breakdown,
      document_discount_amount,
      invoice_kind,
      document_status,
      save_idempotency_key
    )
    VALUES (
      v_tenant,
      v_supplier_id,
      (v_first_allocation->>'grn_id')::bigint,
      (v_first_allocation->>'po_id')::bigint,
      (p_invoice->>'invoice_date')::date,
      v_subtotal,
      NULL,
      v_vat,
      v_total,
      'pending',
      nullif(pg_catalog.btrim(p_invoice->>'matching_notes'), ''),
      v_uid,
      nullif(p_invoice->>'due_date', '')::date,
      v_vat_breakdown,
      v_discount,
      v_kind,
      'draft',
      p_idempotency_key
    )
    RETURNING id INTO v_invoice_id;
  ELSE
    PERFORM 1
    FROM public.supplier_invoices AS invoice
    WHERE invoice.id = v_invoice_id
      AND invoice.tenant_id = v_tenant
      AND invoice.document_status = 'draft'
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'supplier_invoice_not_editable'
        USING ERRCODE = '23514';
    END IF;

    DELETE FROM public.supplier_invoice_receipt_allocations
    WHERE tenant_id = v_tenant
      AND supplier_invoice_id = v_invoice_id;
    DELETE FROM public.supplier_invoice_lines
    WHERE tenant_id = v_tenant
      AND supplier_invoice_id = v_invoice_id;

    v_first_allocation := p_allocations->0;
    UPDATE public.supplier_invoices
    SET supplier_id = v_supplier_id,
        grn_id = (v_first_allocation->>'grn_id')::bigint,
        po_id = (v_first_allocation->>'po_id')::bigint,
        invoice_date = (p_invoice->>'invoice_date')::date,
        subtotal = v_subtotal,
        vat_amount = v_vat,
        total_amount = v_total,
        matching_status = 'pending',
        matching_notes = nullif(
          pg_catalog.btrim(p_invoice->>'matching_notes'),
          ''
        ),
        due_date = nullif(p_invoice->>'due_date', '')::date,
        vat_breakdown = v_vat_breakdown,
        document_discount_amount = v_discount,
        invoice_kind = v_kind,
        save_idempotency_key = p_idempotency_key,
        updated_at = pg_catalog.now()
    WHERE id = v_invoice_id
      AND tenant_id = v_tenant;
  END IF;

  INSERT INTO public.supplier_invoice_lines (
    tenant_id,
    supplier_invoice_id,
    source_line_key,
    ingredient_id,
    description,
    quantity,
    unit_id,
    unit_price,
    line_discount_amount,
    allocated_document_discount,
    vat_rate,
    vat_amount,
    line_total
  )
  SELECT
    v_tenant,
    v_invoice_id,
    line.line_key,
    line.ingredient_id,
    pg_catalog.btrim(line.description),
    line.quantity,
    line.unit_id,
    line.unit_price,
    line.line_discount,
    pg_catalog.round(
      v_discount * line.line_total / v_subtotal,
      2
    ),
    line.vat_rate,
    line.vat_amount,
    line.line_total
  FROM pg_catalog.jsonb_to_recordset(p_lines) AS line(
    line_key text,
    ingredient_id bigint,
    description text,
    quantity numeric,
    unit_id bigint,
    unit_price numeric,
    line_discount numeric,
    vat_rate numeric,
    vat_amount numeric,
    line_total numeric
  );

  INSERT INTO public.supplier_invoice_receipt_allocations (
    tenant_id,
    supplier_invoice_id,
    grn_id,
    po_id,
    purchase_order_item_id,
    invoice_line_id,
    billed_quantity,
    matched_quantity
  )
  SELECT
    v_tenant,
    v_invoice_id,
    allocation.grn_id,
    allocation.po_id,
    allocation.purchase_order_item_id,
    invoice_line.id,
    allocation.quantity,
    allocation.quantity
  FROM pg_catalog.jsonb_to_recordset(p_allocations) AS allocation(
    line_key text,
    grn_id bigint,
    po_id bigint,
    purchase_order_item_id bigint,
    quantity numeric
  )
  JOIN public.supplier_invoice_lines AS invoice_line
    ON invoice_line.tenant_id = v_tenant
   AND invoice_line.supplier_invoice_id = v_invoice_id
   AND invoice_line.source_line_key = allocation.line_key;

  v_result := private.apply_supplier_invoice_matching(v_invoice_id);
  PERFORM public.log_audit(
    'supplier_invoice.draft_saved',
    'supplier_invoice',
    v_invoice_id,
    NULL,
    v_result
  );

  RETURN pg_catalog.jsonb_build_object(
    'invoice_id', v_invoice_id,
    'document_status', 'draft',
    'matching_status', v_result->>'matching_status',
    'replayed', FALSE
  );
END;
$$;


--
-- Name: scan_inventory_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scan_inventory_alerts() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_low bigint := 0;
BEGIN
  WITH stock_by_site AS (
    SELECT
      stock.tenant_id,
      stock.branch_id,
      stock.ingredient_id,
      sum(stock.current_quantity) AS current_quantity
    FROM public.stock_levels AS stock
    JOIN public.inventory_locations AS location
      ON location.id = stock.location_id
     AND location.tenant_id = stock.tenant_id
     AND location.branch_id = stock.branch_id
     AND location.is_active IS TRUE
    JOIN public.branches AS branch
      ON branch.id = stock.branch_id
     AND branch.tenant_id = stock.tenant_id
     AND branch.is_active IS TRUE
    WHERE location.location_kind = 'warehouse'
       OR (
         branch.branch_kind = 'central_kitchen'
         AND location.location_kind = 'production_storage'
       )
    GROUP BY stock.tenant_id, stock.branch_id, stock.ingredient_id
  ),
  low_stock AS (
    SELECT
      stock.tenant_id,
      stock.branch_id,
      stock.ingredient_id,
      stock.current_quantity,
      ingredient.min_stock_level,
      ingredient.name AS ingredient_name,
      branch.branch_kind,
      unit_row.code AS display_unit_code,
      stock.current_quantity / coalesce(nullif(issue_unit.to_base_factor, 0), 1)
        AS display_quantity,
      ingredient.min_stock_level
        / coalesce(nullif(issue_unit.to_base_factor, 0), 1)
        AS display_min_stock_level
    FROM stock_by_site AS stock
    JOIN public.ingredients AS ingredient
      ON ingredient.id = stock.ingredient_id
     AND ingredient.tenant_id = stock.tenant_id
     AND ingredient.is_active IS TRUE
    JOIN public.branches AS branch
      ON branch.id = stock.branch_id
     AND branch.tenant_id = stock.tenant_id
    LEFT JOIN public.ingredient_units AS issue_unit
      ON issue_unit.tenant_id = ingredient.tenant_id
     AND issue_unit.ingredient_id = ingredient.id
     AND issue_unit.unit_id = ingredient.issue_unit_id
     AND issue_unit.is_active IS TRUE
    LEFT JOIN public.units AS unit_row
      ON unit_row.id = issue_unit.unit_id
     AND unit_row.tenant_id = ingredient.tenant_id
    WHERE ingredient.min_stock_level > 0
      AND stock.current_quantity <= ingredient.min_stock_level
  ),
  reactivated AS (
    UPDATE public.notifications AS notification
    SET expires_at = NULL,
        created_at = now()
    FROM low_stock
    WHERE notification.tenant_id = low_stock.tenant_id
      AND notification.dedup_key = format(
        'inventory.stock_low:%s:%s',
        low_stock.branch_id,
        low_stock.ingredient_id
      )
      AND notification.expires_at IS NOT NULL
    RETURNING notification.id
  ),
  cleared_reads AS (
    DELETE FROM public.notification_reads AS read_state
    USING reactivated
    WHERE read_state.notification_id = reactivated.id
    RETURNING 1
  ),
  upserted AS (
    INSERT INTO public.notifications (
      tenant_id,
      target_branch_id,
      target_roles,
      kind,
      severity,
      title,
      body,
      entity_type,
      entity_id,
      action_url,
      dedup_key,
      meta,
      expires_at
    )
    SELECT
      low_stock.tenant_id,
      low_stock.branch_id,
      CASE low_stock.branch_kind
        WHEN 'central_supply'
          THEN ARRAY['owner', 'central_supply_ops']::text[]
        WHEN 'central_kitchen'
          THEN ARRAY['owner', 'central_kitchen_lead']::text[]
        ELSE ARRAY['owner', 'branch_manager']::text[]
      END,
      'inventory.stock_low',
      'warning',
      format('Tồn kho thấp: %s', low_stock.ingredient_name),
      format(
        'Còn %s%s (mức tối thiểu %s%s)',
        trim(
          trailing '.' from trim(
            trailing '0' from to_char(
              low_stock.display_quantity,
              'FM999999999999999990.999999999999'
            )
          )
        ),
        CASE
          WHEN low_stock.display_unit_code IS NULL THEN ''
          ELSE format(' %s', low_stock.display_unit_code)
        END,
        trim(
          trailing '.' from trim(
            trailing '0' from to_char(
              low_stock.display_min_stock_level,
              'FM999999999999999990.999999999999'
            )
          )
        ),
        CASE
          WHEN low_stock.display_unit_code IS NULL THEN ''
          ELSE format(' %s', low_stock.display_unit_code)
        END
      ),
      'ingredient',
      low_stock.ingredient_id,
      CASE
        WHEN low_stock.branch_kind = 'branch'
          THEN format(
            '/br/%s/stock/on-hand/%s',
            low_stock.branch_id,
            low_stock.ingredient_id
          )
        ELSE format(
          '/inventory/stock/%s?branchId=%s',
          low_stock.ingredient_id,
          low_stock.branch_id
        )
      END,
      format(
        'inventory.stock_low:%s:%s',
        low_stock.branch_id,
        low_stock.ingredient_id
      ),
      jsonb_build_object(
        'branch_id', low_stock.branch_id,
        'current_quantity_base', low_stock.current_quantity,
        'min_stock_level_base', low_stock.min_stock_level,
        'display_quantity', low_stock.display_quantity,
        'display_min_stock_level', low_stock.display_min_stock_level,
        'display_unit_code', low_stock.display_unit_code
      ),
      NULL
    FROM low_stock
    ON CONFLICT (tenant_id, dedup_key)
      WHERE dedup_key IS NOT NULL
    DO UPDATE
    SET target_branch_id = EXCLUDED.target_branch_id,
        target_roles = EXCLUDED.target_roles,
        severity = EXCLUDED.severity,
        title = EXCLUDED.title,
        body = EXCLUDED.body,
        entity_type = EXCLUDED.entity_type,
        entity_id = EXCLUDED.entity_id,
        action_url = EXCLUDED.action_url,
        meta = EXCLUDED.meta,
        expires_at = NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_low FROM low_stock;

  WITH stock_by_site AS (
    SELECT
      stock.tenant_id,
      stock.branch_id,
      stock.ingredient_id,
      sum(stock.current_quantity) AS current_quantity
    FROM public.stock_levels AS stock
    JOIN public.inventory_locations AS location
      ON location.id = stock.location_id
     AND location.tenant_id = stock.tenant_id
     AND location.branch_id = stock.branch_id
     AND location.is_active IS TRUE
    JOIN public.branches AS branch
      ON branch.id = stock.branch_id
     AND branch.tenant_id = stock.tenant_id
     AND branch.is_active IS TRUE
    WHERE location.location_kind = 'warehouse'
       OR (
         branch.branch_kind = 'central_kitchen'
         AND location.location_kind = 'production_storage'
       )
    GROUP BY stock.tenant_id, stock.branch_id, stock.ingredient_id
  )
  UPDATE public.notifications AS notification
  SET expires_at = now()
  WHERE notification.kind = 'inventory.stock_low'
    AND notification.expires_at IS NULL
    AND notification.dedup_key LIKE 'inventory.stock_low:%'
    AND NOT EXISTS (
      SELECT 1
      FROM stock_by_site AS stock
      JOIN public.ingredients AS ingredient
        ON ingredient.id = stock.ingredient_id
       AND ingredient.tenant_id = stock.tenant_id
       AND ingredient.is_active IS TRUE
      WHERE stock.tenant_id = notification.tenant_id
        AND stock.branch_id = notification.target_branch_id
        AND stock.ingredient_id = notification.entity_id
        AND ingredient.min_stock_level > 0
        AND stock.current_quantity <= ingredient.min_stock_level
    );

  UPDATE public.notifications
  SET expires_at = coalesce(expires_at, now())
  WHERE kind = 'inventory.stock_low'
    AND dedup_key IS DISTINCT FROM format(
      'inventory.stock_low:%s:%s',
      target_branch_id,
      entity_id
    );

  RETURN v_low;
END;
$$;


--
-- Name: self_order_accept_request(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_accept_request(p_request_id bigint, p_target_order_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request_ref public.self_order_requests%ROWTYPE;
  v_request public.self_order_requests%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_open_order_count integer := 0;
  v_order_id bigint;
  v_pos_session_id bigint;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT r.*
  INTO v_request_ref
  FROM public.self_order_requests r
  WHERE r.id = p_request_id
    AND r.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_request_ref.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'permission denied: pos:use' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('self-order-table'),
    hashtext(v_request_ref.table_id::text)
  );

  SELECT r.*
  INTO v_request
  FROM public.self_order_requests r
  WHERE r.id = v_request_ref.id
    AND r.tenant_id = v_request_ref.tenant_id
  FOR UPDATE;

  IF v_request.status = 'accepted' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'status', 'accepted',
      'orderId', v_request.order_id
    );
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'self_order_request_not_pending' USING ERRCODE = '22023';
  END IF;

  SELECT ps.id
  INTO v_pos_session_id
  FROM public.pos_sessions ps
  WHERE ps.tenant_id = v_request.tenant_id
    AND ps.branch_id = v_request.branch_id
    AND ps.status = 'open'
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_pos_session_closed' USING ERRCODE = '22023';
  END IF;

  IF p_target_order_id IS NOT NULL THEN
    v_order_id := p_target_order_id;
  ELSE
    SELECT count(*)::integer, min(o.id)
    INTO v_open_order_count, v_order_id
    FROM public.orders o
    WHERE o.tenant_id = v_request.tenant_id
      AND o.branch_id = v_request.branch_id
      AND o.table_id = v_request.table_id
      AND o.payment_status <> 'paid'
      AND o.status NOT IN ('completed', 'cancelled')
      AND o.merged_into_order_id IS NULL;

    IF v_open_order_count <> 1 THEN
      v_order_id := NULL;
    END IF;
  END IF;

  IF v_order_id IS NULL THEN
    v_result := public.create_order(
      v_request.tenant_id,
      v_request.branch_id,
      v_uid,
      v_request.cart_payload,
      'dine_in',
      v_request.table_id,
      v_pos_session_id,
      v_request.customer_note,
      v_request.client_op_id
    );
    v_order_id := NULLIF(v_result ->> 'order_id', '')::bigint;
  ELSE
    SELECT o.*
    INTO v_order
    FROM public.orders o
    WHERE o.id = v_order_id
      AND o.tenant_id = v_request.tenant_id
      AND o.branch_id = v_request.branch_id
      AND o.table_id = v_request.table_id
      AND o.payment_status <> 'paid'
      AND o.status NOT IN ('completed', 'cancelled')
      AND o.merged_into_order_id IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'self_order_target_order_not_appendable' USING ERRCODE = '22023';
    END IF;
    IF public.self_order_active_payment_lock(v_order.id) IS NOT NULL THEN
      RAISE EXCEPTION 'self_order_pending_payment_exists' USING ERRCODE = '55P03';
    END IF;

    v_result := public.append_order_items(
      v_order.id,
      v_request.cart_payload,
      v_request.client_op_id
    );
  END IF;

  UPDATE public.self_order_requests
  SET status = 'accepted',
      order_id = v_order_id,
      decided_by = v_uid,
      decided_at = now()
  WHERE id = v_request.id
    AND tenant_id = v_request.tenant_id
    AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_request_not_pending' USING ERRCODE = '40001';
  END IF;

  RETURN COALESCE(v_result, '{}'::jsonb) || jsonb_build_object(
    'ok', true,
    'status', 'accepted',
    'orderId', v_order_id
  );
END;
$$;


--
-- Name: self_order_active_payment_lock(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_active_payment_lock(p_order_id bigint) RETURNS bigint
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  SELECT candidate.lock_id
  FROM (
    SELECT COALESCE(pr.payment_id, pr.id) AS lock_id, pr.created_at
    FROM public.self_order_payment_requests pr
    WHERE pr.order_id = p_order_id
      AND pr.status IN ('cash_call', 'vietqr_pending')

    UNION ALL

    SELECT p.id AS lock_id, p.created_at
    FROM public.payments p
    WHERE p.order_id = p_order_id
      AND p.status = 'pending'
  ) candidate
  ORDER BY candidate.created_at DESC, candidate.lock_id DESC
  LIMIT 1;
$$;


--
-- Name: self_order_branch_has_open_pos_session(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_branch_has_open_pos_session(p_tenant_id bigint, p_branch_id bigint) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.pos_sessions ps
    WHERE ps.tenant_id = p_tenant_id
      AND ps.branch_id = p_branch_id
      AND ps.status = 'open'
  );
$$;


--
-- Name: self_order_cancel_payment_request(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_cancel_payment_request(p_request_id bigint, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request_ref public.self_order_payment_requests%ROWTYPE;
  v_request public.self_order_payment_requests%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_payment_found boolean := false;
  v_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.*
  INTO v_request_ref
  FROM public.self_order_payment_requests pr
  WHERE pr.id = p_request_id
    AND pr.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_payment_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_request_ref.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'permission denied: pos:use' USING ERRCODE = '42501';
  END IF;

  SELECT o.*
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_request_ref.order_id
    AND o.tenant_id = v_request_ref.tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_payment_order_missing' USING ERRCODE = '23503';
  END IF;
  IF NOT pg_try_advisory_xact_lock(v_order.id) THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END IF;

  BEGIN
    SELECT p.*
    INTO v_payment
    FROM public.payments p
    WHERE p.tenant_id = v_request_ref.tenant_id
      AND p.order_id = v_request_ref.order_id
      AND (
        p.id = v_request_ref.payment_id
        OR (
          p.status = 'completed'
          AND (
            (v_request_ref.method = 'cash_call' AND p.method = 'cash')
            OR (v_request_ref.method = 'vietqr' AND p.method = 'vietqr')
          )
        )
      )
    ORDER BY
      CASE WHEN p.status = 'completed' THEN 0 ELSE 1 END,
      CASE WHEN p.id = v_request_ref.payment_id THEN 0 ELSE 1 END,
      p.id DESC
    LIMIT 1
    FOR UPDATE NOWAIT;
    v_payment_found := FOUND;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END;

  SELECT pr.*
  INTO v_request
  FROM public.self_order_payment_requests pr
  WHERE pr.id = v_request_ref.id
    AND pr.tenant_id = v_request_ref.tenant_id
    AND pr.order_id = v_request_ref.order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_payment_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_request.status NOT IN ('cash_call', 'vietqr_pending') THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'paymentCompleted', (
        v_request.status = 'completed'
        OR COALESCE(v_order.payment_status, 'unpaid') = 'paid'
        OR (v_payment_found AND v_payment.status = 'completed')
      )
    ) || public.self_order_payment_request_public_payload(v_request.id);
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid'
     OR (v_payment_found AND v_payment.status = 'completed') THEN
    UPDATE public.self_order_payment_requests
    SET status = 'completed',
        payment_id = COALESCE(
          v_request.payment_id,
          CASE WHEN v_payment_found THEN v_payment.id ELSE NULL END
        ),
        completed_at = COALESCE(
          CASE WHEN v_payment_found THEN v_payment.paid_at ELSE NULL END,
          now()
        )
    WHERE id = v_request.id;

    RETURN jsonb_build_object('ok', true, 'paymentCompleted', true)
      || public.self_order_payment_request_public_payload(v_request.id);
  END IF;

  UPDATE public.self_order_payment_requests
  SET status = 'cancelled',
      cancelled_at = now(),
      cancel_reason = v_reason
  WHERE id = v_request.id
    AND status IN ('cash_call', 'vietqr_pending');

  IF v_payment_found AND v_payment.status = 'pending' THEN
    UPDATE public.payments
    SET status = 'failed',
        updated_at = now()
    WHERE id = v_payment.id
      AND tenant_id = v_request.tenant_id
      AND status = 'pending';
  END IF;

  IF v_request.method = 'vietqr' THEN
    UPDATE public.orders o
    SET payment_status = 'unpaid',
        payment_method = NULL,
        updated_at = now()
    WHERE o.id = v_request.order_id
      AND o.tenant_id = v_request.tenant_id
      AND COALESCE(o.payment_status, 'unpaid') <> 'paid'
      AND NOT EXISTS (
        SELECT 1
        FROM public.payments p
        WHERE p.tenant_id = v_request.tenant_id
          AND p.order_id = v_request.order_id
          AND p.status IN ('pending', 'completed')
      );
  END IF;

  RETURN jsonb_build_object('ok', true)
    || public.self_order_payment_request_public_payload(v_request.id);
END;
$$;


--
-- Name: self_order_cancel_pending_payment_and_add(text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_cancel_pending_payment_and_add(p_token text, p_client_op_id uuid, p_items jsonb, p_customer_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  RAISE EXCEPTION 'self_order_payment_cancel_staff_required'
    USING ERRCODE = '42501';
END;
$$;


--
-- Name: self_order_cancel_vietqr_payment(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_cancel_vietqr_payment(p_token text, p_client_op_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_table record;
  v_request_ref public.self_order_payment_requests%ROWTYPE;
  v_request public.self_order_payment_requests%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_payment_found boolean := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT t.id AS table_id, t.tenant_id
  INTO v_table
  FROM public.tables t
  JOIN public.branches b
    ON b.id = t.branch_id
   AND b.tenant_id = t.tenant_id
   AND b.is_active = true
  WHERE t.self_order_token = p_token
    AND t.self_order_enabled = true
    AND t.status <> 'maintenance'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'invalid_or_disabled_token'
    );
  END IF;

  SELECT pr.*
  INTO v_request_ref
  FROM public.self_order_payment_requests pr
  WHERE pr.tenant_id = v_table.tenant_id
    AND pr.table_id = v_table.table_id
    AND pr.client_op_id = p_client_op_id
  ORDER BY pr.id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'self_order_payment_request_not_found'
    );
  END IF;
  IF v_request_ref.method <> 'vietqr' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'self_order_payment_cancel_not_allowed'
    );
  END IF;
  IF v_request_ref.status <> 'vietqr_pending' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true
    ) || public.self_order_payment_request_public_payload(v_request_ref.id);
  END IF;

  SELECT o.*
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_request_ref.order_id
    AND o.tenant_id = v_request_ref.tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_payment_order_missing' USING ERRCODE = '23503';
  END IF;
  IF NOT pg_try_advisory_xact_lock(v_order.id) THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END IF;

  BEGIN
    SELECT p.*
    INTO v_payment
    FROM public.payments p
    WHERE p.tenant_id = v_request_ref.tenant_id
      AND p.order_id = v_request_ref.order_id
      AND (
        p.id = v_request_ref.payment_id
        OR (
          p.status = 'completed'
          AND p.method = 'vietqr'
        )
      )
    ORDER BY
      CASE WHEN p.status = 'completed' THEN 0 ELSE 1 END,
      CASE WHEN p.id = v_request_ref.payment_id THEN 0 ELSE 1 END,
      p.id DESC
    LIMIT 1
    FOR UPDATE NOWAIT;
    v_payment_found := FOUND;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END;

  SELECT pr.*
  INTO v_request
  FROM public.self_order_payment_requests pr
  WHERE pr.id = v_request_ref.id
    AND pr.tenant_id = v_request_ref.tenant_id
    AND pr.table_id = v_table.table_id
    AND pr.client_op_id = p_client_op_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'self_order_payment_request_not_found'
    );
  END IF;
  IF v_request.status <> 'vietqr_pending' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true
    ) || public.self_order_payment_request_public_payload(v_request.id);
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid'
     OR (v_payment_found AND v_payment.status = 'completed') THEN
    UPDATE public.self_order_payment_requests
    SET status = 'completed',
        payment_id = CASE
          WHEN v_payment_found AND v_payment.status = 'completed'
            THEN v_payment.id
          ELSE v_request.payment_id
        END,
        completed_at = COALESCE(
          CASE WHEN v_payment_found THEN v_payment.paid_at ELSE NULL END,
          now()
        )
    WHERE id = v_request.id
      AND status = 'vietqr_pending';

    RETURN jsonb_build_object('ok', true)
      || public.self_order_payment_request_public_payload(v_request.id);
  END IF;

  UPDATE public.self_order_payment_requests
  SET status = 'cancelled',
      cancelled_at = now(),
      cancel_reason = 'guest_cancelled_vietqr'
  WHERE id = v_request.id
    AND status = 'vietqr_pending';

  IF v_payment_found AND v_payment.status = 'pending' THEN
    UPDATE public.payments
    SET status = 'failed',
        updated_at = now()
    WHERE id = v_payment.id
      AND tenant_id = v_request.tenant_id
      AND status = 'pending';
  END IF;

  UPDATE public.orders o
  SET payment_status = 'unpaid',
      payment_method = NULL,
      updated_at = now()
  WHERE o.id = v_request.order_id
    AND o.tenant_id = v_request.tenant_id
    AND COALESCE(o.payment_status, 'unpaid') <> 'paid'
    AND NOT EXISTS (
      SELECT 1
      FROM public.payments p
      WHERE p.tenant_id = v_request.tenant_id
        AND p.order_id = v_request.order_id
        AND p.status IN ('pending', 'completed')
    );

  RETURN jsonb_build_object('ok', true)
    || public.self_order_payment_request_public_payload(v_request.id);
END;
$$;


--
-- Name: FUNCTION self_order_cancel_vietqr_payment(p_token text, p_client_op_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.self_order_cancel_vietqr_payment(p_token text, p_client_op_id uuid) IS 'Cancel the exact active VietQR request bound to a public self-order table token.';


--
-- Name: self_order_canonicalize_cart(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_canonicalize_cart(p_tenant_id bigint, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_item jsonb;
  v_menu record;
  v_variant_id bigint;
  v_variant_name text;
  v_variant_price numeric(15,2);
  v_modifier_ids bigint[];
  v_modifiers jsonb;
  v_result jsonb := '[]'::jsonb;
  v_quantity int;
BEGIN
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'invalid_cart_payload' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) AS value LOOP
    v_quantity := (v_item ->> 'quantity')::int;
    IF v_quantity IS NULL OR v_quantity < 1 OR v_quantity > 99 THEN
      RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
    END IF;

    SELECT id, name, base_price
    INTO v_menu
    FROM public.menu_items
    WHERE id = (v_item ->> 'menu_item_id')::bigint
      AND tenant_id = p_tenant_id
      AND is_active = true;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'menu_item_not_available' USING ERRCODE = 'P0002';
    END IF;

    v_variant_id := NULL;
    v_variant_name := NULL;
    v_variant_price := 0;
    IF NULLIF(v_item ->> 'variant_id', '') IS NOT NULL THEN
      SELECT id, name, price_adjustment
      INTO v_variant_id, v_variant_name, v_variant_price
      FROM public.menu_item_variants
      WHERE id = (v_item ->> 'variant_id')::bigint
        AND item_id = v_menu.id
        AND tenant_id = p_tenant_id
        AND is_active = true;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'variant_not_available' USING ERRCODE = 'P0002';
      END IF;
    END IF;

    SELECT COALESCE(array_agg(DISTINCT (m.value ->> 'modifier_id')::bigint), ARRAY[]::bigint[])
    INTO v_modifier_ids
    FROM jsonb_array_elements(COALESCE(v_item -> 'modifiers', '[]'::jsonb)) AS m(value);

    IF COALESCE(array_length(v_modifier_ids, 1), 0) > 0 THEN
      SELECT jsonb_agg(
        jsonb_build_object(
          'modifier_id', mm.id,
          'name', mm.name,
          'price', mm.price
        )
        ORDER BY mm.sort_order, mm.id
      )
      INTO v_modifiers
      FROM public.menu_item_modifiers mm
      WHERE mm.tenant_id = p_tenant_id
        AND mm.item_id = v_menu.id
        AND mm.is_active = true
        AND mm.id = ANY(v_modifier_ids);

      IF jsonb_array_length(COALESCE(v_modifiers, '[]'::jsonb)) <> array_length(v_modifier_ids, 1) THEN
        RAISE EXCEPTION 'modifier_not_available' USING ERRCODE = 'P0002';
      END IF;
    ELSE
      v_modifiers := '[]'::jsonb;
    END IF;

    v_result := v_result || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'key', COALESCE(NULLIF(v_item ->> 'key', ''), extensions.gen_random_uuid()::text),
      'menu_item_id', v_menu.id,
      'item_name', v_menu.name,
      'variant_id', v_variant_id,
      'variant_name', v_variant_name,
      'quantity', v_quantity,
      'unit_price', v_menu.base_price + COALESCE(v_variant_price, 0),
      'modifiers', v_modifiers,
      'sides', COALESCE(v_item -> 'sides', '[]'::jsonb),
      'note', NULLIF(btrim(COALESCE(v_item ->> 'note', '')), '')
    )));
  END LOOP;

  RETURN v_result;
END;
$$;


--
-- Name: self_order_consume_rate_limits(text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_consume_rate_limits(p_purpose text, p_token text, p_ip_hash text, p_tenant_id bigint, p_table_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_token_hash text;
  v_ip_scope_hash text;
  v_token_limit integer;
  v_ip_limit integer;
  v_window_seconds integer := 600;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;
  IF p_purpose NOT IN ('batch', 'payment')
     OR p_token IS NULL
     OR p_token = ''
     OR p_tenant_id IS NULL
     OR p_table_id IS NULL
     OR (p_ip_hash IS NOT NULL AND p_ip_hash !~ '^[0-9a-f]{64}$') THEN
    RAISE EXCEPTION 'self_order_invalid_rate_identity' USING ERRCODE = '22023';
  END IF;

  IF p_purpose = 'batch' THEN
    v_token_limit := 20;
    v_ip_limit := 30;
  ELSE
    v_token_limit := 10;
    v_ip_limit := 15;
  END IF;

  v_token_hash := public.self_order_scope_hash(
    p_tenant_id::text || ':' || p_table_id::text || ':' || p_token
  );
  v_ip_scope_hash := CASE
    WHEN p_ip_hash IS NULL THEN NULL
    ELSE public.self_order_scope_hash(v_token_hash || ':' || p_ip_hash)
  END;

  PERFORM public.self_order_take_rate_bucket(
    p_purpose,
    'token',
    v_token_hash,
    v_token_limit,
    v_window_seconds
  );
  IF v_ip_scope_hash IS NOT NULL THEN
    PERFORM public.self_order_take_rate_bucket(
      p_purpose,
      'ip',
      v_ip_scope_hash,
      v_ip_limit,
      v_window_seconds
    );
  END IF;

  RETURN jsonb_build_object('ok', true, 'windowSeconds', v_window_seconds);
END;
$_$;


--
-- Name: self_order_create_payment_request(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_create_payment_request(p_token text, p_client_op_id uuid, p_method text, p_invoice_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_table public.tables%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_existing public.self_order_payment_requests%ROWTYPE;
  v_active public.self_order_payment_requests%ROWTYPE;
  v_open_order_count integer := 0;
  v_order_id bigint;
  v_invoice_payload jsonb;
  v_fingerprint text;
  v_payment_id bigint;
  v_bank_code text;
  v_account_no text;
  v_account_name text;
  v_payment_code text;
  v_qr_payload text;
  v_config_snapshot jsonb := '{}'::jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;
  IF p_client_op_id IS NULL THEN
    RAISE EXCEPTION 'self_order_missing_operation_id' USING ERRCODE = '22023';
  END IF;
  IF p_method NOT IN ('cash_call', 'vietqr') THEN
    RAISE EXCEPTION 'invalid_payment_method' USING ERRCODE = '22023';
  END IF;

  v_invoice_payload := public.self_order_normalize_invoice_payload(
    COALESCE(p_invoice_payload, '{}'::jsonb)
  );
  v_fingerprint := public.self_order_payment_request_fingerprint(
    p_method,
    v_invoice_payload
  );

  SELECT t.*
  INTO v_table
  FROM public.tables t
  JOIN public.branches b
    ON b.id = t.branch_id
   AND b.tenant_id = t.tenant_id
   AND b.is_active = true
  WHERE t.self_order_token = p_token
    AND t.self_order_enabled = true
    AND t.status <> 'maintenance'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'invalid_or_disabled_token');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('self-order-table'),
    hashtext(v_table.id::text)
  );

  SELECT pr.*
  INTO v_existing
  FROM public.self_order_payment_requests pr
  WHERE pr.tenant_id = v_table.tenant_id
    AND pr.client_op_id = p_client_op_id
  ORDER BY pr.id DESC
  LIMIT 1;

  IF FOUND THEN
    IF v_existing.table_id <> v_table.id
       OR (
         v_existing.request_fingerprint_version = 'payment:v1'
         AND v_existing.request_fingerprint IS DISTINCT FROM v_fingerprint
       ) THEN
      RAISE EXCEPTION 'self_order_idempotency_conflict' USING ERRCODE = '22023';
    END IF;
    IF v_existing.status IN ('cash_call', 'vietqr_pending')
       AND v_existing.expires_at <= now() THEN
      PERFORM public.self_order_expire_payment_request(v_existing.id);
      SELECT pr.* INTO v_existing
      FROM public.self_order_payment_requests pr
      WHERE pr.id = v_existing.id;
    END IF;
    RETURN jsonb_build_object('ok', true, 'idempotent', true)
      || COALESCE(
        public.self_order_payment_request_public_payload(v_existing.id),
        '{}'::jsonb
      );
  END IF;

  IF NOT public.self_order_branch_has_open_pos_session(
    v_table.tenant_id,
    v_table.branch_id
  ) THEN
    RAISE EXCEPTION 'self_order_pos_session_closed' USING ERRCODE = '22023';
  END IF;

  SELECT count(*)::integer, min(o.id)
  INTO v_open_order_count, v_order_id
  FROM public.orders o
  WHERE o.tenant_id = v_table.tenant_id
    AND o.branch_id = v_table.branch_id
    AND o.table_id = v_table.id
    AND o.payment_status <> 'paid'
    AND o.status NOT IN ('completed', 'cancelled')
    AND o.merged_into_order_id IS NULL;

  IF v_open_order_count <> 1 THEN
    RAISE EXCEPTION 'self_order_order_ambiguous' USING ERRCODE = '22023';
  END IF;

  SELECT o.*
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_order_id
    AND o.tenant_id = v_table.tenant_id
  FOR UPDATE;

  IF NOT pg_try_advisory_xact_lock(v_order.id) THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END IF;
  IF v_order.status NOT IN ('new', 'confirmed', 'preparing', 'ready', 'served')
     OR COALESCE(v_order.payment_status, 'unpaid') = 'paid'
     OR v_order.merged_into_order_id IS NOT NULL THEN
    RAISE EXCEPTION 'self_order_order_not_payable' USING ERRCODE = '22023';
  END IF;


  SELECT pr.*
  INTO v_active
  FROM public.self_order_payment_requests pr
  WHERE pr.tenant_id = v_order.tenant_id
    AND pr.order_id = v_order.id
    AND pr.status IN ('cash_call', 'vietqr_pending')
  ORDER BY pr.id DESC
  LIMIT 1;

  IF FOUND AND v_active.expires_at <= now() THEN
    PERFORM public.self_order_expire_payment_request(v_active.id);
    SELECT pr.*
    INTO v_active
    FROM public.self_order_payment_requests pr
    WHERE pr.tenant_id = v_order.tenant_id
      AND pr.order_id = v_order.id
      AND pr.status IN ('cash_call', 'vietqr_pending')
    ORDER BY pr.id DESC
    LIMIT 1;
  END IF;

  IF FOUND THEN
    IF v_active.request_fingerprint_version = 'payment:v1'
       AND v_active.request_fingerprint = v_fingerprint THEN
      RETURN jsonb_build_object('ok', true, 'recovered', true)
        || public.self_order_payment_request_public_payload(v_active.id);
    END IF;
    RAISE EXCEPTION 'self_order_pending_payment_exists' USING ERRCODE = '55P03';
  END IF;

  BEGIN
    PERFORM 1
    FROM public.payments p
    WHERE p.tenant_id = v_order.tenant_id
      AND p.order_id = v_order.id
      AND p.status = 'pending'
    ORDER BY p.id DESC
    LIMIT 1
    FOR UPDATE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END;

  IF FOUND THEN
    RAISE EXCEPTION 'self_order_pending_payment_exists' USING ERRCODE = '55P03';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.payments p
    WHERE p.tenant_id = v_order.tenant_id
      AND p.order_id = v_order.id
      AND p.status = 'completed'
  ) THEN
    RAISE EXCEPTION 'self_order_payment_completed' USING ERRCODE = '22023';
  END IF;

  IF p_method = 'cash_call' THEN
    INSERT INTO public.self_order_payment_requests (
      tenant_id,
      branch_id,
      table_id,
      order_id,
      client_op_id,
      method,
      status,
      amount_snapshot,
      invoice_payload,
      request_fingerprint,
      request_fingerprint_version,
      expires_at
    )
    VALUES (
      v_order.tenant_id,
      v_order.branch_id,
      v_order.table_id,
      v_order.id,
      p_client_op_id,
      'cash_call',
      'cash_call',
      v_order.total_amount,
      v_invoice_payload,
      v_fingerprint,
      'payment:v1',
      now() + interval '15 minutes'
    )
    RETURNING * INTO v_existing;

    RETURN jsonb_build_object('ok', true)
      || public.self_order_payment_request_public_payload(v_existing.id);
  END IF;

  IF v_order.total_amount <= 0 THEN
    RAISE EXCEPTION 'self_order_vietqr_requires_positive_amount' USING ERRCODE = '22023';
  END IF;

  v_payment_code := NULLIF(btrim(COALESCE(v_order.payment_code, '')), '');
  IF v_payment_code IS NULL THEN
    RAISE EXCEPTION 'self_order_vietqr_config_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT
    max(NULLIF(btrim(ss.value), '')) FILTER (
      WHERE ss.key = 'payment_vietqr_bank_code'
    ),
    max(NULLIF(btrim(ss.value), '')) FILTER (
      WHERE ss.key = 'payment_vietqr_account_no'
    ),
    max(NULLIF(btrim(ss.value), '')) FILTER (
      WHERE ss.key = 'payment_vietqr_account_name'
    )
  INTO v_bank_code, v_account_no, v_account_name
  FROM public.system_settings ss
  WHERE ss.tenant_id = v_order.tenant_id
    AND ss.key IN (
      'payment_vietqr_bank_code',
      'payment_vietqr_account_no',
      'payment_vietqr_account_name'
    );

  v_bank_code := upper(v_bank_code);
  IF v_bank_code IS NULL OR v_account_no IS NULL THEN
    RAISE EXCEPTION 'self_order_vietqr_config_missing' USING ERRCODE = '22023';
  END IF;
  IF public.print_vietqr_bank_bin(v_bank_code) !~ '^[0-9]{6}$'
     OR char_length(v_account_no) > 50 THEN
    RAISE EXCEPTION 'self_order_vietqr_config_invalid' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_qr_payload := public.print_vietqr_emvco(
      v_bank_code,
      v_account_no,
      v_account_name,
      v_order.total_amount,
      v_payment_code
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'self_order_vietqr_config_invalid' USING ERRCODE = '22023';
  END;

  IF v_qr_payload IS NULL THEN
    RAISE EXCEPTION 'self_order_vietqr_config_invalid' USING ERRCODE = '22023';
  END IF;

  v_config_snapshot := jsonb_strip_nulls(jsonb_build_object(
    'bankCode', v_bank_code,
    'accountNo', v_account_no,
    'accountName', COALESCE(v_account_name, '')
  ));

  INSERT INTO public.payments (
    tenant_id,
    branch_id,
    order_id,
    method,
    amount,
    status,
    provider_ref,
    provider_data,
    created_by
  )
  VALUES (
    v_order.tenant_id,
    v_order.branch_id,
    v_order.id,
    'vietqr',
    v_order.total_amount,
    'pending',
    v_payment_code,
    jsonb_build_object(
      'source', 'qr_self_order',
      'description', v_payment_code,
      'invoicePayload', v_invoice_payload
    ),
    v_order.created_by
  )
  RETURNING id INTO v_payment_id;

  UPDATE public.orders
  SET payment_status = 'pending',
      payment_method = 'vietqr',
      updated_at = now()
  WHERE id = v_order.id
    AND tenant_id = v_order.tenant_id;

  INSERT INTO public.self_order_payment_requests (
    tenant_id,
    branch_id,
    table_id,
    order_id,
    payment_id,
    client_op_id,
    method,
    status,
    amount_snapshot,
    invoice_payload,
    request_fingerprint,
    request_fingerprint_version,
    payment_code_snapshot,
    qr_payload_snapshot,
    vietqr_config_snapshot,
    expires_at
  )
  VALUES (
    v_order.tenant_id,
    v_order.branch_id,
    v_order.table_id,
    v_order.id,
    v_payment_id,
    p_client_op_id,
    'vietqr',
    'vietqr_pending',
    v_order.total_amount,
    v_invoice_payload,
    v_fingerprint,
    'payment:v1',
    v_payment_code,
    v_qr_payload,
    v_config_snapshot,
    now() + interval '30 minutes'
  )
  RETURNING * INTO v_existing;

  RETURN jsonb_build_object('ok', true)
    || public.self_order_payment_request_public_payload(v_existing.id);
END;
$_$;


--
-- Name: self_order_enforce_open_pos_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_enforce_open_pos_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint;
  v_branch_id bigint;
  v_should_check boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_tenant_id := NEW.tenant_id;
    v_branch_id := NEW.branch_id;
    v_should_check := true;
  ELSIF TG_OP = 'UPDATE'
        AND TG_TABLE_NAME = 'self_order_batches'
        AND OLD.status IS DISTINCT FROM NEW.status
        AND NEW.status IN ('accepted', 'auto_accepted') THEN
    v_tenant_id := COALESCE(NEW.tenant_id, OLD.tenant_id);
    v_branch_id := COALESCE(NEW.branch_id, OLD.branch_id);
    v_should_check := true;
  END IF;

  IF v_should_check
     AND NOT public.self_order_branch_has_open_pos_session(v_tenant_id, v_branch_id) THEN
    RAISE EXCEPTION 'self_order_pos_session_closed' USING ERRCODE = 'P0002';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: self_order_enforce_payment_request_invariants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_enforce_payment_request_invariants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id
     OR OLD.branch_id IS DISTINCT FROM NEW.branch_id
     OR OLD.table_id IS DISTINCT FROM NEW.table_id
     OR OLD.order_id IS DISTINCT FROM NEW.order_id
     OR OLD.client_op_id IS DISTINCT FROM NEW.client_op_id
     OR OLD.method IS DISTINCT FROM NEW.method
     OR OLD.amount_snapshot IS DISTINCT FROM NEW.amount_snapshot
     OR OLD.invoice_payload IS DISTINCT FROM NEW.invoice_payload
     OR OLD.request_fingerprint IS DISTINCT FROM NEW.request_fingerprint
     OR OLD.request_fingerprint_version IS DISTINCT FROM NEW.request_fingerprint_version
     OR OLD.payment_code_snapshot IS DISTINCT FROM NEW.payment_code_snapshot
     OR OLD.qr_payload_snapshot IS DISTINCT FROM NEW.qr_payload_snapshot
     OR OLD.vietqr_config_snapshot IS DISTINCT FROM NEW.vietqr_config_snapshot
     OR OLD.expires_at IS DISTINCT FROM NEW.expires_at THEN
    RAISE EXCEPTION 'self_order_payment_request_immutable' USING ERRCODE = '22023';
  END IF;

  IF OLD.payment_id IS DISTINCT FROM NEW.payment_id
     AND NOT (
       NEW.payment_id IS NOT NULL
       AND NEW.status = 'completed'
       AND (
         (
           OLD.payment_id IS NULL
           AND OLD.status IN ('cash_call', 'vietqr_pending')
         )
         OR (
           OLD.status = 'cancelled'
           AND OLD.method = 'vietqr'
           AND OLD.cancel_reason = 'guest_cancelled_vietqr'
         )
       )
     ) THEN
    RAISE EXCEPTION 'self_order_payment_binding_immutable' USING ERRCODE = '22023';
  END IF;

  IF OLD.cancel_reason IS DISTINCT FROM NEW.cancel_reason
     AND NOT (
       OLD.cancel_reason IS NULL
       AND NEW.cancel_reason IS NOT NULL
       AND OLD.status IN ('cash_call', 'vietqr_pending')
       AND NEW.status = 'cancelled'
     ) THEN
    RAISE EXCEPTION 'self_order_payment_cancel_reason_immutable' USING ERRCODE = '22023';
  END IF;

  IF OLD.status IS DISTINCT FROM NEW.status
     AND NOT (
       (
         OLD.status IN ('cash_call', 'vietqr_pending')
         AND NEW.status IN ('completed', 'cancelled', 'expired')
       )
       OR (
         OLD.status = 'cancelled'
         AND OLD.method = 'vietqr'
         AND OLD.cancel_reason = 'guest_cancelled_vietqr'
         AND NEW.status = 'completed'
       )
     ) THEN
    RAISE EXCEPTION 'self_order_invalid_payment_request_transition' USING ERRCODE = '22023';
  END IF;

  IF NEW.status = 'completed'
     AND (NEW.completed_at IS NULL OR NEW.payment_id IS NULL) THEN
    RAISE EXCEPTION 'self_order_completed_request_missing_payment_evidence' USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'cancelled' AND NEW.cancelled_at IS NULL THEN
    RAISE EXCEPTION 'self_order_cancelled_request_missing_timestamp' USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'expired' AND NEW.expired_at IS NULL THEN
    RAISE EXCEPTION 'self_order_expired_request_missing_timestamp' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: self_order_expire_payment_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_expire_payment_request(p_request_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request_ref public.self_order_payment_requests%ROWTYPE;
  v_request public.self_order_payment_requests%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_payment_found boolean := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT pr.*
  INTO v_request_ref
  FROM public.self_order_payment_requests pr
  WHERE pr.id = p_request_id;

  IF NOT FOUND
     OR v_request_ref.status NOT IN ('cash_call', 'vietqr_pending')
     OR v_request_ref.expires_at > now() THEN
    RETURN false;
  END IF;

  SELECT o.*
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_request_ref.order_id
    AND o.tenant_id = v_request_ref.tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_payment_order_missing' USING ERRCODE = '23503';
  END IF;
  IF NOT pg_try_advisory_xact_lock(v_order.id) THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END IF;

  BEGIN
    SELECT p.*
    INTO v_payment
    FROM public.payments p
    WHERE p.tenant_id = v_request_ref.tenant_id
      AND p.order_id = v_request_ref.order_id
      AND (
        p.id = v_request_ref.payment_id
        OR (
          v_request_ref.payment_id IS NULL
          AND v_request_ref.method = 'cash_call'
          AND p.method = 'cash'
          AND p.status = 'completed'
        )
      )
    ORDER BY
      CASE WHEN p.id = v_request_ref.payment_id THEN 0 ELSE 1 END,
      p.id DESC
    LIMIT 1
    FOR UPDATE NOWAIT;
    v_payment_found := FOUND;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
  END;

  SELECT pr.*
  INTO v_request
  FROM public.self_order_payment_requests pr
  WHERE pr.id = p_request_id
    AND pr.tenant_id = v_request_ref.tenant_id
    AND pr.order_id = v_request_ref.order_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_request.status NOT IN ('cash_call', 'vietqr_pending')
     OR v_request.expires_at > now() THEN
    RETURN false;
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid'
     OR (v_payment_found AND v_payment.status = 'completed') THEN
    UPDATE public.self_order_payment_requests
    SET status = 'completed',
        payment_id = COALESCE(
          v_request.payment_id,
          CASE WHEN v_payment_found THEN v_payment.id ELSE NULL END
        ),
        completed_at = COALESCE(
          CASE WHEN v_payment_found THEN v_payment.paid_at ELSE NULL END,
          now()
        )
    WHERE id = v_request.id
      AND status IN ('cash_call', 'vietqr_pending');
    RETURN false;
  END IF;

  UPDATE public.self_order_payment_requests
  SET status = 'expired',
      expired_at = now()
  WHERE id = v_request.id
    AND status IN ('cash_call', 'vietqr_pending');

  IF v_payment_found AND v_payment.status = 'pending' THEN
    UPDATE public.payments
    SET status = 'failed',
        updated_at = now()
    WHERE id = v_payment.id
      AND status = 'pending';
  END IF;

  IF v_request.method = 'vietqr' THEN
    UPDATE public.orders o
    SET payment_status = 'unpaid',
        payment_method = NULL,
        updated_at = now()
    WHERE o.id = v_request.order_id
      AND o.tenant_id = v_request.tenant_id
      AND COALESCE(o.payment_status, 'unpaid') <> 'paid'
      AND NOT EXISTS (
        SELECT 1
        FROM public.payments p
        WHERE p.tenant_id = v_request.tenant_id
          AND p.order_id = v_request.order_id
          AND p.status IN ('pending', 'completed')
      );
  END IF;

  RETURN true;
END;
$$;


--
-- Name: self_order_fill_payment_request_fingerprint(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_fill_payment_request_fingerprint() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.request_fingerprint IS NULL THEN
    NEW.request_fingerprint := public.self_order_payment_request_fingerprint(
      NEW.method,
      NEW.invoice_payload
    );
    NEW.request_fingerprint_version := 'payment:v1';
  ELSIF NEW.request_fingerprint_version IS NULL THEN
    NEW.request_fingerprint_version := 'payment:v1';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: self_order_get_payment_request_status(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_get_payment_request_status(p_token text, p_client_op_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_table record;
  v_status text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT t.id AS table_id, t.tenant_id
  INTO v_table
  FROM public.tables t
  JOIN public.branches b
    ON b.id = t.branch_id
   AND b.tenant_id = t.tenant_id
   AND b.is_active = true
  WHERE t.self_order_token = p_token
    AND t.self_order_enabled = true
    AND t.status <> 'maintenance'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'invalid_or_disabled_token');
  END IF;

  SELECT pr.status
  INTO v_status
  FROM public.self_order_payment_requests pr
  WHERE pr.tenant_id = v_table.tenant_id
    AND pr.table_id = v_table.table_id
    AND pr.client_op_id = p_client_op_id
  ORDER BY pr.id DESC
  LIMIT 1;

  RETURN jsonb_build_object('ok', true, 'status', v_status);
END;
$$;


--
-- Name: self_order_get_snapshot(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_get_snapshot(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;
  RETURN public.self_order_get_snapshot(p_token, NULL::uuid);
END;
$$;


--
-- Name: self_order_get_snapshot(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_get_snapshot(p_token text, p_client_op_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_table record;
  v_request public.self_order_requests%ROWTYPE;
  v_request_found boolean := false;
  v_open_order_count integer := 0;
  v_order_id bigint;
  v_order_payload jsonb := NULL;
  v_rounds_payload jsonb := '[]'::jsonb;
  v_payment_payload jsonb := NULL;
  v_request_payload jsonb := NULL;
  v_state text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT
    t.id AS table_id,
    t.tenant_id,
    t.branch_id,
    t.number AS table_number,
    b.name AS branch_name
  INTO v_table
  FROM public.tables t
  JOIN public.branches b
    ON b.id = t.branch_id
   AND b.tenant_id = t.tenant_id
   AND b.is_active = true
  WHERE t.self_order_token = p_token
    AND t.self_order_enabled = true
    AND t.status <> 'maintenance'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'invalid_or_disabled_token');
  END IF;

  IF NOT public.self_order_branch_has_open_pos_session(
    v_table.tenant_id,
    v_table.branch_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'pos_session_closed');
  END IF;

  SELECT r.*
  INTO v_request
  FROM public.self_order_requests r
  WHERE r.tenant_id = v_table.tenant_id
    AND r.table_id = v_table.table_id
    AND r.status = 'pending'
  ORDER BY r.id DESC
  LIMIT 1;
  v_request_found := FOUND;

  IF NOT v_request_found AND p_client_op_id IS NOT NULL THEN
    SELECT r.*
    INTO v_request
    FROM public.self_order_requests r
    WHERE r.tenant_id = v_table.tenant_id
      AND r.table_id = v_table.table_id
      AND r.client_op_id = p_client_op_id
      AND r.status = 'rejected'
    ORDER BY r.id DESC
    LIMIT 1;
    v_request_found := FOUND;
  END IF;

  IF v_request_found THEN
    v_request_payload := jsonb_build_object(
      'id', v_request.id,
      'clientOpId', v_request.client_op_id,
      'status', v_request.status,
      'items', v_request.cart_payload,
      'customerNote', v_request.customer_note,
      'orderId', v_request.order_id,
      'createdAt', v_request.created_at,
      'decidedAt', v_request.decided_at
    );
  END IF;

  SELECT count(*)::integer, min(o.id)
  INTO v_open_order_count, v_order_id
  FROM public.orders o
  WHERE o.tenant_id = v_table.tenant_id
    AND o.branch_id = v_table.branch_id
    AND o.table_id = v_table.table_id
    AND o.payment_status <> 'paid'
    AND o.status NOT IN ('completed', 'cancelled')
    AND o.merged_into_order_id IS NULL;

  IF v_open_order_count = 1 THEN
    SELECT jsonb_build_object(
      'id', o.id,
      'orderNumber', o.order_number,
      'status', o.status,
      'paymentStatus', o.payment_status,
      'paymentMethod', o.payment_method,
      'subtotal', o.subtotal,
      'serviceCharge', o.service_charge,
      'discountAmount', o.discount_amount,
      'totalAmount', o.total_amount,
      'itemCount', (
        SELECT COALESCE(sum(oi.quantity), 0)::integer
        FROM public.order_items oi
        WHERE oi.tenant_id = o.tenant_id
          AND oi.order_id = o.id
          AND oi.status <> 'cancelled'
      ),
      'items', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'id', oi.id,
            'menuItemId', oi.menu_item_id,
            'itemName', oi.item_name,
            'variantId', oi.variant_id,
            'variantName', oi.variant_name,
            'quantity', oi.quantity,
            'unitPrice', oi.unit_price,
            'lineTotal', oi.subtotal,
            'modifiers', COALESCE(oi.modifiers, '[]'::jsonb),
            'sides', COALESCE(oi.sides, '[]'::jsonb),
            'note', oi.note
          ) ORDER BY oi.id
        ), '[]'::jsonb)
        FROM public.order_items oi
        WHERE oi.tenant_id = o.tenant_id
          AND oi.order_id = o.id
          AND oi.status <> 'cancelled'
      )
    )
    INTO v_order_payload
    FROM public.orders o
    WHERE o.id = v_order_id
      AND o.tenant_id = v_table.tenant_id;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', ksb.id,
        'sendSeq', ksb.send_seq,
        'kind', ksb.kind,
        'ticketNumber', ksb.kitchen_ticket_number,
        'createdAt', ksb.created_at,
        'items', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', lines.id,
              'itemName', lines.item_name,
              'variantName', lines.variant_name,
              'quantity', lines.quantity,
              'modifiers', lines.modifiers,
              'sides', lines.sides,
              'note', lines.note
            ) ORDER BY lines.id
          )
          FROM (
            SELECT DISTINCT ON (oi.id)
              oi.id,
              oi.item_name,
              oi.variant_name,
              oi.quantity,
              COALESCE(oi.modifiers, '[]'::jsonb) AS modifiers,
              COALESCE(oi.sides, '[]'::jsonb) AS sides,
              oi.note
            FROM public.kds_tickets kt
            JOIN public.order_items oi
              ON oi.id = kt.order_item_id
             AND oi.tenant_id = kt.tenant_id
            WHERE kt.tenant_id = v_table.tenant_id
              AND kt.kitchen_send_batch_id = ksb.id
            ORDER BY oi.id, kt.id
          ) lines
        ), '[]'::jsonb)
      ) ORDER BY ksb.send_seq
    ), '[]'::jsonb)
    INTO v_rounds_payload
    FROM public.kitchen_send_batches ksb
    WHERE ksb.tenant_id = v_table.tenant_id
      AND ksb.order_id = v_order_id;

    SELECT public.self_order_payment_request_public_payload(pr.id)
    INTO v_payment_payload
    FROM public.self_order_payment_requests pr
    WHERE pr.tenant_id = v_table.tenant_id
      AND pr.order_id = v_order_id
      AND pr.status IN ('cash_call', 'vietqr_pending')
      AND pr.expires_at > now()
    ORDER BY pr.id DESC
    LIMIT 1;
  END IF;

  v_state := CASE
    WHEN v_request_found AND v_request.status = 'pending'
      THEN 'awaiting_confirmation'
    WHEN v_open_order_count > 1
      THEN 'multiple_open_orders'
    WHEN v_open_order_count = 1 AND v_payment_payload IS NOT NULL
      THEN 'payment_pending'
    WHEN v_open_order_count = 1
      THEN 'open'
    WHEN v_request_found AND v_request.status = 'rejected'
      THEN 'rejected'
    ELSE 'unopened'
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'state', v_state,
    'branch', jsonb_build_object('name', v_table.branch_name),
    'table', jsonb_build_object(
      'id', v_table.table_id,
      'number', v_table.table_number
    ),
    'openOrderCount', v_open_order_count,
    'order', CASE WHEN v_open_order_count = 1 THEN v_order_payload ELSE NULL END,
    'rounds', CASE WHEN v_open_order_count = 1 THEN v_rounds_payload ELSE '[]'::jsonb END,
    'request', v_request_payload,
    'paymentRequest', CASE WHEN v_open_order_count = 1 THEN v_payment_payload ELSE NULL END,
    'menu', public.self_order_menu_payload(v_table.tenant_id)
  );
END;
$$;


--
-- Name: self_order_guard_table_token_rotation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_guard_table_token_rotation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT pg_try_advisory_xact_lock(
    hashtext('self-order-table'),
    hashtext(OLD.id::text)
  ) THEN
    RAISE EXCEPTION 'self_order_operation_in_progress' USING ERRCODE = '55P03';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: self_order_menu_payload(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_menu_payload(p_tenant_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'name', c.name,
      'type', c.type,
      'sort_order', c.sort_order,
      'menu_items', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', mi.id,
            'name', mi.name,
            'description', mi.description,
            'base_price', mi.base_price,
            'image_url', mi.image_url,
            'sort_order', mi.sort_order,
            'menu_item_variants', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'id', v.id,
                  'name', v.name,
                  'price_adjustment', v.price_adjustment,
                  'sort_order', v.sort_order
                )
                ORDER BY v.sort_order, v.id
              )
              FROM public.menu_item_variants v
              WHERE v.tenant_id = mi.tenant_id
                AND v.item_id = mi.id
                AND v.is_active = true
            ), '[]'::jsonb),
            'menu_item_modifiers', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'id', m.id,
                  'name', m.name,
                  'price', m.price,
                  'sort_order', m.sort_order
                )
                ORDER BY m.sort_order, m.id
              )
              FROM public.menu_item_modifiers m
              WHERE m.tenant_id = mi.tenant_id
                AND m.item_id = mi.id
                AND m.is_active = true
            ), '[]'::jsonb),
            'menu_item_available_sides', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'id', s.id,
                  'is_default', s.is_default,
                  'side_item', jsonb_build_object(
                    'id', side_item.id,
                    'name', side_item.name,
                    'base_price', side_item.base_price
                  )
                )
                ORDER BY side_item.sort_order, side_item.id
              )
              FROM public.menu_item_available_sides s
              JOIN public.menu_items side_item
                ON side_item.id = s.side_item_id
               AND side_item.tenant_id = s.tenant_id
               AND side_item.is_active = true
              WHERE s.tenant_id = mi.tenant_id
                AND s.main_item_id = mi.id
            ), '[]'::jsonb)
          )
          ORDER BY mi.sort_order, mi.id
        )
        FROM public.menu_items mi
        WHERE mi.tenant_id = c.tenant_id
          AND mi.category_id = c.id
          AND mi.is_active = true
      ), '[]'::jsonb)
    )
    ORDER BY c.sort_order, c.id
  ), '[]'::jsonb)
  FROM public.menu_categories c
  WHERE c.tenant_id = p_tenant_id
    AND c.is_active = true;
$$;


--
-- Name: self_order_normalize_invoice_payload(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_normalize_invoice_payload(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_buyer_name text := btrim(COALESCE(v_payload ->> 'buyerName', ''));
  v_tax_code text := btrim(COALESCE(v_payload ->> 'buyerTaxCode', ''));
  v_address text := btrim(COALESCE(v_payload ->> 'buyerAddress', ''));
  v_email text := btrim(COALESCE(v_payload ->> 'buyerEmail', ''));
  v_not_get boolean := COALESCE((v_payload ->> 'buyerNotGetInvoice')::boolean, false);
BEGIN
  IF v_not_get
     OR (v_buyer_name = '' AND v_tax_code = '' AND v_address = '' AND v_email = '') THEN
    RETURN jsonb_build_object(
      'buyerName', 'Bán cho người tiêu dùng',
      'buyerNotGetInvoice', true
    );
  END IF;

  IF v_tax_code <> '' THEN
    IF v_buyer_name = '' OR v_address = '' THEN
      RAISE EXCEPTION 'invalid_invoice_payload' USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'buyerName', NULLIF(v_buyer_name, ''),
    'buyerTaxCode', NULLIF(v_tax_code, ''),
    'buyerAddress', NULLIF(v_address, ''),
    'buyerEmail', NULLIF(v_email, ''),
    'buyerNotGetInvoice', false
  ));
END;
$$;


--
-- Name: self_order_payment_request_fingerprint(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_payment_request_fingerprint(p_method text, p_invoice_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'version', 'payment:v1',
          'method', p_method,
          'invoice', COALESCE(p_invoice_payload, '{}'::jsonb)
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: self_order_payment_request_public_payload(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_payment_request_public_payload(p_request_id bigint) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'id', pr.id,
    'clientOpId', pr.client_op_id,
    'status', pr.status,
    'method', pr.method,
    'amount', pr.amount_snapshot,
    'paymentId', pr.payment_id,
    'paymentCode', pr.payment_code_snapshot,
    'qrData', pr.qr_payload_snapshot,
    'bankCode', pr.vietqr_config_snapshot ->> 'bankCode',
    'accountNo', pr.vietqr_config_snapshot ->> 'accountNo',
    'accountName', pr.vietqr_config_snapshot ->> 'accountName',
    'createdAt', pr.created_at,
    'expiresAt', pr.expires_at
  ))
  FROM public.self_order_payment_requests pr
  WHERE pr.id = p_request_id;
$$;


--
-- Name: self_order_reconcile_expired_payment_requests(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_reconcile_expired_payment_requests(p_tenant_id bigint, p_branch_id bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_candidate record;
  v_count integer := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  FOR v_candidate IN
    SELECT pr.id, pr.order_id
    FROM public.self_order_payment_requests pr
    WHERE pr.tenant_id = p_tenant_id
      AND pr.branch_id = p_branch_id
      AND pr.status IN ('cash_call', 'vietqr_pending')
      AND pr.expires_at <= now()
    ORDER BY pr.order_id, pr.id
  LOOP
    BEGIN
      PERFORM 1
      FROM public.orders o
      WHERE o.id = v_candidate.order_id
        AND o.tenant_id = p_tenant_id
      FOR UPDATE SKIP LOCKED;

      IF NOT FOUND THEN
        CONTINUE;
      END IF;
      IF NOT pg_try_advisory_xact_lock(v_candidate.order_id) THEN
        RAISE EXCEPTION 'self_order_retry' USING ERRCODE = '40001';
      END IF;
      IF public.self_order_expire_payment_request(v_candidate.id) THEN
        v_count := v_count + 1;
      END IF;
    EXCEPTION WHEN serialization_failure THEN
      RAISE NOTICE 'Skipped busy self-order payment request %', v_candidate.id;
    END;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: self_order_reject_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_reject_request(p_request_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request_ref public.self_order_requests%ROWTYPE;
  v_request public.self_order_requests%ROWTYPE;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT r.*
  INTO v_request_ref
  FROM public.self_order_requests r
  WHERE r.id = p_request_id
    AND r.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_request_ref.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'permission denied: pos:use' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('self-order-table'),
    hashtext(v_request_ref.table_id::text)
  );

  SELECT r.*
  INTO v_request
  FROM public.self_order_requests r
  WHERE r.id = v_request_ref.id
    AND r.tenant_id = v_request_ref.tenant_id
  FOR UPDATE;

  IF v_request.status = 'rejected' THEN
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'status', 'rejected');
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'self_order_request_not_pending' USING ERRCODE = '22023';
  END IF;

  UPDATE public.self_order_requests
  SET status = 'rejected',
      decided_by = v_uid,
      decided_at = now()
  WHERE id = v_request.id
    AND tenant_id = v_request.tenant_id
    AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'self_order_request_not_pending' USING ERRCODE = '40001';
  END IF;

  RETURN jsonb_build_object('ok', true, 'status', 'rejected');
END;
$$;


--
-- Name: self_order_scope_hash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_scope_hash(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT encode(
    extensions.digest(convert_to(COALESCE(p_value, ''), 'UTF8'), 'sha256'),
    'hex'
  );
$$;


--
-- Name: self_order_set_actor_claims(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_set_actor_claims(p_actor uuid, p_tenant_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM set_config('request.jwt.claim.sub', p_actor::text, true);
  PERFORM set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'sub', p_actor::text,
      'role', 'authenticated',
      'app_metadata', jsonb_build_object('tenant_id', p_tenant_id)
    )::text,
    true
  );
END;
$$;


--
-- Name: self_order_submit(text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_submit(p_token text, p_items jsonb, p_customer_note text, p_client_op_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_table public.tables%ROWTYPE;
  v_existing public.self_order_requests%ROWTYPE;
  v_pending_request public.self_order_requests%ROWTYPE;
  v_operation public.self_order_request_operations%ROWTYPE;
  v_operation_found boolean := false;
  v_order public.orders%ROWTYPE;
  v_active_request public.self_order_payment_requests%ROWTYPE;
  v_items jsonb;
  v_merged_items jsonb;
  v_note text := NULLIF(btrim(COALESCE(p_customer_note, '')), '');
  v_merged_note text;
  v_open_order_count integer := 0;
  v_order_id bigint;
  v_request_id bigint;
  v_result jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;
  IF p_client_op_id IS NULL THEN
    RAISE EXCEPTION 'self_order_missing_operation_id' USING ERRCODE = '22023';
  END IF;
  IF v_note IS NOT NULL AND char_length(v_note) > 500 THEN
    RAISE EXCEPTION 'self_order_customer_note_too_long' USING ERRCODE = '22023';
  END IF;

  SELECT t.*
  INTO v_table
  FROM public.tables t
  JOIN public.branches b
    ON b.id = t.branch_id
   AND b.tenant_id = t.tenant_id
   AND b.is_active = true
  WHERE t.self_order_token = p_token
    AND t.self_order_enabled = true
    AND t.status <> 'maintenance'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'invalid_or_disabled_token');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('self-order-table'),
    hashtext(v_table.id::text)
  );

  SELECT t.*
  INTO v_table
  FROM public.tables t
  WHERE t.id = v_table.id
    AND t.self_order_token = p_token
    AND t.self_order_enabled = true
    AND t.status <> 'maintenance';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'invalid_or_disabled_token');
  END IF;
  IF NOT public.self_order_branch_has_open_pos_session(
    v_table.tenant_id,
    v_table.branch_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'pos_session_closed');
  END IF;

  v_items := public.self_order_canonicalize_cart(v_table.tenant_id, p_items);

  SELECT r.*
  INTO v_existing
  FROM public.self_order_requests r
  WHERE r.tenant_id = v_table.tenant_id
    AND r.client_op_id = p_client_op_id
  FOR UPDATE;

  IF FOUND THEN
    SELECT o.*
    INTO v_operation
    FROM public.self_order_request_operations o
    WHERE o.tenant_id = v_table.tenant_id
      AND o.client_op_id = p_client_op_id
    FOR UPDATE;
    v_operation_found := FOUND;

    IF v_existing.table_id <> v_table.id
       OR (
         SELECT jsonb_agg(item.value - 'key' ORDER BY item.ordinality)
         FROM jsonb_array_elements(
           CASE
             WHEN v_operation_found THEN v_operation.cart_payload
             ELSE v_existing.cart_payload
           END
         ) WITH ORDINALITY AS item(value, ordinality)
       ) IS DISTINCT FROM (
         SELECT jsonb_agg(item.value - 'key' ORDER BY item.ordinality)
         FROM jsonb_array_elements(v_items)
           WITH ORDINALITY AS item(value, ordinality)
       )
       OR (
         CASE
           WHEN v_operation_found THEN v_operation.customer_note
           ELSE v_existing.customer_note
         END
       ) IS DISTINCT FROM v_note THEN
      RAISE EXCEPTION 'self_order_idempotency_conflict' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'requestId', v_existing.id,
      'status', v_existing.status,
      'orderId', v_existing.order_id
    );
  END IF;

  SELECT o.*
  INTO v_operation
  FROM public.self_order_request_operations o
  WHERE o.tenant_id = v_table.tenant_id
    AND o.client_op_id = p_client_op_id
  FOR UPDATE;

  IF FOUND THEN
    SELECT r.*
    INTO v_existing
    FROM public.self_order_requests r
    WHERE r.id = v_operation.request_id
      AND r.tenant_id = v_operation.tenant_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_existing.table_id <> v_table.id
       OR (
         SELECT jsonb_agg(item.value - 'key' ORDER BY item.ordinality)
         FROM jsonb_array_elements(v_operation.cart_payload)
           WITH ORDINALITY AS item(value, ordinality)
       ) IS DISTINCT FROM (
         SELECT jsonb_agg(item.value - 'key' ORDER BY item.ordinality)
         FROM jsonb_array_elements(v_items)
           WITH ORDINALITY AS item(value, ordinality)
       )
       OR v_operation.customer_note IS DISTINCT FROM v_note THEN
      RAISE EXCEPTION 'self_order_idempotency_conflict' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'requestId', v_existing.id,
      'status', v_existing.status,
      'orderId', v_existing.order_id
    );
  END IF;

  SELECT r.*
  INTO v_pending_request
  FROM public.self_order_requests r
  WHERE r.tenant_id = v_table.tenant_id
    AND r.table_id = v_table.id
    AND r.status = 'pending'
  ORDER BY r.id DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    v_merged_items := public.self_order_canonicalize_cart(
      v_table.tenant_id,
      v_pending_request.cart_payload || v_items
    );
    v_merged_note := NULLIF(
      concat_ws(E'\n', v_pending_request.customer_note, v_note),
      ''
    );
    IF v_merged_note IS NOT NULL AND char_length(v_merged_note) > 500 THEN
      RAISE EXCEPTION 'self_order_customer_note_too_long' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.self_order_request_operations (
      tenant_id,
      client_op_id,
      request_id,
      cart_payload,
      customer_note
    )
    VALUES (
      v_pending_request.tenant_id,
      v_pending_request.client_op_id,
      v_pending_request.id,
      v_pending_request.cart_payload,
      v_pending_request.customer_note
    )
    ON CONFLICT (tenant_id, client_op_id) DO NOTHING;

    UPDATE public.self_order_requests
    SET cart_payload = v_merged_items,
        customer_note = v_merged_note
    WHERE id = v_pending_request.id
      AND tenant_id = v_pending_request.tenant_id
      AND status = 'pending'
    RETURNING id INTO v_request_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'self_order_request_not_pending' USING ERRCODE = '40001';
    END IF;

    INSERT INTO public.self_order_request_operations (
      tenant_id,
      client_op_id,
      request_id,
      cart_payload,
      customer_note
    )
    VALUES (
      v_table.tenant_id,
      p_client_op_id,
      v_request_id,
      v_items,
      v_note
    );

    RETURN jsonb_build_object(
      'ok', true,
      'requestId', v_request_id,
      'status', 'pending'
    );
  END IF;

  SELECT count(*)::integer, min(o.id)
  INTO v_open_order_count, v_order_id
  FROM public.orders o
  WHERE o.tenant_id = v_table.tenant_id
    AND o.branch_id = v_table.branch_id
    AND o.table_id = v_table.id
    AND o.payment_status <> 'paid'
    AND o.status NOT IN ('completed', 'cancelled')
    AND o.merged_into_order_id IS NULL;

  IF v_open_order_count = 1 THEN
    SELECT o.*
    INTO v_order
    FROM public.orders o
    WHERE o.id = v_order_id
      AND o.tenant_id = v_table.tenant_id
    FOR UPDATE;

    SELECT pr.*
    INTO v_active_request
    FROM public.self_order_payment_requests pr
    WHERE pr.tenant_id = v_order.tenant_id
      AND pr.order_id = v_order.id
      AND pr.status IN ('cash_call', 'vietqr_pending')
    ORDER BY pr.id DESC
    LIMIT 1;

    IF FOUND AND v_active_request.expires_at <= now() THEN
      PERFORM public.self_order_expire_payment_request(v_active_request.id);
    END IF;

    IF public.self_order_active_payment_lock(v_order.id) IS NOT NULL THEN
      RAISE EXCEPTION 'self_order_pending_payment_exists' USING ERRCODE = '55P03';
    END IF;

    PERFORM public.self_order_set_actor_claims(v_order.created_by, v_order.tenant_id);
    v_result := public.append_order_items(v_order.id, v_items, p_client_op_id);

    INSERT INTO public.self_order_requests (
      tenant_id,
      branch_id,
      table_id,
      cart_payload,
      customer_note,
      client_op_id,
      status,
      order_id,
      decided_by,
      decided_at
    )
    VALUES (
      v_table.tenant_id,
      v_table.branch_id,
      v_table.id,
      v_items,
      v_note,
      p_client_op_id,
      'accepted',
      v_order.id,
      v_order.created_by,
      now()
    )
    RETURNING id INTO v_request_id;

    RETURN COALESCE(v_result, '{}'::jsonb) || jsonb_build_object(
      'ok', true,
      'requestId', v_request_id,
      'status', 'accepted',
      'orderId', v_order.id
    );
  END IF;

  BEGIN
    INSERT INTO public.self_order_requests (
      tenant_id,
      branch_id,
      table_id,
      cart_payload,
      customer_note,
      client_op_id,
      status
    )
    VALUES (
      v_table.tenant_id,
      v_table.branch_id,
      v_table.id,
      v_items,
      v_note,
      p_client_op_id,
      'pending'
    )
    RETURNING id INTO v_request_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'self_order_pending_request_exists' USING ERRCODE = '55P03';
  END;

  INSERT INTO public.self_order_request_operations (
    tenant_id,
    client_op_id,
    request_id,
    cart_payload,
    customer_note
  )
  VALUES (
    v_table.tenant_id,
    p_client_op_id,
    v_request_id,
    v_items,
    v_note
  );

  RETURN jsonb_build_object(
    'ok', true,
    'requestId', v_request_id,
    'status', 'pending',
    'openOrderCount', v_open_order_count
  );
END;
$$;


--
-- Name: self_order_sync_payment_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_sync_payment_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_status_changed boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_status_changed := true;
  ELSIF TG_OP = 'UPDATE' THEN
    v_status_changed := OLD.status IS DISTINCT FROM NEW.status;
  END IF;

  IF NEW.status = 'completed' AND v_status_changed THEN
    UPDATE public.self_order_payment_requests pr
    SET status = 'completed',
        payment_id = COALESCE(pr.payment_id, NEW.id),
        completed_at = COALESCE(NEW.paid_at, now())
    WHERE pr.tenant_id = NEW.tenant_id
      AND pr.order_id = NEW.order_id
      AND pr.status IN ('cash_call', 'vietqr_pending')
      AND (
        pr.payment_id = NEW.id
        OR (
          pr.payment_id IS NULL
          AND pr.method = 'cash_call'
          AND NEW.method = 'cash'
        )
        OR (
          pr.method = 'vietqr'
          AND NEW.method = 'vietqr'
        )
      );

    IF NOT FOUND AND NEW.method = 'vietqr' THEN
      UPDATE public.self_order_payment_requests pr
      SET status = 'completed',
          payment_id = NEW.id,
          completed_at = COALESCE(NEW.paid_at, now())
      WHERE pr.id = (
        SELECT candidate.id
        FROM public.self_order_payment_requests candidate
        WHERE candidate.tenant_id = NEW.tenant_id
          AND candidate.order_id = NEW.order_id
          AND candidate.method = 'vietqr'
          AND candidate.status = 'cancelled'
          AND candidate.cancel_reason = 'guest_cancelled_vietqr'
          AND candidate.amount_snapshot = NEW.amount
          AND candidate.payment_code_snapshot IS NOT NULL
          AND NULLIF(btrim(COALESCE(NEW.provider_ref, '')), '') IS NOT NULL
          AND lower(COALESCE(candidate.payment_code_snapshot, ''))
            = lower(COALESCE(NEW.provider_ref, ''))
        ORDER BY candidate.id DESC
        LIMIT 1
      );
    END IF;
  ELSIF NEW.status = 'failed' AND v_status_changed THEN
    UPDATE public.self_order_payment_requests pr
    SET status = 'cancelled',
        cancelled_at = now(),
        cancel_reason = COALESCE(pr.cancel_reason, 'payment_failed')
    WHERE pr.tenant_id = NEW.tenant_id
      AND pr.payment_id = NEW.id
      AND pr.status IN ('cash_call', 'vietqr_pending');

    IF FOUND THEN
      UPDATE public.orders o
      SET payment_status = 'unpaid',
          payment_method = NULL,
          updated_at = now()
      WHERE o.id = NEW.order_id
        AND o.tenant_id = NEW.tenant_id
        AND COALESCE(o.payment_status, 'unpaid') <> 'paid'
        AND NOT EXISTS (
          SELECT 1
          FROM public.payments p
          WHERE p.tenant_id = NEW.tenant_id
            AND p.order_id = NEW.order_id
            AND p.status IN ('pending', 'completed')
        );
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: self_order_sync_payment_request_from_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_sync_payment_request_from_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_reason text;
  v_payment_id bigint;
  v_payment_method text;
  v_paid_at timestamptz;
BEGIN
  IF NEW.payment_status = 'paid' THEN
    SELECT p.id, p.method, p.paid_at
    INTO v_payment_id, v_payment_method, v_paid_at
    FROM public.payments p
    WHERE p.tenant_id = NEW.tenant_id
      AND p.branch_id = NEW.branch_id
      AND p.order_id = NEW.id
      AND p.status = 'completed'
    ORDER BY p.paid_at DESC NULLS LAST, p.id DESC
    LIMIT 1;

    IF v_payment_id IS NULL THEN
      RETURN NULL;
    END IF;

    UPDATE public.self_order_payment_requests pr
    SET status = 'completed',
        payment_id = COALESCE(pr.payment_id, v_payment_id),
        completed_at = COALESCE(v_paid_at, now())
    WHERE pr.tenant_id = NEW.tenant_id
      AND pr.branch_id = NEW.branch_id
      AND pr.order_id = NEW.id
      AND pr.status IN ('cash_call', 'vietqr_pending')
      AND (
        (pr.method = 'cash_call' AND v_payment_method = 'cash')
        OR (pr.method = 'vietqr' AND v_payment_method = 'vietqr')
      );

    UPDATE public.self_order_payment_requests pr
    SET status = 'cancelled',
        cancelled_at = now(),
        cancel_reason = COALESCE(pr.cancel_reason, 'order_paid_by_other_method')
    WHERE pr.tenant_id = NEW.tenant_id
      AND pr.branch_id = NEW.branch_id
      AND pr.order_id = NEW.id
      AND pr.status IN ('cash_call', 'vietqr_pending')
      AND NOT (
        (pr.method = 'cash_call' AND v_payment_method = 'cash')
        OR (pr.method = 'vietqr' AND v_payment_method = 'vietqr')
      );
  ELSIF NEW.status IN ('completed', 'cancelled') THEN
    v_reason := 'order_' || NEW.status;

    UPDATE public.self_order_payment_requests pr
    SET status = 'cancelled',
        cancelled_at = now(),
        cancel_reason = COALESCE(pr.cancel_reason, v_reason)
    WHERE pr.tenant_id = NEW.tenant_id
      AND pr.order_id = NEW.id
      AND pr.status IN ('cash_call', 'vietqr_pending');
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: self_order_take_rate_bucket(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_order_take_rate_bucket(p_purpose text, p_scope_type text, p_scope_hash text, p_limit integer, p_window_seconds integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_window_start timestamptz;
  v_hits integer;
  v_retry_after_seconds integer;
BEGIN
  IF p_purpose NOT IN ('batch', 'payment')
     OR p_scope_type NOT IN ('token', 'ip')
     OR p_scope_hash IS NULL
     OR p_scope_hash !~ '^[0-9a-f]{64}$'
     OR p_limit < 1
     OR p_window_seconds < 1 THEN
    RAISE EXCEPTION 'self_order_invalid_rate_limit_input' USING ERRCODE = '22023';
  END IF;

  v_window_start := to_timestamp(
    floor(extract(epoch FROM now()) / p_window_seconds) * p_window_seconds
  );

  DELETE FROM public.self_order_rate_buckets r
  WHERE r.ctid IN (
    SELECT stale.ctid
    FROM public.self_order_rate_buckets stale
    WHERE stale.expires_at <= now()
    ORDER BY stale.expires_at
    LIMIT 100
  );

  INSERT INTO public.self_order_rate_buckets (
    purpose,
    scope_type,
    scope_hash,
    window_start,
    hits,
    expires_at
  )
  VALUES (
    p_purpose,
    p_scope_type,
    p_scope_hash,
    v_window_start,
    1,
    v_window_start + make_interval(secs => p_window_seconds * 2)
  )
  ON CONFLICT (purpose, scope_type, scope_hash, window_start)
  DO UPDATE SET hits = self_order_rate_buckets.hits + 1
  RETURNING hits INTO v_hits;

  IF v_hits > p_limit THEN
    v_retry_after_seconds := GREATEST(
      1,
      ceil(extract(epoch FROM (
        v_window_start
        + make_interval(secs => p_window_seconds)
        - clock_timestamp()
      )))::integer
    );
    RAISE EXCEPTION 'self_order_rate_limited'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'retryAfterSeconds', v_retry_after_seconds
            )::text;
  END IF;

  RETURN v_hits;
END;
$_$;


--
-- Name: self_service_cancel_checkout(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_service_cancel_checkout(p_attendance_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.uid() IS NULL OR public.auth_role() = 'owner' THEN
    RAISE EXCEPTION 'self_service_not_allowed' USING ERRCODE = '42501';
  END IF;

  UPDATE public.attendance_records attendance
  SET checkout_requested_at = NULL,
      checkout_requested_by_role = NULL,
      checkout_approval_target_roles = ARRAY[]::text[],
      updated_at = now()
  FROM public.employees employee
  WHERE attendance.id = p_attendance_id
    AND attendance.employee_id = employee.id
    AND attendance.tenant_id = employee.tenant_id
    AND employee.profile_id = auth.uid()
    AND attendance.check_out IS NULL
    AND attendance.checkout_approved_at IS NULL
    AND attendance.checkout_requested_at IS NOT NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'checkout_request_not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: self_service_clock_in(bigint, bigint, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_service_clock_in(p_branch_id bigint, p_shift_id bigint, p_business_date date, p_photo_path text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint;
  v_employee_id bigint;
  v_assigned_branch_id bigint;
  v_role text;
  v_position_id bigint;
  v_branch_kind text;
  v_is_company_self_service boolean := false;
  v_is_opening boolean;
  v_is_closing boolean;
  v_attendance_id bigint;
  v_assignment public.shift_assignments%ROWTYPE;
  v_shift public.shifts%ROWTYPE;
  v_now timestamptz := now();
  v_vn_date date := (v_now AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_vn_time time := (v_now AT TIME ZONE 'Asia/Ho_Chi_Minh')::time;
  v_candidate_dates date[];
  v_work_date date;
  v_scheduled_start timestamptz;
  v_scheduled_end timestamptz;
BEGIN
  SELECT profile.tenant_id, employee.id, profile.branch_id,
         private.staff_role_from_position_code(position.code), profile.position_id
  INTO v_tenant_id, v_employee_id, v_assigned_branch_id, v_role, v_position_id
  FROM public.profiles profile
  JOIN public.positions position
    ON position.id = profile.position_id
   AND position.tenant_id = profile.tenant_id
  JOIN public.employees employee
    ON employee.profile_id = profile.id
   AND employee.tenant_id = profile.tenant_id
  WHERE profile.id = v_actor
    AND profile.is_active
    AND position.is_active
    AND employee.is_active;

  SELECT EXISTS (
    SELECT 1
    FROM public.auth_role_bindings binding
    WHERE binding.user_id = v_actor
      AND binding.tenant_id = v_tenant_id
      AND binding.role_code = 'self_service_member'
      AND binding.scope_type = 'tenant'
      AND binding.branch_id IS NULL
      AND binding.valid_from <= v_now
      AND (binding.valid_until IS NULL OR binding.valid_until > v_now)
  )
  INTO v_is_company_self_service;
  v_is_company_self_service :=
    v_role IS NULL
    AND v_assigned_branch_id IS NULL
    AND v_is_company_self_service;

  IF v_actor IS NULL
     OR v_employee_id IS NULL
     OR v_role = 'owner'
     OR (v_role IS NULL AND NOT v_is_company_self_service) THEN
    RAISE EXCEPTION 'self_service_not_allowed' USING ERRCODE = '42501';
  END IF;
  IF p_photo_path IS NULL OR btrim(p_photo_path) = '' THEN
    RAISE EXCEPTION 'photo_required' USING ERRCODE = '23514';
  END IF;

  IF v_is_company_self_service THEN
    IF p_branch_id IS NOT NULL THEN
      RAISE EXCEPTION 'company_scope_must_be_null' USING ERRCODE = '42501';
    END IF;
  ELSIF v_role = 'accountant' THEN
    IF v_assigned_branch_id IS NOT NULL OR p_branch_id IS NOT NULL THEN
      RAISE EXCEPTION 'accountant_scope_must_be_null' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF v_assigned_branch_id IS NULL
       OR p_branch_id IS DISTINCT FROM v_assigned_branch_id THEN
      RAISE EXCEPTION 'assigned_site_mismatch' USING ERRCODE = '42501';
    END IF;
    SELECT branch.branch_kind
    INTO v_branch_kind
    FROM public.branches branch
    WHERE branch.id = v_assigned_branch_id
      AND branch.tenant_id = v_tenant_id
      AND branch.is_active
      AND branch.branch_kind IN ('branch', 'central_supply', 'central_kitchen');
    IF v_branch_kind IS NULL THEN
      RAISE EXCEPTION 'assigned_site_not_active' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_candidate_dates := ARRAY[v_vn_date, (v_vn_date - 1)];

  SELECT sa.*
  INTO v_assignment
  FROM public.shift_assignments sa
  JOIN public.shifts sh
    ON sh.id = sa.shift_id
   AND sh.tenant_id = sa.tenant_id
   AND sh.is_active
  WHERE sa.tenant_id = v_tenant_id
    AND sa.employee_id = v_employee_id
    AND sa.branch_id IS NOT DISTINCT FROM v_assigned_branch_id
    AND sa.work_date = ANY (v_candidate_dates)
    AND (
      (
        sa.work_date = v_vn_date
        AND (
          (sh.end_time > sh.start_time AND v_vn_time >= sh.start_time AND v_vn_time < sh.end_time)
          OR (sh.end_time <= sh.start_time AND (v_vn_time >= sh.start_time OR v_vn_time < sh.end_time))
        )
      )
      OR (
        sa.work_date = (v_vn_date - 1)
        AND sh.end_time <= sh.start_time
        AND v_vn_time < sh.end_time
      )
      OR sa.work_date = v_vn_date
    )
  ORDER BY
    CASE
      WHEN sa.work_date = v_vn_date
           AND (
             (sh.end_time > sh.start_time AND v_vn_time >= sh.start_time AND v_vn_time < sh.end_time)
             OR (sh.end_time <= sh.start_time AND (v_vn_time >= sh.start_time OR v_vn_time < sh.end_time))
           )
        THEN 0
      WHEN sa.work_date = (v_vn_date - 1)
           AND sh.end_time <= sh.start_time
           AND v_vn_time < sh.end_time
        THEN 1
      ELSE 2
    END,
    sa.work_date DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_assignment_required' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_shift
  FROM public.shifts sh
  WHERE sh.id = v_assignment.shift_id
    AND sh.tenant_id = v_tenant_id
    AND sh.is_active
    AND sh.branch_id IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_shift_id IS DISTINCT FROM v_assignment.shift_id THEN
    RAISE EXCEPTION 'shift_assignment_mismatch' USING ERRCODE = '22023';
  END IF;
  IF p_business_date IS DISTINCT FROM v_assignment.work_date THEN
    RAISE EXCEPTION 'shift_assignment_mismatch' USING ERRCODE = '22023';
  END IF;

  v_work_date := v_assignment.work_date;
  v_is_opening := v_shift.is_opening;
  v_is_closing := v_shift.is_closing;

  v_scheduled_start := ((v_work_date + v_shift.start_time) AT TIME ZONE 'Asia/Ho_Chi_Minh');
  IF v_shift.end_time > v_shift.start_time THEN
    v_scheduled_end := ((v_work_date + v_shift.end_time) AT TIME ZONE 'Asia/Ho_Chi_Minh');
  ELSE
    v_scheduled_end := (((v_work_date + 1) + v_shift.end_time) AT TIME ZONE 'Asia/Ho_Chi_Minh');
  END IF;

  INSERT INTO public.attendance_records (
    tenant_id, branch_id, employee_id, shift_id, date, check_in, status,
    method, check_in_photo_path, checklist_template_id,
    shift_assignment_id, scheduled_start_at, scheduled_end_at
  )
  VALUES (
    v_tenant_id, v_assigned_branch_id, v_employee_id, v_assignment.shift_id,
    v_work_date, v_now, 'present', 'pwa', p_photo_path, NULL,
    v_assignment.id, v_scheduled_start, v_scheduled_end
  )
  RETURNING id INTO v_attendance_id;

  INSERT INTO public.attendance_checklist_items (
    tenant_id, attendance_record_id, template_item_id, title, phase,
    done_definition, is_required, scope, task_kind, sort_order
  )
  SELECT v_tenant_id, v_attendance_id, NULL, task.title, task.phase,
         task.done_definition, task.is_required, task.applicability, task.kind,
         row_number() OVER (ORDER BY task.sort_order, task.id)::integer
  FROM public.position_shift_tasks task
  WHERE task.tenant_id = v_tenant_id
    AND task.position_id = v_position_id
    AND (
      task.applicability = 'every_shift'
      OR (task.applicability = 'opening' AND v_is_opening)
      OR (task.applicability = 'closing' AND v_is_closing)
    );

  RETURN v_attendance_id;
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'duplicate_clock_in' USING ERRCODE = '23505';
END;
$$;


--
-- Name: self_service_request_checkout(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_service_request_checkout(p_attendance_id bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_employee_id bigint;
  v_role text := public.auth_role();
  v_record public.attendance_records%ROWTYPE;
  v_branch_kind text;
  v_requested_at timestamptz := now();
  v_target_roles text[];
BEGIN
  IF v_actor IS NULL OR v_tenant_id IS NULL OR v_role = 'owner' THEN
    RAISE EXCEPTION 'self_service_not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT employee.id
  INTO v_employee_id
  FROM public.employees employee
  WHERE employee.profile_id = v_actor
    AND employee.tenant_id = v_tenant_id
    AND employee.is_active;

  SELECT attendance.*
  INTO v_record
  FROM public.attendance_records attendance
  WHERE attendance.id = p_attendance_id
    AND attendance.tenant_id = v_tenant_id
    AND attendance.employee_id = v_employee_id
    AND attendance.check_out IS NULL
  FOR UPDATE;
  IF v_record.id IS NULL THEN
    RAISE EXCEPTION 'open_attendance_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.attendance_checklist_items item
    WHERE item.attendance_record_id = v_record.id
      AND item.tenant_id = v_tenant_id
      AND item.is_required
      AND NOT item.is_done
  ) THEN
    RAISE EXCEPTION 'checklist_incomplete' USING ERRCODE = '23514';
  END IF;

  IF v_record.checkout_requested_at IS NOT NULL THEN
    RETURN v_record.checkout_requested_at;
  END IF;

  SELECT branch.branch_kind INTO v_branch_kind
  FROM public.branches branch
  WHERE branch.id = v_record.branch_id
    AND branch.tenant_id = v_tenant_id;

  v_target_roles := CASE
    WHEN v_role IN ('cashier', 'chef', 'branch_staff')
      AND v_branch_kind = 'branch'
      THEN ARRAY['branch_manager']::text[]
    ELSE ARRAY['owner']::text[]
  END;

  UPDATE public.attendance_records attendance
  SET checkout_requested_at = v_requested_at,
      checkout_requested_by_role = v_role,
      checkout_approval_target_roles = v_target_roles,
      updated_at = now()
  WHERE attendance.id = v_record.id
    AND attendance.check_out IS NULL;

  INSERT INTO public.notifications (
    tenant_id, target_branch_id, target_roles, kind, severity, title, body,
    entity_type, entity_id, action_url, meta, dedup_key
  )
  VALUES (
    v_tenant_id,
    CASE WHEN v_target_roles = ARRAY['branch_manager']::text[] THEN v_record.branch_id ELSE NULL END,
    v_target_roles,
    'hr.checkout_requested', 'info', 'Yêu cầu kết ca mới',
    'Nhân viên đã gửi yêu cầu kết ca.',
    'attendance_record', v_record.id,
    CASE
      WHEN v_target_roles = ARRAY['branch_manager']::text[]
        THEN format('/br/%s/shift/checkout-approvals', v_record.branch_id)
      ELSE '/hr/attendance/checkout-approvals'
    END,
    jsonb_build_object('attendance_id', v_record.id, 'branch_id', v_record.branch_id),
    format('hr.checkout_request:%s', v_record.id)
  )
  ON CONFLICT (tenant_id, dedup_key) WHERE dedup_key IS NOT NULL
  DO UPDATE SET created_at = EXCLUDED.created_at, expires_at = NULL, meta = EXCLUDED.meta;

  RETURN v_requested_at;
END;
$$;


--
-- Name: self_service_toggle_task(bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.self_service_toggle_task(p_item_id bigint, p_done boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR public.auth_role() = 'owner' THEN
    RAISE EXCEPTION 'self_service_not_allowed' USING ERRCODE = '42501';
  END IF;

  UPDATE public.attendance_checklist_items item
  SET is_done = p_done,
      completed_at = CASE WHEN p_done THEN now() ELSE NULL END
  FROM public.attendance_records attendance
  JOIN public.employees employee
    ON employee.id = attendance.employee_id
   AND employee.tenant_id = attendance.tenant_id
  WHERE item.id = p_item_id
    AND item.attendance_record_id = attendance.id
    AND item.tenant_id = attendance.tenant_id
    AND employee.profile_id = v_actor
    AND attendance.check_out IS NULL
    AND attendance.checkout_requested_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'task_not_editable' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: send_purchase_order(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_purchase_order(p_po_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_po public.purchase_orders%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT purchase_order.*
  INTO v_po
  FROM public.purchase_orders AS purchase_order
  WHERE purchase_order.id = p_po_id
    AND purchase_order.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_po.branch_id, 'procurement:po_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_po.status = 'sent' THEN
    RETURN jsonb_build_object('id', p_po_id, 'status', 'sent');
  END IF;
  IF v_po.status <> 'draft'
     OR v_po.purchase_request_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM public.purchase_order_items AS item
       WHERE item.po_id = p_po_id
         AND item.tenant_id = v_tenant
     )
     OR EXISTS (
       SELECT 1
       FROM public.purchase_order_items AS item
       WHERE item.po_id = p_po_id
         AND item.tenant_id = v_tenant
         AND (
           item.quantity <= 0
           OR item.unit_price_est IS NULL
           OR item.unit_price_est < 0
         )
     ) THEN
    RAISE EXCEPTION 'purchase_order_not_sendable'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.purchase_order_items
  SET line_total = round(quantity * unit_price_est, 2)
  WHERE po_id = p_po_id
    AND tenant_id = v_tenant;

  UPDATE public.purchase_orders
  SET status = 'sent',
      ordered_at = now(),
      updated_at = now()
  WHERE id = p_po_id
    AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'procurement.po.sent',
    'purchase_order',
    p_po_id,
    to_jsonb(v_po),
    jsonb_build_object('status', 'sent')
  );

  RETURN jsonb_build_object('id', p_po_id, 'status', 'sent');
END;
$$;


--
-- Name: set_auth_role_binding(uuid, text, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_auth_role_binding(p_target_user_id uuid, p_role_code text, p_branch_id bigint DEFAULT NULL::bigint, p_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_scope_type text;
  v_binding_id bigint;
BEGIN
  IF v_actor IS NULL OR v_tenant_id IS NULL
     OR NOT public.has_permission(NULL, 'auth:binding_manage') THEN
    RAISE EXCEPTION 'binding_manage_forbidden' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(auth.jwt() ->> 'aal', 'aal1') <> 'aal2' THEN
    RAISE EXCEPTION 'aal2_required' USING ERRCODE = '42501';
  END IF;

  SELECT role.allowed_scope
  INTO v_scope_type
  FROM public.auth_access_roles role
  WHERE role.code = p_role_code;
  IF v_scope_type IS NULL THEN
    RAISE EXCEPTION 'role_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles profile
    WHERE profile.id = p_target_user_id
      AND profile.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'target_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF (v_scope_type = 'tenant' AND p_branch_id IS NOT NULL)
     OR (v_scope_type = 'branch' AND p_branch_id IS NULL) THEN
    RAISE EXCEPTION 'binding_scope_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches branch
    WHERE branch.id = p_branch_id
      AND branch.tenant_id = v_tenant_id
      AND branch.is_active
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT p_active
     AND p_target_user_id = v_actor
     AND p_role_code IN ('tenant_owner', 'security_admin') THEN
    RAISE EXCEPTION 'self_security_revoke_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_active THEN
    SELECT binding.id INTO v_binding_id
    FROM public.auth_role_bindings binding
    WHERE binding.tenant_id = v_tenant_id
      AND binding.user_id = p_target_user_id
      AND binding.role_code = p_role_code
      AND binding.scope_type = v_scope_type
      AND binding.branch_id IS NOT DISTINCT FROM p_branch_id
      AND binding.valid_until IS NULL
    FOR UPDATE;

    IF v_binding_id IS NULL THEN
      INSERT INTO public.auth_role_bindings (
        tenant_id, user_id, role_code, scope_type, branch_id, granted_by
      ) VALUES (
        v_tenant_id, p_target_user_id, p_role_code, v_scope_type, p_branch_id, v_actor
      )
      RETURNING id INTO v_binding_id;

      INSERT INTO public.auth_role_binding_audit_log (
        tenant_id, actor_user_id, target_user_id, role_code,
        scope_type, branch_id, action
      ) VALUES (
        v_tenant_id, v_actor, p_target_user_id, p_role_code,
        v_scope_type, p_branch_id, 'grant'
      );
    END IF;
  ELSE
    UPDATE public.auth_role_bindings binding
    SET valid_until = now()
    WHERE binding.tenant_id = v_tenant_id
      AND binding.user_id = p_target_user_id
      AND binding.role_code = p_role_code
      AND binding.scope_type = v_scope_type
      AND binding.branch_id IS NOT DISTINCT FROM p_branch_id
      AND binding.valid_until IS NULL
    RETURNING binding.id INTO v_binding_id;

    IF v_binding_id IS NOT NULL THEN
      INSERT INTO public.auth_role_binding_audit_log (
        tenant_id, actor_user_id, target_user_id, role_code,
        scope_type, branch_id, action
      ) VALUES (
        v_tenant_id, v_actor, p_target_user_id, p_role_code,
        v_scope_type, p_branch_id, 'revoke'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'binding_id', v_binding_id,
    'active', p_active,
    'role_code', p_role_code,
    'scope_type', v_scope_type,
    'branch_id', p_branch_id
  );
END;
$$;


--
-- Name: set_branch_kind(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_branch_kind(p_branch_id bigint, p_kind text DEFAULT 'branch'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_tenant bigint;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id
  INTO v_tenant
  FROM public.profiles p
  WHERE p.id = v_actor_id
    AND COALESCE(p.is_active, true) = true;

  IF NOT FOUND OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_kind NOT IN ('branch', 'central_supply', 'central_kitchen') THEN
    RAISE EXCEPTION 'invalid branch_kind' USING ERRCODE = '22023';
  END IF;

  UPDATE public.branches
  SET branch_kind = p_kind,
      updated_at = now()
  WHERE id = p_branch_id
    AND tenant_id = v_tenant
    AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: FUNCTION set_branch_kind(p_branch_id bigint, p_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_branch_kind(p_branch_id bigint, p_kind text) IS 'Sets the operating site kind for a branch-backed inventory site.';


--
-- Name: set_branch_menu_daily_limit(bigint, bigint, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint, p_limit_quantity integer, p_is_disabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_role      TEXT   := public.auth_role();
  v_branch    BIGINT := public.auth_branch_id();
  v_today     DATE   := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_row       public.branch_menu_item_daily_limits;
  v_stock_capacity INTEGER;
BEGIN
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF v_role NOT IN ('owner', 'branch_manager') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'branch_manager'
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_limit_quantity IS NOT NULL AND p_limit_quantity < 0 THEN
    RAISE EXCEPTION 'limit_quantity must be nonnegative or null' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.menu_items mi
    WHERE mi.id = p_menu_item_id
      AND mi.tenant_id = v_tenant_id
      AND mi.is_active = TRUE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'menu item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM 1 FROM public.branches b
    WHERE b.id = p_branch_id AND b.tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  v_stock_capacity := public.compute_menu_item_stock_capacity(
    v_tenant_id,
    p_branch_id,
    p_menu_item_id
  );

  INSERT INTO public.branch_menu_item_daily_limits
    (
      tenant_id,
      branch_id,
      menu_item_id,
      limit_date,
      limit_quantity,
      is_disabled,
      sold_today,
      stock_capacity
    )
  VALUES
    (
      v_tenant_id,
      p_branch_id,
      p_menu_item_id,
      v_today,
      p_limit_quantity,
      p_is_disabled,
      0,
      v_stock_capacity
    )
  ON CONFLICT (branch_id, menu_item_id, limit_date)
  DO UPDATE SET
    limit_quantity = EXCLUDED.limit_quantity,
    is_disabled    = EXCLUDED.is_disabled,
    stock_capacity = EXCLUDED.stock_capacity,
    updated_at     = now()
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'branch_id', v_row.branch_id,
    'menu_item_id', v_row.menu_item_id,
    'limit_date', v_row.limit_date,
    'limit_quantity', v_row.limit_quantity,
    'is_disabled', v_row.is_disabled,
    'sold_today', v_row.sold_today,
    'stock_capacity', v_row.stock_capacity
  );
END;
$$;


--
-- Name: FUNCTION set_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint, p_limit_quantity integer, p_is_disabled boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint, p_limit_quantity integer, p_is_disabled boolean) IS 'Upserts today''s manual daily limit row. limit_quantity is a pure manual cap: NULL = no manual limit (never defaulted or clamped from stock capacity — D064 limit-ratchet invariant); is_disabled is settable for every active item including capacity-NULL ones.';


--
-- Name: set_inventory_count_assignments(bigint, bigint, bigint, bigint[], bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_inventory_count_assignments(p_branch_id bigint, p_location_id bigint, p_employee_id bigint, p_ingredient_ids bigint[], p_shift_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_ingredient_ids bigint[] :=
    coalesce(p_ingredient_ids, ARRAY[]::bigint[]);
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  PERFORM 1
  FROM public.inventory_locations AS location
  JOIN public.branches AS branch
    ON branch.id = location.branch_id
   AND branch.tenant_id = location.tenant_id
   AND branch.is_active IS TRUE
  WHERE location.id = p_location_id
    AND location.tenant_id = v_tenant
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'location_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    p_branch_id,
    'inventory:count_assign'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_shift_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.shifts AS shift
       WHERE shift.id = p_shift_id
         AND shift.tenant_id = v_tenant
         AND shift.is_active IS TRUE
         AND (
           shift.branch_id IS NULL
           OR shift.branch_id = p_branch_id
         )
     ) THEN
    RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees AS employee
    JOIN public.profiles AS profile
      ON profile.id = employee.profile_id
     AND profile.tenant_id = employee.tenant_id
    WHERE employee.id = p_employee_id
      AND employee.tenant_id = v_tenant
      AND employee.is_active IS TRUE
      AND profile.branch_id = p_branch_id
  ) THEN
    RAISE EXCEPTION 'employee_not_in_branch'
      USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(v_ingredient_ids) AS selected(ingredient_id)
    LEFT JOIN public.ingredients AS ingredient
      ON ingredient.id = selected.ingredient_id
     AND ingredient.tenant_id = v_tenant
    WHERE ingredient.id IS NULL
  ) THEN
    RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.inventory_count_assignments AS assignment
  SET is_active = FALSE,
      updated_at = now()
  WHERE assignment.tenant_id = v_tenant
    AND assignment.branch_id = p_branch_id
    AND assignment.location_id = p_location_id
    AND assignment.ingredient_id = ANY(v_ingredient_ids)
    AND assignment.is_active IS TRUE
    AND (
      assignment.employee_id <> p_employee_id
      OR assignment.shift_id IS DISTINCT FROM p_shift_id
    )
    AND assignment.shift_id IS NOT DISTINCT FROM p_shift_id;

  UPDATE public.inventory_count_assignments AS assignment
  SET is_active = FALSE,
      updated_at = now()
  WHERE assignment.tenant_id = v_tenant
    AND assignment.branch_id = p_branch_id
    AND assignment.location_id = p_location_id
    AND assignment.employee_id = p_employee_id
    AND assignment.shift_id IS NOT DISTINCT FROM p_shift_id
    AND assignment.is_active IS TRUE
    AND NOT (
      assignment.ingredient_id = ANY(v_ingredient_ids)
    );

  INSERT INTO public.inventory_count_assignments (
    tenant_id,
    branch_id,
    location_id,
    employee_id,
    ingredient_id,
    shift_id,
    is_active,
    assigned_by
  )
  SELECT
    v_tenant,
    p_branch_id,
    p_location_id,
    p_employee_id,
    selected.ingredient_id,
    p_shift_id,
    TRUE,
    v_uid
  FROM (
    SELECT DISTINCT unnest(v_ingredient_ids) AS ingredient_id
  ) AS selected
  ON CONFLICT (
    tenant_id,
    branch_id,
    location_id,
    employee_id,
    ingredient_id,
    (coalesce(shift_id, 0::bigint))
  )
  DO UPDATE
  SET is_active = TRUE,
      assigned_by = v_uid,
      updated_at = now();

  PERFORM public.log_audit(
    'set_count_assignments',
    'inventory_count_assignment',
    p_employee_id,
    NULL,
    jsonb_build_object(
      'branch_id',
      p_branch_id,
      'location_id',
      p_location_id,
      'employee_id',
      p_employee_id,
      'shift_id',
      p_shift_id,
      'ingredient_ids',
      v_ingredient_ids
    )
  );

  RETURN jsonb_build_object(
    'success',
    TRUE,
    'employee_id',
    p_employee_id,
    'location_id',
    p_location_id,
    'shift_id',
    p_shift_id,
    'count',
    coalesce(array_length(v_ingredient_ids, 1), 0)
  );
END;
$$;


--
-- Name: FUNCTION set_inventory_count_assignments(p_branch_id bigint, p_location_id bigint, p_employee_id bigint, p_ingredient_ids bigint[], p_shift_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_inventory_count_assignments(p_branch_id bigint, p_location_id bigint, p_employee_id bigint, p_ingredient_ids bigint[], p_shift_id bigint) IS 'Assigns counts only for the authenticated tenant site active warehouse.';


--
-- Name: set_order_service_charge(bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_order_service_charge(p_order_id bigint, p_amount numeric, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid          UUID;
  v_prof_tenant  BIGINT;
  v_prof_branch  BIGINT;
  v_prof_role    TEXT;
  v_order        RECORD;
  v_note_trim    TEXT;
  v_amount       NUMERIC(15,2);
  v_total_amount NUMERIC(15,2);
  v_has_pending  BOOLEAN;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'cashier')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_amount IS NULL OR p_amount < 0 THEN
    RAISE EXCEPTION 'service_charge_invalid_amount' USING ERRCODE = '22023';
  END IF;

  IF p_amount > 50000000 THEN
    RAISE EXCEPTION 'service_charge_amount_too_large' USING ERRCODE = '22023';
  END IF;

  v_note_trim := COALESCE(trim(p_note), '');
  IF length(v_note_trim) < 3 THEN
    RAISE EXCEPTION 'service_charge_note_required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status,
         o.subtotal, o.tax_amount, o.service_charge, o.discount_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.payments p
    WHERE p.order_id = p_order_id
      AND p.tenant_id = v_order.tenant_id
      AND p.branch_id = v_order.branch_id
      AND p.status = 'pending'
  )
  INTO v_has_pending;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'pending' OR v_has_pending THEN
    RAISE EXCEPTION 'service_charge_payment_pending' USING ERRCODE = '22023';
  END IF;

  v_amount := ROUND(p_amount::NUMERIC, 2);
  v_total_amount := COALESCE(v_order.subtotal, 0)
                  + COALESCE(v_order.tax_amount, 0)
                  + v_amount
                  - COALESCE(v_order.discount_amount, 0);

  UPDATE public.orders
     SET service_charge = v_amount,
         total_amount   = v_total_amount,
         updated_at     = now()
   WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_order.tenant_id,
    p_order_id,
    v_order.status,
    v_order.status,
    v_uid,
    CASE
      WHEN v_amount = 0 THEN 'service_charge_cleared'
      ELSE 'service_charge_set: ' || v_amount::TEXT || 'đ'
    END || ' :: ' || v_note_trim
  );

  RETURN jsonb_build_object(
    'order_id',       p_order_id,
    'service_charge', v_amount,
    'total_amount',   v_total_amount
  );
END;
$$;


--
-- Name: FUNCTION set_order_service_charge(p_order_id bigint, p_amount numeric, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_order_service_charge(p_order_id bigint, p_amount numeric, p_note text) IS 'Set or clear orders.service_charge before payment. Requires note >=3 chars, blocks paid/terminal/pending-payment orders, recomputes total_amount, and records an order_status_history audit note.';


--
-- Name: set_pos_order_item_priority(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pos_order_item_priority(p_order_item_id bigint, p_is_priority boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_item public.order_items%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_note TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item
  FROM public.order_items
  WHERE id = p_order_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = v_item.order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1
    FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  IF v_item.status NOT IN ('pending', 'preparing') THEN
    RAISE EXCEPTION 'item not prioritizable' USING ERRCODE = '22023';
  END IF;

  v_note := NULLIF(trim(COALESCE(p_note, '')), '');

  UPDATE public.order_items
  SET is_priority = COALESCE(p_is_priority, FALSE),
      priority_note = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_note ELSE NULL END,
      priority_marked_at = CASE WHEN COALESCE(p_is_priority, FALSE) THEN now() ELSE NULL END,
      priority_marked_by = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_uid ELSE NULL END,
      updated_at = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET updated_at = now()
  WHERE order_item_id = p_order_item_id
    AND tenant_id = v_item.tenant_id
    AND status IN ('pending', 'preparing');

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id,
    v_order.id,
    v_order.status,
    v_order.status,
    v_uid,
    CASE WHEN COALESCE(p_is_priority, FALSE)
      THEN 'priority_item:on '
      ELSE 'priority_item:off '
    END || p_order_item_id::TEXT || COALESCE(' - ' || v_note, '')
  );

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'order_item_id', p_order_item_id,
    'is_priority', COALESCE(p_is_priority, FALSE)
  );
END;
$$;


--
-- Name: set_pos_order_priority(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pos_order_priority(p_order_id bigint, p_is_priority boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order public.orders%ROWTYPE;
  v_active_count INT;
  v_note TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1
    FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*)::INT INTO v_active_count
  FROM public.order_items
  WHERE order_id = p_order_id
    AND tenant_id = v_order.tenant_id
    AND status IN ('pending', 'preparing');

  IF v_active_count = 0 THEN
    RAISE EXCEPTION 'no active kitchen work' USING ERRCODE = '22023';
  END IF;

  v_note := NULLIF(trim(COALESCE(p_note, '')), '');

  UPDATE public.orders
  SET is_priority = COALESCE(p_is_priority, FALSE),
      priority_note = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_note ELSE NULL END,
      priority_marked_at = CASE WHEN COALESCE(p_is_priority, FALSE) THEN now() ELSE NULL END,
      priority_marked_by = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_uid ELSE NULL END,
      updated_at = now()
  WHERE id = p_order_id;

  UPDATE public.kds_tickets kt
  SET updated_at = now()
  WHERE kt.order_id = p_order_id
    AND kt.tenant_id = v_order.tenant_id
    AND kt.status IN ('pending', 'preparing');

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id,
    p_order_id,
    v_order.status,
    v_order.status,
    v_uid,
    CASE WHEN COALESCE(p_is_priority, FALSE)
      THEN 'priority_order:on'
      ELSE 'priority_order:off'
    END || COALESCE(' - ' || v_note, '')
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'is_priority', COALESCE(p_is_priority, FALSE)
  );
END;
$$;


--
-- Name: set_print_template_versions_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_print_template_versions_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := COALESCE(NEW.created_by, auth.uid());
  END IF;
  NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: set_production_recipe_status(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_production_recipe_status(p_recipe_spec_id bigint, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator()
     OR NOT public.has_permission_any('inventory:production_confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('active', 'inactive') THEN
    RAISE EXCEPTION 'recipe_status_invalid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.production_recipe_specs AS spec
  SET status = p_status, updated_at = now()
  WHERE spec.id = p_recipe_spec_id
    AND spec.tenant_id = v_tenant
    AND (
      p_status = 'inactive'
      OR (
        spec.output_unit_id IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public.production_recipes AS recipe
          WHERE recipe.recipe_spec_id = spec.id
        )
      )
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'recipe_not_ready' USING ERRCODE = '23514';
  END IF;
  RETURN jsonb_build_object('recipe_spec_id', p_recipe_spec_id, 'status', p_status);
END;
$$;


--
-- Name: set_supplier_item_preferred(bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_supplier_item_preferred(p_item_id bigint, p_is_preferred boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_item public.supplier_items%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'missing_tenant' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:price_list_write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_item_id IS NULL OR p_item_id <= 0 THEN
    RAISE EXCEPTION 'invalid_supplier_item_id' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_item
  FROM public.supplier_items
  WHERE id = p_item_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_item_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT v_item.is_active THEN
    RAISE EXCEPTION 'supplier_item_inactive' USING ERRCODE = '22023';
  END IF;

  IF p_is_preferred THEN
    UPDATE public.supplier_items
    SET is_preferred = false,
        updated_at = pg_catalog.now()
    WHERE tenant_id = v_tenant
      AND ingredient_id = v_item.ingredient_id
      AND is_active
      AND is_preferred
      AND id IS DISTINCT FROM p_item_id;

    UPDATE public.supplier_items
    SET is_preferred = true,
        updated_at = pg_catalog.now()
    WHERE id = p_item_id
      AND tenant_id = v_tenant;
  ELSE
    UPDATE public.supplier_items
    SET is_preferred = false,
        updated_at = pg_catalog.now()
    WHERE id = p_item_id
      AND tenant_id = v_tenant;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'item_id', p_item_id,
    'ingredient_id', v_item.ingredient_id,
    'supplier_id', v_item.supplier_id,
    'is_preferred', p_is_preferred
  );
END;
$$;


--
-- Name: FUNCTION set_supplier_item_preferred(p_item_id bigint, p_is_preferred boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_supplier_item_preferred(p_item_id bigint, p_is_preferred boolean) IS 'Sets or clears preferred supplier mapping for an ingredient; clears other active preferreds when enabling.';


--
-- Name: snapshot_payroll_calculation(integer, integer, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_payroll_calculation(p_period_year integer, p_period_month integer, p_standard_days numeric, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_period_id bigint;
  v_period_status text;
  v_entry_count integer;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL
     OR NOT public.has_permission(NULL, 'hr:payroll_snapshot') THEN
    RAISE EXCEPTION 'missing_payroll_snapshot_permission' USING ERRCODE = '42501';
  END IF;
  IF p_period_year < 2020
     OR p_period_month NOT BETWEEN 1 AND 12
     OR p_standard_days IS NULL
     OR p_standard_days <= 0
     OR p_standard_days > 31
     OR p_entries IS NULL
     OR jsonb_typeof(p_entries) <> 'array'
     OR jsonb_array_length(p_entries) = 0 THEN
    RAISE EXCEPTION 'invalid_payroll_snapshot' USING ERRCODE = '23514';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(format('%s:%s:%s', v_tenant_id, p_period_year, p_period_month), 0)
  );

  SELECT period.id, period.status
  INTO v_period_id, v_period_status
  FROM public.payroll_periods period
  WHERE period.tenant_id = v_tenant_id
    AND period.period_year = p_period_year
    AND period.period_month = p_period_month
  FOR UPDATE;

  IF FOUND AND v_period_status IN ('approved', 'paid') THEN
    SELECT count(*)::integer
    INTO v_entry_count
    FROM public.payroll_entries entry
    WHERE entry.tenant_id = v_tenant_id
      AND entry.payroll_period_id = v_period_id;

    RETURN jsonb_build_object(
      'period_id', v_period_id,
      'employee_count', v_entry_count,
      'status', 'already_finalized'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_populate_recordset(NULL::public.payroll_entries, p_entries) entry
    GROUP BY entry.employee_id
    HAVING count(*) > 1
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_populate_recordset(NULL::public.payroll_entries, p_entries) entry
    LEFT JOIN public.employees employee
      ON employee.id = entry.employee_id
     AND employee.tenant_id = v_tenant_id
    WHERE employee.id IS NULL
      OR entry.working_days IS NULL OR entry.working_days < 0
      OR entry.paid_leave_days IS NULL OR entry.paid_leave_days < 0
      OR entry.unpaid_leave_days IS NULL OR entry.unpaid_leave_days < 0
      OR entry.payable_days IS NULL OR entry.payable_days < 0
      OR entry.payable_days > p_standard_days
      OR entry.standard_days IS DISTINCT FROM p_standard_days
      OR entry.base_salary IS NULL OR entry.base_salary < 0
      OR entry.gross_total IS NULL OR entry.gross_total < 0
      OR entry.net_salary IS NULL OR entry.net_salary < 0
  ) THEN
    RAISE EXCEPTION 'invalid_payroll_entry' USING ERRCODE = '23514';
  END IF;

  IF v_period_id IS NULL THEN
    INSERT INTO public.payroll_periods (
      tenant_id, period_year, period_month, standard_days,
      status, approved_by, approved_at
    ) VALUES (
      v_tenant_id, p_period_year, p_period_month, p_standard_days,
      'approved', v_user_id, now()
    )
    RETURNING id INTO v_period_id;
  ELSE
    UPDATE public.payroll_periods
    SET standard_days = p_standard_days,
        status = 'approved',
        approved_by = v_user_id,
        approved_at = now(),
        updated_at = now()
    WHERE id = v_period_id
      AND tenant_id = v_tenant_id;
  END IF;

  DELETE FROM public.payroll_entries entry
  WHERE entry.tenant_id = v_tenant_id
    AND entry.payroll_period_id = v_period_id
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_populate_recordset(NULL::public.payroll_entries, p_entries) source
      WHERE source.employee_id = entry.employee_id
    );

  INSERT INTO public.payroll_entries (
    tenant_id, payroll_period_id, employee_id,
    working_days, paid_leave_days, unpaid_leave_days, payable_days,
    standard_days, overtime_hours, base_salary, allowances,
    tax_exempt_allowances, overtime_pay, bonus, gross_total,
    bhxh_employee, bhyt_employee, bhtn_employee, total_insurance_employee,
    bhxh_employer, bhyt_employer, bhtn_employer, total_insurance_employer,
    personal_deduction, dependent_count, dependent_deduction, charity_deduction,
    taxable_income, pit_tax, advance_deduction, other_deductions, net_salary,
    insurance_base
  )
  SELECT
    v_tenant_id, v_period_id, entry.employee_id,
    entry.working_days, entry.paid_leave_days, entry.unpaid_leave_days, entry.payable_days,
    entry.standard_days, entry.overtime_hours, entry.base_salary, entry.allowances,
    entry.tax_exempt_allowances, entry.overtime_pay, entry.bonus, entry.gross_total,
    entry.bhxh_employee, entry.bhyt_employee, entry.bhtn_employee, entry.total_insurance_employee,
    entry.bhxh_employer, entry.bhyt_employer, entry.bhtn_employer, entry.total_insurance_employer,
    entry.personal_deduction, entry.dependent_count, entry.dependent_deduction, entry.charity_deduction,
    entry.taxable_income, entry.pit_tax, entry.advance_deduction, entry.other_deductions, entry.net_salary,
    entry.insurance_base
  FROM jsonb_populate_recordset(NULL::public.payroll_entries, p_entries) entry
  ON CONFLICT (payroll_period_id, employee_id, tenant_id) DO UPDATE SET
    working_days = EXCLUDED.working_days,
    paid_leave_days = EXCLUDED.paid_leave_days,
    unpaid_leave_days = EXCLUDED.unpaid_leave_days,
    payable_days = EXCLUDED.payable_days,
    standard_days = EXCLUDED.standard_days,
    overtime_hours = EXCLUDED.overtime_hours,
    base_salary = EXCLUDED.base_salary,
    allowances = EXCLUDED.allowances,
    tax_exempt_allowances = EXCLUDED.tax_exempt_allowances,
    overtime_pay = EXCLUDED.overtime_pay,
    bonus = EXCLUDED.bonus,
    gross_total = EXCLUDED.gross_total,
    bhxh_employee = EXCLUDED.bhxh_employee,
    bhyt_employee = EXCLUDED.bhyt_employee,
    bhtn_employee = EXCLUDED.bhtn_employee,
    total_insurance_employee = EXCLUDED.total_insurance_employee,
    bhxh_employer = EXCLUDED.bhxh_employer,
    bhyt_employer = EXCLUDED.bhyt_employer,
    bhtn_employer = EXCLUDED.bhtn_employer,
    total_insurance_employer = EXCLUDED.total_insurance_employer,
    personal_deduction = EXCLUDED.personal_deduction,
    dependent_count = EXCLUDED.dependent_count,
    dependent_deduction = EXCLUDED.dependent_deduction,
    charity_deduction = EXCLUDED.charity_deduction,
    taxable_income = EXCLUDED.taxable_income,
    pit_tax = EXCLUDED.pit_tax,
    advance_deduction = EXCLUDED.advance_deduction,
    other_deductions = EXCLUDED.other_deductions,
    net_salary = EXCLUDED.net_salary,
    insurance_base = EXCLUDED.insurance_base,
    updated_at = now();

  GET DIAGNOSTICS v_entry_count = ROW_COUNT;

  PERFORM public.log_audit(
    'approve',
    'payroll_period',
    v_period_id,
    NULL,
    jsonb_build_object(
      'period_year', p_period_year,
      'period_month', p_period_month,
      'standard_days', p_standard_days,
      'employee_count', v_entry_count,
      'status', 'approved'
    )
  );

  RETURN jsonb_build_object(
    'period_id', v_period_id,
    'employee_count', v_entry_count,
    'status', 'approved'
  );
END;
$$;


--
-- Name: split_order(bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_order(p_source_order_id bigint, p_item_partials jsonb, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid                  UUID;
  v_prof_tenant          BIGINT;
  v_prof_branch          BIGINT;
  v_prof_role            TEXT;
  v_source               RECORD;
  v_active_total_rows    INT;
  v_full_move_count      INT := 0;
  v_total_units_moved    INT := 0;
  v_remaining_rows       INT;
  v_new_order_id         BIGINT;
  v_new_order_number     TEXT;
  v_seq                  INT;
  v_date_part            TEXT;
  v_flag_enabled         TEXT;
  v_existing_id          BIGINT;
  v_existing_number      TEXT;
  v_source_subtotal      NUMERIC(15,2);
  v_source_discount      NUMERIC(15,2);
  v_source_total         NUMERIC(15,2);
  v_new_subtotal         NUMERIC(15,2);
  v_new_total            NUMERIC(15,2);
  v_partial              JSONB;
  v_partial_item_id      BIGINT;
  v_partial_qty          INT;
  v_src_row              public.order_items%ROWTYPE;
  v_new_item_id          BIGINT;
  v_branch_code          TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
    INTO v_prof_tenant, v_prof_branch, v_prof_role
    FROM public.profiles p
    LEFT JOIN public.positions po ON po.id = p.position_id
   WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_item_partials IS NULL
     OR jsonb_typeof(p_item_partials) <> 'array'
     OR jsonb_array_length(p_item_partials) = 0
  THEN
    RAISE EXCEPTION 'split_no_items' USING ERRCODE = '22023';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT o.id, o.order_number INTO v_existing_id, v_existing_number
      FROM public.orders o
     WHERE o.split_from_order_id = p_source_order_id
       AND o.idempotency_key = p_idempotency_key;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'source_order_id',  p_source_order_id,
        'new_order_id',     v_existing_id,
        'new_order_number', v_existing_number,
        'idempotent',       true
      );
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(p_source_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
         o.payment_status, o.pos_session_id, o.service_charge,
         o.discount_type, o.discount_value
    INTO v_source
    FROM public.orders o
   WHERE o.id = p_source_order_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_source.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = v_source.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_source.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  ELSE
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = v_source.branch_id AND b.tenant_id = v_prof_tenant;
  END IF;

  SELECT value INTO v_flag_enabled
    FROM public.system_settings
   WHERE tenant_id = v_source.tenant_id AND key = 'pos_split_merge_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'split_merge_disabled' USING ERRCODE = 'P0001';
  END IF;

  IF v_source.status NOT IN ('new', 'confirmed', 'preparing', 'ready', 'served') THEN
    RAISE EXCEPTION 'split_source_not_eligible' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_source.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'split_source_paid' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.payments
   WHERE order_id = p_source_order_id AND status NOT IN ('failed', 'completed');
  IF FOUND THEN
    RAISE EXCEPTION 'split_payment_pending' USING ERRCODE = '22023';
  END IF;

  FOR v_partial IN SELECT value FROM jsonb_array_elements(p_item_partials)
  LOOP
    v_partial_item_id := NULLIF(v_partial ->> 'item_id', '')::BIGINT;
    v_partial_qty := NULLIF(v_partial ->> 'quantity', '')::INT;

    IF v_partial_item_id IS NULL OR v_partial_qty IS NULL OR v_partial_qty < 1 THEN
      RAISE EXCEPTION 'split_items_invalid' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_src_row
      FROM public.order_items
     WHERE id = v_partial_item_id
       AND order_id = p_source_order_id
       AND status <> 'cancelled'
       FOR UPDATE;

    IF NOT FOUND OR v_partial_qty > v_src_row.quantity THEN
      RAISE EXCEPTION 'split_items_invalid' USING ERRCODE = '22023';
    END IF;

    IF v_partial_qty = v_src_row.quantity THEN
      v_full_move_count := v_full_move_count + 1;
    END IF;

    v_total_units_moved := v_total_units_moved + v_partial_qty;
  END LOOP;

  SELECT COUNT(*) INTO v_active_total_rows
    FROM public.order_items
   WHERE order_id = p_source_order_id AND status <> 'cancelled';

  v_remaining_rows := v_active_total_rows - v_full_move_count;
  IF v_remaining_rows < 1 THEN
    RAISE EXCEPTION 'split_would_empty_source' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.order_daily_counters (
    tenant_id, branch_id, counter_date, last_seq
  )
  VALUES (
    v_source.tenant_id,
    v_source.branch_id,
    (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    1
  )
  ON CONFLICT (tenant_id, branch_id, counter_date)
  DO UPDATE SET
    last_seq   = public.order_daily_counters.last_seq + 1,
    updated_at = now()
  RETURNING last_seq INTO v_seq;

  v_date_part := to_char(
    CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYMMDD'
  );

  IF v_source.order_type = 'dine_in' THEN
    v_new_order_number := 'TC-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  ELSE
    v_new_order_number := 'MV-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  END IF;

  IF v_branch_code IS NOT NULL THEN
    v_new_order_number := v_new_order_number || '-' || v_branch_code;
  END IF;

  INSERT INTO public.orders (
    tenant_id, branch_id, table_id, order_number, order_type,
    status, subtotal, total_amount, note, created_by,
    pos_session_id, idempotency_key, split_from_order_id
  )
  VALUES (
    v_source.tenant_id, v_source.branch_id, v_source.table_id,
    v_new_order_number, v_source.order_type,
    v_source.status,
    0, 0, NULL, v_uid,
    v_source.pos_session_id, p_idempotency_key, p_source_order_id
  )
  RETURNING id INTO v_new_order_id;

  FOR v_partial IN SELECT value FROM jsonb_array_elements(p_item_partials)
  LOOP
    v_partial_item_id := (v_partial ->> 'item_id')::BIGINT;
    v_partial_qty := (v_partial ->> 'quantity')::INT;

    SELECT * INTO v_src_row
      FROM public.order_items
     WHERE id = v_partial_item_id;

    IF v_partial_qty = v_src_row.quantity THEN
      UPDATE public.order_items
         SET order_id   = v_new_order_id,
             updated_at = now()
       WHERE id = v_partial_item_id
         AND order_id = p_source_order_id;

      UPDATE public.kds_tickets
         SET order_id   = v_new_order_id,
             updated_at = now()
       WHERE order_item_id = v_partial_item_id
         AND order_id = p_source_order_id;
    ELSE
      PERFORM set_config('comtammatu.skip_quota_enforcement', 'true', true);
      INSERT INTO public.order_items (
        tenant_id, order_id, menu_item_id, variant_id,
        item_name, variant_name, quantity, unit_price,
        modifiers, sides, subtotal, note, status,
        sent_to_kitchen_at
      )
      VALUES (
        v_src_row.tenant_id, v_new_order_id,
        v_src_row.menu_item_id, v_src_row.variant_id,
        v_src_row.item_name, v_src_row.variant_name,
        v_partial_qty, v_src_row.unit_price,
        v_src_row.modifiers, v_src_row.sides,
        v_src_row.unit_price * v_partial_qty,
        v_src_row.note, v_src_row.status,
        v_src_row.sent_to_kitchen_at
      )
      RETURNING id INTO v_new_item_id;
      PERFORM set_config('comtammatu.skip_quota_enforcement', 'false', true);

      UPDATE public.order_items
         SET quantity   = v_src_row.quantity - v_partial_qty,
             subtotal   = v_src_row.unit_price * (v_src_row.quantity - v_partial_qty),
             updated_at = now()
       WHERE id = v_partial_item_id;

      INSERT INTO public.kds_tickets (
        tenant_id, branch_id, station_id, order_id, order_item_id,
        status, bumped_at, bumped_by, created_at
      )
      SELECT
        kt.tenant_id, kt.branch_id, kt.station_id,
        v_new_order_id, v_new_item_id,
        kt.status, kt.bumped_at, kt.bumped_by, kt.created_at
      FROM public.kds_tickets kt
      WHERE kt.order_item_id = v_partial_item_id
        AND kt.order_id = p_source_order_id;
    END IF;
  END LOOP;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_source_subtotal
    FROM public.order_items
   WHERE order_id = p_source_order_id AND status <> 'cancelled';

  v_source_discount := public.compute_discount_amount(
    v_source.discount_type, v_source.discount_value, v_source_subtotal
  );

  v_source_total := v_source_subtotal
                  + COALESCE(v_source.service_charge, 0)
                  - v_source_discount;

  UPDATE public.orders
     SET subtotal        = v_source_subtotal,
         discount_amount = v_source_discount,
         total_amount    = v_source_total,
         updated_at      = now()
   WHERE id = p_source_order_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_new_subtotal
    FROM public.order_items
   WHERE order_id = v_new_order_id AND status <> 'cancelled';

  v_new_total := v_new_subtotal;

  UPDATE public.orders
     SET subtotal     = v_new_subtotal,
         total_amount = v_new_total,
         updated_at   = now()
   WHERE id = v_new_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES
    (v_source.tenant_id, p_source_order_id, v_source.status, v_source.status, v_uid,
     'split_to: ' || v_new_order_number
       || ' (moved ' || v_total_units_moved::TEXT || ' units across '
       || jsonb_array_length(p_item_partials)::TEXT || ' lines)'),
    (v_source.tenant_id, v_new_order_id, NULL, v_source.status, v_uid,
     'split_from: order#' || p_source_order_id::TEXT);

  RETURN jsonb_build_object(
    'source_order_id',  p_source_order_id,
    'new_order_id',     v_new_order_id,
    'new_order_number', v_new_order_number,
    'moved_count',      v_total_units_moved,
    'source_subtotal',  v_source_subtotal,
    'source_total',     v_source_total,
    'new_subtotal',     v_new_subtotal,
    'new_total',        v_new_total
  );
END;
$$;


--
-- Name: FUNCTION split_order(p_source_order_id bigint, p_item_partials jsonb, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.split_order(p_source_order_id bigint, p_item_partials jsonb, p_idempotency_key uuid) IS 'Tách hoá đơn — partials [{item_id, quantity}]. quantity == row.quantity → in-place UPDATE order_id; quantity < row.quantity → INSERT clone trên đơn mới + giảm qty source + mirror kds_tickets per station. Source phải giữ ≥1 active ROW sau move (block split_would_empty_source). Đơn mới: discount=0, service_charge=0, status inherit từ source. Idempotent qua p_idempotency_key. Clone INSERT bypass enforce_branch_menu_daily_limit qua GUC comtammatu.skip_quota_enforcement (net qty unchanged). Counter mint dùng schema (tenant,branch,date) — chia chung pool với create_order.';


--
-- Name: start_production_run(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_production_run(p_run_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
  PERFORM auth.role();
  RAISE EXCEPTION 'production_maintenance_legacy_rpc' USING ERRCODE = '55000';
END; $$;


--
-- Name: start_production_run(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_production_run(p_run_id bigint, p_branch_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator()
     OR NOT public.has_permission(p_branch_id, 'inventory:production_confirm') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;
  UPDATE public.production_runs AS run
  SET status = 'in_progress', started_at = now(), updated_at = now()
  WHERE run.tenant_id = v_tenant
    AND run.id = p_run_id
    AND run.branch_id = p_branch_id
    AND run.status = 'draft';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_transition_invalid' USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('production_run_id', p_run_id, 'status', 'in_progress');
END;
$$;


--
-- Name: start_stocktake(bigint, bigint, text, boolean, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_stocktake(p_branch_id bigint, p_location_id bigint DEFAULT NULL::bigint, p_mode text DEFAULT 'daily'::text, p_blind_mode boolean DEFAULT NULL::boolean, p_auditor_id uuid DEFAULT NULL::uuid, p_threshold_pct numeric DEFAULT NULL::numeric, p_threshold_vnd numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_blind boolean;
  v_session_id bigint;
  v_is_unaudited boolean := FALSE;
  v_rows integer := 0;
  v_location_id bigint;
  v_session_number text;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF p_mode NOT IN (
    'daily',
    'weekly',
    'monthly',
    'quarterly',
    'spot'
  ) THEN
    RAISE EXCEPTION 'invalid mode' USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.branches AS branch
  WHERE branch.id = p_branch_id
    AND branch.tenant_id = v_tenant
    AND branch.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(
    p_branch_id,
    'inventory:stocktake_create'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT location.id
  INTO v_location_id
  FROM public.inventory_locations AS location
  WHERE location.tenant_id = v_tenant
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE
    AND (
      p_location_id IS NULL
      OR location.id = p_location_id
    )
  ORDER BY
    location.is_default_consumption DESC,
    location.sort_order NULLS LAST,
    location.id
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'location_not_found_or_inactive'
      USING ERRCODE = 'P0002';
  END IF;

  IF p_auditor_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.profiles AS profile
       WHERE profile.id = p_auditor_id
         AND profile.tenant_id = v_tenant
         AND coalesce(profile.is_active, TRUE) IS TRUE
     ) THEN
    RAISE EXCEPTION 'auditor_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_blind := coalesce(
    p_blind_mode,
    CASE p_mode
      WHEN 'daily' THEN FALSE
      WHEN 'weekly' THEN FALSE
      WHEN 'monthly' THEN TRUE
      WHEN 'quarterly' THEN TRUE
      WHEN 'spot' THEN TRUE
    END
  );
  IF p_mode IN ('monthly', 'quarterly')
     AND p_auditor_id IS NULL THEN
    v_is_unaudited := TRUE;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stock_levels AS stock
    WHERE stock.tenant_id = v_tenant
      AND stock.branch_id = p_branch_id
      AND stock.location_id = v_location_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.ingredient_units AS ingredient_unit
        JOIN public.units AS unit
          ON unit.id = ingredient_unit.unit_id
         AND unit.tenant_id = ingredient_unit.tenant_id
         AND unit.is_active IS TRUE
        WHERE ingredient_unit.tenant_id = v_tenant
          AND ingredient_unit.ingredient_id = stock.ingredient_id
          AND ingredient_unit.is_base IS TRUE
          AND ingredient_unit.is_active IS TRUE
      )
  ) THEN
    RAISE EXCEPTION 'stocktake_entry_unit_missing'
      USING ERRCODE = '23503';
  END IF;

  v_session_number := public.next_inventory_doc_number(
    v_tenant,
    'stocktake'
  );

  INSERT INTO public.stocktake_sessions (
    tenant_id,
    branch_id,
    location_id,
    status,
    started_at,
    created_by,
    mode,
    blind_mode,
    auditor_id,
    is_unaudited,
    variance_threshold_pct,
    variance_threshold_vnd,
    abc_snapshot_at,
    current_round,
    session_number
  )
  VALUES (
    v_tenant,
    p_branch_id,
    v_location_id,
    'in_progress',
    now(),
    v_uid,
    p_mode,
    v_blind,
    p_auditor_id,
    v_is_unaudited,
    coalesce(p_threshold_pct, 5.00),
    coalesce(p_threshold_vnd, 200000),
    now(),
    1,
    v_session_number
  )
  RETURNING id INTO v_session_id;

  INSERT INTO public.stocktake_lines (
    tenant_id,
    session_id,
    ingredient_id,
    system_quantity,
    round_no,
    abc_class,
    entry_unit_id
  )
  SELECT
    v_tenant,
    v_session_id,
    stock.ingredient_id,
    coalesce(stock.current_quantity, 0),
    1,
    public.get_ingredient_abc_class(
      p_branch_id,
      stock.ingredient_id
    ),
    base_unit.unit_id
  FROM public.stock_levels AS stock
  JOIN public.ingredients AS ingredient
    ON ingredient.id = stock.ingredient_id
   AND ingredient.tenant_id = stock.tenant_id
   AND ingredient.is_active IS TRUE
  JOIN LATERAL (
    SELECT ingredient_unit.unit_id
    FROM public.ingredient_units AS ingredient_unit
    JOIN public.units AS unit
      ON unit.id = ingredient_unit.unit_id
     AND unit.tenant_id = ingredient_unit.tenant_id
     AND unit.is_active IS TRUE
    WHERE ingredient_unit.tenant_id = v_tenant
      AND ingredient_unit.ingredient_id = stock.ingredient_id
      AND ingredient_unit.is_base IS TRUE
      AND ingredient_unit.is_active IS TRUE
    ORDER BY ingredient_unit.sort_order, ingredient_unit.id
    LIMIT 1
  ) AS base_unit ON TRUE
  WHERE stock.tenant_id = v_tenant
    AND stock.branch_id = p_branch_id
    AND stock.location_id = v_location_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  RETURN jsonb_build_object(
    'session_id',
    v_session_id,
    'session_number',
    v_session_number,
    'mode',
    p_mode,
    'blind_mode',
    v_blind,
    'is_unaudited',
    v_is_unaudited,
    'seeded_lines',
    v_rows,
    'abc_snapshot_at',
    now()
  );
END;
$$;


--
-- Name: FUNCTION start_stocktake(p_branch_id bigint, p_location_id bigint, p_mode text, p_blind_mode boolean, p_auditor_id uuid, p_threshold_pct numeric, p_threshold_vnd numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.start_stocktake(p_branch_id bigint, p_location_id bigint, p_mode text, p_blind_mode boolean, p_auditor_id uuid, p_threshold_pct numeric, p_threshold_vnd numeric) IS 'Starts a stocktake only at the authenticated tenant site active warehouse.';


--
-- Name: stock_issue_items_bubble_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_issue_items_bubble_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.approval_required THEN
    UPDATE public.stock_issues SET approval_status = 'pending'
     WHERE id = NEW.issue_id AND approval_status = 'not_required';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: stock_issue_items_compute_waste_tier(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_issue_items_compute_waste_tier() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_parent record;
  v_item_value numeric(15,2);
  v_stock record;
  v_quantity_ratio numeric(5,4);
  v_rolling_sum numeric(15,2);
  v_shift_sum numeric(15,2);
  v_branch_cap record;
  v_branch_today numeric(15,2);
  v_photo boolean := FALSE;
  v_approve boolean := FALSE;
  v_tier smallint := 0;
  v_quantity_base numeric(15,3);
  v_risky_reasons constant text[] := ARRAY[
    'dropped',
    'quality_fail',
    'contaminated',
    'found_missing',
    'theft_suspected'
  ];
  v_always_tier2 constant text[] := ARRAY[
    'found_missing',
    'theft_suspected'
  ];
  v_tier1_threshold constant numeric := 150000;
  v_tier2_threshold constant numeric := 500000;
  v_shift_cap constant numeric := 1500000;
BEGIN
  SELECT
    issue.tenant_id,
    issue.branch_id,
    issue.source_location_id,
    issue.created_by,
    issue.issue_type,
    issue.shift_key,
    issue.issued_at
  INTO v_parent
  FROM public.stock_issues AS issue
  WHERE issue.id = NEW.issue_id;

  IF NOT FOUND OR v_parent.issue_type <> 'writeoff' THEN
    RETURN NEW;
  END IF;

  v_quantity_base := public.inv_to_base(
    NEW.ingredient_id,
    NEW.entry_unit_id,
    NEW.quantity
  );

  IF NEW.unit_cost IS NOT NULL AND NEW.unit_cost > 0 THEN
    v_item_value := v_quantity_base * NEW.unit_cost;
  ELSE
    SELECT stock.current_quantity, stock.avg_unit_cost
    INTO v_stock
    FROM public.stock_levels AS stock
    WHERE stock.branch_id = v_parent.branch_id
      AND stock.ingredient_id = NEW.ingredient_id
      AND (
        v_parent.source_location_id IS NULL
        OR stock.location_id = v_parent.source_location_id
      )
    ORDER BY stock.location_id
    LIMIT 1;
    v_item_value := coalesce(
      v_quantity_base * v_stock.avg_unit_cost,
      0
    );
  END IF;

  SELECT stock.current_quantity
  INTO v_stock
  FROM public.stock_levels AS stock
  WHERE stock.branch_id = v_parent.branch_id
    AND stock.ingredient_id = NEW.ingredient_id
    AND (
      v_parent.source_location_id IS NULL
      OR stock.location_id = v_parent.source_location_id
    )
  ORDER BY stock.location_id
  LIMIT 1;

  IF v_stock.current_quantity IS NOT NULL
     AND v_stock.current_quantity > 0 THEN
    v_quantity_ratio := least(
      v_quantity_base / v_stock.current_quantity,
      9.9999
    )::numeric(5,4);
  ELSE
    v_quantity_ratio := NULL;
  END IF;

  SELECT coalesce(sum(
    public.inv_to_base(
      item.ingredient_id,
      item.entry_unit_id,
      item.quantity
    ) * item.unit_cost
  ), 0)
  INTO v_rolling_sum
  FROM public.stock_issue_items AS item
  JOIN public.stock_issues AS issue
    ON issue.id = item.issue_id
  WHERE issue.issue_type = 'writeoff'
    AND issue.created_by = v_parent.created_by
    AND issue.branch_id = v_parent.branch_id
    AND item.ingredient_id = NEW.ingredient_id
    AND issue.created_at > now() - interval '15 minutes'
    AND item.id <> coalesce(NEW.id, -1);

  IF v_parent.shift_key IS NOT NULL THEN
    SELECT coalesce(sum(
      public.inv_to_base(
        item.ingredient_id,
        item.entry_unit_id,
        item.quantity
      ) * item.unit_cost
    ), 0)
    INTO v_shift_sum
    FROM public.stock_issue_items AS item
    JOIN public.stock_issues AS issue
      ON issue.id = item.issue_id
    WHERE issue.issue_type = 'writeoff'
      AND issue.created_by = v_parent.created_by
      AND issue.branch_id = v_parent.branch_id
      AND issue.shift_key = v_parent.shift_key
      AND item.id <> coalesce(NEW.id, -1);
  ELSE
    v_shift_sum := 0;
  END IF;

  SELECT cap.cap_vnd, cap.avg_revenue_7d
  INTO v_branch_cap
  FROM public.branch_daily_waste_cap AS cap
  WHERE cap.branch_id = v_parent.branch_id;

  SELECT coalesce(sum(
    public.inv_to_base(
      item.ingredient_id,
      item.entry_unit_id,
      item.quantity
    ) * item.unit_cost
  ), 0)
  INTO v_branch_today
  FROM public.stock_issue_items AS item
  JOIN public.stock_issues AS issue
    ON issue.id = item.issue_id
  WHERE issue.issue_type = 'writeoff'
    AND issue.branch_id = v_parent.branch_id
    AND issue.issued_at >= date_trunc(
      'day',
      now() AT TIME ZONE coalesce(
        (
          SELECT branch.timezone
          FROM public.branches AS branch
          WHERE branch.id = v_parent.branch_id
        ),
        'Asia/Ho_Chi_Minh'
      )
    )
    AND item.id <> coalesce(NEW.id, -1);

  v_photo := v_item_value >= v_tier1_threshold
    OR (
      v_quantity_ratio IS NOT NULL
      AND v_quantity_ratio >= 0.5
    )
    OR (
      NEW.reason_code IS NOT NULL
      AND NEW.reason_code = ANY(v_risky_reasons)
    )
    OR v_rolling_sum + v_item_value >= v_tier1_threshold;

  v_approve := v_item_value >= v_tier2_threshold
    OR v_shift_sum + v_item_value >= v_shift_cap
    OR (
      NEW.reason_code IS NOT NULL
      AND NEW.reason_code = ANY(v_always_tier2)
    )
    OR (
      v_branch_cap.cap_vnd IS NOT NULL
      AND v_branch_today + v_item_value > v_branch_cap.cap_vnd
    );

  IF v_approve THEN
    v_tier := 2;
  ELSIF v_photo THEN
    v_tier := 1;
  END IF;

  NEW.waste_tier := v_tier;
  NEW.photo_required := v_photo;
  NEW.approval_required := v_approve;
  NEW.qty_ratio := v_quantity_ratio;
  NEW.rolling_15min_sum := v_rolling_sum;

  IF v_photo
     AND coalesce(array_length(NEW.photo_urls, 1), 0) = 0
     AND NOT public.has_permission(
       v_parent.branch_id,
       'inventory:waste_bypass_photo'
     ) THEN
    RAISE EXCEPTION
      'waste photo required for tier >= 1 (reason=%, value=%, qty_ratio=%)',
      NEW.reason_code,
      v_item_value,
      v_quantity_ratio
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: stock_issue_items_reason_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_issue_items_reason_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.reason_code IS NOT NULL AND NEW.reason_code IS DISTINCT FROM OLD.reason_code THEN
    RAISE EXCEPTION 'reason_code is immutable once set (got % -> %)', OLD.reason_code, NEW.reason_code USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: stock_issue_items_set_writeoff_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_issue_items_set_writeoff_cost() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_parent RECORD;
  v_unit_cost numeric(15,2);
BEGIN
  SELECT
    issue.tenant_id,
    issue.branch_id,
    issue.source_location_id,
    issue.issue_type
  INTO v_parent
  FROM public.stock_issues issue
  WHERE issue.id = NEW.issue_id;

  IF NOT FOUND OR v_parent.issue_type <> 'writeoff' THEN
    RETURN NEW;
  END IF;

  SELECT stock.avg_unit_cost
  INTO v_unit_cost
  FROM public.stock_levels stock
  WHERE stock.tenant_id = v_parent.tenant_id
    AND stock.branch_id = v_parent.branch_id
    AND stock.ingredient_id = NEW.ingredient_id
    AND (
      v_parent.source_location_id IS NULL
      OR stock.location_id = v_parent.source_location_id
    )
  ORDER BY stock.location_id
  LIMIT 1;

  IF v_unit_cost IS NULL THEN
    SELECT ingredient.unit_cost
    INTO v_unit_cost
    FROM public.ingredients ingredient
    WHERE ingredient.tenant_id = v_parent.tenant_id
      AND ingredient.id = NEW.ingredient_id;
  END IF;

  NEW.unit_cost := COALESCE(v_unit_cost, 0);
  RETURN NEW;
END;
$$;


--
-- Name: stock_ledger_reconciliation(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_ledger_reconciliation(p_branch_id bigint, p_location_id bigint DEFAULT NULL::bigint) RETURNS TABLE(ingredient_id bigint, ingredient_name text, location_id bigint, ledger_sum numeric, stock_levels_qty numeric, drift numeric, drift_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'inventory:read') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH ledger AS (
    SELECT sm.ingredient_id,
           sm.location_id,
           COALESCE(SUM(sm.quantity_change), 0)::numeric AS ledger_sum
    FROM public.stock_movements sm
    WHERE sm.tenant_id = v_tenant
      AND sm.branch_id = p_branch_id
      AND (p_location_id IS NULL OR sm.location_id = p_location_id)
    GROUP BY sm.ingredient_id, sm.location_id
  ),
  levels AS (
    SELECT sl.ingredient_id,
           sl.location_id,
           sl.current_quantity::numeric AS stock_levels_qty
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = p_branch_id
      AND (p_location_id IS NULL OR sl.location_id = p_location_id)
  ),
  pairs AS (
    SELECT
      COALESCE(l.ingredient_id, lv.ingredient_id) AS ingredient_id,
      COALESCE(l.location_id, lv.location_id) AS location_id,
      COALESCE(l.ledger_sum, 0)::numeric AS ledger_sum,
      COALESCE(lv.stock_levels_qty, 0)::numeric AS stock_levels_qty
    FROM ledger l
    FULL OUTER JOIN levels lv USING (ingredient_id, location_id)
  )
  SELECT
    p.ingredient_id,
    i.name AS ingredient_name,
    p.location_id,
    p.ledger_sum,
    p.stock_levels_qty,
    (p.stock_levels_qty - p.ledger_sum)::numeric AS drift,
    CASE
      WHEN abs(p.ledger_sum) > 0.001
        THEN round(((p.stock_levels_qty - p.ledger_sum) / abs(p.ledger_sum)) * 100, 3)
      ELSE NULL
    END AS drift_pct
  FROM pairs p
  JOIN public.ingredients i
    ON i.id = p.ingredient_id
   AND i.tenant_id = v_tenant
  WHERE abs(p.stock_levels_qty - p.ledger_sum) > 0.001
  ORDER BY i.name, p.location_id;
END;
$$;


--
-- Name: FUNCTION stock_ledger_reconciliation(p_branch_id bigint, p_location_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.stock_ledger_reconciliation(p_branch_id bigint, p_location_id bigint) IS 'Returns ingredient/location rows where the stock_movements ledger sum diverges from stock_levels.current_quantity beyond 0.001. Call with (branch_id) or (branch_id, location_id).';


--
-- Name: stock_request_actor_can_read(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_request_actor_can_read(p_request_id bigint, p_item_fulfill_site_kind text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_branch_id bigint;
  v_actor_fulfill_kind text;
BEGIN
  IF auth.uid() IS NULL OR public.auth_tenant_id() IS NULL THEN
    RETURN false;
  END IF;

  SELECT req.branch_id
  INTO v_branch_id
  FROM public.stock_requests AS req
  WHERE req.id = p_request_id
    AND req.tenant_id = public.auth_tenant_id();

  IF v_branch_id IS NULL THEN
    RETURN false;
  END IF;

  IF public.auth_is_owner(auth.uid())
     OR public.has_permission(v_branch_id, 'inventory:read')
     OR public.has_permission(v_branch_id, 'inventory:request_create')
  THEN
    RETURN true;
  END IF;

  IF NOT public.has_permission_any('inventory:request_fulfill') THEN
    RETURN false;
  END IF;

  v_actor_fulfill_kind := CASE public.auth_role()
    WHEN 'central_supply_ops' THEN 'central_supply'
    WHEN 'central_kitchen_lead' THEN 'central_kitchen'
    ELSE NULL
  END;

  IF v_actor_fulfill_kind IS NULL THEN
    RETURN false;
  END IF;

  IF p_item_fulfill_site_kind IS NOT NULL THEN
    RETURN p_item_fulfill_site_kind = v_actor_fulfill_kind;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.stock_request_items AS item
    WHERE item.request_id = p_request_id
      AND item.tenant_id = public.auth_tenant_id()
      AND item.fulfill_site_kind = v_actor_fulfill_kind
  );
END;
$$;


--
-- Name: stock_transfer_confirm_receive(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_confirm_receive(p_transfer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
