--
-- Name: stock_transfer_receive(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_receive(p_transfer_id bigint, p_items jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_line public.stock_transfer_items%ROWTYPE;
  v_payload jsonb;
  v_received numeric;
  v_note text;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  FOR v_line IN
    SELECT item.*
    FROM public.stock_transfer_items AS item
    WHERE item.transfer_id = p_transfer_id
      AND item.tenant_id = v_tenant
  LOOP
    v_payload := p_items -> v_line.ingredient_id::text;
    v_received := CASE
      WHEN v_payload IS NULL THEN v_line.quantity
      WHEN jsonb_typeof(v_payload) = 'object'
        THEN (v_payload ->> 'qty')::numeric
      ELSE (v_payload #>> '{}')::numeric
    END;
    v_note := CASE
      WHEN jsonb_typeof(v_payload) = 'object'
        THEN NULLIF(btrim(v_payload ->> 'note'), '')
      ELSE NULL
    END;

    IF v_received < v_line.quantity
       AND length(COALESCE(v_note, '')) < 5 THEN
      RAISE EXCEPTION 'short_receive_reason_required:%',
        v_line.ingredient_id
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  RETURN public.stock_transfer_receive_legacy(p_transfer_id, p_items);
END;
$$;


--
-- Name: stock_transfer_receive_legacy(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_receive_legacy(p_transfer_id bigint, p_items jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_key text;
  v_value jsonb;
  v_ingredient_id bigint;
  v_received_quantity numeric;
  v_sent_quantity numeric;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '28000';
  END IF;

  PERFORM private.assert_stock_transfer_warehouse_endpoints(
    p_transfer_id,
    v_tenant
  );

  IF p_items IS NOT NULL THEN
    IF jsonb_typeof(p_items) <> 'object' THEN
      RAISE EXCEPTION 'transfer_receive_items_invalid'
        USING ERRCODE = '22023';
    END IF;

    FOR v_key, v_value IN
      SELECT item.key, item.value
      FROM jsonb_each(p_items) AS item(key, value)
    LOOP
      v_ingredient_id := v_key::bigint;
      v_received_quantity := CASE
        WHEN jsonb_typeof(v_value) = 'object'
          THEN nullif(v_value ->> 'qty', '')::numeric
        ELSE nullif(v_value #>> '{}', '')::numeric
      END;

      SELECT transfer_item.quantity
      INTO v_sent_quantity
      FROM public.stock_transfer_items AS transfer_item
      JOIN public.stock_transfers AS transfer
        ON transfer.id = transfer_item.transfer_id
       AND transfer.tenant_id = transfer_item.tenant_id
      WHERE transfer_item.transfer_id = p_transfer_id
        AND transfer_item.tenant_id = v_tenant
        AND transfer_item.ingredient_id = v_ingredient_id
      FOR UPDATE OF transfer_item;

      IF NOT FOUND
         OR v_received_quantity IS NULL
         OR v_received_quantity < 0
         OR v_received_quantity > v_sent_quantity
         OR v_received_quantity = 'NaN'::numeric
         OR v_received_quantity = 'Infinity'::numeric
         OR v_received_quantity = '-Infinity'::numeric THEN
        RAISE EXCEPTION 'invalid_receive_qty:%', v_ingredient_id
          USING ERRCODE = '22023';
      END IF;
    END LOOP;
  END IF;

  RETURN private.execute_stock_transfer_receive(
    p_transfer_id,
    p_items
  );
END;
$$;


--
-- Name: submit_count_round(bigint, smallint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_count_round(p_session_id bigint, p_round_no smallint, p_counts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_session public.stocktake_sessions%ROWTYPE;
  v_count jsonb;
  v_applied integer := 0;
  v_conflict_count integer := 0;
  v_existing record;
  v_offline_at timestamptz;
  v_ingredient bigint;
  v_counted numeric;
  v_op_id uuid;
  v_entry_unit bigint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT session.*
  INTO v_session
  FROM public.stocktake_sessions AS session
  JOIN public.inventory_locations AS location
    ON location.id = session.location_id
   AND location.tenant_id = session.tenant_id
   AND location.branch_id = session.branch_id
   AND location.location_kind = 'warehouse'
   AND location.is_active IS TRUE
  WHERE session.id = p_session_id
    AND session.tenant_id = v_tenant
  FOR UPDATE OF session;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_session.status <> 'in_progress' THEN
    RAISE EXCEPTION 'session not in_progress (status=%)',
      v_session.status
      USING ERRCODE = '22023';
  END IF;
  IF NOT public.has_permission(
    v_session.branch_id,
    'inventory:stocktake_create'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_round_no <> v_session.current_round THEN
    RAISE EXCEPTION 'round % does not match current_round %',
      p_round_no,
      v_session.current_round
      USING ERRCODE = '22023';
  END IF;

  FOR v_count IN
    SELECT element.value
    FROM jsonb_array_elements(p_counts) AS element(value)
  LOOP
    v_ingredient := (v_count ->> 'ingredient_id')::bigint;
    v_counted := (v_count ->> 'counted_quantity')::numeric;
    v_op_id := nullif(v_count ->> 'client_op_id', '')::uuid;
    v_offline_at := nullif(
      v_count ->> 'offline_created_at',
      ''
    )::timestamptz;
    v_entry_unit := nullif(v_count ->> 'entry_unit_id', '')::bigint;

    IF v_ingredient IS NULL
       OR v_counted IS NULL
       OR v_counted < 0
       OR v_counted = 'NaN'::numeric
       OR v_counted = 'Infinity'::numeric
       OR v_counted = '-Infinity'::numeric THEN
      RAISE EXCEPTION 'counted_quantity_invalid'
        USING ERRCODE = '22023';
    END IF;

    IF v_session.offline_enabled AND v_offline_at IS NOT NULL
       AND (
         v_offline_at > now() + interval '5 minutes'
         OR v_offline_at < v_session.started_at
       ) THEN
      INSERT INTO public.stocktake_conflicts (
        tenant_id,
        session_id,
        ingredient_id,
        round_no,
        conflict_type,
        client_payload,
        submitted_by
      )
      VALUES (
        v_tenant,
        p_session_id,
        v_ingredient,
        p_round_no,
        'clock_tamper',
        jsonb_build_object(
          'client_op_id',
          v_op_id,
          'offline_created_at',
          v_offline_at,
          'counted_quantity',
          v_counted
        ),
        v_uid
      );
      v_conflict_count := v_conflict_count + 1;
      CONTINUE;
    END IF;

    SELECT
      line.id,
      line.counted_quantity,
      line.is_final
    INTO v_existing
    FROM public.stocktake_lines AS line
    WHERE line.tenant_id = v_tenant
      AND line.session_id = p_session_id
      AND line.ingredient_id = v_ingredient
      AND line.round_no = p_round_no;

    IF FOUND
       AND v_existing.is_final
       AND v_existing.counted_quantity IS DISTINCT FROM v_counted THEN
      INSERT INTO public.stocktake_conflicts (
        tenant_id,
        session_id,
        ingredient_id,
        round_no,
        conflict_type,
        client_payload,
        server_payload,
        submitted_by
      )
      VALUES (
        v_tenant,
        p_session_id,
        v_ingredient,
        p_round_no,
        'is_final_overwrite',
        jsonb_build_object(
          'client_op_id',
          v_op_id,
          'counted_quantity',
          v_counted,
          'offline_created_at',
          v_offline_at
        ),
        jsonb_build_object(
          'existing_counted_quantity',
          v_existing.counted_quantity,
          'is_final',
          TRUE
        ),
        v_uid
      );
      v_conflict_count := v_conflict_count + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.stocktake_lines (
      tenant_id,
      session_id,
      ingredient_id,
      system_quantity,
      counted_quantity,
      entry_unit_id,
      counted_by,
      counted_at,
      round_no,
      abc_class,
      client_op_id,
      offline_created_at
    )
    SELECT
      v_tenant,
      p_session_id,
      v_ingredient,
      round_one.system_quantity,
      v_counted,
      coalesce(v_entry_unit, round_one.entry_unit_id),
      v_uid,
      now(),
      p_round_no,
      round_one.abc_class,
      v_op_id,
      v_offline_at
    FROM public.stocktake_lines AS round_one
    WHERE round_one.tenant_id = v_tenant
      AND round_one.session_id = p_session_id
      AND round_one.ingredient_id = v_ingredient
      AND round_one.round_no = 1
    ON CONFLICT (session_id, ingredient_id, round_no) DO UPDATE
    SET counted_quantity = EXCLUDED.counted_quantity,
        entry_unit_id = EXCLUDED.entry_unit_id,
        counted_by = EXCLUDED.counted_by,
        counted_at = EXCLUDED.counted_at,
        client_op_id = coalesce(
          EXCLUDED.client_op_id,
          public.stocktake_lines.client_op_id
        ),
        offline_created_at = coalesce(
          EXCLUDED.offline_created_at,
          public.stocktake_lines.offline_created_at
        );

    v_applied := v_applied + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'applied_count',
    v_applied,
    'conflict_count',
    v_conflict_count,
    'round_no',
    p_round_no
  );
END;
$$;


--
-- Name: submit_feedback(text, uuid, smallint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_feedback(p_token text, p_client_submission_id uuid, p_rating smallint, p_comment text, p_ip_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_qr public.feedback_qr_codes%ROWTYPE;
  v_branch public.branches%ROWTYPE;
  v_comment TEXT;
  v_token_hash TEXT;
  v_token_ip_hash TEXT;
  v_existing_id BIGINT;
  v_feedback_id BIGINT;
  v_window_seconds INTEGER := 1800;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  IF p_token IS NULL OR p_token !~ '^[A-Za-z0-9_-]{14}$' THEN
    RAISE EXCEPTION 'feedback_token_invalid' USING ERRCODE = '22023';
  END IF;

  IF p_client_submission_id IS NULL THEN
    RAISE EXCEPTION 'feedback_client_submission_required' USING ERRCODE = '22023';
  END IF;

  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'feedback_rating_invalid' USING ERRCODE = '22023';
  END IF;

  IF p_ip_hash IS NOT NULL AND p_ip_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'feedback_ip_hash_invalid' USING ERRCODE = '22023';
  END IF;

  v_comment := NULLIF(btrim(COALESCE(p_comment, '')), '');
  IF v_comment IS NOT NULL AND char_length(v_comment) > 2000 THEN
    RAISE EXCEPTION 'feedback_comment_too_long' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_qr
  FROM public.feedback_qr_codes q
  WHERE q.token = p_token
  FOR UPDATE;

  IF NOT FOUND OR NOT v_qr.is_active THEN
    RAISE EXCEPTION 'feedback_token_invalid' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_branch
  FROM public.branches b
  WHERE b.id = v_qr.branch_id
    AND b.tenant_id = v_qr.tenant_id
  FOR SHARE;

  IF NOT FOUND
     OR NOT COALESCE(v_branch.is_active, false)
     OR v_branch.branch_kind IS DISTINCT FROM 'branch' THEN
    RAISE EXCEPTION 'feedback_branch_inactive' USING ERRCODE = 'P0002';
  END IF;

  SELECT f.id
  INTO v_existing_id
  FROM public.feedbacks f
  WHERE f.qr_code_id = v_qr.id
    AND f.client_submission_id = p_client_submission_id;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'feedbackId', v_existing_id,
      'duplicate', true
    );
  END IF;

  v_token_hash := public.self_order_scope_hash(
    v_qr.tenant_id::text || ':' || v_qr.id::text || ':' || p_token
  );

  PERFORM public.feedback_take_rate_bucket('token', v_token_hash, 100, v_window_seconds);

  IF p_ip_hash IS NOT NULL THEN
    v_token_ip_hash := public.self_order_scope_hash(v_token_hash || ':' || p_ip_hash);
    PERFORM public.feedback_take_rate_bucket('token_ip', v_token_ip_hash, 5, v_window_seconds);
  END IF;

  INSERT INTO public.feedbacks (
    tenant_id,
    branch_id,
    qr_code_id,
    client_submission_id,
    rating,
    comment
  )
  VALUES (
    v_qr.tenant_id,
    v_qr.branch_id,
    v_qr.id,
    p_client_submission_id,
    p_rating,
    v_comment
  )
  ON CONFLICT (qr_code_id, client_submission_id)
  DO NOTHING
  RETURNING id INTO v_feedback_id;

  IF v_feedback_id IS NULL THEN
    SELECT f.id
    INTO v_feedback_id
    FROM public.feedbacks f
    WHERE f.qr_code_id = v_qr.id
      AND f.client_submission_id = p_client_submission_id;

    RETURN jsonb_build_object(
      'ok', true,
      'feedbackId', v_feedback_id,
      'duplicate', true
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'feedbackId', v_feedback_id,
    'duplicate', false
  );
END;
$_$;


--
-- Name: submit_inventory_count_slip(bigint, bigint, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_inventory_count_slip(p_branch_id bigint, p_location_id bigint, p_lines jsonb, p_shift_id bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_employee_id bigint;
  v_employee_name text;
  v_today date :=
    (current_timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_slip_id bigint;
  v_status text;
  v_line jsonb;
  v_ingredient_id bigint;
  v_counted numeric(15,3);
  v_assigned_count integer;
  v_line_count integer;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF jsonb_typeof(p_lines) <> 'array'
     OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'empty_count' USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.inventory_locations AS location
  JOIN public.branches AS branch
    ON branch.id = location.branch_id
   AND branch.tenant_id = location.tenant_id
   AND branch.is_active IS TRUE
  WHERE location.id = p_location_id
    AND location.tenant_id = v_tenant
    AND location.branch_id = p_branch_id
    AND location.location_kind = 'warehouse'
    AND location.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'location_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_shift_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.shifts AS shift
       WHERE shift.id = p_shift_id
         AND shift.tenant_id = v_tenant
         AND shift.is_active IS TRUE
         AND (
           shift.branch_id IS NULL
           OR shift.branch_id = p_branch_id
         )
     ) THEN
    RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT employee.id, profile.full_name
  INTO v_employee_id, v_employee_name
  FROM public.employees AS employee
  JOIN public.profiles AS profile
    ON profile.id = employee.profile_id
   AND profile.tenant_id = employee.tenant_id
  WHERE employee.profile_id = v_uid
    AND employee.tenant_id = v_tenant
    AND employee.is_active IS TRUE
    AND profile.branch_id = p_branch_id
  LIMIT 1;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION 'no_active_employee_in_branch'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(v_employee_id);

  FOR v_line IN
    SELECT element.value
    FROM jsonb_array_elements(p_lines) AS element(value)
  LOOP
    v_ingredient_id := (v_line ->> 'ingredient_id')::bigint;
    v_counted := (v_line ->> 'counted_quantity')::numeric;

    IF v_ingredient_id IS NULL OR v_counted IS NULL THEN
      RAISE EXCEPTION 'invalid_line' USING ERRCODE = '22023';
    END IF;
    IF v_counted < 0
       OR v_counted = 'NaN'::numeric
       OR v_counted = 'Infinity'::numeric
       OR v_counted = '-Infinity'::numeric THEN
      RAISE EXCEPTION 'counted_quantity_invalid'
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.inventory_count_assignments AS assignment
      WHERE assignment.tenant_id = v_tenant
        AND assignment.branch_id = p_branch_id
        AND assignment.location_id = p_location_id
        AND assignment.employee_id = v_employee_id
        AND assignment.ingredient_id = v_ingredient_id
        AND assignment.is_active IS TRUE
        AND (
          (
            p_shift_id IS NULL
            AND assignment.shift_id IS NULL
          )
          OR (
            p_shift_id IS NOT NULL
            AND (
              assignment.shift_id = p_shift_id
              OR (
                assignment.shift_id IS NULL
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.inventory_count_assignments
                    AS specific
                  WHERE specific.tenant_id = v_tenant
                    AND specific.branch_id = p_branch_id
                    AND specific.location_id = p_location_id
                    AND specific.ingredient_id = v_ingredient_id
                    AND specific.shift_id = p_shift_id
                    AND specific.is_active IS TRUE
                )
              )
            )
          )
        )
    ) THEN
      RAISE EXCEPTION 'not_assigned' USING ERRCODE = '42501';
    END IF;
  END LOOP;

  SELECT count(DISTINCT assignment.ingredient_id)
  INTO v_assigned_count
  FROM public.inventory_count_assignments AS assignment
  WHERE assignment.tenant_id = v_tenant
    AND assignment.branch_id = p_branch_id
    AND assignment.location_id = p_location_id
    AND assignment.employee_id = v_employee_id
    AND assignment.is_active IS TRUE
    AND (
      (
        p_shift_id IS NULL
        AND assignment.shift_id IS NULL
      )
      OR (
        p_shift_id IS NOT NULL
        AND (
          assignment.shift_id = p_shift_id
          OR (
            assignment.shift_id IS NULL
            AND NOT EXISTS (
              SELECT 1
              FROM public.inventory_count_assignments AS specific
              WHERE specific.tenant_id = v_tenant
                AND specific.branch_id = p_branch_id
                AND specific.location_id = p_location_id
                AND specific.ingredient_id =
                  assignment.ingredient_id
                AND specific.shift_id = p_shift_id
                AND specific.is_active IS TRUE
            )
          )
        )
      )
    );

  SELECT count(DISTINCT (line ->> 'ingredient_id')::bigint)
  INTO v_line_count
  FROM jsonb_array_elements(p_lines) AS submitted(line);

  IF v_line_count <> v_assigned_count THEN
    RAISE EXCEPTION 'incomplete_count' USING ERRCODE = '22023';
  END IF;

  SELECT slip.id, slip.status
  INTO v_slip_id, v_status
  FROM public.inventory_count_slips AS slip
  WHERE slip.tenant_id = v_tenant
    AND slip.branch_id = p_branch_id
    AND slip.location_id = p_location_id
    AND slip.employee_id = v_employee_id
    AND slip.count_date = v_today
    AND slip.shift_id IS NOT DISTINCT FROM p_shift_id
  FOR UPDATE;

  IF v_slip_id IS NOT NULL AND v_status = 'approved' THEN
    RAISE EXCEPTION 'slip_already_approved'
      USING ERRCODE = '22023';
  END IF;

  IF v_slip_id IS NULL THEN
    INSERT INTO public.inventory_count_slips (
      tenant_id,
      branch_id,
      location_id,
      employee_id,
      count_date,
      shift_id,
      status,
      submitted_by,
      submitted_at,
      slip_number
    )
    VALUES (
      v_tenant,
      p_branch_id,
      p_location_id,
      v_employee_id,
      v_today,
      p_shift_id,
      'submitted',
      v_uid,
      now(),
      public.next_inventory_doc_number(v_tenant, 'count_slip')
    )
    RETURNING id INTO v_slip_id;
  ELSE
    UPDATE public.inventory_count_slips
    SET status = 'submitted',
        submitted_by = v_uid,
        submitted_at = now(),
        reviewed_by = NULL,
        reviewed_at = NULL,
        review_note = NULL,
        updated_at = now()
    WHERE id = v_slip_id
      AND tenant_id = v_tenant;

    DELETE FROM public.inventory_count_slip_lines
    WHERE tenant_id = v_tenant
      AND slip_id = v_slip_id;
  END IF;

  INSERT INTO public.inventory_count_slip_lines (
    tenant_id,
    slip_id,
    ingredient_id,
    system_quantity,
    counted_quantity,
    entry_unit_id,
    note
  )
  SELECT
    v_tenant,
    v_slip_id,
    (submitted.line ->> 'ingredient_id')::bigint,
    coalesce((
      SELECT stock.current_quantity
      FROM public.stock_levels AS stock
      WHERE stock.tenant_id = v_tenant
        AND stock.branch_id = p_branch_id
        AND stock.location_id = p_location_id
        AND stock.ingredient_id =
          (submitted.line ->> 'ingredient_id')::bigint
    ), 0),
    (submitted.line ->> 'counted_quantity')::numeric,
    nullif(
      submitted.line ->> 'entry_unit_id',
      ''
    )::bigint,
    nullif(trim(submitted.line ->> 'note'), '')
  FROM jsonb_array_elements(p_lines) AS submitted(line);

  INSERT INTO public.notifications (
    tenant_id,
    target_branch_id,
    target_roles,
    kind,
    severity,
    title,
    body,
    entity_type,
    entity_id,
    action_url,
    meta,
    dedup_key
  )
  VALUES (
    v_tenant,
    p_branch_id,
    ARRAY['branch_manager', 'owner', 'owner']::text[],
    'inventory.count_slip_submitted',
    'info',
    'Phiếu đếm tồn mới',
    format(
      '%s đã gửi phiếu đếm tồn (%s mục) chờ duyệt.',
      coalesce(v_employee_name, 'Nhân viên'),
      v_line_count
    ),
    'inventory_count_slip',
    v_slip_id,
    format('/br/%s/stock/count-slips', p_branch_id),
    jsonb_build_object(
      'slip_id',
      v_slip_id,
      'employee_id',
      v_employee_id,
      'branch_id',
      p_branch_id,
      'location_id',
      p_location_id,
      'shift_id',
      p_shift_id,
      'line_count',
      v_line_count
    ),
    format('inventory.count_slip:%s:submitted', v_slip_id)
  )
  ON CONFLICT (
    tenant_id,
    dedup_key
  ) WHERE dedup_key IS NOT NULL
  DO UPDATE
  SET created_at = EXCLUDED.created_at,
      expires_at = NULL,
      meta = EXCLUDED.meta;

  PERFORM public.log_audit(
    'submit',
    'inventory_count_slip',
    v_slip_id,
    NULL,
    jsonb_build_object(
      'branch_id',
      p_branch_id,
      'location_id',
      p_location_id,
      'shift_id',
      p_shift_id,
      'line_count',
      v_line_count
    )
  );

  RETURN v_slip_id;
END;
$$;


--
-- Name: FUNCTION submit_inventory_count_slip(p_branch_id bigint, p_location_id bigint, p_lines jsonb, p_shift_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_inventory_count_slip(p_branch_id bigint, p_location_id bigint, p_lines jsonb, p_shift_id bigint) IS 'Submits assigned counts only for the authenticated tenant site active warehouse.';


--
-- Name: submit_invoice_buyer_request_as_system(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_invoice_buyer_request_as_system(p_token_hash text, p_invoice_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.tax_invoice_buyer_requests%ROWTYPE;
  v_job public.tax_invoice_issue_jobs%ROWTYPE;
  v_invoice public.tax_invoices%ROWTYPE;
  v_buyer_payload jsonb;
  v_payload jsonb;
  v_existing_job_id bigint;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_request
  FROM public.tax_invoice_buyer_requests request
  WHERE request.token_hash = p_token_hash
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_buyer_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_request.status = 'submitted' THEN
    SELECT job.id
    INTO v_existing_job_id
    FROM public.tax_invoice_issue_jobs job
    WHERE job.tenant_id = v_request.tenant_id
      AND job.order_id = v_request.order_id;
    RETURN jsonb_build_object(
      'status', 'submitted',
      'jobId', v_existing_job_id
    );
  END IF;
  IF v_request.status = 'expired' THEN
    RETURN jsonb_build_object('status', 'expired');
  END IF;
  IF v_request.expires_at <= now() THEN
    UPDATE public.tax_invoice_buyer_requests
    SET status = 'expired',
        closed_at = now(),
        close_reason = 'deadline_elapsed',
        updated_at = now()
    WHERE id = v_request.id;
    RETURN jsonb_build_object('status', 'expired');
  END IF;

  SELECT * INTO v_job
  FROM public.tax_invoice_issue_jobs job
  WHERE job.tenant_id = v_request.tenant_id
    AND job.order_id = v_request.order_id
  FOR UPDATE;
  IF NOT FOUND
    OR v_job.status <> 'queued'
    OR v_job.tax_invoice_id IS NULL THEN
    RAISE EXCEPTION 'invoice_buyer_request_closed' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices invoice
  WHERE invoice.id = v_job.tax_invoice_id
    AND invoice.tenant_id = v_request.tenant_id
    AND invoice.order_id = v_request.order_id
  FOR UPDATE;
  IF NOT FOUND
    OR v_invoice.status <> 'draft'
    OR v_invoice.invoice_number IS NOT NULL THEN
    RAISE EXCEPTION 'invoice_buyer_request_closed' USING ERRCODE = '55000';
  END IF;

  v_buyer_payload := public.self_order_normalize_invoice_payload(p_invoice_payload);
  IF v_buyer_payload->>'buyerNotGetInvoice' = 'true'
    OR COALESCE(v_buyer_payload->>'buyerTaxCode', '') = ''
    OR COALESCE(v_buyer_payload->>'buyerName', '') = ''
    OR COALESCE(v_buyer_payload->>'buyerAddress', '') = ''
    OR COALESCE(v_buyer_payload->>'buyerEmail', '') = ''
    OR jsonb_typeof(v_job.invoice_payload -> 'draftSnapshot') IS DISTINCT FROM 'object'
    THEN
    RAISE EXCEPTION 'invoice_buyer_request_invalid_payload' USING ERRCODE = '22023';
  END IF;
  v_payload := v_buyer_payload || jsonb_build_object(
    'draftSnapshot',
    v_job.invoice_payload -> 'draftSnapshot'
  );

  UPDATE public.tax_invoices
  SET buyer_name = v_buyer_payload ->> 'buyerName',
      buyer_tax_code = v_buyer_payload ->> 'buyerTaxCode',
      buyer_address = v_buyer_payload ->> 'buyerAddress',
      buyer_email = NULLIF(v_buyer_payload ->> 'buyerEmail', ''),
      updated_at = now()
  WHERE id = v_invoice.id;

  INSERT INTO public.tax_invoice_events (
    tax_invoice_id,
    tenant_id,
    from_status,
    to_status,
    actor_id,
    payload,
    note
  ) VALUES (
    v_invoice.id,
    v_invoice.tenant_id,
    'draft',
    'draft',
    NULL,
    jsonb_build_object(
      'buyer_tax_code', v_buyer_payload ->> 'buyerTaxCode',
      'buyer_name', v_buyer_payload ->> 'buyerName',
      'source', 'receipt_qr'
    ),
    'Buyer details confirmed from receipt QR'
  );

  UPDATE public.tax_invoice_buyer_requests
  SET status = 'submitted',
      submitted_payload = v_buyer_payload,
      submitted_at = now(),
      closed_at = now(),
      close_reason = 'customer_submitted',
      updated_at = now()
  WHERE id = v_request.id;

  UPDATE public.tax_invoice_issue_jobs
  SET invoice_payload = v_payload,
      available_at = now(),
      updated_at = now()
  WHERE id = v_job.id;

  RETURN jsonb_build_object(
    'status', 'submitted',
    'jobId', v_job.id,
    'taxInvoiceId', v_invoice.id
  );
END;
$$;


--
-- Name: submit_leave_request(bigint, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_leave_request(p_branch_id bigint, p_start_date date, p_end_date date, p_leave_type text DEFAULT 'annual'::text, p_reason text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_actor uuid := auth.uid();
  v_role text := public.auth_role();
  v_employee_id bigint;
  v_assigned_branch_id bigint;
  v_branch_kind text;
  v_request_id bigint;
  v_leave_type text := COALESCE(NULLIF(btrim(p_leave_type), ''), 'annual');
BEGIN
  SELECT employee.id, profile.branch_id
  INTO v_employee_id, v_assigned_branch_id
  FROM public.employees employee
  JOIN public.profiles profile
    ON profile.id = employee.profile_id AND profile.tenant_id = employee.tenant_id
  WHERE employee.profile_id = v_actor
    AND employee.tenant_id = v_tenant_id
    AND employee.is_active
    AND profile.is_active;

  IF v_actor IS NULL OR v_employee_id IS NULL OR v_role = 'owner' THEN
    RAISE EXCEPTION 'submit_leave_request: self service not allowed' USING ERRCODE = '42501';
  END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date
     OR p_start_date < (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date THEN
    RAISE EXCEPTION 'submit_leave_request: invalid date range' USING ERRCODE = '23514';
  END IF;
  IF v_leave_type NOT IN ('annual', 'sick', 'unpaid', 'personal', 'other') THEN
    RAISE EXCEPTION 'submit_leave_request: invalid leave type' USING ERRCODE = '23514';
  END IF;
  IF p_reason IS NOT NULL AND char_length(p_reason) > 500 THEN
    RAISE EXCEPTION 'submit_leave_request: reason too long' USING ERRCODE = '22001';
  END IF;

  IF v_role = 'accountant' THEN
    IF v_assigned_branch_id IS NOT NULL OR p_branch_id IS NOT NULL THEN
      RAISE EXCEPTION 'submit_leave_request: accountant scope must be null' USING ERRCODE = '42501';
    END IF;
    v_branch_kind := NULL;
  ELSE
    IF v_assigned_branch_id IS NULL
       OR p_branch_id IS DISTINCT FROM v_assigned_branch_id THEN
      RAISE EXCEPTION 'submit_leave_request: assigned site mismatch' USING ERRCODE = '42501';
    END IF;
    SELECT branch.branch_kind INTO v_branch_kind
    FROM public.branches branch
    WHERE branch.id = v_assigned_branch_id
      AND branch.tenant_id = v_tenant_id
      AND branch.is_active
      AND branch.branch_kind IN ('branch', 'central_supply', 'central_kitchen');
    IF v_branch_kind IS NULL THEN
      RAISE EXCEPTION 'submit_leave_request: branch not found or inactive' USING ERRCODE = '23503';
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(v_employee_id);
  IF EXISTS (
    SELECT 1 FROM public.leave_requests request
    WHERE request.tenant_id = v_tenant_id
      AND request.employee_id = v_employee_id
      AND request.status IN ('pending', 'approved')
      AND daterange(request.start_date, request.end_date, '[]')
          && daterange(p_start_date, p_end_date, '[]')
  ) THEN
    RAISE EXCEPTION 'submit_leave_request: date range overlaps existing request'
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.leave_requests (
    tenant_id, branch_id, employee_id, start_date, end_date, leave_type,
    status, reason
  )
  VALUES (
    v_tenant_id, v_assigned_branch_id, v_employee_id, p_start_date, p_end_date,
    v_leave_type, 'pending', NULLIF(btrim(p_reason), '')
  )
  RETURNING id INTO v_request_id;

  INSERT INTO public.notifications (
    tenant_id, target_branch_id, target_roles, kind, severity, title, body,
    entity_type, entity_id, action_url, meta, dedup_key
  )
  VALUES (
    v_tenant_id,
    CASE WHEN v_branch_kind = 'branch' AND v_role <> 'branch_manager'
      THEN v_assigned_branch_id ELSE NULL END,
    CASE WHEN v_branch_kind = 'branch' AND v_role <> 'branch_manager'
      THEN ARRAY['branch_manager', 'owner']::text[] ELSE ARRAY['owner']::text[] END,
    'hr.leave_requested', 'info', 'Yêu cầu nghỉ phép mới',
    'Nhân viên đã gửi yêu cầu nghỉ phép.',
    'leave_request', v_request_id,
    CASE WHEN v_branch_kind = 'branch' AND v_role <> 'branch_manager'
      THEN format('/br/%s/shift/leave-approvals', v_assigned_branch_id)
      ELSE '/hr/attendance?tab=approvals' END,
    jsonb_build_object('leave_request_id', v_request_id, 'branch_id', v_assigned_branch_id),
    format('hr.leave_request:%s', v_request_id)
  )
  ON CONFLICT (tenant_id, dedup_key) WHERE dedup_key IS NOT NULL
  DO UPDATE SET created_at = EXCLUDED.created_at, expires_at = NULL, meta = EXCLUDED.meta;

  RETURN v_request_id;
END;
$$;


--
-- Name: FUNCTION submit_leave_request(p_branch_id bigint, p_start_date date, p_end_date date, p_leave_type text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_leave_request(p_branch_id bigint, p_start_date date, p_end_date date, p_leave_type text, p_reason text) IS 'Submits an exact-branch leave request and notifies canonical approver roles.';


--
-- Name: submit_purchase_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_purchase_request(p_request_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_request record;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT request.*
  INTO v_request
  FROM public.purchase_requests request
  WHERE request.id = p_request_id
    AND request.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_request_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_request.branch_id, 'procurement:grn_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_request.status <> 'draft' THEN
    RAISE EXCEPTION 'purchase_request_not_draft' USING ERRCODE = '23514';
  END IF;

  UPDATE public.purchase_requests
  SET status = 'submitted',
      submitted_by = v_uid,
      submitted_at = now(),
      updated_at = now()
  WHERE id = p_request_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'request_id', p_request_id,
    'status', 'submitted'
  );
END;
$$;


--
-- Name: submit_stock_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_stock_request(p_request_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_req public.stock_requests%ROWTYPE;
  v_line_count int;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_req
  FROM public.stock_requests AS req
  WHERE req.id = p_request_id AND req.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stock_request_not_found' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_req.status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'stock_request_not_draft' USING ERRCODE = '22023';
  END IF;
  IF NOT public.auth_is_owner(auth.uid())
     AND NOT public.has_permission(
       v_req.branch_id,
       'inventory:request_submit'
     )
  THEN
    RAISE EXCEPTION 'forbidden_request_submit' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::int INTO v_line_count
  FROM public.stock_request_items AS item
  WHERE item.request_id = p_request_id
    AND item.tenant_id = v_tenant;

  IF v_line_count < 1 THEN
    RAISE EXCEPTION 'stock_request_empty' USING ERRCODE = '22023';
  END IF;

  UPDATE public.stock_requests
  SET status = 'submitted',
      submitted_at = now(),
      updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('request_id', p_request_id, 'status', 'submitted');
END;
$$;


--
-- Name: sync_insurance_base(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_insurance_base(p_employee_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_insurance_base NUMERIC(15,2);
  v_gross NUMERIC(15,2);
BEGIN
  SELECT ec.insurance_base_salary, ec.gross_salary
  INTO v_insurance_base, v_gross
  FROM public.employment_contracts ec
  WHERE ec.employee_id = p_employee_id
    AND ec.status = 'active'
  ORDER BY ec.start_date DESC
  LIMIT 1;

  IF v_insurance_base IS NOT NULL THEN
    UPDATE public.employees
    SET
      insurance_base_salary = v_insurance_base,
      base_salary = v_gross,
      updated_at = now()
    WHERE id = p_employee_id;
  END IF;
END;
$$;


--
-- Name: sync_missing_permissions_from_template(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_missing_permissions_from_template() RETURNS TABLE(rows_added integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_profile record;
  v_permission record;
  v_added integer := 0;
  v_rows integer;
BEGIN
  FOR v_profile IN
    SELECT
      pr.id AS user_id,
      pr.tenant_id,
      pr.branch_id,
      po.code AS position_code,
      private.staff_role_from_position_code(po.code) AS user_role
    FROM public.profiles pr
    JOIN public.positions po
      ON po.id = pr.position_id
     AND po.tenant_id = pr.tenant_id
    WHERE COALESCE(pr.is_active, true) = true
      AND COALESCE(po.is_active, true) = true
  LOOP
    IF v_profile.user_role IS NULL THEN
      CONTINUE;
    END IF;

    FOR v_permission IN
      SELECT
        rt.id AS template_id,
        pk.key AS permission_key,
        CASE
          WHEN pk.scope = 'tenant' THEN NULL::bigint
          ELSE v_profile.branch_id
        END AS grant_branch_id
      FROM public.role_templates rt
      CROSS JOIN LATERAL unnest(rt.permission_keys) AS perm(permission_key)
      JOIN public.permission_keys pk ON pk.key = perm.permission_key
      WHERE rt.tenant_id = v_profile.tenant_id
        AND rt.position_code = v_profile.position_code
    LOOP
      IF v_permission.grant_branch_id IS NULL
         AND EXISTS (
           SELECT 1
           FROM public.permission_keys pk
           WHERE pk.key = v_permission.permission_key
             AND pk.scope = 'branch'
         ) THEN
        CONTINUE;
      END IF;

      INSERT INTO public.staff_permissions (
        user_id,
        tenant_id,
        branch_id,
        permission_key,
        source_template
      )
      VALUES (
        v_profile.user_id,
        v_profile.tenant_id,
        v_permission.grant_branch_id,
        v_permission.permission_key,
        v_permission.template_id
      )
      ON CONFLICT DO NOTHING;

      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END LOOP;
  END LOOP;

  RETURN QUERY SELECT v_added;
END;
$$;


--
-- Name: FUNCTION sync_missing_permissions_from_template(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_missing_permissions_from_template() IS 'Additive backfill: inserts template rows missing from staff_permissions. Never removes. Safe to run anytime after a template edit.';


--
-- Name: sync_order_item_status_from_kds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_order_item_status_from_kds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    UPDATE public.order_items oi
    SET
      status = CASE
        WHEN NEW.status = 'cancelled' THEN 'cancelled'::text
        ELSE NEW.status::text
      END,
      updated_at = now()
    WHERE oi.id = NEW.order_item_id
      AND oi.tenant_id = NEW.tenant_id
      AND oi.status <> 'cancelled';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tio_assert_one_active_summary_per_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tio_assert_one_active_summary_per_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('hddt-order:' || NEW.order_id::text, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM public.tax_invoices direct_invoice
    WHERE direct_invoice.tenant_id = NEW.tenant_id
      AND direct_invoice.order_id = NEW.order_id
      AND direct_invoice.status NOT IN (
        'cancelled',
        'replaced',
        'not_required'
      )
  ) THEN
    RAISE EXCEPTION 'order % already has active per-order invoice', NEW.order_id
      USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.tax_invoice_orders tio
    JOIN public.tax_invoices summary_invoice
      ON summary_invoice.id = tio.tax_invoice_id
    WHERE tio.tenant_id = NEW.tenant_id
      AND tio.order_id = NEW.order_id
      AND tio.tax_invoice_id <> NEW.tax_invoice_id
      AND summary_invoice.status NOT IN ('cancelled', 'replaced')
  ) THEN
    RAISE EXCEPTION 'order % already in active daily summary', NEW.order_id
      USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: toggle_category_active(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_category_active(p_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_state BOOLEAN;
BEGIN
  UPDATE public.menu_categories
    SET is_active = NOT is_active
    WHERE id = p_id AND tenant_id = public.auth_tenant_id()
    RETURNING is_active INTO new_state;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  RETURN new_state;
END;
$$;


--
-- Name: toggle_ingredient_active(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_ingredient_active(p_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_new_state boolean;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '28000';
  END IF;
  IF public.auth_role() <> 'owner'
     OR NOT public.has_permission_any('inventory:write') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.ingredients
  SET is_active = NOT is_active,
      updated_at = now()
  WHERE id = p_id
    AND tenant_id = v_tenant
  RETURNING is_active INTO v_new_state;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found'
      USING ERRCODE = 'P0002';
  END IF;

  RETURN v_new_state;
END;
$$;


--
-- Name: toggle_item_active(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_item_active(p_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_state BOOLEAN;
BEGIN
  UPDATE public.menu_items
    SET is_active = NOT is_active
    WHERE id = p_id AND tenant_id = public.auth_tenant_id()
    RETURNING is_active INTO new_state;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  RETURN new_state;
END;
$$;


--
-- Name: toggle_profile_active(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_profile_active(p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_current boolean;
BEGIN
  SELECT COALESCE(p.is_active, true)
  INTO v_current
  FROM public.profiles p
  WHERE p.id = p_target_id
    AND p.tenant_id = public.auth_tenant_id();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_profile_not_found_in_tenant' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.update_staff_profile(
    p_target_id => p_target_id,
    p_is_active => NOT v_current
  );

  RETURN NOT v_current;
END;
$$;


--
-- Name: FUNCTION toggle_profile_active(p_target_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.toggle_profile_active(p_target_id uuid) IS 'Staff active-state toggle RPC. SECURITY DEFINER with staff:manage gate before role hierarchy checks.';


--
-- Name: transfer_order_table(bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_order_table(p_order_id bigint, p_new_table_id bigint, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order RECORD;
  v_new_table RECORD;
  v_old_table_id BIGINT;
  v_active_on_old INT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT id, tenant_id, branch_id, table_id, order_type, status,
         last_transfer_idempotency_key
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role <> 'owner' THEN
    IF v_prof_branch IS NULL THEN
      RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
    END IF;
    IF v_order.branch_id <> v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'forbidden: missing pos:use' USING ERRCODE = '42501';
  END IF;

  IF p_idempotency_key IS NOT NULL
     AND v_order.last_transfer_idempotency_key = p_idempotency_key THEN
    RETURN jsonb_build_object(
      'order_id', p_order_id,
      'table_id', v_order.table_id,
      'idempotent', true
    );
  END IF;

  IF v_order.order_type <> 'dine_in' THEN
    RAISE EXCEPTION 'takeaway cannot transfer' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  SELECT id, status INTO v_new_table
  FROM public.tables
  WHERE id = p_new_table_id AND branch_id = v_order.branch_id AND tenant_id = v_order.tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'table not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_new_table_id = v_order.table_id THEN
    UPDATE public.orders
    SET last_transfer_idempotency_key = COALESCE(p_idempotency_key, last_transfer_idempotency_key),
        updated_at = now()
    WHERE id = p_order_id;
    RETURN jsonb_build_object('order_id', p_order_id, 'table_id', p_new_table_id);
  END IF;

  IF v_new_table.status NOT IN ('available', 'occupied') THEN
    RAISE EXCEPTION 'table not available' USING ERRCODE = '22023';
  END IF;

  v_old_table_id := v_order.table_id;

  UPDATE public.orders
  SET table_id = p_new_table_id,
      last_transfer_idempotency_key = p_idempotency_key,
      updated_at = now()
  WHERE id = p_order_id;

  UPDATE public.tables
  SET status = 'occupied', updated_at = now()
  WHERE id = p_new_table_id AND tenant_id = v_order.tenant_id;

  IF v_old_table_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_active_on_old
    FROM public.orders
    WHERE table_id = v_old_table_id
      AND tenant_id = v_order.tenant_id
      AND id <> p_order_id
      AND status NOT IN ('completed', 'cancelled', 'served');

    IF v_active_on_old = 0 THEN
      UPDATE public.tables
      SET status = 'available', updated_at = now()
      WHERE id = v_old_table_id AND tenant_id = v_order.tenant_id;
    END IF;
  END IF;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id, p_order_id, v_order.status, v_order.status, v_uid,
    'transfer_table -> ' || p_new_table_id::text
  );

  RETURN jsonb_build_object('order_id', p_order_id, 'table_id', p_new_table_id);
END;
$$;


--
-- Name: transition_expense_payment(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_expense_payment(p_expense_id bigint, p_target_method text) RETURNS TABLE(expense_id bigint, payment_method text, paid_at timestamp with time zone, transfer_content text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_user_id uuid := auth.uid();
  v_expense public.expenses%ROWTYPE;
  v_updated public.expenses%ROWTYPE;
  v_prelock_transfer_content text;
  v_is_paid_correction boolean := false;
BEGIN
  IF v_user_id IS NULL
    OR v_tenant_id IS NULL
    OR NOT (
      public.auth_is_owner(v_user_id)
      OR public.has_position('accountant')
    )
    OR NOT public.has_permission_any('finance:expense_create')
    OR NOT EXISTS (
      SELECT 1
      FROM public.profiles profile
      WHERE profile.id = v_user_id
        AND profile.tenant_id = v_tenant_id
        AND COALESCE(profile.is_active, true)
    )
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_target_method IS NULL
    OR p_target_method NOT IN ('cash', 'transfer', 'unpaid')
  THEN
    RAISE EXCEPTION 'expense_payment_target_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT expense.transfer_content
  INTO v_prelock_transfer_content
  FROM public.expenses expense
  WHERE expense.id = p_expense_id
    AND expense.tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'expense_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_target_method = 'unpaid'
    AND v_prelock_transfer_content IS NOT NULL
  THEN
    PERFORM event.id
    FROM public.webhook_events event
    WHERE event.tenant_id = v_tenant_id
      AND event.provider = 'sepay'
      AND private.sepay_payload_contains_transfer_content(
        event.payload,
        v_prelock_transfer_content
      )
    ORDER BY event.id
    FOR UPDATE;
  END IF;

  SELECT expense.*
  INTO v_expense
  FROM public.expenses expense
  WHERE expense.id = p_expense_id
    AND expense.tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'expense_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_target_method = 'unpaid'
    AND v_expense.transfer_content IS NOT NULL
    AND v_expense.transfer_content IS DISTINCT FROM v_prelock_transfer_content
  THEN
    RAISE EXCEPTION 'expense_payment_state_changed' USING ERRCODE = '40001';
  END IF;

  IF NOT (
    v_expense.category = ANY (ARRAY[
      'rent',
      'utilities',
      'gas_fuel',
      'salary',
      'supplies',
      'repair',
      'marketing',
      'fees_tax',
      'hospitality',
      'other'
    ]::text[])
  ) THEN
    RAISE EXCEPTION 'expense_payment_transition_not_operating'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bank_transaction_expense_matches match
    WHERE match.tenant_id = v_tenant_id
      AND match.expense_id = v_expense.id
  ) OR EXISTS (
    SELECT 1
    FROM public.webhook_events event
    WHERE event.tenant_id = v_tenant_id
      AND event.provider = 'sepay'
      AND event.expense_id = v_expense.id
  ) THEN
    RAISE EXCEPTION 'expense_already_matched' USING ERRCODE = '23505';
  END IF;

  IF p_target_method = 'cash'
    AND v_expense.payment_method = 'cash'
    AND v_expense.paid_at IS NOT NULL
    AND v_expense.transfer_content IS NULL
  THEN
    RETURN QUERY SELECT
      v_expense.id,
      v_expense.payment_method,
      v_expense.paid_at,
      v_expense.transfer_content;
    RETURN;
  END IF;

  IF p_target_method = 'transfer'
    AND v_expense.payment_method = 'transfer'
    AND v_expense.paid_at IS NOT NULL
  THEN
    RETURN QUERY SELECT
      v_expense.id,
      v_expense.payment_method,
      v_expense.paid_at,
      v_expense.transfer_content;
    RETURN;
  END IF;

  IF p_target_method = 'unpaid'
    AND v_expense.payment_method = 'unpaid'
    AND v_expense.paid_at IS NULL
    AND v_expense.transfer_content IS NULL
  THEN
    RETURN QUERY SELECT
      v_expense.id,
      v_expense.payment_method,
      v_expense.paid_at,
      v_expense.transfer_content;
    RETURN;
  END IF;

  v_is_paid_correction :=
    v_expense.paid_at IS NOT NULL
    AND v_expense.payment_method IN ('cash', 'transfer')
    AND p_target_method IS DISTINCT FROM v_expense.payment_method;

  IF v_is_paid_correction THEN
    NULL;
  ELSIF v_expense.payment_method = 'unpaid'
    AND v_expense.paid_at IS NULL
  THEN
    IF p_target_method = 'cash'
      AND v_expense.transfer_content IS NOT NULL
    THEN
      RAISE EXCEPTION 'expense_transfer_instruction_must_cancel'
        USING ERRCODE = '23514';
    END IF;

    IF p_target_method = 'unpaid'
      AND v_expense.transfer_content IS NULL
    THEN
      RAISE EXCEPTION 'expense_payment_state_final' USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'expense_payment_state_final' USING ERRCODE = '23514';
  END IF;

  PERFORM set_config(
    'app.expense_payment_transition_id',
    v_expense.id::text,
    true
  );

  UPDATE public.expenses expense
  SET payment_method = CASE
        WHEN p_target_method = 'cash' THEN 'cash'
        WHEN p_target_method = 'transfer' THEN 'transfer'
        ELSE 'unpaid'
      END,
      paid_at = CASE
        WHEN p_target_method = 'unpaid' THEN NULL
        WHEN v_expense.paid_at IS NOT NULL THEN v_expense.paid_at
        ELSE now()
      END,
      transfer_content = CASE
        WHEN p_target_method = 'transfer'
          AND NOT v_is_paid_correction
          THEN v_expense.transfer_content
        ELSE NULL
      END
  WHERE expense.id = v_expense.id
    AND expense.tenant_id = v_tenant_id
  RETURNING expense.* INTO v_updated;

  PERFORM set_config('app.expense_payment_transition_id', '', true);

  PERFORM public.log_audit(
    'update',
    'expense',
    v_expense.id,
    to_jsonb(v_expense),
    to_jsonb(v_updated)
  );

  RETURN QUERY SELECT
    v_updated.id,
    v_updated.payment_method,
    v_updated.paid_at,
    v_updated.transfer_content;
END;
$$;


--
-- Name: FUNCTION transition_expense_payment(p_expense_id bigint, p_target_method text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transition_expense_payment(p_expense_id bigint, p_target_method text) IS 'Confirm unpaid operating expense as cash or bank transfer, cancel a transfer-content intent, or correct an unmatched paid method (cash/transfer/unpaid) for Owner/Accountant with finance:expense_create.';


--
-- Name: transition_order_item_status(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_order_item_status(p_item_id bigint, p_new_status text, p_expected_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id UUID;
  v_actor_tenant BIGINT;
  v_actor_branch BIGINT;
  v_item RECORD;
  v_order RECORD;
  v_derived_status TEXT;
  v_old_order_status TEXT;
  v_pending_count INT;
  v_preparing_count INT;
  v_ready_count INT;
  v_served_count INT;
  v_cancelled_count INT;
  v_total_count INT;
BEGIN
  -- Auth context
  v_actor_id := auth.uid();
  v_actor_tenant := public.auth_tenant_id();
  v_actor_branch := public.auth_branch_id();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  -- Validate new_status
  IF p_new_status NOT IN ('pending', 'preparing', 'ready', 'served', 'cancelled') THEN
    RAISE EXCEPTION 'invalid item status: %', p_new_status USING ERRCODE = '22023';
  END IF;

  -- Fetch and lock item + parent order
  SELECT oi.id, oi.order_id, oi.tenant_id, oi.status AS item_status
  INTO v_item
  FROM public.order_items oi
  WHERE oi.id = p_item_id
    AND oi.tenant_id = v_actor_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Fetch parent order for branch check
  SELECT o.id, o.branch_id, o.status, o.table_id, o.order_type, o.tenant_id
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_item.order_id
  FOR UPDATE;

  -- Branch authorization (ops roles must be in same branch, managers bypass)
  IF v_actor_branch IS NOT NULL AND v_order.branch_id <> v_actor_branch THEN
    RAISE EXCEPTION 'not_in_branch' USING ERRCODE = 'P0003';
  END IF;

  -- Optimistic locking: verify expected status
  IF v_item.item_status <> p_expected_status THEN
    RAISE EXCEPTION 'status_changed:% expected % got %', v_item.item_status, p_expected_status, v_item.item_status
      USING ERRCODE = 'P0001';
  END IF;

  -- Validate transition
  IF NOT (
    (p_expected_status = 'pending' AND p_new_status IN ('preparing', 'cancelled'))
    OR (p_expected_status = 'preparing' AND p_new_status IN ('ready', 'cancelled'))
    OR (p_expected_status = 'ready' AND p_new_status = 'served')
    -- Allow served → cancelled for post-serve void (manager action)
  ) THEN
    RAISE EXCEPTION 'invalid_transition:% to %', p_expected_status, p_new_status
      USING ERRCODE = '22023';
  END IF;

  -- Apply item status change
  UPDATE public.order_items
  SET status = p_new_status, updated_at = now()
  WHERE id = p_item_id;

  -- ── Derive order status from sibling items ──
  v_old_order_status := v_order.status;

  SELECT
    COUNT(*) FILTER (WHERE status = 'pending') AS pending_count,
    COUNT(*) FILTER (WHERE status = 'preparing') AS preparing_count,
    COUNT(*) FILTER (WHERE status = 'ready') AS ready_count,
    COUNT(*) FILTER (WHERE status = 'served') AS served_count,
    COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled_count,
    COUNT(*) AS total_count
  INTO v_pending_count, v_preparing_count, v_ready_count, v_served_count, v_cancelled_count, v_total_count
  FROM public.order_items
  WHERE order_id = v_item.order_id;

  -- Derive new order status
  IF v_cancelled_count = v_total_count THEN
    v_derived_status := 'cancelled';
  ELSIF v_served_count + v_cancelled_count = v_total_count THEN
    v_derived_status := 'served';
  ELSIF v_ready_count + v_served_count + v_cancelled_count = v_total_count THEN
    v_derived_status := 'ready';
  ELSIF v_preparing_count > 0 OR v_ready_count > 0 THEN
    v_derived_status := 'preparing';
  ELSE
    v_derived_status := v_old_order_status; -- no change
  END IF;

  -- Update order status if changed
  IF v_derived_status <> v_old_order_status
     AND v_old_order_status NOT IN ('completed') -- never override completed
  THEN
    UPDATE public.orders
    SET status = v_derived_status, updated_at = now()
    WHERE id = v_item.order_id;

    -- Write audit trail for order transition
    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    ) VALUES (
      v_actor_tenant, v_item.order_id, v_old_order_status, v_derived_status,
      v_actor_id, 'derived from item ' || p_item_id || ' → ' || p_new_status
    );

    -- Table release handled by existing trigger trg_order_release_table
  END IF;

  RETURN jsonb_build_object(
    'item_id', p_item_id,
    'item_status', p_new_status,
    'order_id', v_item.order_id,
    'order_status', v_derived_status,
    'order_status_changed', v_derived_status <> v_old_order_status
  );
END;
$$;


--
-- Name: transition_order_status(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_order_status(p_order_id bigint, p_new_status text, p_expected_status text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id UUID;
  v_actor_tenant BIGINT;
  v_actor_branch BIGINT;
  v_order RECORD;
BEGIN
  v_actor_id := auth.uid();
  v_actor_tenant := public.auth_tenant_id();
  v_actor_branch := public.auth_branch_id();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, status, table_id, order_type
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = v_actor_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_branch IS NOT NULL AND v_order.branch_id <> v_actor_branch THEN
    RAISE EXCEPTION 'not_in_branch' USING ERRCODE = 'P0003';
  END IF;

  IF v_order.status <> p_expected_status THEN
    RAISE EXCEPTION 'status_changed:% expected % got %', v_order.status, p_expected_status, v_order.status
      USING ERRCODE = 'P0001';
  END IF;

  IF NOT (
    (p_expected_status = 'new' AND p_new_status = 'confirmed')
    OR (p_expected_status = 'served' AND p_new_status = 'completed')
    OR (p_expected_status NOT IN ('completed') AND p_new_status = 'cancelled')
  ) THEN
    RAISE EXCEPTION 'invalid_transition:% to %', p_expected_status, p_new_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.orders
  SET status = p_new_status, updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_actor_tenant, p_order_id, v_order.status, p_new_status, v_actor_id, p_note
  );

  IF p_new_status = 'cancelled' THEN
    UPDATE public.order_items
    SET status = 'cancelled', updated_at = now()
    WHERE order_id = p_order_id
      AND status NOT IN ('served', 'cancelled');
  END IF;

  IF p_new_status = 'completed' AND p_expected_status = 'served' THEN
    PERFORM public.consume_stock_for_order(p_order_id);
  END IF;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'old_status', v_order.status,
    'new_status', p_new_status
  );
END;
$$;


--
-- Name: transition_supplier_return(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_supplier_return(p_return_id bigint, p_target_status text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid       UUID   := auth.uid();
  v_tenant    BIGINT := public.auth_tenant_id();
  v_ret       RECORD;
  v_credit_id BIGINT;
  v_credit_no TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_target_status NOT IN ('credited', 'refunded', 'cancelled') THEN
    RAISE EXCEPTION 'invalid_target_status' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ret
  FROM public.supplier_returns
  WHERE id = p_return_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'return_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Permission: confirm-grade for credit/refund (impacts AP); confirm-grade for cancel too
  IF NOT public.has_permission(v_ret.branch_id, 'supplier_return:confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- State transition rules
  IF p_target_status = 'cancelled' AND v_ret.status NOT IN ('draft', 'sent') THEN
    RAISE EXCEPTION 'cannot_cancel_after_credit' USING ERRCODE = '22023';
  END IF;
  IF p_target_status IN ('credited', 'refunded') AND v_ret.status <> 'sent' THEN
    RAISE EXCEPTION 'must_be_sent_before_credit' USING ERRCODE = '22023';
  END IF;
  IF p_target_status = 'credited' AND v_ret.resolution <> 'credit_note' THEN
    RAISE EXCEPTION 'resolution_mismatch_credit' USING ERRCODE = '22023';
  END IF;
  IF p_target_status = 'refunded' AND v_ret.resolution <> 'cash_refund' THEN
    RAISE EXCEPTION 'resolution_mismatch_refund' USING ERRCODE = '22023';
  END IF;

  -- Move state
  UPDATE public.supplier_returns
  SET status = p_target_status,
      notes = COALESCE(p_notes, notes),
      updated_at = now()
  WHERE id = p_return_id;

  -- Auto-create supplier_credit_note for credited/refunded
  IF p_target_status IN ('credited', 'refunded') THEN
    v_credit_no := 'CN-' || to_char(now(),'YYMMDD') || '-' ||
                   lpad(nextval('public.supplier_credit_notes_id_seq')::TEXT, 4, '0');

    INSERT INTO public.supplier_credit_notes (
      tenant_id, supplier_id, return_id, credit_number,
      kind, amount, status, notes, created_by, applied_at
    ) VALUES (
      v_tenant, v_ret.supplier_id, p_return_id, v_credit_no,
      CASE WHEN p_target_status = 'credited' THEN 'credit_note' ELSE 'cash_refund' END,
      v_ret.total_value,
      CASE WHEN p_target_status = 'refunded' THEN 'applied' ELSE 'open' END,
      p_notes,
      v_uid,
      CASE WHEN p_target_status = 'refunded' THEN now() ELSE NULL END
    )
    ON CONFLICT (return_id, tenant_id) DO NOTHING
    RETURNING id INTO v_credit_id;
  END IF;

  RETURN jsonb_build_object(
    'return_id', p_return_id,
    'status', p_target_status,
    'credit_note_id', v_credit_id,
    'credit_number', v_credit_no
  );
END;
$$;


--
-- Name: FUNCTION transition_supplier_return(p_return_id bigint, p_target_status text, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transition_supplier_return(p_return_id bigint, p_target_status text, p_notes text) IS 'Transitions supplier_returns.status from sent → credited|refunded|cancelled. For credited/refunded, auto-inserts a supplier_credit_notes row (idempotent on return_id).';


--
-- Name: transition_tax_invoice_state(bigint, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_tax_invoice_state(p_tax_invoice_id bigint, p_to_status text, p_payload jsonb DEFAULT NULL::jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice  RECORD;
  v_uid      UUID := auth.uid();
  v_allowed  BOOLEAN := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices
  WHERE id = p_tax_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_invoice.tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_to_status IN ('cancelled', 'replaced') THEN
    IF NOT (public.auth_is_owner(v_uid) OR public.has_position('accountant'))
      OR NOT public.has_permission_any('finance:view') THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission(v_invoice.branch_id, 'orders:write') THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_allowed := (
    (v_invoice.status = 'draft'     AND p_to_status IN ('signing', 'cancelled'))
    OR (v_invoice.status = 'signing'   AND p_to_status IN ('submitted', 'issued', 'draft', 'cancelled'))
    OR (v_invoice.status = 'submitted' AND p_to_status IN ('issued', 'cancelled'))
    OR (v_invoice.status = 'issued'    AND p_to_status IN ('cancelled', 'replaced'))
  );

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'illegal_transition: % -> %', v_invoice.status, p_to_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.tax_invoices
  SET
    status = p_to_status,
    issued_at = CASE WHEN p_to_status = 'issued' THEN now() ELSE issued_at END,
    cancelled_at = CASE WHEN p_to_status = 'cancelled' THEN now() ELSE cancelled_at END,
    signing_started_at = CASE WHEN p_to_status = 'signing' THEN now() ELSE signing_started_at END,
    provider_data = CASE
      WHEN p_payload IS NULL THEN provider_data
      ELSE COALESCE(provider_data, '{}'::JSONB) || jsonb_build_object(p_to_status, p_payload)
    END,
    updated_at = now()
  WHERE id = p_tax_invoice_id;

  INSERT INTO public.tax_invoice_events
    (tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note)
  VALUES
    (p_tax_invoice_id, v_invoice.tenant_id, v_invoice.status, p_to_status, v_uid, p_payload, p_note);

  RETURN jsonb_build_object(
    'tax_invoice_id', p_tax_invoice_id,
    'from_status', v_invoice.status,
    'to_status', p_to_status
  );
END;
$$;


--
-- Name: transition_tax_invoice_state_as_system(bigint, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_tax_invoice_state_as_system(p_tax_invoice_id bigint, p_to_status text, p_actor uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT NULL::jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_allowed BOOLEAN := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices
  WHERE id = p_tax_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_allowed := (
    (v_invoice.status = 'draft'     AND p_to_status IN ('signing', 'cancelled'))
    OR (v_invoice.status = 'signing'   AND p_to_status IN ('submitted', 'issued', 'draft', 'cancelled'))
    OR (v_invoice.status = 'submitted' AND p_to_status IN ('issued', 'cancelled'))
    OR (v_invoice.status = 'issued'    AND p_to_status IN ('cancelled', 'replaced'))
  );

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'illegal_transition: % -> %', v_invoice.status, p_to_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.tax_invoices
  SET
    status = p_to_status,
    issued_at = CASE WHEN p_to_status = 'issued'    THEN now() ELSE issued_at END,
    cancelled_at = CASE WHEN p_to_status = 'cancelled' THEN now() ELSE cancelled_at END,
    signing_started_at = CASE WHEN p_to_status = 'signing'   THEN now() ELSE signing_started_at END,
    provider_data = CASE
      WHEN p_payload IS NULL THEN provider_data
      WHEN provider_data IS NULL THEN p_payload
      ELSE provider_data || p_payload
    END,
    updated_at = now()
  WHERE id = p_tax_invoice_id;

  INSERT INTO public.tax_invoice_events
    (tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note)
  VALUES
    (p_tax_invoice_id, v_invoice.tenant_id, v_invoice.status, p_to_status, p_actor, p_payload, p_note);

  RETURN jsonb_build_object(
    'tax_invoice_id', p_tax_invoice_id,
    'from_status', v_invoice.status,
    'to_status', p_to_status,
    'actor', p_actor
  );
END;
$$;


--
-- Name: FUNCTION transition_tax_invoice_state_as_system(p_tax_invoice_id bigint, p_to_status text, p_actor uuid, p_payload jsonb, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transition_tax_invoice_state_as_system(p_tax_invoice_id bigint, p_to_status text, p_actor uuid, p_payload jsonb, p_note text) IS 'Service-role-only overload of transition_tax_invoice_state. Use from cron routes that need to drive HĐĐT state machine without auth.uid(). Per D1 owner decision 2026-05-08.';


