--
-- Name: trg_notify_po_sent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_notify_po_sent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_branch_kind text;
  v_target_branch_id bigint;
  v_target_roles text[];
  v_kind text;
  v_title text;
  v_body text;
  v_action_url text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status
     OR NEW.status NOT IN ('sent', 'pending_approval', 'approved') THEN
    RETURN NEW;
  END IF;

  SELECT branch.branch_kind
  INTO v_branch_kind
  FROM public.branches AS branch
  WHERE branch.id = NEW.branch_id
    AND branch.tenant_id = NEW.tenant_id;

  IF NEW.status = 'pending_approval' THEN
    v_target_branch_id := NULL;
    v_target_roles := ARRAY['owner', 'accountant']::text[];
    v_kind := 'procurement.po_pending_approval';
    v_title := format('Phiếu mua %s chờ duyệt', NEW.po_number);
    v_body := 'Kiểm tra nhà cung cấp, số lượng và duyệt mua.';
    v_action_url := format(
      '/inventory/purchase-orders?poId=%s&mode=view',
      NEW.id
    );
  ELSE
    v_target_branch_id := NEW.branch_id;
    v_target_roles := CASE v_branch_kind
      WHEN 'central_supply'
        THEN ARRAY['owner', 'central_supply_ops']::text[]
      WHEN 'central_kitchen'
        THEN ARRAY['owner', 'central_kitchen_lead']::text[]
      ELSE ARRAY['owner', 'branch_manager']::text[]
    END;
    v_kind := CASE NEW.status
      WHEN 'approved' THEN 'workflow.po_approved'
      ELSE 'workflow.po_sent'
    END;
    v_title := CASE NEW.status
      WHEN 'approved'
        THEN format('Phiếu mua %s đã duyệt', NEW.po_number)
      ELSE format('PO %s đã gửi nhà cung cấp', NEW.po_number)
    END;
    v_body := CASE NEW.status
      WHEN 'approved'
        THEN 'Phiếu nhập nháp đã sẵn sàng để Kho tiếp nhận hàng.'
      ELSE 'Chờ nhập hàng và đối chiếu phiếu nhập khi nhà cung cấp giao.'
    END;
    v_action_url := CASE
      WHEN v_branch_kind IN ('central_supply', 'central_kitchen')
        THEN '/inventory/grn'
      ELSE format('/br/%s/stock/grn', NEW.branch_id)
    END;
  END IF;

  INSERT INTO public.notifications (
    tenant_id,
    target_branch_id,
    target_roles,
    kind,
    severity,
    title,
    body,
    entity_type,
    entity_id,
    action_url,
    meta
  )
  VALUES (
    NEW.tenant_id,
    v_target_branch_id,
    v_target_roles,
    v_kind,
    'info',
    v_title,
    v_body,
    'purchase_order',
    NEW.id,
    v_action_url,
    jsonb_build_object(
      'po_number', NEW.po_number,
      'status', NEW.status
    )
  );

  RETURN NEW;
END;
$$;


--
-- Name: trg_notify_pos_shift_variance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_notify_pos_shift_variance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_threshold numeric(15,2);
  v_severity text;
  v_cashier_name text;
  v_diff_label text;
  v_diff_amount text;
BEGIN
  IF NEW.status = 'closed'
     AND OLD.status = 'open'
     AND NEW.cash_difference IS NOT NULL
     AND NEW.expected_cash IS NOT NULL THEN
    v_threshold := GREATEST(
      50000::numeric,
      ROUND(COALESCE(NEW.expected_cash, 0) * 0.005, 2)
    );

    IF abs(NEW.cash_difference) > v_threshold THEN
      v_severity := CASE
        WHEN abs(NEW.cash_difference) > v_threshold * 5 THEN 'critical'
        ELSE 'warning'
      END;

      SELECT full_name INTO v_cashier_name
      FROM public.profiles
      WHERE id = NEW.closed_by;

      v_diff_label := CASE
        WHEN NEW.cash_difference > 0 THEN 'thừa'
        ELSE 'thiếu'
      END;
      v_diff_amount := to_char(abs(NEW.cash_difference), 'FM999G999G999');

      INSERT INTO public.notifications (
        tenant_id, target_branch_id, target_roles,
        kind, severity, title, body,
        entity_type, entity_id, action_url, meta,
        dedup_key
      )
      VALUES (
        NEW.tenant_id,
        NEW.branch_id,
        ARRAY['branch_manager', 'owner']::text[],
        'pos.shift_variance',
        v_severity,
        format('Lệch quỹ ca #%s: %s %sđ', NEW.id, v_diff_label, v_diff_amount),
        format(
          '%s đóng ca lúc %s. Két thực %sđ — kỳ vọng %sđ. Ngưỡng cảnh báo %sđ.',
          COALESCE(v_cashier_name, 'Thu ngân'),
          to_char(NEW.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM'),
          to_char(COALESCE(NEW.closing_cash, 0), 'FM999G999G999'),
          to_char(NEW.expected_cash, 'FM999G999G999'),
          to_char(v_threshold, 'FM999G999G999')
        ),
        'pos_session',
        NEW.id,
        format('/br/%s/pos-sessions?session=%s', NEW.branch_id, NEW.id),
        jsonb_build_object(
          'session_id', NEW.id,
          'cashier_name', v_cashier_name,
          'opening_cash', NEW.opening_cash,
          'closing_cash', NEW.closing_cash,
          'expected_cash', NEW.expected_cash,
          'cash_difference', NEW.cash_difference,
          'variance_threshold', v_threshold,
          'variance_note', NEW.variance_approval_note
        ),
        format('pos.shift_variance:%s', NEW.id)
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trg_notify_pos_shift_variance(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trg_notify_pos_shift_variance() IS 'D8 (2026-04-27): emit pos.shift_variance notification khi cashier đóng ca với |cash_difference| > max(50k, 0.5%% × expected_cash). Severity critical nếu > 5× threshold (~lệch nghiêm trọng), warning ngược lại. Dedup per session_id chống re-fire.';


--
-- Name: trg_notify_stocktake_completed(); Type: FUNCTION; Schema: public; Owner: -
