--
-- Name: trg_update_stock_on_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_update_stock_on_movement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.location_id IS NULL THEN
    RAISE EXCEPTION 'stock_movements.location_id required (after per-location migration)'
      USING ERRCODE = '23502';
  END IF;

  UPDATE public.stock_levels
  SET
    current_quantity = current_quantity + NEW.quantity_change,
    updated_at = now()
  WHERE ingredient_id = NEW.ingredient_id
    AND branch_id IS NOT DISTINCT FROM NEW.branch_id
    AND location_id = NEW.location_id
    AND tenant_id = NEW.tenant_id;

  IF NOT FOUND THEN
    INSERT INTO public.stock_levels (
      tenant_id,
      branch_id,
      ingredient_id,
      location_id,
      current_quantity
    )
    VALUES (
      NEW.tenant_id,
      NEW.branch_id,
      NEW.ingredient_id,
      NEW.location_id,
      NEW.quantity_change
    );
  END IF;

  IF NEW.type = 'count_adjustment' THEN
    UPDATE public.stock_levels
    SET last_counted_at = now()
    WHERE ingredient_id = NEW.ingredient_id
      AND branch_id IS NOT DISTINCT FROM NEW.branch_id
      AND location_id = NEW.location_id
      AND tenant_id = NEW.tenant_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: update_ingredient_thresholds_bulk(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_ingredient_thresholds_bulk(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_row jsonb;
  v_value numeric;
  v_field text;
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF public.auth_role() <> 'owner'
     OR NOT public.has_permission_any('inventory:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_payload IS NOT NULL
     AND jsonb_typeof(p_payload) = 'array' THEN
    FOR v_row IN
      SELECT item.value
      FROM jsonb_array_elements(p_payload) AS item(value)
    LOOP
      FOREACH v_field IN ARRAY ARRAY[
        'min_stock_level',
        'max_stock_level',
        'reorder_point'
      ]::text[]
      LOOP
        IF v_row ? v_field
           AND v_row ->> v_field IS NOT NULL
           AND v_row ->> v_field <> '' THEN
          v_value := (v_row ->> v_field)::numeric;
          IF v_value = 'NaN'::numeric
             OR v_value = 'Infinity'::numeric
             OR v_value = '-Infinity'::numeric THEN
            RAISE EXCEPTION 'thresholds.bulk: non-finite value'
              USING ERRCODE = '22023';
          END IF;
        END IF;
      END LOOP;
    END LOOP;
  END IF;

  RETURN private.execute_update_ingredient_thresholds_bulk(
    p_payload
  );
END;
$$;


--
-- Name: update_my_dependents_count(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_dependents_count(p_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_user_id   UUID   := auth.uid();
  v_emp_id    BIGINT;
  v_old       INTEGER;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'update_my_dependents_count: missing auth context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_count IS NULL OR p_count < 0 OR p_count > 20 THEN
    RAISE EXCEPTION 'update_my_dependents_count: invalid count'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT id, dependents_count INTO v_emp_id, v_old
  FROM public.employees
  WHERE profile_id = v_user_id
    AND tenant_id = v_tenant_id
    AND is_active = true
  LIMIT 1;

  IF v_emp_id IS NULL THEN
    RAISE EXCEPTION 'update_my_dependents_count: no active employee record'
      USING ERRCODE = 'no_data_found';
  END IF;

  UPDATE public.employees
  SET dependents_count = p_count,
      updated_at = now()
  WHERE id = v_emp_id;

  PERFORM public.log_audit(
    'update'::TEXT,
    'employee'::TEXT,
    v_emp_id,
    jsonb_build_object('dependents_count', v_old),
    jsonb_build_object('dependents_count', p_count, 'self_service', true)
  );
END;
$$;


--
-- Name: FUNCTION update_my_dependents_count(p_count integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_my_dependents_count(p_count integer) IS 'Self-service: employee updates own dependents_count. Affects PIT. SECURITY DEFINER bypasses employees_write RLS; guarded by profile_id = auth.uid() and count in [0, 20].';


