--
-- Name: update_staff_profile(uuid, text, text, text, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_staff_profile(p_target_id uuid, p_full_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_position_code text DEFAULT NULL::text, p_branch_id bigint DEFAULT NULL::bigint, p_is_active boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor_tenant bigint;
  v_target record;
  v_final_position_id bigint;
  v_final_position_code text;
  v_final_role text;
  v_required_kind text;
  v_final_branch_id bigint;
  v_final_active boolean;
  v_assignment_changed boolean;
  v_permission record;
BEGIN
  SELECT profile.tenant_id
  INTO v_actor_tenant
  FROM public.profiles profile
  JOIN public.positions position
    ON position.id = profile.position_id
   AND position.tenant_id = profile.tenant_id
  WHERE profile.id = v_actor_id
    AND profile.is_active
    AND position.code = 'owner';

  IF NOT FOUND
     OR NOT public.has_permission_any('hr:manage_employee')
     OR NOT public.has_permission_any('staff:assign_position') THEN
    RAISE EXCEPTION 'forbidden_staff_profile_management'
      USING ERRCODE = '42501';
  END IF;

  SELECT
    profile.position_id,
    profile.branch_id,
    profile.is_active,
    position.code AS position_code
  INTO v_target
  FROM public.profiles profile
  JOIN public.positions position
    ON position.id = profile.position_id
   AND position.tenant_id = profile.tenant_id
  WHERE profile.id = p_target_id
    AND profile.tenant_id = v_actor_tenant
  FOR UPDATE OF profile;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_profile_not_found_in_tenant'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_target.position_code = 'owner' THEN
    RAISE EXCEPTION 'cannot_modify_owner' USING ERRCODE = '42501';
  END IF;

  v_final_position_code := COALESCE(
    NULLIF(p_position_code, ''),
    v_target.position_code
  );

  SELECT position.id,
         private.staff_role_from_position_code(position.code),
         private.required_branch_kind_for_position_code(position.code)
  INTO v_final_position_id, v_final_role, v_required_kind
  FROM public.positions position
  WHERE position.tenant_id = v_actor_tenant
    AND position.code = v_final_position_code
    AND position.is_active
  LIMIT 1;

  IF v_final_position_id IS NULL OR v_final_role = 'owner' THEN
    RAISE EXCEPTION 'position_not_assignable: %', v_final_position_code
      USING ERRCODE = '22023';
  END IF;

  IF v_final_role IS NULL THEN
    v_required_kind := NULL;
  END IF;

  IF v_required_kind IS NULL THEN
    v_final_branch_id := NULL;
  ELSE
    v_final_branch_id := COALESCE(p_branch_id, v_target.branch_id);

    IF v_final_branch_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.branches branch
      WHERE branch.id = v_final_branch_id
        AND branch.tenant_id = v_actor_tenant
        AND branch.branch_kind = v_required_kind
        AND branch.is_active
    ) THEN
      RAISE EXCEPTION 'position_site_kind_mismatch'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  v_final_active := COALESCE(p_is_active, v_target.is_active);
  v_assignment_changed :=
    v_target.position_id IS DISTINCT FROM v_final_position_id
    OR v_target.branch_id IS DISTINCT FROM v_final_branch_id
    OR v_target.is_active IS DISTINCT FROM v_final_active;

  UPDATE public.profiles
  SET full_name = COALESCE(p_full_name, full_name),
      phone = COALESCE(p_phone, phone),
      position_id = v_final_position_id,
      branch_id = v_final_branch_id,
      is_active = v_final_active,
      updated_at = now()
  WHERE id = p_target_id
    AND tenant_id = v_actor_tenant;

  IF v_assignment_changed THEN
    INSERT INTO public.permission_audit_log (
      tenant_id,
      actor_user_id,
      target_user_id,
      branch_id,
      permission_key,
      action,
      source_template_id,
      metadata
    )
    SELECT
      permission.tenant_id,
      v_actor_id,
      permission.user_id,
      permission.branch_id,
      permission.permission_key,
      'revoke',
      permission.source_template,
      jsonb_build_object('reason', 'profile_assignment_changed')
    FROM public.staff_permissions permission
    WHERE permission.user_id = p_target_id
      AND permission.tenant_id = v_actor_tenant;

    DELETE FROM public.staff_permissions permission
    WHERE permission.user_id = p_target_id
      AND permission.tenant_id = v_actor_tenant;

    IF v_final_active AND v_final_role IS NOT NULL THEN
      FOR v_permission IN
        SELECT
          template.id AS template_id,
          permission_key.key AS permission_key,
          CASE
            WHEN permission_key.scope = 'tenant' THEN NULL::bigint
            WHEN permission_key.scope = 'either'
                 AND v_final_role = 'accountant' THEN NULL::bigint
            ELSE v_final_branch_id
          END AS grant_branch_id
        FROM public.role_templates template
        CROSS JOIN LATERAL
          unnest(template.permission_keys) AS item(permission_key)
        JOIN public.permission_keys permission_key
          ON permission_key.key = item.permission_key
        WHERE template.tenant_id = v_actor_tenant
          AND template.position_code = v_final_position_code
      LOOP
        INSERT INTO public.staff_permissions (
          user_id,
          tenant_id,
          branch_id,
          permission_key,
          source_template,
          granted_by
        ) VALUES (
          p_target_id,
          v_actor_tenant,
          v_permission.grant_branch_id,
          v_permission.permission_key,
          v_permission.template_id,
          v_actor_id
        )
        ON CONFLICT DO NOTHING;

        INSERT INTO public.permission_audit_log (
          tenant_id,
          actor_user_id,
          target_user_id,
          branch_id,
          permission_key,
          action,
          source_template_id,
          metadata
        ) VALUES (
          v_actor_tenant,
          v_actor_id,
          p_target_id,
          v_permission.grant_branch_id,
          v_permission.permission_key,
          'grant',
          v_permission.template_id,
          jsonb_build_object('reason', 'profile_assignment_changed')
        );
      END LOOP;
    END IF;

    DELETE FROM auth.sessions session_row
    WHERE session_row.user_id = p_target_id;
  END IF;
END;
$$;


--
-- Name: FUNCTION update_staff_profile(p_target_id uuid, p_full_name text, p_phone text, p_position_code text, p_branch_id bigint, p_is_active boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_staff_profile(p_target_id uuid, p_full_name text, p_phone text, p_position_code text, p_branch_id bigint, p_is_active boolean) IS 'Owner-managed profile boundary. Unmapped active company positions receive self-service only and no position-derived work-module permissions.';


--
-- Name: update_tenant_identity(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_tenant_identity(p_legal_name text, p_tax_code text, p_legal_address text, p_representative text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant BIGINT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'permission denied: settings:tenant' USING ERRCODE = '42501';
  END IF;

  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  UPDATE public.tenants
  SET legal_name = NULLIF(btrim(p_legal_name), ''),
      tax_code = NULLIF(btrim(p_tax_code), ''),
      legal_address = NULLIF(btrim(p_legal_address), ''),
      representative = NULLIF(btrim(p_representative), ''),
      updated_at = now()
  WHERE id = v_tenant;
END;
$$;


--
-- Name: update_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: upsert_branch_revenue_targets(date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_branch_revenue_targets(p_year_month date, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_month date;
  v_updated integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT (public.auth_is_owner(v_uid) OR public.has_position('accountant'))
     OR NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_year_month IS NULL OR p_rows IS NULL
     OR jsonb_typeof(p_rows) <> 'array'
     OR jsonb_array_length(p_rows) < 1
     OR jsonb_array_length(p_rows) > 200 THEN
    RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
  END IF;

  v_month := date_trunc('month', p_year_month::timestamp)::date;

  WITH incoming AS (
    SELECT
      (row_data ->> 'branch_id')::bigint AS branch_id,
      (row_data ->> 'target_amount')::numeric AS target_amount,
      COALESCE(row_data -> 'reward_tiers', '[]'::jsonb) AS reward_tiers
    FROM jsonb_array_elements(p_rows) AS row_data
  ),
  validated AS (
    SELECT
      incoming.branch_id,
      incoming.target_amount,
      incoming.reward_tiers
    FROM incoming
    JOIN public.branches b
      ON b.id = incoming.branch_id
     AND b.tenant_id = v_tenant
     AND b.branch_kind = 'branch'
     AND b.is_active IS TRUE
    WHERE incoming.branch_id IS NOT NULL
      AND incoming.target_amount IS NOT NULL
      AND incoming.target_amount > 0
  ),
  upserted AS (
    INSERT INTO public.branch_revenue_targets AS t (
      tenant_id,
      branch_id,
      year_month,
      target_amount,
      reward_tiers,
      updated_by
    )
    SELECT
      v_tenant,
      validated.branch_id,
      v_month,
      round(validated.target_amount, 0),
      validated.reward_tiers,
      v_uid
    FROM validated
    ON CONFLICT (branch_id, year_month)
    DO UPDATE SET
      target_amount = EXCLUDED.target_amount,
      reward_tiers = EXCLUDED.reward_tiers,
      updated_by = EXCLUDED.updated_by,
      updated_at = now()
    RETURNING t.id
  )
  SELECT count(*)::integer INTO v_updated FROM upserted;

  IF v_updated = 0 THEN
    RAISE EXCEPTION 'no_valid_rows' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'updated', v_updated,
    'year_month', v_month
  );
END;
$$;


--
-- Name: FUNCTION upsert_branch_revenue_targets(p_year_month date, p_rows jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_branch_revenue_targets(p_year_month date, p_rows jsonb) IS 'Owner-only bulk upsert of monthly Doanh thu thuần targets and reward tiers per branch.';


--
-- Name: upsert_payroll_adjustment(bigint, bigint, date, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_payroll_adjustment(p_adjustment_id bigint DEFAULT NULL::bigint, p_employee_id bigint DEFAULT NULL::bigint, p_effective_month date DEFAULT NULL::date, p_kind text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_adjustment public.payroll_adjustments%ROWTYPE;
  v_existing boolean := false;
  v_month date := date_trunc('month', p_effective_month)::date;
  v_prior jsonb;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'upsert_payroll_adjustment: missing auth context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NOT public.has_permission_any('finance:payroll_calculate') THEN
    RAISE EXCEPTION 'upsert_payroll_adjustment: missing payroll permission'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_employee_id IS NULL OR p_effective_month IS NULL OR p_kind IS NULL
    OR p_kind NOT IN ('bonus', 'taxable_allowance', 'tax_exempt_allowance', 'advance', 'deduction')
    OR p_amount IS NULL OR p_amount <= 0 OR p_amount > 1000000000
    OR (p_note IS NOT NULL AND char_length(p_note) > 500) THEN
    RAISE EXCEPTION 'upsert_payroll_adjustment: invalid input'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = p_employee_id
      AND e.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'upsert_payroll_adjustment: employee not found'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF p_adjustment_id IS NOT NULL THEN
    SELECT * INTO v_adjustment
    FROM public.payroll_adjustments pa
    WHERE pa.id = p_adjustment_id
      AND pa.tenant_id = v_tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'upsert_payroll_adjustment: adjustment not found'
        USING ERRCODE = 'no_data_found';
    END IF;
    v_existing := true;
    v_prior := jsonb_build_object(
      'employee_id', v_adjustment.employee_id,
      'effective_month', v_adjustment.effective_month,
      'kind', v_adjustment.kind,
      'amount', v_adjustment.amount,
      'note', v_adjustment.note
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.payroll_periods pp
    WHERE pp.tenant_id = v_tenant_id
      AND pp.status IN ('approved', 'paid')
      AND (
        (pp.period_year = EXTRACT(YEAR FROM v_month)::integer
          AND pp.period_month = EXTRACT(MONTH FROM v_month)::integer)
        OR (v_existing
          AND pp.period_year = EXTRACT(YEAR FROM v_adjustment.effective_month)::integer
          AND pp.period_month = EXTRACT(MONTH FROM v_adjustment.effective_month)::integer)
      )
  ) THEN
    RAISE EXCEPTION 'upsert_payroll_adjustment: payroll snapshot locked'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_existing THEN
    UPDATE public.payroll_adjustments
    SET employee_id = p_employee_id,
        effective_month = v_month,
        kind = p_kind,
        amount = p_amount,
        note = NULLIF(btrim(p_note), ''),
        updated_at = now()
    WHERE id = v_adjustment.id
    RETURNING * INTO v_adjustment;
  ELSE
    INSERT INTO public.payroll_adjustments (
      tenant_id,
      employee_id,
      effective_month,
      kind,
      amount,
      note,
      created_by
    ) VALUES (
      v_tenant_id,
      p_employee_id,
      v_month,
      p_kind,
      p_amount,
      NULLIF(btrim(p_note), ''),
      v_user_id
    )
    RETURNING * INTO v_adjustment;
  END IF;

  PERFORM public.log_audit(
    CASE WHEN v_existing THEN 'update' ELSE 'create' END,
    'payroll_adjustment',
    v_adjustment.id,
    v_prior,
    jsonb_build_object(
      'employee_id', v_adjustment.employee_id,
      'effective_month', v_adjustment.effective_month,
      'kind', v_adjustment.kind,
      'amount', v_adjustment.amount,
      'note', v_adjustment.note
    )
  );

  RETURN v_adjustment.id;
END;
$$;


--
-- Name: upsert_payroll_calculation(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_payroll_calculation(p_period_id bigint, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_period RECORD;
  v_count INTEGER;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission_any('finance:payroll_calculate') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array' OR jsonb_array_length(p_entries) = 0 THEN
    RAISE EXCEPTION 'invalid_payroll_entries' USING ERRCODE = '22023';
  END IF;

  SELECT pp.id, pp.status INTO v_period
  FROM public.payroll_periods pp
  WHERE pp.id = p_period_id AND pp.tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'payroll_period_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_period.status NOT IN ('draft', 'calculated') THEN
    RAISE EXCEPTION 'payroll_locked' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.payroll_entries pe
  WHERE pe.payroll_period_id = p_period_id
    AND pe.tenant_id = v_tenant
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_entries) x
      WHERE (x->>'employee_id')::bigint = pe.employee_id
    );

  INSERT INTO public.payroll_entries (
    tenant_id, payroll_period_id, employee_id,
    working_days, paid_leave_days, unpaid_leave_days, payable_days,
    standard_days, overtime_hours, base_salary, allowances,
    tax_exempt_allowances, overtime_pay, bonus, gross_total,
    bhxh_employee, bhyt_employee, bhtn_employee, total_insurance_employee,
    bhxh_employer, bhyt_employer, bhtn_employer, total_insurance_employer,
    personal_deduction, dependent_count, dependent_deduction, charity_deduction,
    taxable_income, pit_tax, advance_deduction, other_deductions, net_salary, insurance_base
  )
  SELECT
    v_tenant, p_period_id, x.employee_id,
    x.working_days, x.paid_leave_days, x.unpaid_leave_days, x.payable_days,
    x.standard_days, x.overtime_hours, x.base_salary, x.allowances,
    x.tax_exempt_allowances, x.overtime_pay, x.bonus, x.gross_total,
    x.bhxh_employee, x.bhyt_employee, x.bhtn_employee, x.total_insurance_employee,
    x.bhxh_employer, x.bhyt_employer, x.bhtn_employer, x.total_insurance_employer,
    x.personal_deduction, x.dependent_count, x.dependent_deduction, x.charity_deduction,
    x.taxable_income, x.pit_tax, x.advance_deduction, x.other_deductions, x.net_salary, x.insurance_base
  FROM jsonb_to_recordset(p_entries) AS x(
    employee_id bigint,
    working_days numeric, paid_leave_days numeric, unpaid_leave_days numeric, payable_days numeric,
    standard_days numeric, overtime_hours numeric,
    base_salary numeric, allowances numeric, tax_exempt_allowances numeric,
    overtime_pay numeric, bonus numeric, gross_total numeric,
    bhxh_employee numeric, bhyt_employee numeric, bhtn_employee numeric, total_insurance_employee numeric,
    bhxh_employer numeric, bhyt_employer numeric, bhtn_employer numeric, total_insurance_employer numeric,
    personal_deduction numeric, dependent_count integer, dependent_deduction numeric, charity_deduction numeric,
    taxable_income numeric, pit_tax numeric, advance_deduction numeric, other_deductions numeric,
    net_salary numeric, insurance_base numeric
  )
  ON CONFLICT (payroll_period_id, employee_id, tenant_id) DO UPDATE SET
    working_days = EXCLUDED.working_days,
    paid_leave_days = EXCLUDED.paid_leave_days,
    unpaid_leave_days = EXCLUDED.unpaid_leave_days,
    payable_days = EXCLUDED.payable_days,
    standard_days = EXCLUDED.standard_days,
    overtime_hours = EXCLUDED.overtime_hours,
    base_salary = EXCLUDED.base_salary,
    allowances = EXCLUDED.allowances,
    tax_exempt_allowances = EXCLUDED.tax_exempt_allowances,
    overtime_pay = EXCLUDED.overtime_pay,
    bonus = EXCLUDED.bonus,
    gross_total = EXCLUDED.gross_total,
    bhxh_employee = EXCLUDED.bhxh_employee,
    bhyt_employee = EXCLUDED.bhyt_employee,
    bhtn_employee = EXCLUDED.bhtn_employee,
    total_insurance_employee = EXCLUDED.total_insurance_employee,
    bhxh_employer = EXCLUDED.bhxh_employer,
    bhyt_employer = EXCLUDED.bhyt_employer,
    bhtn_employer = EXCLUDED.bhtn_employer,
    total_insurance_employer = EXCLUDED.total_insurance_employer,
    personal_deduction = EXCLUDED.personal_deduction,
    dependent_count = EXCLUDED.dependent_count,
    dependent_deduction = EXCLUDED.dependent_deduction,
    charity_deduction = EXCLUDED.charity_deduction,
    taxable_income = EXCLUDED.taxable_income,
    pit_tax = EXCLUDED.pit_tax,
    advance_deduction = EXCLUDED.advance_deduction,
    other_deductions = EXCLUDED.other_deductions,
    net_salary = EXCLUDED.net_salary,
    insurance_base = EXCLUDED.insurance_base,
    updated_at = now();

  GET DIAGNOSTICS v_count = ROW_COUNT;

  UPDATE public.payroll_periods
  SET status = 'calculated'
  WHERE id = p_period_id AND tenant_id = v_tenant;

  RETURN jsonb_build_object('employee_count', v_count, 'status', 'calculated');
END;
$$;


--
-- Name: upsert_position_shift_tasks(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_position_shift_tasks(p_position_id bigint, p_tasks jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id bigint := public.auth_tenant_id();
  v_tasks jsonb := COALESCE(p_tasks, '[]'::jsonb);
  v_item jsonb;
  v_title text;
  v_kind text;
  v_appl text;
  v_phase text;
  v_done text;
  v_req boolean;
  v_sort integer := 0;
  v_task_id bigint;
  v_ingredient_ids jsonb;
  v_ingredient_value text;
  v_ingredient_id bigint;
  v_ingredient_sort integer;
BEGIN
  IF NOT (SELECT public.has_permission_any('staff:manage')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.positions
    WHERE id = p_position_id
      AND tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'position_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF jsonb_typeof(v_tasks) <> 'array' THEN
    RAISE EXCEPTION 'tasks_invalid' USING ERRCODE = '23514';
  END IF;

  IF jsonb_array_length(v_tasks) > 40 THEN
    RAISE EXCEPTION 'too_many_tasks' USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.position_shift_tasks
  WHERE tenant_id = v_tenant_id
    AND position_id = p_position_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_tasks) LOOP
    v_title := btrim(COALESCE(v_item->>'title', ''));
    v_kind := COALESCE(NULLIF(v_item->>'kind', ''), 'standard');
    v_appl := COALESCE(NULLIF(v_item->>'applicability', ''), 'every_shift');
    v_phase := COALESCE(NULLIF(v_item->>'phase', ''), 'start_of_shift');
    v_done := btrim(COALESCE(v_item->>'doneDefinition', ''));
    v_req := COALESCE(NULLIF(v_item->>'isRequired', '')::boolean, true);

    IF v_title = '' THEN
      CONTINUE;
    END IF;

    IF char_length(v_title) > 120 THEN
      RAISE EXCEPTION 'task_title_too_long' USING ERRCODE = '23514';
    END IF;
    IF v_kind <> ALL (ARRAY['standard', 'consumption_report']::text[]) THEN
      RAISE EXCEPTION 'task_kind_invalid' USING ERRCODE = '23514';
    END IF;
    IF v_appl <> ALL (ARRAY['every_shift', 'opening', 'closing']::text[]) THEN
      RAISE EXCEPTION 'task_applicability_invalid' USING ERRCODE = '23514';
    END IF;
    IF v_phase <> ALL (ARRAY['start_of_shift', 'end_of_shift']::text[]) THEN
      RAISE EXCEPTION 'task_phase_invalid' USING ERRCODE = '23514';
    END IF;
    IF char_length(v_done) > 240 THEN
      RAISE EXCEPTION 'done_definition_too_long' USING ERRCODE = '23514';
    END IF;

    v_sort := v_sort + 1;

    INSERT INTO public.position_shift_tasks (
      tenant_id,
      position_id,
      title,
      kind,
      applicability,
      phase,
      is_required,
      done_definition,
      sort_order
    ) VALUES (
      v_tenant_id,
      p_position_id,
      v_title,
      v_kind,
      v_appl,
      v_phase,
      v_req,
      v_done,
      v_sort
    )
    RETURNING id INTO v_task_id;

    IF v_kind = 'consumption_report' THEN
      v_ingredient_ids := COALESCE(v_item->'ingredientIds', '[]'::jsonb);
      IF jsonb_typeof(v_ingredient_ids) <> 'array' THEN
        RAISE EXCEPTION 'ingredients_invalid' USING ERRCODE = '23514';
      END IF;
      IF jsonb_array_length(v_ingredient_ids) > 80 THEN
        RAISE EXCEPTION 'too_many_ingredients' USING ERRCODE = '23514';
      END IF;

      v_ingredient_sort := 0;
      FOR v_ingredient_value IN SELECT value FROM jsonb_array_elements_text(v_ingredient_ids) LOOP
        v_ingredient_id := v_ingredient_value::bigint;
        IF NOT EXISTS (
          SELECT 1
          FROM public.ingredients
          WHERE id = v_ingredient_id
            AND tenant_id = v_tenant_id
            AND is_active = true
        ) THEN
          RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
        END IF;

        v_ingredient_sort := v_ingredient_sort + 1;
        INSERT INTO public.shift_checklist_consumption_default_items (
          tenant_id,
          template_item_id,
          position_task_id,
          ingredient_id,
          sort_order
        ) VALUES (
          v_tenant_id,
          NULL,
          v_task_id,
          v_ingredient_id,
          v_ingredient_sort
        );
      END LOOP;
    END IF;
  END LOOP;

  RETURN p_position_id;
END;
$$;


--
-- Name: upsert_printer_with_routes(bigint, bigint, text, text, text, integer, smallint, text, boolean, text[], bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_printer_with_routes(p_printer_id bigint DEFAULT NULL::bigint, p_branch_id bigint DEFAULT NULL::bigint, p_role text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_lan_host text DEFAULT NULL::text, p_lan_port integer DEFAULT NULL::integer, p_paper_width_mm smallint DEFAULT 80, p_code_page text DEFAULT 'CP1258'::text, p_is_active boolean DEFAULT true, p_print_types text[] DEFAULT ARRAY[]::text[], p_category_ids bigint[] DEFAULT ARRAY[]::bigint[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_tenant_id BIGINT;
  v_claim_branch_id BIGINT;
  v_existing RECORD;
  v_printer_id BIGINT;
  v_print_type TEXT;
  v_category_id BIGINT;
  v_role TEXT;
  v_sort_order INT;
  v_allowed_print_types TEXT[] := ARRAY[
    'receipt',
    'provisional_bill',
    'shift_close_report',
    'kitchen_ticket',
    'cancel_ticket'
  ];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  v_tenant_id := public.auth_tenant_id();
  v_claim_branch_id := public.auth_branch_id();

  IF p_branch_id IS NULL OR p_name IS NULL THEN
    RAISE EXCEPTION 'invalid_printer_payload' USING ERRCODE = '22023';
  END IF;

  IF v_claim_branch_id IS NOT NULL AND v_claim_branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'printer:manage') THEN
    RAISE EXCEPTION 'permission denied: printer:manage' USING ERRCODE = '42501';
  END IF;

  v_role := COALESCE(NULLIF(trim(COALESCE(p_role, '')), ''), 'custom');

  PERFORM 1
  FROM public.branches
  WHERE id = p_branch_id
    AND tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

IF NULLIF(trim(COALESCE(p_lan_host, '')), '') IS NULL THEN
    RAISE EXCEPTION 'lan host required' USING ERRCODE = '22023';
  END IF;

  IF p_paper_width_mm NOT IN (58, 80) THEN
    RAISE EXCEPTION 'invalid paper width' USING ERRCODE = '22023';
  END IF;

  FOREACH v_print_type IN ARRAY COALESCE(p_print_types, ARRAY[]::TEXT[])
  LOOP
    IF NOT v_print_type = ANY(v_allowed_print_types) THEN
      RAISE EXCEPTION 'invalid print type: %', v_print_type USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOREACH v_category_id IN ARRAY COALESCE(p_category_ids, ARRAY[]::BIGINT[])
  LOOP
    PERFORM 1
    FROM public.menu_categories
    WHERE id = v_category_id
      AND tenant_id = v_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'category not found: %', v_category_id USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  IF p_printer_id IS NOT NULL THEN
    SELECT id, branch_id, role
    INTO v_existing
    FROM public.printers
    WHERE id = p_printer_id
      AND tenant_id = v_tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'printer not found' USING ERRCODE = 'P0002';
    END IF;

    IF v_existing.branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'cannot move printer across branches' USING ERRCODE = '22023';
    END IF;

    UPDATE public.printers
       SET role = v_role,
           name = trim(p_name),
           connection_type = 'lan',
           lan_host = trim(p_lan_host),
           lan_port = COALESCE(p_lan_port, 9100),
           paper_width_mm = p_paper_width_mm,
           code_page = COALESCE(NULLIF(trim(p_code_page), ''), 'CP1258'),
           is_active = COALESCE(p_is_active, TRUE)
     WHERE id = p_printer_id
       AND tenant_id = v_tenant_id
     RETURNING id INTO v_printer_id;
  ELSE
    SELECT COALESCE(MAX(sort_order), -1) + 1
      INTO v_sort_order
      FROM public.printers
     WHERE tenant_id = v_tenant_id
       AND branch_id = p_branch_id;

    INSERT INTO public.printers (
      tenant_id,
      branch_id,
      role,
      name,
      sort_order,
      connection_type,
      lan_host,
      lan_port,
      paper_width_mm,
      code_page,
      is_active
    ) VALUES (
      v_tenant_id,
      p_branch_id,
      v_role,
      trim(p_name),
      v_sort_order,
      'lan',
      trim(p_lan_host),
      COALESCE(p_lan_port, 9100),
      p_paper_width_mm,
      COALESCE(NULLIF(trim(p_code_page), ''), 'CP1258'),
      COALESCE(p_is_active, TRUE)
    )
    RETURNING id INTO v_printer_id;
  END IF;

  DELETE FROM public.printer_print_types ppt
  WHERE ppt.tenant_id = v_tenant_id
    AND ppt.branch_id = p_branch_id
    AND ppt.printer_id <> v_printer_id
    AND ppt.print_type = ANY(COALESCE(p_print_types, ARRAY[]::TEXT[]))
    AND ppt.print_type IN ('receipt', 'provisional_bill', 'shift_close_report');

  DELETE FROM public.printer_print_types
  WHERE tenant_id = v_tenant_id
    AND branch_id = p_branch_id
    AND printer_id = v_printer_id;

  INSERT INTO public.printer_print_types (tenant_id, branch_id, printer_id, print_type)
  SELECT v_tenant_id, p_branch_id, v_printer_id, unnest(COALESCE(p_print_types, ARRAY[]::TEXT[]))
  ON CONFLICT (tenant_id, branch_id, printer_id, print_type) DO NOTHING;

  DELETE FROM public.printer_menu_categories
  WHERE tenant_id = v_tenant_id
    AND branch_id = p_branch_id
    AND printer_id = v_printer_id;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    DELETE FROM public.printer_menu_categories
    WHERE tenant_id = v_tenant_id
      AND branch_id = p_branch_id
      AND category_id = ANY(p_category_ids);

    INSERT INTO public.printer_menu_categories (
      tenant_id,
      branch_id,
      printer_id,
      category_id
    )
    SELECT DISTINCT v_tenant_id, p_branch_id, v_printer_id, x.category_id
    FROM unnest(p_category_ids) AS x(category_id)
    ON CONFLICT (tenant_id, branch_id, category_id) DO UPDATE
      SET printer_id = EXCLUDED.printer_id;
  END IF;

  RETURN v_printer_id;
END;
$$;


--
-- Name: FUNCTION upsert_printer_with_routes(p_printer_id bigint, p_branch_id bigint, p_role text, p_name text, p_lan_host text, p_lan_port integer, p_paper_width_mm smallint, p_code_page text, p_is_active boolean, p_print_types text[], p_category_ids bigint[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_printer_with_routes(p_printer_id bigint, p_branch_id bigint, p_role text, p_name text, p_lan_host text, p_lan_port integer, p_paper_width_mm smallint, p_code_page text, p_is_active boolean, p_print_types text[], p_category_ids bigint[]) IS 'Upsert a branch printer (LAN-only) and its print-type/category routes. Printer role is a slot label only; routing choices are not role-restricted.';


--
-- Name: upsert_production_recipe_lines(bigint, jsonb, numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_production_recipe_lines(p_finished_good_id bigint, p_lines jsonb, p_output_quantity numeric, p_old_finished_good_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
  PERFORM auth.role();
  RAISE EXCEPTION 'production_maintenance_legacy_rpc' USING ERRCODE = '55000';
END; $$;


--
-- Name: upsert_production_recipe_lines(bigint, numeric, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_production_recipe_lines(p_finished_good_id bigint, p_output_quantity numeric, p_output_unit_id bigint, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant bigint := public.auth_tenant_id();
  v_uid uuid := auth.uid();
  v_spec_id bigint;
  v_output_factor numeric(18,12);
  v_output_code text;
  v_line jsonb;
  v_ingredient_id bigint;
  v_quantity numeric;
  v_entry_unit_id bigint;
  v_entry_factor numeric(18,12);
  v_entry_code text;
  v_kept bigint[] := ARRAY[]::bigint[];
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator()
     OR NOT (
       public.has_permission_any('inventory:production_create')
       OR public.has_permission_any('inventory:production_confirm')
       OR public.has_permission_any('menu:write')
     ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_output_quantity IS NULL
     OR p_output_quantity <= 0
     OR p_output_quantity IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) THEN
    RAISE EXCEPTION 'output_quantity_invalid' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'invalid_group_shape' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.ingredients AS finished_good
    WHERE finished_good.tenant_id = v_tenant
      AND finished_good.id = p_finished_good_id
      AND finished_good.item_kind = 'finished_good'
      AND finished_good.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'finished_good_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT ingredient_unit.to_base_factor, unit_row.code
  INTO v_output_factor, v_output_code
  FROM public.ingredient_units AS ingredient_unit
  JOIN public.units AS unit_row
    ON unit_row.id = ingredient_unit.unit_id
   AND unit_row.tenant_id = ingredient_unit.tenant_id
   AND unit_row.is_active IS TRUE
  WHERE ingredient_unit.tenant_id = v_tenant
    AND ingredient_unit.ingredient_id = p_finished_good_id
    AND ingredient_unit.unit_id = p_output_unit_id
    AND ingredient_unit.is_active IS TRUE;

  IF v_output_factor IS NULL OR v_output_factor <= 0 THEN
    RAISE EXCEPTION 'output_unit_invalid' USING ERRCODE = '23514';
  END IF;

  IF (
    SELECT count(*) <> count(DISTINCT (line.value ->> 'ingredientId'))
    FROM jsonb_array_elements(p_lines) AS line(value)
  ) THEN
    RAISE EXCEPTION 'duplicate_ingredient' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.production_recipe_specs (
    tenant_id, finished_good_id, output_quantity, output_unit_id,
    output_to_base_factor, output_unit_code, status, created_by
  ) VALUES (
    v_tenant, p_finished_good_id, p_output_quantity, p_output_unit_id,
    v_output_factor, v_output_code, 'active', v_uid
  )
  ON CONFLICT (tenant_id, finished_good_id) DO UPDATE SET
    output_quantity = EXCLUDED.output_quantity,
    output_unit_id = EXCLUDED.output_unit_id,
    output_to_base_factor = EXCLUDED.output_to_base_factor,
    output_unit_code = EXCLUDED.output_unit_code,
    status = 'active',
    updated_at = now()
  RETURNING id INTO v_spec_id;

  FOR v_line IN
    SELECT line.value FROM jsonb_array_elements(p_lines) AS line(value)
  LOOP
    BEGIN
      v_ingredient_id := nullif(v_line ->> 'ingredientId', '')::bigint;
      v_quantity := nullif(v_line ->> 'quantity', '')::numeric;
      v_entry_unit_id := nullif(v_line ->> 'entryUnitId', '')::bigint;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'recipe_line_invalid' USING ERRCODE = '22023';
    END;

    IF v_ingredient_id IS NULL OR v_entry_unit_id IS NULL
       OR v_quantity IS NULL OR v_quantity <= 0
       OR v_quantity IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) THEN
      RAISE EXCEPTION 'recipe_line_invalid' USING ERRCODE = '22023';
    END IF;
    IF v_ingredient_id = p_finished_good_id THEN
      RAISE EXCEPTION 'recipe_self_reference' USING ERRCODE = '23514';
    END IF;

    SELECT ingredient_unit.to_base_factor, unit_row.code
    INTO v_entry_factor, v_entry_code
    FROM public.ingredients AS ingredient
    JOIN public.ingredient_units AS ingredient_unit
      ON ingredient_unit.tenant_id = ingredient.tenant_id
     AND ingredient_unit.ingredient_id = ingredient.id
     AND ingredient_unit.unit_id = v_entry_unit_id
     AND ingredient_unit.is_active IS TRUE
    JOIN public.units AS unit_row
      ON unit_row.id = ingredient_unit.unit_id
     AND unit_row.tenant_id = ingredient_unit.tenant_id
     AND unit_row.is_active IS TRUE
    WHERE ingredient.tenant_id = v_tenant
      AND ingredient.id = v_ingredient_id
      AND ingredient.item_kind = 'raw_material'
      AND ingredient.is_active IS TRUE;

    IF v_entry_factor IS NULL OR v_entry_factor <= 0 THEN
      RAISE EXCEPTION 'ingredient_unit_invalid' USING ERRCODE = '23514';
    END IF;

    INSERT INTO public.production_recipes (
      tenant_id, recipe_spec_id, finished_good_id, ingredient_id,
      quantity, entry_unit_id, entry_to_base_factor, entry_unit_code,
      output_quantity, note
    ) VALUES (
      v_tenant, v_spec_id, p_finished_good_id, v_ingredient_id,
      v_quantity, v_entry_unit_id, v_entry_factor, v_entry_code,
      p_output_quantity, nullif(pg_catalog.btrim(v_line ->> 'note'), '')
    )
    ON CONFLICT (finished_good_id, ingredient_id, tenant_id) DO UPDATE SET
      recipe_spec_id = EXCLUDED.recipe_spec_id,
      quantity = EXCLUDED.quantity,
      entry_unit_id = EXCLUDED.entry_unit_id,
      entry_to_base_factor = EXCLUDED.entry_to_base_factor,
      entry_unit_code = EXCLUDED.entry_unit_code,
      output_quantity = EXCLUDED.output_quantity,
      note = EXCLUDED.note,
      updated_at = now();

    v_kept := v_kept || v_ingredient_id;
  END LOOP;

  DELETE FROM public.production_recipes AS recipe
  WHERE recipe.tenant_id = v_tenant
    AND recipe.recipe_spec_id = v_spec_id
    AND NOT (recipe.ingredient_id = ANY(v_kept));

  RETURN jsonb_build_object(
    'recipe_spec_id', v_spec_id,
    'finished_good_id', p_finished_good_id,
    'status', 'active',
    'line_count', array_length(v_kept, 1)
  );
END;
$$;


--
-- Name: upsert_recipe_lines(bigint, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_recipe_lines(p_menu_item_id bigint, p_lines jsonb, p_old_menu_item_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_kept bigint[] := ARRAY[]::bigint[];
  v_line jsonb;
  v_ingredient_id bigint;
  v_entry_unit_id bigint;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '28000';
  END IF;
  IF public.auth_role() <> 'owner' THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501';
  END IF;
  IF NOT (
    public.has_permission_any('inventory:write')
    OR public.has_permission_any('menu:write')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.menu_items AS menu_item
    WHERE menu_item.id = p_menu_item_id
      AND menu_item.tenant_id = v_tenant
  ) THEN
    RAISE EXCEPTION 'menu_item_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'lines_must_be_array'
      USING ERRCODE = '22023';
  END IF;

  IF p_old_menu_item_id IS NOT NULL
     AND p_old_menu_item_id <> p_menu_item_id THEN
    DELETE FROM public.recipes AS recipe
    WHERE recipe.tenant_id = v_tenant
      AND recipe.menu_item_id = p_old_menu_item_id;
  END IF;

  FOR v_line IN
    SELECT value
    FROM jsonb_array_elements(p_lines)
  LOOP
    IF (v_line ->> 'ingredient_id') IS NULL
       OR (v_line ->> 'quantity') IS NULL THEN
      RAISE EXCEPTION 'invalid_line_shape'
        USING ERRCODE = '22023';
    END IF;

    v_ingredient_id := (v_line ->> 'ingredient_id')::bigint;
    v_entry_unit_id :=
      nullif(v_line ->> 'entry_unit_id', '')::bigint;

    PERFORM public.inventory_entry_unit_code(
      v_tenant,
      v_ingredient_id,
      v_entry_unit_id
    );

    INSERT INTO public.recipes (
      tenant_id,
      menu_item_id,
      ingredient_id,
      quantity,
      entry_unit_id,
      note,
      yield_factor
    )
    VALUES (
      v_tenant,
      p_menu_item_id,
      v_ingredient_id,
      (v_line ->> 'quantity')::numeric,
      v_entry_unit_id,
      nullif(v_line ->> 'note', ''),
      coalesce(
        nullif(v_line ->> 'yield_factor', '')::numeric,
        1.000
      )
    )
    ON CONFLICT (menu_item_id, ingredient_id, tenant_id)
    DO UPDATE SET
      quantity = excluded.quantity,
      entry_unit_id = excluded.entry_unit_id,
      note = excluded.note,
      yield_factor = excluded.yield_factor;

    v_kept := v_kept || v_ingredient_id;
  END LOOP;

  DELETE FROM public.recipes AS recipe
  WHERE recipe.tenant_id = v_tenant
    AND recipe.menu_item_id = p_menu_item_id
    AND NOT (recipe.ingredient_id = ANY(v_kept));

  RETURN jsonb_build_object(
    'menu_item_id',
    p_menu_item_id,
    'kept_count',
    coalesce(array_length(v_kept, 1), 0)
  );
END;
$$;


--
-- Name: FUNCTION upsert_recipe_lines(p_menu_item_id bigint, p_lines jsonb, p_old_menu_item_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_recipe_lines(p_menu_item_id bigint, p_lines jsonb, p_old_menu_item_id bigint) IS 'Atomically replace the recipe lines of a menu item. Inserts or updates provided lines, clears old menu item recipe if changed, and deletes removed lines.';


--
-- Name: upsert_shift_checklist_template(bigint, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_shift_checklist_template(p_tenant_id bigint, p_branch_id bigint, p_template_id bigint, p_name text, p_items jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_template_id bigint;
  v_items jsonb := COALESCE(p_items, '[]'::jsonb);
  v_item jsonb;
  v_title text;
  v_phase text;
  v_done_definition text;
  v_is_required boolean;
  v_scope text;
  v_task_kind text;
  v_sort integer := 0;
  v_name text := btrim(COALESCE(p_name, ''));
BEGIN
  IF v_name = '' THEN
    RAISE EXCEPTION 'template_name_required' USING ERRCODE = '23514';
  END IF;

  IF char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'template_name_too_long' USING ERRCODE = '23514';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = p_tenant_id
      AND COALESCE(b.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF jsonb_typeof(v_items) <> 'array' THEN
    RAISE EXCEPTION 'checklist_items_invalid' USING ERRCODE = '23514';
  END IF;

  IF jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'checklist_empty' USING ERRCODE = '23514';
  END IF;

  IF jsonb_array_length(v_items) > 40 THEN
    RAISE EXCEPTION 'checklist_too_many_items' USING ERRCODE = '23514';
  END IF;

  IF p_template_id IS NULL THEN
    INSERT INTO public.shift_checklist_templates (
      tenant_id,
      branch_id,
      name,
      is_active
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      v_name,
      true
    )
    RETURNING id INTO v_template_id;
  ELSE
    SELECT id
    INTO v_template_id
    FROM public.shift_checklist_templates
    WHERE id = p_template_id
      AND tenant_id = p_tenant_id
      AND branch_id IS NOT DISTINCT FROM p_branch_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'template_not_found' USING ERRCODE = 'P0002';
    END IF;

    UPDATE public.shift_checklist_templates
    SET name = v_name,
        is_active = true
    WHERE id = v_template_id;
  END IF;

  DELETE FROM public.shift_checklist_template_items
  WHERE tenant_id = p_tenant_id
    AND template_id = v_template_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_title := btrim(COALESCE(v_item ->> 'title', ''));
    v_phase := COALESCE(NULLIF(v_item ->> 'phase', ''), 'during_shift');
    v_done_definition := btrim(
      COALESCE(
        v_item ->> 'doneDefinition',
        v_item ->> 'done_definition',
        ''
      )
    );
    v_is_required := COALESCE(
      NULLIF(v_item ->> 'isRequired', '')::boolean,
      NULLIF(v_item ->> 'is_required', '')::boolean,
      true
    );
    v_scope := COALESCE(NULLIF(v_item ->> 'scope', ''), 'every_shift');
    v_task_kind := COALESCE(NULLIF(v_item ->> 'taskKind', ''), 'standard');

    IF v_title = '' THEN
      CONTINUE;
    END IF;

    IF char_length(v_title) > 120 THEN
      RAISE EXCEPTION 'checklist_item_too_long' USING ERRCODE = '23514';
    END IF;

    IF v_phase <> ALL (ARRAY['start_of_shift', 'during_shift', 'end_of_shift']::text[]) THEN
      RAISE EXCEPTION 'checklist_phase_invalid' USING ERRCODE = '23514';
    END IF;

    IF v_scope <> ALL (ARRAY['every_shift', 'opening', 'closing', 'weekly']::text[]) THEN
      RAISE EXCEPTION 'checklist_scope_invalid' USING ERRCODE = '23514';
    END IF;

    IF v_task_kind <> ALL (ARRAY['standard', 'consumption_report']::text[]) THEN
      RAISE EXCEPTION 'checklist_task_kind_invalid' USING ERRCODE = '23514';
    END IF;

    IF char_length(v_done_definition) > 240 THEN
      RAISE EXCEPTION 'done_definition_too_long' USING ERRCODE = '23514';
    END IF;

    v_sort := v_sort + 1;

    INSERT INTO public.shift_checklist_template_items (
      tenant_id,
      template_id,
      title,
      phase,
      done_definition,
      is_required,
      scope,
      task_kind,
      sort_order,
      is_active
    )
    VALUES (
      p_tenant_id,
      v_template_id,
      v_title,
      v_phase,
      v_done_definition,
      v_is_required,
      v_scope,
      v_task_kind,
      v_sort,
      true
    );
  END LOOP;

  IF v_sort = 0 THEN
    RAISE EXCEPTION 'checklist_empty' USING ERRCODE = '23514';
  END IF;

  RETURN v_template_id;
END;
$$;


--
-- Name: FUNCTION upsert_shift_checklist_template(p_tenant_id bigint, p_branch_id bigint, p_template_id bigint, p_name text, p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_shift_checklist_template(p_tenant_id bigint, p_branch_id bigint, p_template_id bigint, p_name text, p_items jsonb) IS 'Service-role-only atomic checklist template save. Payload includes item title, phase, done definition, and required flag.';


--
-- Name: upsert_station_with_categories(bigint, bigint, text, integer, boolean, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_station_with_categories(p_station_id bigint DEFAULT NULL::bigint, p_branch_id bigint DEFAULT NULL::bigint, p_name text DEFAULT NULL::text, p_position integer DEFAULT 0, p_is_active boolean DEFAULT true, p_category_ids bigint[] DEFAULT ARRAY[]::bigint[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             uuid    := auth.uid();
  v_tenant_id       bigint  := public.auth_tenant_id();
  v_claim_branch_id bigint  := public.auth_branch_id();
  v_existing        RECORD;
  v_station_id      bigint;
  v_category_id     bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_branch_id IS NULL OR NULLIF(btrim(COALESCE(p_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_station_payload' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_position, 0) < 0 THEN
    RAISE EXCEPTION 'invalid_station_payload' USING ERRCODE = '22023';
  END IF;

  IF v_claim_branch_id IS NOT NULL AND v_claim_branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'branch_mismatch' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'settings:branch') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.branches WHERE id = p_branch_id AND tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  FOREACH v_category_id IN ARRAY COALESCE(p_category_ids, ARRAY[]::bigint[])
  LOOP
    PERFORM 1 FROM public.menu_categories
     WHERE id = v_category_id AND tenant_id = v_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'category_not_found' USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  IF p_station_id IS NOT NULL THEN
    SELECT id, branch_id INTO v_existing
      FROM public.kds_stations
     WHERE id = p_station_id AND tenant_id = v_tenant_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'station_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_existing.branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'cannot_move_station_across_branches' USING ERRCODE = '22023';
    END IF;

    UPDATE public.kds_stations
       SET name = btrim(p_name),
           position = COALESCE(p_position, 0),
           is_active = COALESCE(p_is_active, TRUE),
           updated_at = now()
     WHERE id = p_station_id AND tenant_id = v_tenant_id
     RETURNING id INTO v_station_id;
  ELSE
    INSERT INTO public.kds_stations (tenant_id, branch_id, name, position, is_active)
    VALUES (v_tenant_id, p_branch_id, btrim(p_name), COALESCE(p_position, 0), COALESCE(p_is_active, TRUE))
    RETURNING id INTO v_station_id;
  END IF;

  DELETE FROM public.kds_station_categories
   WHERE station_id = v_station_id AND tenant_id = v_tenant_id;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    INSERT INTO public.kds_station_categories (tenant_id, station_id, category_id)
    SELECT DISTINCT v_tenant_id, v_station_id, x.category_id
      FROM unnest(p_category_ids) AS x(category_id)
     WHERE x.category_id IS NOT NULL
    ON CONFLICT (station_id, category_id, tenant_id) DO NOTHING;
  END IF;

  RETURN v_station_id;
END;
$$;


--
-- Name: validate_refund_ledger_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_refund_ledger_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_refund_id bigint;
  v_current_payout_method text;
  v_current_event_id bigint;
  v_old_event_id bigint;
  v_new_event_id bigint;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_refund_id := OLD.id;
    v_old_event_id := OLD.webhook_event_id;
  ELSE
    v_refund_id := NEW.id;
    v_new_event_id := NEW.webhook_event_id;
    IF TG_OP = 'UPDATE' THEN
      v_old_event_id := OLD.webhook_event_id;
    END IF;
  END IF;

  SELECT refund.payout_method, refund.webhook_event_id
  INTO v_current_payout_method, v_current_event_id
  FROM public.refunds refund
  WHERE refund.id = v_refund_id;

  IF FOUND AND v_current_payout_method IS NULL THEN
    RAISE EXCEPTION 'refund_payout_method_required' USING ERRCODE = '23514';
  END IF;

  PERFORM public.assert_refund_webhook_allocation(v_current_event_id);
  IF v_old_event_id IS DISTINCT FROM v_current_event_id THEN
    PERFORM public.assert_refund_webhook_allocation(v_old_event_id);
  END IF;
  IF v_new_event_id IS DISTINCT FROM v_current_event_id THEN
    PERFORM public.assert_refund_webhook_allocation(v_new_event_id);
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_refund_webhook_event_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_refund_webhook_event_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.assert_refund_webhook_allocation(NEW.id);
  RETURN NEW;
END;
$$;


--
-- Name: verify_service_supplier_invoice(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_service_supplier_invoice(p_invoice_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_invoice public.supplier_invoices%ROWTYPE;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('procurement:invoice_match') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_reason IS NULL
     OR char_length(btrim(p_reason)) < 5
     OR char_length(btrim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'service_verification_reason_required'
      USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_invoice
  FROM public.supplier_invoices
  WHERE id = p_invoice_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_invoice.invoice_kind <> 'service'
     OR v_invoice.matching_status <> 'pending'
     OR EXISTS (
       SELECT 1
       FROM public.supplier_invoice_receipt_allocations allocation
       WHERE allocation.tenant_id = v_tenant
         AND allocation.supplier_invoice_id = p_invoice_id
     ) THEN
    RAISE EXCEPTION 'service_invoice_verification_invalid'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.supplier_invoices
  SET service_verified_by = v_uid,
      service_verified_at = pg_catalog.now(),
      service_verification_reason = btrim(p_reason),
      updated_at = pg_catalog.now()
  WHERE id = p_invoice_id
    AND tenant_id = v_tenant;

  v_result := private.apply_supplier_invoice_matching(p_invoice_id);

  PERFORM public.log_audit(
    'supplier_invoice.service_verified',
    'supplier_invoice',
    p_invoice_id,
    pg_catalog.jsonb_build_object(
      'matching_status', v_invoice.matching_status
    ),
    v_result || pg_catalog.jsonb_build_object(
      'reason', btrim(p_reason)
    )
  );

  RETURN v_result;
END;
$$;


--
-- Name: vietqr_payment_code_prefix(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vietqr_payment_code_prefix() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT COALESCE(
    (SELECT NULLIF(btrim(regexp_replace(upper(value), '[^A-Z0-9]+', ' ', 'g')), '')
       FROM public.system_settings
      WHERE key = 'payment_vietqr_code_prefix'
      ORDER BY tenant_id
      LIMIT 1),
    'QAJZRU5550 MBBMS01382716 1'
  );
$$;


--
-- Name: void_order_item(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_order_item(p_order_item_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_prof_tenant     BIGINT;
  v_prof_branch     BIGINT;
  v_prof_role       TEXT;
  v_item            RECORD;
  v_order           RECORD;
  v_subtotal        NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_all_cancelled   BOOLEAN;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'unassigned')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'cashier') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_item.status IN ('served', 'cancelled') THEN
    RAISE EXCEPTION 'item not voidable' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = p_reason,
      updated_at = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET status = 'cancelled', updated_at = now()
  WHERE order_item_id = p_order_item_id AND tenant_id = v_item.tenant_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  SELECT NOT EXISTS (
    SELECT 1 FROM public.order_items WHERE order_id = v_item.order_id AND status <> 'cancelled'
  ) INTO v_all_cancelled;

  IF v_all_cancelled THEN
    UPDATE public.orders
    SET
      status          = 'cancelled',
      subtotal        = 0,
      discount_type   = NULL,
      discount_value  = NULL,
      discount_note   = NULL,
      discount_amount = 0,
      total_amount    = 0 + COALESCE(service_charge, 0),
      updated_at      = now()
    WHERE id = v_item.order_id;

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_item.tenant_id, v_item.order_id, v_order.status, 'cancelled', v_uid,
      'auto_cancel_all_items_voided: ' || p_reason
    );
  ELSE
    v_discount_amount := public.compute_discount_amount(
      v_order.discount_type, v_order.discount_value, v_subtotal
    );

    UPDATE public.orders o
    SET
      subtotal        = v_subtotal,
      discount_type   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_type END,
      discount_value  = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_value END,
      discount_note   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_note END,
      discount_amount = v_discount_amount,
      total_amount    = v_subtotal + COALESCE(o.service_charge, 0) - v_discount_amount,
      updated_at      = now()
    WHERE o.id = v_item.order_id;

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
      'void_item ' || p_order_item_id::text || ': ' || p_reason
    );
  END IF;

  RETURN jsonb_build_object(
    'order_id', v_item.order_id,
    'auto_cancelled_order', v_all_cancelled,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


--
-- Name: weekly_waste_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_waste_report() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_week_end date := date_trunc(
    'week',
    now() AT TIME ZONE 'Asia/Ho_Chi_Minh'
  )::date;
  v_week_start date := v_week_end - 7;
  v_count integer := 0;
BEGIN
  WITH report AS (
    SELECT
      issue.tenant_id,
      issue.branch_id,
      branch.branch_kind,
      count(*) AS waste_count,
      count(*) FILTER (
        WHERE issue.approval_status = 'pending'
      ) AS pending_count,
      count(*) FILTER (
        WHERE issue.approval_status = 'approved'
      ) AS approved_count,
      count(*) FILTER (
        WHERE issue.approval_status = 'rejected'
      ) AS rejected_count
    FROM public.stock_issues AS issue
    JOIN public.branches AS branch
      ON branch.id = issue.branch_id
     AND branch.tenant_id = issue.tenant_id
    WHERE issue.issue_type = 'writeoff'
      AND issue.issued_at >= v_week_start AT TIME ZONE 'Asia/Ho_Chi_Minh'
      AND issue.issued_at < v_week_end AT TIME ZONE 'Asia/Ho_Chi_Minh'
    GROUP BY issue.tenant_id, issue.branch_id, branch.branch_kind
  ),
  upserted AS (
    INSERT INTO public.notifications (
      tenant_id,
      target_branch_id,
      target_roles,
      kind,
      severity,
      title,
      body,
      entity_type,
      entity_id,
      action_url,
      meta,
      dedup_key,
      expires_at
    )
    SELECT
      report.tenant_id,
      report.branch_id,
      CASE report.branch_kind
        WHEN 'central_supply'
          THEN ARRAY['owner', 'accountant', 'central_supply_ops']::text[]
        WHEN 'central_kitchen'
          THEN ARRAY['owner', 'accountant', 'central_kitchen_lead']::text[]
        ELSE ARRAY['owner', 'accountant', 'branch_manager']::text[]
      END,
      'inventory.waste.weekly_report',
      CASE WHEN report.pending_count >= 5 THEN 'warning' ELSE 'info' END,
      format(
        'Tổng hợp hao hụt %s–%s',
        to_char(v_week_start, 'DD/MM'),
        to_char(v_week_end - 1, 'DD/MM/YYYY')
      ),
      format(
        '%s phiếu; chờ duyệt %s, đã duyệt %s, đã từ chối %s.',
        report.waste_count,
        report.pending_count,
        report.approved_count,
        report.rejected_count
      ),
      'branch',
      report.branch_id,
      CASE
        WHEN report.branch_kind = 'branch'
          THEN format('/br/%s/stock/waste-approvals', report.branch_id)
        ELSE format(
          '/inventory/waste/approvals?branchId=%s',
          report.branch_id
        )
      END,
      jsonb_build_object(
        'week_start', v_week_start,
        'week_end', v_week_end - 1,
        'waste_count', report.waste_count,
        'pending_count', report.pending_count,
        'approved_count', report.approved_count,
        'rejected_count', report.rejected_count
      ),
      format(
        'inventory.waste.weekly_report:%s:%s',
        report.branch_id,
        to_char(v_week_start, 'IYYY-IW')
      ),
      now() + interval '14 days'
    FROM report
    ON CONFLICT (tenant_id, dedup_key)
      WHERE dedup_key IS NOT NULL
    DO UPDATE
    SET target_branch_id = EXCLUDED.target_branch_id,
        target_roles = EXCLUDED.target_roles,
        severity = EXCLUDED.severity,
        title = EXCLUDED.title,
        body = EXCLUDED.body,
        action_url = EXCLUDED.action_url,
        meta = EXCLUDED.meta,
        expires_at = EXCLUDED.expires_at
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM upserted;

  RETURN v_count;
END;
$$;


