--

CREATE TABLE public.expenses (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    branch_id bigint,
    expense_date date NOT NULL,
    category text NOT NULL,
    amount numeric(15,2) NOT NULL,
    payment_method text DEFAULT 'cash'::text NOT NULL,
    paid_at timestamp with time zone,
    vendor_name text,
    note text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    transfer_content text,
    vat_breakdown jsonb DEFAULT '[]'::jsonb NOT NULL,
    subtotal numeric(14,2) NOT NULL,
    vat_amount numeric(14,2) NOT NULL,
    invoice_attachment_url text,
    CONSTRAINT expenses_amount_positive_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT expenses_category_check CHECK ((category = ANY (ARRAY['rent'::text, 'utilities'::text, 'gas_fuel'::text, 'salary'::text, 'cogs_manual'::text, 'supplies'::text, 'repair'::text, 'marketing'::text, 'fees_tax'::text, 'hospitality'::text, 'bank_deposit'::text, 'other'::text]))),
    CONSTRAINT expenses_invoice_attachment_url_length_check CHECK (((invoice_attachment_url IS NULL) OR (char_length(invoice_attachment_url) <= 2048))),
    CONSTRAINT expenses_note_length_check CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT expenses_paid_at_unpaid_check CHECK (((payment_method <> 'unpaid'::text) OR (paid_at IS NULL))),
    CONSTRAINT expenses_payment_method_check CHECK ((payment_method = ANY (ARRAY['cash'::text, 'transfer'::text, 'unpaid'::text]))),
    CONSTRAINT expenses_transfer_content_shape_check CHECK (((transfer_content IS NULL) OR ((category <> 'bank_deposit'::text) AND (char_length(transfer_content) <= 64) AND (transfer_content ~ (('^[A-Z0-9]{2,16} [A-Z0-9]{2,16} '::text || (id)::text) || '$'::text)) AND (((payment_method = 'unpaid'::text) AND (paid_at IS NULL)) OR ((payment_method = 'transfer'::text) AND (paid_at IS NOT NULL)))))),
    CONSTRAINT expenses_vendor_name_length_check CHECK (((vendor_name IS NULL) OR (char_length(vendor_name) <= 200)))
);


