-- Name: grn_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.grn_items (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    grn_id bigint NOT NULL,
    ingredient_id bigint NOT NULL,
    received_quantity numeric(15,3) NOT NULL,
    unit_cost numeric(15,2) DEFAULT 0 NOT NULL,
    total_cost numeric(15,2) DEFAULT 0 NOT NULL,
    rejected_quantity numeric(15,3) DEFAULT 0 NOT NULL,
    rejection_reason text,
    rejected_photo_url text,
    entry_unit_id bigint,
    supplier_id bigint NOT NULL,
    purchase_order_item_id bigint,
    po_applied_quantity numeric(15,3) DEFAULT 0 NOT NULL,
    cost_pending boolean DEFAULT false NOT NULL,
    provisional_cost_source text,
    entry_to_base_factor numeric(18,12),
    entry_unit_code text,
    CONSTRAINT grn_items_po_applied_accepted CHECK ((po_applied_quantity <= (received_quantity - rejected_quantity))),
    CONSTRAINT grn_items_po_applied_non_negative CHECK ((po_applied_quantity >= (0)::numeric)),
    CONSTRAINT grn_items_provisional_cost_source_check CHECK (((provisional_cost_source IS NULL) OR (provisional_cost_source = ANY (ARRAY['wac'::text, 'reference'::text, 'pending'::text, 'invoice'::text])))),
    CONSTRAINT grn_items_received_quantity_check CHECK (((received_quantity <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (received_quantity >= (0)::numeric))),
    CONSTRAINT grn_items_rejected_le_received CHECK (((rejected_quantity <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (rejected_quantity >= (0)::numeric) AND (rejected_quantity <= received_quantity))),
    CONSTRAINT grn_items_total_cost_nonnegative CHECK (((total_cost <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (total_cost >= (0)::numeric))),
    CONSTRAINT grn_items_unit_cost_nonnegative CHECK (((unit_cost <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (unit_cost >= (0)::numeric)))
);


--
-- Name: COLUMN grn_items.received_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.grn_items.received_quantity IS 'Tổng số lượng nhà cung cấp đã giao (gross delivered). Stock impact = received − rejected. Số nhận tốt vào kho được tính bằng (received − rejected_quantity).';


--
-- Name: COLUMN grn_items.rejected_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.grn_items.rejected_quantity IS 'Số lượng (subset của received_quantity) bị từ chối + trả NCC. Bắt buộc ≤ received_quantity.';


--
-- Name: COLUMN grn_items.supplier_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.grn_items.supplier_id IS 'Supplier for this receipt line. Multi-supplier GRNs carry distinct suppliers per line; POs split by this column.';


--
-- Name: COLUMN grn_items.po_applied_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.grn_items.po_applied_quantity IS 'Accepted quantity from this receipt that fulfills the linked PO line. Accepted excess is the remainder and carries zero receipt value.';


