    yield_factor numeric(5,3) DEFAULT 1.000 NOT NULL,
    entry_unit_id bigint,
    CONSTRAINT recipes_quantity_valid CHECK (((quantity > (0)::numeric) AND (quantity <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])))),
    CONSTRAINT recipes_yield_factor_valid CHECK (((yield_factor > (0)::numeric) AND (yield_factor <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric]))))
);


