--
-- Name: mv_food_cost; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_food_cost AS
 WITH latest_grn_cost AS (
         SELECT DISTINCT ON (item.ingredient_id, item.tenant_id) item.ingredient_id,
            item.tenant_id,
            item.unit_cost
           FROM (public.grn_items item
             JOIN public.goods_received_notes grn ON ((grn.id = item.grn_id)))
          WHERE ((grn.status = 'confirmed'::text) AND ((item.received_quantity - item.rejected_quantity) > (0)::numeric))
          ORDER BY item.ingredient_id, item.tenant_id, grn.received_date DESC NULLS LAST
        ), recipe_cost AS (
         SELECT recipe.menu_item_id,
            recipe.tenant_id,
            sum((recipe.quantity * COALESCE(latest.unit_cost, ingredient.unit_cost, (0)::numeric))) AS cost_per_unit
           FROM ((public.recipes recipe
             JOIN public.ingredients ingredient ON ((ingredient.id = recipe.ingredient_id)))
             LEFT JOIN latest_grn_cost latest ON (((latest.ingredient_id = recipe.ingredient_id) AND (latest.tenant_id = recipe.tenant_id))))
          GROUP BY recipe.menu_item_id, recipe.tenant_id
        )
 SELECT (date_trunc('week'::text, orders.created_at))::date AS period_start,
    ((date_trunc('week'::text, orders.created_at) + '6 days'::interval))::date AS period_end,
    orders.branch_id,
    orders.tenant_id,
    order_item.menu_item_id,
    max(order_item.item_name) AS item_name,
    sum(order_item.quantity) AS quantity_sold,
    sum(order_item.subtotal) AS revenue,
    sum(((order_item.quantity)::numeric * COALESCE(recipe_cost.cost_per_unit, (0)::numeric))) AS ingredient_cost,
        CASE
            WHEN (sum(order_item.subtotal) > (0)::numeric) THEN round(((sum(((order_item.quantity)::numeric * COALESCE(recipe_cost.cost_per_unit, (0)::numeric))) / sum(order_item.subtotal)) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS food_cost_pct
   FROM ((public.order_items order_item
     JOIN public.orders orders ON ((orders.id = order_item.order_id)))
     LEFT JOIN recipe_cost ON (((recipe_cost.menu_item_id = order_item.menu_item_id) AND (recipe_cost.tenant_id = order_item.tenant_id))))
  WHERE ((orders.status <> 'cancelled'::text) AND (order_item.status <> 'cancelled'::text))
  GROUP BY ((date_trunc('week'::text, orders.created_at))::date), (((date_trunc('week'::text, orders.created_at) + '6 days'::interval))::date), orders.branch_id, orders.tenant_id, order_item.menu_item_id
  WITH NO DATA;


