    CONSTRAINT stock_levels_avg_unit_cost_valid CHECK (((avg_unit_cost IS NULL) OR ((avg_unit_cost >= (0)::numeric) AND (avg_unit_cost <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric]))))),
    CONSTRAINT stock_levels_current_quantity_valid CHECK (((current_quantity >= (0)::numeric) AND (current_quantity <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric]))))
);


