-- Name: mv_inventory_stock_current; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_inventory_stock_current AS
 SELECT stock.tenant_id,
    stock.branch_id,
    stock.location_id,
    location.name AS location_name,
    location.location_kind,
    stock.ingredient_id,
    ingredient.name AS ingredient_name,
    ingredient.category AS ingredient_category,
    ingredient.is_active AS ingredient_is_active,
    ingredient.item_kind,
    stock.current_quantity,
    stock.avg_unit_cost,
    ((stock.current_quantity * COALESCE(stock.avg_unit_cost, (0)::numeric)))::numeric(20,2) AS stock_value,
    ingredient.reorder_point,
    ingredient.min_stock_level,
    ingredient.max_stock_level,
    ingredient.shelf_life_days,
    stock.updated_at,
    stock.last_counted_at
   FROM ((public.stock_levels stock
     JOIN public.inventory_locations location ON ((location.id = stock.location_id)))
     JOIN public.ingredients ingredient ON ((ingredient.id = stock.ingredient_id)))
  WHERE ((location.is_active = true) AND (ingredient.is_active = true))
  WITH NO DATA;


--
-- Name: mv_inventory_value_ranking; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_inventory_value_ranking AS
 SELECT tenant_id,
    branch_id,
    ingredient_id,
    sum(stock_value) AS total_value
   FROM public.mv_inventory_stock_current stock
  GROUP BY tenant_id, branch_id, ingredient_id
  WITH NO DATA;


