--
-- Name: pos_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pos_sessions (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    branch_id bigint NOT NULL,
    terminal_id bigint,
    opened_by uuid NOT NULL,
    closed_by uuid,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    opening_cash numeric(15,2) DEFAULT 0 NOT NULL,
    closing_cash numeric(15,2),
    expected_cash numeric(15,2),
    cash_difference numeric(15,2),
    status text DEFAULT 'open'::text NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    variance_approval_note text,
    variance_approver_user_id uuid,
    variance_resolution_type text,
    variance_settlement_amount numeric(15,2),
    variance_resolved_at timestamp with time zone,
    CONSTRAINT pos_sessions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text]))),
    CONSTRAINT pos_sessions_variance_resolution_shape_check CHECK ((((variance_resolution_type IS NULL) AND (variance_settlement_amount IS NULL) AND (variance_resolved_at IS NULL)) OR ((variance_resolution_type IS NOT NULL) AND (variance_settlement_amount IS NOT NULL) AND (variance_settlement_amount >= (0)::numeric) AND (variance_resolved_at IS NOT NULL) AND (variance_approval_note IS NOT NULL) AND (variance_approver_user_id IS NOT NULL)))),
    CONSTRAINT pos_sessions_variance_resolution_type_check CHECK (((variance_resolution_type IS NULL) OR (variance_resolution_type = ANY (ARRAY['staff_repaid'::text, 'accepted_adjustment'::text]))))
);

ALTER TABLE ONLY public.pos_sessions REPLICA IDENTITY FULL;


--
-- Name: COLUMN pos_sessions.terminal_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pos_sessions.terminal_id IS 'OPTIONAL sau D7 (2026-04-27). Trước D7: NOT NULL FK pos_terminals — per-terminal model. Sau D7: nullable. NULL = ca chung của chi nhánh (không liên kết terminal vật lý cụ thể). Closed sessions từ trước D7 vẫn giữ terminal_id cho audit.';


--
-- Name: COLUMN pos_sessions.variance_approval_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pos_sessions.variance_approval_note IS 'Lý do duyệt chênh lệch cuối ca khi |cash_difference| > max(50k, 0.5% × expected_cash). NULL khi diff trong ngưỡng.';


--
-- Name: COLUMN pos_sessions.variance_approver_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pos_sessions.variance_approver_user_id IS 'User duyệt chênh lệch (auth.uid() tại close time, phải có pos:close_shift_variance_override). NULL khi diff trong ngưỡng.';


--
-- Name: COLUMN pos_sessions.variance_resolution_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pos_sessions.variance_resolution_type IS 'Structured resolution for an over-threshold cash variance: full staff repayment for a shortage, or an accepted cash-book adjustment.';


--
-- Name: COLUMN pos_sessions.variance_settlement_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pos_sessions.variance_settlement_amount IS 'Amount settled by the selected variance resolution. Full shortage amount for staff_repaid; zero for accepted_adjustment.';


--
-- Name: COLUMN pos_sessions.variance_resolved_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pos_sessions.variance_resolved_at IS 'Timestamp when an authorized manager resolved the variance.';


--
-- Name: CONSTRAINT pos_sessions_variance_resolution_shape_check ON pos_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT pos_sessions_variance_resolution_shape_check ON public.pos_sessions IS 'Structured variance resolution fields are written and cleared as one state; close-time cash counts and differences stay unchanged.';


