    webhook_event_id bigint,
    CONSTRAINT refunds_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT refunds_approved_shape_check CHECK (((status <> 'approved'::text) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT refunds_payout_method_check CHECK (((payout_method IS NULL) OR (payout_method = ANY (ARRAY['cash'::text, 'bank_transfer'::text])))),
    CONSTRAINT refunds_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT refunds_webhook_event_shape_check CHECK (((webhook_event_id IS NULL) OR ((status = 'approved'::text) AND (payout_method = 'bank_transfer'::text))))
);


