CREATE TABLE public.supplier_invoices (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    supplier_id bigint NOT NULL,
    grn_id bigint,
    po_id bigint,
    invoice_date timestamp with time zone NOT NULL,
    subtotal numeric(15,2) NOT NULL,
    vat_rate numeric(5,2),
    vat_amount numeric(15,2) NOT NULL,
    total_amount numeric(15,2) NOT NULL,
    matching_status text DEFAULT 'pending'::text NOT NULL,
    matching_notes text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    due_date date,
    payment_status text DEFAULT 'unpaid'::text NOT NULL,
    paid_amount numeric(15,2) DEFAULT 0 NOT NULL,
    paid_at timestamp with time zone,
    credit_applied_amount numeric(15,2) DEFAULT 0 NOT NULL,
    vat_breakdown jsonb DEFAULT '[]'::jsonb NOT NULL,
    vat_invoice_attachment_path text,
    document_discount_amount numeric(15,2) DEFAULT 0 NOT NULL,
    discrepancy_accepted_by uuid,
    discrepancy_accepted_at timestamp with time zone,
    discrepancy_reason text,
    invoice_kind text DEFAULT 'goods'::text NOT NULL,
    service_verified_by uuid,
    service_verified_at timestamp with time zone,
    service_verification_reason text,
    matching_expected_amount numeric(15,2),
    matching_received_amount numeric(15,2),
    matching_difference_amount numeric(15,2),
    matching_reason_code text,
    document_status text DEFAULT 'confirmed'::text NOT NULL,
    save_idempotency_key uuid,
    confirmed_at timestamp with time zone,
    confirmed_by uuid,
    CONSTRAINT supplier_invoices_credit_applied_amount_check CHECK ((credit_applied_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_document_discount_amount_check CHECK ((document_discount_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_document_status_check CHECK ((document_status = ANY (ARRAY['draft'::text, 'confirmed'::text, 'cancelled'::text, 'adjusted'::text]))),
    CONSTRAINT supplier_invoices_invoice_kind_check CHECK ((invoice_kind = ANY (ARRAY['goods'::text, 'service'::text]))),
    CONSTRAINT supplier_invoices_matching_status_check CHECK ((matching_status = ANY (ARRAY['pending'::text, 'matched'::text, 'discrepancy'::text, 'approved'::text]))),
    CONSTRAINT supplier_invoices_paid_amount_non_negative CHECK ((paid_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_payment_status_check CHECK ((payment_status = ANY (ARRAY['unpaid'::text, 'partial'::text, 'paid'::text]))),
    CONSTRAINT supplier_invoices_service_verification_check CHECK ((((service_verified_by IS NULL) AND (service_verified_at IS NULL) AND (service_verification_reason IS NULL)) OR ((invoice_kind = 'service'::text) AND (service_verified_by IS NOT NULL) AND (service_verified_at IS NOT NULL) AND (char_length(btrim(service_verification_reason)) >= 5))))
);


--
-- Name: COLUMN supplier_invoices.vat_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.vat_rate IS 'Single VAT rate for compatibility; NULL when vat_breakdown contains multiple rates.';


--
-- Name: COLUMN supplier_invoices.due_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.due_date IS 'Payment due date. Can be auto-calculated from invoice_date + supplier.payment_terms_days.';


--
-- Name: COLUMN supplier_invoices.payment_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.payment_status IS 'AP status: unpaid (default), partial, paid.';


--
-- Name: COLUMN supplier_invoices.paid_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.paid_amount IS 'Total amount paid so far toward this invoice.';


--
-- Name: COLUMN supplier_invoices.paid_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.paid_at IS 'Timestamp of last/final payment.';


--
-- Name: COLUMN supplier_invoices.credit_applied_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.credit_applied_amount IS 'Sum of supplier_credit_notes applied against this invoice. Effective AP balance = total_amount - paid_amount - credit_applied_amount.';


--
-- Name: COLUMN supplier_invoices.vat_breakdown; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.vat_breakdown IS 'Immutable input-VAT summary by rate. Header subtotal, VAT and total are derived from this snapshot.';


--
-- Name: COLUMN supplier_invoices.vat_invoice_attachment_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.vat_invoice_attachment_path IS 'Private storage path for HĐ GTGT evidence; required before record_supplier_payment.';


--
-- Name: COLUMN supplier_invoices.invoice_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoices.invoice_kind IS 'goods invoices match confirmed receipt allocations; service invoices require manual document verification.';


--
-- Name: supplier_invoices_id_seq; Type: SEQUENCE; Schema: public; Owner: -
