--
-- Name: supplier_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_payments (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    supplier_invoice_id bigint,
    payment_method text NOT NULL,
    amount numeric(15,2) NOT NULL,
    payment_date timestamp with time zone DEFAULT now() NOT NULL,
    reference_note text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    webhook_event_id bigint,
    idempotency_key uuid,
    idempotency_result_status text,
    supplier_id bigint NOT NULL,
    CONSTRAINT supplier_payments_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT supplier_payments_idempotency_result_check CHECK ((((idempotency_key IS NULL) AND (idempotency_result_status IS NULL)) OR ((idempotency_key IS NOT NULL) AND (idempotency_result_status IS NOT NULL) AND (idempotency_result_status = ANY (ARRAY['partial'::text, 'paid'::text]))))),
    CONSTRAINT supplier_payments_payment_method_check CHECK ((payment_method = ANY (ARRAY['cash'::text, 'bank_transfer'::text])))
);


--
-- Name: COLUMN supplier_payments.idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_payments.idempotency_key IS 'Client-generated payment intent key. Unique within a tenant and immutable for an exact supplier-payment retry.';


--
-- Name: COLUMN supplier_payments.idempotency_result_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_payments.idempotency_result_status IS 'Invoice payment status returned by the first successful execution of an idempotent supplier-payment intent.';


