ALTER TABLE public.tables ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.tables_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: tax_invoice_buyer_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_invoice_buyer_requests (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    branch_id bigint NOT NULL,
    order_id bigint NOT NULL,
    token_hash text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    submitted_payload jsonb,
    submitted_at timestamp with time zone,
    closed_at timestamp with time zone,
    close_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tax_invoice_buyer_requests_close_state_check CHECK ((((status = 'open'::text) AND (closed_at IS NULL) AND (close_reason IS NULL)) OR ((status = 'submitted'::text) AND (closed_at IS NOT NULL) AND (close_reason = 'customer_submitted'::text)) OR ((status = 'expired'::text) AND (closed_at IS NOT NULL) AND (close_reason = 'deadline_elapsed'::text)))),
    CONSTRAINT tax_invoice_buyer_requests_status_check CHECK ((status = ANY (ARRAY['open'::text, 'submitted'::text, 'expired'::text]))),
    CONSTRAINT tax_invoice_buyer_requests_token_hash_check CHECK ((token_hash ~ '^[a-f0-9]{64}$'::text))
);


