    submission_snapshot jsonb,
    CONSTRAINT tax_invoice_issue_jobs_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT tax_invoice_issue_jobs_operation_check CHECK ((operation = ANY (ARRAY['issue'::text, 'replace'::text, 'adjust'::text]))),
    CONSTRAINT tax_invoice_issue_jobs_status_check CHECK ((status = ANY (ARRAY['pending_payment'::text, 'queued'::text, 'processing'::text, 'completed'::text, 'blocked'::text, 'reconcile_required'::text])))
);


