-- Name: attendance_checklist_items; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.attendance_checklist_items ENABLE ROW LEVEL SECURITY;

--
-- Name: attendance_checklist_items attendance_checklist_items_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY attendance_checklist_items_select ON public.attendance_checklist_items FOR SELECT TO authenticated USING (((tenant_id = ( SELECT public.auth_tenant_id() AS auth_tenant_id)) AND (EXISTS ( SELECT 1
   FROM public.attendance_records attendance
  WHERE ((attendance.id = attendance_checklist_items.attendance_record_id) AND (attendance.tenant_id = attendance_checklist_items.tenant_id) AND ((EXISTS ( SELECT 1
           FROM public.employees employee
          WHERE ((employee.id = attendance.employee_id) AND (employee.profile_id = ( SELECT auth.uid() AS uid))))) OR public.has_permission(attendance.branch_id, 'staff:view'::text) OR public.has_permission(attendance.branch_id, 'hr:view_employee'::text) OR public.has_permission(attendance.branch_id, 'staff:manage'::text)))))));


