   FROM public.attendance_consumption_reports report
  WHERE ((report.id = attendance_consumption_report_lines.report_id) AND (report.tenant_id = attendance_consumption_report_lines.tenant_id) AND ((EXISTS ( SELECT 1
           FROM public.employees employee
          WHERE ((employee.id = report.employee_id) AND (employee.tenant_id = report.tenant_id) AND (employee.profile_id = ( SELECT auth.uid() AS uid))))) OR public.has_permission(report.branch_id, 'hr:approve_checkout'::text) OR public.has_permission(report.branch_id, 'inventory:read'::text)))))));


