--
-- Name: stocktake_lines stocktake_lines_blind_block; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY stocktake_lines_blind_block ON public.stocktake_lines AS RESTRICTIVE FOR SELECT TO authenticated USING (((NOT (EXISTS ( SELECT 1
   FROM public.stocktake_sessions ss
  WHERE ((ss.id = stocktake_lines.session_id) AND (ss.blind_mode = true) AND (ss.status = 'in_progress'::text))))) OR public.has_permission(NULL::bigint, 'inventory:stocktake_unblind'::text)));


--
-- Name: stocktake_lines stocktake_lines_count_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY stocktake_lines_count_update ON public.stocktake_lines FOR UPDATE TO authenticated USING (((tenant_id = public.auth_tenant_id()) AND (is_final IS FALSE) AND (EXISTS ( SELECT 1
   FROM ((public.stocktake_sessions session
     JOIN public.inventory_locations location ON (((location.id = session.location_id) AND (location.tenant_id = session.tenant_id) AND (location.branch_id = session.branch_id) AND (location.location_kind = 'warehouse'::text) AND (location.is_active IS TRUE))))
     JOIN public.branches branch ON (((branch.id = session.branch_id) AND (branch.tenant_id = session.tenant_id) AND (branch.is_active IS TRUE))))
  WHERE ((session.id = stocktake_lines.session_id) AND (session.tenant_id = stocktake_lines.tenant_id) AND (session.status = 'in_progress'::text) AND (session.current_round = stocktake_lines.round_no) AND public.has_permission(session.branch_id, 'inventory:write'::text)))))) WITH CHECK (((tenant_id = public.auth_tenant_id()) AND (is_final IS FALSE) AND (EXISTS ( SELECT 1
   FROM ((public.stocktake_sessions session
     JOIN public.inventory_locations location ON (((location.id = session.location_id) AND (location.tenant_id = session.tenant_id) AND (location.branch_id = session.branch_id) AND (location.location_kind = 'warehouse'::text) AND (location.is_active IS TRUE))))
     JOIN public.branches branch ON (((branch.id = session.branch_id) AND (branch.tenant_id = session.tenant_id) AND (branch.is_active IS TRUE))))
  WHERE ((session.id = stocktake_lines.session_id) AND (session.tenant_id = stocktake_lines.tenant_id) AND (session.status = 'in_progress'::text) AND (session.current_round = stocktake_lines.round_no) AND public.has_permission(session.branch_id, 'inventory:write'::text))))));


