--
-- Name: stocktake_sessions stocktake_sessions_cancel; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY stocktake_sessions_cancel ON public.stocktake_sessions FOR UPDATE TO authenticated USING (((tenant_id = public.auth_tenant_id()) AND (status = 'in_progress'::text) AND public.has_permission(branch_id, 'inventory:write'::text) AND (EXISTS ( SELECT 1
   FROM (public.inventory_locations location
     JOIN public.branches branch ON (((branch.id = location.branch_id) AND (branch.tenant_id = location.tenant_id) AND (branch.is_active IS TRUE))))
  WHERE ((location.id = stocktake_sessions.location_id) AND (location.tenant_id = stocktake_sessions.tenant_id) AND (location.branch_id = stocktake_sessions.branch_id) AND (location.location_kind = 'warehouse'::text) AND (location.is_active IS TRUE)))))) WITH CHECK (((tenant_id = public.auth_tenant_id()) AND (status = 'cancelled'::text) AND public.has_permission(branch_id, 'inventory:write'::text) AND (EXISTS ( SELECT 1
   FROM (public.inventory_locations location
     JOIN public.branches branch ON (((branch.id = location.branch_id) AND (branch.tenant_id = location.tenant_id) AND (branch.is_active IS TRUE))))
  WHERE ((location.id = stocktake_sessions.location_id) AND (location.tenant_id = stocktake_sessions.tenant_id) AND (location.branch_id = stocktake_sessions.branch_id) AND (location.location_kind = 'warehouse'::text) AND (location.is_active IS TRUE))))));


